-- elimina campo LOGDIVESTPRDLOT.Qtd_SldPrd
Declare @sql NVARCHAR(MAX)

if Exists(Select ti.COLUMN_NAME
            From INFORMATION_SCHEMA.KEY_COLUMN_USAGE ti Inner Join
                 SYSOBJECTS so on ti.CONSTRAINT_NAME = so.NAME
           Where ti.TABLE_SCHEMA = 'dbo' AND ti.TABLE_NAME = 'LOGDIVESTPRDLOT'
             And ti.TABLE_NAME = OBJECT_NAME(so.Parent_Obj) And so.XTYPE = 'PK'
             And ti.COLUMN_NAME = 'Qtd_SldPrd')
  begin
    -- elimina FK´s existentes
    while 1 = 1
      begin
        Select top 1 @Sql = N'ALTER TABLE dbo.'+OBJECT_NAME(Parent_Object_ID)+N' DROP CONSTRAINT ['+NAME+N']'
          From SYS.FOREIGN_KEYS
         Where OBJECT_NAME(Referenced_Object_ID)='LOGDIVESTPRDLOT'

        if @@ROWCOUNT = 0 BREAK
        Exec (@Sql)
      end

    -- elimina PK existente
    Select @sql = N'ALTER TABLE dbo.LOGDIVESTPRDLOT DROP CONSTRAINT ['+NAME+N']'
      From dbo.SYSOBJECTS Where OBJECT_NAME(Parent_Obj) = 'LOGDIVESTPRDLOT' And XTYPE = 'PK'    
    Exec (@Sql)

    Exec PR_ADM_ExcluiCampo 'LOGDIVESTPRDLOT', 'Qtd_SldPrd'

    Delete FROM dbo.LOGDIVESTPRDLOT  
	  
  end

GO

-- normaliza campo
IF EXISTS (Select Column_Name from Information_Schema.columns
