  Versao 20.06
  Outubro de 2022
  Tabela: GNRTO: Recriar chaves FK_GNRTO_GNRTR
*/

IF EXISTS(SELECT name FROM sys.foreign_keys 
          WHERE OBJECT_NAME(parent_object_id) = 'GNRTO'
                AND OBJECT_NAME(Referenced_Object_ID) = 'GNRTR'
                AND name = 'FK_GNRTO_GNRTR')
  ALTER TABLE dbo.GNRTO DROP CONSTRAINT FK_GNRTO_GNRTR

GO

IF NOT EXISTS(SELECT 1 FROM SYS.FOREIGN_KEYS WHERE name = 'FK_GNRTO_GNRTR')
  ALTER TABLE dbo.GNRTO  WITH CHECK ADD 
	  CONSTRAINT FK_GNRTO_GNRTR 
		  FOREIGN KEY(Id_Gnrtr) REFERENCES dbo.GNRTR (Id)
        ON DELETE CASCADE
GO

