INSERT INTO TBREC (
	Cod_UF,
	Cod_Receit,
	Des_Receit,
	Cod_Estabe,
	Tip_Receit
)
SELECT 
	S_TBREC.Cod_UF,
	S_TBREC.Cod_Receit,
	S_TBREC.Des_Receit,
	S_TBREC.Cod_Estabe,
	S_TBREC.Tip_Receit
FROM @TBREC AS S_TBREC
WHERE NOT EXISTS (
           SELECT *
		   FROM TBREC AS T_TBREC
		   WHERE 1=1
		         AND T_TBREC.Tip_Receit = S_TBREC.Tip_Receit
				 AND T_TBREC.Cod_UF = S_TBREC.Cod_UF
				 AND T_TBREC.Cod_Receit = S_TBREC.Cod_Receit
      )


