/*
  Versao 20.06
  Novembro de 2022
  Tabela: GNRCX: Armazena informações extras que são necessárias para o envio da GNRE
*/

IF NOT EXISTS (SELECT * FROM dbo.sysobjects WHERE id = object_id(N'dbo.GNRCX') AND OBJECTPROPERTY(id, N'IsUserTable') = 1)

    CREATE TABLE dbo.GNRCX (
		Cod_UF char(2) NOT NULL,
		Cod_Receit integer NOT NULL,
		Tipo char(2) NOT NULL,              -- F=Campo Fixo | X=Campo Extra
		Cod_CmpDes integer NULL,			-- Campo Extra
		Nom_CmpDes varchar(50) NOT NULL,	-- Campo Extra
		Tip_CmpDes char(2) NULL,		    -- Campo Extra
		Nom_CmpOri varchar(50) NULL			-- Campo Extra	
    )

GO
        
IF NOT EXISTS (SELECT name FROM sysobjects where name = 'PK_GNRCX')
    ALTER TABLE dbo.GNRCX ADD CONSTRAINT PK_GNRCX PRIMARY KEY CLUSTERED  
	    (Cod_UF, Cod_Receit, Tipo, Nom_CmpDes ) WITH (FILLFACTOR=80, PAD_INDEX=ON) ON "PRIMARY"

GO

DECLARE @GNRCX TABLE(
	  Cod_UF char(2) NOT NULL,
	  Cod_Receit integer NOT NULL,
	  Tipo char(2),                     -- F=Campo Fixo | X=Campo Extra
	  Cod_CmpDes integer NULL,			-- Campo Extra
	  Nom_CmpDes varchar(50) NULL,		-- Campo Extra
	  Tip_CmpDes char(2) NULL,		    -- Campo Extra
	  Nom_CmpOri varchar(50) NULL		-- Campo Extra	
)

