SET NOCOUNT OFF

INSERT INTO GNRCX (
	Cod_UF, 
	Cod_Receit, 
	Tipo, 
	Cod_CmpDes, 
	Nom_CmpDes, 
	Tip_CmpDes, 
	Nom_CmpOri	
)
SELECT 
	S_GNRCX.Cod_UF,
	S_GNRCX.Cod_Receit,
	S_GNRCX.Tipo,
	S_GNRCX.Cod_CmpDes,
	S_GNRCX.Nom_CmpDes,
	S_GNRCX.Tip_CmpDes,
	S_GNRCX.Nom_CmpOri 	
FROM @GNRCX AS S_GNRCX
WHERE NOT EXISTS (
           SELECT *
		   FROM GNRCX AS T_GNRCX
		   WHERE 1=1
				 AND T_GNRCX.Cod_UF = S_GNRCX.Cod_UF
				 AND T_GNRCX.Cod_Receit = S_GNRCX.Cod_Receit
      )


