CREATE PROCEDURE [dbo].[PR_AtualizaCfopNFECB] 
@PCodEstabe int,
@PNumPrt int

AS

SET NOCOUNT ON

Begin Transaction

  Declare @WCodCfo smallint

  if Exists(Select 1 
              From NFEIT 
             Where Cod_Estabe = @PCodEstabe 
               and Protocolo = @PNumPrt 
               and Cod_Cfo > 0
               and Cod_Cfo <> 1910 And Cod_Cfo <> 2910)
    begin
	  Set @WCodCfo = 0

      -- atualiza Cfop do cabecalho com o do item de maior valor
      -- se existe pelo menos 1 item com ST o CFOp da NF é de ST
      if Exists(Select 1 
                  From NFECB 
                 Where Cod_Estabe = @PCodEstabe 
                   And Protocolo = @PNumPrt 
                   And Vlr_IstFon > 0
                   And Cod_Cfo <> 1910 And Cod_Cfo <> 2910)
        Set @WCodCfo = (Select top 1 IsNull(Cod_Cfo,0) From NFEIT 
                         Where Cod_Estabe = @PCodEstabe
                           And Protocolo = @PNumPrt 
                           And Vlr_SubsTrib > 0
                           And Cod_Cfo <> 1910 And Cod_Cfo <> 2910
                         Group by Cod_Cfo
                         Order by sum(Vlr_BasIcmsNor) desc)
      else
      if Exists(Select 1 
                  From NFECB 
                 Where Cod_Estabe = @PCodEstabe 
                   And Protocolo = @PNumPrt 
                   And Vlr_SbtRes > 0
                   And Cod_Cfo <> 1910 And Cod_Cfo <> 2910)
        Set @WCodCfo = (Select top 1 IsNull(Cod_Cfo,0) From NFEIT 
                         Where Cod_Estabe = @PCodEstabe
                           And Protocolo = @PNumPrt 
                           And Vlr_SbtRes > 0
                           And Cod_Cfo <> 1910 And Cod_Cfo <> 2910
                         Group by Cod_Cfo
                         Order by sum(Vlr_BasIcmsNor) desc)
      else
        Set @WCodCfo = (Select top 1 IsNull(Cod_Cfo,0) 
                          From NFEIT 
                         Where Cod_Estabe = @PCodEstabe
                           And Protocolo = @PNumPrt 
                           And Cod_Cfo <> 1910 And Cod_Cfo <> 2910
                         Group by Cod_Cfo
                         Order by sum(Vlr_BasIcmsNor) desc)

      if @WCodCfo > 0
        Update NFECB
           Set Cod_Cfo = @WCodCfo
         Where Cod_Estabe = @PCodEstabe 
           and Protocolo = @PNumPrt

    end  -- if Exists(Select 1


  -- verifica CFOP cabeçalho x itens
  if Exists(Select 1
              From NFECB cb
             Where cb.Cod_Estabe = @PCodEstabe 
               and cb.Protocolo = @PNumPrt
               and cb.Cod_Cfo > 0
               And Exists(Select 1
                            From NFEIT it
                           Where it.Cod_Estabe = cb.Cod_Estabe
                             And it.Protocolo = cb.Protocolo
                             And it.Cod_Cfo > 0)
               And not Exists(Select 1
                                From NFEIT it
                               Where it.Cod_Estabe = cb.Cod_Estabe
                                 And it.Protocolo = cb.Protocolo
                                 And it.Cod_Cfo > 0
                                 And it.Cod_Cfo = IsNull(cb.Cod_Cfo,0)))
    Update cb
       Set cb.Cod_Cfo =  it.CodCfo
      From NFECB cb
           Outer Apply (Select top 1 CodCfo = IsNull(Cod_Cfo,0) 
                          From NFEIT 
                         Where Cod_Estabe = @PCodEstabe
                           And Protocolo = @PNumPrt
                           And Cod_Cfo > 0
                         Group by Cod_Cfo
                         Order by sum(Vlr_BasIcmsNor) desc) it
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Protocolo = @PNumPrt

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_AtualizaCfopNFSCB] 
@PCodEstabe int,
@PSerNot varchar(3),
@PNumNot int

AS

SET NOCOUNT ON

Begin Transaction

  Declare @WCodCfo smallint

  if Exists(Select 1
              From NFSIT 
             Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
               and Cod_Cfo > 0
               and Cod_Cfo <> 5910 And Cod_Cfo <> 6910)
    begin
      -- atualiza Cfop do cabecalho com o do item de maior valor
      -- se existe pelo menos 1 item com ST o CFOp da NF é de ST
      if Exists(Select 1 
                  From NFSIT 
	             Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
                   And Vlr_SubsTrib > 0
                   And Cod_Cfo <> 5910 And Cod_Cfo <> 6910)
        Set @WCodCfo = (Select top 1 IsNull(Cod_Cfo,0) From NFSIT 
                         Where Cod_Estabe = @PCodEstabe
                           And Ser_Nota = @PSerNot 
                           And Num_Nota = @PNumNot 
                           And Cod_Cfo <> 5910 And Cod_Cfo <> 6910
                           And Vlr_SubsTrib > 0
                         Group by Cod_Cfo
                         Order by sum(Vlr_BasIcmsNor) desc)
      else
      if Exists(Select 1 
                  From NFSCB cb Inner Join NFSIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Ser_Nota = it.Ser_Nota and cb.Num_Nota = it.Num_Nota 
	             Where cb.Cod_Estabe = @PCodEstabe And cb.Ser_Nota = @PSerNot And cb.Num_Nota = @PNumNot
                   And it.Vlr_SbtRes > 0
                   And it.Cod_Cfo <> 5910 And it.Cod_Cfo <> 6910)
        Set @WCodCfo = (Select top 1 IsNull(Cod_Cfo,0) From NFSIT 
                         Where Cod_Estabe = @PCodEstabe
                           And Ser_Nota = @PSerNot 
                           And Num_Nota = @PNumNot 
                           And Cod_Cfo <> 5910 And Cod_Cfo <> 6910
                           And Vlr_SbtRes > 0
                         Group by Cod_Cfo
                         Order by sum(Vlr_BasIcmsNor) desc)
      else
        Set @WCodCfo = (Select top 1 IsNull(Cod_Cfo,0) 
                          From NFSIT 
                         Where Cod_Estabe = @PCodEstabe
                           And Ser_Nota = @PSerNot 
                           And Num_Nota = @PNumNot 
                           And Cod_Cfo <> 5910 And Cod_Cfo <> 6910
                         Group by Cod_Cfo
                         Order by sum(Vlr_BasIcmsNor) desc)

      if @WCodCfo > 0
        Update NFSCB
           Set Cod_Cfo1 = @WCodCfo
         Where Cod_Estabe = @PCodEstabe 
           and Ser_Nota = @PSerNot 
           and Num_Nota = @PNumNot

    end  -- if Exists(Select 1


  -- verifica CFOP cabeçalho x itens
  if Exists(Select 1
              From NFSCB cb
             Where cb.Cod_Estabe = @PCodEstabe 
               and cb.Ser_Nota = @PSerNot 
               and cb.Num_Nota = @PNumNot
               and cb.Cod_Cfo1 > 0
               And Exists(Select 1
                            From NFSIT it
                           Where it.Cod_Estabe = cb.Cod_Estabe
                             And it.Ser_Nota = cb.Ser_Nota
                             And it.Num_Nota = cb.Num_Nota
                             And it.Cod_Cfo > 0)
               And not Exists(Select 1
                                From NFSIT it
                               Where it.Cod_Estabe = cb.Cod_Estabe
                                 And it.Ser_Nota = cb.Ser_Nota
                                 And it.Num_Nota = cb.Num_Nota
                                 And it.Cod_Cfo > 0
                                 And it.Cod_Cfo = IsNull(cb.Cod_Cfo1,0)))
    Update cb
       Set cb.Cod_Cfo1 =  it.CodCfo
      From NFSCB cb
           Outer Apply (Select top 1 CodCfo = IsNull(Cod_Cfo,0) 
                          From NFSIT 
                         Where Cod_Estabe = @PCodEstabe
                           And Ser_Nota = @PSerNot 
                           And Num_Nota = @PNumNot 
                           And Cod_Cfo > 0
                         Group by Cod_Cfo
                         Order by sum(Vlr_BasIcmsNor) desc) it
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Ser_Nota = @PSerNot 
       and cb.Num_Nota = @PNumNot

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_AtualizaCfopItemNF]
@PCodEstabe int ,      -- cod. estabelecimento
@PSerNot varchar(3),   -- serie da nota fisca de saidal
@PNumNot int           -- num.da nota fiscal de saida ou protocolo da nf entrada

AS

SET NOCOUNT ON

Begin Transaction

Declare @CodCfo smallint,
        @CodOpe varchar(3),
        @CodCfoNor smallint,
        @CodCfoSbt smallint,
        @FlgOpeInt bit,
		@FlgConsumFin bit,
        @FlgUsaCfoSbtOpeIntSaiGenSim bit

-- colococa campos de TPOPE na memoria
Declare @to_CodCfoConFinInt smallint,
        @to_CodCfoConFinExt smallint,
	    @to_CodCfoNorInt smallint,
        @to_CodCfoNorExt smallint,
        @to_CodCfoSbtInt smallint,
        @to_CodCfoSbtExt smallint

-- coloca campos de ESTAB na memoria
Declare @em_FlgContriSubstituido bit

Select @em_FlgContriSubstituido = IsNull(Flg_ContriSubstituido,0)
  From ESTAB
 Where Cod_Estabe = @PCodEstabe

-- atualiza cfops em itens de entrada se @PSerNot = null
if IsNull(@PSerNot,'') = ''
  begin
    if Exists(Select Protocolo From NFECB Where Cod_Estabe = @PCodEstabe and Protocolo = @PNumNot)
      begin
        Set @CodCfo = (Select Cod_Cfo From NFECB Where Cod_Estabe = @PCodEstabe and Protocolo = @PNumNot)

        EXEC PR_CfopEntSai @PCodEstabe, @CodCfo, @CodCfoNor output, @CodCfoSbt output

        -- exceto bonificação: 1910, 2910
        Update NFEIT
           Set Cod_Cfo = case 
                           When (Cod_Cfo = 1910) or (Cod_Cfo = 2910) Then Cod_Cfo
                           When Round(IsNull(Vlr_SubsTrib,0)+IsNull(Vlr_DifTri,0)+IsNull(Vlr_SbtRes,0),2) > 0 then @CodCfoSbt
                           Else @CodCfoNor
                         end
         Where Cod_Estabe = @PCodEstabe
           and Protocolo = @PNumNot

        -- atualiza Cfop do cabecalho com o do item de maior valor
        Exec PR_AtualizaCfopNFECB @PCodEstabe, @PNumNot

      end
  end
else
  begin
    if Exists(Select Ser_Nota, Num_Nota From NFSCB Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot)
      begin
        Select @CodCfo = cb.Cod_Cfo1,
		       @CodOpe = cb.Cod_Ope,
               @FlgOpeInt = Case
                              When cb.Estado = (Select Des_Estado From ESTAB Where Cod_Estabe = @PCodEstabe) then 1
                              Else 0
                            End,  
               @FlgConsumFin = IsNull(Flg_ConsumFin,0),							 
               @FlgUsaCfoSbtOpeIntSaiGenSim = IsNull(rg.Flg_UsaCfoSbtSaiIntGenSim,0) 
          From NFSCB cb Left Outer Join
               RGTRI rg on cb.Cod_RegTri = rg.Cod_RegTri
         Where cb.Cod_Estabe = @PCodEstabe 
           and cb.Ser_Nota = @PSerNot and cb.Num_Nota = @PNumNot
        
		Set @CodCfoNor = 0
		Set @CodCfoSbt = 0

        if Exists(Select Cod_Ope From TPOPE Where Cod_Ope = @CodOpe)
          begin
            Select @to_CodCfoConFinInt = IsNull(Cod_CfoConFinInt,0),
	               @to_CodCfoConFinExt = IsNull(Cod_CfoConFinExt,0),
        	       @to_CodCfoNorInt = Isnull(Cod_CfoNorInt,0),       
                   @to_CodCfoNorExt = Isnull(Cod_CfoNorExt,0),
                   @to_CodCfoSbtInt = Case 
		                                When @em_FlgContriSubstituido = 1 and IsNull(Cod_CfoSbtIntSubstituido,0) > 0 then Cod_CfoSbtIntSubstituido
					                    Else Isnull(Cod_CfoSbtInt,0)
							          End, 
                   @to_CodCfoSbtExt = Case 
		                                When @em_FlgContriSubstituido = 1 and IsNull(Cod_CfoSbtExtSubstituido,0) > 0 then Cod_CfoSbtExtSubstituido
							            Else Isnull(Cod_CfoSbtExt,0)
							          End
             From TPOPE
            Where Cod_Ope = @CodOpe

            if @FlgConsumFin = 1
              if @FlgOpeInt = 1
        	    begin
                  Set @CodCfoNor = @to_CodCfoConFinInt
                  Set @CodCfoSbt = @to_CodCfoConFinInt
                end
              else
        	    begin
                  Set @CodCfoNor = @to_CodCfoConFinExt
                  Set @CodCfoSbt = @to_CodCfoConFinExt
                end
            else
              if @FlgOpeInt = 1
                begin
                  Set @CodCfoNor = @to_CodCfoNorInt
                  Set @CodCfoSbt = @to_CodCfoSbtInt
                end
              else
                begin
                  Set @CodCfoNor = @to_CodCfoNorExt
                  Set @CodCfoSbt = @to_CodCfoSbtExt
                end
          end

		if (@CodCfoNor = 0) or (@CodCfoSbt = 0)
          EXEC PR_CfopEntSai @CodCfo, @CodCfoNor output, @CodCfoSbt output
        
        -- exceto bonificação: 5910, 6910
        Update it
           Set it.Cod_Cfo = case 
                              When (it.Cod_Cfo = 5910) or (it.Cod_Cfo = 6910) Then Cod_Cfo
                              When Round(IsNull(it.Vlr_SubsTrib,0)+IsNull(it.Vlr_SbtRes,0),2) > 0 then @CodCfoSbt
                              Else Case 
                                     When (@FlgUsaCfoSbtOpeIntSaiGenSim = 1) and 
                                          (it.Flg_UsaDebPresum = 1) and (it.Alq_IcmPresum > 0) and (it.Alq_IcmPresum <> it.Alq_Icms) then @CodCfoSbt
                                     Else @CodCfoNor
                                   End  
                            end
          From NFSIT it
         Where it.Cod_Estabe = @PCodEstabe 
           and it.Ser_Nota = @PSerNot and it.Num_Nota = @PNumNot

        -- atualiza Cfop do cabecalho com o do item de maior valor
        Exec PR_AtualizaCfopNFSCB @PCodEstabe, @PSerNot, @PNumNot

      end
  end

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraMensagensNF]
(
  @PCodEstabe int,
  @PNumNot int,
  @PSerNot varchar(3),
  @PTipNot char(1)
)

AS

SET NOCOUNT ON

if ((@PTipNot = 'E') and
    (not Exists(Select 1 From NFECB 
                 Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot))) or
   ((@PTipNot = 'S') and
    (not Exists(Select 1 From NFSCB 
                 Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot)))
  Return
else
BEGIN
BEGIN TRANSACTION

Declare @it_CodPrd int          
      , @it_CodLot varchar(20)
      , @it_SeqIte int
      , @rg_IdMensag int
      , @mg_FlgInfCpl bit = 0
      , @mg_FlgobsCont bit = 0
      , @mg_FlginfAdFisco bit = 0
      , @mg_FlgobsFisco bit = 0
      , @Chave int
      , @WNumSeqMensag int
      , @PObserv varchar(1600)

      , @NomFantas varchar(80) = ''
      , @TipNot varchar(1)
      , @ObsNf1 varchar(1600) = ''
      , @ObsNf2 varchar(200) = ''
      , @ObsNf3 varchar(200) = ''
      , @ListaTipPor344 varchar(100)

    Declare @TabObs Table(
      Chave Int Identity(1,1) PRIMARY KEY
    , Tip_Not varchar(1)
    , Des_Observ varchar(1600)
    , Flg_infCpl bit
    , Flg_obsCont bit
    , Flg_infAdFisco bit
    , Flg_obsFisco bit
    )


-- mensagens em NFSCB/NFECB
if @PTipNot = 'S'
  begin
    Delete
      From NSCOB 
     Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot

    Delete
      From NSIOB 
       Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
  end
else
  begin
    Delete
      From NECOB 
     Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot

    Delete
      From NEIOB 
     Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot
  end

-- Nome Fantasia do destinatario da NF ----
Set @NomFantas = ''
Set @PObserv = ''
Set @mg_FlgInfCpl = 1
Set @mg_FlgobsCont = 0
Set @mg_FlginfAdFisco = 0
Set @mg_FlgobsFisco = 0

if @PTipNot = 'S' --SAIDAS
  begin
    Select @NomFantas = (Select dbo.FN_NomeFantasia(IsNull(Cod_Cliente,0), IsNull(Cod_Fornecedor,0), 0))
      From NFSCB
     Where Cod_Estabe = @PCodEstabe
       And Ser_Nota = @PSerNot
       And Num_Nota = @PNumNot

	if IsNull(@NomFantas,'') <> '' 
      Set @PObserv = 'FANTASIA DESTINATARIO: '+@NomFantas

    if (@PObserv <> '') and
       not exists(Select 1 From NSCOB 
                   Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
                     And Des_Observ = @PObserv)
      begin
        Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                       From NSCOB 
                                      Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot),0) + 1

        Insert Into NSCOB (Cod_Estabe, Ser_Nota, Num_Nota, Num_SeqMensag, Id_Mensag, Des_Observ
                        ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                   Values (@PCodEstabe, @PSerNot, @PNumNot, @WNumSeqMensag, 0, @PObserv
                        ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
      end
  end
else
  begin
    Select @NomFantas = (Select dbo.FN_NomeFantasia(IsNull(Cod_EmiCliente,0), IsNull(Cod_EmiFornec,0), ISNull(Cod_EmiTransp,0)))
      From NFECB
     Where Cod_Estabe = @PCodEstabe
       And Protocolo = @PNumNot

	if IsNull(@NomFantas,'') <> '' 
      Set @PObserv = 'FANTASIA DESTINATARIO: '+@NomFantas

    if (@PObserv <> '') and
       not exists(Select 1 From NECOB 
                   Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot
                     And Des_Observ = @PObserv)
      begin
        Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                       From NECOB 
                                      Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot),0) + 1

        Insert Into NECOB (Cod_Estabe, Protocolo, Num_SeqMensag, Id_Mensag, Des_Observ
                        ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                   Values (@PCodEstabe, @PNumNot, @WNumSeqMensag, 0, @PObserv
                        ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
      end
  end
-----------------------------------------

-- Observações na UF
Set @ObsNf1 = ''
Set @ObsNf2 = ''
Set @ObsNf3 = ''
Set @mg_FlgInfCpl = 1
Set @mg_FlgobsCont = 0
Set @mg_FlginfAdFisco = 0
Set @mg_FlgobsFisco = 0

if Exists(Select 1
            From ESTAD uf
                 Inner Join ESTAB es on uf.Codigo = es.Des_Estado
           Where Cod_Estabe = @PCodEstabe
             And ( (IsNull(uf.ObservacaoNF,'') <> '') or
                   (IsNull(uf.Obs2_NF,'') <> '') or 
                   (IsNull(uf.Obs3_NF,'') <> '') ) )
  begin
    Select @ObsNf1 = IsNull(uf.ObservacaoNF,'')
         , @ObsNf2 = IsNull(uf.Obs2_NF,'')
         , @ObsNf3 = IsNull(uf.Obs3_NF,'')
      From ESTAD uf
           Inner Join ESTAB es on uf.Codigo = es.Des_Estado
    Where Cod_Estabe = @PCodEstabe

    if @PTipNot = 'S' --SAIDAS
      begin
        Set @PObserv = ''
        if IsNull(@ObsNf1,'') <> '' 
          Set @PObserv = @ObsNf1
        if (@PObserv <> '') and
           not exists(Select 1 From NSCOB 
                       Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
                         And Des_Observ = @PObserv)
          begin
            Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                           From NSCOB 
                                          Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot),0) + 1

            Insert Into NSCOB (Cod_Estabe, Ser_Nota, Num_Nota, Num_SeqMensag, Id_Mensag, Des_Observ
                            ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                       Values (@PCodEstabe, @PSerNot, @PNumNot, @WNumSeqMensag, 0, @PObserv
                            ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
          end

        Set @PObserv = ''
        if IsNull(@ObsNf2,'') <> '' 
          Set @PObserv = @ObsNf2
        if (@PObserv <> '') and
           not exists(Select 1 From NSCOB 
                       Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
                         And Des_Observ = @PObserv)
          begin
            Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                           From NSCOB 
                                          Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot),0) + 1

            Insert Into NSCOB (Cod_Estabe, Ser_Nota, Num_Nota, Num_SeqMensag, Id_Mensag, Des_Observ
                            ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                       Values (@PCodEstabe, @PSerNot, @PNumNot, @WNumSeqMensag, 0, @PObserv
                            ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
          end

        Set @PObserv = ''
        if IsNull(@ObsNf3,'') <> '' 
          Set @PObserv = @ObsNf3
        if (@PObserv <> '') and
           not exists(Select 1 From NSCOB 
                       Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
                         And Des_Observ = @PObserv)
          begin
            Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                           From NSCOB 
                                          Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot),0) + 1

            Insert Into NSCOB (Cod_Estabe, Ser_Nota, Num_Nota, Num_SeqMensag, Id_Mensag, Des_Observ
                            ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                       Values (@PCodEstabe, @PSerNot, @PNumNot, @WNumSeqMensag, 0, @PObserv
                            ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
          end
      end -- if @PTipNot = 'S' --SAIDAS
    else -- entrada
      begin
        Set @PObserv = ''
        if IsNull(@ObsNf1,'') <> '' 
          Set @PObserv = @ObsNf1
        if (@PObserv <> '') and
           not exists(Select 1 From NECOB 
                       Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot
                         And Des_Observ = @PObserv)
          begin
            Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                           From NECOB 
                                          Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot),0) + 1

            Insert Into NECOB (Cod_Estabe, Protocolo, Num_SeqMensag, Id_Mensag, Des_Observ
                            ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                       Values (@PCodEstabe, @PNumNot, @WNumSeqMensag, 0, @PObserv
                            ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
          end

        Set @PObserv = ''
        if IsNull(@ObsNf2,'') <> '' 
          Set @PObserv = @ObsNf2
        if (@PObserv <> '') and
           not exists(Select 1 From NECOB 
                       Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot
                         And Des_Observ = @PObserv)
          begin
            Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                           From NECOB 
                                          Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot),0) + 1

            Insert Into NECOB (Cod_Estabe, Protocolo, Num_SeqMensag, Id_Mensag, Des_Observ
                            ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                       Values (@PCodEstabe, @PNumNot, @WNumSeqMensag, 0, @PObserv
                            ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
          end

        Set @PObserv = ''
        if IsNull(@ObsNf3,'') <> '' 
          Set @PObserv = @ObsNf3
        if (@PObserv <> '') and
           not exists(Select 1 From NECOB 
                       Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot
                         And Des_Observ = @PObserv)
          begin
            Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                           From NECOB 
                                          Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot),0) + 1

            Insert Into NECOB (Cod_Estabe, Protocolo, Num_SeqMensag, Id_Mensag, Des_Observ
                            ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                       Values (@PCodEstabe, @PNumNot, @WNumSeqMensag, 0, @PObserv
                            ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
          end
      end -- else if @PTipNot = 'S' --SAIDAS
  end  -- if Exists(Select 1
-----------------------------------------------------------------------------------------

-- observacao no Ag.Cobrador
Set @ObsNf1 = ''
Set @mg_FlgInfCpl = 1
Set @mg_FlgobsCont = 0
Set @mg_FlginfAdFisco = 0
Set @mg_FlgobsFisco = 0

if @PTipNot = 'S' --SAIDAS
  begin
    if Exists(Select 1
                From NFSCB cb
                     inner join AGCOB ag on cb.Cod_AGente = ag.Codigo
               Where Cod_Estabe = @PCodEstabe
                 And Ser_Nota = @PSerNot
                 And Num_Nota = @PNumNot
                 And IsNull(ag.Obs1_Nf,'') <> '')
      begin
        Select @ObsNf1 = Ltrim(Rtrim(IsNull(ag.Obs1_Nf,'')))
          From NFSCB cb
               inner join AGCOB ag on cb.Cod_AGente = ag.Codigo
         Where Cod_Estabe = @PCodEstabe
           And Ser_Nota = @PSerNot
           And Num_Nota = @PNumNot
           And IsNull(ag.Obs1_Nf,'') <> ''

        Set @PObserv = ''
        if IsNull(@ObsNf1,'') <> '' 
          Set @PObserv = @ObsNf1
        if (@PObserv <> '') and
           not exists(Select 1 From NSCOB 
                       Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
                         And Des_Observ = @PObserv)
          begin
            Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                           From NSCOB 
                                          Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot),0) + 1

            Insert Into NSCOB (Cod_Estabe, Ser_Nota, Num_Nota, Num_SeqMensag, Id_Mensag, Des_Observ
                            ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                       Values (@PCodEstabe, @PSerNot, @PNumNot, @WNumSeqMensag, 0, @PObserv
                            ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
          end
      end  -- if Exists(Select 1
  end  -- if @PTipNot = 'S' --SAIDAS
-----------------------------------------------------------------------------------------

-- CNAE do cliente
Set @ObsNf1 = ''
Set @mg_FlgInfCpl = 1
Set @mg_FlgobsCont = 0
Set @mg_FlginfAdFisco = 0
Set @mg_FlgobsFisco = 0

if (@PTipNot = 'S') and
   Exists(Select 1
           From FS_PARAM 
          Where Cod_Estabe = @PCodEstabe
            And Cod_Param = 'NFE_CFG_DNF_IMPCNAE'
            And Val_Param ='1') And
   Exists( Select 1
             From NFSCB cb 
                  Inner Join CLIEN cl on cb.Cod_Cliente = cl.Codigo
            Where cb.Cod_Estabe = @PCodEstabe
              And cb.Ser_Nota = @PSerNot
              And cb.Num_Nota = @PNumNot
              And IsNull(cl.Cod_CNAE,'') <> '')
  begin
    Select @ObsNf1 = cl.Cod_CNAE
      From NFSCB cb 
           Inner Join CLIEN cl on cb.Cod_Cliente = cl.Codigo
     Where cb.Cod_Estabe = @PCodEstabe
       And cb.Ser_Nota = @PSerNot
       And cb.Num_Nota = @PNumNot
       And IsNull(cl.Cod_CNAE,'') <> ''

    Set @PObserv = ''
    if IsNull(@ObsNf1,'') <> '' 
      Set @PObserv = @ObsNf1
    if (@PObserv <> '') and
       not exists(Select 1 From NSCOB 
                   Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
                     And Des_Observ = @PObserv)
      begin
        Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                       From NSCOB 
                                      Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot),0) + 1

        Insert Into NSCOB (Cod_Estabe, Ser_Nota, Num_Nota, Num_SeqMensag, Id_Mensag, Des_Observ
                        ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                   Values (@PCodEstabe, @PSerNot, @PNumNot, @WNumSeqMensag, 0, @PObserv
                            ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
      end
  end
--------------------------------------

-- CLTRI: classificação tributária
Set @ObsNf1 = ''
Set @mg_FlgInfCpl = 1
Set @mg_FlgobsCont = 0
Set @mg_FlginfAdFisco = 0
Set @mg_FlgobsFisco = 0

if Exists(Select 1
            From NFSIT it 
                 Inner Join NFSCB cb on (it.Cod_Estabe = cb.Cod_Estabe And it.Ser_Nota = cb.Ser_Nota And it.Num_Nota = cb.Num_Nota) 
                 Inner Join CLTRI ct on (it.Cod_ClaTri = ct.Cod_ClaTri)
           Where it.Cod_Estabe = @PCodEstabe
             And it.Ser_Nota = @PSerNot
             And it.Num_Nota = @PNumNot
             And IsNull(ct.Obs_FiscalSai,'') <> '' )
  begin
    Delete From @TabObs

    Insert Into @TabObs (Tip_Not, Des_Observ, Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
      Select Distinct @PTipNot, (IsNull(ct.Obs_FiscalSai,'')), 1, 0, 0, 0
        From NFSIT it 
             Inner Join NFSCB cb on (it.Cod_Estabe = cb.Cod_Estabe And it.Ser_Nota = cb.Ser_Nota And it.Num_Nota = cb.Num_Nota) 
             Inner Join CLTRI ct on (it.Cod_ClaTri = ct.Cod_ClaTri)
       Where it.Cod_Estabe = @PCodEstabe
         And it.Ser_Nota = @PSerNot
         And it.Num_Nota = @PNumNot
         And IsNull(ct.Obs_FiscalSai,'') <> '' 

    While Exists(Select 1 From @TabObs)
      begin
        Select top 1
               @Chave = Chave
             , @ObsNf1 = Des_Observ
             , @mg_FlgInfCpl = Flg_InfCpl
             , @mg_FlgobsCont = Flg_obsCont
             , @mg_FlgInfAdFisco = Flg_InfAdFisco
             , @mg_FlgobsFisco = Flg_obsFisco
          From @TabObs
         Order by Chave

        Set @PObserv = ''
        if IsNull(@ObsNf1,'') <> '' 
          Set @PObserv = @ObsNf1
        if (@PObserv <> '') and
           not exists(Select 1 From NSCOB 
                       Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
                         And Des_Observ = @PObserv)
          begin
            Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                           From NSCOB 
                                          Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot),0) + 1

            Insert Into NSCOB (Cod_Estabe, Ser_Nota, Num_Nota, Num_SeqMensag, Id_Mensag, Des_Observ
                            ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                       Values (@PCodEstabe, @PSerNot, @PNumNot, @WNumSeqMensag, 0, @PObserv
                            ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
          end

        Delete From @TabObs Where Chave = @Chave
      end
  end
------------

-- RGTRI
if exists(Select 1
            From NFSCB cb
                 Inner Join RGTRI rg on cb.Cod_RegTri = rg.Cod_RegTri
           Where cb.Cod_Estabe = @PCodEstabe
             And Ser_Nota = @PSerNot
             And Num_Nota = @PNumNot
             And IsNull(rg.Id_MensagReg,0) > 0 )
  begin
    Select @rg_IdMensag = IsNull(rg.Id_MensagReg,0)
         , @mg_FlgInfCpl = IsNull(mg.Flg_InfCpl,0)
         , @mg_FlgobsCont = IsNull(mg.Flg_obsCont,0)
         , @mg_FlginfAdFisco = IsNull(mg.Flg_infAdFisco,0)
         , @mg_FlgobsFisco = IsNull(mg.Flg_obsFisco,0)

      From NFSCB cb
           Inner Join RGTRI rg on cb.Cod_RegTri = rg.Cod_RegTri
           inner join TBMSG mg on rg.Id_MensagReg = mg.Id_Mensag
     Where cb.Cod_Estabe = @PCodEstabe
       And cb.Ser_Nota = @PSerNot
       And cb.Num_Nota = @PNumNot
       And IsNull(rg.Id_MensagReg,0) > 0 

    if @rg_IdMensag > 0
      begin

        Exec PR_MontaMensagemNF 'S', @rg_IdMensag, @PCodEstabe, @PNumNot, @PSerNot, 0, '', 0, 'R', @PObserv output

		if (@PObserv <> '') and
           not exists(Select 1 From NSCOB 
                       Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
                         And Id_Mensag = @rg_IdMensag)
          begin
            Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                           From NSCOB 
                                          Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot),0) + 1
            Insert Into NSCOB (Cod_Estabe, Ser_Nota, Num_Nota, Num_SeqMensag, Id_Mensag, Des_Observ
                            ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
              Values (@PCodEstabe, @PSerNot, @PNumNot, @WNumSeqMensag, @rg_IdMensag, @PObserv
                   ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
          end
       end

  end  -- if exists(Select 1 NFSCB
