--IMPRIME INFO. PORTARIA 344/98
Set @ObsNf1 = 'PORTARIA 344/98: PRODUTO SUJEITO A CONTROLE ESPECIAL'

Declare @TabPor344 Table(
  Chave Int Identity(1,1) PRIMARY KEY
, Tip_Por344	VARCHAR(2)
)

if @PTipNot = 'S'
  begin
    if Exists(Select 1
                From FS_PARAM 
               Where Cod_Estabe = @PCodEstabe
                 And Cod_Param = 'NFE_CFG_DNF_PRT34498'
                 And Val_Param ='1') and
       Exists(Select 1
                From NFSIT it
                     inner join PRODU pr on it.Cod_Produto = pr.Codigo
               Where it.Cod_Estabe = @PCodEstabe
                And it.Ser_Nota = @PSerNot
                And it.Num_Nota = @PNumNot
                And IsNull(pr.Tip_Por344,'') <> '')
    
      begin
        Insert Into @TabPor344 (Tip_Por344)
          Select distinct pr.Tip_Por344 
            From NFSIT it
                 inner join PRODU pr on it.Cod_Produto = pr.Codigo
           Where it.Cod_Estabe = @PCodEstabe
             And it.Ser_Nota = @PSerNot
             And it.Num_Nota = @PNumNot
             And IsNull(pr.Tip_Por344,'') <> ''
           Order by pr.Tip_Por344

        Set @ListaTipPor344 = ''

        while exists(Select 1 From @TabPor344)
          begin
            Select top 1
                   @Chave = Chave
                 , @NomFantas = Tip_Por344
              From @TabPor344
             Order by Chave

            if @ListaTipPor344 <> ''
              Set @ListaTipPor344 = @ListaTipPor344 + ', '
            Set @ListaTipPor344 = @ListaTipPor344 + @NomFantas

            Delete From @TabPor344 Where Chave = @Chave
          end 

        if IsNull(@ListaTipPor344,'') <> '' 
          Set @PObserv = 'PORTARIA 344/98: PRODUTO SUJEITO A CONTROLE ESPECIAL, LISTAS:' + @ListaTipPor344

        if not Exists(Select 1 From @TabObs Where Tip_Not = @PTipNot And Des_Observ = @PObserv)
          Insert Into @TabObs (Tip_Not, Des_Observ, Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                       Values (@PTipNot, @PObserv, 1, 0, 0, 0)
      end  -- if Exists(Select 1
  end  -- if @PTipNot = 'S'
else
  begin
    if Exists(Select 1
                From FS_PARAM 
               Where Cod_Estabe = @PCodEstabe
                 And Cod_Param = 'NFE_CFG_DNF_PRT34498'
                 And Val_Param ='1') and
       Exists(Select 1
                From NFEIT it
                     inner join PRODU pr on it.Cod_Produto = pr.Codigo
               Where it.Cod_Estabe = @PCodEstabe
                And it.Protocolo = @PNumNot
                And IsNull(pr.Tip_Por344,'') <> '')
      begin
        Insert Into @TabPor344 (Tip_Por344)
          Select distinct pr.Tip_Por344 
            From NFEIT it
                 inner join PRODU pr on it.Cod_Produto = pr.Codigo
           Where it.Cod_Estabe = @PCodEstabe
             And it.Protocolo = @PNumNot
             And IsNull(pr.Tip_Por344,'') <> ''
           Order by pr.Tip_Por344

        Set @ListaTipPor344 = ''

        while exists(Select 1 From @TabPor344)
          begin
            Select top 1
                   @Chave = Chave
                 , @NomFantas = Tip_Por344
              From @TabPor344
             Order by Chave

            if @ListaTipPor344 <> ''
              Set @ListaTipPor344 = @ListaTipPor344 + ', '
            Set @ListaTipPor344 = @ListaTipPor344 + @NomFantas

            Delete From @TabPor344 Where Chave = @Chave
          end 

        if IsNull(@ListaTipPor344,'') <> '' 
          Set @PObserv = 'PORTARIA 344/98: PRODUTO SUJEITO A CONTROLE ESPECIAL, LISTAS:' + @ListaTipPor344

        if not Exists(Select 1 From @TabObs Where Tip_Not = @PTipNot And Des_Observ = @PObserv)
          Insert Into @TabObs (Tip_Not, Des_Observ, Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                       Values (@PTipNot, @PObserv, 1, 0, 0, 0)

      end  -- if Exists(Select 1
  end  -- else if @PTipNot = 'S'


