while (@WValDif <> 0) and (Abs(@WValDif) < @WValCabIcm)
  begin
    DECLARE ITENS_Cr Cursor Local Fast_Forward For
      Select Chave
      From #TMP_Itens
      Where Vlr_BasIcm > 0
      Order by Vlr_TotIte desc, Chave 
        
    OPEN ITENS_Cr
    FETCH NEXT FROM ITENS_Cr INTO @Chave 
    WHILE @@FETCH_STATUS = 0
    BEGIN
      if @WValDif <> 0
         begin
