             Set Vlr_Icm = Vlr_Icm + @ParDif   
           Where Chave = @Chave
           And Vlr_Icm > 0 
           And Abs(Dif_VlrIcm) < @WValLimDif  
           
           if @@ROWCOUNT > 0
             Set @WValDif = @WValDif - @ParDif
         end
       else
         Break  
      FETCH NEXT FROM ITENS_Cr INTO @Chave
