      FETCH NEXT FROM ITENS_Cr INTO @Chave
    END

    CLOSE ITENS_Cr
    DEALLOCATE ITENS_Cr     
          
  end  -- while @WValDif <> 0

-- normaliza FcpSbt ----------------------------------------------------------------------------------------
Set @WValDif = Round(@WValCabFcpSbt - (Select SUM(Vlr_FcpSbt) From #TMP_Itens),2) 
if @WValDif < 0
  Set @ParDif = -0.01  
else  
  Set @ParDif = 0.01  
  
while (@WValDif <> 0) and (Abs(@WValDif) < @WValCabFcpSbt)
  begin
    if @ParDif > 0
      DECLARE ITENS_Cr Cursor Local Fast_Forward For
        Select Chave
        From #TMP_Itens
        Where Vlr_FcpSbt > 0
        Order by Vlr_TotIte desc, Chave 
    else
      DECLARE ITENS_Cr Cursor Local Fast_Forward For
        Select Chave
        From #TMP_Itens
        Where Vlr_FcpSbt > 0
        Order by Vlr_TotIte desc, Chave 
        
    OPEN ITENS_Cr
    FETCH NEXT FROM ITENS_Cr INTO @Chave 
    WHILE @@FETCH_STATUS = 0
    BEGIN
      if @WValDif <> 0
         begin
           Update #TMP_Itens
             Set Vlr_FcpSbt = Vlr_FcpSbt + @ParDif   
           Where Chave = @Chave
           And Vlr_FcpSbt > 0
                      
           Set @WValDif = @WValDif - @ParDif
         end
       else
         Break  
      FETCH NEXT FROM ITENS_Cr INTO @Chave
    END

    CLOSE ITENS_Cr
    DEALLOCATE ITENS_Cr     
          
  end  -- while @WValDif <> 0

-- normaliza FcpSbtRet ----------------------------------------------------------------------------------------
Set @WValDif = Round(@WValCabFcpSbtRet - (Select SUM(Vlr_FcpSbtRet) From #TMP_Itens),2) 
if @WValDif < 0
  Set @ParDif = -0.01  
else  
  Set @ParDif = 0.01  
  
while (@WValDif <> 0) and (Abs(@WValDif) < @WValCabFcpSbtRet)
  begin
    if @ParDif > 0
      DECLARE ITENS_Cr Cursor Local Fast_Forward For
        Select Chave
        From #TMP_Itens
        Where Vlr_FcpSbtRet > 0
        Order by Vlr_TotIte desc, Chave 
    else
      DECLARE ITENS_Cr Cursor Local Fast_Forward For
        Select Chave
        From #TMP_Itens
        Where Vlr_FcpSbtRet > 0
        Order by Vlr_TotIte desc, Chave 
        
    OPEN ITENS_Cr
    FETCH NEXT FROM ITENS_Cr INTO @Chave 
    WHILE @@FETCH_STATUS = 0
    BEGIN
      if @WValDif <> 0
         begin
           Update #TMP_Itens
             Set Vlr_FcpSbtRet = Vlr_FcpSbtRet + @ParDif   
           Where Chave = @Chave
           And Vlr_FcpSbtRet > 0
                      
           Set @WValDif = @WValDif - @ParDif
         end
       else
         Break  
      FETCH NEXT FROM ITENS_Cr INTO @Chave
    END

    CLOSE ITENS_Cr
    DEALLOCATE ITENS_Cr     
          
  end  -- while @WValDif <> 0


-- normaliza IcmParDes ----------------------------------------------------------------------------------------
Set @WValDif = Round(@WValCabIcmParDes - (Select SUM(Vlr_IcmParDes) From #TMP_Itens),2) 
if @WValDif < 0
  Set @ParDif = -0.01  
else  
  Set @ParDif = 0.01  
  
while (@WValDif <> 0) and (Abs(@WValDif) < @WValCabIcmParDes)
  begin
    if @ParDif > 0
      DECLARE ITENS_Cr Cursor Local Fast_Forward For
        Select Chave
        From #TMP_Itens
        Where Vlr_IcmParDes > 0
        Order by Vlr_TotIte desc, Chave 
    else
      DECLARE ITENS_Cr Cursor Local Fast_Forward For
        Select Chave
        From #TMP_Itens
        Where Vlr_IcmParDes > 0
        Order by Vlr_TotIte desc, Chave 
        
    OPEN ITENS_Cr
    FETCH NEXT FROM ITENS_Cr INTO @Chave 
    WHILE @@FETCH_STATUS = 0
    BEGIN
      if @WValDif <> 0
         begin
           Update #TMP_Itens
             Set Vlr_IcmParDes = Vlr_IcmParDes + @ParDif   
           Where Chave = @Chave
           And Vlr_IcmParDes > 0
                      
           Set @WValDif = @WValDif - @ParDif
         end
       else
         Break  
      FETCH NEXT FROM ITENS_Cr INTO @Chave
    END

    CLOSE ITENS_Cr
    DEALLOCATE ITENS_Cr     
          
  end  -- while @WValDif <> 0
----------------------------------------------------------------------------------------------------------

-- normaliza IcmParRem ----------------------------------------------------------------------------------------
Set @WValDif = Round(@WValCabIcmParRem - (Select SUM(Vlr_IcmParRem) From #TMP_Itens),2) 
if @WValDif < 0
  Set @ParDif = -0.01  
else  
  Set @ParDif = 0.01  
  
while (@WValDif <> 0) and (Abs(@WValDif) < @WValCabIcmParRem)
  begin
    if @ParDif > 0
      DECLARE ITENS_Cr Cursor Local Fast_Forward For
        Select Chave
        From #TMP_Itens
        Where Vlr_IcmParRem > 0
        Order by Vlr_TotIte desc, Chave 
    else
      DECLARE ITENS_Cr Cursor Local Fast_Forward For
        Select Chave
        From #TMP_Itens
        Where Vlr_IcmParRem > 0
        Order by Vlr_TotIte desc, Chave 
        
    OPEN ITENS_Cr
    FETCH NEXT FROM ITENS_Cr INTO @Chave 
    WHILE @@FETCH_STATUS = 0
    BEGIN
      if @WValDif <> 0
         begin
           Update #TMP_Itens
             Set Vlr_IcmParRem = Vlr_IcmParRem + @ParDif   
           Where Chave = @Chave
           And Vlr_IcmParRem > 0
                      
           Set @WValDif = @WValDif - @ParDif
         end
       else
         Break  
      FETCH NEXT FROM ITENS_Cr INTO @Chave
    END

    CLOSE ITENS_Cr
    DEALLOCATE ITENS_Cr     
          
  end  -- while @WValDif <> 0
----------------------------------------------------------------------------------------------------------

------- Normaliza FCP: B.Calculo x Aliquota = Vlr_IcmFcp  -----------------------------------------------------------
/* está alterando NFSCB.Vlr_IcmFcpDes ????
if Round(@WValCabIcmFcpDes,2) = Round((Select SUM(Vlr_IcmFcpDes) From #TMP_Itens),2) 
  begin
    Set @WValDif = Round(@WValCabIcmFcpDes - (Select sum(Round(Vlr_BasIcmDes*Per_AcrAlqIntFcp/100,2)) From #TMP_Itens),2) 
    if ABS(@WValDif) > 0 
      begin
        Update #TMP_Itens
          Set Vlr_IcmFcpDes = Round(Vlr_BasIcmDes*Per_AcrAlqIntFcp/100,2)
          Where Round(Vlr_BasIcmDes*Per_AcrAlqIntFcp/100,2) <> Vlr_IcmFcpDes
          
        -- atualiza valor na tabela de origem (alterando valor original ????)
        Set @WValCabIcmFcpDes = Round((Select sum(Vlr_IcmFcpDes) From #TMP_Itens),2)
        if @PTipNota = 'S'
          begin
            Update NFSCB
              Set Vlr_IcmFcpDes = @WValCabIcmFcpDes
            Where Cod_Estabe = @PCodEstabe 
            and Ser_Nota = @PSerNota 
            and Num_Nota = @PNumNota
          end
        else
          begin
            Update NFECB
              Set Vlr_IcmFcpDes = @WValCabIcmFcpDes
            From NFECB 
            Where Cod_Estabe = @PCodEstabe 
            and Protocolo = @PNumNota
          end
      end
  end  
*/
---------------------------------------------------------------------------------------------------------------

-- normaliza EAN (a partir da versão 4.0)
Update #TMP_Itens
  Set Cod_EAN = 'SEM GTIN'
Where IsNull(Cod_EAN,'') = ''
And Cast(Substring(@pm_VerNfe,1,CharIndex('.',@pm_VerNfe)-1) as int) > 3

------------------------------------------------------------------------------------------------------------------
-- recalcula campos
Update #TMP_Itens
  Set Vlr_DscTotIte = Vlr_TotBruIte - Vlr_TotIte + Vlr_DscRat + Vlr_DscBonRat + Vlr_DscTri, -- desc. sem repasse
      Vlr_TotDsp = Vlr_DspRat + Vlr_DspExt + Vlr_SbtRes,
      Vlr_BasIcmSbtRet = Vlr_BasSbtRes + Vlr_BasSbtEmb,
      Vlr_IcmSbtRet = Vlr_SbtRes + Vlr_SbtEmb
      
-- monta observacao 
DECLARE ITENS_Cr Cursor Local Fast_Forward For
  Select Chave, Cod_Produto, Num_SeqIte, Cod_Lote, Cod_LoteOri, Tip_LisPis, Vlr_TotBruIte, Vlr_DscTotIte,
         Flg_DscItePdv, Prc_UniPdv, Per_DscPdv, Prc_Fabric,
         Vlr_BasSbtRes, Vlr_SbtRes, Vlr_BasSbtEmb, Vlr_SbtEmb, Tip_Consumidor,
         Vlr_DscTri, Per_DscTri, Des_Produto, Des_Fabric, Tip_Por344, Tip_Sai, 
         Str_VolEmb, Obs_IteNf, Vlr_BasRepIcm, Per_RepIcm, Vlr_RepIcm,
         Per_Desconto = Case When (Vlr_DscRat + Vlr_DscBonRat) > 0 then 0 Else Per_Desconto End,
         Vlr_TotIte
  From #TMP_Itens
  Order by Chave 
OPEN ITENS_Cr
FETCH NEXT FROM ITENS_Cr INTO @Chave, @CodPrd, @SeqIte, @CodLot, @WCodLotOri, @WTipLisPis, @WVlrTotBruIte, @WVlrDscTotIte,
                              @WFlgDscItePdv, @WPrcUniPdv, @WPerDscPdv, @WPrcFabric,
                              @WVlrBasSbtRes, @WVlrSbtRes, @WVlrBasSbtEmb, @WVlrSbtEmb, @WTipCon,
                              @WVlrDscTri, @WPerDscTri, @WDesProduto, @WDesFabric, @WTipPor344, @WTipSai, 
                              @WStrVolEmb, @WObsIteNf, @WVlrBasRepIcm, @WPerRepIcm, @WVlrRepIcm, @WPerDscIte, @WVlrTotLiqIte
WHILE @@FETCH_STATUS = 0
  BEGIN
    -- monta observacao cancatenada infAdProd
    Set @WDesCplProduto = ''

    Delete From @Tab

    if @PTipNota = 'S'
      Insert Into @Tab (Obs_Fiscal)
        Select Des_Observ From NSIOB
         Where Cod_Estabe = @PCodEstabe 
           and Ser_Nota = @PSerNota 
           and Num_Nota = @PNumNota
           and Cod_Produto = @CodPrd
           and Cod_Lote = @CodLot
           and Num_SeqIte = @SeqIte
    else
      Insert Into @Tab (Obs_Fiscal)
        Select Des_Observ From NEIOB
         Where Cod_Estabe = @PCodEstabe 
           and Protocolo = @PNumNota
           and Cod_Produto = @CodPrd
           and Cod_Lote = @CodLot
           and Num_SeqIte = @SeqIte

    While Exists(Select 1 From @Tab)
      begin
        Select top 1
               @ChaveTab = ChaveTab
             , @WObsFis = Obs_Fiscal
          From @Tab
         Order by ChaveTab

        if PatIndex(@WObsFis+'%', @WDesCplProduto) = 0
          begin
            if (Len(@WDesCplProduto) > 0) and
               (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
              Set @WDesCplProduto = @WDesCplProduto + ';  '
            Set @WDesCplProduto = @WDesCplProduto + @WObsFis
          end

        Delete From @Tab Where ChaveTab = @ChaveTab
      end


    if (@pm_CodImpDscFab = '1') and (@WDesFabric <> '')
      Set @WDesProduto = @WDesProduto+' ('+Substring(@WDesFabric,1,5)+')'
    if @WTipPor344 <> ''
      Set @WDesProduto = @WDesProduto+' ('+@WTipPor344+')'  
    if @WTipSai = 'B'                     
      Set @WDesProduto = @WDesProduto+' **Bonific.**'

    if (@CodLot = '') and (@WCodLotOri <> '')
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + 'Lote: '+@WCodLotOri
      end
    
    if (@pm_CodImpPrcFab = '1') and (@WPrcFabric > 0)
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + 'PF: '+CAST(cast(@WPrcFabric as numeric(12,2)) as varchar)
      end


    Set @WTipLisPis = Case              
                        When @WTipLisPis = 'P' then '(+)'
                        When @WTipLisPis = 'N' then '(-)'
                        When @WTipLisPis = 'X' then '(n)'
                        When @WTipLisPis = 'O' then '(o)'
                      End
    if (Len(@WDesCplProduto) > 0) and
       (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
      Set @WDesCplProduto = @WDesCplProduto + ';  '
    Set @WDesCplProduto = @WDesCplProduto+'Lista '+@WTipLisPis

    -- desconto repasse
    if @WPerRepIcm > 0
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + 'Repasse '+CAST(cast(@WPerRepIcm as numeric(8,2)) as varchar)+'%'
      end

    -- desconto total (-repasse)
    Set @WPerDsc = 0
    if (@WVlrDscTotIte > 0) and (@WVlrTotBruIte > 0) 
      begin
	    if @WPerDscIte > 0 
		  Set @WPerDsc = @WPerDscIte
		else
          Set @WPerDsc = Round(@WVlrDscTotIte*100/@WVlrTotBruIte,2)
        if @WPerDsc > 0
          Set @WDesCplProduto = @WDesCplProduto + 'Desc.'+CAST(cast(@WPerDsc as numeric(8,2)) as varchar)+'%  '
      end

    if (@pm_FlgImpDscEmbNot = 1) and (@WFlgDscItePdv = 1) and (@WPerDscPdv > 0) 
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + 'Desc.Emb.'+CAST(cast(@WPerDscPdv as numeric(8,2)) as varchar)+'%'
      end
    
    if ((@WVlrBasSbtRes+@WVlrBasSbtEmb) > 0) and
       ((@WVlrSbtRes+@WVlrSbtEmb) > 0)
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + 'BCRE: '+CAST(cast((@WVlrBasSbtRes+@WVlrBasSbtEmb) as numeric(12,2)) as varchar)
        Set @WDesCplProduto = @WDesCplProduto + '  VRE: '+CAST(cast((@WVlrSbtRes+@WVlrSbtEmb) as numeric(12,2)) as varchar)
      end   
  
/*    
    if @WVlrDscTri > 0
      if Charindex(@WTipCon,';P;E;M;') > 0  -- consumidor final
        Set @WDesCplProduto = @WDesCplProduto + 'ICMS abatido no valor de '+CAST(cast(@WVlrDscTri as numeric(12,2)) as varchar)+'  '
          else
      if @WPerDscTri > 0
        Set @WDesCplProduto = @WDesCplProduto + 'Desc.Repasse '+ CAST(cast(@WVlrDscTri as numeric(12,2)) as varchar) +'/'+CAST(@WPerDscTri as varchar)+'%  '
*/

    if @WStrVolEmb <> ''
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + @WStrVolEmb
      end

    if @WObsIteNf <> ''
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + @WObsIteNf
      end
---------------------------------------------------------------------------------------------------

    Update #TMP_Itens
      Set Des_Produto = @WDesProduto,
          Obs_Produto = Substring(@WDesCplProduto,1,500)
    Where Chave = @Chave

  FETCH NEXT FROM ITENS_Cr INTO @Chave, @CodPrd, @SeqIte, @CodLot, @WCodLotOri, @WTipLisPis, @WVlrTotBruIte, @WVlrDscTotIte,
                                @WFlgDscItePdv, @WPrcUniPdv, @WPerDscPdv, @WPrcFabric,
                                @WVlrBasSbtRes, @WVlrSbtRes, @WVlrBasSbtEmb, @WVlrSbtEmb, @WTipCon,
                                @WVlrDscTri, @WPerDscTri, @WDesProduto, @WDesFabric, @WTipPor344, @WTipSai, 
                                @WStrVolEmb, @WObsIteNf, @WVlrBasRepIcm, @WPerRepIcm, @WVlrRepIcm, @WPerDscIte, @WVlrTotLiqIte
END

CLOSE ITENS_Cr
DEALLOCATE ITENS_Cr     
      
----------------------------------------------------------------------------------------------------------

Set @WSelect = 'Select cProd = Cod_Produto, 
       cEAN = Cod_EAN, 
       NCM = Cod_NCM, 
       nItem = Num_SeqIte,
       nItemPed = Num_SeqPdc,
       Cod_GrpPrc = Cod_GrpPrc,
       CFOP = Cod_Cfo, 
       Tip_Por344,
       xProd = Des_Produto,
       cProdANVISA = Reg_MS, 
       xMotivoIsencao = Des_MtvIseRegMS,

       infAdProd = Obs_Produto,
       uCom = Und_Com,
       qCom = Qtd_Com,
       vUnCom = Prc_UniCom,
       vProd = Vlr_TotBruIte,
       vDesc = Vlr_DscTotIte + Vlr_RepIcm,
       Vlr_LiqMer = Vlr_TotIte,
       Vlr_BasSbtRes, Vlr_SbtRes, 
       nLote = Cod_Lote, 
       dVal = Dat_Vencim,
       dFab = Dat_Fabric,
       vFrete = Vlr_Frete,
       vSeg = Vlr_Seguro,
       vOutro = Vlr_TotDsp,
       uTrib = Und_Tri,
       qTrib = Qtd_Tri,
       vUnTrib = Prc_UniTri,

       orig = Cod_OriPrd,
       CST_Icm = Cod_CstIcm,
       CSOSN_Icm = Cod_CsosnIcm,
       modBC = Cod_ModBasCalIcm,
       pRedBC = Per_RedBasCalIcm, 
       vBC = Vlr_BasIcm, 
       pICMS = Alq_Icm - Alq_FcpIcm, 
           
       vICMSOp = Vlr_IcmPro,
       pDif = Per_IcmDiferi,
       vIcmsDif = Case 
                    When Vlr_IcmDiferi > 0 then 
                      Case 
                        When Vlr_IcmDiferi = (Vlr_IcmPro - (Vlr_Icm - Vlr_FcpIcm)) then Vlr_IcmDiferi 
                        Else (Vlr_IcmPro - (Vlr_Icm - Vlr_FcpIcm)) 
                      End
                    Else 0
                  End,
       vICMS = Vlr_Icm - Vlr_FcpIcm, 
       vICMSDeson = Vlr_IcmDesone, 
       motDesICMS = Cod_MtvIcmDesone,

       modBCST = Cod_ModBasCalIcmSbt,
       pMVAST = Alq_AgrSbt, 
       pRedBCST = Per_RedBasCalIcmSbt,
       vBCST = Vlr_BasIcmSbt, 
       pICMSST = Alq_IcmSbt - Alq_FcpSbt, 
       vICMSST = Vlr_IcmSbt - Vlr_FcpSbt,
       
       CST_Ipi, cEnq = Cod_EnqIpi,
       vBCIPI = Vlr_BasIpi+Vlr_BasDevIpi, 
       pIPI = Alq_Ipi, vIPI = Vlr_Ipi,
       pDevol = Per_DevIpi, vIPIDevol = Vlr_DevIpi,

       CST_Pis, Vlr_BasPis, Alq_Pis, Vlr_Pis,
       CST_Cofins, Vlr_BasCofins, Alq_Cofins, Vlr_Cofins, 
       vPMC = Prc_MaxCon, 
       Prc_Fabric,
  
       CEST = Cod_CEST,

       vBCUFDest = Vlr_BasIcmDes,
       vBCFCPUFDest = Vlr_BasIcmDes,
       pFCPUFDest = Per_AcrAlqIntFcp, 
       pICMSUFDest = Alq_IntDes,    
       pICMSInter = Alq_Interesta,
       pICMSInterPart = Per_PrvParIcm,

       vFCPUFDest = Vlr_IcmFcpDes,
       vICMSUFDest = Vlr_IcmParDes,    
       vICMSUFRemet = Vlr_IcmParRem,

       vBCFCP = Vlr_BasIcm,
       pFCP = Alq_FcpIcm,         
       vFCP = Vlr_FcpIcm,         

       vBCFCPST = Vlr_BasIcmSbt,
       pFCPST = Alq_FcpSbt,       
       vFCPST = Vlr_FcpSbt,       

       vBCSTRet, 
       pST,
       vICMSSubstituto,
       vICMSSTRet,

       vBCFCPSTRet,
       pFCPSTRet, 
       vFCPSTRet, 

       pRedBCEfet,
       vBCEfet,
       pICMSEfet,
       vICMSEfet,
           
       cBenef, 
       xPed = Cod_PedCmpCli   
       
From #TMP_Itens '

if @pm_CtrImpIteNotFis = 'A'
  Set @WSelect = @WSelect +'Order by xProd'
else  
  Set @WSelect = @WSelect +'Order by cProd'

Exec (@WSelect)

DROP TABLE #TMP_Itens

RETURN;

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CalcTributNFSIT]
@PCodEstabe int,
@PSerNot varchar(3),
@PNumNot int,
@PCodPrd int,
@PCodLot varchar(20),
@PNumSeqIte int,
@PTipNot char(1),    -- descartar
@PRegTri int,        -- descartar
@PCodOpe varchar(3)  -- descartar

AS

SET NOCOUNT ON 

Begin Transaction

-- variaveis que serão gravadas na NFSIT
Declare @PFlgPrcUniAcrIcm bit,
        @PPrcUni numeric(18,8),
        @PPerDscIte numeric(9,6),
        @PPrcUniSemAcrIcm numeric(18,8),    
        @PPrcUniComAcrIcm numeric(18,8),
        @PPrcFab numeric(18,4),
        @PPrcVen numeric(18,4),
        @PPrcMax numeric(18,4),
        @PPrcRefFpb numeric(18,4),
        @PPrcUltEnt numeric(18,4),
        @PVlrDscRat numeric(18,4),
        
        @PFlgValDscSuframa bit, 
        @PVlrBasTri numeric(18,4),
        @PCodSt varchar(2),
        @PCodCsosn varchar(3),
        @PClaTri varchar(4),
        @PCodModBasCalIcm varchar(1),
        @PAlqIcm numeric(18,4),
        @PPerRedBasCalIcm numeric(18,4),
        @PBasIcmNor numeric(18,4),
        @PIcmNor numeric(18,4),
        @PBasRep numeric(18,4),
        @PVlrRep numeric(18,4),
        @PVlrPrdSub numeric(18,4),
        @PVlrBasCalSubTriEntMed numeric(18,4),
        @PCodModBasCalIcmSbt varchar(1),
        @PAlqIcmSbt numeric(18,4),
        @PAlqAgrSbt numeric(18,4),
        @PPerRedBasCalIcmSbt numeric(18,4),
        @PBasSub numeric(18,4),
        @PVlrSub numeric(18,4),
        @PBasRes numeric(18,4),
        @PVlrRes numeric(18,4),
        @PBasDscTri numeric(18,4),      -- desconto de tributacao (Pernambuco)
        @PPerDscTri numeric(9,4),       -- desconto de tributacao (Pernambuco)
        @PVlrDscTri numeric(18,4),      -- desconto de tributacao (Pernambuco)
        @PBasRecSbt numeric(18,4),
        @PVlrRecSbt numeric(18,4),
        @PBasIcm numeric(18,4),      -- icms tributavel
        @PVlrIcm numeric(18,4),      -- icms tributavel
        @PVlrIse numeric(18,4),
        @PVlrOut numeric(18,4),
        @PCstPis varchar(2),
        @PVlrBasPis numeric(18,4),
        @PAlqPis numeric(18,4),
        @PVlrPis numeric(18,4),
        @PCstCof varchar(2),
        @PVlrBasCof numeric(18,4),
        @PAlqCof numeric(18,4),
        @PVlrCof numeric(18,4),
        @PVlrDsp numeric(18,4),
        @PCodCfo smallint,
        
        @PAlqIntIcmUfDes numeric(18,4),
        @PPerFcpUfDes numeric(18,4),
        @PPerParIcmUfDes numeric(18,4),
        @PVlrFcpUfDes numeric(18,4),
        @PVlrParIcmUfDes numeric(18,4),
        @PVlrParIcmUfRem numeric(18,4),

        @PVlrIcmDesone numeric(18,4),          -- icms desonerado
        @PMtvIcmDesone varchar(1),             -- cpd.motivo icms desonerado
        @PFlgIncFis bit,                       -- incentivo fiscal
        @PVlrDscSuframa numeric(18,4),         -- desconto suframa

        @PFlgUsaDebPresum bit,
        @PAlqDebPresum numeric(18,4),
        @PObsNf varchar(200),

        @PAlqIcmFcp numeric(18,4),
        @PVlrIcmFcp numeric(18,4),          -- icms tributavel FCP: embutido em @PVlrIcm
        @PAlqIcmSbtFcp numeric(18,4),
        @PVlrSubFcp numeric(18,4),
        @PAlqIcmSbtFcpRet numeric(18,4),
        @PVlrSubFcpRet numeric(18,4),

        @PPerIcmDiferi numeric(18,4),
        @PVlrIcmDiferi numeric(18,4),

        @PPrcPon numeric(18,4),

        @PCodOriMer varchar(1), 
        @PCstIpi varchar(2), 
        @PVlrBasIpi numeric(18,4), 
        @PAlqIpi numeric(7,4), 
        @PVlrIpi numeric(18,4), 
        @PCodEnqIpi varchar(3),		

        @PAlqIrf numeric(18,4)   -- Imposto de Renda Retido na Fonte        

-- variaveis de trabalho
Declare @WCodCfoNor smallint,
        @WCodCfoSbt smallint,
        @WCodCfoBon smallint,
        @WFlgSbtEmbPrc bit,
        @WFlgOpeInt bit,
        @WDscIteIcm numeric(18,4)

-- coloca campos de NFSCB na memoria
Declare @cb_CodOpe varchar(3),
        @cb_CodRegTri int,
        @cb_TipSai varchar(1),
        @cb_Per_DescontoCom numeric(18,4),
        @cb_CodCfo smallint,
        @cb_Estado varchar(2),
        @cb_DatEmi smalldatetime,
        @cb_TipRetImp varchar(1),
        @cb_InsSufram varchar(9),  -- inscricao suframa
        @cb_TipCon varchar(1),
        @cl_CodRamAtv int,
		@rt_FlgConsumFin bit,
        @rt_FlgUsaCfoSbtSaiIntGenSim bit,
        @rt_FlgDscIcmOrgPubSemAcr bit,
        @rt_FlgDscIcmOrgPubComAcr bit,
        @em_CodEst varchar(2),
		@em_FlgContriSubstituido bit,
        @pm_QtdDecPrcItePdv smallint

Select @em_CodEst = Des_Estado,
       @em_FlgContriSubstituido = IsNull(Flg_ContriSubstituido,0)
  From ESTAB
 Where Cod_Estabe = @PCodEstabe  

Select @pm_QtdDecPrcItePdv = ISNULL(QtdDecPrcItePdv,0)
  From PARAM
 Where Cod_Estabe = @PCodEstabe

-- indica se reduz aliq. PIS/COFINS
Set @cl_CodRamAtv = 0

Select @cb_TipSai = IsNull(cb.Tip_Saida,''),
       @cb_CodRegTri = IsNull(cb.Cod_RegTri,0),
       @cb_CodOpe = cb.Cod_Ope,
       @cb_DatEmi = cb.Dat_Emissao,
       @cb_Per_DescontoCom = Isnull(cb.Per_DescontoCom,0),
       @cb_CodCfo = IsNull(cb.Cod_Cfo1,0),
       @cb_Estado = cb.Estado,
       @cb_TipRetImp = cb.Tip_RetImp,
       @cb_InsSufram = ISNULL(cb.Inscricao_Suframa,''),
       @cb_TipCon = dbo.FN_CodTipConsum (cb.Tip_Consumidor, '', cb.Cgc, cb.Cgf, cb.Estado),
       @cl_CodRamAtv = IsNull(cl.Cod_RamoAtividade,0),
	   @rt_FlgConsumFin = IsNull(rt.Flg_ConsumFin,0),
       @rt_FlgUsaCfoSbtSaiIntGenSim = IsNull(rt.Flg_UsaCfoSbtSaiIntGenSim,0),
       @rt_FlgDscIcmOrgPubSemAcr = IsNull(rt.Flg_DscIcmOrgPub,0),
       @rt_FlgDscIcmOrgPubComAcr = IsNull(rt.Flg_DscIcmOrgPubAcr,0)

  From NFSCB cb 
       Left Join CLIEN cl on cb.Cod_Cliente = cl.Codigo 
       Left Join RGTRI rt on cb.Cod_RegTri = rt.Cod_RegTri
 Where cb.Cod_Estabe = @PCodEstabe 
   and cb.Ser_Nota = @PSerNot and cb.Num_Nota = @PNumNot

-- operacao interna ou externa
if @cb_Estado = @em_CodEst
  Set @WFlgOpeInt = 1
else
  Set @WFlgOpeInt = 0

-- colococa campos de TPOPE na memoria
Declare @to_CodCfoConFinInt smallint,
        @to_CodCfoConFinExt smallint,
	    @to_CodCfoNorInt smallint,
        @to_CodCfoNorExt smallint,
        @to_CodCfoSbtInt smallint,
        @to_CodCfoSbtExt smallint,
        @to_CodCfoSubstituidoInt smallint,
        @to_CodCfoSubstituidoExt smallint,
        @to_FlgCalIcmSbt bit = 0,
        @to_FlgCalIcmNor bit = 0,
        @to_FlgCalRepIcm bit = 0,
        @to_FlgCalPisCof bit = 0,
		@to_FlgCalIpi    bit = 0

Set @WCodCfoNor = 0
Set @WCodCfoSbt = 0
Set @WCodCfoBon = 0
Set @to_FlgCalIcmSbt = 0
Set @to_FlgCalIcmNor = 0
Set @to_FlgCalRepIcm = 0
Set @to_FlgCalPisCof = 0
Set @to_FlgCalIpi = 0

if Exists(Select Cod_Ope From TPOPE Where Cod_Ope = @cb_CodOpe)
  begin
    Select @to_FlgCalIcmSbt = case 
                                When @WFlgOpeInt = 1 then Isnull(Flg_CalIcmSbt,0)
                                else Isnull(Flg_CalIcmSbtExt,0)
                              end,
           @to_FlgCalIcmNor = case 
                                When @WFlgOpeInt = 1 then Isnull(Flg_CalIcmNor,0)
                                else Isnull(Flg_CalIcmNorExt,0)
                              end,
           @to_FlgCalRepIcm = case 
                                When @WFlgOpeInt = 1 then Isnull(Flg_CalRepIcmInt,0)
                                else Isnull(Flg_CalRepIcm,0)
                              end,
           @to_FlgCalPisCof = IsNull(Flg_CalPisCof,0),
           @to_FlgCalIpi = Isnull(Flg_CalIpi,0),

	       @to_CodCfoConFinInt = IsNull(Cod_CfoConFinInt,0),
	       @to_CodCfoConFinExt = IsNull(Cod_CfoConFinExt,0),
	       @to_CodCfoNorInt = Isnull(Cod_CfoNorInt,0),       
           @to_CodCfoNorExt = Isnull(Cod_CfoNorExt,0),
           @to_CodCfoSbtInt = Case 
                                When @em_FlgContriSubstituido = 1 and IsNull(Cod_CfoSbtIntSubstituido,0) > 0 then Cod_CfoSbtIntSubstituido
			                    Else Isnull(Cod_CfoSbtInt,0)
	 				          End, 
           @to_CodCfoSbtExt = Case 
	                            When @em_FlgContriSubstituido = 1 and IsNull(Cod_CfoSbtExtSubstituido,0) > 0 then Cod_CfoSbtExtSubstituido
					            Else Isnull(Cod_CfoSbtExt,0)
					          End,
           @to_CodCfoSubstituidoInt = IsNull(Cod_CfoSbtIntSubstituido,0),
           @to_CodCfoSubstituidoExt = IsNull(Cod_CfoSbtExtSubstituido,0)

      From TPOPE
     Where Cod_Ope = @cb_CodOpe

    if @rt_FlgConsumFin = 1
      if @WFlgOpeInt = 1
	    begin
          Set @WCodCfoNor = @to_CodCfoConFinInt
          Set @WCodCfoSbt = @to_CodCfoConFinInt
          Set @WCodCfoBon = 5910
        end
      else
	    begin
          Set @WCodCfoNor = @to_CodCfoConFinExt
          Set @WCodCfoSbt = @to_CodCfoConFinExt
          Set @WCodCfoBon = 6910
        end
    else
      if @WFlgOpeInt = 1
        begin
          Set @WCodCfoNor = @to_CodCfoNorInt
          Set @WCodCfoSbt = @to_CodCfoSbtInt
          Set @WCodCfoBon = 5910
        end
      else
        begin
          Set @WCodCfoNor = @to_CodCfoNorExt
          Set @WCodCfoSbt = @to_CodCfoSbtExt
          Set @WCodCfoBon = 6910
        end
  end  -- if Exists(Select Cod_Ope From TPOPE Where Cod_Ope = @cb_CodOpe)

-- coloca campo de PRODU na memoria
Declare @pr_Cod_OriMer varchar(1),
        @pr_Desconto bit,
        @pr_FlgBlqInfPar bit,
        @pr_FlgIncFis bit,
        @pr_TipLisPis varchar(1),
        @pr_CodGrpPrc varchar(1)

Select @pr_Cod_OriMer = IsNull(p.Cod_OriMer,'0'),
       @pr_Desconto = Isnull(p.Flg_BlqDsc,0),
       @pr_FlgBlqInfPar = Isnull(p.Flg_BlqInfPar,0),
       @pr_TipLisPis = pr.Tip_LisPis,
	   @pr_FlgIncFis = pr.Flg_IncFis,
       @pr_CodGrpPrc = ISNULL(pr.Cod_GrpPrc,'')
  From PRXES p 
       Inner Join PRODU pr on p.Cod_Produt = pr.Codigo
 Where p.Cod_Estabe = @PCodEstabe
   And p.Cod_Produt = @PCodPrd

-- coloca campos de NFSIT na memoria
Declare @it_PerDscEmbPrc numeric(7,4),
        @it_PrcUniSemDscEmb numeric(18,8),
        @it_PrcVen numeric(18,4),
        @it_PrcUltEnt numeric(18,4),
        @it_PrcFab numeric(18,4),
        @it_PrcMax numeric(18,4),
        @it_PrcRefFpb numeric(18,4),
        @it_PrcPonFin numeric(18,4),

        @it_FlgDscItePdv bit, 
        @it_QtdPed int,
        @it_QtdBon int,
        
        @it_VlrDscBonRat numeric(18,4),
        @it_VlrDscRat numeric(18,4),
        @it_VlrTotDspRat numeric(18,4),

        @it_CstIpi varchar(2),
        @it_VlrBasIpi numeric(18,4),
        @it_AlqIpi numeric(7,4),
        @it_VlrIpi numeric(18,4),
        @it_CodEnqIpi varchar(3)

-- normaliza valores em NFSIT
Update NFSIT
   Set Fat_CnvImpFat = 1
 Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot 
   And Cod_Produto = @PCodPrd and Cod_Lote = @PCodLot and Num_SeqIte = @PNumSeqIte
   And ISNULL(Fat_CnvImpFat,0) = 0

Update NFSIT
   Set Fat_CnvImpFat = Case
                         When Isnull(Fat_CnvImpFat,0) > 0 Then Isnull(Fat_CnvImpFat,0)
                         Else 1
                       End             
 Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot 
   And Cod_Produto = @PCodPrd and Cod_Lote = @PCodLot and Num_SeqIte = @PNumSeqIte
   And ISNULL(Fat_CnvImpFat,0) = 0

Select @PPrcUni = Isnull(Prc_Unitario,0),
       @PPerDscIte = Isnull(Per_Desconto,0),
       @it_PerDscEmbPrc = IsNull(Per_DscPdv,0),
       @it_PrcUniSemDscEmb = IsNull(Prc_UniPdv,0),
       @PFlgPrcUniAcrIcm = IsNull(Flg_PrcUniAcrIcm,0),
       @PPrcUniSemAcrIcm = IsNull(Prc_UniSemAcrIcm,0),
       @PPrcUniComAcrIcm = IsNull(Prc_UniComAcrIcm,0),
       @it_PrcVen = Isnull(Prc_TabBru,0),
       @it_PrcUltEnt = Isnull(Prc_LiqUltEnt,0),
       @it_PrcFab = Isnull(Prc_Fabric,0),
       @it_PrcMax = Isnull(Prc_MaxCon,0),
       @it_PrcRefFpb = Isnull(Prc_RefFpb,0),
       @it_PrcPonFin = IsNull(Prc_PonFin,0),
       @it_CstIpi = IsNull(CST_Ipi,''), 
       @it_VlrBasIpi = IsNull(Vlr_BasIpi,0), 
       @it_AlqIpi = IsNull(Alq_Ipi,0), 
       @it_VlrIpi = IsNull(Vlr_IPi,0), 
       @it_CodEnqIpi = IsNull(Cod_EnqIpi,''),
       @it_QtdPed = Isnull(Qtd_Produto,0),
       @it_QtdBon = Isnull(Qtd_Bonificacao,0),
       @it_VlrDscBonRat = ISNULL(Vlr_DscBonRat,0),
       @it_VlrDscRat = ISNULL(Vlr_DescRateado,0),
       @it_VlrTotDspRat = Isnull(Vlr_DespRateada,0)+Isnull(Vlr_Frete,0)+IsNull(Vlr_Seguro,0),
	   @it_FlgDscItePdv = IsNull(Flg_DscItePdv,0)
  From NFSIT 
 Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot and 
       Cod_Produto = @PCodPrd and Cod_Lote = @PCodLot and Num_SeqIte = @PNumSeqIte

-- calcula tributos
Set @PBasRecSbt = 0
Set @PVlrRecSbt = 0

-- verifica se embutiu ST no preço unitario
Set @WFlgSbtEmbPrc = 0
if Exists(Select Cod_Produto
            From NSOIT
           Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot and 
                 Cod_Produto = @PCodPrd and Cod_Lote = @PCodLot and Num_SeqIte = @PNumSeqIte)
  Set @WFlgSbtEmbPrc = 1        

Set @PFlgValDscSuframa = 0
if (@cb_InsSufram <> '') and (@pr_FlgIncFis = 1)
  Set @PFlgValDscSuframa = 1

/* aqui retirei
if (@it_PrcUniSemDscEmb > 0) and (@it_PerDscEmbPrc > 0)
  begin
    Set @PPerDscIte = @it_PerDscEmbPrc
    Set @PPrcUni    = @it_PrcUniSemDscEmb
  end
*/

-- normaliza CFO
if (@WCodCfoNor = 0) or (@WCodCfoSbt= 0)
  EXEC PR_CfopEntSai @PCodEstabe, @cb_CodCfo, @WCodCfoNor output, @WCodCfoSbt output

Exec PR_CalcTributItemSaida  @PCodEstabe, @cb_DatEmi, @PRegTri, @cb_Per_DescontoCom, @PTipNot, @cb_CodCfo, @cl_CodRamAtv, @cb_Estado, 
                             @PFlgValDscSuframa, @to_FlgCalIcmSbt, @to_FlgCalIcmNor, @to_FlgCalRepIcm, @to_FlgCalPisCof, @to_FlgCalIpi, @WFlgSbtEmbPrc,
                             @PCodPrd, @it_QtdPed, @it_QtdBon, @PPrcUni output, @PPerDscIte, @it_FlgDscItePdv,
                             @it_VlrDscBonRat, @it_VlrDscRat, @it_VlrTotDspRat,
                             @it_PrcVen, @it_PrcUltEnt, @it_PrcFab, @it_PrcMax, @it_PrcRefFpb, @it_PrcPonFin,
                             @it_CstIpi, @it_VlrBasIpi, @it_AlqIpi, @it_VlrIpi, @it_CodEnqIpi,
							 @PFlgPrcUniAcrIcm output, @PPrcUniSemAcrIcm output, @PPrcUniComAcrIcm output,
	                         @PPrcVen output, @PPrcUltEnt output, @PPrcFab output, @PPrcMax output, @PPrcRefFpb output, @PVlrDscRat output, 
                             @PVlrBasTri output, @PCodSt output, @PCodCsosn output, @PClaTri output, @PCodModBasCalIcm output, @PAlqIcm output, @PPerRedBasCalIcm output,
                             @PBasIcmNor output, @PIcmNor output, @PBasRep output, @PVlrRep output,
                             @PVlrPrdSub output, @PVlrBasCalSubTriEntMed output, @PCodModBasCalIcmSbt output, @PAlqIcmSbt output, @PAlqAgrSbt output, @PPerRedBasCalIcmSbt output,
                             @PBasSub output, @PVlrSub output, @PBasRes output, @PVlrRes output, @PBasDscTri output, @PPerDscTri output, @PVlrDscTri output,
                             @PBasIcm output, @PVlrIcm output, @PVlrIse output, @PVlrOut output,
                             @PCstPis output, @PVlrBasPis output, @PAlqPis output, @PVlrPis output,
                             @PCstCof output, @PVlrBasCof output, @PAlqCof output, @PVlrCof output,
                             @PVlrDsp output,
                             @PAlqIntIcmUfDes output, @PPerFcpUfDes output, @PPerParIcmUfDes output,
                             @PVlrFcpUfDes output, @PVlrParIcmUfDes output, @PVlrParIcmUfRem output,
							 @PVlrIcmDesone output, @PMtvIcmDesone output, @PFlgIncFis output, @PVlrDscSuframa output,
							 @PFlgUsaDebPresum output, @PAlqDebPresum output, @PObsNf output,
                             @PAlqIcmFcp output, @PVlrIcmFcp output, @PAlqIcmSbtFcp output, @PVlrSubFcp output, @PAlqIcmSbtFcpRet output, @PVlrSubFcpRet output,
                             @PPerIcmDiferi output, @PVlrIcmDiferi output, @PPrcPon output,
                             @PCodOriMer output, @PCstIpi output, @PVlrBasIpi output, @PAlqIpi output, @PVlrIpi output, @PCodEnqIpi output

-- define CFOP do item conforme CST
if Charindex(@PCodSt,';10;30;60;70;90;') > 0 
  Set @PCodCfo = @WCodCfoSbt
else
  Set @PCodCfo = @WCodCfoNor

-- verifica CFOP de genericos e similares em op.internas: alterado verifica CFOP para operações com debito presumido
--if (@WFlgOpeInt = 1) and (@rt_FlgUsaCfoSbtSaiIntGenSim = 1) and
--   (CHARINDEX(@pr_CodGrpPrc,';G;S;') > 0) and (@PCodCfo = @WCodCfoNor)
--  Set @PCodCfo = @WCodCfoSbt   
if (@rt_FlgUsaCfoSbtSaiIntGenSim = 1) and
   (@PFlgUsaDebPresum = 1) and (@PAlqDebPresum > 0) and (@PAlqDebPresum <> @PAlqIcm)
  Set @PCodCfo = @WCodCfoSbt   

-- verifica CFOP contribuinte substituto (5403), substituido (5405)
--if Charindex(@cb_Estado,';PE;SC;RS;') > 0
--  begin
--    if (@PCodCfo = 5403) or (@PCodCfo = 5405)
--      if Charindex(@PCodSt,';10;30;70;90;') > 0
--        Set @PCodCfo = 5403
--      else
--        Set @PCodCfo = 5405
--  end

if (@rt_FlgConsumFin = 0) and (@PCodSt = '60')
  if @WFlgOpeInt = 1
    begin
      if (@PCodCfo <> @to_CodCfoSubstituidoInt) and (@to_CodCfoSubstituidoInt > 0)
        Set @PCodCfo = @to_CodCfoSubstituidoInt
    end
else
  if @WFlgOpeInt = 0
    begin
      if (@PCodCfo <> @to_CodCfoSubstituidoExt) and (@to_CodCfoSubstituidoExt > 0)
        Set @PCodCfo = @to_CodCfoSubstituidoExt
    end

-- grava Ramo Atividade em NFSCB
Update NFSCB
   Set Cod_RamAtv = @cl_CodRamAtv
 Where Cod_Estabe = @PCodEstabe 
   and Ser_Nota = @PSerNot 
   and Num_Nota = @PNumNot 
   and Cod_RamAtv <> @cl_CodRamAtv

-- grava valores em NFSIT
Set @pr_FlgBlqInfPar = 0

---- embute desconto no preço
if (@it_PrcUniSemDscEmb > 0) and (@it_PerDscEmbPrc > 0) and
   (@it_FlgDscItePdv = 1)
  begin
    Set @PPrcUni = Round(@PPrcUni*(1-@PPerDscIte/100),@pm_QtdDecPrcItePdv) 
    Set @PPerDscIte = 0
  end

Update NFSIT
   Set Prc_Unitario  = @PPrcUni,
       Per_Desconto  = @PPerDscIte,
       Prc_UniImpFat = @PPrcUni*Fat_CnvImpFat,
       Flg_PrcUniAcrIcm = @PFlgPrcUniAcrIcm,
       Prc_UniSemAcrIcm = @PPrcUniSemAcrIcm,
       Prc_UniComAcrIcm = @PPrcUniComAcrIcm,
       Tip_Aux = @pr_TipLisPis,
       Flg_BlqDsc = @pr_Desconto,
       Flg_BlqInfPar = @pr_FlgBlqInfPar,
       Cod_Cfo = Case 
                   When (Cod_Cfo = 5910) or (Cod_Cfo = 6910) Then Cod_Cfo
                   Else @PCodCfo
                 End,
       Cod_OriMer = @PCodOriMer,
       Ctrl_Tributacao = @PCodSt,
       Cod_CSOSN = @PCodCsosn,
       Cod_Tribut = @PCodOriMer+@PCodSt,
       Cod_ClaTri = @PClaTri,

       Prc_TabBru = @PPrcVen,
       Prc_Fabric = @PPrcFab,
       Prc_MaxCon = @PPrcMax,
       Prc_RefFpb = @PPrcRefFpb,
       Prc_PonFin = @PPrcPon,
       Prc_LiqUltEnt = @PPrcUltEnt,

       Vlr_DescRateado = @PVlrDscRat,
       Vlr_BasTri = @PVlrBasTri,
       Cod_ModBasCalIcm = @PCodModBasCalIcm,
       Alq_Icms = @PAlqIcm,
       Per_RedBasCalIcm = @PPerRedBasCalIcm,
       Vlr_BasIcmsNor = Round(@PBasIcmNor,2),
       Vlr_IcmsNor = @PIcmNor,
       Vlr_BasRepIcms = Round(@PBasRep,2),
       Vlr_RepIcms = @PVlrRep,

       Vlr_PrdSubTri = Round(@PVlrPrdSub,2),
       Vlr_BasCalSubTriEntMed = @PVlrBasCalSubTriEntMed, 
       Cod_ModBasCalIcmSbt = @PCodModBasCalIcmSbt,
       Alq_IcmSbt = @PAlqIcmSbt,
       Alq_AgrSbt = @PAlqAgrSbt,
       Per_RedBasCalIcmSbt = @PPerRedBasCalIcmSbt,

       Vlr_BasSubsTrib = Round(@PBasSub,2),
       Vlr_SubsTrib = @PVlrSub,
       Vlr_BasSbtRes = Round(@PBasRes,2),
       Vlr_SbtRes = @PVlrRes,

       Vlr_BasDscTri = Round(@PBasDscTri,2),
       Per_DscTri = @PPerDscTri,
       Vlr_DscTri = @PVlrDscTri,

       Vlr_BasRecSbt = Round(@PBasRecSbt,2),
       Vlr_RecSbt = @PVlrRecSbt,

       Vlr_BasIcmsTri = Round(@PBasIcm,2),
       Vlr_IcmsTri = @PVlrIcm,
       Vlr_Isento = Round(@PVlrIse,2),
       Vlr_Outros = Round(@PVlrOut,2),
       Vlr_DspExt = @PVlrDsp,
      
       CST_Pis = @PCstPis, 
       Vlr_BasPis = @PVlrBasPis, 
       Alq_Pis = @PAlqPis, 
       Vlr_Pis = @PVlrPis, 
       CST_Cofins = @PCstCof, 
       Vlr_BasCofins = @PVlrBasCof, 
       Alq_Cofins = @PAlqCof, 
       Vlr_Cofins = @PVlrCof,
	   Obs_Nf = @PObsNf,
      
       Alq_IntIcmDes = @PAlqIntIcmUfDes,
       Per_PrvParIcm = @PPerParIcmUfDes,
       Vlr_IcmParDes = @PVlrParIcmUfDes,
       Vlr_IcmParRem = @PVlrParIcmUfRem,

       Vlr_IcmsDeson = @PVlrIcmDesone, 
       Cod_MtvIcmsDeson = @PMtvIcmDesone,
	   Flg_IncFis = @PFlgIncFis, 
       Vlr_DscCalSuframa = @PVlrDscSuframa,

       Flg_UsaDebPresum = @PFlgUsaDebPresum, 
       Alq_IcmPresum = @PAlqDebPresum,

       Per_AcrAlqIntFcp = @PPerFcpUfDes,
       Vlr_IcmFcpDes = @PVlrFcpUfDes,

       Alq_FcpIcm = @PAlqIcmFcp,
       Vlr_FcpIcm = @PVlrIcmFcp,
       Alq_FcpSbt = @PAlqIcmSbtFcp,
       Vlr_FcpSbt = @PVlrSubFcp,
       Alq_FcpSbtRet = @PAlqIcmSbtFcpRet,
       Vlr_FcpSbtRet = @PVlrSubFcpRet,

       Per_IcmDiferi = @PPerIcmDiferi,
       Vlr_IcmDiferi = @PVlrIcmDiferi,

       CST_Ipi = @PCstIpi, 
       Vlr_BasIpi = @PVlrBasIpi, 
       Alq_Ipi = @PAlqIpi, 
       Vlr_Ipi = @PVlrIpi, 
       Cod_EnqIpi = @PCodEnqIpi 

 Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot 
   And Cod_Produto = @PCodPrd and Cod_Lote = @PCodLot and Num_SeqIte = @PNumSeqIte


if (@cb_TipRetImp = 'R') and (@PVlrSub > 0)
  begin
    if Charindex(@PCodSt,';10;30;70;') > 0
      begin
        if @PVlrIcm > 0
          if @PPerRedBasCalIcm > 0
            Set @PCodSt = '20'    -- tributacao com reducao
          else
            Set @PCodSt = '00'    -- tributacao integral
        else
          Set @PCodSt = '41'    -- nao tributada
      end

    Set @PCodCfo = @WCodCfoNor
    Set @PBasRecSbt = @PBasSub
    Set @PVlrRecSbt = @PVlrSub - @PVlrDscTri
    Set @PBasSub = 0 
    Set @PVlrSub = 0
    Set @PVlrDscTri = 0

    Update NFSIT
       Set Cod_Cfo = Case 
                       When ((Tip_Sai = 'B') or (Cod_Cfo = @WCodCfoBon)) Then @WCodCfoBon
                       Else @PCodCfo
                     End,
           Vlr_BasSubsTrib = Round(@PBasSub,2),
           Vlr_SubsTrib = @PVlrSub,
           Vlr_BasSbtRes = Round(@PBasRes,2),
           Vlr_SbtRes = @PVlrRes,
           Vlr_DscTri = @PVlrDscTri,
           Vlr_BasRecSbt = Round(@PBasRecSbt,2),
           Vlr_RecSbt = @PVlrRecSbt
     Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot 
       And Cod_Produto = @PCodPrd and Cod_Lote = @PCodLot and Num_SeqIte = @PNumSeqIte
  end

-- aqui paleativo
-- Imposto de Renda retido na fonte
-- aliquota não deveria estar aqui nem Base de Cálculo e Valor do Irf
Select @PAlqIrf = ISNULL(rx.Alq_IrfIntLoc,0)
  From NFSIT it 
       inner join NFSCB cb ON cb.Cod_Estabe = it.Cod_Estabe and cb.Num_Nota = it.Num_Nota and cb.Ser_Nota = it.Ser_Nota
       inner join RTXCT rx ON rx.Cod_ClaTri = it.Cod_ClaTri and rx.Cod_RegTri = cb.Cod_RegTri
 Where it.Cod_Produto = @PCodPrd 
   and cb.Ser_Nota = @PSerNot 
   and cb.Num_Nota = @PNumNot

-- recalcula Vlr.Liquido
Update NFSIT
   Set Vlr_BruItem  = Round(Prc_Unitario * (Qtd_Produto + Qtd_Bonificacao),2),
       Vlr_TotItem  = Round(Qtd_Produto * Prc_Unitario*(1-Per_Desconto/100),2),  
       Vlr_DescItem = Round(Prc_Unitario * (Qtd_Produto + Qtd_Bonificacao),2) - Round(Qtd_Produto * Prc_Unitario*(1-Per_Desconto/100),2),
       Vlr_LiqVenIte = Round(Qtd_Produto * Prc_Unitario*(1-Per_Desconto/100),2) -- IsNull(Vlr_TotItem,0) 
                     - IsNull(Vlr_RepIcms,0) - Isnull(Vlr_DescRateado,0) - IsNull(Vlr_DscBonRat,0) - IsNull(Vlr_DscTri,0),

       Vlr_LiqItem = Round(Qtd_Produto * Prc_Unitario*(1-Per_Desconto/100),2) --IsNull(Vlr_TotItem,0) 
                   - IsNull(Vlr_RepIcms,0) - Isnull(Vlr_DescRateado,0) - IsNull(Vlr_DscBonRat,0) - IsNull(Vlr_DscTri,0)
                   + IsNull(Vlr_SubsTrib,0) + IsNull(Vlr_SbtRes,0) + IsNull(Vlr_RecSbt,0) + IsNull(Vlr_Ipi,0) + Isnull(Vlr_DespRateada,0)  + Isnull(Vlr_DspExt,0),

	   Vlr_BasIrf = Case 
                       When @PAlqIrf > 0 Then 
							Round(Qtd_Produto * Prc_Unitario*(1-Per_Desconto/100),2) 
							- IsNull(Vlr_RepIcms,0) - Isnull(Vlr_DescRateado,0) - IsNull(Vlr_DscBonRat,0) - IsNull(Vlr_DscTri,0)
							+ IsNull(Vlr_SubsTrib,0) + IsNull(Vlr_SbtRes,0) + IsNull(Vlr_RecSbt,0) + IsNull(Vlr_Ipi,0) + Isnull(Vlr_DespRateada,0)  + Isnull(Vlr_DspExt,0)
                       Else 0
                    End,	
	   Vlr_Irf =    Case 
                       When @PAlqIrf > 0 Then 
							(Round(Qtd_Produto * Prc_Unitario*(1-Per_Desconto/100),2) 
							- IsNull(Vlr_RepIcms,0) - Isnull(Vlr_DescRateado,0) - IsNull(Vlr_DscBonRat,0) - IsNull(Vlr_DscTri,0)
							+ IsNull(Vlr_SubsTrib,0) + IsNull(Vlr_SbtRes,0) + IsNull(Vlr_RecSbt,0) + IsNull(Vlr_Ipi,0) + Isnull(Vlr_DespRateada,0)  + Isnull(Vlr_DspExt,0) )
							* (@PAlqIrf / 100)
                       Else 0
                    End,
	   Alq_Irf = @PAlqIrf
 Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot 
   And Cod_Produto = @PCodPrd and Cod_Lote = @PCodLot and Num_SeqIte = @PNumSeqIte

Commit Transaction
GO


SET ANSI_NULLS ON 
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CalcDivergNotaPedido]
@PCodEstabe int, 
@PProtocolo Int,
@PTolerancia numeric(4,4),  -- limite diferença do preço
@PFlgGerDiverg bit,         -- gera resgistros em DPNCB/DPNIT
@PFlgTemDiverg bit output

AS

SET NOCOUNT ON

Set Dateformat ymd

Declare @FlgMovEst bit = 0

Set @PFlgTemDiverg = 0

Select @FlgMovEst = ISNull(Flg_MovEst,0) 
  From NFECB 
 Where Cod_Estabe = @PCodEstabe 
   And Protocolo = @PProtocolo

if @FlgMovEst = 0
  begin
    If Exists (Select 1 From DNPCB Where Cod_Estabe = @PCodEstabe And Protocolo = @PProtocolo)
      Delete From DNPCB Where Cod_Estabe = @PCodEstabe And Protocolo = @PProtocolo
    Return
  end

-- Verifica se as divergências da nota já foram feitas
If @PFlgGerDiverg = 1 
  Begin
    If Exists (Select 1 From DNPCB Where Cod_Estabe = @PCodEstabe And Protocolo = @PProtocolo)
      Begin
        RAISERROR('Nota Fiscal já teve divergências calculadas', 16, 1)
        Return
      End
  End

BEGIN
Begin Transaction

-- Variáveis do cursor
Declare @Not_CodProduto int, 
        @Not_Descricao varchar(80), 
        @Not_QtdPedido int, 
        @Not_Prc_Unitar numeric(18,4),
        @Ped_CodProduto int, 
        @Ped_Descricao varchar(80), 
        @Ped_QtdPedido int, 
        @Ped_Prc_Unitar numeric(18,4)

-- Variáveis de trabalho
Declare @DivergCont int,
        @DifPrc Numeric(18,4)

-- coloca parametros na memoria
Declare @pm_FlgIgnQtdMenDvgPdc bit,   -- ignora divergencia qtd menores na NF
        @pm_FlgIgnPrcMenDvgPdc bit    -- igonra precos menores na NF

Select @pm_FlgIgnQtdMenDvgPdc = FlgIgnQtdMenDvgPdc,
       @pm_FlgIgnPrcMenDvgPdc = FlgIgnPrcMenDvgPdc
  From PMESt
 Where Cod_Estabe = @PCodEstabe

-- verifica op.triangular
Declare @ProtocoloVincOpeVdo int = 0,
        @WSerDocVincOpeVdo varchar(3),
        @NumProtocPedCompra int

-- Documento vinculado Op.Triangular
Exec PR_DocOpeTriang @PCodEstabe, @PProtocolo, '', 'E', 
     @WSerDocVincOpeVdo output, @ProtocoloVincOpeVdo output

if Exists(Select 1 From NFEPC 
           Where Cod_Estabe = @PCodEstabe 
             and Protocolo = @PProtocolo)
  Set @NumProtocPedCompra = @PProtocolo
else
  Set @NumProtocPedCompra = @ProtocoloVincOpeVdo

Declare Analise_Cr Cursor Local Fast_Forward For 

  Select Not_CodProduto, Not_Descricao, Not_QtdPedido, Not_Prc_Unitar,
         Ped_CodProduto, Ped_Descricao, Ped_QtdPedido, Ped_Prc_Unitar
    From (-- Itens da nota
          Select I.Cod_Produto Not_CodProduto, 
                 P.Descricao Not_Descricao, 
                 IsNull(Sum(I.Qtd_Pedido),0) Not_QtdPedido, 
                 IsNull(Round(Avg(I.Prc_Unitario * (1 - (I.Per_DescItem/100))),4),0) Not_Prc_Unitar
            From NFEIT I
                 Inner Join PRODU P On (P.Codigo = I.Cod_Produto)
           Where I.Cod_Estabe = @PCodEstabe 
             and I.Protocolo = @PProtocolo
           Group by I.Cod_Produto, P.Descricao) N

       Full Outer Join 

         (-- Itens dos pedidos 
      Select I.Cod_Produto Ped_CodProduto, 
                 P.Descricao Ped_Descricao, 
                 IsNull(Sum(I.Qtd_Pendente),0) Ped_QtdPedido, 
                 IsNull(Round(Avg(I.Prc_Unitario * (1 - (I.Per_Desconto / 100))),4),0) Ped_Prc_Unitar 
            From PDCIT I 
                 Inner Join PRODU P On (P.Codigo = I.Cod_Produto) 
                 Inner Join NFEPC X On (X.Cod_Estabe = I.Cod_Estabe And X.Cod_Pedido = I.Numero) 
           Where X.Cod_Estabe = @PCodEstabe 
             and X.Protocolo = @NumProtocPedCompra
           Group By I.Cod_Produto, P.Descricao) P On (P.Ped_CodProduto = N.Not_CodProduto) 

  Order by Ped_CodProduto
Open Analise_Cr 

Fetch Next From Analise_Cr Into 
  @Not_CodProduto, @Not_Descricao, @Not_QtdPedido, @Not_Prc_Unitar, 
  @Ped_CodProduto, @Ped_Descricao, @Ped_QtdPedido, @Ped_Prc_Unitar

If @PFlgGerDiverg = 1 
  begin
    -- Incluir cabeçalho
    Insert Into DNPCB (Cod_Estabe, Protocolo, Status) 
               Values (@PCodEstabe, @PProtocolo, NULL)
    If (@@error <> 0)
      Begin
        if @@trancount > 0
          Rollback Transaction
        Return
      End
  end

Set @DivergCont = 0 

-- Incluir itens (só inclui se tiver divergência)
While @@FETCH_STATUS = 0
  Begin
    -- Tem na nota e no pedido
    If (@Not_CodProduto Is Not Null) And (@Ped_CodProduto Is Not Null)
      Begin
        -- Verifica se a diferença é permitida
        Set @DifPrc = Abs(@Not_Prc_Unitar - @Ped_Prc_Unitar)

    -- ignora divergencia se preço da NF for menor
    if (@pm_FlgIgnPrcMenDvgPdc = 1) and (@Not_Prc_Unitar < @Ped_Prc_Unitar)
      Set @DifPrc = 0.00

        -- Tem divergência ?
    If (@DifPrc > @PTolerancia) Or ((@pm_FlgIgnQtdMenDvgPdc = 0) and (@Not_QtdPedido <> @Ped_QtdPedido)) or
                                   ((@pm_FlgIgnQtdMenDvgPdc = 1) and (@Not_QtdPedido > @Ped_QtdPedido))
          Begin
            Set @DivergCont = @DivergCont + 1
            If @PFlgGerDiverg = 1 
              Begin
                Insert Into DNPIT (Cod_Estabe, Protocolo, Cod_Produto, Status, Qtd_Nota, Prc_Nota, Qtd_Pedido, Prc_Pedido)
                           Values (@PCodEstabe, @PProtocolo, @Not_CodProduto, 'D', @Not_QtdPedido, @Not_Prc_Unitar, @Ped_QtdPedido, @Ped_Prc_Unitar)
                if (@@error <> 0)
                  Begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  End
              End
          End
      End

    -- Tem na nota e não tem no pedido
    Else 
  If (@Not_CodProduto Is Not Null) And (@Ped_CodProduto Is Null)
      Begin
        Set @DivergCont = @DivergCont + 1
        If @PFlgGerDiverg = 1 
          Begin
            Insert Into DNPIT (Cod_Estabe, Protocolo, Cod_Produto, Status, Qtd_Nota, Prc_Nota, Qtd_Pedido, Prc_Pedido)
                       Values (@PCodEstabe, @PProtocolo, @Not_CodProduto, 'N', @Not_QtdPedido, @Not_Prc_Unitar, Null, Null)
            If (@@error <> 0)
              Begin
                if @@trancount > 0
                  Rollback Transaction
                Return
              End
          End
      End

    -- Tem no pedido e não tem na nota
    Else 
    If (@Ped_CodProduto Is Not Null) And (@Not_CodProduto Is Null) and (@pm_FlgIgnQtdMenDvgPdc = 0)
      Begin
        Set @DivergCont = @DivergCont + 1
        If @PFlgGerDiverg = 1 
          Begin
            Insert Into DNPIT (Cod_Estabe, Protocolo, Cod_Produto, Status, Qtd_Nota, Prc_Nota, Qtd_Pedido, Prc_Pedido)
                       Values (@PCodEstabe, @PProtocolo, @Ped_CodProduto, 'P', Null, Null, @Ped_QtdPedido, @Ped_Prc_Unitar)
            If (@@error <> 0)
              Begin
                if @@trancount > 0
                  Rollback Transaction
                Return
              End
          End
      End

    Fetch Next From Analise_Cr Into 
      @Not_CodProduto, @Not_Descricao, @Not_QtdPedido, @Not_Prc_Unitar, 
      @Ped_CodProduto, @Ped_Descricao, @Ped_QtdPedido, @Ped_Prc_Unitar
  End

Close Analise_Cr
Deallocate Analise_Cr

If @DivergCont > 0
  Set @PFlgTemDiverg = 1

if @@trancount > 0
  Commit Transaction
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_AtualizaSaldoVBFSL]
@CodEstabe int,
@CodVdr int,
@CodFab int,
@DatMov smalldatetime,
@NumPrt int,
@CodPrd int,
@CodLot varchar(20),
@TipMov varchar(1),     --  NFSIT.Tip_Sai,  NFEIT.Tip_Ent
@EntSai char(1),        --  Tip_Docume 'E'- entrada, 'S'- saída, 'M'- manutenção
@CodMov char(1),        --  Tip_NF: 'C, V, 'T', 'O', 'D'   'I'- inicial, 'Z'- zera saldo anterior
@SerDoc varchar(3),     --  serie NF
@NumDoc int,            --  Num NF saída, Protocolo entrada
@ValMov numeric(18,4),  --  Valor com sinal
@DesMov varchar(60),
@DesUsu varchar(15)
 
AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now = GetDate()
Set @Date = cast(GetDate() as date)

Begin Transaction 

if Exists(Select 1 From VBFSL 
           Where Cod_Estabe = @CodEstabe 
             And Cod_Vended = @CodVdr
             And Cod_Movime = 'Z' 
             And Num_Protoc <> 999999999)
  begin
    RAISERROR('Existe Registro com lançamento para zerar verba inválido',16,1)
    Return
  end
else
if Exists(Select 1 From VBFSL 
           Where Cod_Estabe = @CodEstabe 
             And Cod_Vended = @CodVdr
             And Cod_Movime = 'I' 
             And Num_Protoc <> 0)
  begin
    RAISERROR('Existe Registro com lançamento inicial inválido',16,1)
    Return
  end
else
  begin

    Declare @WFlgAtu bit,
            @WFlgLanAut bit

    Set @WFlgLanAut = 0
    if @CodPrd > 0
      Set @WFlgLanAut = 1

    Set @WFlgAtu = 0

    -- se ainda não existe o registro inicial com o valor inicial, inclui
    if @CodMov = 'I'
      if not Exists(Select 1 From VBFSL 
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Vended = @CodVdr 
                       And Cod_Fabric = @CodFab
                       and Dat_Movime = @DatMov 
                       And Cod_Movime = @CodMov
                       and Val_Movime = @ValMov)
        Set @WFlgAtu = 1

    -- se não existe registro para zerar saldo anterior com valor do saldo = 0, inclui
    if @CodMov = 'Z'
      if not Exists(Select 1 From VBFSL 
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Vended = @CodVdr 
                       And Cod_Fabric = @CodFab
                       and Dat_Movime = @DatMov 
                       And Cod_Movime = @CodMov
                       and Val_Movime = @ValMov)
        Set @WFlgAtu = 1

    -- se ainda não existe o registro com os dados informados ou se for registro inicial, inclui
    if (@CodMov <> 'I') and (@CodMov <> 'Z')
      if @NumPrt > 0 
        begin
          if not Exists(Select 1 From VBFSL
                         Where Cod_Estabe = @CodEstabe 
                           And Cod_Vended = @CodVdr
                           And Cod_Fabric = @CodFab
                           And Dat_Movime = @DatMov
                           And Num_Protoc = @NumPrt)
            Set @WFlgAtu = 1
        end
      else
        begin
          if (not Exists(Select 1 From VBFSL
                          Where Cod_Estabe = @CodEstabe 
                            And Cod_Vended = @CodVdr
                            And Cod_Fabric = @CodFab
                            And Cod_Produt = @CodPrd
                            And Cod_Lote = @CodLot
                            And Tip_Sai = @TipMov
                            And Tip_Docume = @EntSai
                            And Ser_Docume = @SerDoc
                            And Num_Docume = @NumDoc
                            And Cod_Movime = @CodMov)) 
          Set @WFlgAtu = 1
        end

    if @WFlgAtu = 1
      begin
        Declare @WSldAnt numeric(18,4),
                @cr_SldAtu numeric(18,4),
                @cr_ValMov numeric(18,4),
                @cr_NumPrt int,
                @cr_DatMov smalldatetime,
                @WValAux numeric(18,4),
                @WFlgRep bit,
                @WSldAtu numeric(18,4)

        -- pega num. do protocolo
        if @CodMov = 'Z'    -- registro zera saldo do mês
          Set @NumPrt = 999999999
        else
        if @CodMov = 'I'    -- registro de lancamento inicial ou registro zera saldo anterior
          Set @NumPrt = 0
        else
          if @NumPrt = 0
            begin
              EXEC PR_ProxNumero 'Verba', @NumPrt output
              if @@error <> 0
                begin
                  Rollback Transaction
                  Return
                end
            end

        Set @WSldAtu = 0
        Set @WFlgRep = 0           

        -- saldo anterior
        if @CodMov = 'I'
          Set @WSldAnt = 0
        else
          Set @WSldAnt = IsNull((Select top 1 Val_SldMovime
                                   From VBFSL
                                  Where Cod_Estabe = @CodEstabe 
                                    And Cod_Vended = @CodVdr
                                    And Cod_Fabric = @CodFab
                                    And ((Dat_Movime = @DatMov and Num_Protoc < @NumPrt) or
                                         (Dat_Movime < @DatMov))
                                  Order by Cod_Vended, Cod_Fabric, Dat_Movime desc, Num_Protoc desc),0)

        if @CodMov = 'I'    -- registro de lancamento inicial
          begin
            -- elimina todos os reg. iniciais a partir da data do atual
            Delete From VBFSL
              Where Cod_Estabe = @CodEstabe 
			  And Cod_Vended = @CodVdr
			  And Cod_Fabric = @CodFab
              and Cod_Movime = 'I'
              and Dat_Movime > @DatMov
            -- se houver linhas deletadas saldo deve ser recalculado
            if @@rowcount > 0
              Set @WFlgRep = 1

            -- se houver alteracao registro existente, saldo deve ser recalculado
            Update VBFSL
               Set Val_Movime = @ValMov
             Where Cod_Estabe = @CodEstabe 
               And Cod_Vended = @CodVdr
               And Cod_Fabric = @CodFab
               and Dat_Movime = @DatMov
               and Cod_Movime = 'I'
               and Val_Movime <> @ValMov
               if @@rowcount > 0
                 Set @WFlgRep = 1           
          end  -- if @CodMov = 'I'

        if @CodMov = 'Z'    -- registro sera saldo anterior
          begin
            -- se houver alteracao registro existente, saldo deve ser recalculado
            Update VBFSL
               Set Val_Movime = -@WSldAnt
             Where Cod_Estabe = @CodEstabe 
               And Cod_Vended = @CodVdr
               And Cod_Fabric = @CodFab
               and Dat_Movime = @DatMov
               and Cod_Movime = 'Z'
               and ( (@ValMov <> -@WSldAnt) or
                     (Val_SldMovime <> 0) )
            if @@rowcount > 0
              Set @WFlgRep = 1           
          end  -- if @CodMov = 'Z'

        -- insere novo registro
        if not Exists(Select 1 From VBFSL
                      Where Cod_Estabe = @CodEstabe 
					    And Cod_Vended = @CodVdr
					    And Cod_Fabric = @CodFab
                        And Dat_Movime = @DatMov
                        And Num_Protoc = @NumPrt)
          begin
            Insert into VBFSL (Cod_Estabe, Cod_Vended, Cod_Fabric, Dat_Movime, Num_Protoc, Cod_Produt, Cod_Lote, Tip_Sai, Tip_Docume, Ser_Docume, Num_Docume, 
                               Cod_Movime, Val_Movime, Val_SldMovime, Des_Movime, Flg_Automatic, Usuario, Transacao)
                        Values(@CodEstabe, @CodVdr, @CodFab, @DatMov, @NumPrt, @CodPrd, @CodLot, @TipMov, @EntSai, @SerDoc, @NumDoc, 
                               @CodMov, @ValMov, @WSldAnt, @DesMov, @WFlgLanAut, @DesUsu, @Now) 
            Set @WSldAtu = @WSldAnt
          end

        -- atualiza saldos
        if @WFlgRep = 0
          begin
            Set @WValAux = @WSldAnt + @ValMov - @WSldAtu
            Update VBFSL 
               Set Val_SldMovime = Val_SldMovime + @WValAux
             Where Cod_Estabe = @CodEstabe 
               And Cod_Vended = @CodVdr
               And Cod_Fabric = @CodFab
               and ((Dat_Movime = @DatMov and Num_Protoc >= @NumPrt) or
                    (Dat_Movime > @DatMov))
          end
        else
          begin
            -- reprocessa saldos a partir do registro de inicio atual
            Set @WSldAnt = 0
            Declare VBFSL_Cr Cursor Local Fast_Forward For 

            Select Dat_Movime, Num_Protoc, Val_Movime, Val_SldMovime
              From VBFSL
             Where Cod_Estabe = @CodEstabe 
               And Cod_Vended = @CodVdr
               And Cod_Fabric = @CodFab
               and ((Dat_Movime = @DatMov and Num_Protoc >= @NumPrt) or
                    (Dat_Movime > @DatMov))
             Order by Dat_Movime, Num_Protoc
            Open VBFSL_Cr
            Fetch Next From VBFSL_Cr Into @cr_DatMov, @cr_NumPrt, @cr_ValMov, @cr_SldAtu
            While @@FETCH_STATUS = 0
              begin
                if @cr_SldAtu <> (@cr_ValMov+@WSldAnt)
                  begin
                    Update VBFSL
                       Set Val_SldMovime = @cr_ValMov+@WSldAnt
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Vended = @CodVdr
                       And Cod_Fabric = @CodFab
                       And Dat_Movime = @cr_DatMov
                       And Num_Protoc = @cr_NumPrt
                    Set @cr_SldAtu = @cr_ValMov+@WSldAnt
                  end
                Set @WSldAnt = @cr_SldAtu
                Fetch Next From VBFSL_Cr Into @cr_DatMov, @cr_NumPrt, @cr_ValMov, @cr_SldAtu
              end
            Close VBFSL_Cr
            Deallocate VBFSL_Cr
          end
      end
  end

Commit Transaction
GO

