SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_AtualizaSaldoVBSLD]
@CodEstabe int,
@CodVdr int,
@DatMov smalldatetime,
@NumPrt int,
@CodPrd int,
@CodLot varchar(20),
@TipMov varchar(1),     --  NFSIT.Tip_Sai,  NFEIT.Tip_Ent
@EntSai char(1),        --  Tip_Docume 'E'- entrada, 'S'- saída, 'M'- manutenção
@CodMov char(1),        --  Tip_NF: 'C, V, 'T', 'O', 'D'   'I'- inicial, 'Z'- zera saldo anterior
@SerDoc varchar(3),     --  serie NF
@NumDoc int,            --  Num NF saída, Protocolo entrada
@ValMov numeric(18,4),  --  Valor com sinal
@DesMov varchar(60),
@DesUsu varchar(15)

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now = GetDate()
Set @Date = cast(GetDate() as date)

Begin Transaction 

if Exists(Select 1 From VBSLD Where Cod_Estabe = @CodEstabe And Cod_Movime = 'Z' And Num_Protoc <> 999999999)
  begin
    RAISERROR('Existe Registro com lançamento para zerar verba inválido',16,1)
    Return
  end
else
if Exists(Select 1 From VBSLD Where Cod_Estabe = @CodEstabe And Cod_Movime = 'I' And Num_Protoc <> 0)
  begin
    RAISERROR('Existe Registro com lançamento inicial inválido',16,1)
    Return
  end
else
  begin
    Declare @WFlgAtu bit,
            @WFlgLanAut bit

    Set @WFlgLanAut = 0
    if @CodPrd > 0
      Set @WFlgLanAut = 1

    Set @WFlgAtu = 0

    -- se ainda não existe o registro inicial com o valor inicial, inclui
    if @CodMov = 'I'
      if not Exists(Select 1 From VBSLD 
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Vended = @CodVdr 
                       and Dat_Movime = @DatMov 
                       And Cod_Movime = @CodMov
                       and Val_Movime = @ValMov)
        Set @WFlgAtu = 1

    -- se não existe registro para zerar saldo anterior com valor do saldo = 0, inclui
    if @CodMov = 'Z'
      if not Exists(Select 1 From VBSLD 
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Vended = @CodVdr 
                       and Dat_Movime = @DatMov 
                       And Cod_Movime = @CodMov
                       And Val_Movime = @ValMov)
        Set @WFlgAtu = 1

    -- se ainda não existe o registro com os dados informados ou se for registro inicial, inclui
    if (@CodMov <> 'I') and (@CodMov <> 'Z')
      if @NumPrt > 0 
        begin
          if not Exists(Select 1 From VBSLD
                         Where Cod_Estabe = @CodEstabe 
                           And Cod_Vended = @CodVdr
                           And Dat_Movime = @DatMov
                           And Num_Protoc = @NumPrt)
            Set @WFlgAtu = 1
        end
      else
        begin
          if (not Exists(Select 1 From VBSLD
                          Where Cod_Estabe = @CodEstabe 
                            And Cod_Vended = @CodVdr
                            And Cod_Produt = @CodPrd
                            And Cod_Lote = @CodLot
                            And Tip_Sai = @TipMov
                            And Tip_Docume = @EntSai
                            And Ser_Docume = @SerDoc
                            And Num_Docume = @NumDoc
                            And Cod_Movime = @CodMov)) 
          Set @WFlgAtu = 1
        end

    if @WFlgAtu = 1
      begin
        Declare @WSldAnt numeric(18,4),
                @cr_SldAtu numeric(18,4),
                @cr_ValMov numeric(18,4),
                @cr_NumPrt int,
                @cr_DatMov smalldatetime,
                @WValAux numeric(18,4),
                @WFlgRep bit,
                @WSldAtu numeric(18,4)

        -- pega num. do protocolo
        if @CodMov = 'Z'    -- registro zera saldo anterior
          Set @NumPrt = 999999999
        else
        if @CodMov = 'I'    -- registro de lancamento inicial
          Set @NumPrt = 0
        else
          if @NumPrt = 0
            begin
              EXEC PR_ProxNumero 'Verba', @NumPrt output
              if @@error <> 0
                begin
                  Rollback Transaction
                  Return
                end
            end

        Set @WSldAtu = 0
        Set @WFlgRep = 0           

        -- saldo anterior
        if @CodMov = 'I'
          Set @WSldAnt = 0
        else
          Set @WSldAnt = IsNull((Select top 1 Val_SldMovime
                                   From VBSLD
                                  Where Cod_Estabe = @CodEstabe 
                                    And Cod_Vended = @CodVdr
                                    and ( (Dat_Movime = @DatMov and Num_Protoc < @NumPrt) or
                                          (Dat_Movime < @DatMov) )
                                  Order by Cod_Vended, Dat_Movime desc, Num_Protoc desc),0)


        if @CodMov = 'I'    -- registro de lancamento inicial
          begin
            -- elimina todos os reg. iniciais a partir da data do atual
            Delete From VBSLD
             Where Cod_Estabe = @CodEstabe 
               And Cod_Vended = @CodVdr
               and Cod_Movime = 'I'
               and Dat_Movime > @DatMov
            -- se houver linhas deletadas saldo deve ser recalculado
            if @@rowcount > 0
              Set @WFlgRep = 1
       
            -- se houver alteracao registro existente, saldo deve ser recalculado
            Update VBSLD
               Set Val_Movime = @ValMov
             Where Cod_Estabe = @CodEstabe 
               And Cod_Vended = @CodVdr
               and Dat_Movime = @DatMov
               and Cod_Movime = 'I'
               and Val_Movime <> @ValMov
            if @@rowcount > 0
              Set @WFlgRep = 1           
          end  -- if @CodMov = 'I'

        if @CodMov = 'Z'    -- registro sera saldo do mês
          begin
            -- se houver alteracao registro existente, saldo deve ser recalculado
            Update VBSLD
               Set Val_Movime = -@WSldAnt
             Where Cod_Estabe = @CodEstabe 
               And Cod_Vended = @CodVdr
               and Dat_Movime = @DatMov
               and Cod_Movime = 'Z'
               and ( (@ValMov <> -@WSldAnt) or
                     (Val_SldMovime <> 0) )
            if @@rowcount > 0
              Set @WFlgRep = 1           
          end  -- if @CodMov = 'Z'

        -- insere novo registro
        if not Exists(Select 1 From VBSLD
                       Where Cod_Estabe = @CodEstabe 
                         And Cod_Vended = @CodVdr
                         And Dat_Movime = @DatMov
                         And Num_Protoc = @NumPrt)
          begin
            Insert into VBSLD (Cod_Estabe, Cod_Vended, Dat_Movime, Num_Protoc, Cod_Produt, Cod_Lote, Tip_Sai, Tip_Docume, Ser_Docume, Num_Docume, 
                               Cod_Movime, Val_Movime, Val_SldMovime, Des_Movime, Flg_Automatic, Usuario, Transacao)
                        Values(@CodEstabe, @CodVdr, @DatMov, @NumPrt, @CodPrd, @CodLot, @TipMov, @EntSai, @SerDoc, @NumDoc, 
                               @CodMov, @ValMov, @WSldAnt, @DesMov, @WFlgLanAut, @DesUsu, @Now) 
            Set @WSldAtu = @WSldAnt
          end

        -- atualiza saldos
        if @WFlgRep = 0
          begin
            Set @WValAux = @WSldAnt + @ValMov - @WSldAtu
            Update VBSLD 
               Set Val_SldMovime = Val_SldMovime + @WValAux
             Where Cod_Estabe = @CodEstabe 
               And Cod_Vended = @CodVdr
               and ((Dat_Movime = @DatMov and Num_Protoc >= @NumPrt) or
                    (Dat_Movime > @DatMov))
          end
        else
          begin
            -- reprocessa saldos a partir do registro de inicio atual
            Set @WSldAnt = 0
            Declare VBSLD_Cr Cursor Local Fast_Forward For 

            Select Dat_Movime, Num_Protoc, Val_Movime, Val_SldMovime
              From VBSLD
             Where Cod_Estabe = @CodEstabe 
               And Cod_Vended = @CodVdr
               and ((Dat_Movime = @DatMov and Num_Protoc >= @NumPrt) or
                    (Dat_Movime > @DatMov))
             Order by Dat_Movime, Num_Protoc
            Open VBSLD_Cr
            Fetch Next From VBSLD_Cr Into @cr_DatMov, @cr_NumPrt, @cr_ValMov, @cr_SldAtu
            While @@FETCH_STATUS = 0
              begin
                if @cr_SldAtu <> (@cr_ValMov+@WSldAnt)
                  begin
                    Update VBSLD
                       Set Val_SldMovime = @cr_ValMov+@WSldAnt
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Vended = @CodVdr
                       And Dat_Movime = @cr_DatMov
                       And Num_Protoc = @cr_NumPrt
                    Set @cr_SldAtu = @cr_ValMov+@WSldAnt
                  end
                Set @WSldAnt = @cr_SldAtu
                Fetch Next From VBSLD_Cr Into @cr_DatMov, @cr_NumPrt, @cr_ValMov, @cr_SldAtu
              end
            Close VBSLD_Cr
            Deallocate VBSLD_Cr
          end
      end
  end
  
Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_AtualizaSaldoConsignacao]
@CodEstabe int,
@IdConsig int,
@CodProdut int,
@DatMov smalldatetime,
@EntSai varchar(1), -- 'E' ou 'S': tipo da nota
@TipMov varchar(1), -- 'D'-devolução , 'R'-remessa, 'V"-venda
@QtdMov int         -- qtd com sinal:: negativo = CANCELAMENTO

AS

SET NOCOUNT ON

Begin Transaction 

/*
                      @EntSai   @TipMov
Remessa Consignação    'S'       'R'
Devol.Simbolica        'E'       'D'
Devolucao              'E'       'D'
Venda                  'S'       'V'
*/

Declare @QtdEntDev int, 
        @QtdSaiRem int,
        @QtdSaiFat int,
        @QtdSld int

-- inicializa variaveis
if @QtdMov is null
  Set @QtdMov = 0
  
-- remessa
if (@EntSai = 'S') and (@TipMov = 'R')
  begin
    -- atualiza saldo fisico consignação
    Update PRXES
       Set Qtd_CngCli = IsNull(Qtd_CngCli,0) + @QtdMov
     Where Cod_Estabe = @CodEstabe 
       and Cod_Produt = @CodProdut

    -- atualiza itens do contrato
    Update CNGIT 
       Set Qtd_Digita = IsNull(Qtd_Digita,0) - @QtdMov
     Where Cod_Estabe = @CodEstabe 
       And Id_Consig  = @IdConsig
       and Cod_Produt = @CodProdut

    Update CNGIT 
       Set Qtd_Remess = IsNull(Qtd_Remess,0) + @QtdMov
     Where Cod_Estabe = @CodEstabe 
       And Id_Consig  = @IdConsig
       and Cod_Produt = @CodProdut
  end

-- devolução
if (@EntSai = 'E') and (@TipMov = 'D')
  begin
    -- atualiza saldo fisico consignação
    Update PRXES
       Set Qtd_CngCli = IsNull(Qtd_CngCli,0) - @QtdMov
     Where Cod_Estabe = @CodEstabe 
       and Cod_Produt = @CodProdut

    -- atualiza itens do contrato
    Update CNGIT 
       Set Qtd_Remess = IsNull(Qtd_Remess,0) - @QtdMov
     Where Cod_Estabe = @CodEstabe 
       And Id_Consig  = @IdConsig
       and Cod_Produt = @CodProdut

    Update CNGIT 
       Set Qtd_Devolu = IsNull(Qtd_Devolu,0) + @QtdMov
     Where Cod_Estabe = @CodEstabe 
       And Id_Consig  = @IdConsig
       and Cod_Produt = @CodProdut
  end

-- fatura
if (@EntSai = 'S') and (@TipMov = 'V')
  begin
    -- atualiza itens do contrato
    Update CNGIT 
       Set Qtd_Devolu = IsNull(Qtd_Devolu,0) - @QtdMov
     Where Cod_Estabe = @CodEstabe 
       And Id_Consig  = @IdConsig
       and Cod_Produt = @CodProdut

    Update CNGIT 
       Set Qtd_Fatura = IsNull(Qtd_Fatura,0) + @QtdMov
     Where Cod_Estabe = @CodEstabe 
       And Id_Consig  = @IdConsig
       and Cod_Produt = @CodProdut
  end


-- pega o ultimo movimento do produto
Select top 1 @QtdSld = IsNull(Qtd_Saldo,0)
  From CNGSD 
 Where Cod_Estabe = @CodEstabe
   and Id_Consig = @IdConsig
   and Cod_Produt = @CodProdut 
   and Dat_Movime <= @DatMov
 Order By Dat_Movime desc

-- se o ultimo movimento foi numa data diferente da passada como parametro, inclui uma nova linha
--if @DatMov <> @DatMovAnt
if not Exists(Select Cod_Produt from CNGSD Where Cod_Estabe = @CodEstabe and Id_Consig = @IdConsig and Cod_Produt = @CodProdut and Dat_Movime = @DatMov) and
   (@QtdMov <> 0)
  begin
    Insert into CNGSD (Cod_Estabe, Id_Consig, Cod_Produt, Dat_Movime, Qtd_Saldo) 
               Values (@CodEstabe, @IdConsig, @CodProdut,    @DatMov,    @QtdSld) 
    if (@@error <> 0)
      begin
        if @@trancount > 0
          Rollback Transaction
        Return
      end
  end

--Acumula as quantidades movimentadas na data..
Select @QtdEntDev = 0, 
	   @QtdSaiRem = 0,
	   @QtdSaiFat = 0,
       @QtdSld  = 0

-- valida @TipEntSai x @TipMov
-- atualiza @QTdMov para atualizar saldo em CNGSD
if (@EntSai = 'E') and (@TipMov = 'D')
  begin
    Set @QtdEntDev = @QtdMov
    Set @QtdMov = @QtdEntDev*(-1)
end
else
if (@EntSai = 'S') and (@TipMov = 'R')
  Set @QtdSaiRem = @QtdMov
else
if (@EntSai = 'S') and (@TipMov = 'V')
  begin
    Set @QtdSaiFat = @QtdMov
    -- se for venda: cancela devolução @QtdEntDev
    Set @QtdEntDev = @QtdMov*(-1)
	Set @QtdMov = 0
  end

Update CNGSD 
   Set Qtd_Remess = IsNull(Qtd_Remess,0) + @QtdSaiRem,
       Qtd_Devolu = IsNull(Qtd_Devolu,0) + @QtdEntDev,
       Qtd_Fatura = IsNull(Qtd_Fatura,0) + @QtdSaiFat
 Where Cod_Estabe = @CodEstabe
   and Id_Consig = @IdConsig
   and Cod_Produt = @CodProdut
   and Dat_Movime = @DatMov

-- regrava os saldos  em CNGSD...
Update CNGSD 
   Set Qtd_Saldo = Qtd_Saldo + @QtdMov  -- ??????
 Where Cod_Estabe = @CodEstabe 
   and Id_Consig  = @IdConsig
   and Cod_Produt = @CodProdut
   and Dat_Movime >= @DatMov
   and @QtdMov <> 0

if @@trancount > 0
  Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_FaturaConsignacao]
@PTipEntSai char(1),   -- tipo NF 'E', 'S'
@PCodEstabe int,
@PSerDoc varchar(3),
@PNumDoc int,
@PIdConsig int,
@PNumSequen smallint

AS

BEGIN TRANSACTION

  Declare @StaDoc char(1),
          @DatMov smalldatetime,
          @CodCfo int,
          @QtdPedido int,      
          @CodProdut int,
          @TipMov varchar(1)

  if @PTipEntSai = 'S'
    begin
      Select @TipMov = dbo.FN_TipoNFConsig(Cod_Cfo1), -- (R)emessa, (D)evolução, (V)enda
             @StaDoc = Status, 
             @DatMov = Dat_Emissao
        From NFSCB 
       Where Cod_Estabe = @PCodEstabe 
         and Ser_Nota = @PSerDoc
		 and Num_Nota = @PNumDoc
         and Id_Consig = @PIdConsig

      -- atualiza status de remessa para recalcular campos em trigger da CNGRI
      if @StaDoc = 'C'
        Update CNGRC 
          Set Sta_CngPed = '1'
        Where Cod_Estabe = @PCodEstabe 
          And Id_Consig = @PIdConsig
          And Num_Sequen = @PNumSequen
          And Sta_CngPed = '2'
      else      
        Update CNGRC 
          Set Sta_CngPed = '3'   -- faturado
        Where Cod_Estabe = @PCodEstabe 
          And Id_Consig = @PIdConsig
          and Num_Sequen = @PNumSequen
    end

  if @PTipEntSai = 'E'
    begin
      Select @TipMov = dbo.FN_TipoNFConsig(Cod_Cfo), -- (R)emessa, (D)evolução, (V)enda
             @StaDoc = Status,  
             @DatMov = Dat_Movimento
        From NFECB 
       Where Cod_Estabe = @PCodEstabe 
	     and Protocolo = @PNumDoc
         and Id_Consig = @PIdConsig
    end

  if @TipMov <> 'X'
    begin

      if @PTipEntSai = 'S'
        Declare ITENS_cr CURSOR Local Fast_Forward For 
          Select Cod_Produto, sum(IsNull(Qtd_Produto,0)+IsNull(Qtd_Bonificacao,0)) as Qtd_Pedido 
            From NFSIT 
           Where Cod_Estabe = @PCodEstabe 
             And Ser_Nota = @PSerDoc
             And Num_Nota = @PNumDoc
           Group By Cod_Produto
      else
        Declare ITENS_cr CURSOR Local Fast_Forward For 
          Select Cod_Produto, sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) as Qtd_Pedido 
            From NFEIT 
           Where Cod_Estabe = @PCodEstabe 
             And Protocolo = @PNumDoc
           Group By Cod_Produto
    
     OPEN ITENS_cr
      FETCH NEXT FROM ITENS_cr INTO @CodProdut, @QtdPedido
      WHILE @@FETCH_STATUS = 0
        BEGIN
          -- @QtdPedido com sinal
          if @StaDoc = 'C'
            Set @QtdPedido = @QtdPedido * (-1)
    
          Exec PR_AtualizaSaldoConsignacao @PCodEstabe, @PIdConsig, @CodProdut, 
                                           @DatMov, @PTipEntSai, @TipMov, @QtdPedido
          if @@error <> 0
            begin
              if @@trancount > 0
                Rollback Transaction
              Return
            end
    
          FETCH NEXT FROM ITENS_cr INTO @CodProdut, @QtdPedido    
        END
      CLOSE ITENS_cr 
      DEALLOCATE ITENS_cr
     
      -- recalacula CNGIT.Qtd_Digita todos os itens conforme status em CNGRC
      Exec PR_AtualizaCNGIT @PCodEstabe, @PIdConsig, 0

    end

if @@trancount > 0
  COMMIT TRANSACTION
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_DecrementaSaldoSolicitado]
@CodEstabe int,
@TipPed varchar(1),
@StaPdv1 varchar(1),
@StaPdv2 varchar(1),
@TipBlq varchar(2),
@NumPrtOri int,
@CodPrd int,
@CodLot varchar(20),
@CodPrm int,
@QtdPra int,    -- qtd est.1
@QtdDep int    -- qtd est.2

AS

SET NOCOUNT ON

Begin Transaction

Declare @Date smalldatetime,
        @FlgAtu bit,
        @CodDep smallint,
        @WDatVct smalldatetime, 
        @WDatFab smalldatetime,
        @WQtdEmbFec int
		
Set @Date = cast(GetDate() as Date)

-- sem WMS: deposito unico
Set @CodDep = IsNull((Select min(Cod_Dep) 
                        From TBDEP 
                       Where Cod_Estabe = @CodEstabe),1)

if (IsNull(@TipPed,'') = 'P') and (IsNull(@StaPdv1,'') = 'P') and 
   (IsNull(@StaPdv2,'') <> 'N') and (IsNull(@StaPdv2,'') <> 'D') and (IsNull(@TipBlq,'') <> 'SR') 
  BEGIN
    -- normaliza
    Set @QtdPra = IsNull(@QtdPra,0)
    Set @QtdDep = IsNull(@QtdDep,0)
    Set @FlgAtu = 0
    
    Update PRLOT
       Set Qtd_SolPra = Case 
                          When IsNull(Qtd_SolPra,0) > @QtdPra Then IsNull(Qtd_SolPra,0) - @QtdPra
                          Else 0
                        End
     Where Cod_Estabe = @CodEstabe 
       and Cod_Dep = @CodDep
       and Cod_Produt = @CodPrd
       and Cod_Lote = @CodLot
       and @QtdPra > 0
    if @@rowcount > 0  
      Set @FlgAtu = 1

    Update PRLOT
       Set Qtd_SolDep = Case 
                          When IsNull(Qtd_SolDep,0) > @QtdDep Then IsNull(Qtd_SolDep,0) - @QtdDep
                          Else 0
                        End
     Where Cod_Estabe = @CodEstabe 
       and Cod_Dep = @CodDep
       and Cod_Produt = @CodPrd 
       and Cod_Lote = @CodLot
       and @QtdDep > 0
    if @@rowcount > 0  
      Set @FlgAtu = 1

    Update PRXES 
       Set Qtd_Solici = Case 
                          When IsNull(Qtd_Solici,0) > (@QtdPra+@QtdDep) Then IsNull(Qtd_Solici,0) - @QtdPra - @QtdDep
                          Else 0
                        End
     Where Cod_Estabe = @CodEstabe 
       and Cod_Produt = @CodPrd
       and @FlgAtu = 1

    Update PRXES
       Set Qtd_PrmSolici = Case 
                             When IsNull(Qtd_PrmSolici,0) > (@QtdPra+@QtdDep) Then IsNull(Qtd_PrmSolici,0) - @QtdPra - @QtdDep
                             Else 0
                           End
     Where Cod_Estabe = @CodEstabe 
       and (Cod_Produt = @CodPrd) and (IsNull(@CodPrm,0) > 0)
       and @FlgAtu = 1

      -- se for o caso transfere para zona de cross docking
      if (@FlgAtu = 1) and
          Exists(Select 1 From NFECB Where Cod_Estabe = @CodEstabe And Protocolo = @NumPrtOri And IsNull(Flg_CrossDocking,0) = 1)
        begin
          Declare @IdEndDep int,
                  @NumRua smallint,
                  @NumCol smallint,
                  @NumNiv smallint,
                  @NumApt smallint,
                  @CodOri varchar(20),
                  @CodMtvTrfLot varchar(6) = '',
                  @Usuario varchar(15),
                  @WQtdTrfTot int,
                  @CodDepPck smallint,
                  @NumRuaPck smallint,
                  @NumColPck smallint,
                  @NumNivPck smallint,
                  @NumAptPck smallint

		  Select @IdEndDep = cb.Id_EndDep,
                 @CodDep = ed.Cod_Dep,
                 @NumRua = ed.Num_Rua,
                 @NumCol = ed.Num_Col,
                 @NumNiv = ed.Num_Niv,
                 @NumApt = ed.Num_Apt
            From NFECB cb 
                 inner Join ENDDP ed on cb.Cod_Estabe = ed.Cod_Estabe and cb.Id_EndDep = ed.Id_EndDep
           Where cb.Cod_Estabe = @CodEstabe 
             And cb.Protocolo = @NumPrtOri 
             And IsNull(cb.Flg_CrossDocking,0) = 1
             And IsNull(ed.Num_Cntrol,0) = cb.Protocolo

           if (@IdEndDep > 0) and 
              ((@QtdPra + @QtdDep) > 0)
             begin
               -- dá saída em PRLOT
                Update PRLOT
                   Set Qtd_FisPra = Qtd_FisPra - @QtdPra,
                       Qtd_FisDep = Qtd_FisDep - @QtdDep
                 Where Cod_Estabe = @CodEstabe 
                   and Cod_Dep = @CodDep
                   and Cod_Produt = @CodPrd
                   and Cod_Lote = @CodLot
                   and Qtd_FisPra >= @QtdPra
                   and Qtd_FisDep >= @QtdDep
                if @@rowcount > 0
                  begin
                    Set @CodOri = 'CAN_PDV'
                    Set @Usuario = dbo.FN_UsuarioInfarma()

                    -- registra saida do picking
                    Select top 1 
                           @CodDepPck = dp.Cod_Dep
                         , @NumRuaPck = dp.Num_Rua
                         , @NumColPck = dp.Num_Col
                         , @NumNivPck = dp.Num_Niv
                         , @NumAptPck = dp.Num_Apt
                     From DPXPR dp
                          Inner Join PRXES pr on pr.Cod_Estabe = dp.Cod_Estabe and pr.Cod_Produt = dp.Cod_Produt 
                    Where pr.Cod_Estabe = @CodEstabe
                      And pr.Cod_Produt = @CodPrd
                    Order by dp.Cod_Dep

                    Set @WQtdTrfTot = (@QtdPra + @QtdDep) * (-1) 
                    Exec PR_InserePRLOG @CodEstabe, @CodPrd, @CodLot, @CodDepPck, 
                                        @NumRuaPck, @NumColPck, @NumNivPck, @NumAptPck, 
                                        @WQtdTrfTot, @CodOri, @CodMtvTrfLot, '', '', '', @Usuario

                    -- Transfere para cross docking
                    if Not Exists(Select 1 From PRLTL 
                                   Where Cod_Estabe = @CodEstabe 
                                     And Cod_Produt = @CodPrd 
                                     And Cod_Lote = @CodLot 
                                     And Cod_Dep = @CodDep
                                     And Num_Rua = @NumRua
                                     And Num_Col = @NumCol
                                     And Num_Niv = @NumNiv
                                     And Num_Apt = @NumApt)
                      begin
                        Select top 1 @WDatFab = lt.Dat_Fabric, 
						             @WDatVct = lt.Dat_Vencim, 
									 @WQtdEmbFec = pr.Qtd_Embalagem
                          From PRLOT lt 
                               inner join PRODU pr on lt.Cod_Produt = pr.Codigo
                         Where lt.Cod_Estabe = @CodEstabe
                           And lt.Cod_Produt = @CodPrd 
                           And lt.Cod_Lote = @CodLot

                        Insert Into PRLTL (Cod_Estabe, Cod_Produt, Cod_Lote, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt,
		                                   Qtd_EmbFec, Dat_Vencim, Dat_Fabric, Dat_Entrada, Qtd_FisPra, Qtd_FisDep)
                                   Values (@CodEstabe, @CodPrd,@CodLot, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt,
                                           @WQtdEmbFec, @WDatVct, @WDatFab, @Date,0,0)
                      end

                    Update PRLTL
                       Set Qtd_FisPra = Qtd_FisPra + @QtdPra,
                           Qtd_FisDep = Qtd_FisDep + @QtdDep
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Produt = @CodPrd 
                       And Cod_Lote = @CodLot
                       And Cod_Dep = @CodDep
                       And Num_Rua = @NumRua 
                       And Num_Col = @NumCol
                       And Num_Niv = @NumNiv
                       And Num_Apt = @NumApt

                    -- registra entrada no cross doclking
                    Set @WQtdTrfTot = @QtdPra + @QtdDep
                    Exec PR_InserePRLOG @CodEstabe, @CodPrd, @CodLot, @CodDep, 
                                        @NumRua, @NumCol, @NumNiv, @NumApt, 
                                        @WQtdTrfTot, @CodOri, @CodMtvTrfLot, '', '', '', @Usuario
                  end  -- if @@rowcount > 0
             end  -- if @IdEndDep > 0
        end  -- if (@FlgAtu = 1) and
  END
Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraNFS]
@CodEstabe int,                -- estabelecimento
@CodPed int,                   -- num. do pedido
@CodCfo int,                   -- codigo fiscal de operacao
@NumSel bigint,                -- num. do selo fiscal inicial
@NumFor int,                   -- num. do formulario inicial
@TipNfs varchar(1),            -- tipo de nota: 'V', 'D', 'O'
@DesUsu varchar(15),           -- usuario
@SerNfsRet varchar(3) output,  -- serie NF gerada
@NumNfsRet int output          -- num. NF gerada

AS

SET ANSI_WARNINGS OFF
SET NOCOUNT ON 

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime,
        @MsgErr varchar(200),
        @WFlgWMS bit

Set @Now = GetDate()
Set @Date = cast(GetDate() as Date)

If (@DesUsu = '' or @DesUsu = 'SISTEMA')
  Set @DesUsu = dbo.FN_UsuarioInfarma()

Set @SerNfsRet = ''
Set @NumNfsRet = 0
Set @MsgErr = ''

if Charindex((Select Status2 From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed),';N;D;') > 0 
  Set @MsgErr = 'Pedido já faturado'
else
if ((Select IsNull(FlgNfe,0) From PARAM Where Cod_Estabe = @CodEstabe) = 1) and (not Exists(Select top 1 Num_Nfe From NMNFE Where Cod_Estabe = @CodEstabe And Flg_Padrao = 1))
  Set @MsgErr = 'Não existe série padrão cadastrada para nota fiscal eletrônica'
else
if (Select Ltrim(Rtrim(IsNull(Cod_TipLucro,''))) From ESTAB Where Cod_Estabe = @CodEstabe) = ''
  Set @MsgErr = 'Tipo de Lucro do Estabelecimento não cadastrado'
else
if ((Select Flg_Wms From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed) = 1) and
   Exists(Select it.QtdIte, lt.QtdLot
          From (Select Cod_Produto, QtdIte = SUM(IsNull(Qtd_Pedido,0)+Isnull(Qtd_Bonificacao,0))
                  From PDVIT 
                 Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
                   And (IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) > 0
                 Group by Cod_Produto) it Full Outer Join
               (Select Cod_Produt, QtdLot = SUM(IsNull(Qtd_Lote,0))
                  From PDVLT
                 Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
                   And IsNull(Qtd_Lote,0) > 0
                 Group by Cod_Produt) lt on it.Cod_Produto = lt.Cod_Produt
          Where (IsNull(it.QtdIte,0) <> IsNull(lt.QtdLot,0)))
  Set @MsgErr = 'Existem inconsistências nos Lotes do Pedido. Cancele-o'
else
-- verifica se existe NF faturada para este pedido nos ultimos 6 meses
if Exists(Select 1 From NFSCB
           Where Cod_Estabe = @CodEstabe
             And Cod_Pedido = @CodPed
             And DATEDIFF (month,Dat_Emissao,@Date ) < 6)
  Set @MsgErr = (Select top 1 'Já existe uma NF('+cast(Num_Nota as varchar)+') '+
                              'emitida para este pedido('+cast(@CodPed as varchar)+')'
                   From NFSCB
                  Where Cod_Estabe = @CodEstabe
                    And Cod_Pedido = @CodPed
                    And DATEDIFF (month,Dat_Emissao,@Date ) < 6)


if @MsgErr <> ''
  RAISERROR(@MsgErr,16,1)
else
begin
  Begin Transaction

  Set @SerNfsRet = ''
  Set @NumNfsRet = 0

  Set @WFlgWMS = IsNull((Select Flg_Wms From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed),0)

  Update PDVCB
     Set Qtd_Itens = Qtd_Itens + 0 
   Where Cod_Estabe = @CodEstabe And Numero = @CodPed
  if (@@error <> 0)
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  Update NMFIS
     Set Nota_Fiscal_M1 = Nota_Fiscal_M1 + 0
   Where Cod_Estabe = @CodEstabe
  if (@@error <> 0)
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  Update NMNFE     
     Set Num_Nfe = Num_Nfe + 0
   Where Cod_Estabe = @CodEstabe 
     And Flg_Padrao = 1
  if (@@error <> 0)
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  Declare @WCodOri varchar(20)

  -- variaveis a gravar em NFSCB
  Declare @PEspNfs varchar(3),
          @PQtdPagNfs int,
          @PSerSel varchar(2),
          @PNumSel bigint,
          @PNumFor int,
          @PCodCfo smallint,
          @PDatEmi smalldatetime,
          @PTipVct varchar(1),
          @PTipRetImp varchar(1),
          @PPerDscFin numeric(18,4),   -- novo desc. financeiro sobre valor toal da nf
          @PPerDscFinLiq numeric(18,4),  -- % aplicado sobre Valor da mercadoria
          @PCgc varchar(14),
          @PCgf varchar(15),
          @PDesEnd  varchar(50),
          @PDesBai varchar(20),
          @PCep varchar(8),
          @PEst varchar(2),
          @PDesCid varchar(25),
          @PCodCid int,
          @PCodCidIbge varchar(7),
          @PCodMacReg int,
          @PCodMicReg int,
          @PQtdPar int,
          @PQtdPrzMed numeric(18,4),
          @PFlgComNor bit,
          @PPerComVnd numeric(18,4),
          @PPerComOpe numeric(18,4),
          @PPerComSup numeric(18,4),
          @PPerComGer numeric(18,4),
          @PPerComSupOpe numeric(18,4),
          @PPerComGerOpe numeric(18,4),
          @PModNotFis varchar(2),
          @PCodStaNfe varchar(1),
          @PUfPlaVei varchar(2),
          @PCodPlaVei varchar(10),
		  @PNumInscriSbtEmiUfd varchar(15),

          @PVlrDebVrbVdr numeric(18,4),
          @PVlrComTra numeric(18,4),
          @PVlrDscCom numeric(18,4),
          @PVlrOutDsp numeric(18,4),
          @WVlrOutDsp numeric(18,4),
          @PVlrTotNot numeric(18,4),

          @PVlrSubTri numeric(18,4),
          @PVlrDscTri numeric(18,4),
          @PVlrRecSbt numeric(18,4),
          @PVlrFcpSbt numeric(18,4),
          @PVlrFcpSbtRec numeric(18,4)

  -- coloca campos de PDVCB na memoria
  Declare @cb_TipFat varchar(3),
          @cb_TipSaiPdv varchar(1),
          @cb_TipGerVrb varchar(1),
          @cb_TipRatBon varchar(1),
          @cb_FlgBlqDebVrbNotBon bit,
          @cb_StaPdv1 varchar(1),
          @cb_StaPdv2 varchar(1),
          @cb_TipBlq varchar(2),
          @cb_QtdIte int,
          @cb_TipVct varchar(1),
          @cb_CodCli int,
          @cb_TipCon varchar(1),
          @cb_CodFun int,
          @cb_NomCon varchar(45),
          @cb_CodOriPdv varchar(2),
          @WCodOriPdv varchar(1),
          @cb_CodDig int,
          @cb_CodOpe int,
          @cb_CodVdr int,
          @cb_CodSup int,
          @cb_CodGer int,
          @cb_CodSupOpe int,
          @cb_CodGerOpe int,
          @cb_CodAgc int,
          @cb_CodTra int,
          @cb_CodRot int,
          @cb_CodRegTri int,
          @cb_VlrLiqIte numeric(18,4),
          @cb_VlrBasDscCom numeric(18,4),
          @cb_VlrBasPar numeric(18,4),
          @cb_VlrRepIcm numeric(18,4),
          @cb_VlrSubTri numeric(18,4),
          @cb_VlrSubTriFcp numeric(18,4),
          @cb_VlrSbtRes numeric(18,4),
          @cb_VlrDscTri numeric(18,4),
          @cb_VlrDscBon numeric(18,4),
          @cb_VlrDspExt numeric(18,4),
          @cb_VlrDespes numeric(18,4),
          @cb_VlrIpi numeric(18,4),
          @cb_QtdPes numeric(18,4),
          @cb_QtdVol int,
          @cb_IdPolCom int,
          @cb_PerSubFat  numeric(7,4),
          @cb_PerDscCom numeric(7,4),
          @cb_FlgVlrFin bit,
          @cb_ObsNfs varchar(1600),
          @cb_DatPed smalldatetime,
          @cb_CodPedCliPde varchar(20),
          @cb_CodPedCmpCli varchar(20),
          @cb_NotEmpCli varchar(20),
          @cb_NumConCli varchar(40),
          @cb_DesLayPde varchar(25),
          @cb_CodPrjPde varchar(12),
          @cb_DesConven varchar(30),
          @cb_CodCtr int,
          @cb_NumSeqCtr int,
          @cb_IdConsig int,
          @WCodTipSaiCng varchar(3),
          @cb_TipFrete varchar(1),
          @cb_VlrFrete numeric(18,4),
          @cb_VlrFrePrv numeric(18,4),
          @cb_PerComSup numeric(7,4),
          @cb_PerComGer numeric(7,4),
          @cb_PerComSupOpe numeric(7,4),
          @cb_PerComGerOpe numeric(7,4),
          @cb_FlgGerRetBon bit,
          @cb_UfPlaVei varchar(2),
          @cb_CodPlaVei varchar(10),
          @cb_VlrSdoVrb numeric(18,4),
          @cb_InscricaoSuframa varchar(9),
		  @cb_VlrBasIrf numeric(18,4),
		  @cb_VlrIrf numeric(18,4),		
		  @cb_VlrSemIrf numeric(18,4), 
          @pc_Controle_Saldo varchar(1),
          @pc_FlgAcuVrbPos bit,
          @pc_FlgAcuVrbNeg bit,
          @pc_FlgMarkupCusCom bit,
		  @pc_FlgCtrPdvVrbVdr bit,
		  @pc_FlgCtrPdvVrbOpe bit

  -- normaliza supervisor/gerencia
    Update cb 
       Set cb.Cod_Supervisor = ve.Cod_Supervisor 
     From PDVCB cb 
	      Inner Join VENDE ve on cb.Cod_Vendedor = ve.Codigo
    Where cb.Cod_Estabe = @CodEstabe 
	  And cb.Numero = @CodPed
      And IsNull(cb.Cod_Supervisor,0) <> IsNull(ve.Cod_Supervisor,0)
      
    Update cb 
       Set cb.Cod_Gerencia = su.Cod_Gerencia
      From PDVCB cb 
	       Inner Join VENDE ve on cb.Cod_Vendedor = ve.Codigo
           Inner Join SUPER su on ve.Cod_Supervisor = su.Codigo
     Where cb.Cod_Estabe = @CodEstabe 
	   And cb.Numero = @CodPed
       And IsNull(cb.Cod_Gerencia,0) <> IsNull(su.Cod_Gerencia,0)

    Update cb 
       Set cb.Cod_SupOpe = ve.Cod_Supervisor 
      From PDVCB cb 
	       Inner Join VENDE ve on cb.Cod_VendTlmkt = ve.Codigo
     Where cb.Cod_Estabe = @CodEstabe 
	   And cb.Numero = @CodPed
       And IsNull(cb.Cod_SupOpe,0) <> IsNull(ve.Cod_Supervisor,0)
      
    Update cb 
       Set cb.Cod_GerOpe = su.Cod_Gerencia
      From PDVCB cb 
	       Inner Join VENDE ve on cb.Cod_VendTlmkt = ve.Codigo
           Inner Join SUPER su on ve.Cod_Supervisor = su.Codigo
     Where cb.Cod_Estabe = @CodEstabe 
	   And cb.Numero = @CodPed
       And IsNull(cb.Cod_GerOpe,0) <> IsNull(su.Cod_Gerencia,0)

  Select @cb_TipFat = cb.Tip_Faturamento,
         @cb_TipSaiPdv = IsNull(cb.Tip_SaiPdv,''),
         @cb_TipGerVrb = IsNull(cb.Tip_GerVrb,''),
         @cb_TipRatBon = IsNull(cb.Tip_RatBon,''),
         @cb_FlgBlqDebVrbNotBon = IsNull(cb.Flg_BlqDebVrbNotBon,0),
         @cb_StaPdv1 = cb.Status1,
         @cb_StaPdv2 = cb.Status2,
         @cb_TipBlq = cb.Bloqueio,
         @cb_TipVct = cb.Tip_Vencimento,
         @cb_CodCli = cb.Cod_Cliente,
         @cb_TipCon = cb.Tip_Consumidor,
         @cb_CodFun = cb.Cod_Funcionario,
         @cb_NomCon = cb.Consumidor,
         @cb_CodOriPdv = cb.Cod_OrigemPdv,
         @WCodOriPdv = Substring(cb.Cod_OrigemPdv,1,1),
         @cb_CodDig = cb.Cod_Digitador,
         @cb_CodOpe = cb.Cod_VendTlmkt,
         @cb_CodVdr = cb.Cod_Vendedor,
         @cb_CodSup = cb.Cod_Supervisor,
         @cb_CodGer = cb.Cod_Gerencia,
         @cb_CodSupOpe = cb.Cod_SupOpe,
         @cb_CodGerOpe = cb.Cod_GerOpe,
         @cb_CodAgc = cb.Cod_Agente,
         @cb_CodTra = cb.Cod_Transportadora,
         @cb_CodRot = IsNull(cb.Cod_Rota,0),
         @cb_CodRegTri = cb.Cod_RegTri,
         @cb_VlrLiqIte = cb.Vlr_LiqItens,
         @cb_VlrBasDscCom = cb.Vlr_BasDscCom,
         @cb_VlrBasPar = cb.Vlr_BasPar,
         @cb_VlrRepIcm = ISNULL(cb.Vlr_RepIcms,0),
         @cb_VlrSubTri = ISNULL(cb.Vlr_SubsTrib,0),
         @cb_VlrSbtRes = ISNULL(cb.Vlr_SbtRes,0),
         @cb_VlrDscTri = ISNULL(cb.Vlr_DscTri,0),
         @cb_VlrDscBon = ISNULL(cb.Vlr_DscBon,0),
         @cb_VlrDspExt = ISNULL(cb.Vlr_DspExt,0),
         @cb_VlrDespes = ISNULL(cb.Vlr_Despes,0),
         @cb_VlrIpi = ISNULL(cb.Vlr_Ipi,0),
         @cb_QtdPes = cb.Qtd_Peso,
         @cb_QtdVol = cb.Qtd_Volumes,
         @cb_IdPolCom = cb.Id_PolCom, 
         @cb_QtdIte = cb.Qtd_Itens,
         @cb_PerSubFat = cb.Per_SubFat,
         @cb_PerDscCom = IsNull(cb.Per_DescontoCom,0),
         @cb_FlgVlrFin = cb.Flg_VlrFinanc,
         @cb_ObsNfs = Substring(cb.Obs_NotFis,1,1600),
         @cb_DatPed = cb.Dat_Pedido,
         @cb_CodPedCliPde = cb.Cod_PedCli,
         @cb_CodPedCmpCli = cb.Cod_PedCmpCli,
         @cb_NotEmpCli = cb.Ide_NotEmp,
         @cb_NumConCli = cb.Ide_Contra,
         @cb_DesLayPde = cb.Des_LayoutPde,
         @cb_CodPrjPde = cb.Cod_PrjPde,
         @cb_DesConven = cb.Des_Convenio,
         @cb_CodCtr = cb.Cod_Contrato,
         @cb_IdConsig = IsNull(cb.Id_Consig,0),
         @cb_NumSeqCtr = cb.Num_SequenciaCtr,
         @cb_TipFrete = IsNull(cb.Tip_Frete,'1'),   -- '1'-CIF
         @cb_VlrFrete = Round(IsNull(cb.Vlr_Frete,0),2),
         @cb_VlrFrePrv = Round(IsNull(cb.Vlr_FrePrv,0),2),
         @cb_FlgGerRetBon = IsNull(cb.Flg_GerRetBon,0),
         @cb_PerComSup = IsNull(cb.Per_ComSup,0),
         @cb_PerComGer = IsNull(cb.Per_ComGer,0),
         @cb_PerComSupOpe = IsNull(cb.Per_ComSupOpe,0),
         @cb_PerComGerOpe = IsNull(cb.Per_ComGerOpe,0),
         @cb_UfPlaVei = Ltrim(Rtrim(cb.Uf_PlaVei)),
         @cb_CodPlaVei =  Ltrim(Rtrim(cb.Cod_PlaVei)),
         @cb_VlrSdoVrb = IsNull(cb.Vlr_Verba,0),
         @cb_InscricaoSuframa = IsNull(cb.Inscricao_Suframa,''),
		 @cb_VlrBasIrf = IsNull(cb.Vlr_BasIrf,0),
		 @cb_VlrIrf = IsNull(cb.Vlr_Irf,0),

         @PQtdPar = cb.Qtd_Parcela,
         @PQtdPrzMed = cb.Qtd_PrzMed,
         @PPerDscFinLiq = IsNull(cb.Per_DescontoFin,0),
         @PFlgComNor = cb.Flg_ComisNormal,
         @PPerComOpe = Round(IsNull(cb.Per_ComOpe,0),2),
         @PPerComVnd = Round(IsNull(cb.Per_ComVnd,0),2),
         @pc_Controle_Saldo = pc.Controle_Saldo, 
         @pc_FlgAcuVrbPos = pc.Flg_AcuVrbPos,
         @pc_FlgAcuVrbNeg = pc.Flg_AcuVrbNeg,
         @pc_FlgMarkupCusCom = pc.Flg_MarkupCusCom,
         @pc_FlgCtrPdvVrbVdr = pc.Flg_CtrPdvVrbVdr,
         @pc_FlgCtrPdvVrbOpe = pc.Flg_CtrPdvVrbOpe

    From PDVCB cb
         left join VENDE ve on ve.Codigo = cb.Cod_Vendedor
         left join POCOM pc on pc.Id_PolCom = cb.Id_PolCom
         left join PCXVE xv on xv.Id_PolCom = cb.Id_PolCom and xv.Cod_Vended = cb.Cod_Vendedor
         left join PCXOP xo on xo.Id_PolCom = cb.Id_PolCom and xo.Cod_Vended = cb.Cod_VendTlmkt
         left join PCXSU xs on xs.Id_PolCom = cb.Id_PolCom and xs.Cod_Super  = ve.Cod_Supervisor
   Where cb.Cod_Estabe = @CodEstabe 
     And cb.Numero = @CodPed

  Select @cb_VlrSubTriFcp = ROUND(SUM(ISNULL(Vlr_FcpSbt,0)),2)          
    From PDVIT
   Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed

  -- coloca campos de ESTAB na memoria
  Declare @em_Cep varchar(8),
          @em_CodEst varchar(2),
          @em_CodTipLuc varchar(2),
		  @em_FlgContriSubstituido bit

  Select @em_Cep = Num_Cep,
         @em_CodEst = Des_Estado,
         @em_CodTipLuc = IsNull(Cod_TipLucro,''),
		 @em_FlgContriSubstituido = IsNull(Flg_ContriSubstituido,0)
    From ESTAB
    Where Cod_Estabe = @CodEstabe

  -- coloca campos de PARAM na memoria
  Declare @pm_NumItePagNfs int,
          @pm_FlgCtrSelFis bit,
          @pm_ModeloNotaFiscal varchar(3),
          @pm_SerieSeloFiscal varchar(2),
          @pm_CodCidEmpLoc int,
          @pm_CodMacRegEmpLoc int,
          @pm_CodMicRegEmpLoc int,
          @pm_FlgComPrdPrpDsc bit,
          @pm_FlgDespachMercad bit,
          @pm_FlgNfe bit,
          @pm_FlgIncIpiCalPis bit,
          @pm_FlgExcIcmCalPis bit,
          @pm_FlgDebBlqBanVrbVdr bit,
          @pm_PerCusFinDiaExcPrzMedCfg numeric(18,4),
          @pm_QtdPrzMedCfg int

  Select @pm_NumItePagNfs = IsNull(NumItePagNfs,0),
         @pm_FlgCtrSelFis = IsNull(FlgCtrSelFis,0),
         @pm_ModeloNotaFiscal = ModeloNotaFiscal,
         @pm_SerieSeloFiscal = SerieSeloFiscal,
         @pm_CodCidEmpLoc = CodCidadeEmpLoc,
         @pm_CodMacRegEmpLoc = CodMacRegEmpLoc,
         @pm_CodMicRegEmpLoc = CodMicRegEmpLoc,
         @pm_FlgComPrdPrpDsc = IsNull(FlgComPrdPrpDsc,0),
         @pm_FlgDespachMercad = IsNull(FlgDespachMercad,0),
         @pm_FlgNfe = IsNull(FlgNfe,0),
         @pm_FlgIncIpiCalPis = IsNull(FlgIncIpiCalPis,0),
         @pm_FlgExcIcmCalPis = IsNull(FlgExcIcmCalPis,0),
		 @pm_FlgDebBlqBanVrbVdr = IsNull(FlgDebBlqBanVrbVdr,0),
		 @pm_PerCusFinDiaExcPrzMedCfg = IsNull(PerCusFinDiaExcPrzMedCfg,0),
		 @pm_QtdPrzMedCfg = IsNull(QtdPrzMedCfg,0)
    From PARAM
   Where Cod_Estabe = @CodEstabe 

  -- coloca campos de CLIEN na memoria
  if Exists(Select Codigo From CLIEN Where Codigo = @cb_CodCli)
    begin
      Update CLIEN
         Set Total_Debito = IsNull(Total_Debito,0) + 0
       Where Codigo = @cb_CodCli
    end

  Declare @cl_CodEst varchar(2),
          @cl_TipCon varchar(1),
          @cl_CodCid int,
          @cl_CodBai int,
          @cl_CgcCpf varchar(14),
          @cl_Cgf varchar(15),
          @cl_DesEnd varchar(65),
          @cl_Cep varchar(8),
          @cl_FlgBlqCobTxaBan bit,
          @cl_CodRamAtv int,
          @uf_FlgRegSubTri bit,
          @Uf_BlqInsEstSbtNfs bit,
          @uf_NumInscriSbt varchar(15),
          @PTotDebCli numeric(18,4),
          @PVlrUltFatCli numeric(18,4),
          @PVlrMaiFatCli numeric(18,4)
            
  Select @cl_CodEst = cl.Cod_Estado,
         @cl_TipCon = cl.Tipo_Consumidor,
         @cl_CodCid = cl.Cod_Cidade,
         @cl_CodBai = cl.Cod_Bairro,
         @cl_CgcCpf = cl.Cgc_Cpf,
         @cl_Cgf = cl.Cgf,
         @cl_DesEnd = case
                        when IsNull(cl.Endereco,'') <> '' and IsNull(cl.Numero,'') <> '' and IsNull(cl.Complemento,'') <> '' then
                             ltrim(rtrim(cl.Endereco))+', '+ltrim(rtrim(cl.Numero))+', '+ltrim(rtrim(cl.Complemento))
                        else ltrim(rtrim(cl.Endereco))+', '+ltrim(rtrim(cl.Numero))
                      end,
         @cl_Cep = cl.Cep, 
         @cl_FlgBlqCobTxaBan = cl.Flg_BlqCobTxaBan,
		 @cl_CodRamAtv = cl.Cod_RamoAtividade,
         @PTotDebCli = IsNull(cl.Total_Debito,0),
         @PVlrUltFatCli = IsNull(cl.Valor_UltimaFatura,0),
         @PVlrMaiFatCli = IsNull(cl.Valor_MaiorFatura,0)
    From CLIEN cl 
    Where cl.Codigo = @cb_CodCli

  -- coloca campos de UFXES na memoria
  Select @uf_FlgRegSubTri = IsNull(Flg_RegSubTri,0),
         @Uf_BlqInsEstSbtNfs = IsNull(Flg_BlqNumInscriSubTriNfs,0),
         @uf_NumInscriSbt = case 
                              when (IsNull(Num_InscriSubTri,'') <> '.') and (IsNull(Num_InscriSubTri,'') <> '')  then IsNull(Num_InscriSubTri,'')
                              else ''
                            end
    From UFXES
   Where Cod_Estabe = @CodEstabe
     And Cod_UF = @cl_CodEst

  if @uf_FlgRegSubTri is null Set @uf_FlgRegSubTri = 0
  if @Uf_BlqInsEstSbtNfs is null Set @Uf_BlqInsEstSbtNfs = 0
  if @uf_NumInscriSbt is null Set @uf_NumInscriSbt = ''

  -- coloca campos de CIDAD na memoria
  Declare @ci_DesCid varchar(25),
          @ci_CodCidIbge varchar(7)

  Select @ci_DesCid = Descricao,
         @ci_CodCidIbge = Cod_CidIbge
    From CIDAD
   Where Cod_Estado = @cl_CodEst
     And Codigo = @cl_CodCid

  -- coloca campos de BAIRR na memoria
  Declare @ba_DesBai varchar(20),
          @ba_CodMacReg int,
          @ba_CodMicReg int 
    
  Select @ba_DesBai = Descricao,
         @ba_CodMacReg = Cod_MacroReg,
         @ba_CodMicReg = Cod_MicroReg
    From BAIRR
   Where Cod_Estado = @cl_CodEst
     And Cod_Cidade = @cl_CodCid
     And Codigo = @cl_CodBai

  -- coloca campos de TRANS na memoria
  Declare @tr_Pessoa varchar(1),
          @tr_PerFrete numeric(18,4),
          @tr_VlrMin numeric(18,4),
          @tr_FlgCalFreVerMer bit,
          @tr_UfPlaVei varchar(2),
          @tr_CodPlaVei varchar(10)

  Select @tr_Pessoa = tr.Pessoa,
         @tr_PerFrete = Case 
                          When tx.Cod_Transp is null then IsNull(tr.Per_Frete,0) 
                          Else IsNull(tx.Per_Frete,0) 
                        End,
         @tr_VlrMin = Case 
                          When tx.Cod_Transp is null then IsNull(tr.Vlr_Minimo,0) 
                          Else IsNull(tx.Vlr_Minimo,0) 
                        End,
         @tr_FlgCalFreVerMer = Case 
                                 When tx.Cod_Transp is null then IsNull(tr.Flg_CalFreVlrMer,0) 
                                 Else IsNull(tx.Flg_CalFreVlrMer,0) 
                               End,
         @tr_UfPlaVei = IsNull(Uf_PlaVei,''),
         @tr_CodPlaVei = IsNull(Cod_PlaVei,'')
    From TRANS tr
         Left Join TRXUF tx on tr.Codigo = tx.Cod_Transp and tx.Cod_UF COLLATE DATABASE_DEFAULT = @cl_CodEst COLLATE DATABASE_DEFAULT 
   Where tr.Codigo = @cb_CodTra


  -- colocar campos de AGCOB na memoria 
  -- despesa de boleto somente para banco cobrado na NF
  Declare @ag_VlrDspBolBan numeric(18,4),
          @ag_PerTaxAdm numeric(18,4),
          @ag_CodAplTaxAdm varchar(1)

  Select @ag_VlrDspBolBan = case 
                              When (Isnull(Flg_CobDspBolBanNtf,0) = 1) and (Tipo = 'BC') and
                                   (IsNull(@cl_FlgBlqCobTxaBan,0) = 0) then Round(Isnull(Vlr_DspBolBan,0),2)
                              else 0
                            end,
         @ag_PerTaxAdm = IsNull(Per_TaxAdm,0),
         @ag_CodAplTaxAdm = IsNull(Cod_AplTaxAdm,'')
    From AGCOB
   Where Codigo = @cb_CodAgc
    
  -- coloca campos de RGTRI na memoria
  Declare @rt_FlgConsumFin bit,
          @rt_CtrImpIcmTotNfs bit,
          @rt_FlgDscIcmOrgPub bit,
          @rt_FlgDscIcmOrgPubAcr bit,
          @rt_FlgUsaCfoSbtSaiIntGenSim bit

  Select @rt_FlgConsumFin = IsNull(Flg_ConsumFin,0),
         @rt_CtrImpIcmTotNfs = Isnull(Ctrl_ImpIcmTotNfs,0),
         @rt_FlgDscIcmOrgPub = IsNull(Flg_DscIcmOrgPub,0),
         @rt_FlgDscIcmOrgPubAcr = IsNull(Flg_DscIcmOrgPubAcr,0),
         @rt_FlgUsaCfoSbtSaiIntGenSim = IsNull(Flg_UsaCfoSbtSaiIntGenSim,0)
    From RGTRI
   Where Cod_RegTri = @cb_CodRegTri

  -- coloca campos TPOPE na memoria
  Declare @to_CodCfoConFinInt smallint,
          @to_CodCfoConFinExt smallint,
	      @to_CodCfoNorInt smallint,
          @to_CodCfoNorExt smallint,
          @to_CodCfoSbtInt smallint,
          @to_CodCfoSbtExt smallint,
          @to_CodCfoSubstituidoInt smallint,
          @to_CodCfoSubstituidoExt smallint,
          @to_FlgLanFin bit,
          @to_FlgBlqImpVol bit,
          @to_FlgCalPisCof bit,
          @to_IsnCtaFinDeb int,
          @to_IsnCtaFinDebInterv int,
          @to_IsnCtaFinCre int,
          @cf_FlgBlqTrfEstFis bit,
          @WCodCfoNor smallint,
          @WCodCfoSbt smallint,
          @WCodCfoBon smallint,
          @WFlgOpeInt bit,
          @WFlgRecalcula bit,
          @WVlrAux numeric(18,4)

  Select @to_CodCfoConFinInt = IsNull(Cod_CfoConFinInt,0),
	     @to_CodCfoConFinExt = IsNull(Cod_CfoConFinExt,0),
	     @to_CodCfoNorInt = Isnull(Cod_CfoNorInt,0),       
         @to_CodCfoNorExt = Isnull(Cod_CfoNorExt,0),
         @to_CodCfoSbtInt = Case 
		                      When @em_FlgContriSubstituido = 1 and IsNull(Cod_CfoSbtIntSubstituido,0) > 0 then Cod_CfoSbtIntSubstituido
							  Else Isnull(Cod_CfoSbtInt,0)
							End, 
         @to_CodCfoSbtExt = Case 
		                      When @em_FlgContriSubstituido = 1 and IsNull(Cod_CfoSbtExtSubstituido,0) > 0 then Cod_CfoSbtExtSubstituido
							  Else Isnull(Cod_CfoSbtExt,0)
							End, 
         @to_CodCfoSubstituidoInt = IsNull(Cod_CfoSbtIntSubstituido,0),
         @to_CodCfoSubstituidoExt = IsNull(Cod_CfoSbtExtSubstituido,0),
         @to_FlgLanFin = Isnull(Flg_LanFin,0),
         @to_FlgBlqImpVol = IsNull(Flg_BlqImpVol,0), 
         @to_FlgCalPisCof = IsNull(Flg_CalPisCof,0),
         @to_IsnCtaFinDeb = ISNULL(Isn_CtaFinDeb,0),
         @to_IsnCtaFinCre = ISNULL(Isn_CtaFinCre,0)
    From TPOPE
   Where Cod_Ope = @cb_TipFat 

  -- plano de contas   
  if (Select IsNull(FlgUsaInterv,0) From PMFIN) = 0
    begin
      Set @to_IsnCtaFinDeb = IsNull((Select Isn_CtaFin From CLIEN Where Codigo = @cb_CodCli),0)
      Set @to_IsnCtaFinCre = 0
    end
  else
    begin
      Set @to_IsnCtaFinDebInterv = 0
      if not Exists(Select 1 From PCFIN Where Isn_CtaFin = @to_IsnCtaFinDeb)
        Set @to_IsnCtaFinDeb = 0
      if not Exists(Select 1 From PCFIN Where Isn_CtaFin = @to_IsnCtaFinCre)
        Set @to_IsnCtaFinCre = 0
    
      if (@to_IsnCtaFinDeb = 0) or (@to_IsnCtaFinCre = 0)
        begin
          Set @to_IsnCtaFinDeb = 0
          Set @to_IsnCtaFinCre = 0
        end
      else
        if @to_IsnCtaFinDeb = (Select IsnCtaFinRecCli From PMFIN) 
          begin
            Set @to_IsnCtaFinDebInterv = IsNull((Select Isn_CtaFin From CLIEN Where Codigo = @cb_CodCli),0)
            if @to_IsnCtaFinDebInterv > 0
              Set @to_IsnCtaFinDeb = @to_IsnCtaFinDebInterv
          end
      if @to_IsnCtaFinDeb = @to_IsnCtaFinCre
        begin
         Set @to_IsnCtaFinDeb = 0
         Set @to_IsnCtaFinCre = 0
        end    
    end
     
  -- operacao interna ou externa
  if @cl_CodEst = @em_CodEst
    Set @WFlgOpeInt = 1
  else
    Set @WFlgOpeInt = 0

  if @rt_FlgConsumFin = 1
    if @WFlgOpeInt = 1
	  begin
        Set @WCodCfoNor = @to_CodCfoConFinInt
        Set @WCodCfoSbt = @to_CodCfoConFinInt
        Set @WCodCfoBon = 5910
      end
    else
	  begin
        Set @WCodCfoNor = @to_CodCfoConFinExt
        Set @WCodCfoSbt = @to_CodCfoConFinExt
        Set @WCodCfoBon = 6910
      end
  else
    if @WFlgOpeInt = 1
      begin
        Set @WCodCfoNor = @to_CodCfoNorInt
        Set @WCodCfoSbt = @to_CodCfoSbtInt
        Set @WCodCfoBon = 5910
	  end
    else
      begin
        Set @WCodCfoNor = @to_CodCfoNorExt
        Set @WCodCfoSbt = @to_CodCfoSbtExt
        Set @WCodCfoBon = 6910
      end

  -- coloca campos de NMFIS na memoria
  Declare @nm_NotFis int,
          @nm_SerNotFis int,
          @nm_ModNotFis varchar(2)

  if @pm_FlgNfe = 1
    begin
      -- verifica serie especifica para "incentivos"
      if Exists(Select ix.Ser_NfeEsp
                  From PDVCB cb
                       Inner Join ESXIF ix on cb.Cod_Estabe = ix.Cod_Estabe and cb.Id_IncFis = ix.Id_IncFis
                 Where cb.Cod_Estabe = @CodEstabe
                   And cb.Numero = @CodPed
                   And IsNull(ix.Ser_NfeEsp,0) > 0)
        if not Exists(Select ix.Ser_NfeEsp
                        From PDVCB cb
                             Inner Join ESXIF ix on cb.Cod_Estabe = ix.Cod_Estabe and cb.Id_IncFis = ix.Id_IncFis
                             Left  Join NMNFE nm on cb.Cod_Estabe = nm.Cod_Estabe and ix.Ser_NfeEsp = nm.Ser_Nfe
                       Where cb.Cod_Estabe = @CodEstabe
                         And cb.Numero = @CodPed
                         And IsNull(ix.Ser_NfeEsp,0) > 0
                         And IsNull(nm.Ser_Nfe,0) > 0)
          begin
            Insert Into NMNFE (Cod_Estabe, Ser_Nfe, Num_Nfe, Flg_Padrao, Flg_Contingencia, Mod_Nfe)
              Select cb.Cod_Estabe, ix.Ser_NfeEsp, 0, 0, 0, '55'
                From PDVCB cb
                     Inner Join ESXIF ix on cb.Cod_Estabe = ix.Cod_Estabe and cb.Id_IncFis = ix.Id_IncFis
               Where cb.Cod_Estabe = @CodEstabe
                 And cb.Numero = @CodPed
		  end

      -- poe dados de NMNFE na memoria
      if Exists(Select ix.Ser_NfeEsp
                  From PDVCB cb
                       Inner Join ESXIF ix on cb.Cod_Estabe = ix.Cod_Estabe and cb.Id_IncFis = ix.Id_IncFis
                       Inner Join NMNFE nm on cb.Cod_Estabe = nm.Cod_Estabe and ix.Ser_NfeEsp = nm.Ser_Nfe
                 Where cb.Cod_Estabe = @CodEstabe
                   And cb.Numero = @CodPed
                   And IsNull(ix.Ser_NfeEsp,0) > 0)
        Select @nm_SerNotFis = ix.Ser_NfeEsp
          From PDVCB cb
               Inner Join ESXIF ix on cb.Cod_Estabe = ix.Cod_Estabe and cb.Id_IncFis = ix.Id_IncFis
               Left Join NMNFE nm on cb.Cod_Estabe = nm.Cod_Estabe and ix.Ser_NfeEsp = nm.Ser_Nfe
          Where cb.Cod_Estabe = @CodEstabe
          And cb.Numero = @CodPed
          And IsNull(nm.Ser_Nfe,0) > 0
      else
        Select @nm_SerNotFis = Ser_Nfe
          From NMNFE
         Where Cod_Estabe = @CodEstabe 
           And Flg_Padrao = 1

      Select @nm_NotFis = Num_Nfe,
             @nm_ModNotFis = Mod_Nfe
        From NMNFE
       Where Cod_Estabe = @CodEstabe 
         And Ser_Nfe = @nm_SerNotFis
    end
  else
    begin
      Select @nm_NotFis = Nota_Fiscal_M1
        From NMFIS
       Where Cod_Estabe = @CodEstabe
    end

  -- variaveis de trabalho
  Declare @WQtdMov int,
          @WQtdPraNeg int,
          @WQtdDepNeg int,
          @WFlgEmpPra bit,
          @WFlgEmpDep bit,
          @WQtdMovLot int,
          @WQtdMovPed int,
          @WQtdMovBon int,
          @WQtdMovPra int,
          @WQtdMovDep int,
		  @WQtdDifDia int,
          @WTipNfs varchar(1),
          @WCodTabComOpe int,
          @WCodTabComVdr int,
          @WSumVlrBasDscIte numeric(18,4),
          @WCVlrTotNot numeric(18,4),
          @WVlrTotLiq numeric(18,4),
          @WVlrDesc numeric(18,4),
          @WVlrTotDspBolBan numeric(18,4),
          @WVlrJurPrzExc numeric(18,4),
          @WVlrBasFre numeric(18,4),
          @WCodDoc int,
          @WQtdPrdVrb int,
          @WPerRetBon numeric(18,4),
          @WCodPrm int,  -- codigo da promocao ou flag de politica promocional
          @WTipSai varchar(1),  -- 'B' = bonificacao
          @WVlrBasComiss numeric(18,4), 
          @WTipDes varchar(3),
          @WCodDes int,
          @WVlrMov numeric(18,4),
          @WIdTransacao int,
          @WCodFor int,
          @WVlrEdi numeric(18,4),
          @WVlrBru numeric(18,4),
          @WVlrLiqIte numeric(18,4),
          @WVlrLiqIteCusMed numeric(18,4)

          
  Set @PDatEmi = @Date
  Set @PEspNfs = ''
  Set @SerNfsRet = @cb_TipFat  -- FAT,ORC,FUN
  if @CodEstabe is null
    Set @CodEstabe = 0
  Set @NumNfsRet = @CodPed
  Set @PSerSel = ''
  Set @PNumSel = 0
  Set @PNumFor = 0
  Set @PQtdPagNfs = 0
  Set @PModNotFis = ''
  Set @PCodStaNfe = ''

  if @WCodCfoNor > 0
    begin
      Set @PEspNfs = 'NFF'
      Set @PQtdPagNfs = 0
      Set @PNumFor = 0
      Set @NumNfsRet = @nm_NotFis + 1

      if @pm_FlgNfe = 1 
        begin
          Set @SerNfsRet = cast(@nm_SerNotFis as varchar)
          Set @PModNotFis = @nm_ModNotFis
          Set @PCodStaNfe = 'N'
          -- atualiza NMNFE
          Update NMNFE
             Set Num_Nfe = @NumNfsRet
           Where Cod_Estabe = @CodEstabe 
             And Ser_Nfe = @nm_SerNotFis
        end
      else
        begin
          Set @SerNfsRet = @pm_ModeloNotaFiscal    -- FAT para M1
          Set @PModNotFis = @pm_ModeloNotaFiscal
          Set @PCodStaNfe = ''
          if @pm_NumItePagNfs > 0
            Set @PQtdPagNfs = Ceiling(@cb_QtdIte*1.00 /@pm_NumItePagNfs)
          Set @PNumFor = @NumFor + @PQtdPagNfs - 1
          -- atualiza NMFIS
          if @pm_FlgCtrSelFis = 1
            begin
              Set @PSerSel = @pm_SerieSeloFiscal
              Set @PNumSel = @NumSel + @PQtdPagNfs - 1
              Update NMFIS
                 Set Nota_Fiscal_M1 = @NumNfsRet,
                     Formulario_M1 = @PNumFor,
                     Selo_Fiscal = @PNumSel
               Where Cod_Estabe = @CodEstabe    
            end
          else
            begin
              Update NMFIS
                 Set Nota_Fiscal_M1 = @NumNfsRet,
                     Formulario_M1 = @PNumFor
               Where Cod_Estabe = @CodEstabe    
            end
        end
    end

  if (@cb_TipVct <> 'V') and (@cb_TipVct <> 'A')
    Set @PTipVct = 'P'   -- parcelado
  else
    Set @PTipVct = @cb_TipVct

  Set @PVlrDscCom = 0
  Set @WSumVlrBasDscIte = 0
  if @cb_PerDscCom > 0
    begin
      Set @PVlrDscCom = Round((@cb_VlrBasDscCom - @cb_VlrRepIcm) * @cb_PerDscCom/100,2)
      Set @WSumVlrBasDscIte = IsNull((Select sum(Round(Qtd_Pedido*C_PrcUni*(1-C_PerDscIte/100),2)-Vlr_RepIcms)
                                        From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
                                         And Desconto = 0 And Qtd_Pedido > 0),0)
      if @PVlrDscCom > @WSumVlrBasDscIte
        begin
          Set @PVlrDscCom = 0
          Set @cb_PerDscCom = 0
        end
     end
    
  -- registra tipo de retencao do imp. subst.
  -- se nao tem credenciamento no estado: nao retem na fonte
  -- F- imposto incluido no valor da NF
  -- R- imposto a recolher, nao incluido na NF mas cobrado na duplicata
  Set @PTipRetImp = 'F'
  if @to_CodCfoNorInt > 0  
    if @uf_FlgRegSubTri = 0
      Set @PTipRetImp = 'R'

  if @PTipRetImp = 'R'
    Set @PVlrTotNot = @cb_VlrLiqIte - @PVlrDscCom - @cb_VlrDscBon - @cb_VlrRepIcm + @cb_VlrDespes + @cb_VlrDspExt + @cb_VlrIpi + @cb_VlrSbtRes
  else
    Set @PVlrTotNot = @cb_VlrLiqIte - @PVlrDscCom - @cb_VlrDscBon - @cb_VlrRepIcm + @cb_VlrDespes + @cb_VlrDspExt + @cb_VlrIpi + @cb_VlrSbtRes + @cb_VlrSubTri - @cb_VlrDscTri

  if @cb_FlgVlrFin = 1
    if (@WCodCfoNor > 0) or (@SerNfsRet = 'ORC') or (@to_FlgLanFin = 1)
      begin
        -- recalcula prazo medio, qtd parcelas e desc. financ. ponderado da nf
        Declare @WSomat numeric(18,4), 
                @WVlrDup numeric(18,4), 
                @WVlrFin numeric(18,4)

        Set @PQtdPar = Isnull((Select COUNT(*)
                                 From PDVDP
                                Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed),0)
                
        Set @WSomat = Isnull((Select sum(Vlr_Duplic*cast(Dat_Vencim - @cb_DatPed as int))
                                From PDVDP
                               Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
                                 And IsNull(Flg_Apresentacao,0)=0),0)
        
        Set @WVlrDup = Isnull((Select sum(Vlr_Duplic)
                                 From PDVDP
                                Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed),0)
                
        Set @WVlrFin = Isnull((Select sum(Vlr_DescFinanc)
                                 From PDVDP
                                Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed),0)
                
        -- atualiza cabecalho da NF
        if @WVlrDup > 0 
          begin
            Set @PQtdPrzMed = Round(@WSomat/@WVlrDup,0)
            if @cb_TipVct <> 'P'    --nao ponderado
              Set @PPerDscFinLiq = Round(@WVlrFin*100/@WVlrDup,4) 
          end
        else
          begin
            Set @PQtdPrzMed = 0
            Set @PPerDscFin = 0
          end
      end

  -- recalcula desconto financeiro (aplicar somente sobre valor tot. mercadoria) p/ gravar no item
  Set @PPerDscFin = IsNull(@PPerDscFinLiq,0)
  if ((@cb_VlrSubTri+@cb_VlrSbtRes) > 0) and (@PPerDscFinLiq > 0)
    begin
      Set @WVlrTotLiq = @cb_VlrLiqIte - @PVlrDscCom - @cb_VlrDscBon - @cb_VlrRepIcm - @cb_VlrDscTri 
      Set @WVlrDesc = @PPerDscFinLiq * @WVlrTotLiq / 100
      Set @WVlrTotLiq = @WVlrTotLiq + @cb_VlrSubTri + @cb_VlrSbtRes
      if @WVlrTotLiq > 0 
        Set @PPerDscFin = Round(@WVlrDesc/@WVlrTotLiq*100,2)
    end

  -- calcula despesa ref. taxa administrativa
  Set @WVlrOutDsp = 0.00     
  if @ag_PerTaxAdm > 0
    begin
      if @ag_CodAplTaxAdm = 'P' -- margem (participação)
        Set @WVlrOutDsp = Round(@cb_VlrLiqIte/(1-@ag_PerTaxAdm/100),2)-Round(@cb_VlrLiqIte,2)
      if @ag_CodAplTaxAdm = 'A'  -- mark-up (acrescimo)
        Set @WVlrOutDsp = Round(@cb_VlrLiqIte*@ag_PerTaxAdm/100,2)     
    end

  -- calcula despesa boleto bancario a cobrar na nota fiscal
  Set @WVlrTotDspBolBan = 0
  if @to_FlgLanFin = 1
    begin
      Set @WVlrTotDspBolBan = Round(Isnull(@ag_VlrDspBolBan,0) * @PQtdPar,2)
      Set @WVlrOutDsp = @WVlrOutDsp + @WVlrTotDspBolBan
    end

  -- debito verba/despesa de boleto vendedor
  Set @PVlrDebVrbVdr = 0
  if @TipNfs = 'V'
    begin
      -- taxa boleto
      if @pm_FlgDebBlqBanVrbVdr = 1
        begin
          Set @PVlrDebVrbVdr = @WVlrTotDspBolBan
          Set @WVlrOutDsp = @WVlrOutDsp - @WVlrTotDspBolBan    -- isenta cliente
        end
      -- juros prazo excedente
      Set @WVlrJurPrzExc = 0
      Set @WQtdDifDia = cast(@PQtdPrzMed as int) - @pm_QtdPrzMedCfg
      if (@WQtdDifDia > 0) and (@pm_QtdPrzMedCfg > 0) and (@pm_PerCusFinDiaExcPrzMedCfg > 0)
        begin
          Set @WVlrJurPrzExc = @WQtdDifDia*@pm_PerCusFinDiaExcPrzMedCfg*@PVlrTotNot/100
          Set @PVlrDebVrbVdr = @PVlrDebVrbVdr + @WVlrJurPrzExc
        end   
    end

  if @cb_VlrDespes <> @WVlrOutDsp
    Set @PVlrOutDsp = @WVlrOutDsp
  else
    Set @PVlrOutDsp = @cb_VlrDespes

  if @cb_CodCli > 0
    begin
      Set @PCgc = @cl_CgcCpf
      Set @PCgf = @cl_Cgf
      Set @PDesEnd  = Substring(@cl_DesEnd,1,50)
      Set @PDesBai = @ba_DesBai
      Set @PCep = @cl_Cep
      Set @PEst = @cl_CodEst
      Set @PDesCid = @ci_DesCid
      Set @PCodCid = @cl_CodCid
      Set @PCodCidIbge = @ci_CodCidIbge
      Set @PCodMacReg = @ba_CodMacReg 
      Set @PCodMicReg = @ba_CodMicReg
     end
  else
    begin
      Set @PCgc = ''
      Set @PCgf = ''
      Set @PDesEnd  = ''
      Set @PDesBai = ''
      Set @PCep = @em_Cep 
      Set @PEst = @em_CodEst
      Set @PDesCid = (Select Descricao From CIDAD Where Cod_Estado = @em_CodEst And Codigo = @pm_CodCidEmpLoc)
      Set @PCodCid = @pm_CodCidEmpLoc
      Set @PCodCidIbge = (Select Cod_CidIbge From CIDAD Where Cod_Estado = @em_CodEst And Codigo = @pm_CodCidEmpLoc)
      Set @PCodMacReg = @pm_CodMacRegEmpLoc
      Set @PCodMicReg = @pm_CodMicRegEmpLoc
    end

  -- Grava registro NFSCB 
  if (@cb_VlrSubTri+@cb_VlrSbtRes) > 0
    Set @PCodCfo = @WCodCfoSbt
  else
    Set @PCodCfo = @WCodCfoNor

  Set @PUfPlaVei = @cb_UfPlaVei
  Set @PCodPlaVei = @cb_CodPlaVei
  if (@PUfPlaVei = '') and (@tr_Pessoa = 'F')
    begin
      Set @PUfPlaVei = @tr_UfPlaVei
      Set @PCodPlaVei = @tr_CodPlaVei
    end

  -- registra Insc.Est. ST do emitente na UF destino
--  if (@WFlgOpeInt = 0) and (@uf_FlgRegSubTri= 1) and (@uf_BlqInsEstSbtNfs = 0)
  if @uf_FlgRegSubTri= 1
    Set @PNumInscriSbtEmiUfd = @uf_NumInscriSbt
  else
    Set @PNumInscriSbtEmiUfd = ''


  -- aqui cuidado: implementar em PR_AtualizaCabecNFS ou PR_CalcTributNFS ?????
