    begin
      Set @PVlrSubTri = 0
      Set @PVlrDscTri = 0
      Set @PVlrRecSbt = @cb_VlrSubTri
	  if @cb_VlrSubTri >= @cb_VlrDscTri
        Set @PVlrRecSbt = @cb_VlrSubTri - @cb_VlrDscTri
    
	  Set @PVlrFcpSbt = 0
	  Set @PVlrFcpSbtRec = @cb_VlrSubTriFcp 
    end
  else
    begin
      Set @PVlrSubTri = @cb_VlrSubTri
      Set @PVlrDscTri = @cb_VlrDscTri
      Set @PVlrRecSbt = 0

	  Set @PVlrFcpSbt = @cb_VlrSubTriFcp
	  Set @PVlrFcpSbtRec = 0
    end


  Insert into NFSCB (Cod_Estabe, Ser_Nota, Num_Nota)
    Values (@CodEstabe, @SerNfsRet, @NumNfsRet)
  if @@error <> 0
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end    

  Select @cf_FlgBlqTrfEstFis = IsNull(Flg_BlqTrfEstFis,0) 
