          @Acp_VlrBonificacao numeric (18,4),
          @Acp_VlrDscBonDup numeric (18,4),
          
          @Acp_VlrIcmParDes numeric(18,4),
          @Acp_VlrIcmParRem numeric(18,4),

          @Acp_VlrIcmFcpDes numeric(18,4),

          @Acp_VlrFcpIcm numeric(18,4),
          @Acp_VlrFcpSbt numeric(18,4),
          @Acp_VlrFcpSbtRet numeric(18,4),

          @Acp_VlrBasIpi numeric(18,4),
          @Acp_VlrIpi numeric(18,4)


  -- pega tabela de comissao do vendedor e operador
  Set @WCodTabComOpe = (Select Cod_TabCom From VEXES Where Cod_Estabe = @CodEstabe And Cod_Vended = @cb_CodOpe)
  Set @WCodTabComVdr = (Select Cod_TabCom From VEXES Where Cod_Estabe = @CodEstabe And Cod_Vended = @cb_CodVdr)

  -- comissao de supervisor/gerencia do vendedor    
  Set @cb_PerComSup = (Select IsNull(Per_ComNor,0) From SUPER Where Codigo = @cb_CodSup)
  Set @cb_PerComGer = (Select IsNull(Per_ComNor,0) From GEREN Where Codigo = @cb_CodGer)

  -- comissao de supervisor/gerencia do operador    
  Set @cb_PerComSupOpe = (Select IsNull(Per_ComNor,0) From SUPER Where Codigo = @cb_CodSupOpe)
  Set @cb_PerComGerOpe = (Select IsNull(Per_ComNor,0) From GEREN Where Codigo = @cb_CodGerOpe)

  -- verifica se existe registros em PDVLT (WMS)
  Set @WCodOri = ''
  Set @WFlgAcumula = 0
  if Exists(Select top 1 * From PDVLT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Qtd_Lote > 0)
    begin
      Set @WFlgAcumula = 1 
      -- calcula volume e itens em PDVLT
      Set @cb_QtdIte = IsNull((Select count(*) From (Select distinct Cod_Produt, Cod_Lote From PDVLT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Qtd_Lote > 0) x),0)
--      Set @cb_QtdVol = IsNull((Select count(distinct Num_Vol) From PDVLT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Qtd_Lote > 0),0)
      
      -- configura cod. origem
      if @TipNfs = 'V'
        Set @WCodOri = 'SAI_VEN'
      else  
      if @TipNfs = 'D'
        Set @WCodOri = 'SAI_DEV'
      else  
      if @TipNfs = 'T'
        Set @WCodOri = 'SAI_TRF'
      else  
      if @TipNfs = 'O'
        Set @WCodOri = 'SAI_OUT'
    end

  -- Gera itens da nota
  -- inmportante que seja zero. Parametro utilizado em uma consulta abaixo
  Set @P_NumSeqIte = 0

  -- cria tabela dos lotes do produto que serao utilizados
  Create Table #PDVLT_AUX
       (Chave int identity,
        Cod_Lote varchar(20),
        Qtd_CxaFec int,
        Cod_Dep smallint,
        Num_Rua smallint,
        Num_Col smallint,
        Num_Niv smallint,
        Num_Apt smallint,
        Cod_LocFis varchar(15),
        Qtd_EmbFec int,
        Qtd_Ite int,
        Qtd_Lot int,
        Qtd_Pra int,
        Qtd_Dep int)


  -- R0005  -----------------------------------------------------------------------------------------------------------------
  Declare PRODU_Cr Cursor Local Fast_Forward For 
  
    Select distinct Cod_Produto
      From PDVIT
     Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
       And (IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) > 0

  Open PRODU_Cr
  Fetch Next From PRODU_Cr Into @it_CodPrd
  While @@FETCH_STATUS = 0
    begin
      if @WFlgAcumula = 1 
        begin
          Insert Into #PDVLT_AUX (Cod_Lote, Qtd_CxaFec, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis, Qtd_EmbFec,
                                  Qtd_Ite, Qtd_Lot, Qtd_Pra, Qtd_Dep)
            Select Cod_Lote, Qtd_CxaFec, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis, Qtd_EmbFec,
                   count(*) as QtdIte, sum(Qtd_Lote) as QtdLot, 
                   sum(IsNull(Qtd_LotePra,0)) as QtdPra, sum(IsNull(Qtd_LoteDep,0)) as QtdDep
              From PDVLT
             Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
              And Cod_Produt = @it_CodPrd
              And Qtd_Lote > 0
            Group by Cod_Lote, Qtd_CxaFec, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis, Qtd_EmbFec
            Order by Cod_Lote, Qtd_CxaFec
            
            -- insere registros PRLOG  
            Declare PDVLTAUX_Cr Cursor Local Fast_Forward For 

              Select Cod_Lote, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Qtd_Lot
                From #PDVLT_AUX
               Where Qtd_Lot > 0

            Open PDVLTAUX_Cr
            Fetch Next From PDVLTAUX_Cr Into @lt_CodLot, @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt, @lt_QtdLot 
            While @@FETCH_STATUS = 0
              begin
                -- saida: qtd negativa
                Set @lt_QtdLot = @lt_QtdLot*(-1) 
                Exec PR_InserePRLOG @CodEstabe, @it_CodPrd, @lt_CodLot, @lt_CodDep, 
                                    @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt,
                                    @lt_QtdLot, @WCodOri, '', @SerNfsRet, @NumNfsRet, '', @DesUsu
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end    
                Fetch Next From PDVLTAUX_Cr Into @lt_CodLot, @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt, @lt_QtdLot 
              end  
            Close PDVLTAUX_Cr 
            Deallocate PDVLTAUX_Cr
        end
      else
        begin
          Insert Into #PDVLT_AUX (Cod_Lote, Qtd_CxaFec, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis, Qtd_EmbFec,
                                  Qtd_Ite, Qtd_Lot, Qtd_Pra, Qtd_Dep)
            Select Cod_Lote, 0, 01, 0, 0, 0, 0, '*', 0, 
                   count(*) as QtdIte, sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) as QtdPdv, 
                   sum(IsNull(Qtd_Pra,0)) as QtdPra, sum(IsNull(Qtd_Dep,0)) as QtdDep
              From PDVIT
             Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
               And Cod_Produto = @it_CodPrd
               And Qtd_Pedido > 0
             Group by Cod_Lote
             Order by Cod_Lote
        end


      -- R0010 -------------------------------------------------------------------------------------------------------------------- 
      --- seleciona itens do pedidos que serao faturados
      Declare PDVIT_Cr Cursor Local Fast_Forward For 

        Select it.Cod_Lote, IsNull(it.Tip_Sai,''), it.Qtd_Solicitado, IsNull(it.Qtd_Pedido,0), IsNull(it.Qtd_Bonificacao,0), it.Per_Desconto, it.C_PerDscIte, 
               it.Prc_Unitario, it.C_PrcUni, IsNull(it.Prc_UniSemAcrIcm,0), IsNull(Flg_PrcUniAcrIcm,0), IsNull(it.Prc_UniComAcrIcm,0),
			   it.Prc_Tabela, it.Prc_TabBru, it.Prc_Fabric, it.Prc_MaxCon, it.Prc_RefFpb, it.Flg_BlqInfPar,
               it.Flg_PrcUniDsc, it.Cod_Promocao, it.Tip_Aux, it.Cod_ClaTri, Ltrim(Rtrim(it.Ctrl_Tributacao)), Ltrim(Rtrim(it.Cod_CSOSN)), it.Desconto, it.Per_DscVis, it.Per_Descon,
               IsNull(it.Vlr_DscBonRat,0), IsNull(it.Vlr_Despes,0), IsNull(it.Vlr_DspExt,0), it.Vlr_BasIcmsNor, it.Alq_Icms, it.Vlr_IcmsNor, it.Vlr_BasRepIcms, IsNull(it.Per_RepIcms,0), it.Vlr_RepIcms, it.Vlr_PrdSubTri,
               it.Vlr_BasSubsTrib, it.Vlr_SubsTrib, IsNull(it.Vlr_BasSbtRes,0), IsNull(it.Vlr_SbtRes,0), IsNull(it.Vlr_BasDscTri,0), it.Per_DscTri, IsNull(it.Vlr_DscTri,0), 
               it.Vlr_BasIcmsTri, it.Vlr_IcmsTri, it.Vlr_Isento, it.Vlr_Outros, it.Vlr_Bruto,
               IsNull(it.Fat_CnvImpFat,0), it.Qtd_ImpFat, it.Prc_UniImpFat, it.Des_UnvImpFat, it.Des_AprImpFat, it.Id_PolCom, it.Qtd_Pra, it.Qtd_Dep,
               it.Cod_ModBasCalIcm, it.Cod_ModBasCalIcmSbt, it.Vlr_BasTri, it.Per_RedBasCalIcm, it.Per_RedBasCalIcmSbt, 
               it.Alq_IcmSbt, it.Alq_AgrSbt, IsNull(it.Vlr_Verba,0), IsNull(it.Vlr_VrbVdr,0), IsNull(it.Vlr_VrbOpe,0), IsNull(it.Vlr_VrbSup,0), 
               it.Cod_PrjPde, it.Prc_UniPde, it.Per_DscPde, it.Num_SeqPdc, IsNull(it.Flg_PolPrm,0),
               IsNull(it.Vlr_DscBonDup,0), IsNull(it.Vlr_Bonificacao,0), IsNull(it.Prc_CusMinComMarkup,0), IsNull(it.Vlr_BasVerba,0),
               IsNull(it.Alq_IntIcmDes,0), IsNull(it.Per_AcrAlqIntFcp,0), IsNull(it.Per_PrvParIcm,0),
               IsNull(it.Vlr_IcmFcpDes,0), IsNull(it.Vlr_IcmParDes,0), IsNull(it.Vlr_IcmParRem,0), IsNull(it.Cod_KitPrm,0), IsNull(it.Flg_UsaDebPresum,0), IsNull(it.Alq_IcmPresum,0),
			   IsNull(it.Prc_PolCom,0), IsNull(it.Per_DscPolCom,0),
			   IsNull(it.Vlr_IcmsDeson,0), IsNull(it.Cod_MtvIcmsDeson,''), IsNull(it.Vlr_DscCalSuframa,0), IsNull(it.Flg_IncFis,0),
			   IsNull(it.Alq_FcpIcm,0), IsNull(it.Vlr_FcpIcm,0), IsNull(it.Alq_FcpSbt,0), IsNull(it.Vlr_FcpSbt,0), IsNull(it.Alq_FcpSbtRet,0), IsNull(it.Vlr_FcpSbtRet,0),
			   IsNull(it.Per_IcmDiferi,0), IsNull(it.Vlr_IcmDiferi,0), pr.Cod_Fabricante,
               IsNull(it.Cod_OriMer,'0'), IsNull(it.Vlr_BasIpi,0), IsNull(it.Vlr_Ipi,0), IsNull(it.Alq_Ipi,0), IsNull(it.CST_Ipi,''), IsNull(it.Cod_EnqIpi,''), 
			   IsNull(Vlr_BasIrf, 0), IsNull(Alq_Irf, 0), IsNull(Vlr_Irf, 0) 
          From PDVIT it
               Inner join PRODU pr on pr.Codigo = it.Cod_Produto
         Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
           And Cod_Produto = @it_CodPrd
           And (IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) > 0

      Open PDVIT_Cr
      Fetch Next From PDVIT_Cr Into @it_CodLot, @it_TipSai, @it_QtdSol, @it_QtdPed, @it_QtdBon, @it_PerDsc, @it_CPerDscIte, 
                                    @it_PrcUni, @it_CPrcUni, @it_PrcUniSemAcrIcm, @it_FlgPrcUniAcrIcm, @it_PrcUniComAcrIcm,
                                    @it_PrcTab, @it_PrcTabBru, @it_PrcFab, @it_PrcMax, @it_PrcRefFpb, @it_FlgBlqInfPar,
                                    @it_FlgPrcUniDsc, @it_CodPrm, @it_TipAux, @it_CodClaTri, @it_CodCst, @it_CodCsosn, @it_FlgBlqDsc, @it_PerDscVis, @it_PerDscPrz,
                                    @it_VlrDscBonRat, @it_VlrDespes, @it_VlrDspExt, @it_VlrBasIcmNor, @it_AlqIcm, @it_VlrIcmNor, @it_VlrBasRepIcm, @it_PerRepIcm, @it_VlrRepIcm, @it_VlrPrdSubTri,
                                    @it_VlrBasSubTri, @it_VlrSubTri, @it_VlrBasSbtRes, @it_VlrSbtRes, @it_VlrBasDscTri, @it_PerDscTri, @it_VlrDscTri, 
                                    @it_VlrBasIcmTri, @it_VlrIcmTri, @it_VlrIsento,  @it_VlrOutros, @it_VlrBru,
                                    @it_FatCnvImpFat, @it_QtdImpFat, @it_PrcUniImpFat, @it_DesUnvImpFat, @it_DesAprImpFat, @it_IdPolCom, @it_QtdPra, @it_QtdDep,
                                    @it_CodModBasCalIcm, @it_CodModBasCalIcmSbt, @it_VlrBasTri, @it_PerRedBasCalIcm, @it_PerRedBasCalIcmSbt, 
                                    @it_AlqIcmSbt, @it_AlqAgrSbt, @it_VlrVerba, @it_VlrVrbVdr, @it_VlrVrbOpe, @it_VlrVrbSup,
                                    @it_CodPrjPde, @it_PrcUniPde, @it_PerDscPde, @it_NumSeqPdc, @it_FlgPolPrm,
                                    @it_VlrDscBonDup, @it_VlrBonificacao, @it_PrcCusMinComMarkup, @it_VlrBasVerba,
                                    @it_AlqIntIcmDes, @it_PerAcrAlqIntFcp, @it_PerPrvParIcm, 
                                    @it_VlrIcmFcpDes, @it_VlrIcmParDes, @it_VlrIcmParRem, @it_CodKitPrm, @it_FlgUsaDebPresum, @it_AlqIcmPresum,
									@it_PrcPolCom, @it_PerDscPolCom,
                                    @it_VlrIcmDesone, @it_CodMtvIcmDesone, @it_VlrDscCalSuframa, @it_FlgIncFis,
                                    @it_AlqFcpIcm, @it_VlrFcpIcm, @it_AlqFcpSbt, @it_VlrFcpSbt, @it_AlqFcpSbtRet, @it_VlrFcpSbtRet,
                                    @it_PerIcmDiferi, @it_VlrIcmDiferi, @it_CodFab,
                                    @it_CodOriMer, @it_VlrBasIpi, @it_VlrIpi, @it_AlqIpi, @it_CSTIpi, @it_CodEnqIpi, @cb_VlrBasIrfIt, @cb_AlqIrfIt, @cb_VlrIrfIt 
      While @@FETCH_STATUS = 0
        begin
          if @it_FatCnvImpFat = 0
            Set @it_FatCnvImpFat = 1

          -- CFOp do item
          Select @P_PrcCusMed = IsNull(p.Prc_CusMed,0),
                 @P_PrcCusCom = Case 
                                  When IsNull(p.Prc_CusMedCom,0) > 0 Then IsNull(p.Prc_CusMedCom,0) 
                                  Else IsNull(p.Prc_CusMed,0) 
                                End,
                 @P_FlgIncFis = IsNull(pr.Flg_IncFis,0),
                 @it_TipAux = pr.Tip_LisPis,
                 @pr_CodClaFis = Ltrim(Rtrim(pr.Cod_ClaFis)),
                 @pr_CodCEST = Ltrim(Rtrim(pr.Cod_CEST)),
                 @pr_CodGrpPrc = ISNULL(pr.Cod_GrpPrc,'')
            From PRXES p 
                 Inner Join PRODU pr on p.Cod_Produt = pr.Codigo
           Where p.Cod_Estabe = @CodEstabe
             And p.Cod_Produt = @it_CodPrd

          Set @P_FlgIncFis = @it_FlgIncFis

          if IsNull(@it_CodCst,'') = ''
            begin
              Set @rx_CodCst = Ltrim(Rtrim(IsNull((Select Cod_ImpNotSai From RTXCT Where Cod_RegTri = @cb_CodRegTri And Cod_ClaTri = @it_CodClaTri),'')))
              Set @it_CodCst = @rx_CodCst
             end
          if Len(@it_CodCst) < 2
            Set @it_CodCst = @it_CodCst + '0'

          if Charindex(@it_CodCst,';10;30;60;70;') > 0
            Set @P_CodCfo = @WCodCfoSbt
          else
            Set @P_CodCfo = @WCodCfoNor
            
          -- registra desconto informado no item  (se desc. foi convertido para Global o valor inicial fica armazenado aqui)
          Set @P_PerDsc = 0
          Set @P_PerDscFin = 0
          if Substring(@cb_CodOriPdv,2,1) = 'F'
            begin
              if @cb_TipVct = 'V'
                Set @P_PerDsc = @it_PerDscVis
              else
                Set @P_PerDsc = @it_PerDscPrz
              if @PPerDscFinLiq > 0
                Set @P_PerDscFin = @P_PerDsc
            end
          else
            begin
              Set @P_PerDsc = @it_PerDscPrz    
              Set @P_PerDscFin = @PPerDscFinLiq
            end

          Set @it_VlrBruIte = Round(@it_CPrcUni * (@it_QtdPed+@it_QtdBon),2)
          Set @it_VlrTotIte = Round(@it_QtdPed * @it_CPrcUni * (1-@it_CPerDscIte/100),2)
          if @it_FlgBlqDsc = 1
            Set @it_VlrLiqIte = @it_VlrTotIte - @it_VlrRepIcm - @it_VlrDscBonRat + @it_VlrDespes + @it_VlrDspExt + @it_VlrSubTri + @it_VlrSbtRes - @it_VlrDscTri
          else
            Set @it_VlrLiqIte = @it_VlrTotIte * (1 - @cb_PerDscCom/100) - @it_VlrRepIcm - @it_VlrDscBonRat + @it_VlrDespes + @it_VlrDspExt + @it_VlrSubTri + @it_VlrSbtRes - @it_VlrDscTri

          -- inicializa acumuladores do item do pedido
          Set @Acp_UndIte = 0

          -- indice de bonificacao
          if @it_QtdBon > 0
            Set @WFatBon = @it_QtdBon*1.0/(@it_QtdPed+@it_QtdBon)
          else
            Set @WFatBon = 0

          Set @Sld_QtdPed = @it_QtdPed
          Set @Sld_QtdBon = @it_QtdBon

          while (@Sld_QtdPed+@Sld_QtdBon) > 0
            begin
              -- selciona lotes ainda disponiveis
              Declare PDVLTAUX_Cr Cursor Local Fast_Forward For 
              
                Select Chave, Cod_Lote, Qtd_CxaFec, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, 
                       Cod_LocFis, Qtd_EmbFec, Qtd_Ite, Qtd_Lot, Qtd_Pra, Qtd_Dep
                From #PDVLT_AUX
                Where Qtd_Lot > 0
                
              Open PDVLTAUX_Cr
              Fetch Next From PDVLTAUX_Cr Into @lt_Chave, @lt_CodLot, @lt_QtdCxaFec, @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt, 
                                               @lt_CodLocFis, @lt_QtdEmbFec, @lt_QtdIte, @lt_QtdLot, @lt_QtdPra, @lt_QtdDep
             
              While (@@FETCH_STATUS = 0) and ((@Sld_QtdPed+@Sld_QtdBon) > 0)
                begin
                  Set @P_CodLot = @lt_CodLot
                  Set @P_QtdPed = 0
                  Set @P_QtdBon = 0
                  Set @P_QtdPra = 0
                  Set @P_QtdDep = 0

                  if (@lt_QtdPra+@lt_QtdDep) <> @lt_QtdLot
                    Set @lt_QtdPra = @lt_QtdLot - @lt_QtdDep
                    
                  -- acumula quantidades por lote ---
                  While (@P_CodLot = @lt_CodLot) and ((@Sld_QtdPed+@Sld_QtdBon) > 0) and (@@FETCH_STATUS = 0)
                    begin
                      Set @WQtdMovLot = 0
                      Set @WQtdMovPed = 0
                      Set @WQtdMovBon = 0
                      Set @WQtdMovPra = 0
                      Set @WQtdMovDep = 0

                      -- qtd. lote (Qtd_Ped, Qtd_Bon) -------------------
                      if (@Sld_QtdPed+@Sld_QtdBon) > @lt_QtdLot
                        Set @WQtdMovLot = @lt_QtdLot           
                      else
                        Set @WQtdMovLot = @Sld_QtdPed+@Sld_QtdBon
                      if @Sld_QtdBon > 0
                        Set @WQtdMovBon = Round(@WQtdMovLot*@WFatBon,0)
                      Set @WQtdMovPed = @WQtdMovLot - @WQtdMovBon
                      ---------------------------------------------------

                      if @WQtdMovLot > @lt_QtdPra
                        Set @WQtdMovPra = @lt_QtdPra
                      else
                        Set @WQtdMovPra = @WQtdMovLot
                      Set @WQtdMovDep = @WQtdMovLot - @WQtdMovPra
                      
                      -- atualiza lotes estoque grosso/fino f[@lt_QtdCxaFec]
                      -- configura flag de emprestimo de estoque
                      Set @WFlgEmpPra = 0
                      Set @WFlgEmpDep = 0
                      if (@PCodCfo > 0) and (@WQtdMovDep > 0)
                        Set @WFlgEmpDep = 1 
                      if (@PCodCfo = 0) and (@WQtdMovPra > 0)
                        Set @WFlgEmpPra = 1 

                      -- grava movimento (saida: sinal negativo)
                      Set @WQtdPraNeg = @WQtdMovPra * (-1)
                      Set @WQtdDepNeg = @WQtdMovDep * (-1)
  
                      if (@lt_QtdCxaFec > 0) and ((IsNull(@lt_CodLocFis,'') = '') or (@lt_CodLocFis <> 'PRLOT'))   -- depositO FECHADO
                        begin
                          -- atualiza mov em PRSLD e fisico em PRLTL e PRODU
                          EXEC PR_AtualizaSaldoEstoqueGrosso @CodEstabe, @it_CodPrd, @P_CodLot, @lt_QtdEmbFec, @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt,
                                                             @PDatEmi, 'S', @TipNfs, @WQtdPraNeg, @WFlgEmpPra, @WQtdDepNeg, @WFlgEmpDep
                          if (@@error <> 0)
                            begin
                              if @@trancount > 0
                                Rollback Transaction
                              Return
                            end
                            
                          -- retira a quantidade solicitada (em PRLTL)
                          EXEC PR_DecrementaSaldoSolicitado_PRLTL @CodEstabe, 'P', @cb_StaPdv1, @cb_StaPdv2, @cb_TipBlq, @it_CodPrd, @P_CodLot, @lt_QtdEmbFec,
                                                                  @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt, @WQtdMovPra, @WQtdMovDep
                          if (@@error <> 0)
                            begin
                              if @@trancount > 0
                                Rollback Transaction
                              Return
                            end
                        end
                      else
                        begin
                          -- atualiza mov em PRSLD e fisico em PRLOT e PRODU
                          EXEC PR_AtualizaSaldoEstoque 'NF', @CodEstabe, @lt_CodDep, @it_CodPrd, @P_CodLot, @PdatEmi, 'S', @TipNfs, @WQtdPraNeg, @WFlgEmpPra, @WQtdDepNeg, @WFlgEmpDep
                          if (@@error <> 0)
                            begin
                              if @@trancount > 0
                                Rollback Transaction
                              Return
                            end
                            
                          -- retira a quantidade solicitada (em PRLOT)
                          EXEC PR_DecrementaSaldoSolicitado_PRLOT @CodEstabe, 'P', @cb_StaPdv1, @cb_StaPdv2, @cb_TipBlq, @it_CodPrd, @P_CodLot, @lt_CodDep, @WQtdMovPra, @WQtdMovDep
                          if (@@error <> 0)
                            begin
                              if @@trancount > 0
                                Rollback Transaction
                              Return
                            end
                        end

                      -- acumula por lote
                      Set @P_QtdPed = @P_QtdPed + @WQtdMovPed
                      Set @P_QtdBon = @P_QtdBon + @WQtdMovBon
                      Set @P_QtdPra = @P_QtdPra + @WQtdMovPra
                      Set @P_QtdDep = @P_QtdDep + @WQtdMovDep

                      -- decrementa saldos           
                      Set @Sld_QtdPed = @Sld_QtdPed - @WQtdMovPed
                      Set @Sld_QtdBon = @Sld_QtdBon - @WQtdMovBon

                      Update #PDVLT_AUX
                         Set Qtd_Lot = Qtd_Lot - @WQtdMovLot,
                             Qtd_Pra = Qtd_Pra - @WQtdMovPra,
                             Qtd_Dep = Qtd_Dep - @WQtdMovDep
                       Where Chave = @lt_Chave
                        
                      Delete From #PDVLT_AUX
                       Where Qtd_Lot = 0 

                      Fetch Next From PDVLTAUX_Cr Into @lt_Chave, @lt_CodLot, @lt_QtdCxaFec, @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt, 
                                                       @lt_CodLocFis, @lt_QtdEmbFec, @lt_QtdIte, @lt_QtdLot, @lt_QtdPra, @lt_QtdDep
                    end  -- While (@P_CodLot = @lt_CodLot) and (@lt_QtdLot > 0)

                  -- calcula participacao
                  Set @WFatParIte = (@P_QtdPed+@P_QtdBon)*1.0/(@it_QtdPed+@it_QtdBon)
                  if @it_FatCnvImpFat > 0
                    Set @P_QtdImpFat = Round((@P_QtdPed+@P_QtdBon)*1.0/@it_FatCnvImpFat,0)
                  else
                    Set @P_QtdImpFat = 0

                  Set @P_VlrBruIte = Round(@WFatParIte*@it_VlrBruIte,2)
                  Set @P_VlrTotIte = Round(@WFatParIte*@it_VlrTotIte,2)
                  Set @P_VlrLiqIte = @WFatParIte*@it_VlrLiqIte
                  Set @P_VlrBasTri = Round(@WFatParIte*@it_VlrBasTri,2)

                  -- preciso do repasse e desconto rateado p/ comparar B.C. Icms 
                  Set @P_VlrBasRepIcm = Round(@WFatParIte*@it_VlrBasRepIcm,2)
                  Set @P_VlrRepIcm = @WFatParIte*@it_VlrRepIcm
                  
                  Set @P_VlrDscRat = 0
                  if (@it_FlgBlqDsc = 0) and (@WSumVlrBasDscIte > 0)
                    Set @P_VlrDscRat = (@P_VlrTotIte - @P_VlrRepIcm) * @PVlrDscCom/@WSumVlrBasDscIte
                    
                  Set @P_VlrBasDscTri = Round(@WFatParIte*@it_VlrBasDscTri,2)
                  Set @P_VlrDscTri = Round(@WFatParIte*@it_VlrDscTri,2)
                  Set @P_VlrDscBonRat = Round(@WFatParIte*@it_VlrDscBonRat,2)
                  
                  Set @P_VlrDespes = Round(@WFatParIte*@it_VlrDespes,2)
                  Set @P_VlrDspExt = Round(@WFatParIte*@it_VlrDspExt,2)

                  Set @P_VlrBasIcmNor = Round(@WFatParIte*@it_VlrBasIcmNor,2)
                  Set @P_VlrIcmNor = @WFatParIte*@it_VlrIcmNor
                  Set @P_VlrBasIcmTri = Round(@WFatParIte*@it_VlrBasIcmTri,2)
                  Set @P_VlrIcmTri = @WFatParIte*@it_VlrIcmTri
                  Set @P_VlrIcmDiferi = @WFatParIte*@it_VlrIcmDiferi
				  Set @P_VlrIcmDesone = @WFatParIte*@it_VlrIcmDesone
				  Set @P_VlrDscCalSuframa = @WFatParIte*@it_VlrDscCalSuframa
                  Set @P_VlrIsento = Round(@WFatParIte*@it_VlrIsento,2)
                  Set @P_VlrOutros = Round(@WFatParIte*@it_VlrOutros,2)

                  Set @P_VlrPrdSubTri = Round(@WFatParIte*@it_VlrPrdSubTri,2)
                  Set @P_VlrBasSubTri = Round(@WFatParIte*@it_VlrBasSubTri,2)
                  Set @P_VlrSubTri = @WFatParIte*@it_VlrSubTri
                  Set @P_VlrBasSbtRes = Round(@WFatParIte*@it_VlrBasSbtRes,2)
                  Set @P_VlrSbtRes = @WFatParIte*@it_VlrSbtRes
                  Set @P_VlrBasRecSbt = 0
                  Set @P_VlrRecSbt = 0
                  Set @P_VlrFcpSbtRec = 0

                  Set @P_VlrBasVerba  = Round(@WFatParIte*@it_VlrBasVerba,2)
                  Set @P_VlrVerba     = Round(@WFatParIte*@it_VlrVerba,2)
                  Set @P_VlrVrbVdr    = Round(@WFatParIte*@it_VlrVrbVdr,2)
                  Set @P_VlrVrbOpe    = Round(@WFatParIte*@it_VlrVrbOpe,2)
                  Set @P_VlrVrbSup    = Round(@WFatParIte*@it_VlrVrbSup,2)

                  Set @P_VlrBonificacao = Round(@WFatParIte*@it_VlrBonificacao,2)
                  Set @P_VlrDscBonDup = Round(@WFatParIte*@it_VlrDscBonDup,2)

                  Set @P_VlrIcmParDes = @WFatParIte*@it_VlrIcmParDes
                  Set @P_VlrIcmParRem = @WFatParIte*@it_VlrIcmParRem 
                  Set @P_VlrIcmFcpDes = @WFatParIte*@it_VlrIcmFcpDes
                  Set @P_VlrFcpIcm = @WFatParIte*@it_VlrFcpIcm
                  Set @P_VlrFcpSbt = @WFatParIte*@it_VlrFcpSbt
                  Set @P_VlrFcpSbtRet = @WFatParIte*@it_VlrFcpSbtRet 

                  -- garante fechamento de valores
                  Set @Acp_UndIte = @Acp_UndIte + @P_QtdPed + @P_QtdBon

                  if @Acp_UndIte = @it_QtdPed+@it_QtdBon -- ultimo item....
                    begin
                      Select @Acp_VlrBruIte    = IsNull(sum(IsNull(Vlr_BruItem,0)),0)
                           , @Acp_VlrTotIte    = IsNull(sum(IsNull(Vlr_TotItem,0)),0)
                           , @Acp_VlrLiqIte    = IsNull(sum(IsNull(Vlr_LiqItem,0)),0)

                           , @Acp_VlrDscBonRat = IsNull(sum(IsNull(Vlr_DscBonRat,0)),0)
                           , @Acp_VlrDespes    = IsNull(sum(IsNull(Vlr_DespRateada,0)),0)
                           , @Acp_VlrDspExt    = IsNull(sum(IsNull(Vlr_DspExt,0)),0)

                           , @Acp_VlrBasIpi    = IsNull(sum(IsNull(Vlr_Ipi,0)),0)
                           , @Acp_VlrIpi       = IsNull(sum(IsNull(Vlr_Ipi,0)),0)

                           , @Acp_VlrBasTri    = IsNull(sum(IsNull(Vlr_BasTri,0)),0)
                           , @Acp_VlrBasRepIcm = IsNull(sum(IsNull(Vlr_BasRepIcms,0)),0)
                           , @Acp_VlrRepIcm    = IsNull(sum(IsNull(Vlr_RepIcms,0)),0)
                           , @Acp_VlrBasIcmNor = IsNull(sum(IsNull(Vlr_BasIcmsNor,0)),0)
                           , @Acp_VlrIcmNor    = IsNull(sum(IsNull(Vlr_IcmsNor,0)),0)
                           , @Acp_VlrBasIcmTri = IsNull(sum(IsNull(Vlr_BasIcmsTri,0)),0)
                           , @Acp_VlrIcmTri    = IsNull(sum(IsNull(Vlr_IcmsTri,0)),0)
                           , @Acp_VlrIsento    = IsNull(sum(IsNull(Vlr_Isento,0)),0)
                           , @Acp_VlrOutros    = IsNull(sum(IsNull(Vlr_Outros,0)),0)

                           , @Acp_VlrBasDscTri = IsNull(sum(IsNull(Vlr_BasDscTri,0)),0)
                           , @Acp_VlrDscTri    = IsNull(sum(IsNull(Vlr_DscTri,0)),0)
                           , @Acp_VlrIcmDiferi = IsNull(sum(IsNull(Vlr_IcmDiferi,0)),0)
                           , @Acp_VlrIcmDesone = IsNull(sum(IsNull(Vlr_IcmsDeson,0)),0)
                           , @Acp_VlrDscCalSuf = IsNull(sum(IsNull(Vlr_DscCalSuframa,0)),0)

                           , @Acp_VlrPrdSubTri = IsNull(sum(IsNull(Vlr_PrdSubTri,0)),0)
                           , @Acp_VlrBasSubTri = IsNull(sum(IsNull(Vlr_BasSubsTrib,0)),0)
                           , @Acp_VlrSubTri    = IsNull(sum(IsNull(Vlr_SubsTrib,0)),0)
                           , @Acp_VlrBasSbtRes = IsNull(sum(IsNull(Vlr_BasSbtRes,0)),0)
                           , @Acp_VlrSbtRes    = IsNull(sum(IsNull(Vlr_SbtRes,0)),0)

                           , @Acp_VlrIcmParDes = IsNull(sum(IsNull(Vlr_IcmParDes,0)),0)
                           , @Acp_VlrIcmParRem = IsNull(sum(IsNull(Vlr_IcmParRem,0)),0)
                           , @Acp_VlrIcmFcpDes = IsNull(sum(IsNull(Vlr_IcmFcpDes,0)),0)
                           , @Acp_VlrFcpIcm    = IsNull(sum(IsNull(Vlr_FcpIcm,0)),0)
                           , @Acp_VlrFcpSbt    = IsNull(sum(IsNull(Vlr_FcpSbt,0)),0)
                           , @Acp_VlrFcpSbtRet = IsNull(sum(IsNull(Vlr_FcpSbtRet,0)),0)

                           , @Acp_VlrBasVerba  = IsNull(sum(IsNull(Vlr_BasVerba,0)),0)
                           , @Acp_VlrVerba     = IsNull(sum(IsNull(Vlr_Verba,0)),0)
                           , @Acp_VlrVrbVdr    = IsNull(sum(IsNull(Vlr_VrbVdr,0)),0)
                           , @Acp_VlrVrbOpe    = IsNull(sum(IsNull(Vlr_VrbOpe,0)),0)
                           , @Acp_VlrVrbSup    = IsNull(sum(IsNull(Vlr_VrbSup,0)),0)

                           --, sum(Vlr_Bonificacao)
                           , @Acp_VlrDscBonDup = IsNull(sum(IsNull(Vlr_DscBonDup,0)),0)
                           
                        From NFSIT 
                       Where Cod_Estabe = @CodEstabe 
                         And Ser_Nota = @SerNfsRet 
                         And Num_Nota = @NumNfsRet
                         And Cod_Produto = @it_CodPrd  
						 And Cod_LotPdv = @it_CodLot
						 And Tip_Sai  = @it_TipSai

					  Set @P_VlrBruIte = @it_VlrBruIte - @Acp_VlrBruIte
                      Set @P_VlrTotIte = @it_VlrTotIte - @Acp_VlrTotIte
                      Set @P_VlrLiqIte = @it_VlrLiqIte - @Acp_VlrLiqIte
                      Set @P_VlrDscBonRat = @it_VlrDscBonRat - @Acp_VlrDscBonRat 
                      Set @P_VlrDespes = @it_VlrDespes - @Acp_VlrDespes 
                      Set @P_VlrDspExt = @it_VlrDspExt - @Acp_VlrDspExt 
                      Set @P_VlrBasTri = @it_VlrBasTri - @Acp_VlrBasTri
                      Set @P_VlrBasRepIcm = @it_VlrBasRepIcm - @Acp_VlrBasRepIcm
                      Set @P_VlrRepIcm = @it_VlrRepIcm - @Acp_VlrRepIcm
                      Set @P_VlrBasIcmNor = @it_VlrBasIcmNor - @Acp_VlrBasIcmNor
                      Set @P_VlrIcmNor = @it_VlrIcmNor - @Acp_VlrIcmNor
                      Set @P_VlrBasIcmTri = @it_VlrBasIcmTri - @Acp_VlrBasIcmTri
                      Set @P_VlrIcmTri = @it_VlrIcmTri - @Acp_VlrIcmTri
                      Set @P_VlrIsento = @it_VlrIsento - @Acp_VlrIsento
                      Set @P_VlrOutros = @it_VlrOutros - @Acp_VlrOutros
                      Set @P_VlrBasDscTri = @it_VlrBasDscTri - @Acp_VlrBasDscTri 
                      Set @P_VlrDscTri = @it_VlrDscTri - @Acp_VlrDscTri 
                      Set @P_VlrIcmDiferi = @it_VlrIcmDiferi - @Acp_VlrIcmDiferi
                      Set @P_VlrIcmDesone = @it_VlrIcmDesone - @Acp_VlrIcmDesone
                      Set @P_VlrDscCalSuframa = @it_VlrDscCalSuframa - @Acp_VlrDscCalSuf
                      Set @P_VlrPrdSubTri = @it_VlrPrdSubTri - @Acp_VlrPrdSubTri
                      Set @P_VlrBasSubTri = @it_VlrBasSubTri - @Acp_VlrBasSubTri
                      Set @P_VlrSubTri = @it_VlrSubTri - @Acp_VlrSubTri
                      Set @P_VlrBasSbtRes = @it_VlrBasSbtRes - @Acp_VlrBasSbtRes
                      Set @P_VlrSbtRes = @it_VlrSbtRes - @Acp_VlrSbtRes

                      Set @P_VlrIcmParDes = @it_VlrIcmParDes - @Acp_VlrIcmParDes
                      Set @P_VlrIcmParRem = @it_VlrIcmParRem - @Acp_VlrIcmParRem
                      Set @P_VlrIcmFcpDes = @it_VlrIcmFcpDes - @Acp_VlrIcmFcpDes
                      Set @P_VlrFcpIcm = @it_VlrFcpIcm - @Acp_VlrFcpIcm
                      Set @P_VlrFcpSbt = @it_VlrFcpSbt - @Acp_VlrFcpSbt
                      Set @P_VlrFcpSbtRet = @it_VlrFcpSbtRet - @Acp_VlrFcpSbtRet

                      Set @P_VlrBasVerba  = @it_VlrBasVerba - @Acp_VlrBasVerba
                      Set @P_VlrVerba     = @it_VlrVerba    - @Acp_VlrVerba
                      Set @P_VlrVrbVdr    = @it_VlrVrbVdr   - @Acp_VlrVrbVdr
                      Set @P_VlrVrbOpe    = @it_VlrVrbOpe   - @Acp_VlrVrbOpe
                      Set @P_VlrVrbSup    = @it_VlrVrbSup   - @Acp_VlrVrbSup

                      Set @P_VlrBonificacao = @it_VlrBonificacao - @Acp_VlrBonificacao
                      Set @P_VlrDscBonDup = @it_VlrDscBonDup - @Acp_VlrDscBonDup

                      Set @P_VlrBasIpi = @it_VlrBasIpi - @Acp_VlrBasIpi
                      Set @P_VlrIpi = @it_VlrIpi - @Acp_VlrIpi
                    end

                  -- grava item da nota
                  if @PTipRetImp = 'R'
                    begin
                      if Charindex(@it_CodCst,';10;30;70;') > 0
                        begin
                          if @P_VlrIcmTri > 0
                            if @it_PerRedBasCalIcm > 0
                              Set @it_CodCst = '20'    -- tributacao com reducao
                            else
                              Set @it_CodCst = '00'    -- tributacao integral
                          else
                            Set @it_CodCst = '41'    -- nao tributada
                        end
                      if @it_CodCst <> '60'
                        Set @P_CodCfo = @WCodCfoNor

                      Set @P_VlrBasRecSbt = @P_VlrBasSubTri
                      Set @P_VlrRecSbt = @P_VlrSubTri
                      if @P_VlrSubTri >= @P_VlrDscTri
                        Set @P_VlrRecSbt = @P_VlrSubTri - @P_VlrDscTri                 
                      Set @P_VlrBasSubTri = 0
                      Set @P_VlrSubTri = 0

					  Set @P_VlrFcpSbtRec = @P_VlrFcpSbt
					  Set @P_VlrFcpSbt = 0

					  Set @P_VlrBasDscTri = 0
					  Set @it_PerDscTri = 0
                      Set @P_VlrDscTri = 0
                    end

                  -- recalcula preco unitario a ser impresso na NF
                  if @it_FlgPrcUniDsc = 1
                    Set @it_PrcUniImpFat = @it_CPrcUni*@it_FatCnvImpFat

                  -- verifica CFOP de genericos e similares em op.internas: alterado verifica CFOP para operações com debito presumido
--                  if (@WFlgOpeInt = 1) and (@rt_FlgUsaCfoSbtSaiIntGenSim = 1) and
--                     (CHARINDEX(@pr_CodGrpPrc,';G;S;') > 0) and (@P_CodCfo = @WCodCfoNor)
--                    Set @P_CodCfo = @WCodCfoSbt   
                  if (@rt_FlgUsaCfoSbtSaiIntGenSim = 1) and
                     (@it_FlgUsaDebPresum = 1) and (@it_AlqIcmPresum > 0) and (@it_AlqIcmPresum <> @it_AlqIcm) 
                    Set @P_CodCfo = @WCodCfoSbt   

                  -- verifica CFOP contribuinte substituto (5403), substituido (5405)
--                  if Charindex(@PEst,';PE;SC;RS;') > 0
--                    begin
--                      if (@P_CodCfo = 5403) or (@P_CodCfo = 5405)
--                        if Charindex(@it_CodCst,';10;30;70;') > 0
--                          Set @P_CodCfo = 5403
--                        else
--                          Set @P_CodCfo = 5405
--                    end

                  if (@rt_FlgConsumFin = 0) and (@it_CodCst = '60')
                    if @WFlgOpeInt = 1
                      begin
                        if (@P_CodCfo <> @to_CodCfoSubstituidoInt) and (@to_CodCfoSubstituidoInt > 0)
                          Set @P_CodCfo = @to_CodCfoSubstituidoInt
                      end
                    else
                    if @WFlgOpeInt = 0
                      begin
                        if (@P_CodCfo <> @to_CodCfoSubstituidoExt) and (@to_CodCfoSubstituidoExt > 0)
                          Set @P_CodCfo = @to_CodCfoSubstituidoExt
                      end
                 
                  --ajusta ressarcimento ST
                  if (@it_CodCst = '60') and (@P_VlrSubTri > 0)
                    begin
                      Set @P_VlrBasSbtRes = @P_VlrBasSubTri 
                      Set @P_VlrSbtRes = @P_VlrSubTri
                      Set @P_VlrBasSubTri = 0 
                      Set @P_VlrSubTri = 0 

                      Set @P_VlrFcpSbtRet = @P_VlrFcpSbt
					  Set @P_VlrFcpSbt = 0
                    end

                  -- pis/cofins --------------------------------------------------------------------------------------------
                  Set @WVlrBasPisCof = @P_VlrBasTri -- @it_VlrBasTri
				  if @P_VlrSbtRes > 0
                    Set @WVlrBasPisCof = Round(@WVlrBasPisCof+@P_VlrSbtRes,2) 

                  -- normaliza CFOP de bonificacao antes de gravar NFSIT
                  -- somente quando a bonificacao não é rateada como desconto para TODOS os itens (inclusive o item bonificado)
                  -- o item pode ter sido "bonificado" rateando seu valor para outros itens: neste caso o cfop do item não é de bonificação
                  if ((@it_TipSai = 'B') and (@cb_TipRatBon <> 'T')) or (@cb_TipSaiPdv = 'B')
                    Set @P_CodCfo = @WCodCfoBon   

                  -- ipi
                  if @pm_FlgIncIpiCalPis = 1  
                    Set @WVlrBasPisCof = @WVlrBasPisCof + @P_VlrIpi

                  -- exclui icms destacado  
                  if @pm_FlgExcIcmCalPis = 1
                    Set @WVlrBasPisCof = @WVlrBasPisCof - @P_VlrIcmNor

                  Exec PR_CalculaPisCofins @CodEstabe, @to_FlgCalPisCof, 'S', @em_CodTipLuc, @Date, @P_CodCfo, @cl_CodRamAtv, @pr_CodClaFis, @it_TipAux, @WVlrBasPisCof, 
                                           @P_CstPis output, @P_VlrBasPis output, @P_AlqPis output, @P_VlrPis output,
                                           @P_CstCof output, @P_VlrBasCof output, @P_AlqCof output, @P_VlrCof output, @P_ObsNf output
                  if (@@error <> 0)
                    begin
                      if @@trancount > 0
                        Rollback Transaction
                      Return
                    end

                  -- vlr. do desconto do item
                  if @P_VlrBruIte > @P_VlrTotIte
                    Set @P_VlrDscIte = @P_VlrBruIte - @P_VlrTotIte
                  else
                    Set @P_VlrDscIte = 0
                    
                  -- desconto do cabecalho rateado para o item  (ja foi calculado acima)
                    
                  Set @P_VlrLiqVenIte = @P_VlrTotIte - @P_VlrDscRat - @P_VlrDscBonRat - @P_VlrRepIcm  - @P_VlrDscTri

                  ---- recalcula verbas de bonfificações para clientes
                  Set @P_PerVrbPar = 0
                  Set @P_VlrVrbPar = 0
                  Set @P_PerVrbBon = 0
                  Set @P_VlrVrbBon = 0
                  if (@cb_FlgGerRetBon = 1) and (@cb_CodCli > 0)
                    begin
                      -- bonificacao de produto 
                      -- obtem quantidade total do produto no pedido
                      Set @WQtdPrdVrb = IsNull((Select sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0))
                                                  From PDVIT 
                                                 Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
                                                   And Cod_Produto = @it_CodPrd 
                                                   And Qtd_Pedido > 0),0)

                      Set @WPerRetBon = IsNull((Select top 1 it.Per_RetBon 
                                                  From PRBCB cb Inner Join PRBIT it on cb.Id_PRBCB = it.Id_PRBCB
                                                 Where @PdatEmi between cb.Dat_Ini and cb.Dat_Fim
                                                   And cb.Cod_Produt = @it_CodPrd
                                                   And Qtd_Minima <= @WQtdPrdVrb
                                                 Order by it.Qtd_Minima desc),0)
                                            
                      Set @P_PerVrbBon = @WPerRetBon
                      Set @P_VlrVrbBon = Round(@P_VlrLiqVenIte*@WPerRetBon/100,2,1)
                  
                      -- bonificacao de parceria
                      Set @WPerRetBon = IsNull((Select top 1 Per_RetBon
                                                From ((Select top 1 '3' as Num_Ord, cb.Per_RetBon, cb.Numero
                                                         From PARCE cb
                                                        Where cb.Status = '0'
                                                          And cb.CodCli = @cb_CodCli
                                                        Order by cb.Numero desc) 
                                                      UNION
                                                      (Select top 1 '2' as Num_Ord, it.Per_RetBon, cb.Numero
                                                         From PARCE cb Inner Join 
                                                              PARBF it on (cb.Numero = it.Cod_Parcer) Inner Join
                                                              PRODU pr on (it.Cod_Fabric = pr.Cod_Fabricante) 
                                                        Where cb.Status = '0'
                                                          And cb.CodCli = @cb_CodCli
                                                          And pr.Codigo = @it_CodPrd
                                                        Order by cb.Numero desc) 
                                                      UNION
                                                      (Select top 1 '1' as Num_Ord, it.Per_RetBon, cb.Numero
                                                         From PARCE cb Inner Join 
                                                              PARBP it on (cb.Numero = it.Cod_Parcer)
                                                        Where cb.Status = '0'
                                                          And cb.CodCli = @cb_CodCli
                                                          And it.Cod_Produt = @it_CodPrd
                                                        Order by cb.Numero desc)) x
                                                Order by Num_Ord),0)                    
                      Set @P_PerVrbPar = @WPerRetBon
                      Set @P_VlrVrbPar = Round(@P_VlrLiqVenIte*@WPerRetBon/100,2,1)
                    end

                  -- calcula comissao do item
                  Set @WPerRetBon = @P_PerVrbBon + @P_PerVrbPar
                  Set @WCodPrm = ISNULL(@it_CodPrm,0)+ISNULL(@it_FlgPolPrm,0)

                  if ((@it_TipSai = 'B') and (@cb_TipRatBon <> 'T')) or (@cb_TipSaiPdv = 'B')
                    Set @WTipSai = 'B'
                  else  
                    Set @WTipSai = ''
                  
                  Set @WVlrBasComiss = @P_VlrTotIte - @P_VlrRepIcm - @P_VlrDscRat - @P_VlrDscTri

                  Set @it_PerLucBru = 0
                  EXEC PR_CalcComisItemSaida @CodEstabe, @CodPed, @it_CodPrd, @WTipSai, @cb_CodCli, @PDatEmi, @WVlrBasComiss,
                                             @it_CPrcUni, @it_PrcTab, @it_FlgPrcUniDsc, @it_FlgBlqInfPar,
                                             @WCodPrm, @P_PerDsc, @it_CPerDscIte, @cb_PerDscCom, @PPerDscFin, @PTipVct, @PQtdPrzMed,
                                             @PPerComVnd, @WCodTabComVdr, @PPerComOpe, @WCodTabComOpe, @cb_PerComSup, @cb_PerComGer, @cb_PerComSupOpe, @cb_PerComGerOpe, 
                                             @it_IdPolCom, @WPerRetBon, @it_PerLucBru, @P_FlgComNor output, 
                                             @P_PerComOpe output, @P_PerComVnd output, @P_PerComSup output, @P_PerComGer output, @P_PerComSupOpe output, @P_PerComGerOpe output, 
                                             @P_VlrComOpe output, @P_VlrComVnd output, @P_VlrComSup output, @P_VlrComGer output, @P_VlrComSupOpe output, @P_VlrComGerOpe output
                  if (@@error <> 0)
                    begin
                      if @@trancount > 0
                        Rollback Transaction
                      Return
                    end

                  -- calcula comissao de entrega de venda
                  if ((@it_TipSai = 'B') and (@cb_TipRatBon <> 'T')) or (@cb_TipSaiPdv = 'B')
                    Set @WTipSai = 'B'
                  else  
                    Set @WTipSai = ''

                  Set @P_PerComTra = 0
                  Set @P_VlrComTra = 0
                  if (@tr_Pessoa = 'F') and (@TipNfs = 'V') and (@WTipSai <> 'B') and (@it_TipSai <> 'B')
                    begin
                      Select @P_PerComTra = Isnull(Per_ComEnt,0) From PRXES Where Cod_Estabe = @CodEstabe and Cod_Produt = @it_CodPrd
                      Set @P_VlrComTra = @WVlrBasComiss * @P_PerComTra/100
                    end

                  -- retira a quantidade solicitada (em PRODU)
                  EXEC PR_DecrementaSaldoSolicitado_PRODU @CodEstabe, 'P', @cb_StaPdv1, @cb_StaPdv2, @cb_TipBlq, @it_CodPrd, @it_CodPrm, @P_QtdPra, @P_QtdDep, 0
                  if (@@error <> 0)
                    begin
                      if @@trancount > 0
                        Rollback Transaction
                      Return
                    end

                  -- grava movimento (saida: sinal negativo)
                  Set @WQtdMov = (@P_QtdPed + @P_QtdBon) * (-1)
                  if @it_CodPrm > 0
                    begin
                      EXEC PR_GravaPrmMv @CodEstabe, @it_CodPrm, @it_CodPrd, @PDatEmi, @TipNfs, @SerNfsRet, @NumNfsRet, @WQtdMov
                      if (@@error <> 0)
                        begin
                          if @@trancount > 0
                            Rollback Transaction
                          Return
                        end
                    end

                  -- grava estatisticas relativas ao item -----------------------------------------------------------------
				  -- executado após gravaçãodo ítem
                  Set @WQtdMov = @P_QtdPed + @P_QtdBon

                  if @cb_CodCli > 0
                    begin
                      if ((@P_VlrVrbPar <> 0) or (@P_VlrVrbBon <> 0)) and (@TipNfs = 'V') and (@it_TipSai <> 'B')
                        begin
                          Exec PR_AtualizaSaldoVBCSD @CodEstabe, @cb_CodCli, @PDatEmi, 0, @it_CodPrd, @P_CodLot, 'S', @TipNfs, @SerNfsRet, @NumNfsRet, @P_VlrVrbPar, @P_VlrVrbBon, '', 'SISTEMA'

                          if (@@error <> 0)
                            begin
                              if @@trancount > 0
                                Rollback Transaction
                              Return
                            end 
                        end
                    end

                  -- grava movimento relativo a remessa(somente) em consignação: CFOP: 5917 ou 6917 
                  if (@cb_IdConsig > 0) and (@cb_NumSeqCtr > 0) and (dbo.FN_CfopConsigValido(@CodCfo) = 1) 
                    begin
                      if dbo.FN_TipoNFConsig(@CodCfo) = 'R'
                        Set @WCodTipSaiCng = 'NFR'
                      else
                        Set @WCodTipSaiCng = 'NFF'

                      Exec PR_GravaMovimeCNGMV @CodEstabe, @cb_IdConsig, @it_CodPrd, @P_CodLot,
                                               @PDatEmi, 'S', @WCodTipSaiCng, @SerNfsRet, @NumNfsRet, @it_TipSai, 'F', 
                                               @WQtdMov, @it_CPrcUni
                      if (@@error <> 0)
                        begin
                          if @@trancount > 0
                            Rollback Transaction
                          Return
                        end
                    end

                  -- verbas
                  Set @pc_Controle_Saldo = ''
                  if Exists (Select 1 From POCOM Where Id_PolCom = @it_IdPolCom)
                    Select @pc_Controle_Saldo = pc.Controle_Saldo, 
                           @pc_FlgAcuVrbPos = pc.Flg_AcuVrbPos,
                           @pc_FlgAcuVrbNeg = pc.Flg_AcuVrbNeg,
                           @pc_FlgCtrPdvVrbVdr = pc.Flg_CtrPdvVrbVdr,
                           @pc_FlgCtrPdvVrbOpe = pc.Flg_CtrPdvVrbOpe
                      From POCOM pc
                     Where pc.Id_PolCOm = @it_IdPolCom

                  if ((@it_TipSai = 'B') and (@cb_TipRatBon <> '')) or (@cb_TipSaiPdv = 'B')
                    Set @WTipSai = 'B'
                  else  
                    Set @WTipSai = ''

                  if ( (@pc_Controle_Saldo = 'V') or (@pc_Controle_Saldo = 'F') ) and
                       (@P_VlrVerba <> 0                                    ) and
                       ( ( (@TipNfs = 'V') and (@it_TipSai <> 'B') ) or
                         ( @WTipSai = 'B')                                      )
                    begin

                      if (@P_VlrVrbVdr <> 0) and (IsNull(@cb_CodVdr, 0) > 0)
                    	begin
                    	  if (@pc_FlgCtrPdvVrbVdr = 1) and
                             ( ((@pc_FlgAcuVrbPos = 1) and (@P_VlrVrbVdr > 0)) or 
                               ((@pc_FlgAcuVrbNeg = 1) and (@P_VlrVrbVdr < 0)) )  
                            begin							  
                              if @pc_Controle_Saldo = 'V' -- Vendedor/Operador
                                Exec PR_AtualizaSaldoVBSLD @CodEstabe, @cb_CodVdr,             @PDatEmi, 0, @it_CodPrd, @P_CodLot, @it_TipSai, 'S', @TipNfs, @SerNfsRet, @NumNfsRet, @P_VlrVrbVdr, '', 'SISTEMA'
                              else
                                Exec PR_AtualizaSaldoVBFSL @CodEstabe, @cb_CodVdr, @it_CodFab, @PDatEmi, 0, @it_CodPrd, @P_CodLot, @it_TipSai, 'S', @TipNfs, @SerNfsRet, @NumNfsRet, @P_VlrVrbVdr, '', 'SISTEMA'
                    	      if (@@error <> 0)
                    		    begin
                                   if @@trancount > 0
                      		         Rollback Transaction
                    		       Return
                    		    end
                            end
                    	end
                    
                      if (@P_VlrVrbOpe <> 0) and (IsNull(@cb_CodOpe, 0) > 0)
                    	begin
                    	  if (@pc_FlgCtrPdvVrbOpe = 1) and 
                             ( ((@pc_FlgAcuVrbPos = 1) and (@P_VlrVrbOpe > 0)) or
                               ((@pc_FlgAcuVrbNeg = 1) and (@P_VlrVrbOpe < 0)) )
                            begin							  
                              if @pc_Controle_Saldo = 'V' -- Vendedor/Operador
                                Exec PR_AtualizaSaldoVBSLD @CodEstabe, @cb_CodOpe,             @PDatEmi, 0, @it_CodPrd, @P_CodLot, @it_TipSai, 'S', @TipNfs, @SerNfsRet, @NumNfsRet, @P_VlrVrbOpe, '', 'SISTEMA'
                              else
                                Exec PR_AtualizaSaldoVBFSL @CodEstabe, @cb_CodOpe, @it_CodFab, @PDatEmi, 0, @it_CodPrd, @P_CodLot, @it_TipSai, 'S', @TipNfs, @SerNfsRet, @NumNfsRet, @P_VlrVrbOpe, '', 'SISTEMA'
                              if (@@error <> 0)
                                begin
                                  if @@trancount > 0
                                    Rollback Transaction
                                  Return
                                end
                    		end
                    	end
                    
                      if (@P_VlrVrbSup <> 0) and (IsNull(@cb_CodSup, 0) > 0)
                        begin
                          if (@pc_FlgCtrPdvVrbVdr = 1) or (@pc_FlgCtrPdvVrbOpe = 1) 
                            begin
                    	      if ( (@pc_FlgAcuVrbPos = 1) and (@P_VlrVrbSup > 0) ) or
                                 ( (@pc_FlgAcuVrbNeg = 1) and (@P_VlrVrbSup < 0) )
                                begin
                                  Exec PR_AtualizaSaldoVBSSD @CodEstabe, @cb_CodSup, @PDatEmi, 0, @it_CodPrd, @P_CodLot, @it_TipSai, 'S', @TipNfs, @SerNfsRet, @NumNfsRet, @P_VlrVrbSup, '', 'SISTEMA'
                                  if (@@error <> 0)
                                    begin
                                      if @@trancount > 0
                                        Rollback Transaction
                                      Return
                                    end
                                end
                            end
                    	end

                    end  -- if (@P_VlrVerba <> 0)


                  -- verba fornecedor   
                  Set @WVlrBru = Round(@P_QtdPed*@it_PrcFab,2)
                  Set @WVlrEdi = Round(@P_QtdPed*@it_PrcUniPde*(1-@it_PerDscPde/100),2)
                  if @WVlrEdi > 0
                    begin
                      Set @WVlrMov = @WVlrBru - @WVlrEdi
                      Set @WCodFor = IsNull((Select fb.Cod_ForPref From PRODU pr Inner Join FBXES fb on pr.Cod_Fabricante = fb.Cod_FAbric and @CodEstabe = fb.Cod_Estabe
                                              Where pr.Codigo = @it_CodPrd),0)
                      if (@WCodFor > 0) and (@WVlrMov > 0) and (@TipNfs = 'V') and (@it_TipSai <> 'B') --(@it_TipSai <> 'B')
                        begin
                          Exec PR_AtualizaSaldoVBFSD @CodEstabe, @WCodFor, @PDatEmi, 0, @it_CodPrd, @P_CodLot, 'S', @TipNfs, @SerNfsRet, @NumNfsRet, @WVlrMov, 'SAIDA NF', 'SISTEMA'
                          if (@@error <> 0)
                            begin
                              if @@trancount > 0
                                Rollback Transaction
                              Return
                            end
                        end
                    end
                 
                  -- garante compatibilidade de valores  
                  -- @P_VlrTotIte - @P_VlrRepIcm - @P_VlrDscRat - @P_VlrDscBonRat - @P_VlrDscTri + desp.rateada
                  
                  if Round(@P_VlrBasTri,2) <> Round(@P_VlrTotIte-@P_VlrRepIcm-@P_VlrDscRat-@P_VlrDscBonRat-@P_VlrDscTri+@P_VlrDespes+@P_VlrDspExt,2)
                    Set @P_VlrBasTri = Round(@P_VlrTotIte-@P_VlrRepIcm-@P_VlrDscRat-@P_VlrDscBonRat-@P_VlrDscTri+@P_VlrDespes+@P_VlrDspExt,2) 
                 
                  if Round(@P_VlrBasIcmNor,2) > Round(@P_VlrBasTri,2)
                    begin
                     Set @P_VlrBasIcmNor = Round(@P_VlrBasTri,2)
                     Set @P_VlrIcmNor = @P_VlrBasIcmNor*@it_AlqIcm/100
                    end
                   
                  if Round(@P_VlrBasIcmTri,2) > Round(@P_VlrBasTri,2)
                    begin
                     Set @P_VlrBasIcmTri = Round(@P_VlrBasTri,2)
                     Set @P_VlrIcmTri = @P_VlrBasIcmTri*@it_AlqIcm/100
                    end
                   
                  if Round(@P_VlrIsento,2) > Round(@P_VlrBasTri,2)
                    begin
                     Set @P_VlrIsento = Round(@P_VlrBasTri,2)
                    end

                  if Round(@P_VlrOutros,2) > Round(@P_VlrBasTri,2)  -- + ipi, frete, seguro. ouras despesa
                    begin
                     Set @P_VlrOutros = Round(@P_VlrBasTri,2)
                    end

                  if Round(@P_QtdImpFat*100,0) <> Round((Cast(@P_QtdPed+@P_QtdBon as numeric(18,4))/@it_FatCnvImpFat)*100,0) 
                    Set @P_QtdImpFat = Cast(@P_QtdPed+@P_QtdBon as numeric(18,4))/@it_FatCnvImpFat
                  if Round(@it_PrcUniImpFat*10000,0) <> Round(@it_CPrcUni*@it_FatCnvImpFat*10000,0)
                    Set @it_PrcUniImpFat = @it_CPrcUni*@it_FatCnvImpFat
                    
                  --volumes Str_VolEmb varchar(50)
                  Declare @NumVolAnt int = 0,
                          @NumVol int = 0,
                          @StrVol varchar(50) = ''

                  if Exists(Select top 1 * From PDVLT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Qtd_Lote > 0)
				    begin
                      Set @StrVol = 'Volume: '
                      while Exists(Select distinct Num_Vol
                                     From PDVLT
                                    Where Cod_Estabe = @CodEstabe 
                                     And Cod_Pedido = @CodPed
                                     And Cod_Produt = @it_CodPrd
                                     And Cod_Lote = @P_CodLot
                                     And Num_Vol > @NumVolAnt)
                        begin
                          Select top 1 @NumVol = Num_Vol
                            From PDVLT
                           Where Cod_Estabe = @CodEstabe 
                             And Cod_Pedido = @CodPed
                             And Cod_Produt = @it_CodPrd
                             And Cod_Lote = @P_CodLot
                             And Num_Vol > @NumVolAnt
                           Order by Num_Vol

                          if @StrVol <> 'Volume: '
                            Set @StrVol = @StrVol + ','
                          Set @StrVol = @StrVol + CAST(@NumVol as varchar)
                          Set @NumVolAnt = @NumVol
                        end
					end

                  Set @P_NumSeqIte = @P_NumSeqIte + 1

                  Insert into NFSIT
                    (Cod_Estabe, Ser_Nota, Num_Nota, Cod_Produto, Cod_Lote, Num_SeqIte, Cod_LotPdv, Tip_Sai)
                    Values
                    (@CodEstabe, @SerNfsRet, @NumNfsRet, @it_CodPrd, @P_CodLot, @P_NumSeqIte, @it_CodLot, @it_TipSai)
                  if (@@error <> 0)
                    begin
                      if @@trancount > 0
                        Rollback Transaction
                      Return
                    end

                  Update NFSIT
                     Set Qtd_Produto = @P_QtdPed, 
                         Qtd_Bonificacao = @P_QtdBon,  

                         Flg_DscItePdv = @it_FlgPrcUniDsc, 
                         Per_Descon = @P_PerDsc,   -- desconto embutido no preço
                         Prc_UniPdv = @it_PrcUni, 
                         Per_DscPdv = @it_PerDsc, 

                         Per_Desconto = @it_CPerDscIte,
                         Prc_Unitario = @it_CPrcUni,        -- preço com desconto embutido
                         Prc_UniImpFat = @it_PrcUniImpFat,  -- @it_CPrcUni*Fat_CnvImpFat

                         Prc_UniSemAcrIcm = @it_PrcUniSemAcrIcm, 
                         Flg_PrcUniAcrIcm = @it_FlgPrcUniAcrIcm, 
                         Prc_UniComAcrIcm = @it_PrcUniComAcrIcm, 
                         Prc_Tabela = @it_PrcTab, 
                         Per_DescontoFin = @P_PerDscFin, 
                         Cod_Promocao = @it_CodPrm, 

                         Qtd_Pra = @P_QtdPra, 
                         Qtd_Dep = @P_QtdDep,

                         Vlr_DscBonRat = @P_VlrDscBonRat, 
                         Vlr_CusIte = @P_PrcCusMed, 
                         Vlr_CusComIte = @P_PrcCusCom, 
                         Flg_ComisNormal = @P_FlgComNor, 
                         Cod_GrpPrc = @pr_CodGrpPrc, 
                         Fat_CnvImpFat = @it_FatCnvImpFat, 
                         Qtd_ImpFat = @P_QtdImpFat, 
                         Des_UnvImpFat = @it_DesUnvImpFat, 
                         Des_AprImpFat = @it_DesAprImpFat, 

                         Cod_PrjPde = @it_CodPrjPde, 
                         Prc_UniPde = @it_PrcUniPde, 
                         Per_DscPde = @it_PerDscPde, 
                         Num_SeqPdc = @it_NumSeqPdc, 

                         Id_PolCom = @it_IdPolCom,
                         Flg_PolPrm = @it_FlgPolPrm, 
                         Prc_CusMinComMarkup = @it_PrcCusMinComMarkup,  
                         Cod_KitPrm = @it_CodKitPrm, 
                         Prc_PolCom = @it_PrcPolCom, 
                         Per_DscPolCom = @it_PerDscPolCom, 

                         Vlr_DespRateada = @P_VlrDespes, 

                         -- campos calculados em PR_CalcTributNFSIT
                         Tip_Aux = @it_TipAux,  
                         Flg_BlqDsc = @it_FlgBlqDsc, 
                         Flg_BlqInfPar = @it_FlgBlqInfPar, 
                         Cod_Cfo = @P_CodCfo, 
                         Ctrl_Tributacao = @it_CodCst, 
                         Cod_CSOSN = @it_CodCsosn, 
                         Cod_ClaTri = @it_CodClaTri, 
                         Prc_TabBru = @it_PrcTabBru, 
                         Prc_Fabric = @it_PrcFab, 
                         Prc_MaxCon = @it_PrcMax, 
                         Prc_RefFpb = @it_PrcRefFpb, 

                         Vlr_DescRateado = @P_VlrDscRat, 
                         Vlr_BasTri = @P_VlrBasTri, 
                         Cod_ModBasCalIcm = @it_CodModBasCalIcm,
                         Alq_Icms = @it_AlqIcm, 
                         Per_RedBasCalIcm = @it_PerRedBasCalIcm, 
                         Vlr_BasIcmsNor = @P_VlrBasIcmNor, 
                         Vlr_IcmsNor = @P_VlrIcmNor,
                         Vlr_BasRepIcms = @P_VlrBasRepIcm, 
                         Per_RepIcms = @it_PerRepIcm,
                         Vlr_RepIcms = @P_VlrRepIcm,  
                         Vlr_PrdSubTri = @P_VlrPrdSubTri, 
                         Cod_ModBasCalIcmSbt = @it_CodModBasCalIcmSbt, 
                         Alq_IcmSbt = @it_AlqIcmSbt, 
                         Alq_AgrSbt = @it_AlqAgrSbt,
                         Per_RedBasCalIcmSbt = @it_PerRedBasCalIcmSbt, 
                         Vlr_BasSubsTrib = @P_VlrBasSubTri, 
                         Vlr_SubsTrib = @P_VlrSubTri, 
                         Vlr_BasSbtRes = @P_VlrBasSbtRes, 
                         Vlr_SbtRes = @P_VlrSbtRes, 
                         Vlr_BasDscTri = @P_VlrBasDscTri, 
                         Per_DscTri = @it_PerDscTri, 
                         Vlr_DscTri = @P_VlrDscTri, 
                         Vlr_BasRecSbt = @P_VlrBasRecSbt, 
                         Vlr_RecSbt = @P_VlrRecSbt, 
                         Vlr_BasIcmsTri = @P_VlrBasIcmTri, 
                         Vlr_IcmsTri = @P_VlrIcmTri, 
                         Vlr_Isento = @P_VlrIsento, 
                         Vlr_Outros = @P_VlrOutros, 
                         Vlr_DspExt = @P_VlrDspExt, 

                         CST_Pis = @P_CstPis, 
                         Vlr_BasPis = @P_VlrBasPis, 
                         Alq_Pis = @P_AlqPis, 
                         Vlr_Pis = @P_VlrPis, 
                         CST_Cofins = @P_CstCof, 
                         Vlr_BasCofins = @P_VlrBasCof, 
                         Alq_Cofins = @P_AlqCof, 
                         Vlr_Cofins = @P_VlrCof, 

                         Obs_Nf = @P_ObsNf, 
                         Alq_IntIcmDes = @it_AlqIntIcmDes, 
                         Per_PrvParIcm = @it_PerPrvParIcm, 
                         Vlr_IcmParDes = @P_VlrIcmParDes, 
                         Vlr_IcmParRem = @P_VlrIcmParRem, 
                         Vlr_IcmsDeson = @P_VlrIcmDesone, 
                         Cod_MtvIcmsDeson = @it_CodMtvIcmDesone, 
                         Flg_IncFis = @P_FlgIncFis,
                         Vlr_DscCalSuframa = @P_VlrDscCalSuframa,
                         Flg_UsaDebPresum = @it_FlgUsaDebPresum, 
                         Alq_IcmPresum = @it_AlqIcmPresum,
                         Per_AcrAlqIntFcp = @it_PerAcrAlqIntFcp, 
                         Vlr_IcmFcpDes = @P_VlrIcmFcpDes, 
                         Alq_FcpIcm = @it_AlqFcpIcm, 
                         Vlr_FcpIcm = @P_VlrFcpIcm,
                         Alq_FcpSbt =  @it_AlqFcpSbt, 
                         Vlr_FcpSbt = @P_VlrFcpSbt, 
                         Alq_FcpSbtRet = @it_AlqFcpSbtRet, 
                         Vlr_FcpSbtRet = @P_VlrFcpSbtRet, 
                         Per_IcmDiferi = @it_PerIcmDiferi, 
                         Vlr_IcmDiferi = @P_VlrIcmDiferi,

                         -- ??? :
                         Vlr_FcpSbtRec = @P_VlrFcpSbtRec, 
                         Vlr_SubsTribEmb = 0, 

						 Cod_OriMer = @it_CodOriMer,
						 Vlr_BasIpi = @P_VlrBasIpi,
						 Alq_Ipi = @it_AlqIpi,
                         Vlr_Ipi = @P_VlrIpi, 
						 CST_Ipi = @it_CstIpi,
                         Cod_EnqIpi = @it_CodEnqIpi,

                         Per_ComTlmkt = @P_PerComOpe, 
                         Vlr_ComTlmkt = @P_VlrComOpe, 
                         Per_Comissao = @P_PerComVnd, 
                         Vlr_Comissao = @P_VlrComVnd, 
                         Per_ComSup = @P_PerComSup, 
                         Vlr_ComSup = @P_VlrComSup, 
                         Per_ComGer = @P_PerComGer,  
                         Vlr_ComGer = @P_VlrComGer, 
                         Per_ComSupOpe = @P_PerComSupOpe, 
                         Vlr_ComSupOpe = @P_VlrComSupOpe, 
                         Per_ComGerOpe = @P_PerComGerOpe, 
                         Vlr_ComGerOpe = @P_VlrComGerOpe, 
                         Per_ComTra = @P_PerComTra, 
                         Val_ComTra = @P_VlrComTra,

                         Cod_CtlSldVrb = @pc_Controle_Saldo,  
                         Vlr_BasVerba = @P_VlrBasVerba, 
                         --Vlr_Verba = @P_VlrVrbVdr,   -- até 26/11/2022
                         Vlr_Verba = @P_VlrVerba, 
                         Vlr_VrbVdr = @P_VlrVrbVdr, 
                         Vlr_VrbOpe = @P_VlrVrbOpe, 
                         Vlr_VrbSup = @P_VlrVrbSup, 
                         Per_VrbPar = @P_PerVrbPar, 
                         Vlr_VrbPar = @P_VlrVrbPar, 
                         Per_VrbBon = @P_PerVrbBon, 
                         Vlr_VrbBon = @P_VlrVrbBon, 
                         Vlr_DscBonDup = @P_VlrDscBonDup,

                         Str_VolEmb = @StrVol, 
                         Vlr_Frete = 0, 
                         Vlr_Seguro = 0,

                         Transacao = @Now,
						 
						 Vlr_BasIrf = @cb_VlrBasIrfIt, 
						 Alq_Irf = @cb_AlqIrfIt, 
						 Vlr_Irf = @cb_VlrIrfIt 
						 
                   Where Cod_Estabe = @CodEstabe
                     And Ser_Nota = @SerNfsRet 
                     And Num_Nota = @NumNfsRet
                     And Cod_Produto = @it_CodPrd
                     And Cod_Lote = @P_CodLot
                     And Num_SeqIte = @P_NumSeqIte

                  Update NFSIT
                     Set Vlr_BruItem  = Round(Prc_Unitario * (Qtd_Produto + Qtd_Bonificacao),2),
                         Vlr_TotItem  = Round(Qtd_Produto * Prc_Unitario*(1-Per_Desconto/100),2),  
                         Vlr_DescItem = Round(Prc_Unitario * (Qtd_Produto + Qtd_Bonificacao),2) - Round(Qtd_Produto * Prc_Unitario*(1-Per_Desconto/100),2),

                         Vlr_LiqItem = Round(Qtd_Produto * Prc_Unitario*(1-Per_Desconto/100),2) --IsNull(Vlr_TotItem,0) 
                                     - IsNull(Vlr_RepIcms,0) - Isnull(Vlr_DescRateado,0) - IsNull(Vlr_DscBonRat,0) - IsNull(Vlr_DscTri,0)
                                     + IsNull(Vlr_SubsTrib,0) + IsNull(Vlr_SbtRes,0) + IsNull(Vlr_RecSbt,0) + IsNull(Vlr_Ipi,0) + Isnull(Vlr_DespRateada,0)  + Isnull(Vlr_DspExt,0),
                         Vlr_LiqVenIte = Round(Qtd_Produto * Prc_Unitario*(1-Per_Desconto/100),2) --IsNull(Vlr_TotItem,0) 
                                       - IsNull(Vlr_RepIcms,0) - Isnull(Vlr_DescRateado,0) - IsNull(Vlr_DscBonRat,0) - IsNull(Vlr_DscTri,0)
                   Where Cod_Estabe = @CodEstabe
                     And Ser_Nota = @SerNfsRet 
                     And Num_Nota = @NumNfsRet
                     And Cod_Produto = @it_CodPrd
                     And Cod_Lote = @P_CodLot
                     And Num_SeqIte = @P_NumSeqIte

                  -- insere registros NSIUM
                  Insert Into NSIUM (Cod_Estabe, Ser_Nota, Num_Nota, Cod_Produto, Cod_Lote, Num_SeqIte, Cod_IUM, Cod_IUC)
                    Select @CodEstabe, @SerNfsRet, @NumNfsRet, ci.Cod_Produt, ci.Cod_Lote, @P_NumSeqIte, ci.Cod_IUM, ci.Cod_IUC
                      From CPIUM ci 
                     Where ci.Cod_Estabe = @CodEstabe And ci.Num_PedCnf = @CodPed
                       And ci.Cod_Produt = @it_CodPrd
                       And ci.Cod_Lote = @P_CodLot
                  if (@@error <> 0)
                    begin
                      if @@trancount > 0
                        Rollback Transaction
                      Return
                    end
                    
                  -- acumula valores p/  cabecalho
                  if @P_FlgComNor = 0
                    Set @PFlgComNor = 0


                end  -- While (@@FETCH_STATUS = 0) and (@Sld_QtdPed+@Sld_QtdBon) > 0)
              
              Close PDVLTAUX_Cr 
              Deallocate PDVLTAUX_Cr
                
            end  -- while (@Sld_QtdPed+@Sld_QtdBon) > 0

          Fetch Next From PDVIT_Cr Into @it_CodLot, @it_TipSai, @it_QtdSol, @it_QtdPed, @it_QtdBon, @it_PerDsc, @it_CPerDscIte, 
                                        @it_PrcUni, @it_CPrcUni, @it_PrcUniSemAcrIcm, @it_FlgPrcUniAcrIcm, @it_PrcUniComAcrIcm,
                                        @it_PrcTab, @it_PrcTabBru, @it_PrcFab, @it_PrcMax, @it_PrcRefFpb, @it_FlgBlqInfPar,
                                        @it_FlgPrcUniDsc, @it_CodPrm, @it_TipAux, @it_CodClaTri, @it_CodCst, @it_CodCsosn, @it_FlgBlqDsc, @it_PerDscVis, @it_PerDscPrz,
                                        @it_VlrDscBonRat, @it_VlrDespes, @it_VlrDspExt, @it_VlrBasIcmNor, @it_AlqIcm, @it_VlrIcmNor, @it_VlrBasRepIcm, @it_PerRepIcm, @it_VlrRepIcm, @it_VlrPrdSubTri,
                                        @it_VlrBasSubTri, @it_VlrSubTri, @it_VlrBasSbtRes, @it_VlrSbtRes, @it_VlrBasDscTri, @it_PerDscTri, @it_VlrDscTri, 
                                        @it_VlrBasIcmTri, @it_VlrIcmTri, @it_VlrIsento,  @it_VlrOutros, @it_VlrBru,
                                        @it_FatCnvImpFat, @it_QtdImpFat, @it_PrcUniImpFat, @it_DesUnvImpFat, @it_DesAprImpFat, @it_IdPolCom, @it_QtdPra, @it_QtdDep,
                                        @it_CodModBasCalIcm, @it_CodModBasCalIcmSbt, @it_VlrBasTri, @it_PerRedBasCalIcm, @it_PerRedBasCalIcmSbt, 
                                        @it_AlqIcmSbt, @it_AlqAgrSbt, @it_VlrVerba, @it_VlrVrbVdr, @it_VlrVrbOpe, @it_VlrVrbSup,
                                        @it_CodPrjPde, @it_PrcUniPde, @it_PerDscPde, @it_NumSeqPdc, @it_FlgPolPrm,
                                        @it_VlrDscBonDup, @it_VlrBonificacao, @it_PrcCusMinComMarkup, @it_VlrBasVerba,
                                        @it_AlqIntIcmDes, @it_PerAcrAlqIntFcp, @it_PerPrvParIcm,
                                        @it_VlrIcmFcpDes, @it_VlrIcmParDes, @it_VlrIcmParRem, @it_CodKitPrm, @it_FlgUsaDebPresum, @it_AlqIcmPresum,
                                        @it_PrcPolCom, @it_PerDscPolCom,
                                        @it_VlrIcmDesone, @it_CodMtvIcmDesone, @it_VlrDscCalSuframa, @it_FlgIncFis,
                                        @it_AlqFcpIcm, @it_VlrFcpIcm, @it_AlqFcpSbt, @it_VlrFcpSbt, @it_AlqFcpSbtRet, @it_VlrFcpSbtRet,
                                        @it_PerIcmDiferi, @it_VlrIcmDiferi, @it_CodFab,
                                        @it_CodOriMer, @it_VlrBasIpi, @it_VlrIpi, @it_AlqIpi, @it_CSTIpi, @it_CodEnqIpi, @cb_VlrBasIrfIt, @cb_AlqIrfIt, @cb_VlrIrfIt 
        end  --   While @@FETCH_STATUS = 0

      Close PDVIT_Cr 
      Deallocate PDVIT_Cr
      -- R0010 -------------------------------------------------------------------------------------------------------------------- 
      
      Fetch Next From PRODU_Cr Into @it_CodPrd
    end
    
  Close PRODU_Cr 
  Deallocate PRODU_Cr

  -- grava faltas
  Declare PDVIT_Cr Cursor Local Fast_Forward For 

    Select it.Cod_Produto, 
           sum(IsNull(it.Qtd_Solicitado,0)-IsNull(it.Qtd_Pedido,0)-IsNull(it.Qtd_Bonificacao,0)), 
           sum(Round((IsNull(it.Qtd_Solicitado,0)-IsNull(it.Qtd_Pedido,0)-IsNull(it.Qtd_Bonificacao,0))
                      *(it.C_PrcUni*(1-it.C_PerDscIte/100))*(1-@cb_PerDscCom/100),2))
      From PDVIT it
           Inner join PRODU pr on pr.Codigo = it.Cod_Produto
     Where Cod_Estabe = @CodEstabe 
       And Cod_Pedido = @CodPed
       And IsNull(it.Qtd_Solicitado,0) > (IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0))
     Group by it.Cod_Produto

  Open PDVIT_Cr
  Fetch Next From PDVIT_Cr Into @it_CodPrd, @WQtdMov, @WVlrTotLiq 

  While @@FETCH_STATUS = 0
    begin
      EXEC PR_AcuFalNfsItePrd @CodEstabe, @TipNfs, 'F', @PDatEmi, @it_CodPrd, @WQtdMov, @WVlrTotLiq
      if (@@error <> 0)
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end

      Fetch Next From PDVIT_Cr Into @it_CodPrd, @WQtdMov, @WVlrTotLiq
    end  --   While @@FETCH_STATUS = 0

  Close PDVIT_Cr 
  Deallocate PDVIT_Cr

  -- R0005  -----------------------------------------------------------------------------------------------------------------

  Drop Table #PDVLT_AUX

  -- calcula frete p/ pessoa juridica
  if (@tr_Pessoa <> 'F') and (@TipNfs = 'V') and (@cb_TipSaiPdv <> 'B')
    begin
      Set @WVlrTotLiq = @cb_VlrLiqIte - @PVlrDscCom - @cb_VlrDscBon - @cb_VlrRepIcm - @cb_VlrDscTri
      if @tr_FlgCalFreVerMer = 1
        Set @WVlrBasFre = @WVlrTotLiq
      else
        Set @WVlrBasFre = @PVlrTotNot

      Set @PVlrComTra = Round(@WVlrBasFre*@tr_PerFrete/100,2)
      if Round(@PVlrComTra*100,2) < Round(@tr_VlrMin*100,2)
        Set @PVlrComTra = @tr_VlrMin
    end

  -- recalcula parceria pois estava errado na PDVCB    
  Set @cb_VlrBasPar = IsNull((Select sum(it.VlrTotIte)     
                                From (Select VlrTotIte = Case
                                                           When b.Flg_BlqDsc = 0 then Round((IsNull(b.Vlr_TotItem,0)*(1-a.Per_DescontoCom/100)-IsNull(b.Vlr_RepIcms,0)-IsNull(b.Vlr_DscTri,0)),2)
                                                           Else (IsNull(b.Vlr_TotItem,0)-IsNull(b.Vlr_RepIcms,0)-IsNull(b.Vlr_DscTri,0))
                                                         End
                                        From NFSCB a 
                                             Inner Join NFSIT b on ((a.Cod_Estabe = b.Cod_Estabe) and (a.Ser_Nota = b.Ser_Nota) and (a.Num_Nota = b.Num_Nota))
                                       Where a.Cod_Estabe = @CodEstabe and a.Ser_Nota = @SerNfsRet and a.Num_Nota = @NumNfsRet
                                         And b.Flg_BlqInfPar = 0) it),0)

  -- Cfop do cabecalho com o do item de maior valor atualizadoem PR_AtualizaCabecNFS
  
  Update NFSCB
     Set Status = 'F',
         Tip_Saida = @TipNfs,
         Flg_MovEst = 1,
         Cod_Cfo1 = @PCodCfo,
         Flg_ComisNormal = @PFlgComNor,
         Vlr_BasPar = Round(@cb_VlrBasPar,2),
         Val_ComTra = Round(@PVlrComTra,2)
   Where Cod_Estabe = @CodEstabe 
     And Ser_Nota = @SerNfsRet
     And Num_Nota = @NumNfsRet

  -- rateia desconto comercial, qdo for o caso
  Exec PR_RateiaDescontosNFS @CodEstabe, @SerNfsRet, @NumNfsRet
  if @@error <> 0
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end    

  -- rateia comissão de transporte, qdo for o caso
  Exec PR_RateiaComissaoTranspNFS @CodEstabe, @SerNfsRet, @NumNfsRet
  if @@error <> 0
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end    

  -- atualiza valores do cabeçalho
  Exec PR_AtualizaCabecNFS @CodEstabe, @SerNfsRet, @NumNfsRet
  if @@error <> 0
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end    

  -- atualiza PRXES
  Update pr
     Set pr.Dat_UltVen = x.Dat_Emissao
    From PRXES pr 
         Inner Join (Select cb.Dat_Emissao, cb.Cod_Estabe, it.Cod_Produto
                       From NFSCB cb 
                            Inner Join NFSIT it on (cb.Cod_Estabe = it.Cod_Estabe and cb.Ser_Nota = it.Ser_Nota and cb.Num_Nota = it.Num_Nota)
                      Where cb.Cod_Estabe = @CodEstabe
                        And cb.Ser_Nota = @SerNfsRet
                        And cb.Num_Nota = @NumNfsRet 
                        And Tip_Saida = 'V') x ON (pr.Cod_Estabe = x.Cod_Estabe And pr.Cod_Produt = x.Cod_Produto)

  -- gera contas a receber
  if @to_FlgLanFin = 1
    begin

      EXEC PR_GeraTitulosFat @CodEstabe, @SerNfsRet, @NumNfsRet, @to_IsnCtaFinDeb, @to_IsnCtaFinCre, @DesUsu
      if (@@error <> 0)
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end

      -- campo calculado da nota
      -- valor real da NF p/ atualizar acumuladores do sistema
      if @PTipRetImp = 'R'   -- imposto a recolher nao incluido no Total da NF
        Set @WCVlrTotNot = @PVlrTotNot + @cb_VlrSubTri - @cb_VlrDscTri
      else
        Set @WCVlrTotNot = @PVlrTotNot 
      -- atualiza cliente
      Set @PTotDebCli = @PTotDebCli + @WCVlrTotNot
      Set @PVlrUltFatCli = @WCVlrTotNot
      if @WCVlrTotNot > @PVlrMaiFatCli
        Set @PVlrMaiFatCli = @WCVlrTotNot

      Update CLIEN
         Set Total_Debito = @PTotDebCli,
             Data_UltimaFatura = @PDatEmi,
             Valor_UltimaFatura = @PVlrUltFatCli,
             Valor_MaiorFatura = @PVlrMaiFatCli
       Where Codigo = @cb_CodCli
    end
  else
    begin
      -- lancamentos gerenciais
      Set @WVlrMov = (Select Vlr_TotalNota From NFSCB Where Cod_Estabe = @CodEstabe and Ser_Nota = @SerNfsRet And Num_Nota = @NumNfsRet)
      Set @WIdTransacao = (Select Id_Transacao From NFSCB Where Cod_Estabe = @CodEstabe and Ser_Nota = @SerNfsRet And Num_Nota = @NumNfsRet)
  
      -- inclui conta credora
      if @to_IsnCtaFinCre > 0
        Exec PR_AtualizaPCMOV 'I', @CodEstabe, @to_IsnCtaFinCre, @Date, 'NFSCB', 'NFS', @SerNfsRet, @NumNfsRet, 0, @WIdTransacao, @WVlrMov
  
      -- inclui conta devedora
      if @to_IsnCtaFinDeb > 0
        begin
          Set @WVlrMov = -@WVlrMov
          Exec PR_AtualizaPCMOV 'I', @CodEstabe, @to_IsnCtaFinDeb, @Date, 'NFSCB', 'NFS', @SerNfsRet, @NumNfsRet, 0, @WIdTransacao, @WVlrMov
        end
    end

  -- atualiza PDVCB
  if (@pm_FlgDespachMercad = 0) or (Charindex(@cb_TipFat,';FUN;CON;') > 0)
    Update PDVCB
      Set Cod_SerNfs = @SerNfsRet,
          Cod_NumNfsIni = @NumNfsRet,
          Hor_Fatura = @Now,
          Hor_Saida = @Now,
          Status1 = 'D',
          Status2 = 'D',
          Flg_Credito = null
      Where Cod_Estabe = @CodEstabe And Numero = @CodPed
  else
    Update PDVCB
      Set Cod_SerNfs = @SerNfsRet,
          Cod_NumNfsIni = @NumNfsRet,
          Hor_Fatura = @Now,
          Status2 = 'N',
          Flg_Credito = null
      Where Cod_Estabe = @CodEstabe And Numero = @CodPed

  -- elimina conferencia em aberto 
  Delete From CPVCB
   Where Cod_Estabe = @CodEstabe And Num_PedCnf = @CodPed
     And Sta_PedCnf = '0'
  if (@@error <> 0)
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end


  -- atualiza estatisticas do item
  Exec PR_AtualizaEstatisticasNFS @CodEstabe, @SerNfsRet, @NumNfsRet, 'F'
  if @@error <> 0
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  -- recalcula NF se houver despesas ou se orgao publico com desconto ICMS
  -- PDVIT.Vlr_Despes = despesa + frete. na NFSIT estes valores são separados
  Set @WFlgRecalcula = 0
  if (@PVlrOutDsp+@cb_VlrFrete) > 0
    Set @WFlgRecalcula = 1
  if ((@rt_FlgDscIcmOrgPub = 1) or (@rt_FlgDscIcmOrgPubAcr = 1)) and ((@cl_TipCon = 'P') or (@cl_TipCon = 'E') or (@cl_TipCon = 'M'))   
    Set @WFlgRecalcula = 1

  if @WFlgRecalcula = 1
    begin
      EXEC PR_RecalculaNFSCB @CodEstabe, @SerNfsRet, @NumNfsRet
      if (@@error <> 0)
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end
    end  

  -- debita verba do vendedor
  if @PVlrDebVrbVdr > 0
    begin
      Set @WVlrMov = -@PVlrDebVrbVdr
      Exec PR_AtualizaSaldoVBSLD @CodEstabe, @cb_CodVdr, @PDatEmi, 0, 0, '', '', 'S', @TipNfs, @SerNfsRet, @NumNfsRet, @WVlrMov, '', 'SISTEMA'
      if (@@error <> 0)
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end
    end

  -- recalcula NFS (embutir sbt no preco) se for o caso
  EXEC PR_RecalculaNFS_Sbt @CodEstabe, @SerNfsRet, @NumNfsRet
  if (@@error <> 0)
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  -- gera vale (devolucao)   
  if (@TipNfs = 'D') and ((@cb_CodCli > 0) or (@cb_CodFun > 0))
    begin
       Set @WVlrMov = (Select Vlr_TotalNota From NFSCB Where Cod_Estabe = @CodEstabe and Ser_Nota = @SerNfsRet And Num_Nota = @NumNfsRet)
      if @cb_CodCli > 0
        begin
          Set @WTipDes = 'CLI'
          Set @WCodDes = @cb_CodCli
        end
      else
      if @cb_CodFun > 0
        begin
          Set @WTipDes = 'FUN'
          Set @WCodDes = @cb_CodFun
        end

      EXEC PR_ProxNumero 'Vale', @WCodDoc output
      if @@error <> 0
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end

      -- inclui vale
      Insert into VALES
        (Cod_Estabe, Cod_Vale, Des_Vale, Tip_Entid, Cod_Entid, Dat_Emissa, Val_Vale, Deb_Cre, 
         Cod_CtrLanAut, Ser_CtrLanAut, Num_CtrLanAut, Isn_CtaFinDeb, Isn_CtaFinCre, Usuario, Transacao)
      Values
        (@CodEstabe, @WCodDoc,'NFS Devolucao: '+@SerNfsRet+'/'+cast(@NumNfsRet as varchar), @WTipDes, @WCodDes, @Date, @WVlrMov, 'D',
         'DNS', @SerNfsRet, @NumNfsRet, @to_IsnCtaFinDeb, @to_IsnCtaFinCre, @DesUsu,@Now)
    end
      
  -- elimina registros em TBIUM
  Delete ti
    From TBIUM ti, CPIUM ci 
   Where ti.Cod_Estabe = ci.Cod_Estabe 
     And ti.Cod_IUM = ci.Cod_IUM
     And ci.Cod_Estabe = @CodEstabe 
     And ci.Num_PedCnf = @CodPed

  -- gera contrato a partir das faltas, se for o caso
  EXEC PR_CriaContratoPendenciasPedido @CodEstabe, @CodPed
  if (@@error <> 0)
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  -- atualiza itens na tabela de contratos hospitalares 
  if (@cb_CodCtr > 0) and (@cb_NumSeqCtr > 0)
    begin
      Exec PR_FaturaContratoHosp @CodEstabe, @CodPed, @cb_CodCtr, @cb_NumSeqCtr
      if (@@error <> 0)
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end
    end

  -- atualiza itens na tabela de consignações
  if (@cb_IdConsig > 0) and (@cb_NumSeqCtr > 0)
    begin
      Exec PR_FaturaConsignacao 'S', @CodEstabe, @SerNfsRet, @NumNfsRet, @cb_IdConsig, @cb_NumSeqCtr
      if (@@error <> 0)
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end
    end

  -- libera endereço Cross Docking do depósito
  if Exists(Select 1 From PDVCB 
             Where Cod_Estabe = @CodEstabe 
               And Numero = @CodPed
               And IsNull(Num_PrtOri,0) > 0)
    begin
      Declare @WNumProtoc int
      Set @WNumProtoc = IsNull((Select Num_PrtOri From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed),0)
      Exec PR_VinculaDesvinculaEnderecoNFE 'D', @CodEstabe, @WNumProtoc
    end

  if @@trancount > 0
    Commit Transaction
end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ProxNumBlq] 
  @CodAgCob Int,
  @PartNum varchar(18) output
AS

SET NOCOUNT ON

Begin Transaction

  Declare @i Int = 0,
          @NumUltBlq Varchar(18)
	
  select @NumUltBlq = IsNull(Num_UltBlq, '0') from AGCOB WITH (XLOCK, TABLOCK) where Codigo = @CodAgCob;

  while @i < Len(@NumUltBlq)
    begin
	  if IsNumeric(Right(@NumUltBlq, Len(@NumUltBlq) - @i)) = 1
	    begin			
		  set @PartNum = Convert(BigInt, Right(@NumUltBlq, Len(@NumUltBlq) - @i)) + 1
		  set @PartNum = IsNull(Replicate('0', Len(Right(@NumUltBlq, Len(@NumUltBlq) - @i)) - Len(@PartNum)), '')  + @PartNum

  		  if Len(@PartNum) > Len(Right(@NumUltBlq, Len(@NumUltBlq) - @i))
		    begin
			  set @PartNum = Right(@PartNum, Len(@PartNum) - 2)
			end			
			break
  	    end	
    Set @i += 1
  end 
  
  if Len(@PartNum) > 0
    Update AGCOB 
      Set Num_UltBlq = @PartNum
      Where Codigo = @CodAgCob

Commit Transaction
  
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ProIni_ZeraVerbasMes]
@PCodEstabe int   -- -1:  todos os estabelecimentos

AS

SET NOCOUNT ON

Set DateFormat ymd

Declare @pm_FlgZerAutMesSldVrbPos bit, 
        @pm_FlgZerAutMesSldVrbNeg bit

Declare @cr_CodEstabe int,
        @DatMovime smalldatetime, 
        @CodVended int, 
		@CodFabric int,
		@NumProtoc int, 
		@SldVerbaAnt numeric(18,4),
        @CodMovime varchar(1), 
		@VlrZeraVerba numeric(18,4)

-- último dia do mês (data do lançamento)
Set @DatMovime = cast(DATEADD(dd, 0, DATEDIFF(dd, (DatePart(dd,GetDate())-1), GETDATE())) as smalldatetime) - 1;
Set @CodMovime = 'Z'   -- zera saldo anterior
Set @NumProtoc = 999999999    -- garante ultimo protocolo do dia

if Exists(Select e.Cod_Estabe
            From ESTAB e
                 inner join PARAM p on e.Cod_Estabe= p.Cod_Estabe
           Where e.Cod_Estabe = Case 
                                  When @PCodEstabe = -1 Then e.Cod_Estabe 
                                  Else @PCodEstabe 
                                End
		     And ( (IsNull(p.FlgZerAutMesSldVrbPos,0) = 1) or (IsNull(p.FlgZerAutMesSldVrbNeg,0) = 1) ) )
  BEGIN
    BEGIN TRANSACTION

      DECLARE ESTABE_Cr Cursor Local Fast_Forward For
        Select e.Cod_Estabe
          From ESTAB e
               inner join PARAM p on e.Cod_Estabe= p.Cod_Estabe
         Where e.Cod_Estabe = Case 
                                When @PCodEstabe = -1 Then e.Cod_Estabe 
                                Else @PCodEstabe 
                              End
		   And ( (IsNull(p.FlgZerAutMesSldVrbPos,0) = 1) or (IsNull(p.FlgZerAutMesSldVrbNeg,0) = 1) )
      OPEN ESTABE_Cr
      FETCH NEXT FROM ESTABE_Cr INTO @cr_CodEstabe
      WHILE @@FETCH_STATUS = 0
      BEGIN
        Select @pm_FlgZerAutMesSldVrbPos = IsNull(FlgZerAutMesSldVrbPos,0), 
               @pm_FlgZerAutMesSldVrbNeg = IsNull(FlgZerAutMesSldVrbNeg,0)
          From PARAM 
         Where Cod_Estabe = @cr_CodEstabe

        if ((@pm_FlgZerAutMesSldVrbPos = 1) or (@pm_FlgZerAutMesSldVrbNeg = 1))
          begin
        
            -- seleciona vendedores com saldo anterior <> 0 
            Declare VEXES_cr CURSOR Local Fast_Forward For 
              Select vx.Cod_Vended, Saldo_Verba = IsNull(sd.Val_SldMovime,0)
                From VEXES vx
                     Outer Apply (Select top 1 s.Val_SldMovime 
                                    From VBSLD s
                                   Where vx.Cod_Estabe = s.Cod_Estabe and vx.Cod_Vended = s.Cod_Vended
        					         And s.Dat_Movime < @DatMovime + 1
                                   Order by s.Dat_Movime desc, s.Num_Protoc desc) sd
              Where vx.Cod_Estabe = @cr_CodEstabe
                And IsNull(sd.Val_SldMovime,0) <> 0
                And not Exists (Select 1
                                  From VBSLD s
                                 Where vx.Cod_Estabe = s.Cod_Estabe and vx.Cod_Vended = s.Cod_Vended
                                   And s.Dat_Movime = @DatMovime
                                   And s.Cod_Movime = 'Z')
        	Open VEXES_cr
        	Fetch Next From VEXES_cr into @CodVended, @SldVerbaAnt
            While @@FETCH_STATUS = 0
            Begin	  
              Set @VlrZeraVerba = (@SldVerbaAnt * -1);
        
              if ( ((@pm_FlgZerAutMesSldVrbPos = 1) and (@SldVerbaAnt > 0)) or
                   ((@pm_FlgZerAutMesSldVrbNeg = 1) and (@SldVerbaAnt < 0)) )
        
                if not Exists(Select 1 From VBSLD
                               Where Cod_Estabe = @cr_CodEstabe 
                                 And Cod_Vended = @CodVended
                                 And Dat_Movime = @DatMovime
                                 And Num_Protoc = @NumProtoc)
                  begin
                    Exec PR_AtualizaSaldoVBSLD @cr_CodEstabe, @CodVended, @DatMovime, @NumProtoc, 0, '',
                                               '', 'M', @CodMovime, '', 0, 
                                               @VlrZeraVerba, 'ANULA SALDO ANTERIOR', 'SISTEMA'
                  end
        
              Fetch Next From VEXES_cr into @CodVended, @SldVerbaAnt
            End
        	Close VEXES_cr
        	Deallocate VEXES_cr
        
        
            -- seleciona vendedores/fabricantes com saldo anterior <> 0 
            Declare VBFSL_cr CURSOR Local Fast_Forward For 
              Select vb.Cod_Vended, vb.Cod_Fabric, Saldo_Verba = IsNull(sd.Val_SldMovime,0) 
                From (Select distinct Cod_Estabe, Cod_Vended, Cod_Fabric
        		       From VBFSL) vb
                     Outer Apply (Select top 1 s.Val_SldMovime 
                                    From VBFSL s
                                   Where vb.Cod_Estabe = s.Cod_Estabe and vb.Cod_Vended = s.Cod_Vended and vb.Cod_Fabric = s.Cod_Fabric
        					         And s.Dat_Movime < @DatMovime+1
                                   Order by s.Dat_Movime desc, s.Num_Protoc desc) sd
              Where vb.Cod_Estabe = @cr_CodEstabe			    
                And IsNull(sd.Val_SldMovime,0) <> 0
                And not Exists (Select 1
                                  From VBFSL s
                                 Where vb.Cod_Estabe = s.Cod_Estabe and vb.Cod_Vended = s.Cod_Vended and vb.Cod_Fabric = s.Cod_Fabric
                                   And s.Dat_Movime = @DatMovime
                                   And s.Cod_Movime = 'Z')
        	Open VBFSL_cr
        	Fetch Next From VBFSL_cr into @CodVended, @CodFabric, @SldVerbaAnt
            While @@FETCH_STATUS = 0
            Begin	  
              Set @VlrZeraVerba = (@SldVerbaAnt * -1);
        
              if ( ((@pm_FlgZerAutMesSldVrbPos = 1) and (@SldVerbaAnt > 0)) or
                   ((@pm_FlgZerAutMesSldVrbNeg = 1) and (@SldVerbaAnt < 0)) )
        
                if not Exists(Select 1 From VBFSL
                               Where Cod_Estabe = @cr_CodEstabe 
                                 And Cod_Vended = @CodVended
                                 And Cod_Fabric = @CodFabric
                                 And Dat_Movime = @DatMovime
                                 And Num_Protoc = @NumProtoc)
                  begin
                    Exec PR_AtualizaSaldoVBFSL @cr_CodEstabe, @CodVended, @CodFabric, @DatMovime, @NumProtoc, 0, '',
        		                               '', 'M', @CodMovime, '', 0, 
                                               @VlrZeraVerba, 'ANULA SALDO ANTERIOR', 'SISTEMA'
                  end
        
              Fetch Next From VBFSL_cr into @CodVended, @CodFabric, @SldVerbaAnt
            End
        	Close VBFSL_cr
        	Deallocate VBFSL_cr
        
          end  -- if ((@pm_FlgZerAutMesSldVrbPos = 1) or (@pm_FlgZerAutMesSldVrbNeg = 1))

        FETCH NEXT FROM ESTABE_Cr INTO @cr_CodEstabe
      END
      CLOSE ESTABE_Cr
      DEALLOCATE ESTABE_Cr  

    COMMIT TRANSACTION
  END  -- if Exists(Select e.Cod_Estabe
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ProIni_EncerraMes]
@CodEstabe int

AS

SET NOCOUNT ON

Begin Transaction

  -- Pegar a data atual com a hora zerada 
  Set DateFormat ymd  
  Declare @Now smalldatetime,
          @Date smalldatetime,
		  @pm_DatEncRotMen smalldatetime,
		  @pm_QtdMesMedRotMen int,
	  	  @AnoRef int,
	  	  @MesRef int,
		  @AnoMesPar int
        
  Set @Now = GetDate()
  Set @Date = cast(GetDate() as Date)

  -- verifica se executa encerramento mensal (todos os estabelecimentos)
  Select @pm_DatEncRotMen = IsNull(DatFecRotMen,0),
         @pm_QtdMesMedRotMen = IsNull(QtdMesMedRotMen,3)
    From PARAM 
   Where Cod_Estabe = @CodEstabe

  Set @AnoRef = DatePart(Year,@Date)
  Set @MesRef = DatePart(Month,@Date)
  Set @AnoMesPar = DatePart(Year,IsNull(@pm_DatEncRotMen,0))*100+DatePart(Month,IsNull(@pm_DatEncRotMen,0))

  if (@AnoRef*100+@MesRef) > @AnoMesPar
    begin
	  Set @MesRef = @MesRef-1
	  if @MesRef = 0
	    begin
		  Set @MesRef = 12
		  Set @AnoRef = @AnoRef - 1
		end

      Exec PR_ProcessaClaABC @pm_QtdMesMedRotMen, 1, 1, 1
      if @@error <> 0
        begin
          Rollback Transaction
          Return
        end

      Exec PR_ProcessaResumoGeral @MesRef, @AnoRef
      if @@error <> 0
        begin
          Rollback Transaction
          Return
        end

      Exec PR_ProIni_ZeraVerbasMes -1     -- todos os estabelecimentos
      if @@error <> 0
        begin
          Rollback Transaction
          Return
        end

	end

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_VerificaEstoque]
@CodEstabe int

AS

SET NOCOUNT ON 

Print ''
Print 'Verifica estoques negativos em PRXES:'


  -- verifica qtd.fisico > 0 em PRXES sem registro em PRSLD
  if Exists(Select p.Cod_Produt
            From PRXES p Left Outer Join 
                 PRSLD s on p.Cod_Estabe = s.Cod_Estabe and p.Cod_Produt = s.Cod_Produt 
            Where p.Cod_Estabe = @CodEstabe 
            And p.Qtd_Fisico > 0 and s.Cod_Produt is null)
    Select p.Cod_Produt as 'Prd.c/estoque(PRXES) s/registro em PRSLD',
           p.Qtd_Fisico as 'FISICO em PRXES'
    From PRXES p Left Outer Join
         PRSLD s on p.Cod_Estabe = s.Cod_Estabe and p.Cod_Produt = s.Cod_Produt 
    Where p.Cod_Estabe = @CodEstabe 
    And p.Qtd_Fisico > 0 and s.Cod_Produt is null
    
  -- verifica estoque negativo em PRODU
  if Exists(Select Cod_Produt 
            From PRXES 
            Where Cod_Estabe = @CodEstabe 
            And (Qtd_Dispon < 0) or (Qtd_Fisico < 0))
    begin
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': ===> Existem ESTOQUES NEGATIVOS EM PRXES'
      Select Cod_Produt as 'Prd. c/Estoque Negativo', 
             Qtd_Fisico as 'Fisico', 
             Qtd_Reserv as 'Reservado', 
             Qtd_Avaria as 'Avariado', 
             Qtd_Solici as 'Solicitado', 
             Qtd_Dispon as 'Disponivel'
      From PRXES 
      Where Cod_Estabe = @CodEstabe 
      And (Qtd_Dispon < 0) or (Qtd_Fisico < 0)
    end
  else
    PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': Estoques Negativos em PRXES: ok'



Print ''
Print 'Verifica divergências entre PRXES x PRSLD:'

  -- divergencias PRX x PRSLD
  if Exists(Select p.Cod_Produt
            From PRXES p Inner Join 
                 (Select Cod_Estabe, Cod_Produt, Dat_Mov = MAX(Dat_Movime)
                  From PRSLD
                  Where Cod_Estabe = @CodEstabe
                  Group by Cod_Estabe, Cod_Produt) x on p.Cod_Estabe = x.Cod_Estabe and p.Cod_Produt = x.Cod_Produt Inner Join 
                 PRSLD s ON ((p.Cod_Estabe = s.Cod_Estabe) and (p.Cod_Produt = s.Cod_Produt) and (x.Dat_Mov = s.Dat_Movime))
            Where p.Cod_Estabe = @CodEstabe
            and p.Qtd_Fisico <> s.Qtd_SldAtu)
    begin
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': ===> Existem DIVERGENCIAS DE ESTOQUES: PRXES x PRSLD'
      Select p.Cod_Estabe,
	         p.Cod_Produt as 'Prd.c/divergência (PRXES x PRSLD)', 
             p.Qtd_Fisico as 'Físico em PRODU', 
             s.Qtd_SldAtu as 'Físico em PRSLD'
      From PRXES p Inner Join 
           (Select Cod_Estabe, Cod_Produt, Dat_Mov = MAX(Dat_Movime)
            From PRSLD
            Where Cod_Estabe = @CodEstabe
            Group by Cod_Estabe, Cod_Produt) x on p.Cod_Estabe = x.Cod_Estabe and p.Cod_Produt = x.Cod_Produt Inner Join 
           PRSLD s ON ((p.Cod_Estabe = s.Cod_Estabe) and (p.Cod_Produt = s.Cod_Produt) and (x.Dat_Mov = s.Dat_Movime))
      Where p.Cod_Estabe = @CodEstabe
      and p.Qtd_Fisico <> s.Qtd_SldAtu  
    end
  else
    begin
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': Estoque Físico: PRXES x PRSLD ok!'
      if Exists(Select top 1 * From PRXES
                Where Cod_Estabe = @CodEstabe
                And Qtd_Dispon <> (Qtd_Fisico-Qtd_Solici-Qtd_Reserv-Qtd_Avaria))
        begin
          PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': ===> Existem DIVERGENCIAS DOS ESTOQUES EM PRXES'
          Select Cod_Estabe,
		         Cod_Produt as 'Prd.c/divergência (PRXES)', 
				 Qtd_Fisico,
				 Qtd_Solici,
				 Qtd_Reserv,
				 Qtd_Avaria,  
                 Qtd_Dispon as 'Disponivel Cadastrado', 
                 (Qtd_Fisico-Qtd_Solici-Qtd_Reserv-Qtd_Avaria) as 'Disponivel Calculado'
          From PRXES 
          Where Cod_Estabe = @CodEstabe
          And Qtd_Dispon <> (Qtd_Fisico-Qtd_Solici-Qtd_Reserv-Qtd_Avaria)
        end
      else
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': Estoques em PRXES ok!'
    end


Print ''
Print 'Verifica divergências em estoques reservados:'

  -- verifica estoque reservado
  if Exists(Select p.Cod_Produt, p.Qtd_Reserv, r.QtdResTot 
            From PRXES p Left Outer Join
                 (Select Cod_Produto, QtdResTot=sum(IsNull(Qtd_Movimento,0)+IsNull(Qtd_ResDep,0))
                  From RESER
                  Where Cod_Estabe = @CodEstabe
                  Group by Cod_Produto) r on (p.Cod_Produt = r.Cod_Produto)
            Where p.Cod_Estabe = @CodEstabe 
            And p.Qtd_Reserv <> IsNull(r.QtdResTot,0))
    begin          
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': ===> Existem DIVERGENCIAS DE ESTOQUES: PRXES x RESER'
      Select p.Cod_Estabe,
	         p.Cod_Produt as 'Prd.c/divergência (PRXES x RESER)', 
             p.Qtd_Reserv  as 'Reservado em PRXES', 
             r.QtdResTot as 'Reservado em RESER'
      From PRXES p Left Outer Join
           (Select Cod_Produto, QtdResTot=sum(IsNull(Qtd_Movimento,0)+IsNull(Qtd_ResDep,0))
            From RESER
            Where Cod_Estabe = @CodEstabe
            Group by Cod_Produto) r on (p.Cod_Produt = r.Cod_Produto)
      Where p.Cod_Estabe = @CodEstabe
      And p.Qtd_Reserv <> IsNull(r.QtdResTot,0)
    end
  else
    PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': Estoques Reservados em PRXES: ok'



Print ''
Print 'Verifica divergências em estoques avariados:'

  -- verifica estoque avariado
  if Exists(Select p.Cod_Produt, p.Qtd_Avaria, a.QtdAvaTot 
            From PRXES p Left Outer Join
                 (Select Cod_Produto, QtdAvaTot=sum(IsNull(Qtd_Movimento,0)+IsNull(Qtd_AvaDep,0))
                  From AVARI
                  Where Cod_Estabe = @CodEstabe
                  Group by Cod_Produto) a on (p.Cod_Produt = a.Cod_Produto)
            Where p.Cod_Estabe = @CodEstabe 
            And p.Qtd_Avaria <> IsNull(a.QtdAvaTot,0))
    begin          
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': ===> Existem DIVERGENCIAS DE ESTOQUES: PRXES x AVARI'
      Select p.Cod_Estabe,
	         p.Cod_Produt as 'Prd.c/divergência (PRXES x AVARI)', 
             p.Qtd_Avaria  as 'Avariado em PRXES', 
             a.QtdAvaTot as 'Avariado em AVARI'
      From PRXES p Left Outer Join
           (Select Cod_Produto, QtdAvaTot=sum(IsNull(Qtd_Movimento,0)+IsNull(Qtd_AvaDep,0))
            From AVARI
            Where Cod_Estabe = @CodEstabe
            Group by Cod_Produto) a on (p.Cod_Produt = a.Cod_Produto)
      Where p.Cod_Estabe = @CodEstabe 
      And p.Qtd_Avaria <> IsNull(a.QtdAvaTot,0)
    end
  else
    PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': Estoques Avariados em PRXES: ok'



Print ''
Print 'Verifica divergências em estoques solicitados em  PRXES x (PDVIT+ORCIT):'

  -- verifica estoque solicitado em PRXES
  if Exists(Select p.Cod_Produt,
                   IsNull(p.Qtd_Solici,0), IsNull(x.Qtd_Solicitado,0)+IsNull(y.Qtd_Solicitado,0)
            From PRXES p LEFT OUTER JOIN 
                 (Select it.Cod_Produto,
                         sum(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) as Qtd_Solicitado
                  From PDVCB cb Inner Join
                       PDVIT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Numero = it.Cod_Pedido)
                  Where cb.Cod_Estabe = @CodEstabe      
                  and cb.Tip_Pedido = 'P'
                  and cb.Status1 = 'P'
                  and cb.Status2 <> 'N'
                  and cb.Status2 <> 'D'
                  and IsNull(cb.Bloqueio,'') <> 'SR'
                  and (IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) > 0
                  Group by it.Cod_Produto) x ON (p.Cod_Produt = x.Cod_Produto) LEFT OUTER JOIN 
                 (Select it.Cod_Produt,
                         sum(IsNull(it.Qtd_Produt,0)) as Qtd_Solicitado
                  From ORCCB cb Inner Join
                       ORCIT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Cod_Orcame = it.Cod_Orcame)
                  Where cb.Cod_Estabe = @CodEstabe      
                  And cb.Sta_Movime = 'F'
                  and IsNull(cb.Num_Docume,0) = 0
                  and it.Tip_EntSai = 'S'
                  And IsNull(cb.Cod_OriVen,'') <> 'DMD'
                  and (IsNull(it.Qtd_Produt,0)) > 0
                  Group by it.Cod_Produt) y ON (p.Cod_Produt = y.Cod_Produt)
            Where p.Cod_Estabe = @CodEstabe      
            And IsNull(p.Qtd_Solici,0) <> IsNull(x.Qtd_Solicitado,0)+IsNull(y.Qtd_Solicitado,0))
    begin
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': ===> Existem DIVERGENCIAS DE ESTOQUES: PRXES x (PDVIT+ORCIT)'
      
      Select p.Cod_Estabe,
	         p.Cod_Produt as 'Prd.c/divergência (PRXES x (PDVIT+ORCIT))', 
             p.Qtd_Solici as 'Solicitado em PRXES', 
             IsNull(x.Qtd_Solicitado,0) as 'Solicitado em PDVIT', 
             IsNull(y.Qtd_Solicitado,0) as 'Solicitado em ORCIT'
            From PRXES p LEFT OUTER JOIN
                 (Select it.Cod_Produto,
                         sum(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) as Qtd_Solicitado
                  From PDVCB cb Inner Join
                       PDVIT it on (cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Cod_Pedido)
                  Where cb.Cod_Estabe = @CodEstabe      
                  and cb.Tip_Pedido = 'P'
                  and cb.Status1 = 'P'
                  and cb.Status2 <> 'N'
                  and cb.Status2 <> 'D'
                  and IsNull(cb.Bloqueio,'') <> 'SR'
                  and (IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) > 0
                  Group by it.Cod_Produto) x ON (p.Cod_Produt = x.Cod_Produto) LEFT OUTER JOIN
                 (Select it.Cod_Produt,
                         sum(IsNull(it.Qtd_Produt,0)) as Qtd_Solicitado
                  From ORCCB cb Inner Join
                       ORCIT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Cod_Orcame = it.Cod_Orcame)
                  Where cb.Cod_Estabe = @CodEstabe      
                  And cb.Sta_Movime = 'F'
                  and IsNull(cb.Num_Docume,0) = 0
                  and it.Tip_EntSai = 'S'
                  And IsNull(cb.Cod_OriVen,'') <> 'DMD'
                  and (IsNull(it.Qtd_Produt,0)) > 0
                  Group by it.Cod_Produt) y ON (p.Cod_Produt = y.Cod_Produt)
            Where p.Cod_Estabe = @CodEstabe      
            And IsNull(p.Qtd_Solici,0) <> IsNull(x.Qtd_Solicitado,0)+IsNull(y.Qtd_Solicitado,0)
      Order by p.Cod_Produt
    end
  else
    PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': Estoques Solicitados em PRXES: ok'



Print ''
Print 'Verifica divergências em estoques solicitados em PRLOT x (PDV+AVARI+RESER+ORC):'

  -- verifica lotes solicitados em PRLOT
  if Exists(Select lt.Cod_Produt, lt.Cod_Lote, lt.Qtd_Solicitado, 
                   (IsNull(a.Qtd_Sol,0)+IsNull(b.Qtd_Sol,0)+IsNull(c.Qtd_Sol,0)+IsNull(d.Qtd_Sol,0)+IsNull(e.Qtd_Sol,0)) as Qtd_SolTot
            From (Select Cod_Estabe, Cod_Produt, Cod_Lote, Qtd_Solicitado=SUM(IsNull(Qtd_Solicitado,0))
                  From PRLOT
                  Where Cod_Estabe = @CodEstabe
                  Group by Cod_Estabe, Cod_Produt, Cod_Lote) lt Left Outer Join
  
                 (Select it.Cod_Produto, it.Cod_Lote,
                         sum(Isnull(it.Qtd_Pra,0))+sum(Isnull(it.Qtd_Dep,0)) as Qtd_Sol
                  From PDVCB cb Inner Join 
                       PDVIT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Numero = it.Cod_Pedido)
                  Where cb.Cod_Estabe = @CodEstabe
                  and cb.Tip_Pedido = 'P'
                  and IsNull(cb.Flg_WMS,0) = 0
                  and cb.Status1 = 'P'
                  and cb.Status2 <> 'N'
                  and cb.Status2 <> 'D'
                  and IsNull(cb.Bloqueio,'') <> 'SR'
                  and (IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) > 0
                  Group by it.Cod_Produto, it.Cod_Lote) a ON (lt.Cod_Produt = a.Cod_Produto and lt.Cod_Lote = a.Cod_Lote) Left Outer Join
                  
                 (Select it.Cod_Produt, it.Cod_Lote,
                         sum(Isnull(it.Qtd_LotePra,0))+sum(Isnull(it.Qtd_LoteDep,0)) as Qtd_Sol
                  From PDVCB cb Inner Join
                       PDVLT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Numero = it.Cod_Pedido)
                  Where cb.Cod_Estabe = @CodEstabe
                  and cb.Tip_Pedido = 'P'
                  and IsNull(cb.Flg_WMS,0) = 1
                  and cb.Status1 = 'P'
                  and cb.Status2 <> 'N'
                  and cb.Status2 <> 'D'
                  and IsNull(cb.Bloqueio,'') <> 'SR'
                  and IsNull(it.Qtd_Lote,0) > 0
                  and it.Qtd_CxaFec = 0
                  Group by it.Cod_Produt, it.Cod_Lote) b ON (lt.Cod_Produt = b.Cod_Produt and lt.Cod_Lote = b.Cod_Lote) Left Outer Join
                  
                 (Select Cod_Produto, Cod_Lote,                     
                         sum(Isnull(Qtd_Movimento,0))+sum(Isnull(Qtd_AvaDep,0)) as Qtd_Sol
                  From AVARI
                  Where Cod_Estabe = @CodEstabe
                  Group by Cod_Produto, Cod_Lote) c ON (lt.Cod_Produt = c.Cod_Produto and lt.Cod_Lote = c.Cod_Lote) Left Outer Join
  
                 (Select Cod_Produto, Cod_Lote,                     
                         sum(Isnull(Qtd_Movimento,0))+sum(Isnull(Qtd_ResDep,0)) as Qtd_Sol
                  From RESER
                  Where Cod_Estabe = @CodEstabe
                  Group by Cod_Produto, Cod_Lote) d ON (lt.Cod_Produt = d.Cod_Produto and lt.Cod_Lote = d.Cod_Lote) Left Outer Join
  
                 (Select it.Cod_Produt, it.Cod_Lote,
                         sum(Isnull(it.Qtd_Produt,0)) as Qtd_Sol
                  From ORCCB cb Inner Join
                       ORCIT it on (cb.Cod_Estabe = it.Cod_Estabe and cb.Cod_Orcame = it.Cod_Orcame)
                  Where cb.Cod_Estabe = @CodEstabe
                  And cb.Sta_Movime = 'F'
                  and IsNull(cb.Num_Docume,0) = 0
                  and it.Tip_EntSai = 'S'
                  And IsNull(cb.Cod_OriVen,'') <> 'DMD'
                  and (IsNull(it.Qtd_Produt,0)) > 0
                  Group by it.Cod_Produt, it.Cod_Lote) e ON (lt.Cod_Produt = e.Cod_Produt and lt.Cod_Lote = e.Cod_Lote) 
                  
            Where lt.Cod_Estabe = @CodEstabe      
            And lt.Qtd_Solicitado <> (IsNull(a.Qtd_Sol,0)+IsNull(b.Qtd_Sol,0)+IsNull(c.Qtd_Sol,0)+IsNull(d.Qtd_Sol,0)+IsNull(e.Qtd_Sol,0)))
    begin
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': ===> Existem DIVERGENCIAS DE QUANTIDADES SOLICITADAS: PRLOT x (PDV+AVARI+RESER+ORC)'
      Select lt.Cod_Estabe,
	         lt.Cod_Produt as 'Produto', 
             lt.Cod_Lote as 'Lote', 
             lt.Qtd_Solicitado as 'Qtd.Solicitada em PRLOT', 
             (IsNull(a.Qtd_Sol,0)+IsNull(b.Qtd_Sol,0)+IsNull(c.Qtd_Sol,0)+IsNull(d.Qtd_Sol,0)+IsNull(e.Qtd_Sol,0)) as 'Qtd.Solicida em (PDV+RESER+AVARI+ORC)'
      From (Select Cod_Estabe, Cod_Produt, Cod_Lote, Qtd_Solicitado=SUM(IsNull(Qtd_Solicitado,0))
            From PRLOT
            Where Cod_Estabe = @CodEstabe
            Group by Cod_Estabe, Cod_Produt, Cod_Lote) lt Left Outer Join
  
           (Select it.Cod_Produto, it.Cod_Lote,
                   sum(Isnull(it.Qtd_Pra,0))+sum(Isnull(it.Qtd_Dep,0)) as Qtd_Sol
            From PDVCB cb Inner Join 
                 PDVIT it on (cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Cod_Pedido)
            Where cb.Cod_Estabe = @CodEstabe
            and cb.Tip_Pedido = 'P'
            and IsNull(cb.Flg_WMS,0) = 0
            and cb.Status1 = 'P'
            and cb.Status2 <> 'N'
            and cb.Status2 <> 'D'
            and IsNull(cb.Bloqueio,'') <> 'SR'
            and (IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) > 0
            Group by it.Cod_Produto, it.Cod_Lote) a ON (lt.Cod_Produt = a.Cod_Produto and lt.Cod_Lote = a.Cod_Lote) Left Outer Join
      
           (Select it.Cod_Produt, it.Cod_Lote,
                   sum(Isnull(it.Qtd_LotePra,0))+sum(Isnull(it.Qtd_LoteDep,0)) as Qtd_Sol
            From PDVCB cb Inner Join
                 PDVLT it on (cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Cod_Pedido)
            Where cb.Cod_Estabe = @CodEstabe
            and cb.Tip_Pedido = 'P'
            and IsNull(cb.Flg_WMS,0) = 1
            and cb.Status1 = 'P'
            and cb.Status2 <> 'N'
            and cb.Status2 <> 'D'
            and IsNull(cb.Bloqueio,'') <> 'SR'
            and IsNull(it.Qtd_Lote,0) > 0
            and it.Qtd_CxaFec = 0
            Group by it.Cod_Produt, it.Cod_Lote) b ON (lt.Cod_Produt = b.Cod_Produt and lt.Cod_Lote = b.Cod_Lote) Left Outer Join
            
           (Select Cod_Produto, Cod_Lote,                     
                   sum(Isnull(Qtd_Movimento,0))+sum(Isnull(Qtd_AvaDep,0)) as Qtd_Sol
            From AVARI
            Where Cod_Estabe = @CodEstabe
            Group by Cod_Produto, Cod_Lote) c ON (lt.Cod_Produt = c.Cod_Produto and lt.Cod_Lote = c.Cod_Lote) Left Outer Join
       
           (Select Cod_Produto, Cod_Lote,                     
                   sum(Isnull(Qtd_Movimento,0))+sum(Isnull(Qtd_ResDep,0)) as Qtd_Sol
            From RESER
            Where Cod_Estabe = @CodEstabe
            Group by Cod_Produto, Cod_Lote) d ON (lt.Cod_Produt = d.Cod_Produto and lt.Cod_Lote = d.Cod_Lote) Left Outer Join
                       
           (Select it.Cod_Produt, it.Cod_Lote,
                   sum(Isnull(it.Qtd_Produt,0)) as Qtd_Sol
            From ORCCB cb Inner Join
                 ORCIT it on (cb.Cod_Estabe = it.Cod_Estabe and cb.Cod_Orcame = it.Cod_Orcame)
            Where cb.Cod_Estabe = @CodEstabe
            And cb.Sta_Movime = 'F'
            and IsNull(cb.Num_Docume,0) = 0
            and it.Tip_EntSai = 'S'
            And IsNull(cb.Cod_OriVen,'') <> 'DMD'
            and (IsNull(it.Qtd_Produt,0)) > 0
            Group by it.Cod_Produt, it.Cod_Lote) e ON (lt.Cod_Produt = e.Cod_Produt and lt.Cod_Lote = e.Cod_Lote) 
                       
      Where lt.Cod_Estabe = @CodEstabe      
      And lt.Qtd_Solicitado <> (IsNull(a.Qtd_Sol,0)+IsNull(b.Qtd_Sol,0)+IsNull(c.Qtd_Sol,0)+IsNull(d.Qtd_Sol,0)+IsNull(e.Qtd_Sol,0))
    end
  else
    PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': Estoques Solicitado em PRLOT x (PDV+AVARI+RESER+ORC): ok'



Print ''
Print 'Verifica divergências de quantidades solicitadas: PRLTL x PDVLT :'

  
  -- verifica lotes solicitados em PRLTL
  if Exists(Select lt.Cod_Produt, lt.Cod_Lote, sum(lt.Qtd_Solicitado), x.Qtd_SolTotPdv
            From PRLTL lt 
            Inner Join (Select it.Cod_Produt, it.Cod_Lote,
                              sum(Isnull(it.Qtd_LotePra,0))+sum(Isnull(it.Qtd_LoteDep,0)) as Qtd_SolTotPdv
                       From PDVCB cb, PDVLT it
                       Where cb.Cod_Estabe = it.Cod_Estabe 
                       and cb.Numero = it.Cod_Pedido
                       and cb.Cod_Estabe = @CodEstabe
                       and cb.Tip_Pedido = 'P'
                       and IsNull(cb.Flg_WMS,0) = 1
                       and cb.Status1 = 'P'
                       and cb.Status2 <> 'N'
                       and cb.Status2 <> 'D'
                       and IsNull(cb.Bloqueio,'') <> 'SR'
                       and IsNull(it.Qtd_Lote,0) > 0
                       and it.Qtd_CxaFec > 0
                       Group by it.Cod_Produt, it.Cod_Lote) x on (lt.Cod_Produt = x.Cod_Produt and lt.Cod_Lote = x.Cod_lote)
            Where lt.Cod_Estabe = @CodEstabe
            Group by lt.Cod_Produt, lt.Cod_Lote, x.Qtd_SolTotPdv
            Having sum(lt.Qtd_Solicitado) <> IsNull(x.Qtd_SolTotPdv,0))
    begin
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': ===> Existem DIVERGENCIAS DE QUANTIDADES SOLICITADAS: PRLTL x PDVLT'

      Select lt.Cod_Estabe,
	         lt.Cod_Produt as 'Produto', lt.Cod_Lote as 'Lote', sum(lt.Qtd_Solicitado) as 'Qtd.Solicitada em PRLTL', 
             IsNull(x.Qtd_SolTotPdv,0) as 'Qtd.Solicida em PDVCB'
      From PRLTL lt 
      Inner Join (Select it.Cod_Produt, it.Cod_Lote,
                         sum(Isnull(it.Qtd_LotePra,0))+sum(Isnull(it.Qtd_LoteDep,0)) as Qtd_SolTotPdv
                 From PDVCB cb, PDVLT it
                 Where cb.Cod_Estabe = it.Cod_Estabe 
                 and cb.Numero = it.Cod_Pedido
                 and cb.Cod_Estabe = @CodEstabe
                 and cb.Tip_Pedido = 'P'
                 and IsNull(cb.Flg_WMS,0) = 1
                 and cb.Status1 = 'P'
                 and cb.Status2 <> 'N'
                 and cb.Status2 <> 'D'
                 and IsNull(cb.Bloqueio,'') <> 'SR'
                 and IsNull(it.Qtd_Lote,0) > 0
                 and it.Qtd_CxaFec > 0
                 Group by it.Cod_Produt, it.Cod_Lote) x on (lt.Cod_Produt = x.Cod_Produt and lt.Cod_Lote = x.Cod_lote)
      Where lt.Cod_Estabe = @CodEstabe           
      Group by lt.Cod_Estabe, lt.Cod_Produt, lt.Cod_Lote, x.Qtd_SolTotPdv
      Having sum(lt.Qtd_Solicitado) <> IsNull(x.Qtd_SolTotPdv,0)
    end
  else
    PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': Estoques Solicitado em PRLTL x PDVLT: ok'




Print ''
Print 'Verifica slados negativos em PRLOT:'

  -- verifica saldo negativo em PRLOT
  if Exists(Select Cod_Produt From PRLOT Where Cod_Estabe = @CodEstabe And (Qtd_SldPra < 0) or (Qtd_SldDep < 0))
    begin
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': ===> Existem SALDOS NEGATIVOS EM PRLOT'
      Select Cod_Produt as 'Prd. c/Saldo Negativo (PRLOT)', 
             Cod_Lote,
             Qtd_SldPra as 'Saldo 1', 
             Qtd_SldDep as 'Saldo 2'
      From PRLOT
      Where Cod_Estabe = @CodEstabe 
      And (Qtd_SLdPra < 0) or (Qtd_SldDep < 0)
    end
  else
    PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': Saldos Negativos em PRLOT: ok'

Print ''
Print 'Verifica saldos negativos em PRLTL:'

  -- verifica saldo negativo em PRLTL
  if Exists(Select Cod_Produt From PRLTL Where Cod_Estabe = @CodEstabe And (Qtd_SldPra < 0) or (Qtd_SldDep < 0))
    begin
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': ===> Existem SALDOS NEGATIVOS EM PRLTL'
      Select Cod_Produt as 'Prd. c/Saldo Negativo (PRLTL)', 
             Cod_Lote,
             Qtd_SldPra as 'Saldo 1', 
             Qtd_SldDep as 'Saldo 2'
      From PRLTL
      Where Cod_Estabe = @CodEstabe 
      And (Qtd_SLdPra < 0) or (Qtd_SldDep < 0)
    end
  else
    PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': Saldos Negativos em PRLTL: ok'


Print ''
Print 'Verifica divergências de estoques: PRXES x PRLOT+PRLTL :'

  -- verifica qtd.disponivel de PRXES com saldo em PRLOT
  if Exists(Select p.Cod_Produt From PRXES p Left Outer Join 
                                 PRLOT l on p.Cod_Estabe = l.Cod_Estabe and p.Cod_Produt = l.Cod_Produt Left Outer Join 
                                 PRLTL d on p.Cod_Estabe = d.Cod_Estabe and p.Cod_Produt = d.Cod_Produt
            Where p.Cod_Estabe = @CodEstabe
            and p.Qtd_Dispon > 0
            And l.Cod_Produt is Null And d.Cod_Produt is Null)
    Select p.Cod_Produt as 'Prd.s/Lotes disponíveis', p.Qtd_Dispon as 'Disponível em PRXES'
      From PRXES p Left Outer Join 
           PRLOT l on p.Cod_Estabe = l.Cod_Estabe and p.Cod_Produt = l.Cod_Produt Left Outer Join 
           PRLTL d on p.Cod_Estabe = d.Cod_Estabe and p.Cod_Produt = d.Cod_Produt
      Where p.Cod_Estabe = @CodEstabe
      and p.Qtd_Dispon > 0
      And l.Cod_Produt is Null And d.Cod_Produt is Null
    
  if Exists(Select p.Cod_Produt
              From PRXES p 
                   Left Outer Join
                   (Select Cod_Produt, sum(Qtd_Saldo) as QtdSldFra, sum(Qtd_Solicitado) as QtdSolFra
                      From PRLOT 
                      Where Cod_Estabe = @CodEstabe
                      and ((Qtd_Saldo > 0) or (Qtd_Solicitado > 0))
                      Group by Cod_Produt) l on (p.Cod_Produt = l.Cod_Produt)
                   Left Outer Join
                   (Select Cod_Produt, sum(Qtd_Saldo) as QtdSldDep, sum(Qtd_Solicitado) as QtdSolDep
                      From PRLTL
                      Where Cod_Estabe = @CodEstabe
                      and ((Qtd_Saldo > 0) or (Qtd_Solicitado > 0))
                      Group by Cod_Produt) d on (p.Cod_Produt = d.Cod_Produt)     
            Where p.Cod_Estabe = @CodEstabe 
            and p.Qtd_Dispon+(p.Qtd_Solici+p.Qtd_Reserv+p.Qtd_Avaria-IsNull(QtdSolFra,0)-IsNull(QtdSolDep,0)) <> IsNull(l.QtdSldFra,0)+IsNull(d.QtdSldDep,0))
    begin
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': ===> Existem DIVERGENCIAS DE ESTOQUES: PRXES x PRLOT+PRLTL'
      Select p.Cod_Estabe,
	         p.Cod_Produt as 'Prd.c/divergência (PRXES x PRLOT+PRLTL)', p.Qtd_Dispon as 'Disponível em PRXES', 
             IsNull(l.QtdSldFra,0)+IsNull(d.QtdSldDep,0) as 'Disponível em PRLOT+PRLTL',
             (p.Qtd_Solici+p.Qtd_Reserv+p.Qtd_Avaria-IsNull(QtdSolFra,0)-IsNull(QtdSolDep,0)) as 'Lotes nao solicitados',
             IsNull(l.QtdSldFra,0)+IsNull(d.QtdSldDep,0)-(p.Qtd_Dispon+p.Qtd_Solici+p.Qtd_Reserv+p.Qtd_Avaria-IsNull(QtdSolFra,0)-IsNull(QtdSolDep,0)) as 'Diferença'
        From PRXES p 
             Left Outer Join
            (Select Cod_Produt, sum(Qtd_Saldo) as QtdSldFra, sum(Qtd_Solicitado) as QtdSolFra
               From PRLOT 
               Where Cod_Estabe = @CodEstabe 
               and ((Qtd_Saldo > 0) or (Qtd_Solicitado > 0))
               Group by Cod_Produt) l on (p.Cod_Produt = l.Cod_Produt)
             Left Outer Join
            (Select Cod_Produt, sum(Qtd_Saldo) as QtdSldDep, sum(Qtd_Solicitado) as QtdSolDep
               From PRLTL
               Where Cod_Estabe = @CodEstabe 
               and ((Qtd_Saldo > 0) or (Qtd_Solicitado > 0))
               Group by Cod_Produt) d on (p.Cod_Produt = d.Cod_Produt)
        Where p.Cod_Estabe = @CodEstabe 
        and p.Qtd_Dispon+(p.Qtd_Solici+p.Qtd_Reserv+p.Qtd_Avaria-IsNull(QtdSolFra,0)-IsNull(QtdSolDep,0)) <> IsNull(l.QtdSldFra,0)+IsNull(d.QtdSldDep,0)
        Order by p.Cod_Produt
    end
  else
    PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': Estoque Disponível: PRXES x PRLOT+PRLTL ok!'


PRINT ''
PRINT 'FIM DE VERIFICACAO ...'
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_StrNotasEmpenhoDeContrato]
(
  @PCodEstabe smallint,
  @PNumContra varchar(40),
  @PTamStr int
)

RETURNS varchar(8000)

AS

BEGIN

Declare @Str varchar(max)

Set @Str = ''

if (@PTamStr = 0) or (@PTamStr > 8000)
  Set @PTamStr = 8000  -- tam maximo para varchar

if IsNull(@PNumContra,'') <> ''
  begin
    Select @Str = Case 
                    When (Len(@Str)+Len(Ide_NotEmp)+1) <= @PTamStr then 
                      Substring(IsNull(@Str + ';','') + Ide_NotEmp, 1, @PTamStr)
                    Else 
                      @Str
                  End
      From PDVCB
     Where Cod_Estabe = @PCodEstabe
       And IsNull(Ide_Contra,'') = @PNumContra
       And IsNull(Ide_NotEmp,'') <> ''
     Order by Ide_NotEmp
  end

  -- Retorna o resultado da function
  RETURN @Str
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_AtualizaStatusConsignacao]
@PCodEstabe int,  -- estabelecimento
@PIdConsig int    -- consignação, se 0 atualiza todos

AS

SET NOCOUNT ON 

BEGIN TRANSACTION 

Set DateFormat ymd  
Declare @Date smalldatetime  = cast(GetDate() as date)

-- normaliza CNGIT
Update CNGIT
   Set Qtd_Remess = IsNull(Qtd_Remess,0) + 0
 Where Cod_Estabe = @PCodEstabe
   And Id_Consig = Case When @PIdConsig > 0 then @PIdConsig Else Id_Consig End
   And IsNull(Qtd_Penden,0) <>  (isNull(Qtd_Inicio,0) + IsNull(Qtd_AcrDec,0) - IsNull(Qtd_Remess,0) - IsNull(Qtd_Digita,0) -
                                 IsNull(Qtd_Devolu,0) - IsNull(Qtd_Fatura,0))

--Atualiza Status
Update c
   Set c.Sta_Consig = Case  
                        When NOT EXISTS (Select 1 
                                           From CNGIT i 
                                          Where i.Cod_Estabe = c.Cod_Estabe 
										    and i.Id_Consig = c.Id_Consig 
                                            and ((i.Qtd_Penden > 0) or (i.Qtd_Remess > 0) or (i.Qtd_Digita > 0))
                                            and IsNull(i.Flg_Encerr,0) = 0) Then'F'
                        Else 'P'
                      End
  From CNGCB c 
 Where c.Cod_Estabe = @PCodEstabe
   And c.Id_Consig = Case When @PIdConsig > 0 then @PIdConsig Else c.Id_Consig End
   and ((c.Sta_Consig = 'P') or (c.Sta_Consig = 'F'))

if @@trancount > 0
  COMMIT TRANSACTION 
GO

/*************************************************************************************************/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ManutencaoEstoquePulmao]
@PCodEstabe int,
@PNumProtoc int

AS

SET NOCOUNT ON 

Begin Transaction

-- inclusao
if not Exists(Select 1 From NEXML Where Cod_Estabe = @PCodEstabe and Num_Protoc = @PNumProtoc) and
   Exists(Select 1 From NFECB 
			Where Cod_Estabe = @PCodEstabe 
			   and Protocolo = @PNumProtoc 
			   and Status in('A', 'P')			   
			   and Tip_NF in('C', 'D')			   
			   )
  begin
    Insert Into NEXML (Cod_Estabe, Num_Protoc)
      Select cb.Cod_Estabe, cb.Protocolo
      From NFECB cb
           Left Outer Join NEXML x on cb.Cod_Estabe = x.Cod_Estabe and cb.Protocolo = x.Num_Protoc
      Where cb.Cod_Estabe = @PCodEstabe
	  and cb.Protocolo =  @PNumProtoc
      And cb.Status in ('A', 'P')     
	  and cb.Tip_NF in ('C', 'D')			
      And x.Num_Protoc is null

    if @@rowcount > 0
      Update pr
        Set pr.Qtd_Pulmao = IsNull(pr.Qtd_Pulmao,0) + ne.QtdTot
      From PRXES pr
           Inner Join (Select it.Cod_Estabe, it.Cod_Produto, QtdTot=sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0))
                       From NFEIT it
                            Inner Join NEXML x on it.Cod_Estabe = x.Cod_Estabe and it.Protocolo = x.Num_Protoc
                        Where it.Cod_Estabe = @PCodEstabe
                        And it.Protocolo = @PNumProtoc
                        Group by it.Cod_Estabe, it.Cod_Produto) ne on pr.Cod_Estabe = ne.Cod_Estabe and pr.Cod_Produt = ne.Cod_Produto 
      Where pr.Cod_Estabe = @PCodEstabe

  end

-- exclusao
if Exists(Select 1 From NEXML Where Cod_Estabe = @PCodEstabe and Num_Protoc = @PNumProtoc) and
         ((not Exists(Select 1 From NFECB Where Cod_Estabe = @PCodEstabe and Protocolo = @PNumProtoc)) or 
		  (Exists(Select 1 From NFECB Where Cod_Estabe = @PCodEstabe and Protocolo = @PNumProtoc and Status <> 'A')))
  begin
    Update pr
      Set pr.Qtd_Pulmao = case 
	                        when (IsNull(pr.Qtd_Pulmao,0) > ne.QtdTot) then IsNull(pr.Qtd_Pulmao,0) - ne.QtdTot
                            else 0
                          end
    From PRXES pr
         Inner Join (Select it.Cod_Estabe, it.Cod_Produto, QtdTot=sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0))
                     From NFEIT it
                          Inner Join NEXML x on it.Cod_Estabe = x.Cod_Estabe and it.Protocolo = x.Num_Protoc
                      Where it.Cod_Estabe = @PCodEstabe
					  And it.Protocolo = @PNumProtoc
                      Group by it.Cod_Estabe, it.Cod_Produto) ne on pr.Cod_Estabe = ne.Cod_Estabe and pr.Cod_Produt = ne.Cod_Produto 
    Where pr.Cod_Estabe = @PCodEstabe

    Delete From NEXML 
	Where Cod_Estabe = @PCodEstabe and Num_Protoc = @PNumProtoc

  end

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraNfsFatConsig]
@PCodEstabe int,
@PNumPrt int,
@PCodOpeSai varchar(3),
@PSerNotSai varchar(3) output,
@PNumNotSai int output,
@PMsgErr varchar(8000) output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

Set @PSerNotSai = ''
Set @PNumNotSai = 0
Set @PMsgErr = ''

Set @PCodOpeSai = LTRIM(RTRIM(@PCodOpeSai))

if not Exists(Select 1 From NFECB 
               Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumPrt And Tip_NF = 'D' And Status <> 'A')
  Set @PMsgErr = 'Nota Fiscal de Entrada Não Localizada ou Inválida'
else
-- 5112/6112, 5114/6114: venda mercadoria anteriormente consignada
if not Exists(Select 1 
                From TPOPE 
               Where Tip_EntSai = 'S' 
                 and CharIndex(cast(Cod_CfoNorInt as varchar),';5112;5114;') > 0 
                 and CharIndex(cast(Cod_CfoNorExt as varchar),';6112;6114;') > 0
                 and Cod_Ope = @PCodOpeSai and Tip_Ope = 'V' and IsNull(Flg_Bloqueado,0) = 0)
  Set @PMsgErr = 'Tipo de operação (V/5112;5114/6112;6114) inválido para Venda de Mercadoria Remetida Anteriormente em Consignação'
else
if not Exists(Select 1 From CNGDC Where Cod_Estabe = @PCodEstabe And Num_Protoc = @PNumPrt And Tip_Devolu = 'S')
  Set @PMsgErr = 'Não existe registro de Devolução Simbólica de consignação'
else
if Exists(Select 1 From CNGDC Where Cod_Estabe = @PCodEstabe And Num_Protoc = @PNumPrt And Tip_Devolu = 'S' And IsNull(Num_PedVen,0) > 0)
  Set @PMsgErr = 'Devolução simbólica já foi faturada'
else
begin

Declare @es_CodUF varchar(2) = '',
		@es_FlgContriSubstituido bit = 0,
		@rg_FlgConFin bit = 0,

        @ns_FlgWms bit,
		@ns_CodCfo int = 0,
        @ns_FlgBlqTrfEstFis bit = 0,
        @ns_FlgMovEst bit = 1,

        @ns_IdConsig int = 0,
        @ns_NumSequen smallint = 0,
        @ns_NumSeqDev smallint = 0,
        @ns_CodZonMve integer,

        @ns_CodRegTri int = 0,
        @ns_CodTransp int = 0,

		@ne_Cgc varchar(14) = '',
        @ne_Cgf varchar(15) = '',
		@ne_CodEntid int = 0,
        @ne_TipEntid char(1) = '',

        @ne_Endereco varchar(50) = '',
        @ne_Bairro varchar(20) = '',
        @ne_Cidade varchar(25) = '',
        @ne_Cep varchar(8) = '',
        @ne_CodUfOri varchar(2) = '',
		@ne_CodCidIbge varchar(7),

		@op_TipOpe varchar(1),

        @WFlgConFin bit = 0,
		@UsuInfarma varchar(15)

----------------------------------------------------------------------------------------------------------------------------------
Set @ne_CodEntid = 0
Set @ne_TipEntid = ''
Set @ns_CodRegTri = 0

-- identifica emitente da NF
if Exists(Select 1 From NFECB
           Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumPrt 
             And Cod_EmiFornec > 0) or
   Exists(Select 1 From NFECB
           Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumPrt 
            And Cod_EmiCliente > 0) or
   Exists(Select 1 From NFECB
           Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumPrt 
             And Cod_EmiTransp > 0)
  begin
    Select @ns_CodRegTri = IsNull(ex.Cod_RegTri,0), 
    	   @ns_CodTransp = IsNull(ex.Cod_Transp,0),
           @es_CodUF = es.Des_Estado,
    	   @es_FlgContriSubstituido = IsNull(es.Flg_ContriSubstituido,0),
           @rg_FlgConFin = IsNull(rg.Flg_ConsumFin,0),

           @ne_CodUfOri = IsNull(ne.Cod_UfOrigem,''),
           @ne_Endereco = IsNull(ne.Endereco,''),
           @ne_Bairro = IsNull(ne.Bairro,''),
           @ne_Cidade = IsNull(ne.Cidade,''),
           @ne_Cep = IsNull(ne.Cep,''),
		   @ne_CodCidIbge = IsNull(ne.Cod_CidIbge,''),

    	   @ne_Cgc = IsNull(ne.Cgc_Cpf,''),
           @ne_Cgf = IsNull(ne.Cgf_Rg,''),
           @ne_CodEntid = Case
                            When Cod_EmiFornec  > 0 then Cod_EmiFornec
                            When Cod_EmiCliente > 0 then Cod_EmiCliente
                            When Cod_EmiTransp  > 0 then 0
                            Else 0
                          End,
           @ne_TipEntid = Case
                            When Cod_EmiFornec  > 0 then 'F'
                            When Cod_EmiCliente > 0 then 'C'
                            When Cod_EmiTransp  > 0 then 'T'
                            Else 'X'
                          End
     From NFECB ne
          Inner Join ESTAB es on es.Cod_Estabe = ne.Cod_Estabe
          Left  Join ENXES ex on ex.Cod_Estabe = es.Cod_Estabe and ne.Cgc_Cpf = ex.Num_CgcCpf and
                                 ( (ne.Cod_EmiFornec > 0) and (ne.Cod_EmiFornec = ex.Cod_CadFor) or
                                   (ne.Cod_EmiCliente > 0) and (ne.Cod_EmiCliente = ex.Cod_Client) or
                                   (ne.Cod_EmiTransp > 0) and (ne.Cod_EmiTransp = ex.Cod_CadTra) )
    	  Left  Join RGTRI rg on rg.Cod_RegTri = ex.Cod_RegTri
    Where ne.Cod_Estabe = @PCodEstabe 
      And ne.Protocolo = @PNumPrt
  end

if (@ne_Cgc = '') and
   Exists(Select Num_CgcCpf From ENTID Where Num_CgcCpf = @ne_Cgc)
  begin
    Select @ns_CodRegTri = IsNull(ex.Cod_RegTri,0), 
    	   @ns_CodTransp = IsNull(ex.Cod_Transp,0),
           @es_CodUF = es.Des_Estado,
    	   @es_FlgContriSubstituido = IsNull(es.Flg_ContriSubstituido,0),
           @rg_FlgConFin = IsNull(rg.Flg_ConsumFin,0),

           @ne_Endereco = Substring(dbo.FN_EnderecoCompleto(en.Des_Endere, en.Num_Endere, en.Des_CplEnd),1,50),
  		   @ne_Bairro = Substring(en.Des_Bairro,1,20),
  		   @ne_Cidade = Substring(en.Des_Cidade,1,25),
   	       @ne_CodUfOri = en.Des_Estado,
   		   @ne_Cep = en.Num_Cep,
   		   @ne_CodCidIbge = IsNull(en.Cod_CidIbge,''),

           @ne_Cgc = en.Num_CgcCpf,
           @ne_Cgf = en.Num_CgfRg,
           @ne_CodEntid = 0, 
           @ne_TipEntid = 'X'
      From ENXES ex
           Inner Join ENTID en on en.Num_CgcCpf = ex.Num_CgcCpf 
           Inner Join ESTAB es on es.Cod_Estabe = ex.Cod_Estabe
           Left  Join RGTRI rg on rg.Cod_RegTri = ex.Cod_RegTri
     Where ex.Cod_Estabe = @PCodEstabe
       And ex.Num_CgcCpf = @ne_Cgc
  end

if IsNull(@ns_CodRegTri,0) = 0
  begin
    Select top 1 @ns_CodRegTri = IsNull(ex.Cod_RegTri,0), 
                 @ns_CodTransp = IsNull(ex.Cod_Transp,0),
                 @rg_FlgConFin = IsNull(rg.Flg_ConsumFin,0)
      From NFECB ne
           Inner Join ENXES ex on ex.Cod_Estabe = @PCodEstabe and ne.Cgc_Cpf = ex.Num_CgcCpf
           Left  Join RGTRI rg on rg.Cod_RegTri = ex.Cod_RegTri
     Where ne.Cod_Estabe = @PCodEstabe 
       And ne.Protocolo = @PNumPrt
  end


Select @ns_FlgWms = IsNull(ne.Flg_Wms,0),
       @ns_FlgMovEst = IsNull(ne.Flg_MovEst,0),
       @ns_IdConsig = IsNull(dv.Id_Consig,0),
       @ns_NumSequen = IsNull(dv.Num_Sequen,0),
       @ns_NumSeqDev =  IsNull(dv.Num_SeqDev,0)
  From NFECB ne
       inner Join CNGDC dv on ne.Cod_Estabe = dv.Cod_Estabe And ne.Id_Consig = dv.Id_Consig And ne.Num_SeqCtr = dv.Num_Sequen And ne.Num_SeqDev = dv.Num_SeqDev
 Where ne.Cod_Estabe = @PCodEstabe 
   And ne.Protocolo = @PNumPrt

Set @UsuInfarma = dbo.FN_UsuarioInfarma()

BEGIN TRANSACTION

Select @op_TipOpe = op.Tip_Ope,
       @ns_CodCfo = Case
                      When (@rg_FlgConFin = 1) and (@ne_CodUfOri = @es_CodUF)  then op.Cod_CfoConFinInt
                      When (@rg_FlgConFin = 1) and (@ne_CodUfOri <> @es_CodUF) then op.Cod_CfoConFinExt
                      When (@ne_CodUfOri = @es_CodUF)  then op.Cod_CfoNorInt
                      When (@ne_CodUfOri <> @es_CodUF) then op.Cod_CfoNorExt
                   End
  From TPOPE op
 Where op.Cod_Ope = @PCodOpeSai

Select @ns_FlgBlqTrfEstFis = IsNull(Flg_BlqTrfEstFis,0) 
  From TBCFO 
 Where Codigo = @ns_CodCfo

-- grava cabecalho
Set @PSerNotSai = 'XXX'
if IsNull(@PNumNotSai,0) = 0
  EXEC PR_ProxNumero 'Pedido_Venda', @PNumNotSai output

if not Exists(Select 1 From NFSCB Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNotSai And Num_Nota = @PNumNotSai)
  begin
    Insert Into NFSCB (Cod_Estabe,  Ser_Nota,    Num_Nota,    Status, Usuario,     Transacao)
               Values (@PCodEstabe, @PSerNotSai, @PNumNotSai, 'A',    @UsuInfarma, @Now) 
    if @@error <> 0
      begin
        if @@trancount > 0
          Rollback Transaction
        Return
      end        
  end

if (Select Status From NFSCB Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNotSai And Num_Nota = @PNumNotSai) = 'A'
  begin
    -- grava campos na nota
    Update ns
       Set ns.Cod_Ope = @PCodOpeSai,
           ns.Tip_Saida = @op_TipOpe,
           ns.Cod_Cfo1 = @ns_CodCfo,
           ns.Flg_BlqTrfEstFis  = @ns_FlgBlqTrfEstFis,
           ns.Id_Consig = @ns_IdConsig,
           ns.Num_SequenciaCtr = @ns_NumSequen, 
           ns.Num_SeqDev = @ns_NumSeqDev,
           ns.Cod_ZonMovEst = 0,
        
           ns.Cod_RegTri = @ns_CodRegTri,
           ns.Cod_Transportadora = @ns_CodTransp, 
           ns.Cgc = @ne_Cgc,
           ns.Cgf = @ne_Cgf,
           ns.Cod_Cliente = Case When @ne_TipEntid = 'C' then @ne_CodEntid Else 0 End,
           ns.Cod_Fornecedor  = Case When @ne_TipEntid = 'F' then @ne_CodEntid Else 0 End,
        
           ns.Endereco = @ne_Endereco,
           ns.Estado = @ne_CodUfOri,
           ns.Bairro = @ne_Bairro,
           ns.Cidade = @ne_Cidade,
           ns.Cep = @ne_Cep,
           ns.Cod_CidIbge = @ne_CodCidIbge,
        
           ns.Status= 'A',
           ns.Cod_Pedido = @PNumNotSai,   -- pedido de venda
           ns.Flg_MovEst = @ns_FlgMovEst, -- movimenta estoque
           ns.Dat_Emissao = @Date,
           ns.Flg_WMS = @ns_FlgWms,
        
           ns.Obs_Rodape = '',
           ns.Qtd_Itens = ne.Qtd_Itens,
           ns.Tip_Consumidor = ne.Tip_Consumidor,
           ns.Qtd_Volumes = ne.Qtd_Volumes,
           ns.Qtd_PesBru = ns.Qtd_PesBru,
           ns.Qtd_Peso = ne.Qtd_Peso,
        
           ns.Cod_VendTlmkt = ne.Cod_VendTlmkt,
           ns.Cod_Vendedor = ne.Cod_Vendedor,
            
           ns.Vlr_DescontoCom = IsNull(ne.Vlr_Desconto,0),
           ns.Vlr_OutDsp = 0,
           ns.Per_Comvnd = ne.Per_Comvnd,
           ns.Via_Transp = ne.Via_Transp,
           ns.Tip_Frete = '1',
           ns.Vlr_Frete = 0,
           ns.Vlr_Seguro = 0,
           --ns.Pessoa = ns.Pessoa,
    
           ns.Esp_Nota = 'NF',
           ns.Ser_Selo = '',
    
           ns.Flg_Importado = Case When @op_TipOpe = 'D' then 1 Else 0 End, 
           ns.Chv_Acesso    = Case When @op_TipOpe = 'D' then '' Else ne.Chv_Acesso End,    
           ns.Cod_ModDoc    = Case When @op_TipOpe = 'D' then '' Else ne.Cod_ModDoc End,    
           ns.Tip_DocRel    = Case When @op_TipOpe = 'D' then 'E' Else '' End,
           ns.Str_RelDoc    = Case When @op_TipOpe = 'D' then cast(ne.Protocolo as varchar) Else '' End,
           ns.Cod_FinNfe    = Case When @op_TipOpe = 'D' then '4' Else '1' End --1-Normal  4- devolução
    
      From NFSCB ns, NFECB ne
     Where ns.Cod_Estabe = @PCodEstabe
       And ns.Ser_Nota = @PSerNotSai 
       And ns.Num_Nota = @PNumNotSai

       And ne.Cod_Estabe = @PCodEstabe
       And ne.Protocolo = @PNumPrt
       And ns.Status = 'A'
    
    Delete From NFSIT Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNotSai And Num_Nota = @PNumNotSai

    -- inclui itens
    Insert Into NFSIT (Cod_Estabe, Ser_Nota, Num_Nota, Cod_Produto, Cod_Lote, Num_SeqIte, Tip_Sai)
      Select @PCodEstabe, @PSerNotSai, @PNumNotSai, Cod_Produto, Cod_Lote, Num_SeqIte, ''
        From NFEIT
       Where Cod_Estabe = @PCodEstabe 
         And Protocolo = @PNumPrt
    
    Update ns
       Set ns.Cod_ClaTri = ne.Cod_ClaTri,
           ns.Tip_Aux = ne.Tip_LisPis,
       
           ns.Prc_TabBru = ne.Prc_Venda, 
           ns.Prc_Fabric = ne.Prc_Fabric,
           ns.Prc_MaxCon = ne.Prc_MaxCon,
           ns.Prc_RefFpb = ne.Prc_RefFpb,
       
           ns.Ctrl_Tributacao = ne.Ctrl_Tributacao,
       
           ns.Qtd_Produto = ne.Qtd_Pedido,
           ns.Qtd_Bonificacao = ne.Qtd_Bonificacao,
           ns.Prc_Unitario = ne.Prc_Unitario,
           ns.Per_Desconto = ne.Per_DescItem,
           ns.Flg_BlqDsc = 0,
       
           ns.Fat_CnvImpFat = 1
    
      From NFSIT ns, NFEIT ne, PRODU pr
     Where ns.Cod_Estabe = @PCodEstabe 
       And ns.Ser_Nota = @PSerNotSai 
       And ns.Num_Nota = @PNumNotSai
    
       And ne.Cod_Estabe = @PCodEstabe
       And ne.Protocolo = @PNumPrt
    
       And ne.Cod_Produto = ns.Cod_Produto
       And ne.Cod_Lote = ns.Cod_Lote
       And ne.Num_SeqIte = ns.Num_SeqIte
       And pr.Codigo = ns.Cod_Produto
    
    -- calc fields
    Update NFSIT
       Set Vlr_TotItem = Round(Prc_Unitario*Qtd_Produto*(1-Per_Desconto/100),2),
           Vlr_BruItem = Round(Prc_Unitario*(IsNull(Qtd_Produto,0)+IsNull(Qtd_Bonificacao,0)),2),
           Vlr_DescItem = Round(Prc_Unitario*(IsNull(Qtd_Produto,0)+IsNull(Qtd_Bonificacao,0)),2) - Round(Prc_Unitario*Qtd_Produto*(1-Per_Desconto/100),2)
     Where Cod_Estabe = @PCodEstabe 
      And Ser_Nota = @PSerNotSai 
      And Num_Nota = @PNumNotSai
    
    Update NFSIT
       Set Vlr_LiqItem = IsNull(Vlr_TotItem,0) - IsNull(Vlr_RepIcms,0) - Isnull(Vlr_DescRateado,0) - IsNull(Vlr_DscBonRat,0) - IsNull(Vlr_DscTri,0)
                       + IsNull(Vlr_SubsTrib,0) + IsNull(Vlr_SbtRes,0) + IsNull(Vlr_RecSbt,0) + IsNull(Vlr_Ipi,0) + Isnull(Vlr_DespRateada,0) + Isnull(Vlr_DspExt,0),
           Vlr_LiqVenIte = IsNull(Vlr_TotItem,0) - IsNull(Vlr_RepIcms,0) - Isnull(Vlr_DescRateado,0) - IsNull(Vlr_DscBonRat,0) - IsNull(Vlr_DscTri,0),
           Prc_UniImpFat = Prc_Unitario * Fat_CnvImpFat
     Where Cod_Estabe = @PCodEstabe 
       And Ser_Nota = @PSerNotSai 
       And Num_Nota = @PNumNotSai
    
    Exec PR_AtualizaCfopItemNf @PCodEstabe,@PSerNotSai,@PNumNotSai
    
    -- NFSLT
    Delete From NFSLT
     Where Cod_Estabe = @PCodEstabe 
       And Ser_Nota = @PSerNotSai 
       And Num_Nota = @PNumNotSai

    -- tenta pegar endereços de cross docking da entrada
    if @ns_FlgWms = 1
      begin
        Set @ns_CodZonMve = (Select top 1 dbo.FN_CodZonEnd(lt.Cod_Estabe,lt.Cod_Dep,lt.Num_Rua)
                               From NELTL lt
                              Where lt.Cod_Estabe = @PCodEstabe
                                And lt.Num_Protoc = @PNumPrt
                                And dbo.FN_CodZonEnd(lt.Cod_Estabe,lt.Cod_Dep,lt.Num_Rua) > 0
                                And lt.Tip_Local = 'C')
        Update NFSCB
           Set Cod_ZonMovEst = IsNull(@ns_CodZonMve,0)
         Where Cod_Estabe = @PCodEstabe
           And Ser_Nota = @PSerNotSai 
           And Num_Nota = @PNumNotSai

        Insert Into NFSLT (Cod_Estabe, Ser_Nota, Num_Nota, Num_SeqIte, Cod_Produto, Cod_Lote, 
                           Qtd_Lote, Cod_LocFis, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt) 
          Select ite.Cod_Estabe, @PSerNotSai, @PNumNotSai, ite.Num_SeqIte, ite.Cod_Produto, ite.Cod_Lote, 
                 ite.Qtd_Pedido+ite.Qtd_Bonificacao, 'PRLTL', lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt
            From NFEIT ite
                 Inner Join NELTL lt  on ite.Cod_Estabe = lt.Cod_Estabe and ite.Protocolo = lt.Num_Protoc and ite.Cod_Produto = lt.Cod_Produt and ite.Cod_Lote = lt.Cod_Lote
                 Inner Join NFSIT its on its.Cod_Estabe = ite.Cod_Estabe and its.Cod_Produto = ite.Cod_Produto and its.Cod_Lote = ite.Cod_Lote and its.Num_SeqIte = ite.Num_SeqIte 
                 Inner Join PRLTL pr  on pr.Cod_Estabe = lt.Cod_Estabe and pr.Cod_Produt = lt.Cod_Produt and pr.Cod_Lote = lt.Cod_Lote and pr.Cod_Dep = lt.Cod_Dep and 
	     	                             pr.Num_Rua = lt.Num_Rua and pr.Num_Col = lt.Num_Col and pr.Num_Niv = lt.Num_Niv and pr.Num_Apt = lt.Num_Apt
           Where ite.Cod_Estabe = @PCodEstabe
             And ite.Protocolo = @PNumPrt
        
             And lt.Tip_Local = 'C'  -- cross docking
        
             And pr.Qtd_Saldo >= lt.Qtd_Est
             And its.Cod_Estabe = @PCodEstabe 
             And its.Ser_Nota = @PSerNotSai 
             And its.Num_Nota = @PNumNotSai
      end
  end -- if Status = 'A'

-- calcula tributos  
Exec PR_CalcTributNFSCB @PCodEstabe, @PSerNotSai, @PNumNotSai
if @@error <> 0
  begin
    if @@trancount > 0
      Rollback Transaction
    Return
  end

-- atualiza dados do cabecalho da nota gerada
Exec PR_NormalizaValoresNFS @PCodEstabe, @PSerNotSai, @PNumNotSai
if @@error <> 0
  begin
    if @@trancount > 0
      Rollback Transaction
    Return
  end

-- atualiza status CNGDC
Update CNGDC 
   Set Sta_CngPed = '3',
       Num_PedVen = @PNumNotSai
 Where Cod_Estabe = @PCodEstabe
   And Id_Consig  = @ns_IdConsig 
   And Num_Sequen = @ns_NumSequen 
   And Num_SeqDev = @ns_NumSeqDev

-- PR_FechaNFS: eliminar reserva, se for o caso e atualizar ENDDP(Cod_Control, Num_Control)

if @@trancount > 0
  COMMIT TRANSACTION
end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_FechaNFE]
@CodEstabe int,
@NumPrt int,
@NumSel bigint,
@NumFrm int,
@SerNot varchar(3),
@MsgErr varchar(8000) output

AS

SET NOCOUNT ON
SET ANSI_WARNINGS OFF

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now  = GetDate()
Set @Date = cast(GetDate() as Date)

Set @MsgErr = ''

if (Select Status From NFECB Where Cod_Estabe = @CodEstabe and Protocolo  = @NumPrt) = 'F'
  begin
    Set @MsgErr = 'Nota Fiscal já fechada'
    Return
  end


/*
Status = 'P' : Autorizada
Status = 'O' : Em coleta
Status = 'R' : Coletada
Status = 'T' : Coleta autorizada
Status = 'L' : Em endereçamento
Status = 'E' : Endereçada
*/
Declare @FlgWms bit = 0,
        @FlgMovEst bit = 0,
        @FlgIntWms bit = 0,
        @StaIntWms varchar(1),
        @FlgOpeVdo bit = 0,          -- indica op.triangular, venda à ordem
        @IdOpeVdo int,               -- id da op.triangular
        @NumPrtVincOpeVdo int = 0,
        @FlgDevolOpeVdo bit = 0,     -- indica se é devolução op.triangular
        @MsgAlerta varchar(100) = '',
        @FlgPodeFechar bit = 0
 
Select @FlgIntWms = IsNull(FlgIntegrWmsExt,0) 
  From PMEST 
 Where Cod_Estabe = @CodEstabe
 
Select @FlgWms = IsNull(cb.Flg_WMS,0),
       @FlgMovEst = IsNull(cb.Flg_MovEst,0),
       @StaIntWms = IsNull(cb.Sta_IntWms,''),
       @FlgOpeVdo = IsNull(op.Flg_OpeVdo,0)
  From NFECB cb 
       Left Join TPOPE op on cb.Cod_Ope = op.Cod_Ope
 Where cb.Cod_Estabe = @CodEstabe 
   and cb.Protocolo = @NumPrt
 
if (@FlgMovEst = 1) and (@FlgWms = 1)
  begin
    if Exists(Select top 1 1 
                From (Select Cod_Produto, Cod_Lote, 
                             QtdIte = sum(Qtd_Pedido+Qtd_Bonificacao)
                        From NFEIT 
                       Where Cod_Estabe = @CodEstabe 
                         and Protocolo = @NumPrt
                       Group by Cod_Produto, Cod_Lote ) i
                     Full Join
                     (Select Cod_Produt, Cod_Lote, 
                             QtdLot = IsNull(sum(Qtd_Est),0)
                        From NELTL
                       Where Cod_Estabe = @CodEstabe 
                         and Num_Protoc = @NumPrt
                       Group by Cod_Produt, Cod_Lote ) l on i.Cod_Produto = l.Cod_Produt and i.Cod_Lote = l.Cod_Lote
               Where IsNull(i.QtdIte,0) <> IsNull(l.QtdLot,0) )
      begin
        Set @MsgErr = 'Nota Fiscal com inconsistências nas quantidades para armazenagem'
        Return
      end
     
    if Exists(Select top 1 1
                From NELTL
               Where Cod_Estabe = @CodEstabe 
                 and Num_Protoc = @NumPrt
                 and Tip_Local <> dbo.FN_TipLocEnd(Cod_Estabe, Cod_Dep, Num_Rua) )
      begin
        Set @MsgErr = 'Nota Fiscal com inconsistência na Estrutura para endereçamento com endereço'
        Return
      end
  end  -- if (@FlgMovEst = 1) and (@FlgWms = 1)

if Exists(Select 1 
            From NFECB cb 
                 Inner Join CNGDC dv on cb.Cod_Estabe = dv.Cod_Estabe and cb.Id_Consig  = dv.Id_Consig and
                                        cb.Num_SeqCtr = dv.Num_Sequen and cb.Num_SeqDev = dv.Num_SeqDev 
           Where cb.Cod_Estabe = @CodEstabe 
             and cb.Protocolo = @NumPrt
             and ((cb.Tip_NF <> 'D') or (Cod_FinNfe <> '4')))
    begin
      Set @MsgErr = 'Nota Fiscal com Tipo/Finalidade inválida '
      Return
    end

if Exists(Select 1 
            From NFECB cb 
                 Inner Join CNGDC dv on cb.Cod_Estabe = dv.Cod_Estabe and cb.Id_Consig  = dv.Id_Consig and
                                        cb.Num_SeqCtr = dv.Num_Sequen and cb.Num_SeqDev = dv.Num_SeqDev 
           Where cb.Cod_Estabe = @CodEstabe 
             and cb.Protocolo = @NumPrt
             and cb.Tip_NF = 'D'
             and dv.Tip_Devolu = 'S') 
  if not Exists(Select 1 From TPOPE 
                 Where Tip_EntSai = 'S' 
                   and CharIndex(cast(Cod_CfoNorInt as varchar),';5112;5114;') > 0 
                   and CharIndex(cast(Cod_CfoNorExt as varchar),';6112;6114;') > 0
                   and Tip_Ope = 'V' and IsNull(Flg_Bloqueado,0) = 0)
    begin
      Set @MsgErr = 'Não existe Operação configurada para Venda de Mercadoria Remetida Anteriormente em Consignação '
      Return
    end
 
if Exists(Select 1 
            From NFECB cb 
                 inner Join TPOPE op on cb.Cod_Ope = op.Cod_Ope         
           Where cb.Cod_Estabe = @CodEstabe 
             and cb.Protocolo = @NumPrt
             and IsNull(op.Flg_OpeVdo,0) = 1				 )
  begin
    Exec PR_CriticaOperacaoTriangular @CodEstabe, @NumPrt, '', 'E', @MsgAlerta output, @MsgErr output
  end
 
if @MsgErr <> ''
  Return
 
if @MsgErr = ''
  BEGIN
    Begin Transaction

    -- cria arq. temporario
    IF OBJECT_ID('tempdb..#ARQ_NELTL') IS NOT NULL
      DROP TABLE #ARQ_NELTL
 
    CREATE TABLE #ARQ_NELTL
    (
     Chave int identity,
     Cod_Prd int,
     Cod_Lot varchar(20),
     Tip_Loc varchar(1),
     Cod_Dep smallint,
     Num_Rua smallint,
     Num_Col smallint,
     Num_Niv smallint,
     Num_Apt smallint,
     Qtd_Lot int,
     Qtd_EmbFec int,
    ) 

    Set @FlgPodeFechar = 0

    if (@FlgWms = 0) or (@FlgMovEst = 0)
      Set @FlgPodeFechar = 1
    else
    if (@FlgIntWms = 0) and (@StaIntWms = '')
      Set @FlgPodeFechar = 1
    else
	if @FlgIntWms = 1
      begin
        if @StaIntWms = '1'
          Set @FlgPodeFechar = 1
	 else
          begin
            Update NFECB
               Set Sta_IntWMS = '0'
             Where Cod_Estabe = @CodEstabe 
               And Protocolo = @NumPrt
               And IsNull(Sta_IntWMS,'') = ''

            Exec PR_WMSGerarXMLEntrada @CodEstabe, @NumPrt
          end
      end

    -- registra documentos relacionados
    Exec PR_RegistraNEREF @CodEstabe, @NumPrt
    if @@error <> 0
      begin
        if @@trancount > 0
          RollBack Transaction
        Return
      end
  
    if @FlgOpeVdo = 1
      Exec PR_IncluiOPVDO @CodEstabe, @NumPrt, '', 'E', @IdOpeVdo output
  
    if @IdOpeVdo > 0
      Select top 1 
             @NumPrtVincOpeVdo = IsNull(rf.Num_DocRef,0),
             @FlgDevolOpeVdo   = Case
                                   When cb.Tip_NF  = 'D' then 1
                                   When cbv.Tip_NF = 'D' then 1
                                   Else 0
                                 End
        From NFECB cb
             inner Join NEREF rf  on cb.Cod_Estabe = rf.Cod_Estabe
                                 and cb.Protocolo = rf.Protocolo 
                                 and rf.Tip_EntSai = 'E' 
             inner join NFECB cbv on rf.Cod_Estabe = cbv.Cod_Estabe
                                 and rf.Num_DocRef = cbv.Protocolo
       Where cb.Cod_Estabe = @CodEstabe
         And cb.Protocolo = @NumPrt

    if @FlgPodeFechar = 1
      Begin 
          
        Declare @KCfoBonEntInt int = 1910,
                @KCfoBonEntExt int = 2910,		         
                @TipNfe varchar(1),
                @TipNfsRef varchar(1),
                @StaNfe varchar(1),
                @CodModDoc varchar(2),
                @CodRegTri int,
                @CodOpe varchar(3),
                @CodCfo int,
                @FlgBlqTrfEstFis bit,
                @CodUf char(2),
                @NumPed int,
                @FlgImpNot bit,
                @FlgDevTot bit,
                @CodEmiFor int,
                @CodEmiTra int,
                @CodEmiCli int,
                @CodVdr int,
                @CodVdrTlmkt int,
                @CodSup int,                  
                @TipEmi char(3),
                @CodEmi int,
                @ValNot numeric(18,4),
                @ValDspEmb numeric(18,4),
                @IdPdvCon int,
                @FlgReservConsig bit = 0,  -- reserva itens consignados quando for NF de devolução simbólica sem WMS
                @FlgFaturaConsig bit = 0,  -- gera fatura de consignados quando for NF de devolução simbólica
                @IdConsig int = 0,
                @NumSeqCtr smallint = 0,
                @NumSeqDev smallint = 0,
                @NumReserv int = 0,
                @DesHisReserv varchar(40) = '',
                @CodTipDevCng varchar(3) = '',
                @CodOpeSai varchar(3) = '',
                @IdTransacao int,
                @Usuario varchar(15),
                @DesMovime varchar(60),
                @Chave int,
                @CodPrd int,
                @CodLot varchar(20),
                @NumSeqIte smallint,
                @TipEnt varchar(1),
                @DatMov smalldatetime,
                @DatVct smalldatetime,
                @DatFab smalldatetime,
                @TipLoc varchar(1),
                @CodDep smallint,
                @NumRua smallint,
                @NumCol smallint,
                @NumNiv smallint,
                @NumApt smallint,
                @QtdPed int,
                @QtdBon int,
                @PrcUni numeric(18,8),
                @QtdEmbFec smallint,
                @QtdEst int,
                @QtdMov int,
                @QtdMovSld int,
                @CodPrm int,
                @QtdPrm int,
                @QtdPra int,
                @QtdDep int,
                @CusLiqUni numeric(18,4),
                @ValLiq numeric(18,4),
                @ValCusMed numeric(18,4),
                @ValPrcFab numeric(18,4),
                @VlrVerbaVdr numeric(18,4),
                @VlrVerbaSup numeric(18,4),
                @VlrVerbaOpe numeric(18,4),
                @VlrVerbaFor numeric(18,4),
                @QtdSldFis int,
                @WCodDoc int,
                @WCodOri varchar(20),
                @SerNotSai varchar(3),
                @NumNotSai int,
                @CodFab int,
                @QtdPrzMed numeric(18,4),
                @FlgDevChv Bit,
                @WIsnCtaFinEntid int,

                @em_CodEst varchar(2),
                @em_FlgContriSubstituido bit,
                @pm_NumItePagNfs int,
                @pm_FlgCtrSelFis bit,
                @pm_ModeloNotaFiscal varchar(3),
                @pm_SerieSeloFiscal varchar(2),
                @pm_FlgNfe bit,
                @pm_FlgUsaPrcCusLiqEnt bit,
                @pm_FlgManDupDevTotVen bit = 0,
                @pm_QtdDecPrcItePdv smallint,
                @pm_FlgDbqPrdVenAutEntCmp bit,
                @pm_FlgUsaInterv bit,
                @to_IsnCtaFinDeb int,
                @to_IsnCtaFinCre int,
                @to_IsnCtaFinCreInterv int,
                @to_IsnCtaFinDebInterv int,
                @pc_Controle_Saldo varchar(1),
                @pc_FlgAcuVrbPos bit,
                @pc_FlgAcuVrbNeg bit,
		        @pc_FlgCtrPdvVrbVdr bit,
		        @pc_FlgCtrPdvVrbOpe bit

        -- cfop bonificacao entrada
        Set @KCfoBonEntInt = 1910
        Set @KCfoBonEntExt = 2910
        Set @TipNfsRef = ''
                  
        -- poe dados da nf na memoria
        Select @TipNfe = cb.Tip_NF,  
               @StaNfe = cb.Status, 
               @CodModDoc = IsNull(cb.Cod_ModDoc,''),
               @DatMov = cb.Dat_Movimento,
               @CodRegTri = Isnull(cb.Cod_RegTri,0),
               @CodOpe = IsNull(cb.Cod_Ope,''),
               @CodCfo = Isnull(cb.Cod_Cfo,0),
               @FlgBlqTrfEstFis = cf.Flg_BlqTrfEstFis,
               @CodUf = Upper(cb.Cod_UfOrigem),
               @FlgMovEst = IsNull(cb.Flg_MovEst,0),
               @FlgImpNot = IsNull(cb.Flg_ImpNot,0),
               @FlgDevTot = IsNull(cb.Flg_DevTot,0),
               @CodEmiFor = IsNull(cb.Cod_EmiFornec,0),
               @CodEmiTra = IsNull(cb.Cod_EmiTransp,0),
               @CodEmiCli = IsNull(cb.Cod_EmiCliente,0),
               @CodVdr = IsNull(cb.Cod_Vendedor,0), 
               @CodVdrTlmkt = IsNull(cb.Cod_VendTlmkt,0),
               @CodSup = IsNull(ve.Cod_Supervisor,0),
               @ValNot = IsNull(cb.Vlr_Nota,0),
               @IdPdvCon = IsNull(cb.Id_PdvCon,0),

               @FlgReservConsig = Case 
                                    When (cb.Tip_NF = 'D') and (IsNull(cb.Flg_WMS,0) = 0) and 
                                          (IsNull(dv.Id_Consig,0) > 0) and (dv.Tip_Devolu = 'S') then 1 
                                    Else 0 
                                  End,
               @FlgFaturaConsig = Case 
                                    When (cb.Tip_NF = 'D') and 
                                         (IsNull(dv.Id_Consig,0) > 0) and (dv.Tip_Devolu = 'S') then 1 
                                    Else 0 
                                  End,
               @IdConsig        = Case 
                                    When (cb.Tip_NF = 'D') and (IsNull(dv.Id_Consig,0) > 0) then cb.Id_Consig 
                                    Else 0 
                                  End,
               @NumSeqCtr       = Case 
                                    When (cb.Tip_NF = 'D') and (IsNull(dv.Id_Consig,0) > 0) then cb.Num_SeqCtr 
                                    Else 0 
                                  End,
               @NumSeqDev       = Case 
                                    When (cb.Tip_NF = 'D') and (IsNull(dv.Id_Consig,0) > 0) then cb.Num_SeqDev 
                                    Else 0 
                                  End

          From NFECB cb
               left join TBCFO cf on cb.Cod_Cfo = cf.Codigo
               left join VENDE ve on cb.Cod_Vendedor = ve.Codigo
               left join CNGDC dv on cb.Cod_Estabe = dv.Cod_Estabe and cb.Id_Consig  = dv.Id_Consig and
                                     cb.Num_SeqCtr = dv.Num_Sequen and cb.Num_SeqDev = dv.Num_SeqDev 
         Where cb.Cod_Estabe = @CodEstabe 
           and cb.Protocolo = @NumPrt

        Set @Usuario = dbo.FN_UsuarioInfarma()

        Select @em_CodEst = Des_Estado,
               @em_FlgContriSubstituido = IsNull(Flg_ContriSubstituido,0)
          From ESTAB
         Where Cod_Estabe = @CodEstabe  
          
        -- coloca campos PARAM na memoria
        Select @pm_NumItePagNfs = IsNull(NumItePagNfs,0),
               @pm_FlgCtrSelFis = IsNull(FlgCtrSelFis,0),
               @pm_ModeloNotaFiscal = ModeloNotaFiscal,
               @pm_SerieSeloFiscal = SerieSeloFiscal,
               @pm_FlgNfe = IsNull(FlgNfe,0),
               @pm_FlgUsaPrcCusLiqEnt = IsNull(FlgUsaPrcCusLiqEnt,0),
               @pm_FlgManDupDevTotVen = IsNull(FlgManDupDevTotVen, 0),
               @pm_QtdDecPrcItePdv = IsNull(QtdDecPrcItePdv,2),
               @pm_FlgDbqPrdVenAutEntCmp = IsNull(FlgDbqPrdVenAutEntCmp,0)
          From PARAM    
         Where Cod_Estabe = @CodEstabe

        -- coloca campos TPOPE na memoria
        Select @pm_FlgUsaInterv = IsNull(FlgUsaInterv,0)
          From PMFIN
            
        Select @to_IsnCtaFinDeb = ISNULL(Isn_CtaFinDeb,0),
               @to_IsnCtaFinCre = ISNULL(Isn_CtaFinCre,0)
          From TPOPE
         Where Cod_Ope = @CodOpe
          
        -- configura cod. origem (WMS)
        Set @WCodOri = ''
        if @TipNfe = 'C'
          Set @WCodOri = 'ENT_COM'
        else  
        if @TipNfe = 'D'
          Set @WCodOri = 'ENT_DEV'
        else  
        if @TipNfe = 'T'
          Set @WCodOri = 'ENT_TRF'
        else  
        if @TipNfe = 'O'
          Set @WCodOri = 'ENT_OUT'
        
        -- poe na memoria conta da entidade para ser armazenada na tabela VALES
        Set @WIsnCtaFinEntid = 0
        if @CodEmiFor > 0
          Set @WIsnCtaFinEntid = IsNull((Select Isn_CtaFin From FORNE Where Codigo = @CodEmiFor),0)
        else
        if @CodEmiTra > 0  
          Set @WIsnCtaFinEntid = IsNull((Select Isn_CtaFin From TRANS Where Codigo = @CodEmiTra),0)
        else
        if @CodEmiCli > 0  
          Set @WIsnCtaFinEntid = IsNull((Select Isn_CtaFin From CLIEN Where Codigo = @CodEmiCli),0)
        
        -- plano de contas
        Set @to_IsnCtaFinCreInterv = 0
        Set @to_IsnCtaFinDebInterv = 0
        if @pm_FlgUsaInterv = 1
          begin
            if (@to_IsnCtaFinCre = (Select IsnCtaFinPagFor From PMFIN)) and (@CodEmiFor > 0)
              Set @to_IsnCtaFinCreInterv = @WIsnCtaFinEntid
                  
            if (@to_IsnCtaFinCre = (Select IsnCtaFinPagTra From PMFIN)) and (@CodEmiTra > 0)
              Set @to_IsnCtaFinCreInterv = @WIsnCtaFinEntid
                  
            if (@to_IsnCtaFinCre = (Select IsnCtaFinRecCli From PMFIN)) and (@CodEmiCli > 0)
              Set @to_IsnCtaFinCreInterv = @WIsnCtaFinEntid
                  
            if @to_IsnCtaFinCreInterv > 0
              Set @to_IsnCtaFinCre = @to_IsnCtaFinCreInterv 
              
            if (@to_IsnCtaFinDeb = (Select IsnCtaFinPagFor From PMFIN)) and (@CodEmiFor > 0)
              Set @to_IsnCtaFinDebInterv = IsNull((Select Isn_CtaFin From FORNE Where Codigo = @CodEmiFor),0)
                  
            if (@to_IsnCtaFinDeb = (Select IsnCtaFinPagTra From PMFIN)) and (@CodEmiTra > 0)
              Set @to_IsnCtaFinDebInterv = IsNull((Select Isn_CtaFin From TRANS Where Codigo = @CodEmiTra),0)
                  
            if (@to_IsnCtaFinDeb = (Select IsnCtaFinRecCli From PMFIN)) and (@CodEmiCli > 0)
              Set @to_IsnCtaFinDebInterv = IsNull((Select Isn_CtaFin From CLIEN Where Codigo = @CodEmiCli),0)
                  
            if @to_IsnCtaFinDebInterv > 0
              Set @to_IsnCtaFinDeb = @to_IsnCtaFinDebInterv 
              
            if not Exists(Select 1 From PCFIN Where Isn_CtaFin = @to_IsnCtaFinCre And Tip_CtaFin = 'A')
              Set @to_IsnCtaFinCre = 0
            if not Exists(Select 1 From PCFIN Where Isn_CtaFin = @to_IsnCtaFinDeb And Tip_CtaFin = 'A')
              Set @to_IsnCtaFinDeb = 0
        
            if (@to_IsnCtaFinDeb = 0) or (@to_IsnCtaFinCre = 0)
              begin
                if @@trancount > 0
                  RollBack Transaction
                RAISERROR('Pelo menos uma conta gerencial envolvida é inválida',16,1)
                Return
              end              
              
            if (@TipNfe = 'D') and (@FlgMovEst = 1) and            
                not Exists(Select pm.IsnCtaFinDespVal 
                             From PMFIN pm Inner Join
                                  PCFIN pc on pm.IsnCtaFinDespVal  = pc.Isn_CtaFin
                            Where pc.Tip_CtaFin = 'A')     
              begin
                if @@trancount > 0
                  RollBack Transaction
                RAISERROR('Parâmetro Financeiro Conta (CREDITOS A CONCEDER) não configurada',16,1)
                Return
              end              
                
          end  -- if @pm_FlgUsaInterv = 1
        else
          begin
            Set @to_IsnCtaFinDeb = 0
            Set @to_IsnCtaFinCre = @WIsnCtaFinEntid
            Set @to_IsnCtaFinDeb = @to_IsnCtaFinCre  -- igualando debito/credito em 26/06/2015
          end
                   
        -- calcula custo liquido
        Update NFEIT
           Set Vlr_LiqIte = dbo.FN_ValLiqIteNFEIT(Cod_Estabe,
                                                  Protocolo,
                                                  Cod_Produto,
                                                  Cod_Lote,
                                                  Num_SeqIte),
               Cus_LiqUni = dbo.FN_CusLiqUniNFEIT(Cod_Estabe,
                                                  Protocolo,
                                                  Cod_Produto,
                                                  Cod_Lote,
                                                  Num_SeqIte)
         Where Cod_Estabe = @CodEstabe 
           and Protocolo = @NumPrt
        
        -- atualiza cadastro de produtos
        Update pr
           Set pr.Flg_BlqVen = 0
          From NFEIT it Inner Join 
               PRXES pr on it.Cod_Estabe = pr.Cod_Estabe And it.Cod_Produto = pr.Cod_Produt
         Where it.Cod_Estabe = @CodEstabe 
           And it.Protocolo = @NumPrt 
           And @TipNfe = 'C'
           And @FlgMovEst = 1
           And IsNull(@pm_FlgDbqPrdVenAutEntCmp,0) = 1
           And IsNull(pr.Flg_BlqVen,0) = 1

        Update it 
           Set it.Val_PrcVen = Round(it.Cus_LiqUni*(1+IsNull(it.Per_Markup,0)/100),@pm_QtdDecPrcItePdv)
          From NFEIT it 
         Where it.Cod_Estabe = @CodEstabe 
           and it.Protocolo = @NumPrt
           And IsNull(it.Flg_PrcVen,0) = 1
           And IsNull(it.Cus_LiqUni,0) > 0
           And @pm_FlgUsaPrcCusLiqEnt = 1

        Update pr
           Set pr.Prc_VenAnt = case 
                                 When @DatMov > pr.Dat_PrcAtual then pr.Prc_Venda
                                 else pr.Prc_VenAnt
                               end,
               pr.Dat_PrcAnt = case 
                                 When @DatMov > pr.Dat_PrcAtual then pr.Dat_PrcAtual
                                 else pr.Dat_PrcAnt
                               end,
               pr.Prc_Venda = it.Val_PrcVen,
               pr.Dat_PrcAtual = @DatMov,
               pr.Usuario = @Usuario,
               pr.Transacao = @Now
          From NFEIT it Inner Join 
               PRXES pr on it.Cod_Estabe = pr.Cod_Estabe And it.Cod_Produto = pr.Cod_Produt 
         Where it.Cod_Estabe = @CodEstabe 
           And it.Protocolo = @NumPrt 
           And IsNull(it.Flg_PrcVen,0) = 1
           And IsNull(it.Val_PrcVen,0) > 0
           And IsNull(@pm_FlgUsaPrcCusLiqEnt,0) = 1

        -- seta o status de fechado
        Set @StaNfe = 'F'
        Update NFECB
           Set Status = @StaNfe,
               Flg_BlqTrfEstFis = IsNull(@FlgBlqTrfEstFis,0),
               Id_OpeVdo = @IdOpeVdo,
               Transacao = @Now
         Where Cod_Estabe = @CodEstabe 
           and Protocolo = @NumPrt

        if @IdOpeVdo > 0
          Update NFECB
             Set Id_OpeVdo = @IdOpeVdo
         Where Cod_Estabe = @CodEstabe 
           and Protocolo = @NumPrtVincOpeVdo

        -- atribui Protoclo de Entrada ao endereço de Cross Docking
        Update ed
           Set ed.Cod_Cntrol = 'NFE'
             , ed.Num_Cntrol =  cb.Protocolo 
          From NFECB cb
               inner join ENDDP ed on cb.Cod_Estabe = ed.Cod_Estabe and cb.Id_EndDep = ed.Id_EndDep
         Where cb.Cod_Estabe = @CodEstabe
           and cb.Protocolo = @NumPrt
           and IsNull(cb.Flg_CrossDocking,0) = 1

        -- reabre pedido de compra
        -- if @TipNfe = 'C'
        -- pedido de compra atualizado se na NF atual a Flg_MovEst = 1
        if @FlgMovEst = 1
          begin
            if Exists(Select 1 From NFEPC Where Cod_Estabe = @CodEstabe and Protocolo = @NumPrt)
              begin
                Declare Nfepc_Cr Cursor Local Fast_Forward For 
                  Select n.Cod_Pedido
                    From NFEPC n
	    			       Inner Join PDCCB p on n.Cod_Estabe = p.Cod_Estabe and n.Cod_Pedido = p.Numero
                    Where n.Cod_Estabe = @CodEstabe
                      And n.Protocolo = @NumPrt
               end
             else
               begin
                 Declare Nfepc_Cr Cursor Local Fast_Forward For 
                   Select n.Cod_Pedido
                     From NFEPC n
	    			       Inner Join PDCCB p on n.Cod_Estabe = p.Cod_Estabe and n.Cod_Pedido = p.Numero
                   Where n.Cod_Estabe = @CodEstabe
                     And n.Protocolo = @NumPrtVincOpeVdo
              end
            Open Nfepc_Cr
            Fetch Next From Nfepc_Cr Into @NumPed
           While @@FETCH_STATUS = 0
             begin
               Exec PR_ReabrePDC @CodEstabe, @NumPed
               Fetch Next From Nfepc_Cr  Into @NumPed
             end
           Close Nfepc_Cr
           Deallocate Nfepc_Cr
         end  -- @FlgMovEst = 1

        -- atualiza cadastro de produtos
        Update pr
           Set pr.Prc_VenAnt = case 
                                 When @DatMov > pr.Dat_PrcAtual then pr.Prc_Venda
                                 else pr.Prc_VenAnt
                               end,
               pr.Dat_PrcAnt = case 
                                 When @DatMov > pr.Dat_PrcAtual then pr.Dat_PrcAtual
                                 else pr.Dat_PrcAnt
                               end,
               pr.Prc_Venda = it.Val_PrcVen,
               pr.Dat_PrcAtual = @DatMov,
               pr.Usuario = @Usuario,
               pr.Transacao = @Now
          From NFEIT it Inner Join 
               PRXES pr on it.Cod_Estabe = pr.Cod_Estabe And it.Cod_Produto = pr.Cod_Produt
         Where it.Cod_Estabe = @CodEstabe 
           And it.Protocolo = @NumPrt 
           And IsNull(it.Flg_PrcVen,0) = 1
           And IsNull(it.Val_PrcVen,0) > 0
           And IsNull(@pm_FlgUsaPrcCusLiqEnt,0) = 0
          
        -- atualiza cadastro de produtos somente em entradas por compra
        Update pr
           Set pr.Per_Ipi = it.Alq_Ipi
          From NFEIT it Inner Join 
               PRODU pr on it.Cod_Produto = pr.Codigo
         Where it.Cod_Estabe = @CodEstabe 
           And it.Protocolo = @NumPrt 
           And @TipNfe = 'C'

        Update pr
           Set pr.Prc_CusLiqEnt = x.CusUniMedNfe,
               pr.Prc_EntAnt = pr.Prc_UltEnt,
               pr.Per_DscEntAnt = pr.Per_DscUltEnt,
               pr.Qtd_EntAnt = pr.Qtd_UltEnt,
               pr.Dat_EntAnt = pr.Dat_UltCompra,
               pr.Prc_UltEnt = x.PrcUniMedNfe,
               pr.Per_DscUltEnt = x.DscUniMedNfe,
               pr.Qtd_UltEnt = x.QtdTotNfe,
               pr.Dat_UltCompra = x.Dat_Movimento
          From PRXES pr Inner Join 
               (Select cb.Dat_Movimento, it.Cod_Estabe, it.Cod_Produto, 
                       sum(it.Qtd_Pedido+it.Qtd_Bonificacao) as QtdTotNfe,
                       sum(it.Cus_LiqUni*(it.Qtd_Pedido+it.Qtd_Bonificacao))/sum(it.Qtd_Pedido+it.Qtd_Bonificacao) as CusUniMedNfe,
                       sum(it.Prc_Unitario*(it.Qtd_Pedido+it.Qtd_Bonificacao))/sum(it.Qtd_Pedido+it.Qtd_Bonificacao) as PrcUniMedNfe,
                       sum(it.Per_DescItem*it.Prc_Unitario*(it.Qtd_Pedido+it.Qtd_Bonificacao))/sum(it.Prc_Unitario*(it.Qtd_Pedido+it.Qtd_Bonificacao)) as DscUniMedNfe
                  From NFECB cb Inner Join NFEIT it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo))
                 Where cb.Cod_Estabe = @CodEstabe 
                   and cb.Protocolo = @NumPrt 
                   and cb.Flg_AtuPrcCus = 1 and cb.Flg_MovEst = 1 and cb.Cod_Cfo > 0
                 Group by cb.Dat_Movimento, it.Cod_Estabe, it.Cod_Produto) x ON pr.Cod_Estabe = x.Cod_Estabe And pr.Cod_Produt = x.Cod_Produto
          
        Update pr
           Set pr.Prc_CusLiqEntDep = x.CusUniMedNfe,
               pr.Prc_EntAntDep = pr.Prc_UltEntDep,
               pr.Per_DscEntAntDep = pr.Per_DscUltEntDep,
               pr.Qtd_EntAntDep = pr.Qtd_UltEntDep,
               pr.Dat_EntAntDep = pr.Dat_UltEntDep,
               pr.Prc_UltEntDep = x.PrcUniMedNfe,
               pr.Per_DscUltEntDep = x.DscUniMedNfe,
               pr.Qtd_UltEntDep = x.QtdTotNfe,
               pr.Dat_UltEntDep = x.Dat_Movimento
          From PRXES pr Inner Join 
               (Select cb.Dat_Movimento, it.Cod_Estabe, it.Cod_Produto, 
                       sum(it.Qtd_Pedido+it.Qtd_Bonificacao) as QtdTotNfe,
                       sum(it.Cus_LiqUni*(it.Qtd_Pedido+it.Qtd_Bonificacao))/sum(it.Qtd_Pedido+it.Qtd_Bonificacao) as CusUniMedNfe,
                       sum(it.Prc_Unitario*(it.Qtd_Pedido+it.Qtd_Bonificacao))/sum(it.Qtd_Pedido+it.Qtd_Bonificacao) as PrcUniMedNfe,
                       sum(it.Per_DescItem*it.Prc_Unitario*(it.Qtd_Pedido+it.Qtd_Bonificacao))/sum(it.Prc_Unitario*(it.Qtd_Pedido+it.Qtd_Bonificacao)) as DscUniMedNfe
                  From NFECB cb Inner Join NFEIT it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo))
                 Where cb.Cod_Estabe = @CodEstabe 
                   and cb.Protocolo = @NumPrt 
                   and cb.Flg_AtuPrcCus = 1 and cb.Flg_MovEst = 1 and (Isnull(cb.Cod_Cfo,0) = 0)
                 Group by cb.Dat_Movimento, it.Cod_Estabe, it.Cod_Produto) x ON pr.Cod_Estabe = x.Cod_Estabe And pr.Cod_Produt = x.Cod_Produto
        
        --  guarda no item estoque e custo medio anterior a entrada
        Update it
           Set it.Prc_CusMedAnt = pr.Prc_CusMed,
               it.Vlr_BasCalSubTriEntMedAnt = pr.Vlr_BasCalSubTriEntMed,
               it.Qtd_FisAnt = case 
                                 When pr.Qtd_Fisico > 0 then pr.Qtd_Fisico
                                 else 0
                               end
          From NFEIT it Inner Join 
               NFECB cb on ((it.Cod_Estabe = cb.Cod_Estabe) and (it.Protocolo = cb.Protocolo)) Inner Join 
               PRXES pr on it.Cod_Estabe = pr.Cod_Estabe And it.Cod_Produto = pr.Cod_Produt
         Where cb.Cod_Estabe = @CodEstabe 
           and cb.Protocolo = @NumPrt
          
        -- base de calculo medio ST: compras, transferencias e bonificacoes
        Update pr
           Set pr.Vlr_BasCalSubTriEntMed = case
                                             when ((pr.Vlr_BasCalSubTriEntMed = 0) or (pr.Qtd_Fisico <= 0)) then x.BasCalSubTriMedNfe
                                             else (pr.Vlr_BasCalSubTriEntMed*pr.Qtd_Fisico + x.BasCalSubTriMedNfe*x.QtdTotNfe)/(pr.Qtd_Fisico+x.QtdTotNfe)
                                           end
          From PRXES pr Inner Join 
               (Select it.Cod_Estabe, it.Cod_Produto, sum(it.Qtd_Pedido+it.Qtd_Bonificacao) as QtdTotNfe,
                       sum(it.Vlr_BasSubsTrib)/sum(it.Qtd_Pedido+it.Qtd_Bonificacao) as BasCalSubTriMedNfe
                  From NFECB cb Inner Join 
                       NFEIT it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo))
                 Where cb.Cod_Estabe = @CodEstabe 
                   and cb.Protocolo = @NumPrt
                   and cb.Flg_AtuPrcCus = 1 and cb.Flg_MovEst = 1
                   and ((cb.Tip_NF = 'C') or (cb.Tip_NF = 'T') or (cb.Cod_Cfo = @KCfoBonEntExt) or (cb.Cod_Cfo = @KCfoBonEntInt))
        		     and IsNull(it.Vlr_BasSubsTrib,0) > 0
                 Group by it.Cod_Estabe, it.Cod_Produto) x ON pr.Cod_Estabe = x.Cod_Estabe And pr.Cod_Produt = x.Cod_Produto
          
        -- custo medio gerencial
        Update pr
           Set pr.Prc_CusMed = case
                                 when ((pr.Prc_CusMed = 0) or (pr.Qtd_Fisico <= 0)) then x.TotCusMed
                                 else (pr.Prc_CusMed*pr.Qtd_Fisico + x.TotCusMed*x.TotQtd)/(pr.Qtd_Fisico+x.TotQtd)
                               end
          From PRXES pr Inner Join 
               (Select ix.Cod_Estabe, ix.Cod_Produto, TotQtd=sum(ix.QtdTotNfe), TotCusMed=sum(ix.CusMedNfe)
                  From (Select it.Cod_Estabe, it.Cod_Cfo, it.Cod_Produto, 
                               QtdTotNfe = sum(it.Qtd_Pedido+it.Qtd_Bonificacao),
                               CusMedNfe = case 
                                             When ((cb.Cod_Cfo <> @KCfoBonEntInt) and (cb.Cod_Cfo <> @KCfoBonEntExt)) and  -- nao eh nf de bonificacao
                                                  ((it.Cod_Cfo = @KCfoBonEntInt) or (it.Cod_Cfo = @KCfoBonEntExt)) then 0
                                             Else sum(it.Cus_LiqUni*it.Qtd_Pedido)/sum(it.Qtd_Pedido+it.Qtd_Bonificacao)
                                           end
                          From NFECB cb Inner Join 
                               NFEIT it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo))
                         Where cb.Cod_Estabe = @CodEstabe
                           and cb.Protocolo = @NumPrt
                           and cb.Flg_AtuPrcCus = 1 and cb.Flg_MovEst = 1
                         Group by cb.Cod_Cfo, it.Cod_Estabe, it.Cod_Cfo, it.Cod_Produto) ix
                 Group by ix.Cod_Estabe, ix.Cod_Produto) x ON pr.Cod_Estabe = x.Cod_Estabe And pr.Cod_Produt = x.Cod_Produto
          
        -- custo medio 1
        Update pr
           Set pr.Prc_CusMedPra = case
                                    when ((pr.Prc_CusMedPra = 0) or (IsNull(s.Qtd_SldPra,0) <= 0)) then x.TotCusMed
                                    else (pr.Prc_CusMedPra*IsNull(s.Qtd_SldPra,0) + x.TotCusMed*x.TotQtd)/(IsNull(s.Qtd_SldPra,0)+x.TotQtd)
                                  end
          From PRXES pr Inner Join 
               (Select ix.Cod_Estabe, ix.Cod_Produto, TotQtd=sum(ix.QtdTotNfe), TotCusMed=sum(ix.CusMedNfe)
                  From (Select it.Cod_Estabe, it.Cod_Cfo, it.Cod_Produto, 
                               QtdTotNfe = sum(it.Qtd_Pedido+it.Qtd_Bonificacao),
                               CusMedNfe = case 
                                             When ((cb.Cod_Cfo <> @KCfoBonEntInt) and (cb.Cod_Cfo <> @KCfoBonEntExt)) and  -- nao eh nf de bonificacao
                                                  ((it.Cod_Cfo = @KCfoBonEntInt) or (it.Cod_Cfo = @KCfoBonEntExt)) then 0
                                             Else sum(it.Cus_LiqUni*it.Qtd_Pedido)/sum(it.Qtd_Pedido+it.Qtd_Bonificacao)
                                           end
                          From NFECB cb Inner Join 
                               NFEIT it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo))
                         Where cb.Cod_Estabe = @CodEstabe
                           and cb.Protocolo = @NumPrt
                           and cb.Flg_AtuPrcCus = 1 and cb.Flg_MovEst = 1 and Isnull(cb.Cod_Cfo,0) > 0
                         Group by cb.Cod_Cfo, it.Cod_Estabe, it.Cod_Cfo, it.Cod_Produto) ix
                 Group by ix.Cod_Estabe, ix.Cod_Produto) x ON pr.Cod_Estabe = x.Cod_Estabe And pr.Cod_Produt = x.Cod_Produto  Left Outer Join
             (Select Cod_Estabe, Cod_Produt, max(Dat_Movime) as UltDatMov 
                From PRSLD
               Where Cod_Estabe = @CodEstabe
               Group by Cod_Estabe, Cod_Produt) y ON pr.Cod_Estabe = y.Cod_Estabe And pr.Cod_Produt = y.Cod_Produt Left Outer Join 
             PRSLD s ON (pr.Cod_Estabe = s.Cod_Estabe And pr.Cod_Produt = s.Cod_Produt and y.UltDatMov = s.Dat_Movime)
          
        -- custo medio 2
        Update pr
           Set pr.Prc_CusMedDep = case
                                    when ((pr.Prc_CusMedDep = 0) or (IsNull(s.Qtd_SldDep,0) <= 0)) then x.CusMedNfe
                                    else (pr.Prc_CusMedDep*IsNull(s.Qtd_SldDep,0) + x.CusMedNfe*x.QtdTotNfe)/(IsNull(s.Qtd_SldDep,0)+x.QtdTotNfe)
                                  end
          From PRXES pr Inner Join 
               (Select it.Cod_Estabe, it.Cod_Produto, sum(it.Qtd_Pedido+it.Qtd_Bonificacao) as QtdTotNfe,
                       sum(it.Cus_LiqUni*it.Qtd_Pedido)/sum(it.Qtd_Pedido+it.Qtd_Bonificacao) as CusMedNfe
                  From NFECB cb Inner Join NFEIT it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo))
                 Where cb.Cod_Estabe = @CodEstabe 
                   and cb.Protocolo = @NumPrt 
                   and cb.Flg_AtuPrcCus = 1 and cb.Flg_MovEst = 1 and Isnull(cb.Cod_Cfo,0) = 0
                 Group by it.Cod_Estabe, it.Cod_Produto) x ON pr.Cod_Estabe = x.Cod_Estabe and pr.Cod_Produt = x.Cod_Produto Left Outer Join
               (Select Cod_Estabe, Cod_Produt, max(Dat_Movime) as UltDatMov 
                  From PRSLD
                 Where Cod_Estabe = @CodEstabe
                 Group by Cod_Estabe, Cod_Produt) y ON pr.Cod_Estabe = y.Cod_Estabe and pr.Cod_Produt = y.Cod_Produt Left Outer Join 
               PRSLD s ON (pr.Cod_Estabe = s.Cod_Estabe and pr.Cod_Produt = s.Cod_Produt and y.UltDatMov = s.Dat_Movime)
               
        -- atualiza custo medio comercial
		-- considerar verba do fornecedor : Vlr_DscIte2     
        Update pr
           Set pr.Prc_CusMedCom = case
                                    when ((pr.Prc_CusMedCom = 0) or (pr.Qtd_Fisico <= 0)) then x.TotCusMed
                                    else (pr.Prc_CusMedCom*pr.Qtd_Fisico + x.TotCusMed*x.TotQtd)/(pr.Qtd_Fisico+x.TotQtd)
                                  end
          From PRXES pr Inner Join 
               (Select ix.Cod_Estabe, ix.Cod_Produto, TotQtd=sum(ix.QtdTotNfe), TotCusMed=sum(ix.CusMedNfe)
                  From (Select it.Cod_Estabe, it.Cod_Cfo, it.Cod_Produto, 
                               QtdTotNfe = sum(it.Qtd_Pedido+it.Qtd_Bonificacao),
                               CusMedNfe = case 
                                             When ((cb.Cod_Cfo <> @KCfoBonEntInt) and (cb.Cod_Cfo <> @KCfoBonEntExt)) and  -- nao eh nf de bonificacao
                                                  ((it.Cod_Cfo = @KCfoBonEntInt) or (it.Cod_Cfo = @KCfoBonEntExt)) then 0
                                             Else case 
                                                    When IsNull(it.Vlr_DscIte2,0) > 0 then sum(it.Cus_LiqUni*it.Qtd_Pedido+it.Vlr_DscIte2)/sum(it.Qtd_Pedido+it.Qtd_Bonificacao)
                                                    Else sum(it.Cus_LiqUni*it.Qtd_Pedido)/sum(it.Qtd_Pedido+it.Qtd_Bonificacao)
                                                  end
                                           end
                          From NFECB cb Inner Join 
                               NFEIT it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo))
                         Where cb.Cod_Estabe = @CodEstabe
                           and cb.Protocolo = @NumPrt
                           and cb.Flg_AtuPrcCus = 1 and cb.Flg_MovEst = 1
                         Group by cb.Cod_Cfo, it.Cod_Estabe, it.Cod_Cfo, it.Cod_Produto, it.Vlr_DscIte2) ix
                 Group by ix.Cod_Estabe, ix.Cod_Produto) x ON pr.Cod_Estabe = x.Cod_Estabe And pr.Cod_Produt = x.Cod_Produto
        
        -- atualiza itens da nota   
        Update it
           Set it.Dat_Movimento = cb.Dat_Movimento,
               it.Transacao = @Now,
               it.Prc_CustoMedio = pr.Prc_CusMed,
               it.Prc_Venda = case 
                                When Isnull(it.Prc_Venda,0) = 0 then pr.Prc_Venda
                                else it.Prc_Venda
                              end,
               it.Prc_Fabric = case 
                                 When Isnull(it.Prc_Fabric,0) = 0 then pr.Prc_Fabric
                                 else it.Prc_Fabric
                               end,
               it.Prc_MaxCon = case 
                                 When Isnull(it.Prc_MaxCon,0) = 0 then pr.Prc_MaxCon
                                 else it.Prc_MaxCon
                               end
          From NFEIT it Inner Join 
               NFECB cb on ((it.Cod_Estabe = cb.Cod_Estabe) and (it.Protocolo = cb.Protocolo)) Inner Join 
               PRXES pr on it.Cod_Estabe = pr.Cod_Estabe and it.Cod_Produto = pr.Cod_Produt
         Where cb.Cod_Estabe = @CodEstabe 
           and cb.Protocolo = @NumPrt
          
        -- quando for o caso, acrescenta '#' na 1a. posicao do lote NFEIT e NELTL e NEIUM
        -- Estabelecimento - Ceara credenciado
        -- Fornecddor - regiao com termo de acordo no estado
        -- item marcado como estoque pago ST
        if (Upper(@em_CodEst) = 'CE') and (@CodUf = 'CE') and
             ((Select r.Flg_RegEspTrb From RGTRI r, ESTAB es Where es.Cod_Estabe = @CodEstabe and r.Cod_RegTri = es.Cod_RegTri) = 1) and
           ((Select Flg_RegEspTrb From RGTRI Where Cod_RegTri = @CodRegTri ) = 1)
          begin
            Update lt
               Set lt.Cod_Lote = '#'+Substring(lt.Cod_Lote,1,11)
              From NELTL lt Inner Join 
                   PRXES pr on (lt.Cod_Estabe = pr.Cod_Estabe and lt.Cod_Produt = pr.Cod_Produt) Inner Join 
                   NFEIT it on ((lt.Cod_Estabe = it.Cod_Estabe) and (lt.Num_Protoc = it.Protocolo) and (lt.Cod_Produt = it.Cod_Produto) and (lt.Cod_Lote = it.Cod_Lote))
             Where lt.Cod_Estabe = @CodEstabe 
               and lt.Num_Protoc = @NumPrt
               And IsNull(pr.Flg_RegSbtEsp,0) = 0
               And IsNull(it.Flg_RegEspTrb,0) = 1
               And Substring(lt.Cod_Lote,1,1) <> '#'
        
            Update it
               Set it.Cod_Lote = '#'+Substring(it.Cod_Lote,1,11)
              From NFEIT it Inner Join 
                   PRXES pr on (it.Cod_Estabe = pr.Cod_Estabe And it.Cod_Produto = pr.Cod_Produt)
             Where it.Cod_Estabe = @CodEstabe 
               and it.Protocolo = @NumPrt
               And IsNull(pr.Flg_RegSbtEsp,0) = 0
               And IsNull(it.Flg_RegEspTrb,0) = 1
               And Substring(it.Cod_Lote,1,1) <> '#'
          end
          
        -- Tem que ser Depois do PR_RegistraNEREF, para ter o vínculo
        Set @pc_Controle_Saldo = ''
        Select top 1 
               @pc_Controle_Saldo = pc.Controle_Saldo,
               @pc_FlgAcuVrbPos = pc.Flg_AcuVrbPos,
               @pc_FlgAcuVrbNeg = pc.Flg_AcuVrbNeg,
               @pc_FlgCtrPdvVrbVdr = pc.Flg_CtrPdvVrbVdr,
               @pc_FlgCtrPdvVrbOpe = pc.Flg_CtrPdvVrbOpe
          From NEREF r 
               Inner Join NFSCB cb on (r.Tip_EntSai = 'S' and 
                                       r.Cod_Estabe = cb.Cod_Estabe and 
                                       r.Ser_DocRef = cb.Ser_Nota and 
                                       r.Num_DocRef = cb.Num_Nota)
               Inner join POCOM pc on pc.Id_PolCom = cb.Id_PolCom
         Where r.Cod_Estabe = @CodEstabe
           And r.Protocolo = @NumPrt
	 
        -- recalcula verba fornecedor
        Exec PR_CalcVerbaNFE @CodEstabe, @NumPrt
        if @@error <> 0
          begin
            if @@trancount > 0
              RollBack Transaction
            Return
          end


        -- armazena NELTL em tabela temporaria
        if Exists(Select 1 From NELTL Where Cod_Estabe = @CodEstabe and Num_Protoc = @NumPrt)
          Insert Into #ARQ_NELTL
            Select Cod_Produt, Cod_Lote, Tip_Local, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Qtd_Est, Qtd_EmbFec
              From NELTL
             Where Cod_Estabe = @CodEstabe 
               and Num_Protoc = @NumPrt 

        -- dá entrada no estoque  Prc_Fabric, Prc_CustoMedio
        Declare Itens_Cr Cursor Local Fast_Forward For 
          Select it.Cod_Produto, it.Cod_Lote, it.Num_SeqIte, IsNull(it.Tip_Ent,''), it.Dat_Vencim, it.Dat_Fabric, 
		       it.Qtd_Pedido, it.Qtd_Bonificacao, it.Prc_Unitario, it.Cus_LiqUni, 
                 it.Vlr_LiqIte, it.Qtd_Promocao, IsNull(it.Vlr_VrbVdr,0), IsNull(it.Vlr_DscIte2,0),
			   (it.Qtd_Pedido+it.Qtd_Bonificacao)*IsNull(it.Prc_CustoMedio,0), 
                 (it.Qtd_Pedido+it.Qtd_Bonificacao)*IsNull(it.Prc_Fabric,0),
                 pr.Cod_Fabricante, IsNull(it.Vlr_VrbOpe,0), IsNull(it.Vlr_VrbSup,0)
            From NFEIT it 
                 Inner Join NFECB cb on ((it.Cod_Estabe = cb.Cod_Estabe) and (it.Protocolo = cb.Protocolo))
                 Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
           Where cb.Cod_Estabe = @CodEstabe and cb.Protocolo = @NumPrt 
             and cb.Flg_MovEst = 1

        Open Itens_Cr
        Fetch Next From Itens_Cr Into @CodPrd, @CodLot, @NumSeqIte, @TipEnt, @DatVct, @DatFab, 
                                      @QtdPed, @QtdBon, @PrcUni, @CusLiqUni, 
                                      @ValLiq, @QtdPrm, @VlrVerbaVdr, @VlrVerbaFor,
                                      @ValCusMed, @ValPrcFab, @CodFab, @VlrVerbaOpe, @VlrVerbaSup
        While @@FETCH_STATUS = 0
          Begin
            -- qtd total a movimentar do item
            Set @QtdMov = @QtdPed + @QtdBon
          
            -- ver integracao ao WMS
            if @FlgWms = 0
              begin
                -- sem WMS: deposito unico
                Set @CodDep = IsNull((Select min(Cod_Dep) 
                                        From TBDEP 
                                       Where Cod_Estabe = @CodEstabe),1)

                -- se nao existir o lote, cria
                if not Exists(Select 1 From PRLOT Where Cod_Estabe = @CodEstabe and Cod_Dep = @CodDep and Cod_Produt = @CodPrd and Cod_Lote = @CodLot)
                  begin
                    Insert into PRLOT (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Dat_Vencim, Dat_Fabric, Qtd_FisPra, Qtd_SolPra,Qtd_FisDep,Qtd_SolDep)
                               Values (@CodEstabe, @CodDep, @CodPrd, @CodLot, @DatVct, @DatFab, 0, 0, 0, 0)
                    if @@error <> 0
                      begin
                        if @@trancount > 0
                          RollBack Transaction
                        Return
                      end
                  end
                else
                  -- se for o caso atualiza o vencimento do lote existente
                  begin
                    Update PRLOT
                       Set Dat_Vencim = @DatVct,
                           Dat_Fabric = @DatFab
                     Where Cod_Estabe = @CodEstabe    
                       And Cod_Dep = @CodDep
                       And Cod_Produt = @CodPrd
                       And Cod_Lote = @CodLot
                       And ((Dat_Vencim is null) or (Dat_Vencim <> @DatVct) or 
                            (Dat_Fabric is null) or (Dat_Fabric <> @DatFab))
                  end           
            
                Set @QtdPra = 0
                Set @QtdDep = 0
                if @CodCfo > 0
                  Set @QtdPra = @QtdMov
                else
                  Set @QtdDep = @QtdMov  
                Exec PR_AtualizaSaldoEstoque 'NF', @CodEstabe, @CodDep, @CodPrd, @CodLot, @DatMov, 'E', @TipNfe, @QtdPra, 0, @QtdDep, 0
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      RollBack Transaction
                    Return
                  end

                -- reserva itens se for devolução simbolica de consignação
                if @FlgReservConsig = 1
                  begin
				 if @NumReserv = 0
                      begin
				     Set @NumReserv = IsNull((Select max(Numero) From RESER Where Cod_Estabe = @CodEstabe),0) + 1
                        Set @DesHisReserv = 'DEV.CONSIGNAÇÃO ;'+cast(@IdConsig as varchar)+';'+cast(@NumSeqCtr as varchar)+';'+cast(@NumSeqDev as varchar)+';' 
                      end

                    if Exists(Select 1 From RESER Where Cod_Estabe = @CodEstabe and Numero = @NumReserv and Cod_Produto = @CodPrd)
				   Set @NumReserv = IsNull((Select max(Numero) From RESER Where Cod_Estabe = @CodEstabe),0) + 1

                    -- registra reserva
                    Insert Into RESER (Cod_Estabe, Numero, Cod_Dep, Cod_Produto, Cod_Lote, Qtd_Movimento, Qtd_ResDep, Historico,
                                       Id_Consig, Num_SeqCtr, Num_SeqDev, Dat_Movimento, Usuario, Transacao)
                               Values (@CodEstabe, @NumReserv, @CodDep, @CodPrd, @CodLot, @QtdPra, @QtdDep, @DesHisReserv, 
                                       @IdConsig, @NumSeqCtr, @NumSeqDev, @Date, @Usuario, @Now)
                    if @@error <> 0
                      begin
                        if @@trancount > 0
                          RollBack Transaction
                        Return
                      end
                  end
           
              end  -- if @FlgWms = 0
            else
              begin
                -- selecionar até "quantidade" @QtdMov =  @QtdPed + @QtdBon
                -- entrada através de QtdPra e @QtdDep
                Set @QtdMovSld = @QtdMov
            
                While @QtdMovSld > 0
                  begin
            
                    Declare Lotes_Cr Cursor Local Fast_Forward For 
            
                      Select Chave, Tip_Loc, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Qtd_Lot, Qtd_EmbFec
                        From #ARQ_NELTL
                       Where Cod_Prd = @CodPrd
                         And Cod_Lot = @CodLot
                         And Qtd_Lot > 0
            
                    Open Lotes_Cr
                    Fetch Next From Lotes_Cr
                      Into @Chave, @TipLoc, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @QtdEst, @QtdEmbFec
                    
                    While (@@FETCH_STATUS = 0) and (@QtdMovSld > 0)
                      begin
                      
                        if @QtdEst > @QtdMovSld
                          Set @QtdEst = @QtdMovSld
                      
                        Set @QtdPra = 0
                        Set @QtdDep = 0
                        if @CodCfo > 0
                          Set @QtdPra = @QtdEst
                        else
                          Set @QtdDep = @QtdEst
                      
                        -- insere registros prlog
                        Exec PR_InserePRLOG @CodEstabe, @CodPrd, @CodLot, @CodDep, 
                                              @NumRua, @NumCol, @NumNiv, @NumApt,
                                              @QtdEst, @WCodOri, '', @NumPrt, '', '', @Usuario
                        if @@error <> 0
                          begin
                            if @@trancount > 0
                              RollBack Transaction
                            Return
                          end
                        
                        if Ltrim(Rtrim(@TipLoc)) = ''
                          Set @TipLoc = dbo.FN_TipLocEnd(@CodEstabe,@CodDep,@NumRua)
                        
                        if @TipLoc = 'P'   -- picking
                          begin
                            -- se nao existir o lote, cria
                            if not Exists(Select 1 From PRLOT Where Cod_Estabe = @CodEstabe and Cod_Dep = @CodDep and Cod_Produt = @CodPrd and Cod_Lote = @CodLot)
                              begin
                                Insert into PRLOT (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Dat_Vencim, Dat_Fabric, Qtd_FisPra, Qtd_SolPra,Qtd_FisDep,Qtd_SolDep)
                                           Values (@CodEstabe, @CodDep, @CodPrd, @CodLot, @DatVct, @DatFab, 0, 0, 0, 0)
                                if @@error <> 0
                                  begin
                                    if @@trancount > 0
                                      RollBack Transaction
                                    Return
                                  end
                              end
                            else
                              -- se for o caso atualiza o vencimento do lote existente
                              begin
                                Update PRLOT
                                   Set Dat_Vencim = @DatVct,
                                       Dat_Fabric = @DatFab
                                 Where Cod_Estabe = @CodEstabe    
                                   And Cod_Dep = @CodDep
                                   And Cod_Produt = @CodPrd
                                   And Cod_Lote = @CodLot
                                   And ((Dat_Vencim is null) or (Dat_Vencim <> @DatVct) or 
                                        (Dat_Fabric is null) or (Dat_Fabric <> @DatFab))
                              end           
                              
                            -- atualiza mov em PRSLD e fisico em PRLOT e PRODU
                            Exec PR_AtualizaSaldoEstoque 'NF', @CodEstabe, @CodDep, @CodPrd, @CodLot, @DatMov, 'E', @TipNfe, @QtdPra, 0, @QtdDep, 0
                            if @@error <> 0
                              begin
                                if @@trancount > 0
                                  RollBack Transaction
                                Return
                              end
                          end
                        else
                          begin
                            -- elimina mesmo lote com saldo 0 e embalagem diferente
                            Delete From PRLTL
                              Where Cod_Estabe = @CodEstabe
                              And Cod_Produt = @CodPrd
                              And Cod_Lote = @CodLot
                              And Qtd_EmbFec <> @QtdEmbFec
                              And Qtd_Fisico = 0
                           
                            -- se nao existir o lote, cria
                            if not Exists(Select 1 From PRLTL 
                                           Where Cod_Estabe = @CodEstabe 
                           				   and Cod_Produt = @CodPrd 
                           				   and Cod_Lote = @CodLot 
                           				   and Qtd_EmbFec = @QtdEmbFec 
                           				   and Cod_Dep = @CodDep 
                           				   and Num_Rua = @NumRua and Num_Col = @NumCol 
                           				   and Num_Niv = @NumNiv and Num_Apt = @NumApt)
                              begin
                                Insert into PRLTL (Cod_Estabe, Cod_Produt, Cod_Lote, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Qtd_EmbFec, Dat_Vencim, Dat_Fabric, Dat_Entrada, Qtd_FisPra, Qtd_SolPra,Qtd_FisDep,Qtd_SolDep)
                                           Values (@CodEstabe, @CodPrd, @CodLot, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @QtdEmbFec, @DatVct, @DatFab, @DatMov, 0, 0, 0, 0)
                                if @@error <> 0
                                  begin
                                    if @@trancount > 0
                                      RollBack Transaction
                                    Return
                                  end
                              end
                             
                            Exec PR_AtualizaSaldoEstoqueGrosso @CodEstabe, @CodPrd, @CodLot, @QtdEmbFec, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @DatMov, 'E', @TipNfe, @QtdPra, 0, @QtdDep, 0
                            if @@error <> 0
                              begin
                                if @@trancount > 0
                                  RollBack Transaction
                                Return
                              end
                          end                       
                        
                        -- decrementa quantidade a movimentar
                        Update #ARQ_NELTL
                           Set Qtd_Lot = Qtd_Lot - (@QtdPra+@QtdDep)
                         Where Chave = @Chave
                        
                        Set @QtdMovSld = @QtdMovSld - (@QtdPra+@QtdDep)
                        
                        Fetch Next From Lotes_Cr
                         Into @Chave, @TipLoc, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @QtdEst, @QtdEmbFec
                         
                      end  -- While (@@FETCH_STATUS = 0) and (@QtdMovSld > 0)
                      
                    Close Lotes_Cr
                    Deallocate Lotes_Cr
            
                  end  -- While @QtdMovSld > 0
            
              end  -- if @FlgWms = 1
            
            -- da entrada na promocao
            if @QtdPrm > 0
              begin
                Select @CodPrm = Cod_Promocao From PRXES Where Cod_Estabe = @CodEstabe And Cod_Produt = @CodPrd
                if IsNull(@CodPrm,0) > 0
                  EXEC PR_GravaPrmMv @CodEstabe, @CodPrm, @CodPrd, @DatMov, 'C', '', @NumPrt, @QtdPrm
              end
            
            -- atualiza estatisticas de produtos 
            Exec PR_AcuEntNfeItePrd @CodEstabe, @TipNfe, @StaNfe, @CodPrd, @DatMov, @QtdMov, @ValLiq, @ValCusMed, @ValPrcFab
            if @@error <> 0
              begin
                if @@trancount > 0
                  RollBack Transaction
                Return
              end
          
            -- atualiza estatisticas de fabricantes 
            Exec PR_AcuEntNfeIteFor @CodEstabe, @TipNfe, @StaNfe, @CodPrd, @DatMov, @QtdMov, @ValLiq
            if @@error <> 0
              begin
                if @@trancount > 0
                  RollBack Transaction
                Return
              end

            -- atualiza estatisticas de clientes (devolução)
            if @CodEmiCli > 0
              begin
                Exec PR_AcuEntNfeIteCli @CodEstabe, @TipNfe, @StaNfe, @CodEmiCli, @DatMov, @QtdMov, @ValLiq
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      RollBack Transaction
                    Return
                  end
              end

            -- atualiza estatisticas de Vendedores (devolução)
            if @CodVdr > 0
              begin
                Exec PR_AcuEntNfeIteVen @CodEstabe, @TipNfe, @StaNfe, @CodVdr, @DatMov, @QtdMov, @ValLiq
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      RollBack Transaction
                    Return
                  end
              end

            -- atualiza verbas
            if (@TipNfe = 'D') and 
               ((@pc_Controle_Saldo = 'V') or (@pc_Controle_Saldo = 'F'))
              begin
                Set @DesMovime = 'DEVOLUCAO NF'

                -- atualiza verba vendedor
                if (@VlrVerbaVdr <> 0) and (IsNull(@CodVdr,0) > 0) 
                  begin
                    Set @VlrVerbaVdr = -@VlrVerbaVdr
                    if @pc_Controle_Saldo = 'V' -- Vendedor/Operador
                      Exec PR_AtualizaSaldoVBSLD @CodEstabe, @CodVdr,          @DatMov, 0, @CodPrd, @CodLot, @TipEnt, 'E', @TipNfe, '', @NumPrt, @VlrVerbaVdr, @DesMovime, @Usuario
                    else
                      Exec PR_AtualizaSaldoVBFSL @CodEstabe, @CodVdr, @CodFab, @DatMov, 0, @CodPrd, @CodLot, @TipEnt, 'E', @TipNfe, '', @NumPrt, @VlrVerbaVdr, @DesMovime, @Usuario
                    if (@@error <> 0)
                      begin
                        if @@trancount > 0
                          Rollback Transaction
                          Return
                      end
                  end
                 
                -- atualiza verba operador
                if (@VlrVerbaOpe <> 0) and (IsNull(@CodVdrTlmkt,0) > 0)
                  begin							  
                    Set @VlrVerbaOpe = -@VlrVerbaOpe
                    if @pc_Controle_Saldo = 'V' -- Vendedor/Operador
                      Exec PR_AtualizaSaldoVBSLD @CodEstabe, @CodVdrTlmkt,          @DatMov, 0, @CodPrd, @CodLot, @TipEnt, 'E', @TipNfe, '', @NumPrt, @VlrVerbaOpe, @DesMovime, @Usuario
                    else
                      Exec PR_AtualizaSaldoVBFSL @CodEstabe, @CodVdrTlmkt, @CodFab, @DatMov, 0, @CodPrd, @CodLot, @TipEnt, 'E', @TipNfe, '', @NumPrt, @VlrVerbaOpe, @DesMovime, @Usuario
                    if (@@error <> 0)
                      begin
                        if @@trancount > 0
                          Rollback Transaction
                        Return
                      end
                  end
                
                -- atualiza verba supervisor
                if (@VlrVerbaSup <> 0) and (IsNull(@CodSup,0) > 0)
                  begin
                    Set @VlrVerbaSup = -@VlrVerbaSup
                    Exec PR_AtualizaSaldoVBSSD @CodEstabe, @CodSup, @DatMov, 0, @CodPrd, @CodLot, @TipEnt, 'E', @TipNfe, '', @NumPrt, @VlrVerbaSup, @DesMovime, @Usuario
                    if (@@error <> 0)
                      begin
                        if @@trancount > 0
                          Rollback Transaction
                        Return
                      end
                end  
                 
              end  -- -- if (@TipNfe = 'D') and (@VlrVerbaVdr <> 0) and 


            -- atualiza verba fornecedor
            if (@VlrVerbaFor <> 0) and (@CodEmiFor > 0) 
              begin
                Set @DesMovime = 'ENTRADA NF'
                if @TipNfe = 'D'
                  begin
                    Set @VlrVerbaFor = -@VlrVerbaFor
                    Set @DesMovime = 'DEVOLUCAO NF'
                  end
                Exec PR_AtualizaSaldoVBFSD @CodEstabe, @CodEmiFor, @DatMov, 0, @CodPrd, @CodLot, 'E', @TipNfe, '', @NumPrt, @VlrVerbaFor, @DesMovime, @Usuario
                if (@@error <> 0)
                  begin
                    if @@trancount > 0
                      RollBack Transaction
                    Return
                  end
              end


          -- grava movimento relativo a devolução de consignação: CFOP: 
          if (@IdConsig > 0) and (@NumSeqCtr > 0) and (dbo.FN_CfopConsigValido(@CodCfo) = 1) 
            begin
              -- NDS = devolucaosimbolica : @FlgFaturaConsig = 1
              -- NDE = devolucao efetiva
              if @FlgFaturaConsig = 1 
                Set @CodTipDevCng = 'NDS'
              else
                Set @CodTipDevCng = 'NDE'

              Exec PR_GravaMovimeCNGMV @CodEstabe, @IdConsig, @CodPrd, @CodLot,
                                       @DatMov, 'E', @CodTipDevCng, '', @NumPrt, '', 'F', 
                                       @QtdMov, @PrcUni
              if (@@error <> 0)
                begin
                  if @@trancount > 0 
                    Rollback Transaction
                  Return
                end
            end

          -- atualiza TBIUM
            Insert Into TBIUM (Cod_Estabe, Cod_IUM, Cod_Produto, Cod_Lote, Cod_IUC)
              Select i1.Cod_Estabe, i1.Cod_IUM, i1.Cod_Produto, i1.Cod_Lote, i1.Cod_IUC
                From NEIUM i1 
                     Left Join TBIUM tb on i1.Cod_IUM = tb.Cod_IUM   
               Where i1.Cod_Estabe = @CodEstabe 
                 and i1.Protocolo = @NumPrt
                 And i1.Cod_Produto = @CodPrd
                 And i1.Cod_Lote = @CodLot 
                 And i1.Num_SeqIte = @NumSeqIte
                 And tb.Cod_IUM is null 
            if (@@error <> 0)
              begin
                if @@trancount > 0
                  RollBack Transaction
                Return
              end
               
            Update tb
               Set tb.Cod_Produto = i1.Cod_Produto,
                   tb.Cod_Lote = i1.Cod_Lote,
                   tb.Cod_IUC = i1.Cod_IUC
              From TBIUM tb Inner Join NEIUM i1 on tb.Cod_Estabe = i1.Cod_Estabe And tb.Cod_IUM = i1.Cod_IUM
             Where i1.Cod_Estabe = @CodEstabe 
               and i1.Protocolo = @NumPrt
               And i1.Cod_Produto = @CodPrd
               And i1.Cod_Lote = @CodLot 
               And i1.Num_SeqIte = @NumSeqIte
          
            Fetch Next From Itens_Cr Into @CodPrd, @CodLot, @NumSeqIte, @TipEnt, @DatVct, @DatFab, 
                                          @QtdPed, @QtdBon, @PrcUni, @CusLiqUni, 
                                          @ValLiq, @QtdPrm, @VlrVerbaVdr, @VlrVerbaFor,
                                          @ValCusMed, @ValPrcFab, @CodFab, @VlrVerbaOpe, @VlrVerbaSup
          end
        
        Close Itens_Cr
        Deallocate Itens_Cr
          
        -- atualiza estatistica do estabelecimento
        if @FlgMovEst = 1
          begin
            Exec PR_AcuEntNfeCabEmp @CodEstabe, @NumPrt, @TipNfe, @StaNfe, @DatMov
            if @@error <> 0
              begin
                if @@trancount > 0
                  RollBack Transaction
                Return
              end
          end
        
        Declare @WQtdIte int,
                @WQtdPgNf int,
                @WNumNot int,
                @WSerNot varchar(3),
                @WNumFor int,
                @WSerSel varchar(2),
                @WNumSel bigint,
                @WModNotFis varchar(2),
                @WCodStaNfe char(1),
                @nm_NotFis int,
                @nm_SerNotFis int,
                @nm_ModNotFis varchar(2),
                @fs_FlgOpcUsaCreLoj BIT = 0

        Select @fs_FlgOpcUsaCreLoj = ISNULL(Val_param, 0)  FROM fs_param WHERE Cod_Param = 'TRM_OPC_USACRELOJ'
  
        Set @WQtdPgNf = 0
        Set @WNumFor = 0
        Set @WSerSel = ''
        Set @WNumSel = 0
        Set @WModNotFis = @CodModDoc
        Set @WCodStaNfe = ''
        Set @WQtdIte = Isnull((Select count(*) From NFEIT Where Cod_Estabe = @CodEstabe and Protocolo = @NumPrt),0)
        
        -- verifica se é devolução total
        Set @SerNotSai = ''
        Set @NumNotSai = 0
        Set @ValDspEmb = 0

        if (@TipNfe = 'D') 
          begin
            Set @FlgDevTot = 0
	        Set @FlgDevChv = 0
	  
            Select top 1 @SerNotSai = Ser_DocRef, 
                         @NumNotSai = Num_DocRef
              From NEREF
             Where Cod_Estabe = @CodEstabe
               And Protocolo = @NumPrt
               And Tip_EntSai = 'S'

            Set @TipNfsRef = (Select IsNull(cb.Tip_Saida, '')
                                From NEREF r 
                                     Inner Join NFSCB cb on (r.Tip_EntSai = 'S' and 
                                                             r.Cod_Estabe = cb.Cod_Estabe and 
                                                             r.Ser_DocRef = cb.Ser_Nota and 
                                                             r.Num_DocRef = cb.Num_Nota)
                               Where r.Cod_Estabe = @CodEstabe
                                 And r.Protocolo = @NumPrt)

            --Alimenta variaveis a partir de devolução apenas com chave
            Select @FlgDevChv = Case When Isnull(cb.Chv_NotOri, '') <> '' Then 1 Else 0 End,
                   @TipNfsRef = 'S',
                   @SerNotSai = Substring(Chv_NotOri, 23, 3),
                   @NumNotSai = Substring(Chv_NotOri, 26, 9)
              From NFECB cb 
             Where cb.Cod_Estabe = @CodEstabe 
               And cb.Protocolo = @NumPrt
               And Isnull(cb.Chv_NotOri, '') <> ''

            if not Exists(Select e.Cod_Produto, s.Cod_Produto, e.QtdPrdEnt, s.QtdPrdSai
                            From (Select Cod_Produto, QtdPrdEnt=sum(Qtd_Pedido+Qtd_Bonificacao)
                                    From NFEIT
                                   Where Cod_Estabe = @CodEstabe
                                     And Protocolo = @NumPrt
                                   Group by Cod_Produto) e FULL OUTER JOIN
                                 (Select Cod_Produto, QtdPrdSai=sum(Qtd_Produto+Qtd_Bonificacao)
                                    From NFSIT
                                   Where Cod_Estabe = @CodEstabe
                                     And Ser_Nota = @SerNotSai
                                     And Num_Nota = @NumNotSai
                                   Group by Cod_Produto) s on (e.Cod_Produto = s.Cod_Produto)
                           Where IsNull(e.QtdPrdEnt,0) <> IsNull(s.QtdPrdSai,0))
              begin                         
                Set @FlgDevTot = 1
                Set @ValDspEmb = IsNull((Select sum(IsNull(cr.Vlr_DspEmb,0))
                                           From NEREF r Inner Join
                                                NFSCB cb on (r.Tip_EntSai = 'S' and r.Cod_Estabe = cb.Cod_Estabe and 
                                                             r.Ser_DocRef = cb.Ser_Nota and r.Num_DocRef = cb.Num_Nota) Inner Join
                                                CTREC cr on cr.Ser_NfOrigem = cb.Ser_Nota and cr.Num_NfOrigem = cb.Num_Nota and cb.Cod_Estabe = cr.Cod_Estabe
                                          Where r.Cod_Estabe = @CodEstabe
                                            And r.Protocolo = @NumPrt),0)
              end
          end

        if @FlgImpNot = 1
          begin
            if @pm_FlgNfe = 1 
              begin
                Update NMNFE     
                   Set Num_Nfe = Num_Nfe + 0
                 Where Cod_Estabe = @CodEstabe 
                   And Flg_Padrao = 1
         
                Select @nm_SerNotFis = Ser_Nfe,
                       @nm_NotFis = Num_Nfe,
                       @nm_ModNotFis = Mod_Nfe
                  From NMNFE
                 Where Cod_Estabe = @CodEstabe 
                   And Flg_Padrao = 1
         
                --  pega proximo numero da NF
                Set @WNumNot = @nm_NotFis+1
                Set @WSerNot = cast(@nm_SerNotFis as varchar)
                Set @WModNotFis = @nm_ModNotFis
                Set @WCodStaNfe = 'N'
         
                -- atualiza NMNFE
                Update NMNFE
                   Set Num_Nfe = @WNumNot
                 Where Cod_Estabe = @CodEstabe 
                   And Ser_Nfe = @nm_SerNotFis
              end
            else
              begin
                Update NMFIS
                   Set Nota_Fiscal_M1 = Nota_Fiscal_M1 + 0
                 Where Cod_Estabe = @CodEstabe
          
                Select @nm_NotFis = Nota_Fiscal_M1
                  From NMFIS
                 Where Cod_Estabe = @CodEstabe
          
                --  pega proximo numero da NF
                Set @WNumNot = @nm_NotFis+1
                Set @WSerNot = @pm_ModeloNotaFiscal   
                Set @WModNotFis = @pm_ModeloNotaFiscal
                Set @WCodStaNfe = ''
          
                Set @WQtdPgNf = 1
                if @WQtdIte > 0 and @pm_NumItePagNfs > 0
                  Set @WQtdPgNf = Ceiling(@WQtdIte*1.00 /@pm_NumItePagNfs)
                if @WQtdPgNf < 1
                  Set @WQtdPgNf = 1
                Set @WNumFor = @NumFrm + @WQtdPgNf - 1
          
                -- atualiza NMFIS
                if @pm_FlgCtrSelFis = 1
                  begin
                    Set @WSerSel = @pm_SerieSeloFiscal
                    Set @WNumSel = @NumSel + @WQtdPgNf - 1
                    Update NMFIS
                       Set Nota_Fiscal_M1 = @WNumNot,
                           Formulario_M1 = @WNumFor,
                           Selo_Fiscal = @WNumSel
                     Where Cod_Estabe = @CodEstabe    
                  end
                else
                  begin
                    Update NMFIS
                       Set Nota_Fiscal_M1 = @WNumNot,
                           Formulario_M1 = @WNumFor
                     Where Cod_Estabe = @CodEstabe    
                  end
              end
          
            Update NFECB
               Set Qtd_Itens = @WQtdIte,
                   Qtd_PagNf = @WQtdPgNf,
                   Serie = @WSerNot,
                   Numero = @WNumNot,
                   Num_Formulario = @WNumFor,
                   Ser_SeloFisTran = @WSerSel,
                   Num_SeloFisTran = @WNumSel,
                   Flg_DevTot = @FlgDevTot,
                   Cod_ModDoc = @WModNotFis, 
                   Cod_StaNfe =  @WCodStaNfe
             Where Cod_Estabe = @CodEstabe 
               and Protocolo = @NumPrt
          end
        else
          begin
            Update NFECB
               Set Qtd_Itens = @WQtdIte,
                   Qtd_PagNf = @WQtdPgNf,
                   Flg_DevTot = @FlgDevTot,
                   Cod_ModDoc = @WModNotFis, 
                   Cod_StaNfe =  @WCodStaNfe
             Where Cod_Estabe = @CodEstabe 
               and Protocolo = @NumPrt
          end
          
        -- atualiza status integracao WMS
        Update NFECB
           Set Sta_IntWMS = '3'
         Where Cod_Estabe = @CodEstabe 
           And Protocolo = @NumPrt
           And IsNull(Sta_IntWMS,'') <> ''
        
        -- atualiza CFOp dos itens
        if Exists(Select top 1 Cod_Cfo From NFEIT 
                   Where Cod_Estabe = @CodEstabe and Protocolo = @NumPrt 
                     And IsNull(Cod_Cfo,0) = 0)
          begin
            Exec PR_AtualizaCFOpItemNf @CodEstabe, '', @NumPrt
            if @@error <> 0
              begin
                if @@trancount > 0
                  RollBack Transaction
                Return
              end
          end
        
        -- atualiza Cfop do cabecalho com o do item de maior valor
        if @WQtdIte > 0
          begin
            Exec PR_AtualizaCFOpNFECB @CodEstabe, @NumPrt
            if @@error <> 0
              begin
                if @@trancount > 0
                  RollBack Transaction
                Return
              end
          end
          
        -- ver se transfere saldos de PRSLD
        Exec PR_TransfEstNFE @CodEstabe, @NumPrt
        if @@error <> 0
          begin
            if @@trancount > 0
              RollBack Transaction
            Return
          end
        
        -- atualiza tipo de documento em PAGCT
        if Exists(Select Cod_CtaPag From PAGCT Where Cod_Estabe = @CodEstabe And Cod_PrtNfe = @NumPrt)
          begin
            While Exists(Select Cod_CtaPag From PAGCT 
                         Where Cod_Estabe = @CodEstabe And Cod_PrtNfe = @NumPrt And ISNULL(Id_Transacao,0) = 0)
              begin
                Select top 1 @WCodDoc = Cod_CtaPag 
                  From PAGCT 
                 Where Cod_Estabe = @CodEstabe And Cod_PrtNfe = @NumPrt And ISNULL(Id_Transacao,0) = 0
        
                EXEC PR_ProxNumeroEstab @CodEstabe, 'Id_Transacao', @IdTransacao output
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      RollBack Transaction
                    Return
                  end
        
                Update PAGCT
                   Set Id_Transacao = @IdTransacao
                 Where Cod_Estabe = @CodEstabe 
                   And Cod_CtaPag = @WCodDoc
             end
            
            -- tira da previsao em PAGCT 
            Update PAGCT
               Set Flg_Previs = 0
             Where Cod_Estabe = @CodEstabe
               And Cod_PrtNfe = @NumPrt
               And Flg_Previs = 1
         
            Update PAGCT
               Set Isn_CtaFin = @to_IsnCtaFinCre,
                   Dat_Registro = @DatMov,
                   Tip_Documento = case 
                                     When @CodCfo > 0 then 'DUP'
                                     else 'ORC'
                                   end
             Where Cod_Estabe = @CodEstabe
               And Cod_PrtNfe = @NumPrt
            
            if Exists(Select ct.Cod_CtaPag
                        From PAGCT ct Left Outer Join 
                             PCMOV mv on (ct.Id_Transacao = mv.Id_Transacao and 
                                          mv.Nom_Tabela = 'PAGCT' and 
                                          mv.Tip_Docume = 'PAG' and 
                                          ct.Cod_Estabe = mv.Cod_Estabe and 
                                          ct.Cod_CtaPag = mv.Num_Docume)
                       Where ct.Cod_PrtNfe = @NumPrt
                         And IsNull(ct.Id_Transacao,0) > 0     
                         And IsNull(ct.Isn_CtaFin,0) > 0
                         And mv.Id_Transacao is null)
              begin
                Update PAGCT
                   Set Val_Docume = Val_Docume + 0.01
                 Where Cod_Estabe = @CodEstabe 
                   And Cod_PrtNfe = @NumPrt
                  
                Update PAGCT
                   Set Val_Docume = Val_Docume - 0.01
                 Where Cod_Estabe = @CodEstabe 
                   And Cod_PrtNfe = @NumPrt
              end
              
            Update rt 
               Set rt.Isn_CtaFin = @to_IsnCtaFinDeb
              From PAGRT rt Inner Join PAGCT ct on (rt.Cod_Estabe = ct.Cod_Estabe and rt.Cod_CtaPag = ct.Cod_CtaPag)
             Where ct.Cod_Estabe = @CodEstabe 
               And ct.Cod_PrtNfe = @NumPrt
               And IsNull(rt.Isn_CtaFin,0) = 0
          
            if Exists(Select rt.Cod_CtaPag
                        From PAGCT ct Inner Join
                             PAGRT rt on ct.Cod_Estabe = rt.Cod_Estabe and ct.Cod_CtaPag = rt.Cod_CtaPag Left Outer Join 
                             PCMOV mv on (ct.Id_Transacao = mv.Id_Transacao and 
                                          mv.Nom_Tabela = 'PAGRT' and 
                                          mv.Tip_Docume = 'PAG' and 
                                          ct.Cod_Estabe = mv.Cod_Estabe and 
                                          ct.Cod_CtaPag = mv.Num_Docume)
                       Where ct.Cod_Estabe = @CodEstabe 
                         And ct.Cod_PrtNfe = @NumPrt
                         And IsNull(ct.Id_Transacao,0) > 0     
                         And IsNull(ct.Isn_CtaFin,0) > 0
                         And mv.Id_Transacao is null)
              begin
                Update rt
                   Set rt.Val_DocRat = rt.Val_DocRat + 0.01
                  From PAGRT rt Inner Join
                       PAGCT ct on rt.Cod_Estabe = ct.Cod_Estabe And rt.Cod_CtaPag = ct.Cod_CtaPag
                 Where ct.Cod_Estabe = @CodEstabe
                   And ct.Cod_PrtNfe = @NumPrt
                
                Update rt
                   Set rt.Val_DocRat = rt.Val_DocRat - 0.01
                  From PAGRT rt Inner Join
                       PAGCT ct on rt.Cod_Estabe = ct.Cod_Estabe and rt.Cod_CtaPag = ct.Cod_CtaPag
                 Where ct.Cod_Estabe = @CodEstabe 
                   And ct.Cod_PrtNfe = @NumPrt
              end
          
          end
        else
        -- ver se cria vales (devolucao). { (@TipNfsRef <> 'T') Para não gerar vales de uma Nota que sua origem é uma nota de transferência }
        if ( (@SerNot <> 'ECF') and 
		     (@TipNfe = 'D') and (@FlgMovEst = 1) and (@TipNfsRef <> 'T') and 
		     ((@CodEmiFor > 0) or (@CodEmiCli > 0) or (@CodEmiTra > 0)) ) AND
		   ( (@fs_FlgOpcUsaCreLoj = 0) or ((@fs_FlgOpcUsaCreLoj = 1) and (@SerNotSai <> 'ECF')) )
          begin
            if (@FlgDevTot = 1) and (@pm_FlgManDupDevTotVen = 0) and
               (not Exists(Select 1
			               From CTREC
                            Where Cod_Estabe = @CodEstabe     
                              And Ser_NfOrigem = @SerNotSai 
                              and Num_NfOrigem = @NumNotSai 
                              and Status <> 'A')) and
               (not Exists(Select top 1 1
			               From BXREC bx Inner Join 
						        CTREC cr on bx.Cod_Estabe = cr.Cod_Estabe and bx.Cod_Documento = cr.Cod_Documento
                            Where cr.Cod_Estabe = @CodEstabe     
                              And cr.Ser_NfOrigem = @SerNotSai 
                              and cr.Num_NfOrigem = @NumNotSai))
              begin
                -- cancela os titulos
                Exec PR_CancelaDevolveTitulosCTREC @CodEstabe, @SerNotSai, @NumNotSai, @Usuario, 'D', @WIsnCtaFinEntid, @to_IsnCtaFinDeb
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      RollBack Transaction
                    Return
                  end
              end
            else
              begin
                if @CodEmiFor > 0
                  begin
                    Set @TipEmi = 'FOR'
                    Set @CodEmi = @CodEmiFor
                  end
                else
                if @CodEmiCli > 0
                  begin
                    Set @TipEmi = 'CLI'
                    Set @CodEmi = @CodEmiCli
                  end
                else
                if @CodEmiTra > 0
                  begin
                    Set @TipEmi = 'TRA'
                    Set @CodEmi = @CodEmiTra
                  end
          
                -- Parametro: Creditos a conceder
                if @pm_FlgUsaInterv = 1
                  Set @to_IsnCtaFinCre = (Select pm.IsnCtaFinDespVal 
                                            From PMFIN pm Inner Join
                                                 PCFIN pc on pm.IsnCtaFinDespVal  = pc.Isn_CtaFin
                                           Where pc.Tip_CtaFin = 'A')
             
                EXEC PR_ProxNumero 'Vale', @WCodDoc output
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      RollBack Transaction
                    Return
                  end
                
                -- inclui vale
                Insert into VALES
                  (Cod_Estabe, Cod_Vale, Des_Vale, Tip_Entid, Cod_Entid, Dat_Emissa, Val_Vale, Vlr_DspEmb, Deb_Cre, 
                   Cod_CtrLanAut, Num_CtrLanAut, Isn_CtaFinEntid, Isn_CtaFinDeb, Isn_CtaFinCre, Usuario, Transacao)
                Values
                  (@CodEstabe, @WCodDoc,'NFE Devolucao Protocolo: '+cast(@NumPrt as varchar), @TipEmi, @CodEmi, @DatMov, @ValNot+@ValDspEmb, @ValDspEmb, 'C',
                   'DNE', @NumPrt, @WIsnCtaFinEntid, @to_IsnCtaFinDeb, @to_IsnCtaFinCre, @Usuario, @Now)
              end
          end
        else
          begin
            -- lancamentos gerenciais
            Set @ValNot = (Select Vlr_Nota From NFECB Where Cod_Estabe = @CodEstabe and Protocolo = @NumPrt)
            Set @IdTransacao = (Select Id_Transacao From NFECB Where Cod_Estabe = @CodEstabe and Protocolo = @NumPrt)
            
            if @IdTransacao = 0     
              begin
                EXEC PR_ProxNumeroEstab @CodEstabe, 'Id_Transacao', @IdTransacao output
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      RollBack Transaction
                    Return
                  end
        
                Update NFECB
                   Set Id_Transacao = @IdTransacao
                 Where Cod_Estabe = @CodEstabe 
                   And Protocolo = @NumPrt 
              end
              
            -- inclui conta credora
            if @to_IsnCtaFinCre > 0
              begin
                Exec PR_AtualizaPCMOV 'I', @CodEstabe, @to_IsnCtaFinCre, @DatMov, 'NFECB', 'NFE', '', @NumPrt, 0, @IdTransacao, @ValNot
              end
        
            -- inclui conta devedora
            if @to_IsnCtaFinDeb > 0
              begin
                Set @ValNot = -@ValNot
                Exec PR_AtualizaPCMOV 'I', @CodEstabe, @to_IsnCtaFinDeb, @DatMov, 'NFECB', 'NFE', '', @NumPrt, 0, @IdTransacao, @ValNot
              end
          end


        -- ATENCAO: o fechamento do pedido era feito no módulo servidor por causa da rotina de geração de previsões: 05/09/2015
        -- fecha pedidos de compras relacionados
        -- pedido de compra atualizado se na NF atual a Flg_MovEst = 1
        if @FlgMovEst = 1
          begin
            if Exists(Select 1 From NFEPC Where Cod_Estabe = @CodEstabe and Protocolo = @NumPrt)
              begin
                -- registra data da entrada da nota no pedido de compra
                Update p
                   Set p.Dat_Entrada = @DatMov
                  From NFEPC n
                       Inner Join PDCCB p on n.Cod_Estabe = p.Cod_Estabe and n.Cod_Pedido = p.Numero
                 Where n.Cod_Estabe = @CodEstabe
                   And n.Protocolo = @NumPrt
       
                Declare Nfepc_Cr Cursor Local Fast_Forward For 
                  Select n.Cod_Pedido
                    From NFEPC n
                         Inner Join PDCCB p on n.Cod_Estabe = p.Cod_Estabe and n.Cod_Pedido = p.Numero
                   Where n.Cod_Estabe = @CodEstabe
                     And n.Protocolo = @NumPrt
	      	   And p.Status <> 'F'
              end
            else
              begin
                -- registra data da entrada da nota no pedido de compra
                Update p
                   Set p.Dat_Entrada = @DatMov
                  From NFEPC n
                       Inner Join PDCCB p on n.Cod_Estabe = p.Cod_Estabe and n.Cod_Pedido = p.Numero
                 Where n.Cod_Estabe = @CodEstabe
                   And n.Protocolo = @NumPrtVincOpeVdo
         
                Declare Nfepc_Cr Cursor Local Fast_Forward For 
                  Select n.Cod_Pedido
                    From NFEPC n
	      	       Inner Join PDCCB p on n.Cod_Estabe = p.Cod_Estabe and n.Cod_Pedido = p.Numero
                   Where n.Cod_Estabe = @CodEstabe
                     And n.Protocolo = @NumPrtVincOpeVdo
	      	   And p.Status <> 'F'
              end
            Open Nfepc_Cr
            Fetch Next From Nfepc_Cr Into @NumPed
            While @@FETCH_STATUS = 0
              begin
                -- aqui ao reabrir, Qtd_Fatura ficou = 0
                -- fechar com @NumPrt = 0
                -- Exec PR_FechaPDC @CodEstabe, @NumPed, @NumPrt
                Exec PR_FechaPDC @CodEstabe, @NumPed, 0
         
                Fetch Next From Nfepc_Cr Into @NumPed
              end
            Close Nfepc_Cr
            Deallocate Nfepc_Cr
          end  -- @FlgMovEst = 1

        -- calcula prazo medio de compra ???????
        -- DMD-6717: Análise e ajuste na informação de prazo médio de compra no relatório "Prazo Médio de Compras".	
		Update cb
           Set Qtd_PrzMed = Case
                              When cb.Tip_NF = 'C' Then IsNull(pg.QtdPrzMed,0)
                              Else 0
                            End
          From NFECB cb
               Left Join (Select Cod_Estabe, Cod_PrtNfe, 
                                 QtdPrzMed = sum(DATEDIFF(day, Dat_Emissa, Dat_Vencim)) / 
                                             (select count( cod_prtnfe) from pagct where Cod_Estabe = @CodEstabe and Cod_PrtNfe = @NumPrt)
                            from PAGCT
                           Where IsNull(Cod_PrtNfe,0) > 0
                             And IsNull(Dat_Vencim,0) >= IsNull(Dat_Emissa,0)
                           Group by Cod_Estabe, Cod_PrtNfe) pg on cb.Cod_Estabe = pg.Cod_Estabe and cb.Protocolo = pg.Cod_PrtNfe
         Where cb.Cod_Estabe = @CodEstabe 
           And cb.Protocolo = @NumPrt;


        -- cancela estoque pulmão (notas abertas importadas xml aguardando fechamento)
        Exec PR_ManutencaoEstoquePulmao @CodEstabe, @NumPrt
        if @@error <> 0
          begin
            if @@trancount > 0
              RollBack Transaction
            Return
          end
       
        -- importa pedidos desconsolidados se for o caso
        if @IdPdvCon > 0
          begin
            -- 'A': Altera todos os preços (Pr.Cadastro-Desc.Autom)
            Exec PR_GeraPedidosDesconsolidados @IdPdvCon, ''
            if @@error <> 0
              begin
                if @@trancount > 0
                  RollBack Transaction
                Return
              end
          end

        -- atualiza itens na tabela de consignações
        if (@IdConsig > 0) and (@NumSeqCtr > 0)
          begin
            Exec PR_FaturaConsignacao 'E', @CodEstabe, '', @NumPrt, @IdConsig, @NumSeqCtr
            if (@@error <> 0)
              begin
                if @@trancount > 0
                  Rollback Transaction
                Return
              end
          end

        -- fatura consignação
        if @FlgFaturaConsig = 1
          begin
            Set @CodOpeSai = (Select top 1 Cod_Ope From TPOPE 
                               Where Tip_EntSai = 'S' 
                                 and CharIndex(cast(Cod_CfoNorInt as varchar),';5112;5114;') > 0 
                                 and CharIndex(cast(Cod_CfoNorExt as varchar),';6112;6114;') > 0
                                 and Tip_Ope = 'V' and IsNull(Flg_Bloqueado,0) = 0)

            Exec PR_GeraNfsFatConsig @CodEstabe, @NumPrt, @CodOpeSai, @SerNotSai output, @NumNotSai output, @MsgErr output
            if @@error <> 0
              begin
                if @@trancount > 0
                  RollBack Transaction
                Return
              end
          end

      end  -- if @FlgPodeFechar = 1

    IF OBJECT_ID('tempdb..#ARQ_NELTL') IS NOT NULL
      DROP TABLE #ARQ_NELTL

    if @@trancount > 0          
      Commit Transaction   
  END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraNfeDevConsig]
@PCodEstabe int,
@PIdConsig int,
@PNumSequen smallint,
@PNumSeqDev smallint,
@PCodOpeEnt varchar(3),
@PNumProtoc int output,
@PMsgErr varchar(8000) output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = cast(GetDate() as Date)

Set @PNumProtoc = 0
Set @PMsgErr = ''

if not Exists(Select 1 
                From CNGCB cb
                     Inner Join CLIEN cl on cb.Cod_TipCng = 'C' and cb.Cod_Entida = cl.Codigo 
               Where cb.Cod_Estabe = @PCodEstabe And cb.Id_Consig = @PIdConsig)
  Set @PMsgErr = 'Clinte inválido'

if not Exists(Select 1 
                From CNGDC 
               Where Cod_Estabe = @PCodEstabe And Id_Consig = @PIdConsig 
                 And Num_Sequen = @PNumSequen And Num_SeqDev = @PNumSeqDev
			     And Sta_CngPed = '1') 
  Set @PMsgErr = 'Não existe devolução a gerar'

if not Exists(Select 1 
                From CNGDI it 
               Where it.Cod_Estabe = @PCodEstabe And it.Id_Consig = @PIdConsig 
                 And it.Num_Sequen = @PNumSequen And Num_SeqDev = @PNumSeqDev
                 And it.Qtd_Pedido > 0)
  Set @PMsgErr = 'Não existe itens a devolver'

if not Exists(Select 1 
                From CNGDI it 
                     Inner Join PRXES pr on it.Cod_Estabe = pr.Cod_Estabe and it.Cod_Produt = pr.Cod_Produt 
               Where it.Cod_Estabe = @PCodEstabe And it.Id_Consig = @PIdConsig 
                 And it.Num_Sequen = @PNumSequen And Num_SeqDev = @PNumSeqDev)
  Set @PMsgErr = 'Não existe itens a devolver'

if Exists(Select 1 
            From NFECB 
           Where Cod_Estabe = @PCodEstabe and Id_Consig = @PIdConsig 
             And Num_SeqCtr = @PNumSequen And Num_SeqDev = @PNumSeqDev)
  Set @PMsgErr = 'Nota de devolução já foi gerada'


-- 1919/2919: dev.simbolica de mecadoria
if ((Select Tip_Devolu From CNGDC 
      Where Cod_Estabe = @PCodEstabe And Id_Consig = @PIdConsig 
        And Num_Sequen = @PNumSequen And Num_SeqDev = @PNumSeqDev) = 'S') and
   (not Exists(Select 1 
                 From TPOPE 
                Where Tip_EntSai = 'E' 
                  and CharIndex(cast(Cod_CfoNorInt as varchar),';1919;') > 0 
                  and CharIndex(cast(Cod_CfoNorExt as varchar),';2919;') > 0 
                  and Cod_Ope = @PCodOpeEnt and Tip_Ope = 'D'))
  Set @PMsgErr = 'Tipo de operação ('+@PCodOpeEnt+'/D/1919/2919) inválido para Devolução de Consignação'

-- 1918/2918: dev.de mercadoria remetida em consignação 
if ((Select Tip_Devolu From CNGDC 
      Where Cod_Estabe = @PCodEstabe And Id_Consig = @PIdConsig 
        And Num_Sequen = @PNumSequen And Num_SeqDev = @PNumSeqDev) = 'E') and
   (not Exists(Select 1 
                 From TPOPE 
                Where Tip_EntSai = 'E' 
                  and CharIndex(cast(Cod_CfoNorInt as varchar),';1918;') > 0 
                  and CharIndex(cast(Cod_CfoNorExt as varchar),';2918;') > 0
                  and Cod_Ope = @PCodOpeEnt and Tip_Ope = 'D'))
  Set @PMsgErr = 'Tipo de operação ('+@PCodOpeEnt+'/D/1918/2918) inválido para Devolução de Consignação'

if not Exists(Select 1
                From NFSCB cb 
                     Inner Join NFSIT it on it.Cod_Estabe = cb.Cod_Estabe and it.Ser_Nota = cb.Ser_Nota And it.num_Nota = cb.Num_Nota
                     Inner Join CNGDI dv on dv.Cod_Estabe = it.Cod_Estabe and dv.Cod_Produt = it.Cod_Produto and dv.Cod_Lote = it.Cod_Lote
                                     and dv.Id_Consig = cb.Id_Consig  and dv.Num_Sequen = @PNumSequen --cb.Num_SequenciaCtr
               Where cb.Cod_Estabe = @PCodEstabe
                 And cb.Id_Consig  = @PIdConsig) 
                 --And cb.Num_SequenciaCtr = @PNumSequen)
  Set @PMsgErr = 'Não existe NF de Remessa de Consignação vinculada'

if ((Select dbo.FN_ModExtOk(HASHBYTES('MD5','WMS'),
                            HASHBYTES('MD5',(Select Num_Cnpj From ESTAB Where Cod_Estabe = @PCodEstabe)))) = 1) and
   ((Select Tip_Devolu From CNGDC 
      Where Cod_Estabe = @PCodEstabe And Id_Consig = @PIdConsig 
        And Num_Sequen = @PNumSequen And Num_SeqDev = @PNumSeqDev) = 'S') and
   not Exists(Select top 1 1 From TBZON Where Cod_Estabe = @PCodEstabe and Flg_CrossDocking = 1)
  Set @PMsgErr = 'Não existe zona de Cross Docking configurada (devolução simbólica)'

if @PMsgErr = ''
BEGIN
  BEGIN TRANSACTION

  Declare @TipDevoluCng varchar(1),
          @CodCliCng int,
 
          @SerNot varchar(3),
          @NumNot int,
          @CodCfoSai int,

          @WFlgUsaWms bit,

          @NumSeqIte int,
          @CodPrd int,
          @CodLot varchar(20),
          @QtdMov int,
          @PrcUni numeric(18,4),
          @PerDsc numeric(7,4),

          @CodVended int,
          @CodOperad int,

          @TipLoc varchar(1), 
          @CodDep smallint, 
          @NumRua smallint,  
          @NumCol smallint, 
          @NumNiv smallint, 
          @NumApt smallint,
          @QtdEmbFec smallint, 

          @op_TipOpe varchar(1), 
          @op_CodCfo int,
          @cb_CodRegTri int,
          @cb_CodEst varchar(2),
		  @Usuario varchar(35)

  -- usuario infarma auditoria
  Set @Usuario = dbo.FN_UsuarioInfarma()

  -- WMS
  Set @WFlgUsaWms = (Select dbo.FN_ModExtOk(HASHBYTES('MD5','WMS'),
                                            HASHBYTES('MD5',(Select Num_Cnpj From ESTAB Where Cod_Estabe = @PCodEstabe))))

  Set @TipDevoluCng = (Select Tip_Devolu From CNGDC 
                        Where Cod_Estabe = @PCodEstabe And Id_Consig = @PIdConsig 
                          And Num_Sequen = @PNumSequen And Num_SeqDev = @PNumSeqDev)

  Select top 1 @SerNot    = cb.Ser_Nota, 
               @NumNot    = cb.Num_Nota,
               @CodCfoSai = cb.Cod_Cfo1,
               @CodVended = cb.Cod_Vendedor,
               @CodOperad = cb.Cod_VendTlmkt
    From NFSCB cb 
         Inner Join NFSIT it on it.Cod_Estabe = cb.Cod_Estabe and it.Ser_Nota = cb.Ser_Nota And it.num_Nota = cb.Num_Nota
         Inner Join CNGDI dv on dv.Cod_Estabe = it.Cod_Estabe and dv.Cod_Produt = it.Cod_Produto and dv.Cod_Lote = it.Cod_Lote
                            and dv.Id_Consig  = cb.Id_Consig  and dv.Num_Sequen = cb.Num_SequenciaCtr
   Where cb.Cod_Estabe = @PCodEstabe
     And cb.Id_Consig  = @PIdConsig 
     And cb.Num_SequenciaCtr = @PNumSequen

  Select @CodCliCng = cl.Codigo
    From CNGCB cb
         Inner Join CLIEN cl on cb.Cod_TipCng = 'C' and cb.Cod_Entida = cl.Codigo 
   Where cb.Cod_Estabe = @PCodEstabe And cb.Id_Consig = @PIdConsig

  Select @op_TipOpe = Tip_Ope, 
         @op_CodCfo = Case When IsNull(@CodCfoSai,0) < 6000 then Cod_CfoNorInt else Cod_CfoNorExt End
    From TPOPE
   Where Cod_Ope = @PCodOpeEnt

  -- grava novo cabeçalho de NF
  -- Pega novo numero (protocolo)
  EXEC PR_ProxNumero 'Protocolo', @PNumProtoc output

  -- grava cabecalho
  Insert Into NFECB (Cod_Estabe,  Protocolo,   Cod_Ope,     Cod_Cfo,    Tip_NF,     Id_Consig,  Num_SeqCtr,  Num_SeqDev)
             Values (@PCodEstabe, @PNumProtoc, @PCodOpeEnt, @op_CodCfo, @op_TipOpe, @PIdConsig, @PNumSequen, @PNumSeqDev) 
  if @@error <> 0 
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  -- grava campos na nota
  Update cb
     Set cb.Especie = 'NF', 
         cb.Status ='A', 
         cb.Status_2 = '',
         cb.Dat_Movimento = @Date, 
         cb.Dat_Emissao = @Date, 
         cb.Dat_Entrada = @Date, 
         cb.Flg_WMS = @WFlgUsaWms,
         cb.Flg_CrossDocking = Case 
                                 When (@WFlgUsaWms = 1) and (@TipDevoluCng = 'S') then 1 
                                 Else 0 
                               End,
         cb.Flg_MovEst = 1, 
         cb.Flg_ImpNot = 1, 
         cb.Flg_DevTot = 0,

         cb.Qtd_PagNF = 1, 
         cb.Ser_SeloFisTran = '', 
         cb.Cod_FinNfe = '4',       -- devolução
         cb.Tip_Frete = '1',
 
         cb.Tip_DocRel = 'S',
         cb.Str_RelDoc = @SerNot+','+cast(@NumNot as varchar),
         cb.Flg_CalTrbDevCfg = 0,

         cb.Cod_Vendedor = @CodVended,   
         cb.Cod_VendTlmkt = @CodOperad,  
         cb.Tip_Emitente = 'C', 
         cb.Cod_EmiCliente = @CodCliCng, 
         cb.Cod_EmiFornec = 0,
         cb.Cod_EmiTransp = 0,
         cb.Cod_RegTri = en.Cod_RegTri,
         cb.Pessoa = cl.Pessoa,
         cb.Cgc_Cpf = cl.Cgc_Cpf,
         cb.Cgf_Rg = cl.Cgf,
         cb.Endereco = SUBSTRING(dbo.FN_EnderecoCompleto(cl.Endereco, cl.Numero, cl.Complemento),1,50),
         cb.Bairro = ba.Descricao,
         cb.Cidade = ci.Descricao,
         cb.Cod_UfOrigem = cl.Cod_Estado,
         cb.Cep = cl.Cep,
         cb.Cod_CidIbge = ci.Cod_CidIbge,
         cb.Usuario = @Usuario, 
         cb.Transacao = @Now
    From NFECB cb 
         Inner Join CLIEN cl on (cl.Codigo = @CodCliCng) 
         Left  Join CIDAD ci on ((cl.Cod_Estado = ci.Cod_Estado) and (cl.Cod_Cidade = ci.Codigo)) 
         Left  Join BAIRR ba on ((cl.Cod_Estado = ba.Cod_Estado) and (cl.Cod_Cidade = ba.Cod_Cidade) and (cl.Cod_Bairro = ba.Codigo))
         Left  Join ENXES en on ((cb.Cod_Estabe = en.Cod_Estabe) and (cl.Cgc_Cpf = en.Num_CgcCpf)) 
   Where cb.Cod_Estabe = @PCodEstabe
     And cb.Protocolo = @PNumProtoc

  Delete From NELTL 
   Where Cod_Estabe = @PCodEstabe 
     and Num_Protoc = @PNumProtoc

  Select @cb_CodRegTri = Cod_RegTri,
         @cb_CodEst = Cod_UfOrigem
    From NFECB
   Where Cod_Estabe = @PCodEstabe
     And Protocolo = @PNumProtoc
 
  Set @NumSeqIte = 0

  DECLARE CNGDI_Cr CURSOR Local Fast_Forward For 
  
    Select dv.Cod_Produt, dv.Cod_Lote, dv.Qtd_Pedido, 
           C_PrcUni = Case When it.Cod_Produto > 0 then it.Prc_Unitario Else dv.Prc_Unitar End, 
           C_PerDsc = Case When it.Cod_Produto > 0 then it.Per_Desconto Else dv.Per_Descon End
      From CNGDI dv
           Left Join (Select Cod_Produto, Cod_Lote, 
                             Prc_Unitario = max(Prc_Unitario), 
                             Per_Desconto = max(Per_Desconto)
                        From NFSIT
                       Where Cod_Estabe = @PCodEstabe
                         And Ser_Nota = @SerNot
                         and Num_Nota = @NumNot
                       Group by Cod_Produto, Cod_Lote
		             ) it on dv.Cod_Produt = it.Cod_Produto and dv.Cod_Lote = it.Cod_Lote 
     Where dv.Cod_Estabe = @PCodEstabe 
       And dv.Id_Consig  = @PIdConsig 
       And dv.Num_Sequen = @PNumSequen 
       And dv.Num_SeqDev = @PNumSeqDev
       And dv.Qtd_Pedido > 0
  
  OPEN CNGDI_Cr
  FETCH NEXT FROM CNGDI_Cr INTO @CodPrd, @CodLot, @QtdMov, @PrcUni, @PerDsc
  WHILE @@FETCH_STATUS = 0
  BEGIN
    -- grava itens da nota
    Set @NumSeqIte = @NumSeqIte + 1
  
    -- aqui deveria pegar preço e desconto conforme NF de saída origem
    Insert Into NFEIT (Cod_Estabe,  Protocolo,   Cod_Produto, Cod_Lote, Num_SeqIte, Tip_Ent, Qtd_Pedido, Qtd_PedFat, Qtd_Bonificacao, Prc_Unitario, Per_DescItem, FATOR_FAT, Prc_UniFat) 
               Values (@PCodEstabe, @PNumProtoc, @CodPrd,     @CodLot,  @NumSeqIte, '',      @QtdMov,    @QtdMov   , 0,               @PrcUni,      @PerDsc,      1,        @PrcUni)
  
    -- atualiza campos do item da nota
    Update NFEIT
       Set Vlr_BruItem = Round(Prc_Unitario*(Qtd_Pedido+Qtd_Bonificacao),2),
           Vlr_TotItem = Round(Qtd_Pedido*(Prc_Unitario*(1-Per_DescItem/100)),2),
           Vlr_DescItem = 0
     Where Cod_Estabe = @PCodEstabe
       And Protocolo = @PNumProtoc
       And Cod_Produto = @CodPrd 
       And Cod_Lote = @CodLot 
       And Num_SeqIte = @NumSeqIte
  
    -- calcula tributacao
    --Exec PR_CalcTributNFEIT @PCodEstabe, @PNumProtoc, @CodPrd, @CodLot, @NumSeqIte,
    --                        @op_TipOpe, @cb_CodRegTri, 0

    -- NELTL....
    if @WFlgUsaWms = 1
      begin
		Set @CodDep = IsNull((Select min(Cod_Dep) From TBDEP Where Cod_Estabe = @PCodEstabe),1)

        if (Select FlgIntegrWmsExt From PMEST Where Cod_Estabe = @PCodEstabe) = 1
          begin
            Insert Into NELTL (Tip_Local, Cod_Estabe, Num_Protoc, Cod_Produt, Cod_Lote, 
                               Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, 
                               Qtd_Est, Qtd_EmbFec) 
              Select 'P', it.Cod_Estabe, it.Protocolo, it.Cod_Produto, it.Cod_Lote, 
                      dp.Cod_Dep, IsNull(dp.Num_Rua,0), IsNull(dp.Num_Col,0), IsNull(dp.Num_Niv,0), IsNull(dp.Num_Apt,0), 
                      it.QtdTotEnt, p.Qtd_Embalagem 
                From (Select Cod_Estabe, Protocolo, Cod_Produto, Cod_Lote, QtdTotEnt = SUM(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) 
                        From NFEIT 
                       Group by Cod_Estabe, Protocolo, Cod_Produto, Cod_Lote) it Inner Join
                     PRXES pr on pr.Cod_Estabe = it.Cod_Estabe and pr.Cod_Produt = it.Cod_Produto Inner Join  
                     PRODU p on pr.Cod_Produt = p.Codigo Inner Join 
                     DPXPR dp on dp.Cod_Estabe  = it.Cod_Estabe And pr.Cod_Produt = dp.Cod_Produt 
               Where it.Cod_Estabe = @PCodEstabe
                 And it.Protocolo = @PNumProtoc
                 And dp.Cod_Dep = @CodDep
          end
        else
          begin
            -- cria endereço cross docking
            if @TipDevoluCng = 'S'
              begin
                Set @NumRua = (Select top 1 Num_RuaIni From TBZON Where Cod_Estabe = @PCodEstabe and Flg_CrossDocking = 1)
                Set @NumCol = IsNull((Select max(Num_Col) From ENDDP Where Cod_Estabe = @PCodEstabe and Cod_Dep = @CodDep),0) + 1
              end
            else
              begin
                Set @NumRua = (Select zn.Num_RuaIni 
                                 From TBZON zn 
                                      inner join PMEST pm on zn.Cod_Estabe = pm.Cod_Estabe 
                                Where zn.Cod_Estabe = @PCodEstabe
                                  And zn.Cod_Dep = @CodDep
                                  And zn.Cod_Zon = pm.CodZonDev)
                Set @NumCol = 1
              end		    

            Set @NumNiv = 1
            Set @NumApt = 0

            -- elimina endereços órfãos
            if @TipDevoluCng = 'S'
              begin
                Delete en
                  From ENDDP en
                       Left Join NFECB cb on en.Cod_Estabe = cb.Cod_Estabe and en.Num_Cntrol = cb.Protocolo
                 Where IsNull(en.Cod_Cntrol,'') = 'NFE'  
                   And IsNull(en.Num_Cntrol,0) > 0
                   And cb.Protocolo is null

                Delete From ENDDP 
                 Where Cod_Estabe = @PCodEstabe 
                   And Cod_Dep = @CodDep        
                   And Num_Rua = @NumRua        
                   And Num_Col = @NumCol       

                Insert Into ENDDP (Cod_Estabe,  Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_Cntrol, Num_Cntrol,  Flg_Bloqueado)
                           Values (@PCodEstabe, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, 'NFE',      @PNumProtoc, 1)
              end

            Set @TipLoc = dbo.FN_TipLocEnd(@PCodEstabe, @CodDep, @NumRua)
            Set @QtdEmbFec = @QtdMov

            Insert Into NELTL (Cod_Estabe, Num_Protoc, Cod_Produt, Cod_Lote,
                               Tip_Local, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt,
                               Qtd_Est, Qtd_EmbFec)
                       Values (@PCodEstabe, @PNumProtoc, @CodPrd, @CodLot,
                               @TipLoc, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt,
                               @QtdMov, @QtdEmbFec)
          end
      end

    if @@error <> 0
      begin
        if @@trancount > 0
          Rollback Transaction
        Return
      end
  
    FETCH NEXT FROM CNGDI_Cr INTO @CodPrd, @CodLot, @QtdMov, @PrcUni, @PerDsc
  END
  
  CLOSE CNGDI_Cr
  DEALLOCATE CNGDI_Cr     

  -- calcula tributos da NF
  Exec PR_CalcTributNFECB @PCodEstabe, @PNumProtoc, 1
  if @@error <> 0
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  -- atualiza dados do cabecalho da nota gerada
  Exec PR_NormalizaValoresNFE @PCodEstabe, @PNumProtoc
  if @@error <> 0
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  -- atualiza status CNGDC
  Update CNGDC 
     Set Sta_CngPed = '2',
         Num_Protoc = @PNumProtoc
   Where Cod_Estabe = @PCodEstabe And Id_Consig = @PIdConsig 
     And Num_Sequen = @PNumSequen And Num_SeqDev = @PNumSeqDev

  -- fecha NFE: gera NF fatura se for devolução simbólica: CNGDC.Tip_Devolu = 'S'
/*  executa fechamento no Delphi
  Exec PR_FechaNFE @PCodEstabe, @PNumProtoc, 0, 0, '', @PMsgErr output
  if @@error <> 0
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end
*/

  if @@trancount > 0  
    COMMIT TRANSACTION
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE TRIGGER [dbo].[TR_PRLTL_AtualizaSaldoDisponivel] ON [dbo].[PRLTL]
FOR INSERT, UPDATE, DELETE 
NOT FOR REPLICATION
AS

-- comando p/ corrigir erro delphi/ado: record was changed by another user
SET NOCOUNT ON 
SET ANSI_WARNINGS OFF

IF trigger_nestlevel() > 4 
  RETURN

Declare @FlgAtu bit

Set @FlgAtu = 0

if Update(Qtd_FisPra) or Update(Qtd_SolPra)
  begin
    Set @FlgAtu = 1
    Update L
       Set L.Qtd_SldPra = IsNull(I.Qtd_FisPra,0) - IsNull(I.Qtd_SolPra,0)
      From Inserted I inner Join 
           PRLTL L on L.Cod_Estabe = I.Cod_Estabe and L.Cod_Produt = I.Cod_Produt and 
                      L.Cod_Lote = I.Cod_Lote and IsNull(L.Qtd_EmbFec,0) = IsNull(I.Qtd_EmbFec,0) and 
                      L.Cod_Dep = I.Cod_Dep and L.Num_Rua = I.Num_Rua and L.Num_Col = I.Num_Col and 
                      L.Num_Niv = I.Num_Niv and L.Num_Apt = I.Num_Apt
  end


if Update(Qtd_FisDep) or Update(Qtd_SolDep)
  begin
    Set @FlgAtu = 1
    Update L
       Set L.Qtd_SldDep = IsNull(I.Qtd_FisDep,0) - IsNull(I.Qtd_SolDep,0)
      From Inserted I inner Join 
           PRLTL L on L.Cod_Estabe = I.Cod_Estabe and L.Cod_Produt = I.Cod_Produt and 
                      L.Cod_Lote = I.Cod_Lote and IsNull(L.Qtd_EmbFec,0) = IsNull(I.Qtd_EmbFec,0) and 
                      L.Cod_Dep = I.Cod_Dep and L.Num_Rua = I.Num_Rua and L.Num_Col = I.Num_Col and 
                      L.Num_Niv = I.Num_Niv and L.Num_Apt = I.Num_Apt
  end


if @FlgAtu = 1
  begin
    Update L
       Set L.Qtd_Fisico = IsNull(I.Qtd_FisPra,0) + IsNull(I.Qtd_FisDep,0),
           L.Qtd_Solicitado = IsNull(I.Qtd_SolPra,0) + IsNull(I.Qtd_SolDep,0),
           L.Qtd_Saldo = IsNull(I.Qtd_FisPra,0) - IsNull(I.Qtd_SolPra,0) + IsNull(I.Qtd_FisDep,0) - IsNull(I.Qtd_SolDep,0)
      From Inserted I inner Join 
           PRLTL L on L.Cod_Estabe = I.Cod_Estabe and L.Cod_Produt = I.Cod_Produt and 
                      L.Cod_Lote = I.Cod_Lote and IsNull(L.Qtd_EmbFec,0) = IsNull(I.Qtd_EmbFec,0) and 
                      L.Cod_Dep = I.Cod_Dep and L.Num_Rua = I.Num_Rua and L.Num_Col = I.Num_Col and 
                      L.Num_Niv = I.Num_Niv and L.Num_Apt = I.Num_Apt
  end

Update L
   Set L.Fat_CnvAprEmbPad = ap.Fat_CnvApr
  From PRLTL L   
       Inner Join Inserted I on L.Cod_Estabe = I.Cod_Estabe and 
                                L.Cod_Produt = I.Cod_Produt and L.Cod_Lote = I.Cod_Lote and 
                                L.Qtd_EmbFec = I.Qtd_EmbFec and 
                                L.Cod_Dep = I.Cod_Dep and L.Num_Rua = I.Num_Rua and 
                                L.Num_Col = I.Num_Col and L.Num_Niv = I.Num_Niv and
                                L.Num_Apt = I.Num_Apt
       Inner Join PARAM pm on L.Cod_Estabe = pm.Cod_Estabe
       Inner Join PRXAP ap on L.Cod_Produt = ap.Cod_Produt and ap.Flg_Padrao = 1
 Where Case 
         When IsNull(pm.FlgAltUnvItePdv,0) = 1 then ap.Fat_CnvApr
         Else 1
       End <> L.Fat_CnvAprEmbPad

if Update(Qtd_EmbFec) or Update(Fat_CnvAprEmbPad)
  begin
    Update L
       Set L.C_QtdEmbFec = IsNull(L.Qtd_EmbFec,0) * IsNull(L.Fat_CnvAprEmbPad,0) -- aqui atenção
      From Inserted I inner Join 
           PRLTL L on L.Cod_Estabe = I.Cod_Estabe and L.Cod_Produt = I.Cod_Produt and 
                      L.Cod_Lote = I.Cod_Lote and IsNull(L.Qtd_EmbFec,0) = IsNull(I.Qtd_EmbFec,0) and 
                      L.Cod_Dep = I.Cod_Dep and L.Num_Rua = I.Num_Rua and L.Num_Col = I.Num_Col and 
                      L.Num_Niv = I.Num_Niv and L.Num_Apt = I.Num_Apt
  end					    

-- se nao existir cria lote em PRLOT
Insert into PRLOT(Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Dat_Vencim, Dat_Fabric, Qtd_FisPra, Qtd_SolPra, Qtd_FisDep, Qtd_SolDep)
  Select distinct I.Cod_Estabe, I.Cod_Dep, I.Cod_Produt, I.Cod_Lote, I.Dat_Vencim, I.Dat_Fabric, 0, 0, 0, 0
    From Inserted I
   Where I.Qtd_Fisico > 0
	And not exists (Select Cod_Produt From PRLOT T Where ((I.Cod_Estabe = T.Cod_Estabe) and (I.Cod_Dep = T.Cod_Dep) and (I.Cod_Produt = T.Cod_Produt) and (I.Cod_Lote = T.Cod_Lote))) 

-- Atualizar Saldo disponivel do deposito fechado em PRLOT
                   
-- Atualiza quantidade em quarentena (segregada) em PRXES

-- Atualiza Vencto prox. lote em PRXES
Update P
   Set P.Dat_PrxVctLtl = l.Dat_Vencim
  From PRXES P  
       inner join Inserted I on (P.Cod_Estabe = I.Cod_Estabe And P.Cod_Produt = I.Cod_Produt) 
       left  join (Select r.Cod_Estabe, r.Cod_Produt, Dat_Vencim = MIN(r.Dat_Vencim) 
                     From PRLTL r
                     Where r.Qtd_Saldo > 0 
                       And dbo.FN_TipLocEnd(r.Cod_Estabe, r.Cod_Dep, r.Num_Rua) = 'D'
                     Group by r.Cod_Estabe, r.Cod_Produt) l on ((P.Cod_Estabe = l.Cod_Estabe) and (P.Cod_Produt = l.Cod_Produt)) 
  Where @FlgAtu = 1
                                      
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_RetornaPoliticasProduto]
(
 @PCodOri varchar(1),      -- Origem (A-Ativo, P-Receptivo, M-Móvel, T-Eletronico/EDI, W-Internet/WEB, H-Hospitalar, D-por Desdobramento, V-por Val)
 @PCodEstabe int,
 @PCodCli int,             
 @PCodVdr int,             -- OPCIONAL: cod.vendedor 
 @PCodOpe int,             -- OPCIONAL: cod.operador 
 @PIdPolComCab int,     
 @PCodPrd int,
 @PDatRef smalldatetime,
 @PCodLayPde int,          -- OPCIONAL: layout pedido eletronico
 @PCodGrpLay int           -- OPCIONAL: grupo do layout pedido eletronico
)

RETURNS @retPoliticas TABLE 
  ( 
	Id_PolCom int,
    Cod_PolCom varchar(25),
	Dat_Cadastro smalldatetime,
	Flg_NegDsc bit,
    Flg_AcuVrbPos bit, 
    Flg_AcuVrbNeg bit, 
    Flg_MarkupCusCom bit, 
    Tip_RatBon varchar(1), 
    Tip_GerVrb varchar(1), 
    Flg_CtrPdvVrbVdr bit, 
    Flg_CtrPdvVrbOpe bit, 
    Controle_Saldo varchar(1), 
    Per_AcrAutPrc numeric(9,4), 
    Per_DscAutPrc numeric(9,4), 
    Prc_Promoc numeric(18,8), 
    Qtd_PrzMax smallint, 
    Per_Descon numeric(7,4), 
	Per_DscVis numeric(7,4), 
    Qtd_Minimo smallint, 
	Qtd_Maximo smallint, 
    Ordem smallint, 
    Nivel varchar(1),
    Val_PrcTab numeric(18,4),
    Per_DscMaxTab numeric(7,4),
    Prc_Unitar numeric(18,4)
  ) 

--Retorna todas politicas permitidas para o produto

AS

BEGIN

Declare @pm_QtdDecPrcItePdv tinyint,
		@pr_CodCla varchar(2),
        @pr_PrcVen numeric(18,4),
		@pr_PerDscAut numeric(6,4),

		@WTipPrz char(1),
		@WFlgExcClaPolComCab bit,
        @WQtdPrzPolComCab int,
        @WFlgPolCabBlqOutPolIte bit

Select @pm_QtdDecPrcItePdv = IsNull(QtdDecPrcItePdv,0)
  From PARAM 
 Where Cod_Estabe = @PCodEstabe

Set @pr_CodCla = (Select Substring(Cod_Classif,1,2) From PRODU Where Codigo = @PCodPrd)

Select @pr_PrcVen = IsNull(Prc_Venda,0),
       @pr_PerDscAut = IsNull(Per_DscAut,0)
  From PRXES
 Where Cod_Estabe = @PCodEstabe 
   And Cod_Produt = @PCodPrd

Set @WQtdPrzPolComCab = 0
Set @WFlgPolCabBlqOutPolIte = 0
Set @WTipPrz = 'F'

if Exists(Select 1 From POCOM Where Id_PolCom = @PIdPolComCab)
  Select @WQtdPrzPolComCab = IsNull(Qtd_PrzMax,0),
         @WFlgPolCabBlqOutPolIte = IsNull(Flg_BlqPolDifItePdv,0),
		 @WTipPrz = IsNull(Cod_TipPrz,'F')
    From POCOM   
   Where Id_PolCom = @PIdPolComCab

Set @WFlgExcClaPolComCab = 0
if Exists(Select top 1 cp.Id_PolCom 
            From PCXCP cp Inner Join POCOM pc on (cp.Id_PolCom = pc.Id_PolCom) 
           Where cp.Id_PolCom = @PIdPolComCab
             And IsNull(pc.Flg_ExcCla,0) = 1) 
  Set @WFlgExcClaPolComCab = 1

Delete From @retPoliticas

Insert Into @retPoliticas
  Select p.Id_PolCom, p.Cod_PolCom, p.Dat_Cadastro, Flg_NegDsc=IsNull(p.Flg_NegDsc,0), 
         Flg_AcuVrbPos=IsNull(p.Flg_AcuVrbPos,0), Flg_AcuVrbNeg=IsNull(p.Flg_AcuVrbNeg,0), 
	     Flg_MarkupCusCom=IsNull(p.Flg_MarkupCusCom,0), Tip_RatBon=IsNull(p.Tip_RatBon,''), 
         TipGerVrb = dbo.FN_TipGerVrbPdv(p.Id_PolCom), Flg_CtrPdvVrbVdr=IsNull(p.Flg_CtrPdvVrbVdr,0), Flg_CtrPdvVrbOpe=IsNull(p.Flg_CtrPdvVrbOpe,0), 
         Controle_Saldo=IsNull(p.Controle_Saldo,''), Per_AcrAutPrc=IsNull(p.Per_AcrAutPrc,0), Per_DscAutPrc=IsNull(p.Per_DscAutPrc,0), 
         s.Prc_Promoc, s.Qtd_PrzMax, s.Per_Descon, s.Per_DscVis, s.Qtd_Minimo, s.Qtd_Maximo, s.Ordem, s.Nivel, 
         Val_PrcTab = IsNull(tp.Val_PrcVen,0), Per_DscMaxTab = IsNull(tp.Per_DscMax,0),
         Prc_Uni = Case
                     When s.Prc_Promoc > 0 then s.Prc_Promoc
                     When IsNull(tp.Val_PrcVen,0) > 0 then tp.Val_PrcVen
                     When IsNull(p.Per_AcrAutPrc,0) > 0 then Round(@pr_PrcVen*(1+p.Per_AcrAutPrc/100),@pm_QtdDecPrcItePdv)
                     When IsNull(p.Per_DscAutPrc,0) > 0 then Round(@pr_PrcVen*(1-p.Per_DscAutPrc/100),@pm_QtdDecPrcItePdv)
                     Else Round(@pr_PrcVen*(1-@pr_PerDscAut/100),@pm_QtdDecPrcItePdv)
                   End
    From POCOM p 
         Inner Join PCXES pe on ((p.Id_PolCom = pe.Id_PolCom) and (pe.Cod_Estabe = @PCodEstabe)) 
         Inner Join CLIEN cl on cl.Codigo = @PCodCli
         Left  Join ENXES es on es.Cod_Estabe = @PCodEstabe and es.Num_CgcCpf = cl.Cgc_Cpf and es.Cod_Client = cl.Codigo
         Left  Join PCXCL pc on ((p.Id_PolCom = pc.Id_PolCom) and (pc.Cod_Client = cl.Codigo)) 
         Left  Join PCXGC pg on ((p.Id_PolCom = pg.Id_PolCom) and (pg.Cod_GrpCli = cl.Cod_GrpCli)) 
         Left  Join PCXUF pu on ((p.Id_PolCom = pu.Id_PolCom) and (pu.Cod_Uf = cl.Cod_Estado)) 
         Left  Join PCXVE pv on ((p.Id_PolCom = pv.Id_PolCom) and (pv.Cod_Vended = @PCodVdr)) 
         Left  Join PCXOP po on ((p.Id_PolCom = po.Id_PolCom) and (po.Cod_Vended = @PCodOpe)) 
         Left  Join TBPRC tb on ((tb.Cod_Estabe = @PCodEstabe) or (tb.Flg_AllEstabe = 1)) 
		                    and (tb.Cod_TabPrc = Case 
                                                   When (IsNull(p.Flg_UsaTabPrcCadCli,0) = 1) and (IsNull(es.Cod_TabPrc,0) > 0) 
                                                     then es.Cod_TabPrc 
                                                   Else p.Cod_TabPrc
                                                 End)
         Left  Join TPXPR tp on ((tb.Cod_Estabe = tp.Cod_Estabe) and (tb.Cod_TabPrc = tp.Cod_TabPrc) and (tp.Cod_Produt = @PCodPrd))
         Left  Join dbo.FN_ViewPoliticasProduto(@PIdPolComCab, @PCodPrd, @PDatRef) s on (p.Id_PolCom = s.Id_PolCom) 

         Left  Join LGXPC lp on (lp.Cod_Estabe = @PCodEstabe and lp.Cod_Layout = @PCodLayPde and lp.Cod_Grupo = @PCodGrpLay and lp.Id_PolCom = p.Id_PolCom)
         Left  Join TBLPG lg on (lg.Cod_Estabe = lp.Cod_Estabe and lg.Cod_Layout = lp.Cod_Layout and lg.Cod_Grupo = lp.Cod_Grupo)

 Where ( (pc.Cod_Client > 0) or (pg.Cod_GrpCli > 0) or (pu.Cod_Uf <> '') ) 
   And ( (@PCodVdr = 0) or ((@PCodVdr > 0) and (pv.Cod_Vended = @PCodVdr)) )
   And ( (@PCodOpe = 0) or ((@PCodOpe > 0) and (po.Cod_Vended = @PCodOpe)) )
   And IsNull(s.Ordem,0) > 0
   And dbo.FN_PoliticaAtiva(p.Id_PolCom,@PDatRef) = 1
   And p.Tip_PolCom <> 'KIT'

   And (((@WTipPrz = 'L') and (s.Qtd_PrzMax >= @WQtdPrzPolComCab)) or 
        (@WTipPrz = 'F')) 
   And ((p.Flg_BlqCli = 0) or ((p.Flg_BlqCli = 1) and (IsNull(cl.Flg_BlqPrm,0) = 0)))

   And (((@PCodOri = 'M') and (p.Flg_Cfv = 1)) or
        ((@PCodOri = 'T') and (p.Flg_PedEle = 1)) or
        ((@PCodOri = 'W') and (p.Flg_Web = 1)) or
        ((Charindex(@PCodOri,';M;T;W;') = 0) and (p.Flg_Televendas = 1)))

   And @pr_CodCla = Case
                      When @WFlgExcClaPolComCab = 1 then 
                        Case
                          When Exists(Select Cod_Classi From PCXCP Where Id_PolCom = @PIdPolComCab And Cod_Classi = @pr_CodCla) then @pr_CodCla
                          Else '??'
                        End
                      Else @pr_CodCla
                    End

-- verifica se politica do cabecalho permite outrqas politica no item
   And p.Id_PolCom = Case
                       When @WFlgPolCabBlqOutPolIte = 1 then @PIdPolComCab
	                   Else p.Id_PolCom
                     End
-- verifica se há restrição de uso da politica do item
   And ((p.Flg_BlqPolDifCabPdv = 0) or (p.Id_PolCom = @PIdPolComCab))

-- verifica politicas vinculadas ao layout
   And ((IsNull(lg.Flg_UsaPolVnc,0) = 1) and (IsNull(lp.Id_PolCom,0) > 0) or (IsNull(lg.Flg_UsaPolVnc,0) = 0))

 Order by s.Nivel, p.Dat_Cadastro, s.Ordem, s.Id_PolCom 

RETURN
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_SugerePoliticaProduto]
(
 @PCodOri varchar(1),      -- Origem (A-Ativo, P-Receptivo, M-Móvel, T-Eletronico/EDI, W-Internet/WEB, H-Hospitalar, D-por Desdobramento, V-por Val)
 @PCodEstabe int,          -- cod.estabelecimento
 @PCodCli int,             -- codigo cliente
 @PCodVdr int,             -- OPCIONAL: cod.vendedor 
 @PCodOpe int,             -- OPCIONAL: cod.operador 
 @PIdPolComCab int,        -- politica do cabeçalho do pedido
 @PCodPrd int,             -- codigo produto
 @PQtdPed int,             -- OPCIONAL: quantidade produto
 @PCodLayPde int,          -- OPCIONAL: layout pedido eletronico
 @PCodGrpLay int           -- OPCIONAL: grupo do layout pedido eletronico
)
RETURNS int

AS

BEGIN

Declare @Date smalldatetime,
        @IdPolCom int,
        @pm_FlgSugPolComIdeal bit,
        @pm_FlgSugPolComMenDsc bit

Set @Date = cast(GetDate() as Date)

Select @pm_FlgSugPolComIdeal = IsNull(FlgSugPolComIdeal,0),
       @pm_FlgSugPolComMenDsc = IsNull(FlgSugPolComMenDsc,0)
From PARAM 
Where Cod_Estabe = @PCodEstabe

Set @IdPolCom = 0
Set @PCodOri = Ltrim(Rtrim(@PCodOri))

if @pm_FlgSugPolComIdeal = 1
  Set @IdPolCom = IsNull((Select top 1 Id_PolCom 
                          From dbo.FN_RetornaPoliticasProduto(@PCodOri,@PCodEstabe,@PCodCli,@PCodVdr,@PCodOpe,@PIdPolComCab, @PCodPrd, @Date, @PCodLayPde, @PCodGrpLay)
						  Where ((@PQtdPed = 0) or (@PQtdPed >= Qtd_Minimo))
                          Order by Per_Descon desc, Nivel, Ordem),0)
else
if @pm_FlgSugPolComMenDsc = 1
  Set @IdPolCom = IsNull((Select top 1 Id_PolCom 
                          From dbo.FN_RetornaPoliticasProduto(@PCodOri,@PCodEstabe,@PCodCli,@PCodVdr,@PCodOpe,@PIdPolComCab, @PCodPrd, @Date, @PCodLayPde, @PCodGrpLay)
						  Where ((@PQtdPed = 0) or (@PQtdPed >= Qtd_Minimo))
                          Order by Per_Descon, Nivel, Ordem),0)
else
  Set @IdPolCom = IsNull((Select top 1 Id_PolCom 
                          From dbo.FN_RetornaPoliticasProduto(@PCodOri,@PCodEstabe,@PCodCli,@PCodVdr,@PCodOpe,@PIdPolComCab, @PCodPrd, @Date, @PCodLayPde, @PCodGrpLay)
						  Where ((@PQtdPed = 0) or (@PQtdPed >= Qtd_Minimo))
                          Order by Dat_Cadastro desc, Nivel, Ordem),0)

-- Retorna o resultado da function
RETURN IsNull(@IdPolCom,0)

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_InfoDefaultPDVIT]
@PFlgPolCom bit,           -- indica se utiliza politica de comercialização
@PCodEstabe int,           -- estabelecimento
@PNumPdv int,              -- numero pedido
@PCodPrd int,              -- produto
@PQtdPed int,              -- qtd pedido
@PQtdBon int,              -- qtd bonificacao
@PIdPolComIte int output,  -- politica de comercializaçãodo item : passa também parametro
@PFlgBlqDscAutIte bit,     -- bloqueia desconto automatico (Layout PDE)  -- TBLPG.Flg_BlqDscAutIte
-------------------------------------------------------------------------------------------------------
@PFlgAchou bit output,
@PLocFis varchar(15) output,                  -- somente registra
@PCodFab int output,                          -- somente registra 
@PPrcFab numeric(18,8) output,                -- somente registra
@PPrcMaxCon numeric(18,8) output,             -- somente registra
@PPrcRefFpb numeric(18,8) output,             -- somente registra
@PPrcTab numeric(18,8) output,
@PPrcTabBru numeric(18,8) output,             -- somente registra

@PFatCnvImpFat smallint output,               -- somente registra
@PPrcUni numeric(18,8) output,

@PPrcCusMinComMarkup numeric(18,8) output,    -- usado somene na critica
@PPerDscPolCom numeric(7,4) output,
@PPerDscVisPolCom numeric(7,4) output,
@PPrcPolCom numeric(18,8) output,
@PQtdPrzPolCom int output,
@PFlgGerVrbIte bit output,           -- PDVIT.Flg_Verba: indica se gera verba p/ acumular, não gera e usa verba no pedido
@PFlgPolPrm bit output,
@PCodKitPrm int output,
@PCodPromoc int output,
@PFlgEmbDscPrc bit output,           -- PDVIT.Flg_PrcUniDsc: embute desconto no preço  NPOL (nao politica)  
@PQtdPrzMax int output,              -- PDVIT.Qtd_PrzMax
@PPerDscLin numeric(7,4) output,     -- PDVIT.Per_Desconto: desconto prazo "linear"
@PPerDscPrz numeric(7,4) output,     -- PDVIT.Per_Descon: desconto prazo "fabricante" prazo
@PPerDscVis numeric(7,4) output,     -- PDVIT.Per_DscVis: desconto prazo "fabricante" vista
@PPrcUniLiqPer numeric(18,8) output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Date smalldatetime

Set @Date = cast(GetDate() as Date)

BEGIN TRANSACTION

  Declare @WFlgBlqDscExt bit = 0,     -- Bloqueia desconto extra
          @WQtdPrzIte int = 0,

          @PFlgPromoc bit,        
          @PDesPromoc varchar(30),
          @PFlgBlqCtrQtdPromoc bit,
          @PQtdEstPromoc int,
          @PQtdMinPromoc int,
          @PDatEncPromoc smalldatetime,   
          @PDatVctLotPromoc smalldatetime,
          @PQtdPrzPromoc int,
          @PPerDscPromoc decimal(7,4),
          @PPerBonPromoc decimal(7,4),
          @PPrcPromoc decimal(18,8)

  Declare @WPerDscMax numeric(7,4),
          @WPerDscAut numeric(7,4),
          @WPrcUni numeric(18,8),
          @WPerDscPrzIte numeric(7,4),
          @WPerDscVisIte numeric(7,4),
          @WPerDscTabSug numeric(7,4),
          @WTipPrz varchar(1),
          @WPrcUniLiqPromoc numeric(18,8),
          @WPrcUniLiqPolCom numeric(18,8),
          @WPrcUniLiqPdv numeric(18,8),
          @WQtdMaxCfg int

  Declare @pr_PrcVenda numeric(18,8),
          @pr_PrcCustoMedio numeric(18,8),
          @pr_PrcCusMedCom numeric(18,8),
          @pr_PrcCusLiqEnt numeric(18,8),
          @pr_PrcUltEnt numeric(18,8),
          @pr_PerDscUltEnt numeric(7,4),
          @pr_FlgBlqDsc bit,
          @pr_CodCla varchar(7),
          @pr_PerBonAut numeric(7,4),
          @pr_PerDscAut numeric(7,4),
          @pr_PerDscAutOrc numeric(7,4),
          @pr_CodPromoc int,
          @pr_QtdDispon int,
          @pr_QtdPromocDispon int,

          @fb_PerDscMax numeric(7,4),

          @pv_DatPedido smalldatetime,
          @pv_TipPdv varchar(1),  
          @pv_CodOriPdv varchar(2),
          @pv_TipFat varchar(3),   
          @pv_CodCli int, 
          @pv_CodVdr int, 
          @pv_CodOpe int,
          @pv_IdPolCom int,

          @pv_TipRatBon varchar(1),
          @pv_FlgMarkupCusCom bit,
          @pv_CodTabPrc int,   
          @pv_QtdPrzPdv int,
          @pv_PerDscPrzPdv numeric(7,4),
          @pv_PerDscVisPdv numeric(7,4),
          @pv_TipGerVrb varchar(1),
          @pv_FlgMrkCusCom bit, 

          @op_TipPrc varchar(1),
          @op_FlgOrc bit = 0,
          @cl_CodUf varchar(2), 
          @cl_FlgConFin bit,   
          @cl_FlgBlqEmbDscItePrcUni bit,
          @cl_FlgBlqDscPrmExtVenVis bit,

          @pe_CodLayPde int,
          @pe_CodGrpPde int,

          --@pc_FlgBlqVerba bit,

          @pm_QtdDecPrcItePdv smallint,
          @pm_FlgTabPrcConFin bit,
          @pm_FlgEmbDscItePrcUni bit,
          @pm_FlgSugPrmPdv bit,
          @pm_FlgNaoSugDscItePdv bit,
          @pm_PerDscPrmExtVenVis numeric(7,4),
          @pm_FlgCtrDscIte bit,      
          @pm_PerMaxDscIte numeric(7,4)

  Set @PFlgAchou = 0
  Set @PLocFis = ''

  Set @PCodFab = 0
  Set @PQtdPrzMax = 0

  Set @PPrcFab = 0
  Set @PPrcMaxCon = 0
  Set @PPrcRefFpb = 0
  Set @PPrcTab = 0
  Set @PPrcTabBru = 0
  Set @PPrcUni = 0
  Set @PPrcUniLiqPer = 0
  Set @PPrcPolCom = 0
  Set @PPrcCusMinComMarkup = 0
  Set @PFatCnvImpFat = 1

  Set @PPerDscLin = 0
  Set @PPerDscPrz = 0
  Set @PPerDscVis = 0
  Set @PQtdPrzPolCom = 0
  Set @PPerDscPolCom = 0
  Set @PPerDscVisPolCom = 0

  Set @PCodKitPrm = 0
  Set @PCodPromoc = 0
  Set @PFlgGerVrbIte = 0
  Set @PFlgPolPrm = 0
  Set @PFlgPromoc = 0
  Set @PDesPromoc = 0
  Set @PFlgBlqCtrQtdPromoc = 0
  Set @PQtdEstPromoc = 0
  Set @PDatEncPromoc = 0
  Set @PDatVctLotPromoc = 0
  Set @PQtdMinPromoc = 0
  Set @PQtdPrzPromoc = 0
  Set @PPerDscPromoc = 0
  Set @PPerBonPromoc = 0
  Set @PPrcPromoc = 0
  Set @PFlgEmbDscPrc = 0

    -- Status1 = 'P'     -- Pendente
    -- Status2 = 'A','X' -- em aberto 

  if Exists(Select 1 From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @PNumPdv And ((Status2 = 'A') or (Status2 = 'X'))) and
     Exists(Select 1 From PRXES pr Inner Join PRODU p on pr.Cod_Produt = p.Codigo Where pr.Cod_Estabe = @PCodEstabe And pr.Cod_Produt = @PCodPrd)
    begin
      Select @PFlgAchou       = 1,
	         @PLocFis            = IsNull(d.Cod_LocFis,''),   
	         @pr_CodCla          = IsNull(p.Cod_Classif,''), 
			 @PCodFab            = IsNull(p.Cod_Fabricante,0),   
			 @PPrcFab            = IsNull(pr.Prc_Fabric,0),      
			 @PPrcMaxCon         = IsNull(pr.Prc_MaxCon,0),      
			 @PPrcRefFpb         = IsNull(p.Prc_RefFpb,0),       
			 @pr_PrcVenda        = IsNull(pr.Prc_Venda,0), 
			 @pr_FlgBlqDsc       = IsNull(pr.Flg_BlqDsc,0), 
			 @pr_PerBonAut       = IsNull(pr.Per_BonAut,0), 
			 @pr_PerDscAut       = IsNull(pr.Per_DscAut,0), 
			 @pr_PerDscAutOrc    = IsNull(pr.Per_DscAutOrc,0), 
             @pr_PrcCustoMedio   = IsNull(pr.Prc_CusMed,0),   
			 @pr_PrcCusMedCom    = IsNull(pr.Prc_CusMedCom,0), 
			 @pr_PrcCusLiqEnt    = IsNull(pr.Prc_CusLiqEnt,0), 
			 @pr_PrcUltEnt       = IsNull(pr.Prc_UltEnt,0), 
			 @pr_PerDscUltEnt    = IsNull(pr.Per_DscUltEnt,0),
             @pr_CodPromoc       = IsNull(pr.Cod_Promocao,0),
             @pr_QtdDispon       = dbo.FN_EstoqueDisponivelPrd(pr.Cod_Estabe,pr.Cod_Produt),
             @pr_QtdPromocDispon = IsNull(pr.Qtd_PrmDispon,0),
			 @fb_PerDscMax       = Case 
                                     When IsNull(fb.Per_DscMaxVis,0) > IsNull(fb.Per_DscMaxPrz,0) then IsNull(fb.Per_DscMaxVis,0)
                                     Else IsNull(fb.Per_DscMaxPrz,0) 
                                   End
        From PRXES pr 
             Inner Join PRODU p on pr.Cod_Produt = p.Codigo 
             Left Join FABRI fb on p.Cod_Fabricante = fb.Codigo
             Left Outer Join DPXPR d ON ((pr.Cod_Estabe = d.Cod_Estabe) and (pr.Cod_Produt = d.Cod_Produt) and 
                                          d.Cod_Dep = (Select Min(Cod_Dep) FROM DPXPR 
                                                       Where Cod_Estabe = @PCodEstabe
                                                       And Cod_Produt = pr.Cod_Produt)) 
        Where pr.Cod_Estabe = @PCodEstabe
        And pr.Cod_Produt = @PCodPrd


      -- parametros na memoria
      Select @pm_QtdDecPrcItePdv    = IsNull(QtdDecPrcItePdv,2),
             @pm_FlgTabPrcConFin    = IsNull(FlgTabPrcConFin,0),
             @pm_FlgEmbDscItePrcUni = IsNull(FlgEmbDscItePrcUni,0),
             @pm_FlgSugPrmPdv       = IsNull(FlgSugPrmPdv,0),
             @pm_FlgNaoSugDscItePdv = IsNull(FlgNaoSugDscItePdv,0),
             @pm_PerDscPrmExtVenVis = IsNull(PerDscPrmExtVenVis,0),
             @pm_FlgCtrDscIte       = IsNull(FlgCtrDscIte,0),
             @pm_PerMaxDscIte       = IsNull(PerMaxDscIte,0)
        From PARAM
        Where Cod_Estabe = @PCodEstabe

      -- coloca PDVCB na memoria
      Select @pv_DatPedido    = IsNull(cb.Dat_Pedido,@Date),
	         @pv_TipPdv       = IsNull(cb.Tip_Pedido,''),
             @pv_CodOriPdv    = IsNull(cb.Cod_OrigemPdv,''),
             @pv_TipFat       = IsNull(cb.Tip_Faturamento,''),
             @pv_CodCli       = IsNull(cb.Cod_Cliente,0),
			 @pv_IdPolCom     = IsNull(cb.Id_PolCom,0),

			 @pv_CodVdr       = IsNull(cb.Cod_Vendedor,0),
			 @pv_CodOpe       = IsNull(cb.Cod_VendTlmkt,0),

             @pv_TipRatBon    = IsNull(cb.Tip_RatBon,''),
             @pv_FlgMarkupCusCom = IsNull(cb.Flg_MarkupCusCom,0),
             @pv_CodTabPrc    = IsNull(cb.Cod_TabPrc,0),
--             @pv_QtdPrzPdv    = IsNull(cb.Qtd_Prz,0),
             @pv_QtdPrzPdv    = Cast(IsNull(cb.Qtd_PrzMed,0) as int),
             @pv_PerDscPrzPdv = IsNull(cb.Per_DscPrz,0),
             @pv_PerDscVisPdv = IsNull(cb.Per_DscVis,0),
             @pv_TipGerVrb    = IsNull(cb.Tip_GerVrb,'X'),
             @pv_FlgMrkCusCom = IsNull(cb.Flg_MarkupCusCom,0), 
             @op_TipPrc       = IsNull(op.Tip_Prc,''),
             @op_FlgOrc       = Case
                                  When IsNull(op.Cod_CfoNorInt,0) = 0 then 1
                                  Else 0
                                End,
             @cl_CodUf        = IsNull(cl.Cod_Estado,''),
             @cl_FlgConFin    = Case When (IsNull(cl.Tipo_Consumidor,'') = 'F') and (@pm_FlgTabPrcConFin = 1) then 1 Else 0 End,
             @cl_FlgBlqEmbDscItePrcUni = IsNull(en.Flg_BlqEmbDscItePrcUni,0),
             @cl_FlgBlqDscPrmExtVenVis = IsNull(Flg_BlqDscPrmExtVenVis,0),

             @pe_CodLayPde = IsNull(pe.Cod_Layout,0),
             @pe_CodGrpPde = IsNull(pe.Cod_GrpClp,0)

        From PDVCB cb
             Left Join TPOPE op on cb.Tip_Faturamento = op.Cod_Ope
             Left Join CLIEN cl on cb.Cod_Cliente = cl.Codigo
             Left Join ENXES en on cb.Cod_Estabe = en.Cod_Estabe and cl.Cgc_Cpf = en.Num_CgcCpf and cl.Codigo = en.Cod_Client
             Outer Apply (Select top 1 p.Cod_Layout, p.Cod_GrpClp 
                            From PDECB p 
                           Where p.Cod_Estabe = cb.Cod_Estabe
                             And p.Num_PedVen = cb.Numero
                           Order by p.Isn_Arquiv desc) pe
        Where cb.Cod_Estabe = @PCodEstabe
        And cb.NUmero = @PNumPdv


      -- guarda o tipo de prazo: (F)abricante, (L)inear
      Set @WTipPrz = Substring(@pv_CodOriPdv,2,1)            
      if Ltrim(Rtrim(@WTipPrz)) = '' Set @WTipPrz = 'L'      

      -- embute desconto no preço
      if (@pm_FlgEmbDscItePrcUni = 1) and (@cl_FlgBlqEmbDscItePrcUni = 0)  
        Set @PFlgEmbDscPrc = 1 

      Set @WFlgBlqDscExt = 0  --@cl_FlgBlqDscPrmExtVenVis
      Set @WPrcUniLiqPromoc = 0
      Set @WPrcUniLiqPolCom = 0

      -- pr.bruto
      Set @PPrcTabBru = @pr_PrcVenda    

      -- desconto automatico do produto (p/ preco do cadastro)
      Set @WPerDscAut = 0
      if @pr_PerBonAut = 0
        if Upper(LTrim(RTrim(@pv_TipFat))) = 'ORC'
          Set @WPerDscAut = @pr_PerDscAutOrc
        else
          Set @WPerDscAut = @pr_PerDscAut
      if IsNull(@PFlgBlqDscAutIte,0) = 1   -- PARAM ????
        Set @WPerDscAut = 0


      -- inicializa
      --Set @pc_FlgBlqVerba  = 0
      Set @PPrcCusMinComMarkup = 0

-------------------------------------------------------------------------------------------------------------------------
      if @PFlgPolCom = 1
        begin
          if @PIdPolComIte = 0 
             Set @PIdPolComIte = dbo.FN_SugerePoliticaProduto(Substring(@pv_CodOriPdv,1,1),
                                                              @PCodEstabe,
                                                              @pv_CodCli, @pv_CodVdr, @pv_CodOpe,
                                                              @pv_IdPolCom, @PCodPrd, @PQtdPed,
                                                              @pe_CodLayPde, @pe_CodGrpPde)

          -- nem sempre a politica do cabeçalho atende ao item
          if (@PIdPolComIte = 0) and
             (dbo.FN_PoliticaProdutoValida(@PCodEstabe, Substring(@pv_CodOriPdv,1,1), @pv_IdPolCom, @PCodPrd) = 1)		   
		    Set @PIdPolComIte = @pv_IdPolCom 

          --Set @pv_CodTabPrc = IsNull((Select Cod_TabPrc From POCOM Where Id_PolCom = @PIdPolComIte),0)

          if Exists(Select 1 From POCOM Where Id_PolCom = @PIdPolComIte)
            begin
             -- Select @pc_FlgBlqVerba = Case 
             --                            When (IsNull(pc.Flg_AcuVrbPos,0) = 0) and (IsNull(pc.Flg_AcuVrbNeg,0) = 0) then 1 
             --                            Else 0 
             --                          End,
              Select @PFlgGerVrbIte = Case 
                                       When (IsNull(pc.Flg_NegDsc,0) = 1) and (IsNull(pc.Flg_GerVrbPdv,0) = 0) and    -- negocia desconto e não gera e usa verba exclusivamente no pedido
                                            ((IsNull(pc.Flg_AcuVrbPos,0) = 1) or (IsNull(pc.Flg_AcuVrbNeg,0) = 1)) then 1 
                                       Else 0 
                                     End,
                     --@pc_FlgBlqVerba  = IsNull(pc.Flg_BlqVerba,0),
                     @PFlgPolPrm = IsNull(pc.Flg_BlqCli,0), 
                     @PPrcCusMinComMarkup = Case
                                              When (@pv_TipGerVrb <> 'P') and 
                                                   ( (IsNull(pc.Flg_MarkupCusCom,0) = 1) or (@pv_TipRatBon <> '') ) then dbo.FN_PrcMinCom(@PCodEstabe,@PCodPrd)
                                              Else 0
                                            End
                From POCOM pc 
               Where pc.Id_PolCom = @PIdPolComIte
       
            end  -- if Exists(Select 1 From POCOM Where Id_PolCom = @PIdPolComIte)
       
        end  -- if @PFlgPolCom = 1
-------------------------------------------------------------------------------------------------------------------------

      -- Pr. Tabela
      Set @PPrcTab = dbo.FN_PrecoTabelaProduto(@pv_CodCli, @PCodEstabe, @PCodPrd, @PIdPolComIte, @pv_CodTabPrc, @op_FlgOrc, @PFlgBlqDscAutIte)

      Set @PFatCnvImpFat = 1    
      Set @WPerDscMax = 0   -- desconto maximo permitido (para calculo Pr.Permitido) 
      Set @WPerDscTabSug = 0                                        

      Set @WPrcUni = @PPrcTab   -- aquix ?????  o preço de tabela pode estar com desconto embutido (TPXPR)
      Set @WPrcUniLiqPdv = 0          

      -- preço unitario
      if @cl_FlgConFin = 0 
        begin
          --if @PFlgPrcDif = 1
          --Set @WPrcUni = @PPrcTab
          --Set @WPrcUni = ProduCds.FieldByName('H_PrcVen').AsFloat
          --else             
          if @op_TipPrc = 'V' 
            begin
              Set @WPrcUni = @PPrcTab
            end
          else
          if @op_TipPrc = 'M'
            begin
              if @pr_PrcCusMedCom > 0 
                Set @WPrcUni = @pr_PrcCusMedCom  -- custo medio comercial
              else
                Set @WPrcUni = @pr_PrcCustoMedio
              Set @WPerDscMax = 0
            end
          else
          if @op_TipPrc = 'C'
            begin
              Set @WPrcUni = @pr_PrcCusLiqEnt
              Set @WPerDscMax = 0
             end
          else
          if @op_TipPrc = 'E'
            begin
              Set @WPrcUni = @pr_PrcUltEnt*(1-@pr_PerDscUltEnt/100)
              Set @WPerDscMax = 0
             end
        end
      else
        begin
          Set @WPrcUni = @PPrcTab
          Set @WPerDscMax = 0
        end
   
-------------------------------------------------------------------------------------------------------------------------
      if @PFlgPolCom = 0
        begin
          Set @PIdPolComIte = 0  

          -- promocao
          Exec PR_ProdutoEmPromocao @PCodEstabe, @pr_CodPromoc, @PCodPrd, @cl_CodUf,
                                    @PFlgPromoc output, @PDesPromoc output, @PDatEncPromoc output, @PDatVctLotPromoc output, @PQtdMinPromoc output,
                                    @PQtdPrzPromoc output, @PPerDscPromoc output, @PPerBonPromoc output, @PPrcPromoc output, @PFlgBlqCtrQtdPromoc output
          if @PFlgPromoc = 1
            begin
              if @PFlgBlqCtrQtdPromoc = 1
                Set @PQtdEstPromoc = @pr_QtdDispon
              else
                Set @PQtdEstPromoc = @pr_QtdPromocDispon
            end

          Set @WQtdPrzIte = @pv_QtdPrzPdv  

          if @WTipPrz = 'L'     -- prazo linear
            begin
              -- politica de comercializacao = 0
              Set @PQtdPrzMax = 0     --@pv_QtdPrzPdv ????
              Set @PPerDscPrz = 0
              Set @PPerDscVis = 0
        
              if @op_TipPrc = 'V' 
                begin
                  if @fb_PerDscMax > @WPerDscMax
                    Set @WPerDscMax = @fb_PerDscMax
                  if @pm_FlgCtrDscIte = 0
                    if @pm_PerMaxDscIte = 0 
                      Set @WPerDscMax = 99
                   else
                      if @pm_PerMaxDscIte > @WPerDscMax
                        Set @WPerDscMax = @pm_PerMaxDscIte
                 
                  -- sugere promocao automatica
                  if (@pm_FlgSugPrmPdv = 1) and
                     (@PFlgPromoc = 1) and (@op_TipPrc = 'V') and (@PQtdEstPromoc > 0) and
                     ((@pr_QtdPromocDispon > 0) or (@PFlgBlqCtrQtdPromoc = 1)) and
                     (@pr_FlgBlqDsc = 0) 
                    begin
                      if @PPerDscPromoc > 0
                        Set @PPerDscLin = @PPerDscPromoc
                      else
                      if @PPrcPromoc > 0 
                        Set @WPrcUni = @PPrcPromoc
                    end
                  else
                    begin
                      Set @WPerDscTabSug = 0

                      if (@pv_CodTabPrc > 0) and            
                         Exists(Select 1 From TPXPR it 
                                              Inner Join TBPRC cb on it.Cod_Estabe = cb.Cod_Estabe and it.Cod_TabPrc = cb.Cod_TabPrc 
                                 Where it.Cod_TabPrc = @pv_CodTabPrc
                                   And it.Cod_Produt = @PCodPrd
                                   And ((cb.Cod_Estabe = @PCodEstabe) or (cb.Flg_AllEstabe = 1)))
                        begin
                          Select @WPerDscTabSug = Case 
                                                    When IsNull(cb.Flg_IniDsc,0) = 1 then IsNull(it.Per_DscMax,0)
                                                    Else 0
                                                  End
                            From TPXPR it 
                                 Inner Join TBPRC cb on it.Cod_Estabe = cb.Cod_Estabe and it.Cod_TabPrc = cb.Cod_TabPrc 
                           Where it.Cod_TabPrc = @pv_CodTabPrc
                             And it.Cod_Produt = @PCodPrd
                             And ((cb.Cod_Estabe = @PCodEstabe) or (cb.Flg_AllEstabe = 1))
                        end
                      
                       -- sugere desconto da tabela de preços
                      if (@WPerDscTabSug > 0) and (@pr_FlgBlqDsc = 0) 
                        Set @PPerDscLin = @WPerDscTabSug
                    end
                 
                end  -- if @op_TipPrc = 'V'
        
              -- calcula @WPrcUniLiqPdv
              Set @WPrcUni = Round(@WPrcUni,@pm_QtdDecPrcItePdv)
              Set @WPrcUniLiqPdv = @WPrcUni*(1-@PPerDscLin/100)
        
            end -- if @WTipPrz = 'L'
          else
            begin  -- if @WTipPrz = 'F': prazo fabricante - quando alterar aqui ver rotina de reprocessamento de comercializacao de itens
              Set @PPerDscLin = 0

              if @op_TipPrc = 'V' 
                begin
                  -- cond. comercializacao padrao
                  Exec PR_PdvitConComDef @PCodEstabe, @PCodPrd, @pv_CodCli, @pv_QtdPrzPdv, @pv_PerDscPrzPdv, @pv_PerDscVisPdv,
                                          @WQtdPrzIte output, @WPerDscPrzIte output, @WPerDscVisIte output
                
                  Set @PQtdPrzMax = @WQtdPrzIte
                  Set @PPerDscPrz = @WPerDscPrzIte
                  Set @PPerDscVis = @WPerDscVisIte
                
                  -- sugere promocao automatica
                  if (@pm_FlgSugPrmPdv = 1) and
                     (@PFlgPromoc = 1) and (@op_TipPrc = 'V') and
                     ((@pr_QtdPromocDispon > 0) or (@PFlgBlqCtrQtdPromoc = 1)) and
                     (@pr_FlgBlqDsc = 0) 
                    begin
                      if @PQtdPrzPromoc > 0 
                        Set @PQtdPrzMax = @PQtdPrzPromoc
                      if @PPerDscPromoc > 0
                        begin
                          Set @PPerDscPrz = @PPerDscPromoc
                          Set @PPerDscVis = @PPerDscPromoc
                          -- desconto adicional em venda a vista se configurado nas opcoes do sistema
                          -- se existir uma condicao pre-existente na venda a vista
                          if (@pm_PerDscPrmExtVenVis > 0) and
                             (@WPerDscVisIte > 0) and (@WFlgBlqDscExt = 0) 
                            -- (D1+D2) - (D1*D2)/100
                          Set @PPerDscVis = Round((@PPerDscPromoc+@pm_PerDscPrmExtVenVis) - (@PPerDscPromoc*@pm_PerDscPrmExtVenVis)/100,2)
                        end
                      else
                      if @PPrcPromoc > 0 
                        begin
                          Set @WPrcUni = @PPrcPromoc
                
                          Set @PPerDscPrz = 0
                          Set @PPerDscVis = 0
                          -- desconto adicional em venda a vista se configurado nas opcoes do sistema
                          -- se existir uma condicao pre-existente na venda a vista
                          if (@pm_PerDscPrmExtVenVis > 0) and
                             (@WPerDscVisIte > 0) and (@WFlgBlqDscExt = 0) 
                            Set @PPerDscVis = Round(@pm_PerDscPrmExtVenVis,2)
                        end
                
                    end  -- if (@pm_FlgSugPrmPdv = 1) and

                end  -- if @op_TipPrc = 'V'

              -- calcula @WPrcUniLiqPdv
              Set @WPrcUni = Round(@WPrcUni,@pm_QtdDecPrcItePdv)
              Set @WPrcUniLiqPdv = @WPrcUni*(1-@PPerDscPrz/100)

            end  -- if @WTipPrz = 'F'     -- prazo fabricante

          -- calcula preco progressivo
          --CalculaPrcUnitarioPdvit(PIteDts,PPsqDts,@pv_TipFat,@op_TipPrc,PEstCli,@pv_CodTabPrc,
          --                         @WQtdPrzIte, @WQtdPrzIte,PdvcbCds.FieldByName('Flg_TabProgres').AsBoolean,@cl_FlgConFin,PFlgPrcDif,true);

         Set @PPrcUni = @WPrcUni

        end  -- if @PFlgPolCom = 0
------------------------------------------------------------------------------------------------------------------------------------------------

      if @PFlgPolCom = 1
        begin
          -- promocao
          Set @PCodKitPrm = dbo.FN_IdKitPromocao(@PIdPolComIte)

          -- calcula preco progressivo
          --CalculaPrcUnitarioPdvit(PPsqPrd,PPsqDts,PTipFat,PTipPrc,PEstCli,PCodTabPrc,
          --                        PQtdPrzMax,PQtdPrzMax,PdvcbCds.FieldByName('Flg_TabProgres').AsBoolean,false,false,true);

          -- condicoes da politica: define preço unitario/desconto conforme politica de comercializacao
          -- na digitacao do pedido o preço já é sugerido e pode ser alterado
          if @PQtdPed > 0
            Exec PR_PrcPrdPolitica @pv_CodCli, @PCodEstabe, @PCodPrd, @PIdPolComIte, @PQtdPed, @WPrcUni, @pv_DatPedido,
                                   @PPrcUni output, @PQtdPrzMax output, @PPerDscPrz output, @PPerDscVis output, @WQtdMaxCfg output

          -- calcula @WPrcUniLiqPdv
          if @PPrcUni = 0
            Set @PPrcUni = @WPrcUni
          Set @PPrcUni = Round(@PPrcUni,@pm_QtdDecPrcItePdv)
          Set @WPrcUniLiqPdv = @PPrcUni*(1-@PPerDscPrz/100)

--          if IsNull(@pc_FlgBlqVerba,0) = 0
--            Set @PFlgVerba = 1
--          else
--            Set @PFlgVerba = 0

          Set @PQtdPrzPolCom = IsNull(@PQtdPrzMax,0)
--          Set @PPrcPolCom = IsNull(@WPrcUni,0)  alterado em 23/07/2020
          Set @PPrcPolCom = IsNull(@PPrcUni,0)
          Set @PPerDscPolCom = IsNull(@PPerDscPrz,0)
          Set @PPerDscVisPolCom = IsNull(@PPerDscVis,0)
          if @pv_TipPdv = 'C'
            Set @PPerDscLin = IsNull(@PPerDscPrz,0)

          if @PPerDscVisPolCom < @PPerDscPolCom
            Set @PPerDscVisPolCom = @PPerDscPolCom

        end  -- if @PFlgPolCom = 1

      -- produto bloqueado para descontos
      if (@pr_FlgBlqDsc = 1) or (@pm_FlgNaoSugDscItePdv = 1) 
        begin
          Set @PPerDscLin    = 0     
          Set @PPerDscPrz    = 0     
          Set @PPerDscVis    = 0     

          --if @pv_FlgMrkCusCom = 0
          Set @PFlgGerVrbIte  = 0

          Set @PPrcPolCom    = 0
          Set @PPerDscPolCom = 0
          Set @PPerDscVisPolCom = 0
        end

      -- desconto a vista nao pode ser menor que desc. a prazo
      if @PPerDscVis < @PPerDscPrz      
        Set @PPerDscVis = @PPerDscPrz

      -- desconto maximo
      if @WPerDscTabSug > @WPerDscMax
        Set @WPerDscMax = @WPerDscTabSug

	  if @PPerDscLin > @WPerDscMax
        Set @WPerDscMax = @PPerDscLin
      if @PPerDscVis > @WPerDscMax
        Set @WPerDscMax = @PPerDscVis

      if @PPerDscPromoc > @WPerDscMax
        Set @WPerDscMax = @PPerDscPromoc

      -- preco minimo permitido ------
	  if (@PPrcUni > 0) and (@PPrcUni < @WPrcUni)
        Set @WPrcUni = @PPrcUni

      Set @PPrcUniLiqPer = @WPrcUni*(1-@WPerDscMax/100)

      -- calcula preco minimo politica liquido
      Set @WPrcUniLiqPolCom = @PPrcPolCom*(1-@PPerDscVisPolCom/100)
      if (@WPrcUniLiqPolCom > 0) and (@WPrcUniLiqPolCom < @PPrcUniLiqPer)
        Set @PPrcUniLiqPer = @WPrcUniLiqPolCom

      -- calcula preco minimo promocional liquido
      Set @WPrcUniLiqPromoc = @PPrcPromoc*(1-@PPerDscPromoc/100)
      if (@WPrcUniLiqPromoc > 0) and (@WPrcUniLiqPromoc < @PPrcUniLiqPer)
        Set @PPrcUniLiqPer = @WPrcUniLiqPromoc

      -- verifica se venda foi da promocao
      Set @PCodPromoc = 0
      if @PFlgPromoc = 1
        Set @PCodPromoc = @pr_CodPromoc  
/*
      if @PFlgPromoc = 1
        begin
          if @PQtdBon > 0 
            Set @PCodPromoc = @pr_CodPromoc  
          else
          if @WPrcUniLiqPromoc > 0 
            if (Round(@WPrcUniLiqPdv,4) >= Round(@WPrcUniLiqPromoc,4)) and
               (Round(@WPrcUniLiqPdv,4) < Round(@PPrcTab,4)) and
               (Round(@WPrcUniLiqPdv,4) <= Round(@PPrcUniLiqPer,4)) 
              Set @PCodPromoc = @pr_CodPromoc
        end
*/

    end   -- if @PCodPrd > 0

COMMIT TRANSACTION
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_IncluiPDVCB]
@PTipPedido char(1),    -- 'P'-Pedido, 'C'-Cotacao
@PCodEstabe int,
@PNumPdv int = NULL output,    -- se = 0 : cria novo pedido
@PCodOri varchar(1),    -- A-Ativo, P-Receptivo, M-Móvel, T-Eletronico/EDI, W-Internet/WEB, H-Hospitalar, D-por Desdobramento, V-por Vales
@PCodCli int,
@PFlgUsaWms bit,        -- PDVCB.Flg_WMS
@PTipOpe varchar(3),
@PCodVdr int,
@PCodOpe int,
@PCodDig int,
@PIdPolCom int,
@PCodPrz int,
@PCodLayPde int,
@PFlgBlqWms bit,        -- nunca usa WMS tem prioridade sobre @PFlgUsaWms
@PFlgBlqPol bit,        -- nunca usa politica
@PMsgErr varchar(8000) output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now  = GetDate()
Set @Date = cast(GetDate() as Date)

Set @PCodOri = Ltrim(Rtrim(@PCodOri))
Set @PTipOpe = Ltrim(Rtrim(@PTipOpe))

BEGIN

Set @PMsgErr = ''

if @PNumPdv is null
  Set @PNumPdv = 0

Declare @UsuInfarma varchar(15)

Declare @WCodAgeCob int = 0,
        @WMsg varchar(1000),
        @WSta smallint,
        @WStaLic varchar(1),
        @WCodMtv varchar(3),
		@WTipPrz varchar(1),
        @WTipSaiPdv varchar(1),
        @WTipGerVrb varchar(1),
        @WFlgMarkupCusCom bit,
        @WDesLayPde varchar(25),

        @pv_CodTipPed varchar(3),
		@es_CodRegTri int = 0,

		@pm_FlgUsaPolComPdv bit = 0,
		@pm_FlgOrcAgeCobCar bit = 0,
		@pm_FlgGerComOpeAtv bit = 0,
		@pm_CodOpeSemCom int = 0,
		@pm_CodOpePdvCon int = 0,
		@pm_CodAgeCobCar int = 0,
		@pm_FlgPrzLinConFin bit = 0

-- PARAM
Select @pm_FlgUsaPolComPdv = IsNull(FlgUsaPolComPdv,0),
       @pm_FlgOrcAgeCobCar = IsNull(FlgOrcAgeCobCar,0),
       @pm_FlgGerComOpeAtv = IsNull(FlgGerComOpeAtv,0),
       @pm_CodOpeSemCom = IsNull(CodOpeSemCom,0),
	   @pm_CodOpePdvCon = IsNull(CodOpePdvCon,0),
       @pm_CodAgeCobCar = IsNull(CodAgeCobCar,0),
	   @pm_FlgPrzLinConFin = IsNull(FlgPrzLinConFin,0) 
From PARAM 
Where Cod_Estabe = @PCodEstabe

-- se pedido existir ajusta parametros 
Set @WCodAgeCob = 0

if Exists(Select Numero From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv)
  begin
    Set @PFlgUsaWms = (Select IsNull(Flg_WMS,0) From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv)
    Set @WCodAgeCob = (Select IsNull(Cod_Agente,0) From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv)

    if @PCodOri = ''
      Set @PCodOri = (Select Substring(Cod_OrigemPdv,1,1) From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv)
    if @PTipOpe = ''
      Set @PTipOpe = (Select Tip_Faturamento From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv)
    if @PCodVdr = 0
      Set @PCodVdr = (Select IsNull(Cod_Vendedor,0) From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv)
    if @PCodOpe = 0
      Set @PCodOpe = (Select IsNull(Cod_VendTlmkt,0) From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv)
    if @PCodDig = 0
      Set @PCodDig = (Select IsNull(Cod_Digitador,0) From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv)
    if @PIdPolCom = 0
      Set @PIdPolCom = (Select IsNull(Id_PolCom,0) From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv)
    if @PCodPrz = 0
      Set @PCodPrz = (Select IsNull(Cod_Prz,0) From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv)
  end

if @PTipPedido = 'C'
  Set @pv_CodTipPed = 'COT'
else
  Set @pv_CodTipPed = 'PDV'

-- ajusta flags
if @PFlgBlqWms = 1         -- nunca usa WMS
  Set @PFlgUsaWms = 0
if @PFlgBlqPol = 1         -- nunca usa politica
  begin
    Set @pm_FlgUsaPolComPdv = 0
    Set @PIdPolCom = 0
  end

if @PCodOri = '' Set @PCodOri = 'A'   -- ???????
if @PTipOpe = '' Set @PTipOpe = 'FAT'

-----------------------------------------------------------------------------------------------------------------------------
if not Exists(Select Codigo From CLIEN Where Codigo = @PCodCli)
  begin
    if DATALENGTH(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + CHAR(13)
    Set @PMsgErr = 'Cliente inválido ('+cast(@PCodCli as varchar)+')'
  end

if not Exists(Select es.Num_CgcCpf From ENXES es Inner Join CLIEN cl on es.Cod_Estabe = @PCodEstabe and es.Num_CgcCpf = cl.Cgc_Cpf and es.Cod_Client = cl.Codigo Where cl.Codigo = @PCodCli)
  begin
    if DATALENGTH(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + CHAR(13)
    Set @PMsgErr = 'Configuração do Cliente no Estabelecimento inválido'
  end

if not Exists(Select Cod_Ope From TPOPE Where Cod_Ope = @PTipOpe and Tip_EntSai = 'S')
  begin
    if DATALENGTH(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + CHAR(13)
    Set @PMsgErr = 'Tipo de Operação inválido ('+@PTipOpe+')'
  end

-----------------------------------------------------------------------------------------------------------------------------
  
Select @PCodVdr = Case
                    When (@PCodVdr > 0) and exists(select 1 from VENDE where Codigo = @PCodVdr and Cod_TipVenBas <> 'TLM') then @PCodVdr
                    Else IsNull(es.Cod_Vendedor,0) 
                  End,
       @PCodOpe = Case
                    When @PCodOpe > 0 then @PCodOpe
                    When (@pm_FlgGerComOpeAtv = 1) and (IsNull(es.Cod_Operador,0) > 0) then IsNull(es.Cod_Operador,0)
                    When (@pm_FlgGerComOpeAtv = 1) and (@pm_CodOpeSemCom > 0) then @pm_CodOpeSemCom
                    When @pm_CodOpePdvCon > 0 then @pm_CodOpePdvCon
                    When @PCodDig > 0 then @PCodDig
                    Else 0
                  End,
       @PCodDig = Case
                    When @PCodDig > 0 then @PCodDig
                    When @pm_CodOpePdvCon > 0 then @pm_CodOpePdvCon
                    Else 0
                  End,
       @es_CodRegTri = IsNull(es.Cod_RegTri,0)
From CLIEN cl
     Left Join ENXES es on es.Cod_Estabe = @PCodEstabe and es.Num_CgcCpf = cl.Cgc_Cpf and es.Cod_Client = cl.Codigo
     Left Join RGTRI rg on es.Cod_RegTri = rg.Cod_RegTri
Where cl.Codigo = @PCodCli 
And es.Cod_Estabe = @PCodEstabe

-----------------------------------------------------------------------------------------------------------------------------------
if not Exists(Select Codigo
              From VENDE 
			  Where Codigo = @PCodVdr
              And Cod_TipVenBas <> 'TLM')
  begin
    if DATALENGTH(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + CHAR(13)
    Set @PMsgErr = 'Vendedor inválido ('+cast(@PCodVdr as varchar)+')'
  end

if not Exists(Select Codigo
              From VENDE
			  Where Codigo = @PCodOpe 
			  And Cod_TipVenBas = 'TLM')
  begin
    if DATALENGTH(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + CHAR(13)
    Set @PMsgErr = 'Operador inválido ('+cast(@PCodOpe as varchar)+')'
  end

if @es_CodRegTri = 0
  begin
    if DATALENGTH(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + CHAR(13)
    Set @PMsgErr = 'Região Tributária inválida ('+cast(@es_CodRegTri as varchar)+')'
  end

if (@PCodDig > 0) and not Exists(Select Codigo From VENDE Where Codigo = @PCodDig And Cod_TipVenBas = 'TLM')
  begin
    Set @PCodDig = @PCodOpe
  end

-----------------------------------------------------------------------------------------------------------------------------------

Exec PR_AnalisaCreditoCliente @pv_CodTipPed, @PCodEstabe, @PCodCli, @PNumPdv, 
                              @WMsg output, @WSta output, @WStaLic output, @WCodMtv output
/*
      if WSta = 3 then raise Exception.Create(PChar('Venda bloqueada: '+WMsg1[0]));
*/

if @WCodAgeCob = 0
  Set @WCodAgeCob = Case
                     When (Exists (Select Cod_AgeCob From TPOPE Where Cod_Ope = @PTipOpe and Tip_EntSai = 'S' And IsNull(Cod_AgeCob,0) > 0)) then
                       (Select Cod_AgeCob From TPOPE Where Cod_Ope = @PTipOpe)
		             When (Exists (Select Cod_CfoNorInt From TPOPE Where Cod_Ope = @PTipOpe and Tip_EntSai = 'S' And IsNull(Cod_CfoNorInt,0) = 0)) and (@pm_FlgOrcAgeCobCar = 1) then 
				       @pm_CodAgeCobCar
                     Else 
				       (Select es.Cod_AgeCob From ENXES es Inner Join CLIEN cl on es.Cod_Estabe = @PCodEstabe and es.Num_CgcCpf = cl.Cgc_Cpf and es.Cod_Client = cl.Codigo
				        Where cl.Codigo = @PCodCli)
                     End

-- politica de comercialização
Set @WTipPrz = ''
if (@PIdPolCom > 0) or ((@pm_FlgUsaPolComPdv = 1) and (@PCodOri <> 'T'))  -- exceto pedido eletronico
  begin
    if @PIdPolCom = 0
      Set @PIdPolCom = dbo.FN_SugereIdPolComCli (@PCodOri, @WTipPrz, @PCodEstabe, @PCodCli, @PCodVdr, @PCodOpe, @PCodPrz)  -- aqui passava @PCodPrz = 0
    if @PIdPolCom = 0
      Set @PIdPolCom = dbo.FN_SugereIdPolComCli (@PCodOri, @WTipPrz, @PCodEstabe, @PCodCli, @PCodVdr, @PCodOpe, 0)
  end 

-- aqui, qdo for o caso sugere o prazo
if @PCodPrz > 0 
  if @pm_FlgUsaPolComPdv = 1
    begin
      if not Exists(Select Cod_TabPrz From PCXPZ Where Id_PolCom = @PIdPolCom And Cod_TabPrz = @PCodPrz)
        Set @PCodPrz = 0
    end
  else
    begin
      if not Exists(Select Cod_Prz From PRZCB Where Cod_Prz = @PCodPrz And Flg_ParOk = 1)
        Set @PCodPrz = 0
    end

----------------------------------------------------------------------------------------------------------------------------------------
BEGIN TRANSACTION
  if (@PMsgErr <> '') and 
     ((@PNumPdv > 0) and not Exists(Select Numero From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv))
    Set @PNumPdv = 0
  else
  -- cria pedido
  if (@PMsgErr = '') and 
     ((@PNumPdv = 0) or not Exists(Select Numero From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv))
    begin
      if @PNumPdv = 0
        begin
          EXEC PR_ProxNumero 'Pedido_Venda', @PNumPdv output
        end
  
      -- Status1 = 'P'     -- Pendente
      -- Status2 = 'A'     -- em aberto
      -- Tip_Pedido = 'P'  -- P=Pedido C=Cotacao
      Set @UsuInfarma = dbo.FN_UsuarioInfarma()
      Set @WDesLayPde = IsNull((Select Des_Layout From TBCLP Where Cod_Layout = @PCodLayPde),'')
      Set @WTipSaiPdv = dbo.FN_TipSaiPdv(@PTipOpe)
      Set @WTipGerVrb = dbo.FN_TipGerVrbPdv(@PIdPolCom)
      Set @WFlgMarkupCusCom =  dbo.FN_FlgMarkupPDVCB(@PIdPolCom)
  
      Insert Into PDVCB (Cod_Estabe, Numero, Cod_Cliente, Flg_WMS, Status1, Status2, Tip_Pedido, Tip_SaiPdv,
  	                   Tip_Faturamento, Cod_Vendedor, Cod_VendTlmkt, Cod_Digitador, Cod_OrigemPdv,
  	                   Cod_RegTri, Cod_Agente, Id_PolCom, Cod_Prz, Cod_LayoutPde, Des_LayoutPde,
                         Flg_Credito, Cod_BlqLic, Cod_MtvRej, Tip_GerVrb, Flg_MarkupCusCom,
                         Dat_Pedido, Hor_Entrada, Usuario, Transacao)
  
                 Values (@PCodEstabe, @PNumPdv, @PCodCli, @PFlgUsaWms, 'P', 'A', @PTipPedido, @WTipSaiPdv, 
                         @PTipOpe, @PCodVdr, @PCodOpe, @PCodDig, @PCodOri,
  				       @es_CodRegTri, @WCodAgeCob, @PIdPolCom, @PCodPrz, @PCodLayPde, @WDesLayPde,
                         @WSta, @WStaLic, @WCodMtv, @WTipGerVrb, @WFlgMarkupCusCom,
                         @Date, @Now, @UsuInfarma, @Now)
  
      if (@@error <> 0)
        begin
          if @@trancount > 0
  	      Rollback Transaction
  		Return
        end
    end  -- if (@PNumPdv = 0) or
  
  -- para pedidos Pendentes/Abertos
  if Exists(Select Numero From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv)
    begin
      Exec PR_InfoDefaultPDVCB @PCodEstabe, @PNumPdv
    end

  if @@trancount > 0
    COMMIT TRANSACTION

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraPdvRemConsig]
@PCodEstabe int, 
@PIdConsig int, 
@PNumSequen int,
@PTipOpe varchar(3),
@PNumPdv int output,
@PMsgErr varchar(8000) output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now  smalldatetime = GetDate(),
        @Date smalldatetime = cast(GetDate() as Date)

Set @PNumPdv = 0
Set @PMsgErr = ''

if not Exists(Select 1 
                From CNGCB 
               Where Cod_Estabe = @PCodEstabe And Id_Consig = @PIdConsig And Sta_Consig = 'P') 
  Set @PMsgErr = 'Contrato de Consignação não está "pendente"'
else
if not Exists(Select 1 
                From CNGCB cb
                     Inner Join CLIEN cl on cb.Cod_TipCng = 'C' and cb.Cod_Entida = cl.Codigo 
               Where cb.Cod_Estabe = @PCodEstabe And cb.Id_Consig = @PIdConsig)
  Set @PMsgErr = 'Clinte inválido'
else
if not Exists(Select 1 
                From CNGRC 
               Where Cod_Estabe = @PCodEstabe And Id_Consig = @PIdConsig And Num_Sequen = @PNumSequen And Sta_CngPed = '1') 
  Set @PMsgErr = 'Não existe pedido a gerar'
else
if not Exists(Select 1 
                From CNGRI it 
               Where it.Cod_Estabe = @PCodEstabe And it.Id_Consig = @PIdConsig and it.Num_Sequen = @PNumSequen
                 And it.Qtd_Pedido > 0)
  Set @PMsgErr = 'Não existe itens a gerar'
else
if not Exists(Select 1 
                From CNGRI it 
                     Inner Join PRXES pr on it.Cod_Estabe = pr.Cod_Estabe and it.Cod_Produt = pr.Cod_Produt 
               Where it.Cod_Estabe = @PCodEstabe And it.Id_Consig = @PIdConsig and it.Num_Sequen = @PNumSequen)
  Set @PMsgErr = 'Não existe itens a gerar'
else
if Exists(Select 1 
            From PDVCB 
           Where Cod_Estabe = @PCodEstabe and Id_Consig = @PIdConsig and Num_SequenciaCtr = @PNumSequen)
  Select @PMsgErr = 'Pedido ('+cast(Numero as varchar)+') já havia sido gerado'
    From PDVCB 
   Where Cod_Estabe = @PCodEstabe and Id_Consig = @PIdConsig and Num_SequenciaCtr = @PNumSequen
else
if not Exists(Select 1 
                From TPOPE 
               Where Tip_EntSai = 'S' and Cod_CfoNorInt = 5917 and Cod_CfoNorExt = 6917
                 And Cod_Ope = @PTipOpe And Tip_Ope = 'O')
  Set @PMsgErr = 'Tipo de operação (O/5917/6917) inválido para Remessa em Consignação'
else
  begin

    BEGIN TRANSACTION

    Declare @ct_CodCli int,
            @ct_IdPolCom int, 
            @ct_CodVended int,
            @ct_CodOperad int,
            @ct_CodDigita int,
--            @ct_PerComVnd numeric(8,4),

            @pm_FlgUsaPolComPdv bit,
            @pm_FlgAltUnvItePdv bit, 
            @pm_FlgRegDscCliItePdv bit,

            @WFlgUsaWms bit,
            @WFlgBlqWms bit, 
            @WFlgBlqPol bit,
            @WCodTabPrz int, 
            @WCodLayout int,
            @WFlgBlqDscAutIte bit,
            @WFlgCriVrb bit,
            @WFlgBlqQtdPar bit, 

            @WFlgSnhEsp bit,          
            @WFlgNaoCriConCom bit,    
            @WFlgBlqCriPrcVen bit,
            @WNomUsuSnhEsp varchar(35)

    Select @pm_FlgAltUnvItePdv = IsNull(FlgAltUnvItePdv,0), 
           @pm_FlgRegDscCliItePdv = IsNull(FlgRegDscCliItePdv,0),
           @pm_FlgUsaPolComPdv = IsNull(FlgUsaPolComPdv,0)
      From PARAM
     Where Cod_Estabe = @PCodEstabe

    Select @ct_CodCli = cl.Codigo,
           @ct_IdPolCom = IsNull(ct.Id_PolCom,0),
           @ct_CodVended = ct.Cod_Vended, 
           @ct_CodOperad = ct.Cod_Operad, 
           @ct_CodDigita = ct.Cod_Digita 
	  From CNGCB ct
           Inner Join CLIEN cl on ct.Cod_TipCng = 'C' and ct.Cod_Entida = cl.Codigo 
     Where ct.Cod_Estabe = @PCodEstabe and ct.Id_Consig = @PIdConsig

    -- WMS
    Set @WFlgUsaWms = (Select dbo.FN_ModExtOk(HASHBYTES('MD5','WMS'),
                                              HASHBYTES('MD5',(Select Num_Cnpj From ESTAB Where Cod_Estabe = @PCodEstabe))))

    Set @WFlgBlqWms = 0
    Set @WFlgBlqPol = 0
    Set @WCodTabPrz = 0
    Set @WCodLayout = 0

	-- Substring(Cod_OrigemPdv,1,1) = 'G'
    Exec PR_IncluiPDVCB 'P', @PCodEstabe, @PNumPdv output, 'G', @ct_CodCli, @WFlgUsaWms, @PTipOpe,
                        @ct_CodVended, @ct_CodOperad, @ct_CodDigita, @ct_IdPolCom, @WCodTabPrz, @WCodLayout,
                        @WFlgBlqWms, @WFlgBlqPol, @PMsgErr output

    Update pv
       Set pv.Status2 = 'X'
         , pv.Tip_Vencimento = ''
         , pv.Id_Consig = @PIdConsig    
         , pv.Num_SequenciaCtr = @PNumSequen
     From PDVCB pv
    Where pv.Cod_Estabe = @PCodEstabe
      And pv.Numero = @PNumPdv

    if @PNumPdv > 0
      begin
    
        Declare @WPFlgAchou bit,
                @WPTipSai varchar(1),
                @WPCodLot varchar(20),
                @WPLocFis varchar(15),
                @WPCodFab int,
                @WPFatCnvImpFat int,
                @WPPrcFab numeric(18,8),
                @WPPrcMaxCon numeric(18,8),
                @WPPrcRefFpb numeric(18,8),
                @WPPrcCusMinComMarkup numeric(18,8),
                @WPPrcTab numeric(18,8),
                @WPPrcTabBru numeric(18,8),
                @WPPrcUni numeric(18,8),
                @WPPrcUniLiqPer numeric(18,8),
                @WPFlgEmbDscPrc bit,
                @WPPerDscLin numeric(18,8),
                @WPPerDscPrz numeric(18,8),
                @WPPerDscVis numeric(18,8),
                @WPQtdPrzMax int,
                @WPCodRej varchar(3),
                @WPDesMsg varchar(80),
                @WPCmp varchar(20),
                @WPNomUsuDbq varchar(35),
                @WPDesMsgDbq varchar(60),
    
                @cr_NumSeq int,
                @cr_CodPrd int,
                @cr_QtdPed int, 
                @cr_PrcUni numeric(18,8), 
                @cr_PerDsc numeric(8,4), 
                @cr_FatCnvApr int,
                @cr_QtdImpFat numeric(18,4), 
                @cr_PrcUniImp numeric(18,8), 
                @cr_CodRej varchar(3),
                --@cr_DesMsg varchar(80),
                @WIte_QtdSolInf int,
                @WIte_QtdPedInf int, 
                @WIte_QtdBonInf int,
                @WIte_IdPolCom int,
    
                @WPPerDscPolCom numeric(18,8),
                @WPPerDscVisPolCom numeric(18,8),
                @WPPrcPolCom numeric(18,8),
                @WPQtdPrzPolCom int,
                @WPCodKitPrm int,
                @WPCodPromoc int,
                @WPFlgVerba bit,
                @WPFlgPolPrm bit,
    
                @WPC_PrcUni numeric(18,8),
                @WPC_PerDscIte numeric(18,8),
                @WPPrcUniLiqPdv numeric(18,8),
                @WPC_VlrDesconto numeric(18,8)  -- aqui
    
    ----------------------------------------------------------------------------------
    
        Declare PDVIT_Cr Cursor Local Fast_Forward For
    
          Select NumSeq = row_number() over(Order by it.Num_Sequen), it.Cod_Produt,
                 QtdPed = it.Qtd_Pedido,  
                 PrcUni = it.Prc_Unitar, 
                 it.Per_Descon, 
                 IsNull(it.Fat_CnvApr,1), QtdImpFat = it.Qtd_Pedido, PrcUniImp = it.Prc_Unitar
            From CNGRI it
                 Inner Join PRXES p on it.Cod_Estabe = p.Cod_Estabe and it.Cod_Produt = p.Cod_Produt
           Where it.Cod_Estabe = @PCodEstabe 
             And it.Id_Consig = @PIdConsig 
             And it.Num_Sequen = @PNumSequen
             And it.Qtd_Pedido > 0
    
        Open PDVIT_Cr
        Fetch Next From PDVIT_Cr Into @cr_NumSeq, @cr_CodPrd, 
                                      @cr_QtdPed, @cr_PrcUni, @cr_PerDsc, 
                                      @cr_FatCnvApr, @cr_QtdImpFat, @cr_PrcUniImp 
        While @@FETCH_STATUS = 0
          begin
            Set @WIte_QtdPedInf = @cr_QtdPed
            Set @WIte_QtdBonInf = 0
            Set @WIte_IdPolcom  = 0   -- ???????

            Set @WFlgBlqDscAutIte = 0
    
            Exec PR_InfoDefaultPDVIT @pm_FlgUsaPolComPdv, @PCodEstabe, @PNumPdv, @cr_CodPrd, 
                                     @WIte_QtdPedInf, @WIte_QtdBonInf, @WIte_IdPolCom output, @WFlgBlqDscAutIte,
                                     @WPFlgAchou output,
                                     @WPLocFis output,
                                     @WPCodFab output,
                                     @WPPrcFab output,
                                     @WPPrcMaxCon output,
                                     @WPPrcRefFpb output,
                                     @WPPrcTab output,
                                     @WPPrcTabBru output,
                                     @WPFatCnvImpFat output,     
                                     @WPPrcUni output,
                                     @WPPrcCusMinComMarkup output,
                                     @WPPerDscPolCom output,
                                     @WPPerDscVisPolCom output,
                                     @WPPrcPolCom output,
                                     @WPQtdPrzPolCom output,
                                     @WPFlgVerba output,
                                     @WPFlgPolPrm output,
                                     @WPCodKitPrm output,
                                     @WPCodPromoc output,
                                     @WPFlgEmbDscPrc output, 
                                     @WPQtdPrzMax output,
                                     @WPPerDscLin output,
                                     @WPPerDscPrz output,
                                     @WPPerDscVis output,
                                     @WPPrcUniLiqPer output
    
            if @WPFlgAchou = 1
              begin

                if @cr_PrcUni > 0
                  begin
                    Set @WPPrcUni       = @cr_PrcUni
                    Set @WPPerDscLin    = @cr_PerDsc  
                    Set @WPPerDscPrz    = @cr_PerDsc
                    Set @WPPerDscVis    = @cr_PerDsc
                  end

                if IsNull(@cr_PrcUniImp,0) = 0
                  Set @cr_PrcUniImp = @WPPrcUni*@cr_FatCnvApr

                Set @WPCodLot       = '*'
                Set @WPTipSai       = ''
                Set @WPFatCnvImpFat = @cr_FatCnvApr
    
    ----------------------------------------------------------------
                --  calcfields 
                Set @WPC_PrcUni = @WPPrcUni
                Set @WPC_PerDscIte = @cr_PerDsc
                   
                --  calcula preco unitario liquido
                Set @WPPrcUniLiqPdv = @WPPrcUni*(1-@WPC_PerDscIte/100)
                   
                if @WPFlgEmbDscPrc = 1
                  begin
                    Set @WPC_PrcUni = @WPPrcUni*(1-@WPC_PerDscIte/100)
                    Set @WPC_PerDscIte = 0
                  end
                   
                Set @WFlgSnhEsp = 0 
                Set @WNomUsuSnhEsp = ''
                Set @WFlgNaoCriConCom = 0  -- coloquei
                Set @WFlgBlqCriPrcVen = 0  -- coloquei
                Set @WFlgCriVrb = 0        -- coloquei
                Set @WFlgBlqQtdPar = 0
    
                Exec PR_CriticaItemPDV @pm_FlgUsaPolComPdv, @PCodEstabe, @PNumPdv, @cr_CodPrd, 
                                       @WIte_IdPolCom, @WIte_QtdPedInf, @WIte_QtdBonInf, @WPTipSai, @WPQtdPrzMax,
                                       @WPPrcUni, @WPPerDscVis, @WPPerDscPrz, @cr_QtdImpFat, @cr_PrcUniImp,
                                       @WPCodKitPrm, @WPPerDscPolCom, @WPPerDscVisPolCom, @WPPrcPolCom,
                                       @WPPrcUniLiqPdv, @WPPrcCusMinComMarkup, @WPPrcUniLiqPer, @WPFlgVerba,
                                       @WFlgSnhEsp, @WNomUsuSnhEsp, @WFlgNaoCriConCom, @WFlgBlqCriPrcVen, @WFlgCriVrb, @WFlgBlqQtdPar,
                                       @WPCodRej output, @WPDesMsg output, @WPCmp output, @WPNomUsuDbq output, @WPDesMsgDbq output

                Set @WIte_QtdSolInf = @WIte_QtdPedInf + @WIte_QtdBonInf
    
                if (@WPDesMsg = '') or (Substring(@WPCodRej,1,2) = 'PZ')  
                  begin
                    Set @WPCodRej = ''
                    Set @WPDesMsg = ''
                  end
                else
                  begin
                    Set @WIte_QtdPedInf = 0
                    Set @WIte_QtdBonInf = 0
                  end
    
                --Set @WPCodRej = @cr_CodRej
                --Set @WPDesMsg = @cr_DesMsg
    
                Insert Into PDVIT (Cod_Estabe, Num_SeqDig, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai)
                  Values (@PCodEstabe, @cr_NumSeq, @PNumPdv, @cr_CodPrd, @WPCodLot, @WPTipSai)
                         
                Update PDVIT 
                   Set Qtd_Pedido = @WIte_QtdPedInf 
                     , Qtd_Bonificacao = @WIte_QtdBonInf 
                     , Id_PolCom = @WIte_IdPolCom 
                     , Loc_Fisica = @WPLocFis 
                     , Cod_Fabricante = @WPCodFab
                     , Qtd_PrzMax = @WPQtdPrzMax 
                     , Prc_Fabric = @WPPrcFab 
                     , Prc_MaxCon = @WPPrcMaxCon 
                     , Prc_RefFpb = @WPPrcRefFpb 
                     , Prc_Tabela = @WPPrcTab 
                     , Prc_TabBru = @WPPrcTabBru
					 , Prc_Unitario = @WPPrcUni
                     , Per_Desconto = @WPPerDscLin 
                     , Per_Descon = @WPPerDscPrz 
                     , Per_DscVis = @WPPerDscVis 
                     , Flg_Verba = @WPFlgVerba 
                     , Prc_CusMinComMarkup = @WPPrcCusMinComMarkup
                     , Qtd_PrzPolCom = @WPQtdPrzPolCom 
					 , Prc_PolCom = @WPPrcPolCom 
					 , Per_DscPolCom = @WPPerDscPolCom 
					 , Per_DscVisPolCom = @WPPerDscVisPolCom 
					 , Cod_KitPrm = @WPCodKitPrm 
					 , Cod_Promocao = @WPCodPromoc

                     , Prc_UniPde = 0
					 , Per_DscPde = 0 
					 , Cod_PrjPde = '' 
					 , Num_SeqPdc = ''
                         
                     , Flg_PrcUniDsc = @WPFlgEmbDscPrc 
                     , Fat_CnvImpFat = @cr_FatCnvApr 
					 , Qtd_ImpFat = @cr_QtdImpFat 
					 , Prc_UniImpFat = @cr_PrcUniImp
					 , C_PrcUni = @WPC_PrcUni 
					 , C_PerDscIte = @WPC_PerDscIte

                     , Prc_UniLiqPer = @WPPrcUniLiqPer 
					 , Qtd_Solicitado = @WIte_QtdSolInf 
					 , Qtd_Acerto = 0 
					 , Flg_PolPrm = @WPFlgPolPrm

                     , Cod_MtvRej = @WPCodRej
					 , Des_MtvRej = Substring(@WPDesMsg,1,40)
					 , Nom_UsuDesbloq = Substring(@WPNomUsuDbq,1,15)
					 , Des_MsgDesbloq = Substring(@WPDesMsgDbq,1,60)

                 Where Cod_Estabe = @PCodEstabe
                   And Cod_Pedido = @PNumPdv
                   And Cod_Produto = @cr_CodPrd 
                   And Cod_Lote = @WPCodLot
                   And Tip_Sai = @WPTipSai


                --  atualiza motivo qdo for o caso
                Update PDVIT 
                   Set Cod_MtvRej = Case 
                                      When Qtd_Pedido > 0 then 'ES-' 
                                      Else 'ES0'
                                     End 
                 Where Cod_Estabe = @PCodEstabe
                   And Cod_Pedido = @PNumPdv
                   And Cod_Produto = @cr_CodPrd 
                   And Cod_Lote = @WPCodLot
                   And Tip_Sai = @WPTipSai
                   And Qtd_Pedido < Qtd_Solicitado 
                   And IsNull(Cod_MtvRej,'') = '' 

              end  -- if @WPFlgAchou = 1
    
            Fetch Next From PDVIT_Cr Into @cr_NumSeq, @cr_CodPrd, 
                                          @cr_QtdPed, @cr_PrcUni, @cr_PerDsc, 
                                          @cr_FatCnvApr, @cr_QtdImpFat, @cr_PrcUniImp 
          end
        Close PDVIT_Cr
        Deallocate PDVIT_Cr

        Update PDVCB 
    	   Set Status2 = 'A'
         Where Cod_Estabe = @PCodEstabe
           And Numero = @PNumPdv
    
        Exec PR_AtualizaCNGRI @PCodEstabe, @PIdConsig, @PNumSequen
        if (@@error <> 0)
          begin
            if @@trancount > 0
              Rollback Transaction
            Return
          end

        Update CNGRC
           Set Sta_CngPed = '2'
             , Num_PedVen = @PNumPdv
         Where Cod_Estabe = @PCodEstabe 
           And Id_Consig  = @PIdConsig 
           And Num_Sequen = @PNumSequen

      end  -- if @PNumPdv > 0
    
    if @@trancount > 0
      COMMIT TRANSACTION

  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraNfeDeNfs]
@PCodEstabe int,
@PSerNotSai varchar(3),
@PNumNotSai int,
@PCodEstabeDes int,
@PCodOpeEnt varchar(3),
@PFlgWms bit,
@PCodMtvDev varchar(3),
@PDesMtvDev varchar(40),
@PNumPrt int output


AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime,
		@MsgErr varchar(80)

Set @Now = GetDate()
Set @Date = Cast(Cast(Year(@Now) as varchar)+'-'+Cast(Month(@Now) as varchar)+'-'+Cast(Day(@Now) as varchar)+' 00:00:00' as smalldatetime)

Set @PCodOpeEnt = LTRIM(RTRIM(@PCodOpeEnt))

if (@PCodEstabe <> @PCodEstabeDes) and ((Select dbo.FN_InfarmaMultiEmpresa()) = 0)
  RAISERROR('Somente para Sistema Multi-Empresa',16,1)
else
if not Exists(Select Num_Nota From NFSCB 
               Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNotSai And Num_Nota = @PNumNotSai And Status <> 'A')
  RAISERROR('Nota Fiscal Não Localizada ou Inválida',16,1)
else
--if @PNumPrt > 0
--  begin
--    Set @MsgErr = 'Parâmetro (protocolo = '+cast(@PNumPrt as varchar)+') inválido'
--    RAISERROR(@MsgErr,16,1)
--  end
--else
if not Exists(Select 1 From ESTAB Where Cod_Estabe = @PCodEstabeDes)
  RAISERROR('Estabelecimento Destino inexistente',16,1)
else
begin

Declare @es_CodUF varchar(2) = '',
        @es_CodUFOri varchar(2) = '',
        @es_NumCnpjOri varchar(14) = '',
		@es_FlgContriSubstituido bit = 0,
		@pc_IdPdvCon int = 0,
		@rg_FlgConFin bit = 0,
		@ns_CodCfo int = 0,
		@ns_Estado varchar(2) = '',
		@ns_Cgc varchar(14) = '',
		@ns_CodCli int = 0,
		@ns_VlrSubTri numeric(18,4) = 0,
		@pm_FlgUsaEstornoNfe bit = 0,

		@ne_TipOpe varchar(1) = '',
        @ne_TipEmi varchar(1) = '',
		@ne_CodEmi int = 0,
        @ne_Cgc varchar(14) = '',
        @ne_Cgf varchar(15) = '',

		@ne_CodCfo int = 0,				 
        @ne_FlgBlqTrfEstFis bit = 0,
        @ne_FlgMovEst bit = 0,
        @ne_CodRegTri int = 0,
        @ne_CodTransp int = 0,
        @ne_Endereco varchar(50) = '',
        @ne_Bairro varchar(20) = '',
        @ne_Cidade varchar(25) = '',
        @ne_Cep varchar(8) = '',
        @ne_CodUfOri varchar(2) = '',
		@ne_CodCidIbge varchar(7),
		@op_TipOpe varchar(1),
		@op_FlgMovEst bit,

        @WFlgDscBon bit = 0,
        @WFlgConFin bit = 0,
		@WNumCnpj varchar(14) = '',
        @WCodCli int = 0,
		@UsuInfarma varchar(15)

Select @ne_CodRegTri = IsNull(ex.Cod_RegTri,0), 
	   @ne_CodTransp = IsNull(ex.Cod_Transp,0),
       @es_CodUF = es.Des_Estado,
	   @es_FlgContriSubstituido = IsNull(es.Flg_ContriSubstituido,0),
       @rg_FlgConFin = IsNull(rg.Flg_ConsumFin,0),
	   @pc_IdPdvCon = IsNull(pc.Id_PdvCon,0),
	   @ns_CodCfo = IsNull(ns.Cod_Cfo1,0),
	   @ns_Estado = IsNull(ns.Estado,''),
	   @ns_Cgc = IsNull(ns.Cgc,''),
       @ns_CodCli = IsNull(ns.Cod_Cliente,0),
	   @ns_VlrSubTri = IsNull(ns.Vlr_SubsTrib,0),
       @ne_TipOpe = IsNull(ns.Tip_Saida,op.Tip_Ope),
       @ne_FlgMovEst = IsNull(op.Flg_MovEst,IsNull(ns.Flg_MovEst,0)) 
  From NFSCB ns
       Inner Join ESTAB es on es.Cod_Estabe = @PCodEstabeDes
       Left  Join PVCCB pc on pc.Cod_Estabe = ns.Cod_Estabe and pc.Num_PdvCon = ns.Cod_Pedido
       Left  Join ENXES ex on ex.Cod_Estabe = es.Cod_Estabe and ns.Cgc = ex.Num_CgcCpf and ns.Cod_Cliente = ex.Cod_Client
	   Left  Join RGTRI rg on rg.Cod_RegTri = ex.Cod_RegTri
	   Left  Join TPOPE op on ns.Cod_Ope = op.Cod_Ope
 Where ns.Cod_Estabe = @PCodEstabe 
   And ns.Ser_Nota = @PSerNotSai
   And ns.Num_Nota = @PNumNotSai

Select @es_CodUFOri = Des_Estado,
       @es_NumCnpjOri = Num_Cnpj
  From ESTAB 
 Where Cod_Estabe = @PCodEstabe
  
Set @UsuInfarma = dbo.FN_UsuarioInfarma()
Set @ne_CodCfo = dbo.FN_InverteCfop(@ns_CodCfo)
if @ne_TipOpe = 'V' Set @ne_TipOpe = 'C'

-- tenta identificar Tipo de operação se for o caso -------------------------------------
-- pedido consolidado
if (IsNull(@PCodOpeEnt,'') = '') and (@pc_IdPdvCon > 0)
  begin
    Set @PCodOpeEnt = IsNull((Select pm.Cod_TipOpe
                                From PMTRF pm
                                     Left Join CLIEN cl on pm.Tip_EmiDes = 'C' And pm.Cod_EmiDes = cl.Codigo  
                                     Left Join FORNE fo on pm.Tip_EmiDes = 'F' And pm.Cod_EmiDes = fo.Codigo  
                                     Left Join TRANS tr on pm.Tip_EmiDes = 'T' And pm.Cod_EmiDes = tr.Codigo
                               Where pm.Cod_Estabe = @PCodEstabeDes  
                                 And pm.Cod_UF = @es_CodUFOri
                                 And pm.Tip_EntSai = 'E'
                                 And @es_NumCnpjOri = Case  
                                                        When pm.Tip_EmiDes = 'C' then cl.Cgc_Cpf
                                                        When pm.Tip_EmiDes = 'F' then fo.Cgc_Cpf
                                                        When pm.Tip_EmiDes = 'T' then tr.Cgc_Cpf
                                                        Else 'X'
                                                      End),'')
  end

if IsNull(@PCodOpeEnt,'') = ''
  Set @PCodOpeEnt = (Select top 1 Cod_Ope
                       From TPOPE 
                      Where Tip_EntSai = 'E'
                        And ((Cod_CfoNorInt = @ne_CodCfo) or 
                             (Cod_CfoSbtInt = @ne_CodCfo) or 
                             (Cod_CfoNorExt = @ne_CodCfo) or 
                             (Cod_CfoSbtExt = @ne_CodCfo))) 

if IsNull(@PCodOpeEnt,'') = ''
  Set @PCodOpeEnt = (Select top 1 Cod_Ope
                       From TPOPE 
                      Where Tip_EntSai = 'E'
                        And Tip_Ope = @ne_TipOpe)

--------------------------------------------------------------------------------------------------------------------

if (@PCodOpeEnt = '') or (not Exists(Select Cod_Ope From TPOPE Where Cod_Ope = @PCodOpeEnt and Tip_EntSai = 'E'))
  RAISERROR('Tipo de Operação de Entrada Inexistente ou Inválida',16,1)
else
BEGIN
BEGIN TRANSACTION

-- forçar = zero
Set @PNumPrt = 0

Select @op_TipOpe = Tip_Ope,
       @op_FlgMovEst = IsNull(Flg_movEst,0)
  From TPOPE 
 Where Cod_Ope = @PCodOpeEnt

-- identifica emitente 
if @op_TipOpe = 'D'
  begin
    --pelo cnpj da nf de saida
	Set @WNumCnpj = @ns_Cgc
    Set @WCodCli = @ns_CodCli
    if Exists(Select cl.Codigo 
                From CLIEN cl 
                     Inner Join ENXES en on en.Cod_Estabe = @PCodEstabeDes and en.Num_CgcCpf = cl.Cgc_Cpf and en.Cod_Client = cl.Codigo
			   Where cl.Codigo = @WCodCli)
      begin
        Set @ne_TipEmi = 'C'
        Select @ne_CodEmi = cl.Codigo, 
               @ne_Cgc = cl.Cgc_Cpf,
               @ne_Cgf= cl.Cgf,
	           @ne_CodRegTri = en.Cod_RegTri, 
		       @ne_CodTransp = en.Cod_Transp,
               @ne_Endereco = Substring(dbo.FN_EnderecoCompleto(cl.Endereco, cl.Numero, cl.Complemento),1,50),
		       @ne_Bairro = Substring(ba.Descricao,1,20),
		       @ne_Cidade = Substring(ci.Descricao,1,25), 
	           @ne_CodUfOri = cl.Cod_Estado, 
		       @ne_Cep = cl.Cep,
		       @ne_CodCidIbge = IsNull(ci.Cod_CidIbge,'')
          From CLIEN cl 
               Inner Join ENXES en on en.Cod_Estabe = @PCodEstabeDes and en.Num_CgcCpf = cl.Cgc_Cpf and en.Cod_Client = cl.Codigo
	           Left  Join CIDAD ci on cl.Cod_Estado = ci.Cod_Estado and cl.Cod_Cidade = ci.Codigo
	           Left  Join BAIRR ba on cl.Cod_Estado = ba.Cod_Estado and cl.Cod_Cidade = ba.Cod_Cidade and cl.Cod_Bairro = ba.Codigo
         Where cl.Codigo = @WCodCli
      end
    else
    if Exists(Select fo.Codigo From FORNE fo Inner Join ENXES en on fo.Cgc_Cpf = en.Num_CgcCpf 
              Where en.Cod_Estabe = @PCodEstabeDes And fo.Cgc_Cpf = @WNumCnpj)
      begin
        Set @ne_TipEmi = 'F'
        Select @ne_CodEmi = fo.Codigo, 
               @ne_Cgc = fo.Cgc_Cpf,
               @ne_Cgf= fo.Cgf_Rg,
	           @ne_CodRegTri = en.Cod_RegTri, 
		       @ne_CodTransp = en.Cod_Transp,
               @ne_Endereco = Substring(dbo.FN_EnderecoCompleto(fo.Endereco_Com, fo.Numero_Com, fo.Complemento_Com),1,50),
    		   @ne_Bairro = IsNull(Substring(ba.Descricao,1,20),Substring(fo.Bairro_Com,1,20)),
	    	   @ne_Cidade = IsNull(Substring(ci.Descricao,1,25),Substring(fo.Cidade_Com,1,25)), 
	           @ne_CodUfOri = fo.Estado_Com,
    		   @ne_Cep = fo.Cep_Com,
	    	   @ne_CodCidIbge = IsNull(ci.Cod_CidIbge,'')
          From FORNE fo 
               Inner Join ENXES en on fo.Cgc_Cpf = en.Num_CgcCpf 
    	       Left Join CIDAD ci on fo.Estado_Com = ci.Cod_Estado and fo.Cod_Cidade_Com = ci.Codigo
	           Left Join BAIRR ba on fo.Estado_Com = ba.Cod_Estado and fo.Cod_Cidade_Com = ba.Cod_Cidade and fo.Cod_Bairro_Com = ba.Codigo
         Where en.Cod_Estabe = @PCodEstabeDes
           And fo.Cgc_Cpf = @WNumCnpj
      end
    else
    if Exists(Select tr.Codigo From TRANS tr Inner Join ENXES en on tr.Cgc_Cpf = en.Num_CgcCpf 
              Where en.Cod_Estabe = @PCodEstabeDes And tr.Cgc_Cpf = @WNumCnpj)
      begin
        Set @ne_TipEmi = 'T'
        Select @ne_CodEmi = tr.Codigo, 
               @ne_Cgc = tr.Cgc_Cpf,
               @ne_Cgf= tr.Cgf_Rg,
    	       @ne_CodRegTri = en.Cod_RegTri, 
    		   @ne_CodTransp = en.Cod_Transp,
               @ne_Endereco = Substring(dbo.FN_EnderecoCompleto(tr.Endereco, tr.Numero, tr.Complemento),1,50),
    		   @ne_Bairro = IsNull(Substring(ba.Descricao,1,20),Substring(tr.Bairro,1,20)),
    		   @ne_Cidade = IsNull(Substring(ci.Descricao,1,25),Substring(tr.Cidade,1,25)), 
    	       @ne_CodUfOri = tr.Estado,
    		   @ne_Cep = tr.Cep,
    		   @ne_CodCidIbge = IsNull(ci.Cod_CidIbge,'')
          From TRANS tr 
               Inner Join ENXES en on tr.Cgc_Cpf = en.Num_CgcCpf 
    	       Left  Join CIDAD ci on tr.Estado = ci.Cod_Estado and tr.Cod_Cidade = ci.Codigo
     	       Left  Join BAIRR ba on tr.Estado = ba.Cod_Estado and tr.Cod_Cidade = ba.Cod_Cidade and tr.Cod_Bairro = ba.Codigo
         Where en.Cod_Estabe = @PCodEstabeDes
           And tr.Cgc_Cpf = @WNumCnpj
      end
  end  -- if @op_TipOpe = 'D'

if @pc_IdPdvCon > 0
  begin
	Set @WNumCnpj = @es_NumCnpjOri

    if not Exists(Select 1 From PMTRF Where Cod_Estabe = @PCodEstabeDes And Cod_UF = @es_CodUFOri And Tip_EntSai = 'E')
      begin
	    -- dispara trigger
        Update PMTRF 
           Set Cod_EmiDes = IsNull(Cod_EmiDes,0) + 0
         Where Cod_Estabe = @PCodEstabe
           And Cod_UF = @es_CodUF
           And Tip_EntSai = 'S'
      end

    Select @ne_TipEmi = IsNull(x.Tip_EmiDes,''), 
           @ne_CodEmi = IsNull(x.Cod_EmiDes,0),
	       @ne_Cgc = IsNull(x.Num_Cnpj,''),
    	   @ne_Cgf = IsNull(x.Insc_Est,''),
           @ne_CodRegTri = IsNull(ex.Cod_RegTri,0),
           @ne_CodTransp = IsNull(ex.Cod_Transp,0),
           @ne_Endereco = Substring(dbo.FN_EnderecoCompleto(x.Endereco,x.Numero,x.Complem),1,50),
    	   @ne_CodUfOri = IsNull(x.Cod_Estado,''),
           @ne_Cidade = Substring(IsNull(ci.Descricao,''),1,25),
    	   @ne_Bairro = Substring(IsNull(ba.Descricao,''),1,20),
	       @ne_CodCidIbge = IsNull(ci.Cod_CidIbge,'')
      From (Select pm.Tip_EmiDes, pm.Cod_EmiDes,
                   Num_Cnpj   = Case 
                                  When fo.Codigo > 0 then fo.Cgc_Cpf 
                                  When cl.Codigo > 0 then cl.Cgc_Cpf 
                                  When tr.Codigo > 0 then tr.Cgc_Cpf 
                                End,
                   Insc_Est   = Case 
                                  When fo.Codigo > 0 then fo.Cgf_Rg
                                  When cl.Codigo > 0 then cl.Cgf 
                                  When tr.Codigo > 0 then tr.Cgf_Rg 
                                End,
                   Endereco   = Case 
                                  When fo.Codigo > 0 then fo.Endereco_Com 
                                  When cl.Codigo > 0 then cl.Endereco
                                  When tr.Codigo > 0 then tr.Endereco
                                End,
                   Numero     = Case 
                                  When fo.Codigo > 0 then fo.Numero_Com 
                                  When cl.Codigo > 0 then cl.Numero
                                  When tr.Codigo > 0 then tr.Numero
                                End,
                   Complem    = Case 
                                  When fo.Codigo > 0 then fo.Complemento_Com 
                                  When cl.Codigo > 0 then cl.Complemento
                                  When tr.Codigo > 0 then tr.Complemento
                                End,
                   Cod_Estado = Case 
                                  When fo.Codigo > 0 then fo.Estado_Com 
                                  When cl.Codigo > 0 then cl.Cod_Estado
                                  When tr.Codigo > 0 then tr.Estado
                                End,
                   Cod_Cidade = Case 
                                  When fo.Codigo > 0 then fo.Cod_Cidade_Com 
                                  When cl.Codigo > 0 then cl.Cod_Cidade
                                  When tr.Codigo > 0 then tr.Cod_Cidade
                                End,
                   Cod_Bairro = Case 
                                  When fo.Codigo > 0 then fo.Cod_Bairro_Com 
                                  When cl.Codigo > 0 then cl.Cod_Bairro
                                  When tr.Codigo > 0 then tr.Cod_Bairro
                                End
              From PMTRF pm
                   Left Join CLIEN cl on pm.Tip_EmiDes = 'C' And pm.Cod_EmiDes = cl.Codigo  
                   Left Join FORNE fo on pm.Tip_EmiDes = 'F' And pm.Cod_EmiDes = fo.Codigo  
                   Left Join TRANS tr on pm.Tip_EmiDes = 'T' And pm.Cod_EmiDes = tr.Codigo
             Where pm.Cod_Estabe = @PCodEstabeDes  
               And pm.Cod_UF = @es_CodUFOri
               And pm.Tip_EntSai = 'E'
               And @es_NumCnpjOri = Case  
                                      When pm.Tip_EmiDes = 'C' then cl.Cgc_Cpf
                                      When pm.Tip_EmiDes = 'F' then fo.Cgc_Cpf
                                      When pm.Tip_EmiDes = 'T' then tr.Cgc_Cpf
                                      Else 'X'
                                    End) x
           Inner Join ENXES ex on ex.Cod_Estabe = @PCodEstabeDes and x.Num_Cnpj = ex.Num_CgcCpf 
           Left  Join CIDAD ci on x.Cod_Estado = ci.Cod_Estado and x.Cod_Cidade = ci.Codigo
           Left  Join BAIRR ba on x.Cod_Estado = ba.Cod_Estado and x.Cod_Cidade = ba.Cod_Cidade and x.Cod_Bairro = ba.Codigo
  end

if (@ne_Cgc = '') and
   Exists(Select Num_CgcCpf From ENTID Where Num_CgcCpf = @WNumCnpj)
  begin
    Set @ne_TipEmi = 'X'
    Select @ne_CodEmi = 0, 
           @ne_Cgc = en.Num_CgcCpf,
           @ne_Cgf= en.Num_CgfRg,
           @ne_CodRegTri = ex.Cod_RegTri, 
		   @ne_CodTransp = ex.Cod_Transp,
           @ne_Endereco = Substring(dbo.FN_EnderecoCompleto(en.Des_Endere, en.Num_Endere, en.Des_CplEnd),1,50),
  		   @ne_Bairro = Substring(en.Des_Bairro,1,20),
  		   @ne_Cidade = Substring(en.Des_Cidade,1,25),
   	       @ne_CodUfOri = en.Des_Estado,
   		   @ne_Cep = en.Num_Cep,
   		   @ne_CodCidIbge = IsNull(en.Cod_CidIbge,'')
      From ENTID en
           Inner Join ENXES ex on en.Num_CgcCpf = ex.Num_CgcCpf 
     Where ex.Cod_Estabe = @PCodEstabeDes
       And ex.Num_CgcCpf = @WNumCnpj
  end


if @ne_CodCfo = 0
  begin
    Select @ne_CodCfo = Case
                          When (@rg_FlgConFin = 1) and (@ns_Estado = @es_CodUF)  then op.Cod_CfoConFinInt
                          When (@rg_FlgConFin = 1) and (@ns_Estado <> @es_CodUF) then op.Cod_CfoConFinExt
                          When (@ns_VlrSubTri > 0) and (@ns_Estado = @es_CodUF)  and (@es_FlgContriSubstituido = 1) then op.Cod_CfoSbtIntSubstituido
                          When (@ns_VlrSubTri > 0) and (@ns_Estado = @es_CodUF)  and (@es_FlgContriSubstituido = 0) then op.Cod_CfoSbtInt
                          When (@ns_VlrSubTri > 0) and (@ns_Estado <> @es_CodUF) and (@es_FlgContriSubstituido = 1) then op.Cod_CfoSbtExtSubstituido
                          When (@ns_VlrSubTri > 0) and (@ns_Estado <> @es_CodUF) and (@es_FlgContriSubstituido = 0) then op.Cod_CfoSbtExt
                          When (@ns_VlrSubTri = 0) and (@ns_Estado = @es_CodUF)  then op.Cod_CfoNorInt
                          When (@ns_VlrSubTri = 0) and (@ns_Estado <> @es_CodUF) then op.Cod_CfoNorExt
                       End
	 From TPOPE op
    Where op.Cod_Ope = @PCodOpeEnt
  end

Select @ne_FlgBlqTrfEstFis = IsNull(Flg_BlqTrfEstFis,0) 
  From TBCFO 
 Where Codigo = @ne_CodCfo

Set @pm_FlgUsaEstornoNfe = IsNull((Select FlgUsaEstornoNfe From PARAM Where Cod_Estabe = @PCodEstabeDes),0)

if IsNull(@PNumPrt,0) = 0
  EXEC PR_ProxNumero 'Protocolo', @PNumPrt output

-- grava cabecalho
Insert Into NFECB (Cod_Estabe, Protocolo, Flg_Importado, Usuario, Transacao)
           Values (@PCodEstabeDes, @PNumPrt, 1, @UsuInfarma, @Now) 
if @@error <> 0
  begin
    Rollback Transaction
    Return
  end        
              
-- grava campos na nota
Update ne
   Set ne.Cod_Ope = @PCodOpeEnt,
       ne.Tip_NF = @op_TipOpe,
       ne.Cod_RegTri = @ne_CodRegTri,
       ne.Cod_Transp = @ne_CodTransp, 
       ne.Cod_Cfo = @ne_CodCfo,
       ne.Flg_BlqTrfEstFis = IsNull(@ne_FlgBlqTrfEstFis,0),
       ne.Cgc_Cpf = @ne_Cgc,
       ne.Cgf_Rg = @ne_Cgf,
	   ne.Tip_Emitente = @ne_TipEmi,
	   ne.Cod_EmiCliente = Case When @ne_TipEmi = 'C' then @ne_CodEmi Else 0 End,
	   ne.Cod_EmiFornec  = Case When @ne_TipEmi = 'F' then @ne_CodEmi Else 0 End,
	   ne.Cod_EmiTransp  = Case When @ne_TipEmi = 'T' then @ne_CodEmi Else 0 End,

       ne.Endereco = @ne_Endereco,
       ne.Cod_UfOrigem = @ne_CodUfOri,
       ne.Bairro = @ne_Bairro,
       ne.Cidade = @ne_Cidade,
       ne.Cep = @ne_Cep,
	   ne.Cod_CidIbge = @ne_CodCidIbge,

       ne.Status= 'A',
       ne.Status_2 = '',
	   ne.Id_PdvCon = @pc_IdPdvCon,   -- indica que foi gerado por consolidação
       ne.Cod_Pedido = 0,             -- pedido de compra
       ne.Flg_DevTot = 0,             -- nao eh devolucao total
       ne.Flg_MovEst = @op_FlgMovEst, -- movimenta estoque
       ne.Dat_Entrada = @Date,  
       ne.Dat_Emissao = @Date,
       ne.Dat_Movimento = @Date,
       ne.Flg_WMS = @PFlgWms,
       ne.Obs_Rodape = '',
       @WFlgDscBon = Case 
                       When IsNull(ns.Vlr_DscBon,0) > 0 then 1
                       Else 0 
                     End,
       ne.Num_Formulario = ns.Num_Formulario, 
       ne.Qtd_PagNf = ns.Qtd_PagNf, 
       ne.Qtd_Itens = ns.Qtd_Itens,
	   ne.Tip_Consumidor = ns.Tip_Consumidor,
       ne.Qtd_Volumes = ns.Qtd_Volumes,
       ne.Qtd_PesBru = ns.Qtd_PesBru,
       ne.Qtd_Peso = ns.Qtd_Peso,

       ne.Cod_VendTlmkt = ns.Cod_VendTlmkt,
       ne.Cod_Vendedor = ns.Cod_Vendedor,
       ne.Vlr_Mercadoria = ns.Vlr_LiqItens,
       ne.Vlr_Nota = ns.Vlr_TotalNota,
       
       ne.Cod_VlrFiscal = ns.Cod_VlrFiscal,
       ne.Vlr_BasIpi = IsNull(ns.Vlr_BasIpi,0),
       ne.Vlr_Ipi = IsNull(ns.Vlr_Ipi,0),
       ne.Vlr_BasIcmsNor = ns.Vlr_BasIcmsNor,
       ne.Vlr_IcmsNor = ns.Vlr_IcmsNor,
       ne.Vlr_BasIcmsTri = ns.Vlr_BasIcmsTri,
       ne.Vlr_IcmsTri = ns.Vlr_IcmsTri,
       ne.Vlr_BasIstFon = ns.Vlr_BasSubsTrib,
       ne.Vlr_IstFon = ns.Vlr_SubsTrib,
	   ne.Vlr_PrdSubTri = ns.Vlr_PrdSubTri,
       ne.Vlr_Desconto = IsNull(ns.Vlr_DescontoCom,0)+IsNull(ns.Vlr_DscBon,0)+
	                     IsNull(ns.Vlr_RepIcms,0),
	   ne.Vlr_Despesas = ns.Vlr_OutDsp,
	   ne.Vlr_DscTri = IsNull(ns.Vlr_DscTri,0),
       ne.Vlr_BasSbtRes = ns.Vlr_BasSbtRes,
       ne.Vlr_SbtRes = ns.Vlr_SbtRes,
       ne.Vlr_DspExt = ns.Vlr_DspExt,
       ne.Per_Comvnd = ns.Per_Comvnd,
       ne.Vlr_Outros = ns.Vlr_Outros,  
       ne.Vlr_Isento = ns.Vlr_Isento,
	   ne.Via_Transp = ns.Via_Transp,
	   ne.Tip_Frete = '1',
       ne.Vlr_Frete = 0,
       ne.Vlr_Seguro = 0,
--	  ne.Pessoa = ns.Pessoa,

       ne.Numero = Case
                     When @pc_IdPdvCon > 0 Then @PNumNotSai
                     Else 0
                   End,
       ne.Serie = Case
                    When @pc_IdPdvCon > 0 Then @PSerNotSai
                    Else 0
                  End,
       ne.Especie = 'NF',
       ne.Ser_SeloFisTran = '',

       ne.Flg_Importado = 0,
       ne.Flg_ImpNot = Case When @op_TipOpe = 'D' then 1 Else 0 End,  -- imprime NF
       ne.Flg_Estorno = Case When (@pm_FlgUsaEstornoNfe = 1) and (@op_TipOpe = 'D') then 1 Else 0 End,
       ne.Chv_Acesso = Case When @op_TipOpe = 'D' then '' Else ns.Chv_Acesso End,    
       ne.Cod_ModDoc = Case When @op_TipOpe = 'D' then '' Else ns.Cod_ModDoc End,    
       ne.Tip_DocRel = Case When @op_TipOpe = 'D' then 'S' Else '' End,
       ne.Str_RelDoc = Case When @op_TipOpe = 'D' then ns.Ser_Nota+','+cast(ns.Num_Nota as varchar) Else '' End,
	   ne.Cod_FinNfe = Case When @op_TipOpe = 'D' then '4' Else '1' End, --1-Normal  4- devolução
       ne.Cod_MtvDev = @PCodMtvDev,
       ne.Des_MtvDev = @PDesMtvDev

  From NFECB ne, NFSCB ns
 Where ne.Cod_Estabe = @PCodEstabeDes
   And ne.Protocolo = @PNumPrt
   And ns.Cod_Estabe = @PCodEstabe 
   And ns.Ser_Nota = @PSerNotSai 
   And ns.Num_Nota = @PNumNotSai

-- inclui itens
Insert Into NFEIT (Cod_Estabe, Protocolo, Cod_Produto, Cod_Lote, Num_SeqIte, Tip_Ent)
  Select @PCodEstabeDes, @PNumPrt, Cod_Produto, Cod_Lote, Num_SeqIte, ''
   From NFSIT
   Where Cod_Estabe = @PCodEstabe 
     And Ser_Nota = @PSerNotSai 
     And Num_Nota = @PNumNotSai

Update ne
   Set ne.Dat_Movimento = @Date,

       ne.Cod_ClaTri = ns.Cod_ClaTri,
       ne.Tip_LisPis = ns.Tip_Aux,

       ne.Prc_Venda  = ns.Prc_TabBru, 
       ne.Prc_Fabric = ns.Prc_Fabric,
       ne.Prc_MaxCon = ns.Prc_MaxCon,
       ne.Prc_RefFpb = ns.Prc_RefFpb,

       ne.Ctrl_Tributacao = ns.Ctrl_Tributacao,

       ne.Alq_Icms = ns.Alq_Icms, 
       ne.Vlr_BasIcmsNor = ns.Vlr_BasIcmsNor, 
       ne.Vlr_IcmsNor = ns.Vlr_IcmsNor,

       ne.Vlr_PrdSubTri = ns.Vlr_PrdSubTri,
	   ne.Vlr_BasSubsTrib = ns.Vlr_BasSubsTrib, 
	   ne.Vlr_SubsTrib = ns.Vlr_SubsTrib,  
       ne.Alq_IcmDeb = ns.Alq_IcmSbt,
--      ne.Alq_IcmSbt = ns.Alq_IcmSbt,

       ne.Vlr_BasSbtRes = ns.Vlr_BasSbtRes,
       ne.Vlr_SbtRes = ns.Vlr_SbtRes,
       ne.Vlr_DspExt  = ns.Vlr_DspExt,

 	   ne.Vlr_BasIcmsTrib = ns.Vlr_BasIcmsTri, 
	   ne.Vlr_IcmsTrib = ns.Vlr_IcmsTri,
       ne.Vlr_Isento = ns.Vlr_Isento,
       ne.Vlr_Outros = ns.Vlr_Outros,  

	   ne.Vlr_Ipi = ns.Vlr_Ipi, 
       ne.Vlr_Frete = 0,
       ne.Vlr_Seguro = 0,
	   ne.Vlr_DespRateada = ns.Vlr_DespRateada,
	   ne.Vlr_DescRateado = ns.Vlr_DescRateado,
	   ne.Vlr_DscTri = ns.Vlr_DscTri,
       ne.Vlr_Comissao = IsNull(ns.Vlr_Comissao,0),
       ne.Vlr_ComTlmkt = IsNull(ns.Vlr_ComTlmkt,0),
       ne.Vlr_Verba = IsNull(ns.Vlr_Verba,0),
	   ne.Vlr_VrbOpe = IsNull(ns.Vlr_VrbOpe,0),
	   ne.Vlr_VrbSup = IsNull(ns.Vlr_VrbSup,0),
       ne.Vlr_BasRepIcm = 0,  -- ns.Vlr_BasRepIcms
       ne.Vlr_RepIcm = 0,      --ns.Vlr_RepIcms
 
       ne.Flg_ComisNormal = ns.Flg_ComisNormal,
       ne.Dat_Fabric = (Select top 1 Dat_Fabric 
                          From PRLOT Where Cod_Estabe = ns.Cod_Estabe
                           and Cod_Produt = ns.Cod_Produto
                           and Cod_Lote = ns.Cod_Lote
                           and Dat_Fabric > 0
                         Order by Cod_Dep),
       ne.Dat_Vencim = (Select top 1 Dat_Vencim
                          From PRLOT Where Cod_Estabe = ns.Cod_Estabe
                           and Cod_Produt = ns.Cod_Produto
                           and Cod_Lote = ns.Cod_Lote
                         Order by Cod_Dep), 
       ne.Qtd_Pedido = ns.Qtd_Produto,
       ne.Qtd_Bonificacao = ns.Qtd_Bonificacao,
       ne.Prc_Unitario = ns.Prc_Unitario,
       ne.Per_DescItem = Case When ns.Per_Desconto > 0 then ns.Per_Desconto Else 0 End,

       ne.Flg_BlqDsc = Case 
                         When ((@WFlgDscBon = 1) and (IsNull(ns.Vlr_DscBonRat,0) = 0)) then 1 
                         Else 0 
                       End,

       ne.Fator_Fat = 1,
       ne.Qtd_PedFat = ns.Qtd_Produto,
       ne.Qtd_BonFat = ns.Qtd_Bonificacao,
       ne.Prc_UniFat = ns.Prc_Unitario,
	   ne.Per_Markup = IsNull(pr.Per_Markup,0),
	   ne.Cod_CEST = ns.Cod_CEST

  From NFEIT ne, NFSIT ns, PRODU pr
 Where ne.Cod_Estabe = @PCodEstabeDes
   And ne.Protocolo = @PNumPrt
   And ns.Cod_Estabe = @PCodEstabe 
   And ns.Ser_Nota = @PSerNotSai 
   And ns.Num_Nota = @PNumNotSai
   And ne.Cod_Produto = ns.Cod_Produto
   And ne.Cod_Lote = ns.Cod_Lote
   And ne.Num_SeqIte = ns.Num_SeqIte
   And pr.Codigo = ns.Cod_Produto

-- calc fields
Update NFEIT
   Set Vlr_DscIte1 = Case When Per_DescItem > 0 then Round(Prc_Unitario*Qtd_Pedido,2) - Round(Prc_Unitario*Qtd_Pedido*(1-Per_DescItem/100),2) Else 0 End,
       Vlr_DscIte2 = 0,
       Vlr_TotItem = Round(Prc_Unitario*Qtd_Pedido*(1-Per_DescItem/100),2),
       Vlr_BruItem = Round(Prc_Unitario*(Qtd_Pedido+IsNull(Qtd_Bonificacao,0)),2),
       Vlr_DescItem = Case 
                        When Per_DescItem > 0 then Round(Prc_Unitario*(Qtd_Pedido+IsNull(Qtd_Bonificacao,0)),2) - Round(Prc_Unitario*Qtd_Pedido*(1-Per_DescItem/100),2)
	                    Else Round(Prc_Unitario*IsNull(Qtd_Bonificacao,0),2) 
                      End
 Where Cod_Estabe = @PCodEstabeDes
   And Protocolo = @PNumPrt

Update NFEIT
   Set Vlr_LiqIte = Vlr_TotItem -
                    IsNull(Vlr_DescRateado,0) -
                    IsNull(Vlr_DscTri,0) +
                    IsNull(Vlr_DespRateada,0) +
                    IsNull(Vlr_SubsTrib,0) +
                    IsNull(Vlr_DifTri,0) +
                    IsNull(Vlr_SbtRes,0) +
                    IsNull(Vlr_Ipi,0) +
                    IsNull(Vlr_Suframa,0) +
                    IsNull(Vlr_Frete,0) +
                    IsNull(Vlr_Seguro,0) + 
                    IsNull(Vlr_DspExt,0)
 Where Cod_Estabe = @PCodEstabeDes
   And Protocolo = @PNumPrt

Exec PR_AtualizaCfopItemNf @PCodEstabeDes,'',@PNumPrt

-- inclui contas a pagar
if Exists(Select top 1 1 From CTREC Where Cod_Estabe = @PCodEstabe And Ser_NfOrigem = @PSerNotSai And Num_NfOrigem = @PNumNotSai) and
   Exists(Select 1 From NFECB Where Cod_Estabe = @PCodEstabeDes And Protocolo = @PNumPrt And IsNull(Cod_EmiFornec,0) > 0)
  begin

    Declare @cb_CodFornec int,
            @cb_NumNot int,
	        @pm_CodAgeCobCar int,
            @pf_FlgUsaInterv bit,
            @pf_CodCntCusCtaPag int,
            @fo_IsnCtaFin int,
            @WCodCtaPag int,
            @WCodRat int,
            @cr_NumDoc varchar(12),
            @cr_DatEmi smalldatetime,
            @cr_DatVct smalldatetime, 
            @cr_PerDscAtc numeric(18,4),
            @cr_DatDscAtc smalldatetime, 
            @cr_VlrDscAtc numeric(18,4),
            @cr_VlrDoc numeric(18,4)

    Select @pm_CodAgeCobCar = CodAgeCobCar
      From PARAM
     Where Cod_Estabe = @PCodEstabe      

    Select @pf_FlgUsaInterv = IsNull(FlgUsaInterv,0),
           @pf_CodCntCusCtaPag = IsNull(CodCntCusCtaPag,0)
      From PMFIN

    Select @cb_CodFornec = cb.Cod_EmiFornec,
           @cb_NumNot = Numero, 
           @fo_IsnCtaFin = IsNull(fo.Isn_CtaFin,0)     
      From NFECB cb
	       Inner Join FORNE fo on cb.Cod_EmiFornec = fo.Codigo
     Where cb.Cod_Estabe = @PCodEstabeDes
       And cb.Protocolo = @PNumPrt

    -- novo financeiro: zera conta gerencial
    if @pf_FlgUsaInterv = 1
      Set @fo_IsnCtaFin = 0    

    DECLARE Ctrec_Cr CURSOR Local Fast_Forward For 
      Select NumDoc = (Num_Documento+Par_Documento), 
	         Dat_Emissao, Dat_Vencimento, 
             Per_DescFinanc, Dat_DscAtc, Vlr_DscAtc, 
		     VlrDoc = Round((Vlr_Documento-Vlr_DescConced),2)
        From CTREC
       Where Cod_Estabe = @PCodEstabe
         And Ser_NfOrigem = @PSerNotSai
         And Num_NfOrigem = @PNumNotSai
    OPEN Ctrec_Cr
    FETCH NEXT FROM Ctrec_Cr INTO @cr_NumDoc, @cr_DatEmi, @cr_DatVct, @cr_PerDscAtc, @cr_DatDscAtc, @cr_VlrDscAtc, @cr_VlrDoc
    WHILE @@FETCH_STATUS = 0
    BEGIN
      EXEC PR_ProxNumero 'Contas_Pagar', @WCodCtaPag output
      Insert into PAGCT (Cod_Estabe, Cod_CtaPag, Tip_Docume, Sta_Docume, Tip_Documento, Cod_Fornec, Dat_Emissa, Dat_Registro,
                         Num_NotOri, Cod_PrtNfe, Cod_PrtPdc, Flg_Consig, Flg_Previs, Cod_AgeCob, Num_Docume, Dat_Vencim,
                         Val_Docume, Val_Saldo, Observacao, Usuario, Transacao,
                         Per_DscAtc, Dat_DscAtc, Val_DscAtc, Isn_CtaFin)
                  Values(@PCodEstabeDes, @WCodCtaPag, 'F', 'A', 'DUP', @cb_CodFornec, @cr_DatEmi, @Date,
                         @cb_NumNot, @PNumPrt, 0, 0, 1, @pm_CodAgeCobCar, @cr_NumDoc, @cr_DatVct,
                         @cr_VlrDoc, @cr_VlrDoc, '', @UsuInfarma, GetDate(),
                         @cr_PerDscAtc, @cr_DatDscAtc, @cr_VlrDscAtc, @fo_IsnCtaFin)
      if @@error <> 0
        begin
          Rollback Transaction
          Return
        end

      EXEC PR_ProxNumero 'Isn_CtaRat', @WCodRat output
      if @@error <> 0
        begin
          Rollback Transaction
          Return
        end

      Insert into PAGRT (Cod_Estabe, Isn_CtaRat, Cod_CtaPag, Isn_CtaFin, Cod_CntCus, Val_DocRat, Val_DscRat)
                 Values (@PCodEstabeDes, @WCodRat, @WCodCtaPag, @fo_IsnCtaFin, @pf_CodCntCusCtaPag, @cr_VlrDoc, 0) 
      if @@error <> 0
        begin
          Rollback Transaction
          Return
        end

      FETCH NEXT FROM Ctrec_Cr INTO @cr_NumDoc, @cr_DatEmi, @cr_DatVct, @cr_PerDscAtc, @cr_DatDscAtc, @cr_VlrDscAtc, @cr_VlrDoc
    END
    CLOSE Ctrec_Cr
    DEALLOCATE Ctrec_Cr
  end  -- inclui contas a pagar

-- atualiza status que indica que foi gerado nota de entrada ref. pedido consolidado
Update PVCCB 
   Set Sta_PdvCon = '3'   
 Where Id_PdvCon = @pc_IdPdvCon

COMMIT TRANSACTION
END
end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE TRIGGER [dbo].[TR_ENDDP_AtualizaCampos_Depois] ON [dbo].[ENDDP] 
AFTER INSERT, UPDATE, DELETE 
NOT FOR REPLICATION
AS

-- comando p/ corrigir erro delphi/ado: record was changed by another user
SET NOCOUNT ON 

if Update(Vol_Util) or Update(Vol_Ocup)
  begin
    Update E
      Set E.Vol_Disp = Case 
                         When I.Vol_Util > I.Vol_Ocup Then I.Vol_Util-I.Vol_Ocup
                         Else E.Vol_Util
                       End  
      From Inserted I inner Join 
           ENDDP E on E.Cod_Estabe = I.Cod_Estabe and 
                      E.Cod_Dep = I.Cod_Dep and 
                      E.Num_Rua = I.Num_Rua and E.Num_Col = I.Num_Col and 
                      E.Num_NIv = I.Num_Niv and E.Num_Apt = I.Num_Apt
  end
  
GO

