GO

CREATE PROCEDURE [dbo].[PR_CriticaItemPDVIT]
@PFlgPolCom       bit,                        -- indica se utiliza politica de comercialização

@PCodEstabe       int,                        -- PDVIT.Cod_Estabe  
@PNumPdv          int,                        -- PDVIT.Cod_Pedido  
@PCodPrd          int,                        -- PDVIT.Cod_Produto
@PTipSai          varchar(1),                 -- PDVIT.Tip_Sai

@PIdPolComIte     int,                        -- PDVIT.Id_PolCom
@PQtdPed          int           output,       -- PDVIT.Qtd_Pedido
@PQtdBon          int,                        -- PDVIT.Qtd_Bonificacao  
@PQtdPrzMax       int           output,       -- PDVIT.Qtd_PrzMax

@PPrcUni          numeric(18,8),              -- PDVIT.Prc_Unitario
@PPerDscLin       numeric(7,4)  output,       -- PDVIT.Per_Desconto
@PPerDscPrz       numeric(7,4)  output,       -- PDVIT.Per_Descon
@PPerDscVis       numeric(7,4)  output,       -- PDVIT.Per_DscVis

@PFatCnvImpFat    integer,                    -- PDVIT.Fat_CnvImpFat
@PQtdImpFat       numeric(18,8) output,       -- PDVIT.Qtd_UniImpFat 
@PPrcUniImpFat    numeric(18,8),              -- PDVIT.Prc_UniImpFat

@PPrcTabBru       numeric(18,8),              -- PDVIT.Prc_TabBru
@PPrcTab          numeric(18,8) output,       -- PDVIT.Prc_Tabela
@PPrcUniLiqPer    numeric(18,8) output,       -- PDVIT.Prc_UniLiqPer
@PPrcMin          numeric(18,8),

@PCodKitPrm       int,                        -- PDVIT.Cod_KitPrm
@PPrcCusMinComMarkup numeric(18,8),           -- PDVIT.Prc_CusMinComMarkup

@PrcPolCom        numeric(18,8) output,       -- PDVIT.Prc_PolCom       --- passar valor atual 
@PQtdPrzPolCom    int           output,       -- PDVIT.Qtd_PrzPolCom    --- passar valor atual 
@PPerDscPolCom    numeric(7,4)  output,       -- PDVIT.Per_DscPolCom    --- passar valor atual 
@PPerDscVisPolCom numeric(7,4)  output,       -- PDVIT.Per_DscVisPolCom --- passar valor atual 

@PFlgGerVerba     bit           output,       -- PDVIT.Flg_Verba
@PVlrVerbaTot     numeric(18,8),              -- ???  se = 0 calcula nesta procedure

@PFlgSnhEsp       bit,                        -- GlobalDM.SenhaEspecial
@PNomUsuSnhEsp    varchar(35),                -- GlobalDM.NomUsuSenhaEspecial

@PFlgBlqQtdPar    int,                        -- bloqueia Qtd Parcial = 0
@PNaoCriConCom    bit,
@PFlgBlqCriPrcVen bit,
@PFlgCriVrb       bit,
@PFlgBlqDscAutIte bit,                        -- bloqueia desconto automatico do item (parametro do Pedido Eletronico)

@PQtdSol          int           output,       -- PDVIT.Qtd_Solicitado').AsInteger
@PQtdAce          int           output,       -- PDVIT.Qtd_Acerto

@PFlgPolPrm       int           output,       -- PDVIT.Flg_PolPrm
@PCodPromoc       int           output,       -- PDVIT.Cod_Promocao

@PCodRej          varchar(3)    output, 
@PDesMsg          varchar(80)   output, 
@PCmp             varchar(20)   output,
@PNomUsuDbq       varchar(35)   output,
@PDesMsgDbq       varchar(80)   output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = cast(GetDate() as Date)

Set @PQtdSol = 0
Set @PQtdAce = 0

Set @PPrcTab       = 0
Set @PPrcUniLiqPer = 0
Set @PCodPromoc    = 0
Set @PFlgPolPrm    = 0

Set @PCodRej    = ''
Set @PDesMsg    = ''
Set @PCmp       = ''
Set @PNomUsuDbq = ''
Set @PDesMsgDbq = ''

if not Exists(Select 1 From PRXES pr Inner Join PRODU p on pr.Cod_Produt = p.Codigo 
              Where pr.Cod_Estabe = @PCodEstabe And pr.Cod_Produt = @PCodPrd)
  begin
    Set @PCmp    = 'EditCodProduto'
    Set @PCodRej = 'PRX'
    Set @PDesMsg = 'Produto Inexistente'
    Return
  end
else
  begin

    Declare @WFlgLicIrr bit,
            @WMsgLicIrr varchar(30),

            @WQtdPrzMaxAux int,           -- somente para passagem de parametro
            @WPerDscPrzAux numeric(7,4),  -- somente para passagem de parametro
            @WPerDscVisAux numeric(7,4),  -- somente para passagem de parametro

            @WPerDscPrz numeric(7,4),
            @WDscEmbPrc numeric(7,4),
            @WDscTotItePdv numeric(7,4),
            @WPerDscPrcPrm numeric(7,4),
            @WPerDscMax numeric(7,4),
            @WPrcUniLiqPdv numeric(18,8),
            @WPrcUniLiqPrm numeric(18,8),
            @WPrcUni numeric(18,8),
            @WVlrTotIte numeric(18,8),
            @WFlgPrdBlq bit,
            @WQtdFisDsp int,
            @WQtdBonCal int,
            @WPerBonifi numeric(18,8),
            @WNomUsu varchar(35),
            @WFlgConFinTabPrc bit = 0,          -- consumidor final com tabea de preços
            @WFlgPrzDscOk bit = 1,
            @WFlgSegue bit = 1,

            @WFlgPromoc    bit,                 -- em promocao
            @WPerDscPromoc numeric(7,4),        -- desc. promocional
            @WPerBonPromoc numeric(7,4),        -- bonif. promocional
            @WPrcUniPromoc numeric(18,8),       -- prc. promocional
            @WQtdMinPromoc int,                 -- qtd.min promocao 
            @WQtdEstPromoc int,                 -- qtd.est promocao
            @WQtdPrzPromoc int,                 -- prazo promocional
            @WDesPromoc varchar(30),
            @WDatEncPromoc smalldatetime,
            @WDatVctLotPromoc smalldatetime,
            @WFlgBlqCtrQtdPromoc bit,
            @WDesMsg varchar(80), 
            @WNumPdvInc int,
            @WFlgCriPrdTabPrc bit,

            @pm_QtdDecPrcItePdv smallint = 4,
            @pm_BlqEstFisNeg bit = 0,
            @pm_FlgTabPrcConFin bit = 0,
            @pm_FlgCtrDscIte bit = 0,
            @pm_PerMaxDscIte numeric(7,4) = 0,
            @pm_FlgBlqSugPrmQtdMin bit = 0,
            @pm_FlgRegPrzPdvExcConCom bit = 0,
            @pm_FlgLimComMaxFab bit = 0,
            @pm_FlgAltConComPdv bit = 0,
            @pm_FlgCriPrcMinCusLiq bit = 0,
            @pm_FlgCriPrcMinCusMedCom bit = 0,
            @pm_FlgCriPrcMinPmz bit = 0,
            @pm_PerAcrCriPrcMinCusLiq numeric(18,4),
            @pm_FlgCotPrcPrd bit,

            @op_TipPrc varchar(1) = 'V',
			@op_FlgOrc bit = 0,
	        @pr_QtdDispon int = 0,
            @pr_QtdPrmDispon int = 0,
            @pr_CodFabric int = 0,
            @pr_CodPromoc int = 0,
            @pr_CodClaTri varchar(4) = '',
            @pr_CtrlVenda varchar(1) = '',
            @pr_CodClassi varchar(3) = '',
            @pr_FlgPolComercMax bit = 0,
            @pr_FlgPrzComercMax bit = 0,
            @pr_PrcCusMed numeric(18,8) = 0,
            @pr_PrcCusMedCom numeric(18,8) = 0,
            @pr_PrcUltEnt numeric(18,8) = 0,
            @pr_PerDscUltEnt numeric(7,4) = 0,
            @pr_PerBonAut numeric(7,4) = 0,
            @pr_PrcCusLiqEnt numeric(18,8) = 0,
            @pr_FlgBlqVen bit = 0,
            @pr_QtdPrzMaxFat int,
            @pr_PerDscMaxPrz numeric(7,4),
            @pr_PerDscMaxVis numeric(7,4),  
            @fb_QtdPrzMax int,
            @fb_PerDscPrz numeric(7,4),
            @fb_PerDscVis numeric(7,4),  

            @pv_CodTipPed varchar(3),  -- 'PDV','COT'
            @pv_TipPrz varchar(1),  -- 'L'inear ou 'F'abricante
            @pv_Status1 varchar(1),
            @pv_Status2 varchar(1),
            @pv_TipSai varchar(1),
            @pv_CodCli int,
            @pv_TipCon varchar(1),
            @pv_CodTabPrc int,
            @pv_IdPolCom int, 
            @pv_CodRegTri int, 
            @pv_CodVdr int, 
            @pv_CodOpe int,
            @pv_TipFat varchar(3), 
            @pv_CodOriPdv varchar(2), 
            @pv_FlgGerPdvBon bit,
            @pv_NumPdvLig int,
            @pv_IdIncFis int,
            @pv_TipGerVrbPdv varchar(1),
            @pv_TipRatBon varchar(1),
            @pv_FlgMrkCusCom bit,
            @pv_QtdPrzPdv int,
            @pv_PerDscPrzPdv numeric(7,4),
            @pv_PerDscVisPdv numeric(7,4),
            @pv_QtdPrzMed int,

            @cl_CodUf varchar(2),
            @cl_CodGrp int, 
            @cl_CodCliPag int,
            @cl_FlgCliEsp bit = 0,
            @cl_QtdPrzMax int = 0, 
            @cl_PerDscVen numeric(7,4) = 0,
            @cl_PerDscComMaxVis numeric(7,4) = 0,

            @pc_TipGerVrbPdv varchar(1),
            @pc_FlgPolPrm bit,
            @pc_FlgMarkupCusCom bit,
            @pc_FlgGerVrbPdv bit,
            @pc_FlgCtrPdvVrbVdr bit,
            @pc_FlgCtrPdvVrbOpe bit,
            @pc_CtrSld varchar(1),
            @pc_PerAcrAutPrc numeric(7,4),
            @pc_PerDscAutPrc numeric(7,4)
            
    -- PDVCB 
    Select @pm_QtdDecPrcItePdv       = IsNull(pa.QtdDecPrcItePdv,0),
	       @pm_BlqEstFisNeg          = IsNull(pm.BlqEstFisNeg,0),
           @pm_FlgTabPrcConFin       = IsNull(pa.FlgTabPrcConFin,0),
           @pm_FlgCtrDscIte          = IsNull(pa.FlgCtrDscIte,0),
           @pm_PerMaxDscIte          = IsNull(pa.PerMaxDscIte,0),
           @pm_FlgLimComMaxFab       = IsNull(pa.FlgLimComMaxFab,0),
           @pm_FlgAltConComPdv       = IsNull(pa.FlgAltConComPdv,0),
           @pm_FlgBlqSugPrmQtdMin    = IsNull(pa.FlgBlqSugPrmQtdMin,0),
           @pm_FlgRegPrzPdvExcConCom = IsNull(pa.FlgRegPrzPdvExcConCom,0),
           @pm_FlgCriPrcMinCusLiq    = IsNull(pa.FlgCriPrcMinCusLiq,0),
           @pm_FlgCriPrcMinCusMedCom = IsNull(pa.FlgCriPrcMinCusMedCom,0),
           @pm_FlgCriPrcMinPmz       = IsNull(pa.FlgCriPrcMinPmz,0),
           @pm_PerAcrCriPrcMinCusLiq = IsNull(pa.PerAcrCriPrcMinCusLiq,0),
		   @pm_FlgCotPrcPrd          = IsNull(pa.FlgCotPrcPrd,0),

           @pv_CodTipPed       = Case When pv.Tip_Pedido = 'C' then 'COT' Else'PDV' End,
	       @pv_Status1         = IsNull(pv.Status1,''),
           @pv_Status2         = IsNull(pv.Status2,''),
           @pv_TipSai          = IsNull(pv.Tip_SaiPdv,'V'),
	       @pv_CodCli          = IsNull(pv.Cod_Cliente,0),
           @pv_TipCon          = IsNull(pv.Tip_Consumidor,''),
           @pv_CodTabPrc       = IsNull(pv.Cod_TabPrc,0),
           @pv_IdPolCom        = IsNull(pv.Id_PolCom,0), 
           @pv_CodRegTri       = IsNull(pv.Cod_RegTri,0), 
           @pv_CodVdr          = IsNull(pv.Cod_Vendedor,0), 
           @pv_CodOpe          = IsNull(pv.Cod_VendTlmkt,0),
           @pv_TipFat          = IsNull(pv.Tip_Faturamento,''),
           @pv_CodOriPdv       = IsNull(pv.Cod_OrigemPdv,''),
           @pv_TipPrz          = Substring(IsNull(pv.Cod_OrigemPdv,''),2,1),
           @pv_FlgGerPdvBon    = IsNull(pv.Flg_GerPdvBon,0),
           @pv_NumPdvLig       = IsNull(pv.Num_PdvLig,0),
           @pv_IdIncFis        = IsNull(pv.Id_IncFis,0),
           @pv_TipGerVrbPdv    = dbo.FN_TipGerVrbPdv(pv.Id_PolCom),
           @pv_TipRatBon       = IsNull(pv.Tip_RatBon,''),
           @pv_FlgMrkCusCom    = IsNull(pv.Flg_MarkupCusCom,0),
           @pv_QtdPrzPdv       = IsNull(pv.Qtd_Prz,0),
           @pv_PerDscPrzPdv    = IsNull(pv.Per_DscPrz,0),
           @pv_PerDscVisPdv    = IsNull(pv.Per_DscVis,0),
           @pv_QtdPrzMed       = cast(IsNull(pv.Qtd_PrzMed,0) as int),

           @cl_CodUf           = IsNull(cl.Cod_Estado,''),
           @cl_CodGrp          = IsNull(cl.Cod_GrpCli,0), 
           @cl_CodCliPag       = IsNull(cl.Cod_CliPag,0),
           @cl_FlgCliEsp       = IsNull(cl.Flag_ClienteEsp,0),
           @cl_QtdPrzMax       = IsNull(cl.Qtd_PrzMax,0),  
           @cl_PerDscVen       = IsNull(cl.Per_DscVen,0),
           @cl_PerDscComMaxVis = IsNull(cl.Per_DscComMaxVis,0),

           @op_TipPrc          = IsNull(op.Tip_Prc,'V'),
           @op_FlgOrc          = Case
                                   When IsNull(op.Cod_CfoNorInt,0) = 0 then 1
                                   Else 0 
                                 End
      From PDVCB pv
           Left  Join CLIEN cl on pv.Cod_Cliente = cl.Codigo
           Left  Join TPOPE op on pv.Tip_Faturamento = op.Cod_Ope 
           Inner Join PARAM pa on pv.Cod_Estabe = pa.Cod_Estabe 
           Inner Join PMEST pm on pv.Cod_Estabe = pm.Cod_Estabe 
      Where pv.Cod_Estabe = @PCodEstabe
      And pv.Numero = @PNumPdv 

    -- PRODU PRXES
    Select @pr_QtdDispon       = dbo.FN_EstoqueDisponivelPrd(pr.Cod_Estabe,pr.Cod_Produt), 
	       @pr_QtdPrmDispon    = IsNull(pr.Qtd_PrmDispon,0), 
		   @pr_CodClaTri       = IsNull(pr.Cod_ClaTri,''), 
		   @pr_FlgBlqVen       = IsNull(pr.Flg_BlqVen,0), 
		   @pr_PrcCusMed       = IsNull(pr.Prc_CusMed,0),
		   @pr_PrcCusMedCom    = IsNull(pr.Prc_CusMedCom,0),
           @pr_PrcCusLiqEnt    = IsNull(pr.Prc_CusLiqEnt,0),
           @pr_PrcUltEnt       = IsNull(pr.Prc_UltEnt,0),
           @pr_PerDscUltEnt    = IsNull(pr.Per_DscUltEnt,0),
           @pr_PerBonAut       = IsNull(pr.Per_BonAut,0),
           @pr_QtdPrzMaxFat    = IsNull(pr.Qtd_PrzMaxFat,0), 
           @pr_PerDscMaxPrz    = IsNull(pr.Per_DscMaxPrz,0),
           @pr_PerDscMaxVis    = IsNull(pr.Per_DscMaxVis,0),
           @pr_CodFabric       = IsNull(p.Cod_Fabricante,0), 
           @pr_CodPromoc       = IsNull(p.Cod_Promocao,0),
		   @pr_CtrlVenda       = IsNull(p.Ctrl_Venda,''), 
		   @pr_CodClassi       = IsNull(p.Cod_Classif,''), 
           @pr_FlgPolComercMax = IsNull(p.Flg_PolComercMax,0),
           @pr_FlgPrzComercMax = IsNull(p.Flg_PrzComercMax,0),

           @fb_QtdPrzMax       = IsNull(fb.Qtd_PrzMaxFat,0), 
           @fb_PerDscPrz       = IsNull(fb.Per_DscMaxPrz,0),
           @fb_PerDscVis       = IsNull(fb.Per_DscMaxVis,0)
      From PRXES pr 
           Inner Join PRODU p on pr.Cod_Produt = p.Codigo 
           Inner Join FABRI fb on p.Cod_Fabricante = fb.Codigo
      Where pr.Cod_Estabe = @PCodEstabe
      And pr.Cod_Produt = @PCodPrd

  Set @WNomUsu = dbo.FN_UsuarioInfarma()

  if @fb_PerDscVis < @fb_PerDscPrz 
    Set @fb_PerDscVis = @fb_PerDscPrz

  if @op_TipPrc = '' Set @op_TipPrc = 'V'

  -- registra a qtde solicitada e zera a de acerto
  Set @PQtdSol = @PQtdPed + @PQtdBon
  Set @PQtdAce = 0

  -- POCOM
  -- bloqueia estoque fisico negativo
  if (@pm_BlqEstFisNeg = 1) and (@op_FlgOrc = 0)
    begin
      Set @WQtdFisDsp = dbo.FN_SldFiscalDisponPrd(@PCodEstabe,@PCodPrd)
      if @PQtdPed > @WQtdFisDsp
        begin
          if @WQtdFisDsp < 0 Set @WQtdFisDsp = 0
          Set @PQtdPed = @WQtdFisDsp
        end
    end

  -- POCOM
  -- produto controlado bloqueado p/ lic.saude irregular
  if @pv_CodCli > 0
    if CharIndex(@pr_CtrlVenda,';C;E;P;') <> 0 
      begin
        -- licença da saúde
        Exec PR_AnalisaLicencaCliente @pv_CodTipPed, 'SAUDE', @pv_CodCli, @WFlgLicIrr output, @WMsgLicIrr output
        if @WFlgLicIrr = 1
          begin
            Set @PCmp = 'EditCodProduto'
            Set @PCodRej = '344'
            Set @PDesMsg = 'Produto controlado bloqueado p/ Lic.Saude Irregular'
            Return
          end

        Exec PR_AnalisaLicencaCliente @pv_CodTipPed, 'ANVISA', @pv_CodCli, @WFlgLicIrr output, @WMsgLicIrr output
        if @WFlgLicIrr = 1
          begin
            Set @PCmp    = 'EditCodProduto'
            Set @PCodRej = '344'
            Set @PDesMsg = 'Produto controlado bloqueado p/ Lic.Anvisa irregular'
            Return 
          end
      end

  -- POCOM
  if @pr_FlgBlqVen = 1
    begin
      Set @PCmp    = 'EditCodProduto'
      Set @PCodRej = 'PRB'
      Set @PDesMsg = 'Produto bloqueado para vendas'
      Return
    end

  -- critica se item "incentivado"
  if (@pv_IdIncFis > 0) and
     Exists(Select 1 From IFXGI Where Id_IncFis = @pv_IdIncFis) and
     ( (Select dbo.FN_ProdutoIncentivado(@PCodEstabe, @PCodPrd, @pv_IdIncFis)) = 0 )		 	   
    begin
      Set @PCmp    = 'EditCodProduto'
      Set @PCodRej = 'PRB'
      Set @PDesMsg = 'Produto bloqueado para este pedido(incentivo)'
      Return
    end

  -- critica pedido desdobrado incentivado: só aceita itens não incentivados
  if Exists(Select 1
              From PDVCB
             Where Cod_Estabe = @PCodEstabe 
               And Numero = @PNumPdv
               And Exists(Select Numero From PDVCB 
                           Where Cod_Estabe = @PCodEstabe 
                             And Num_PdvPai = @PNumPdv 
                             And Id_IncFis > 0) 
               And (Select dbo.FN_ProdutoIncentivado(@PCodEstabe, @PCodPrd, @pv_IdIncFis)) = 1 )							 
    begin
      Set @WNumPdvInc = (Select Numero From PDVCB
                          Where Cod_Estabe = @PCodEstabe 
                            And Num_PdvPai = @PNumPdv 
                            And Id_IncFis > 0)
      Set @PCmp    = 'EditCodProduto'
      Set @PCodRej = 'PRB'
      Set @PDesMsg = 'Produto incentivado bloqueado para este pedido. Incluir no pedido('+Cast(@WNumPdvInc as varchar)+') '
      Return
    end

  -- POCOM
  if @PQtdPed <= 0 
    begin
      Set @PCmp    = 'EditQtdPedido'
      Set @PCodRej = 'QTX'
      Set @PDesMsg = 'Quantidade do Pedido inválida'
      Return
    end

  -- POCOM
  if @PQtdBon < 0
    begin
      Set @PCmp    = 'EditQtdBonificacao'
      Set @PCodRej = 'QTX'
      Set @PDesMsg = 'Quantidade de Bonificação inválida'
      Return
    end

  -- POCOM
  if @PQtdBon > @PQtdPed
    begin
      Set @PCmp    = 'EditQtdBonificacao'
      Set @PCodRej = 'QTX'
      Set @PDesMsg = 'Quantidade de Bonificação inválida'
      Return
    end

  -- POCOM
  if (@PQtdBon > 0) and
     ((@PQtdPed + @PQtdBon) > @pr_QtdDispon)
    begin
      Set @PCmp    = 'EditQtdPedido'
      if @pr_QtdDispon > 0
        Set @PCodRej = 'ES-'
      else
        Set @PCodRej = 'ES0'
      Set @PDesMsg = '(Quantidade + Bonificação) inválida'
      Return
    end

  -- POCOM
  if (@pv_FlgGerPdvBon = 1) and (@PQtdBon > 0) 
    begin
      -- zera descontos
      Set @PPerDscLin = 0
      Set @PPerDscPrz = 0
      Set @PPerDscVis = 0
      if (@pv_NumPdvLig > 0) and
         (Substring(@pv_CodOriPdv,1,1) = 'D') 
        begin
          Set @PCmp    = 'EditQtdBonificacao'
          Set @PCodRej = 'QTX'
          Set @PDesMsg = 'Quantidade de Bonificação inválida para Pedido Desdobrado por Bonificação'
          Return
        end

      if Exists(Select 1 From PRBON Where Cod_Produt = @PCodPrd And Qtd_Minima <= @PQtdPed)  -- 2
        begin
           Select top 1 @WPerBonifi = IsNull(Per_Bonifi,0) 
             From PRBON 
             Where Cod_Produt = @PCodPrd
             And Qtd_Minima <= @PQtdPed
             Order by Qtd_Minima desc 

          Set @WQtdBonCal = 0
          -- Sintaxe: round(número, casa-decimal, 1) -- 1 indica trunc ao invés de round
          Set @WQtdBonCal = round(@PQtdPed*@WPerBonifi/100+0.05, 0, 1)

          if @PQtdBon > @WQtdBonCal 
            begin
              Set @PCmp    = 'EditQtdBonificacao'
              Set @PCodRej = 'QTX'
              Set @PDesMsg = 'Quantidade de Bonificação maior que o permitido ('+cast(@WQtdBonCal as varchar)+')'
              Return
            end
        end

    end  -- if (@pv_FlgGerPdvBon = 1) and (@PQtdBon > 0)

  -- desconto a vista nao pode ser menor que desc. a prazo
  if @PPerDscVis < @PPerDscPrz
    Set @PPerDscVis = @PPerDscPrz

  -- Verifica se bloqueia o item se tiver a quantidade inferior a pedida.
  if @PFlgBlqQtdPar = 1
    begin
      if (@PQtdPed + @PQtdBon) > @pr_QtdDispon
        begin
          Set @PCmp    = 'EditQtdPedido'
          if @pr_QtdDispon > 0 
            Set @PCodRej = 'ES-'
          else
            Set @PCodRej = 'ES0'
          Set @PDesMsg = 'Estoque Insuficiente para atender qtd.total'
        end
    end

  -- desconto linear - 1
  if (@PPerDscLin < 0) or (@PPerDscLin > 100)
    begin
      Set @PCmp    = 'EditPerDesconto'
      Set @PCodRej = 'DCX'
      Set @PDesMsg = 'Desconto inválido'
      Return
    end

  -- POCOM
  if (@PPerDscVis < 0) or (@PPerDscVis > 100)
    begin
      Set @PCmp    = 'EditPerDscVis'
      Set @PCodRej = 'DCX'
      Set @PDesMsg = 'Desconto inválido'
      Return
    end

  -- POCOM
  if (@PPerDscPrz < 0) or (@PPerDscPrz > 100)
    begin
      Set @PCmp    = 'EditPerDesconto'
      Set @PCodRej = 'DCX'
      Set @PDesMsg = 'Desconto inválido'
      Return
    end

  -- POCOM
  if @pv_CodRegTri <= 0 
    begin
      Set @PCmp    = 'EditCodProduto'
      Set @PCodRej = 'CAD'
      Set @PDesMsg = 'Região Tributária inválida'
      Return
    end
  else
  if not Exists(Select Cod_RegTri From RTXCT 
                  Where Cod_RegTri = @pv_CodRegTri
                  And Cod_ClaTri = @pr_CodClaTri)
    begin
      Set @PCmp    = 'EditCodProduto'
      Set @PCodRej = 'CAD'
      Set @PDesMsg = 'Regime de Tributação não definido para este produto'
      Return
    end

  -- POCOM
  if @PPrcUni <= 0
    begin
      Set @PCmp    = 'EditPrcUnitario'
      Set @PCodRej = 'PUX'
      Set @PDesMsg = 'Preço Unitário inválido'
      Return
    end

  -- calcula preco unitario liquido
  if @PFlgPolCom = 1
    Set @WPerDscPrz = @PPerDscPrz
  else
    -- prazo linear
    if @pv_TipPrz = 'L' 
      Set @WPerDscPrz = @PPerDscLin
    else
      Set @WPerDscPrz = @PPerDscPrz

  Set @WPrcUniLiqPdv = @PPrcUni*(1-@WPerDscPrz/100)

  -- REDEFINE PREÇO DE TABELA  30/06/2011
  -- calcula preco minimo tabela de precos liquido
  -- poe na memoria campos da politica do item que poderao ser utilizados
  Set @pc_PerAcrAutPrc = 0
  Set @pc_PerDscAutPrc = 0
  Set @pc_FlgPolPrm    = 0
  Set @pc_FlgMarkupCusCom = 0
  Set @pc_TipGerVrbPdv = ''

  Set @PFlgGerVerba = 0

  Set @pc_FlgGerVrbPdv = 0
  Set @pc_FlgCtrPdvVrbVdr = 0
  Set @pc_FlgCtrPdvVrbOpe = 0
  Set @pc_CtrSld       = 'V'


  Set @WFlgPromoc    = 0
  Set @WPerDscPromoc = 0
  Set @WPrcUniPromoc = 0
  Set @WQtdMinPromoc = 0
  Set @WQtdEstPromoc = 0
  Set @WQtdPrzPromoc = 0
  Set @WDesPromoc    = ''
  Set @WDatEncPromoc = 0
  Set @WDatVctLotPromoc = 0
  Set @WFlgBlqCtrQtdPromoc = 0

  -- em promocao
  if @PFlgPolCom = 0
    begin
      -- promocao
      Exec PR_ProdutoEmPromocao @PCodEstabe, @pr_CodPromoc, @PCodPrd, @cl_CodUf,
                                @WFlgPromoc output, @WDesPromoc output, @WDatEncPromoc output, @WDatVctLotPromoc output, @WQtdMinPromoc output,
                                @WQtdPrzPromoc output, @WPerDscPromoc output, @WPerBonPromoc output, @WPrcUniPromoc output, @WFlgBlqCtrQtdPromoc output

      if @WFlgPromoc = 1
        begin
          if @WFlgBlqCtrQtdPromoc = 1
            Set @WQtdEstPromoc = @pr_QtdDispon
          else
            Set @WQtdEstPromoc = @pr_QtdPrmDispon
        end
    end

  if @PFlgPolCom = 1
    begin
  -- POCOM
      -- verifica politica de comercializacao
      if @pv_IdPolCom = 0
        begin
          Set @PCmp    = 'EditCodProduto'
          Set @PCodRej = 'PCX'
          Set @PDesMsg = 'Não existe Política de Comercialização definida para este pedido'
          Return
        end

      if @PIdPolComIte = 0 
        begin
          Set @PCmp    = 'EditCodProduto'
          Set @PCodRej = 'PCX'
          Set @PDesMsg = 'Não existe Política de Comercialização definida para este produto'
          Return
        end

      if not Exists(Select 1 From POCOM WHERE Id_PolCom = @PIdPolComIte)
        begin
          Set @PCmp    = 'EditCodProduto'
          Set @PCodRej = 'PCX'
          Set @PDesMsg = 'Política de Comercialização inexistente'
          Return
        end

      if dbo.FN_PolComPrdValida(@PIdPolComIte,@PCodPrd,@PQtdPed,@Date) = 0
        begin
          Set @PCmp    = 'EditCodProduto'
          Set @PCodRej = 'PCX'
          Set @PDesMsg = 'Não existe Política de Comercialização definida para este produto'
          Return
        end

      if (@PIdPolComIte > 0) and
         Exists(Select 1 From POCOM WHERE Id_PolCom = @PIdPolComIte)
        begin
          Select --@pv_CodTabPrc    = IsNull(Cod_TabPrc,0), 
                 @pc_PerAcrAutPrc = IsNull(Per_AcrAutPrc,0), 
                 @pc_PerDscAutPrc = IsNull(Per_DscAutPrc,0), 
                 @pc_TipGerVrbPdv = dbo.FN_TipGerVrbPdv(Id_PolCom),
                 @pc_FlgPolPrm    = IsNull(Flg_BlqCli,0), 
                 @pc_FlgMarkupCusCom = Case When (IsNull(Flg_NegDsc,0) = 1) then IsNull(Flg_MarkupCusCom,0) Else 0  End, 
                 @pc_FlgGerVrbPdv    = Case When (IsNull(Flg_NegDsc,0) = 1) then IsNull(Flg_GerVrbPdv,0)    Else 0  End,  -- gera e usa verba somente no pedido
                 @PFlgGerVerba       = Case When (IsNull(Flg_NegDsc,0) = 1) and ((IsNull(Flg_AcuVrbPos,0) = 1) or (IsNull(Flg_AcuVrbNeg,0) = 1)) then 1
                                            Else 0 
                                       End,
                 @pc_FlgCtrPdvVrbVdr = IsNull(Flg_CtrPdvVrbVdr,0),
                 @pc_FlgCtrPdvVrbOpe = IsNull(Flg_CtrPdvVrbOpe,0),
                 @pc_CtrSld          = IsNull(Controle_Saldo,'V')
            From POCOM 
            Where Id_PolCom = @PIdPolComIte
        end
    end  -- if @PFlgPolCom = 1

  Set @WPerDscMax = 0  -- desconto maximo permitido

  -- POCOM
  Set @WFlgCriPrdTabPrc = 1 -- critica produto em tabela de preços TPXPR
  if (@pv_CodTipPed = 'COT') and (@pm_FlgCotPrcPrd = 1) 
    Set @WFlgCriPrdTabPrc = 0


  if (@PFlgPolCom = 0) and   -- item atendido por condições da politica se não existir na tabela de preços
     (@pv_CodTabPrc > 0) and (@WFlgCriPrdTabPrc = 1) and
     not Exists(Select 1 
                  From TPXPR it
                       Inner Join TBPRC cb on (it.Cod_Estabe = cb.Cod_Estabe and it.Cod_TabPrc = cb.Cod_TabPrc)
                 Where it.Cod_TabPrc = @pv_CodTabPrc 
                   And it.Cod_Produt = @PCodPrd
                   And ((cb.Cod_Estabe = @PCodEstabe) or (cb.Flg_AllEstabe = 1)))
    begin
      Set @PCodRej = 'CAD';
      Set @PCmp    = 'EditCodProduto';
      Set @PDesMsg = 'Produto não está relacionado para venda nesta tabela de preços';
      Return
    end

  -- Pr. Tabela
  Set @PPrcTab = dbo.FN_PrecoTabelaProduto(@pv_CodCli, @PCodEstabe, @PCodPrd, @PIdPolComIte, @pv_CodTabPrc, @op_FlgOrc, @PFlgBlqDscAutIte)
 
  -- se controla desconto no item (somente para preços de Venda) -- 1
  if (CharIndex(@op_TipPrc,';M;C;E;') = 0) and (@PFlgPolCom = 0)
    begin
      if @pv_TipPrz = 'L'
        begin
          Set @WPerDscMax = @fb_PerDscVis
          if not @pm_FlgCtrDscIte = 0
 			if @pm_PerMaxDscIte > 0 
              if @pm_PerMaxDscIte > @WPerDscMax
                Set @WPerDscMax = @pm_PerMaxDscIte
              else
                Set @WPerDscMax = @WPerDscMax
            else
              Set @WPerDscMax = 99
        end
      else
        begin
          -- cond. comercializacao padrao
          Exec PR_PdvitConComDef @PCodEstabe, @PCodPrd, @pv_CodCli, @pv_QtdPrzPdv, @pv_PerDscPrzPdv, @pv_PerDscVisPdv,
                                 @WQtdPrzMaxAux output, @WPerDscPrzAux output, @WPerDscVisAux output
          if @WPerDscPrzAux > @WPerDscMax
            Set @WPerDscMax = @WPerDscPrzAux
        end
    end


  -- POCOM
  -- calcula desconto embutido no preco p/ obter desconto real
  Set @WDscEmbPrc = 0
  if Round(@PPrcUni,4) < Round(@PPrcTab,4)
    Set @WDscEmbPrc = (@PPrcTab-@PPrcUni)*100/@PPrcTab
  if (@WPerDscPrz + @WDscEmbPrc) > 0
    Set @WDscTotItePdv = @WPerDscPrz + @WDscEmbPrc - (@WPerDscPrz*@WDscEmbPrc/100)
  else
    Set @WDscTotItePdv = 0

  -- calcula preco minimo promocional liquido  -- 1
  Set @WPrcUniLiqPrm = @WPrcUniPromoc
  if @WPerDscPromoc > 0
    Set @WPrcUniLiqPrm = @PPrcTab*(1- @WPerDscPromoc/100)
  Set @WPerDscPrcPrm = 0
  if (@WPrcUniPromoc > 0) and (@PPrcTab > 0)
    if @PPrcTab > @WPrcUniPromoc
      Set @WPerDscPrcPrm = (@PPrcTab-@WPrcUniPromoc)*100/@PPrcTab

-- POCOM
  -- pr.minimo liquido permitido
  if @op_TipPrc = 'V'
    Set @PPrcUniLiqPer = @PPrcTab*(1-@WPerDscMax/100)
  else
  if @op_TipPrc = 'M'
    if @pr_PrcCusMedCom > 0
      Set @PPrcUniLiqPer = @pr_PrcCusMedCom   -- custo medio comercial
    else
      Set @PPrcUniLiqPer = @pr_PrcCusMed
  else
  if @op_TipPrc = 'C'
    Set @PPrcUniLiqPer = @pr_PrcCusLiqEnt
  else
  if @op_TipPrc = 'E'
    Set @PPrcUniLiqPer = @pr_PrcUltEnt*(1-@pr_PerDscUltEnt/100)
  else
    Set @PPrcUniLiqPer = @PPrcTab*(1-@WPerDscMax/100)

  -- ver descontos promocionais apos calculo do pr.minimo permitido
  if  @WPerDscPromoc > @WPerDscMax 
    Set @WPerDscMax =  @WPerDscPromoc
  if @WPerDscPrcPrm > @WPerDscMax
    Set @WPerDscMax = @WPerDscPrcPrm

  -- POCOM
  if @PQtdPrzMax < 0 
    begin
      Set @PCmp    = 'EditQtdPrz'
      Set @PCodRej = 'PZX'
      Set @PDesMsg = 'Prazo inválido'
      Return
    end

  -- prazo fabricante
  if (@pv_CodCli > 0) and
     (@pv_TipPrz = 'F') and (@PQtdPrzMax = 0) 
    begin
      Set @PCmp    = 'EditQtdPrz'
      Set @PCodRej = 'PZX'
      Set @PDesMsg = 'Prazo inválido'
      Return
    end

  -- verifica se venda foi da promocao
  Set @PFlgPolPrm = @pc_FlgPolPrm
  Set @PCodPromoc = 0
  if @WFlgPromoc = 1
    begin
      if @PQtdBon > 0 
        Set @PCodPromoc = @pr_CodPromoc
      else
      if @WPrcUniLiqPrm > 0 
        if (Round(@WPrcUniLiqPdv,4) >= Round(@WPrcUniLiqPrm,4)) and
           (Round(@WPrcUniLiqPdv,4) < Round(@PPrcTab,4)) and
           (Round(@WPrcUniLiqPdv,4) <= Round(@PPrcUniLiqPer,4))
          Set @PCodPromoc = @pr_CodPromoc
    end

  -- é consumidor final e utiliza tab. precos
  Set @WFlgConFinTabPrc = 0

------------------------------------------------------------------------------------------------------------------------------------------------
  if @PFlgPolCom = 0
    begin
      if (@pm_FlgTabPrcConFin = 1) and (@pv_TipCon  = 'F')
        Set @WFlgConFinTabPrc = 1

      if @WFlgConFinTabPrc = 1
        if @PPrcTab <= 0
          begin
            Set @PCmp    = 'EditCodProduto'
            Set @PCodRej = 'CAD'
            Set @PDesMsg = 'Preço de Venda/Tabela inválido'
            Return
          end

      if @PQtdBon > 0 
        begin

          if @PPerDscLin > 0   -- prazo linear
            begin
              Set @PDesMsg ='Bonificação/Desconto inválido (mutuamente exclusivos)'
              if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1))     -- senha especial ou nao critica condicoes de comercializacao
                begin
                  Set @PCmp    = 'EditQtdBonificacao'
                  Set @PCodRej = 'DCX'
                  Return
                end
              else
                begin
                  if (@PFlgSnhEsp = 1) 
                    Set @PNomUsuDbq = @PNomUsuSnhEsp
                  else
                    Set @PNomUsuDbq = @WNomUsu
                  Set @PDesMsgDbq = @PDesMsg
                end
            end
  
          if (@PPerDscPrz > 0) or (@PPerDscVis > 0) -- prazo fabricante
            begin
              Set @PDesMsg ='Bonificação/Desconto inválido (mutuamente exclusivos)'
              if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1))   -- senha especial ou nao critica condicoes de comercializacao
                begin
                  Set @PCodRej = 'QTX'
                  Set @PCmp    = 'EditQtdBonificacao'
                  Return
                end
              else
                begin
                  if (@PFlgSnhEsp = 1) 
                    Set @PNomUsuDbq = @PNomUsuSnhEsp
                  else
                    Set @PNomUsuDbq = @WNomUsu
                  Set @PDesMsgDbq = @PDesMsg
                end
            end

          if (@pr_PerBonAut > 0) and
             (@PQtdBon > round(@PQtdPed*@pr_PerBonAut/100+0.05, 0, 1)) 
            begin
              Set @PDesMsg ='Bonificação maior que a permitida'
              if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1)) 
                begin
                  Set @PCodRej = 'QTX'
                  Set @PCmp    = 'EditQtdBonificacao'
                  Return
                end
              else
                begin
                  if (@PFlgSnhEsp = 1) 
                    Set @PNomUsuDbq = @PNomUsuSnhEsp
                  else
                    Set @PNomUsuDbq = @WNomUsu
                  Set @PDesMsgDbq = @PDesMsg
                end
            end
          else
            if (@WFlgPromoc = 0) and
               (@PQtdBon > round(@PQtdPed*@pr_PerBonAut/100+0.05, 0, 1)) 
              begin
                Set @PDesMsg ='Bonificação maior que a permitida'
                if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1)) 
                  begin
                    Set @PCodRej = 'QTX'
                    Set @PCmp    = 'EditQtdBonificacao'
                    Return
                  end
                else
                  begin
                    if (@PFlgSnhEsp = 1) 
                      Set @PNomUsuDbq = @PNomUsuSnhEsp
                    else
                      Set @PNomUsuDbq = @WNomUsu
                    Set @PDesMsgDbq = @PDesMsg
                  end
              end
        end  -- if @PQtdBon > 0 
    
      -- prazo linear  
      if @pv_TipPrz = 'L' 
        begin
          -- se controla desconto no item (somente para preços de Venda)
          if CharIndex(@op_TipPrc,';M;C;E;') = 0 
            if (@pm_FlgCtrDscIte = 1) and (@PFlgBlqCriPrcVen = 0)
			  begin
                if (Round(@WDscTotItePdv*100,0) > Round(@WPerDscMax*100,0)) and (@pv_CodTabPrc = 0) 
                  if (Abs(Round(@WDscTotItePdv*100,0) - Round(@WPerDscMax*100,0)) > 1) 
                    begin
                      Set @PDesMsg ='Desconto ('+cast(@WDscTotItePdv as varchar)+') maior que o permitido ('+cast(@WPerDscMax as varchar)+')'
                      if not ((@PFlgSnhEsp = 1)  or (@PNaoCriConCom = 1)) 
                        begin
                          if @PPerDscLin > 0 
                            begin
                              Set @PCmp    = 'EditPerDesconto'
                              Set @PCodRej = 'DC+'
                            end
                          else
                            begin
                              Set @PCmp    = 'EditPrcUnitario'
                              Set @PCodRej = 'PU-'
                            end
                          Return
                        end
                      else
                        begin
                          if (@PFlgSnhEsp = 1) 
                            Set @PNomUsuDbq = @PNomUsuSnhEsp
                          else
                            Set @PNomUsuDbq = @WNomUsu
                          Set @PDesMsgDbq = @PDesMsg
                        end
                    end
              end
            else
              if @pm_PerMaxDscIte > 0 
                if (Round(@WDscTotItePdv*100,0) > Round(@WPerDscMax*100,0)) and (@pv_CodTabPrc = 0) 
                  if (Abs(Round(@WDscTotItePdv*100,0) - Round(@WPerDscMax*100,0)) > 1) 
                    begin
                      Set @PDesMsg ='Desconto ('+cast(@WDscTotItePdv as varchar)+') maior que o permitido ('+cast(@WPerDscMax as varchar)+')'
                      if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1)) 
                        begin
                          if @PPerDscLin > 0 
                            begin
                              Set @PCmp    = 'EditPerDesconto'
                              Set @PCodRej = 'DC+'
                            end
                          else
                            begin
                              Set @PCmp    = 'EditPrcUnitario'
                              Set @PCodRej = 'PU-'
                            end
                          Return
                        end
                      else
                        begin
                          if (@PFlgSnhEsp = 1) 
                            Set @PNomUsuDbq = @PNomUsuSnhEsp
                          else
                            Set @PNomUsuDbq = @WNomUsu
                          Set @PDesMsgDbq = @PDesMsg
                        end
                    end

        end  -- if @pv_TipPrz = 'L' 
      else
      -- Prazo Fabricante
      if @pv_TipPrz = 'F' 
        begin

          -- condicoes de comercializacao/ somente para vendas
          Set @WQtdPrzMaxAux = @pv_QtdPrzPdv
          Set @WPerDscPrzAux = @pv_PerDscPrzPdv
          Set @WPerDscVisAux = @pv_PerDscVisPdv

          Set @WFlgPrzDscOk = 1
          Set @WFlgSegue = 1

          if (CharIndex(@op_TipPrc,';M;C;E;') = 0) and (@pv_CodCli > 0) 
            begin
              -- ver se existe politica de comercializacao geral no produto
              if @pr_FlgPolComercMax = 1
                begin
                  Set @WFlgSegue = 0

                  -- descontos
                  Set @WQtdPrzMaxAux = Case 
                                         When (@pm_FlgRegPrzPdvExcConCom = 0) and (@pr_FlgPrzComercMax = 1) then @pr_QtdPrzMaxFat
                                         Else @WQtdPrzMaxAux 
                                       End
                  Set @WPerDscPrzAux = @pr_PerDscMaxPrz
                  Set @WPerDscVisAux = @pr_PerDscMaxVis 

                  -- prazo
				  if @pr_FlgPrzComercMax = 1
                    begin
                      if (@PQtdPrzMax <= @WQtdPrzMaxAux) and
                         (@PPerDscPrz <= @WPerDscPrzAux) and
                         (@PPerDscVis <= @WPerDscVisAux) 
                        Set @WFlgPrzDscOk = 1
                      else
                        begin
                          Set @PDesMsg ='Prazo/Desconto Diferenciado do Produto inválido para este produto'
                          if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1)) 
                            Set @WFlgPrzDscOk = 0
                          else
                            begin
                              if (@PFlgSnhEsp = 1) 
                                Set @PNomUsuDbq = @PNomUsuSnhEsp
                              else
                                Set @PNomUsuDbq = @WNomUsu
                              Set @PDesMsgDbq = @PDesMsg
                            end
                        end
                    end
                  else -- @pr_FlgPrzComercMax = 1
                    begin
                      -- pega prazo diferenciado do fabricante para o cliente
                      if Exists(Select 1 From CLXFB Where Cod_CliPag = @cl_CodCliPag And Cod_Fabric = @pr_CodFabric)
                        begin
                          Select @WQtdPrzMaxAux = Case 
                                                    When (@pm_FlgRegPrzPdvExcConCom = 0) then IsNull(Qtd_PrzMax,0)
                                                    Else @WQtdPrzMaxAux 
                                                  End
                            From CLXFB 
                            Where Cod_CliPag = @cl_CodCliPag 
                            And Cod_Fabric = @pr_CodFabric 

                          if (@PQtdPrzMax <= @WQtdPrzMaxAux) and
                             (@PPerDscPrz <= @WPerDscPrzAux) and
                             (@PPerDscVis <= @WPerDscVisAux) 
                            Set @WFlgPrzDscOk = 1
                          else
                            begin
                              Set @PDesMsg ='Prazo/Desconto Diferenciado do Fabricante inválido para este cliente'
                              if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1)) 
                                Set @WFlgPrzDscOk = 0
                              else
                                begin
                                  if (@PFlgSnhEsp = 1) 
                                    Set @PNomUsuDbq = @PNomUsuSnhEsp
                                  else
                                    Set @PNomUsuDbq = @WNomUsu
                                  Set @PDesMsgDbq = @PDesMsg
                                end
                            end
                        end
                      else
                      -- pega prazo do cliente
                      if @cl_FlgCliEsp = 1 
                        begin
                          if @pm_FlgRegPrzPdvExcConCom = 0
                            Set @WQtdPrzMaxAux = @cl_QtdPrzMax

                          if (@PQtdPrzMax <= @WQtdPrzMaxAux) and
                             (@PPerDscPrz <= @WPerDscPrzAux) and
                             (@PPerDscVis <= @WPerDscVisAux) 
                            Set @WFlgPrzDscOk = 1
                          else
                            begin
                              Set @PDesMsg ='Prazo/Desconto inválido para cliente especial'
                              if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1)) 
                                Set @WFlgPrzDscOk = 0
                              else
                                begin
                                  if (@PFlgSnhEsp = 1) 
                                    Set @PNomUsuDbq = @PNomUsuSnhEsp
                                  else
                                    Set @PNomUsuDbq = @WNomUsu
                                  Set @PDesMsgDbq = @PDesMsg
                                end
                            end
                        end
                      else
                        begin
                          -- pega o prazo diferenciado do fabricante para o grupo
                          if Exists(Select 1 From GCXFB Where Cod_GrpCli = @cl_CodGrp And Cod_Fabric = @pr_CodFabric) 
                            begin
                              Select @WQtdPrzMaxAux = Case 
                                                        When (@pm_FlgRegPrzPdvExcConCom = 0) then IsNull(Qtd_PrzMax,0)
                                                        Else @WQtdPrzMaxAux 
                                                      End
                                From GCXFB 
                                Where Cod_GrpCli = @cl_CodGrp
                                And Cod_Fabric = @pr_CodFabric 
                      
                              if (@PQtdPrzMax <= @WQtdPrzMaxAux) and
                                 (@PPerDscPrz <= @WPerDscPrzAux) and
                                 (@PPerDscVis <= @WPerDscVisAux) 
                                Set @WFlgPrzDscOk = 1
                              else
                                begin
                                  Set @PDesMsg ='Prazo/Desconto Diferenciado do Fabricante inválido para este grupo de clientes'
                                  if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1)) 
                                    Set @WFlgPrzDscOk = 0
                                  else
                                    begin
                                      if (@PFlgSnhEsp = 1) 
                                        Set @PNomUsuDbq = @PNomUsuSnhEsp
                                      else
                                        Set @PNomUsuDbq = @WNomUsu
                                      Set @PDesMsgDbq = @PDesMsg
                                    end
                                end
                            end
                          else
                            begin
                              -- ver se mantem prazo do pedido ou pega o default do grupo
                              if @pm_FlgAltConComPdv = 0
                                begin
                                  if Exists(Select 1 From GRCLI Where Cod_GrpCli = @cl_CodGrp) 
                                    -- pega prazo do grupo
                                    if ((Select IsNull(Flg_ComFab,0) From GRCLI Where Cod_GrpCli = @cl_CodGrp) = 1) and  
                                       (@fb_QtdPrzMax >= 0)
                                      begin
                                        if @pm_FlgRegPrzPdvExcConCom = 0
                                          Set @WQtdPrzMaxAux = @fb_QtdPrzMax
                      
                                        if (@PQtdPrzMax <= @WQtdPrzMaxAux) and
                                           (@PPerDscPrz <= @WPerDscPrzAux) and
                                           (@PPerDscVis <= @WPerDscVisAux) 
                                          Set @WFlgPrzDscOk = 1
                                        else
                                          begin
                                            Set @PDesMsg = 'Prazo/Desconto deste Grupo excede condições do fabricante'
                                            if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1)) 
                                              Set @WFlgPrzDscOk = 0
                                            else
                                              begin
                                                if (@PFlgSnhEsp = 1) 
                                                  Set @PNomUsuDbq = @PNomUsuSnhEsp
                                                else
                                                  Set @PNomUsuDbq = @WNomUsu
                                                Set @PDesMsgDbq = @PDesMsg
                                              end
                                          end
                                      end
                                    else
                                      begin
                                      -- pega prazo do grupo
                                        Select @WQtdPrzMaxAux = Case 
                                                                  When (@pm_FlgRegPrzPdvExcConCom = 0) then IsNull(Qtd_PrzMax,0)
                                                                  Else @WQtdPrzMaxAux 
                                                                End
                                          From GRCLI
                                          Where Cod_GrpCli = @cl_CodGrp
                      
                                        if (@PQtdPrzMax <= @WQtdPrzMaxAux) and
                                           (@PPerDscPrz <= @WPerDscPrzAux) and
                                           (@PPerDscVis <= @WPerDscVisAux) 
                                          Set @WFlgPrzDscOk = 1
                                        else
                                          begin
                                            Set @PDesMsg = 'Prazo/Desconto inválido para este grupo de clientes'
                                            if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1)) 
                                              Set @WFlgPrzDscOk = 0
                                            else
                                              begin
                                                if (@PFlgSnhEsp = 1) 
                                                  Set @PNomUsuDbq = @PNomUsuSnhEsp
                                                else
                                                  Set @PNomUsuDbq = @WNomUsu
                                                Set @PDesMsgDbq = @PDesMsg
                                              end
                                          end
                                      end
                                  else
                                  -- Fabricante: condicoes default
                                  if (@pm_FlgLimComMaxFab = 0) and (@fb_QtdPrzMax >= 0)
                                    begin
                                      Set @WQtdPrzMaxAux = @fb_QtdPrzMax
                      
                                      if (@PQtdPrzMax <= @WQtdPrzMaxAux) and
                                         (@PPerDscPrz <= @WPerDscPrzAux) and
                                         (@PPerDscVis <= @WPerDscVisAux) 
                                        Set @WFlgPrzDscOk = 1
                                      else
                                        begin
                                          Set @PDesMsg = 'Prazo/Desconto deste Grupo excede condições do fabricante'
                                          if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1)) 
                                            Set @WFlgPrzDscOk = 0
                                          else
                                            begin
                                              if (@PFlgSnhEsp = 1) 
                                                Set @PNomUsuDbq = @PNomUsuSnhEsp
                                              else
                                                Set @PNomUsuDbq = @WNomUsu
                                              Set @PDesMsgDbq = @PDesMsg
                                            end
                                        end
                                    end
                                end  -- if @pm_FlgAltConComPdv = 0
                      
                            end  -- else de if Exists(Select 1 From GCXFB Where Cod_GrpCli = @cl_CodGrp And Cod_Fabric = @pr_CodFabric) 
                      
                        end  -- else de if @cl_FlgCliEsp = 1

                    end  -- else de @pr_FlgPrzComercMax = 1

                end  -- if @pr_FlgPolComercMax = 1

              -- critica desconto diferenciado do produto para o cliente
              if (@WFlgSegue = 1) and (@WFlgPrzDscOk = 1)
                begin
                  if Exists(Select 1 From CLXPD Where Cod_CliPag = @cl_CodCliPag And Cod_Produt = @PCodPrd)
                    begin
                      Set @WFlgSegue = 0

                      Select @WQtdPrzMaxAux = Case 
                                                When (@pm_FlgRegPrzPdvExcConCom = 0) then IsNull(Qtd_PrzMax,0)
                                                Else @WQtdPrzMaxAux 
                                              End, 
                             @WPerDscPrzAux = IsNull(Per_Descon,0), 
                             @WPerDscVisAux = IsNull(Per_DscVis,0) 
                        From CLXPD 
                        Where Cod_CliPag = @cl_CodCliPag 
                        And Cod_Produt = @PCodPrd

                      if (@PQtdPrzMax <= @WQtdPrzMaxAux) and
                         (@PPerDscPrz <= @WPerDscPrzAux) and
                         (@PPerDscVis <= @WPerDscVisAux) 
                        Set @WFlgPrzDscOk = 1
                      else
                        begin
                          Set @PDesMsg = 'Prazo/Desconto Diferenciado do Produto inválido para este cliente'
                          if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1)) 
                            Set @WFlgPrzDscOk = 0
                          else
                            begin
                              if (@PFlgSnhEsp = 1) 
                                Set @PNomUsuDbq = @PNomUsuSnhEsp
                              else
                                Set @PNomUsuDbq = @WNomUsu
                              Set @PDesMsgDbq = @PDesMsg
                            end
                        end
                    end
                end

              -- critica desconto diferenciado do fabricante para o cliente
              if (@WFlgSegue = 1) and (@WFlgPrzDscOk = 1)
                begin
                  if Exists(Select 1 From CLXFB Where Cod_CliPag = @cl_CodCliPag And Cod_Fabric = @pr_CodFabric)
                    begin
                      Set @WFlgSegue = 0

                      Select @WQtdPrzMaxAux = Case 
                                                When (@pm_FlgRegPrzPdvExcConCom = 0) then IsNull(Qtd_PrzMax,0)
                                                Else @WQtdPrzMaxAux 
                                              End, 
                             @WPerDscPrzAux = IsNull(Per_Descon,0), 
                             @WPerDscVisAux = IsNull(Per_DscVis,0) 
                        From CLXFB 
                        Where Cod_CliPag = @cl_CodCliPag 
                        And Cod_Fabric = @pr_CodFabric

                      if (@PQtdPrzMax <= @WQtdPrzMaxAux) and
                         (@PPerDscPrz <= @WPerDscPrzAux) and
                         (@PPerDscVis <= @WPerDscVisAux) 
                        Set @WFlgPrzDscOk = 1
                      else
                        begin
                          Set @PDesMsg = 'Prazo/Desconto Diferenciado do Fabricante inválido para este cliente'
                          if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1)) 
                            Set @WFlgPrzDscOk = 0
                          else
                            begin
                              if (@PFlgSnhEsp = 1) 
                                Set @PNomUsuDbq = @PNomUsuSnhEsp
                              else
                                Set @PNomUsuDbq = @WNomUsu
                              Set @PDesMsgDbq = @PDesMsg
                            end
                        end
                    end
                end

              -- critica desconto do cliente especial ou grupo
              if (@WFlgSegue = 1) and (@WFlgPrzDscOk = 1)
                if @cl_FlgCliEsp = 1 
                  begin
                    Set @WFlgSegue = 0

                    if @pm_FlgRegPrzPdvExcConCom = 0
                      Set @WQtdPrzMaxAux = @cl_QtdPrzMax
                    Set @WPerDscPrzAux = @cl_PerDscVen
                    Set @WPerDscVisAux = @cl_PerDscComMaxVis

                      if (@PQtdPrzMax <= @WQtdPrzMaxAux) and
                         (@PPerDscPrz <= @WPerDscPrzAux) and
                         (@PPerDscVis <= @WPerDscVisAux) 
                      Set @WFlgPrzDscOk = 1
                    else
                      begin
                        Set @PDesMsg = 'Prazo/Desconto inválido para cliente especial'
                        if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1)) 
                          Set @WFlgPrzDscOk = 0
                        else
                          begin
                            if (@PFlgSnhEsp = 1) 
                              Set @PNomUsuDbq = @PNomUsuSnhEsp
                            else
                              Set @PNomUsuDbq = @WNomUsu
                            Set @PDesMsgDbq = @PDesMsg
                          end
                      end
                  end
                else
                  begin
                    -- verifica o desconto diferenciado do produto para o grupo
                    if (@WFlgSegue = 1) and (@WFlgPrzDscOk = 1)
                      begin
                        if Exists(Select 1 From GCXPR Where Cod_GrpCli = @cl_CodGrp And Cod_Produt = @PCodPrd)
                          begin
                            Set @WFlgSegue = 0

                            Select @WQtdPrzMaxAux = Case 
                                                      When (@pm_FlgRegPrzPdvExcConCom = 0) then IsNull(Qtd_PrzMax,0)
                                                      Else @WQtdPrzMaxAux 
                                                    End, 
                                   @WPerDscPrzAux = IsNull(Per_Descon,0), 
                                   @WPerDscVisAux = IsNull(Per_DscVis,0) 
                              From GCXPR 
                              Where Cod_GrpCli = @cl_CodGrp
                              And Cod_Produt = @PCodPrd

                            if (@PQtdPrzMax <= @WQtdPrzMaxAux) and
                               (@PPerDscPrz <= @WPerDscPrzAux) and
                               (@PPerDscVis <= @WPerDscVisAux) 
                              Set @WFlgPrzDscOk = 1
                            else
                              begin
                                Set @PDesMsg = 'Prazo/Desconto Diferenciado do Produto inválido para este grupo de clientes'
                                if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1)) 
                                  Set @WFlgPrzDscOk = 0
                                else
                                  begin
                                    if (@PFlgSnhEsp = 1) 
                                      Set @PNomUsuDbq = @PNomUsuSnhEsp
                                    else
                                      Set @PNomUsuDbq = @WNomUsu
                                    Set @PDesMsgDbq = @PDesMsg
                                  end
                              end
                          end
                      end

                    -- verifica o desconto diferenciado do fabricante para o grupo
                    if (@WFlgSegue = 1) and (@WFlgPrzDscOk = 1)
                      begin
                        if Exists(Select 1 From GCXFB Where Cod_GrpCli = @cl_CodGrp And Cod_Fabric = @pr_CodFabric) 
                          begin
                            Set @WFlgSegue = 0

                            Select @WQtdPrzMaxAux = Case 
                                                      When (@pm_FlgRegPrzPdvExcConCom = 0) then IsNull(Qtd_PrzMax,0)
                                                      Else @WQtdPrzMaxAux 
                                                    End, 
                                   @WPerDscPrzAux = IsNull(Per_Descon,0), 
                                   @WPerDscVisAux = IsNull(Per_DscVis,0) 
                              From GCXFB 
                              Where Cod_GrpCli = @cl_CodGrp
                              And Cod_Fabric = @pr_CodFabric

                            if (@PQtdPrzMax <= @WQtdPrzMaxAux) and
                               (@PPerDscPrz <= @WPerDscPrzAux) and
                               (@PPerDscVis <= @WPerDscVisAux) 
                              Set @WFlgPrzDscOk = 1
                            else
                              begin
                                Set @PDesMsg = 'Prazo/Desconto Diferenciado do Fabricante inválido para este grupo de clientes'
                                if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1)) 
                                  Set @WFlgPrzDscOk = 0
                                else
                                  begin
                                    if (@PFlgSnhEsp = 1) 
                                      Set @PNomUsuDbq = @PNomUsuSnhEsp
                                    else
                                      Set @PNomUsuDbq = @WNomUsu
                                    Set @PDesMsgDbq = @PDesMsg
                                  end
                              end
                          end
                      end

                    -- verifica o desconto do grupo ou do pedido
                    if (@WFlgSegue = 1) and (@WFlgPrzDscOk = 1) and (@pm_FlgAltConComPdv = 0) 
                      begin
                        if Exists(Select 1 From GRCLI Where Cod_GrpCli = @cl_CodGrp)
                          begin
                            Set @WFlgSegue = 0

                            if (Select IsNull(Flg_ComFab,0) From GRCLI Where Cod_GrpCli = @cl_CodGrp) = 1
                              begin
                                if @pm_FlgRegPrzPdvExcConCom = 0
                                  Set @WQtdPrzMaxAux = @fb_QtdPrzMax
                                Set @WPerDscPrzAux = @fb_PerDscPrz
                                Set @WPerDscVisAux = @fb_PerDscVis

                                if (@PQtdPrzMax <= @WQtdPrzMaxAux) and
                                   (@PPerDscPrz <= @WPerDscPrzAux) and
                                   (@PPerDscVis <= @WPerDscVisAux) 
                                  Set @WFlgPrzDscOk = 1
                                else
                                  begin
                                    Set @PDesMsg = 'Prazo/Desconto deste Grupo excede condições do fabricante'
                                    if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1)) 
                                      Set @WFlgPrzDscOk = 0
                                    else
                                      begin
                                        if (@PFlgSnhEsp = 1) 
                                          Set @PNomUsuDbq = @PNomUsuSnhEsp
                                        else
                                          Set @PNomUsuDbq = @WNomUsu
                                        Set @PDesMsgDbq = @PDesMsg
                                      end
                                  end
                              end
                            else
                              begin
                                Select @WQtdPrzMaxAux = Case 
                                                          When (@pm_FlgRegPrzPdvExcConCom = 0) then IsNull(Qtd_PrzMax,0)
                                                          Else @WQtdPrzMaxAux 
                                                        End, 
                                       @WPerDscPrzAux = IsNull(Per_Descon,0), 
                                       @WPerDscVisAux = IsNull(Per_DscVis,0) 
                                  From GRCLI
                                  Where Cod_GrpCli = @cl_CodGrp

                                if (@PQtdPrzMax <= @WQtdPrzMaxAux) and
                                   (@PPerDscPrz <= @WPerDscPrzAux) and
                                   (@PPerDscVis <= @WPerDscVisAux) 
                                  Set @WFlgPrzDscOk = 1
                                else
                                  begin
                                    Set @PDesMsg = 'Prazo/Desconto inválido para este grupo de clientes'
                                    if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1)) 
                                      Set @WFlgPrzDscOk = 0
                                    else
                                      begin
                                        if (@PFlgSnhEsp = 1) 
                                          Set @PNomUsuDbq = @PNomUsuSnhEsp
                                        else
                                          Set @PNomUsuDbq = @WNomUsu
                                        Set @PDesMsgDbq = @PDesMsg
                                      end
                                  end
                              end
                          end

                        else
                        -- Fabricante: condicoes default
                        if (@pm_FlgLimComMaxFab = 0) and (@fb_QtdPrzMax >= 0) 
                          begin
                            if @pm_FlgRegPrzPdvExcConCom = 0
                              Set @WQtdPrzMaxAux  = @fb_QtdPrzMax
                            Set @WPerDscPrzAux = @fb_PerDscPrz
                            Set @WPerDscVisAux = @fb_PerDscVis

                            if (@PQtdPrzMax <= @WQtdPrzMaxAux) and
                               (@PPerDscPrz <= @WPerDscPrzAux) and
                               (@PPerDscVis <= @WPerDscVisAux) 
                              Set @WFlgPrzDscOk = 1
                            else
                              begin
                                Set @PDesMsg = 'Prazo/Desconto deste Grupo excede condições do fabricante'
                                if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1)) 
                                  Set @WFlgPrzDscOk = 0
                                else
                                  begin
                                    if (@PFlgSnhEsp = 1) 
                                      Set @PNomUsuDbq = @PNomUsuSnhEsp
                                    else
                                      Set @PNomUsuDbq = @WNomUsu
                                    Set @PDesMsgDbq = @PDesMsg
                                  end
                              end
                          end

                      end  -- if (@WFlgSegue = 1) and (@WFlgPrzDscOk = 1) and (@pm_FlgAltConComPdv = 0) 
                  end  -- if @cl_FlgCliEsp = 1

              -- verifica promocao
              if (@WFlgPrzDscOk = 0) and (@WFlgPromoc = 1)
                if @WQtdPrzPromoc > 0 
                  if (@PQtdPrzMax <= @WQtdPrzPromoc) and
                     (@WDscTotItePdv <=  @WPerDscPromoc) 
                    Set @WFlgPrzDscOk = 1
                  else
                    begin
                      Set @PDesMsg = 'Prazo/Desconto excede condições da promoção'
                      if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1)) 
                        Set @WFlgPrzDscOk = 0
                      else
                        begin
                          if (@PFlgSnhEsp = 1) 
                            Set @PNomUsuDbq = @PNomUsuSnhEsp
                          else
                            Set @PNomUsuDbq = @WNomUsu
                          Set @PDesMsgDbq = @PDesMsg
                        end
                    end
                else
                if (@WDscTotItePdv <=  @WPerDscPromoc) 
                  Set @WFlgPrzDscOk = 1
                else
                  begin
                    Set @PDesMsg = 'Prazo/Desconto excede condições da promoção'
                    if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1)) 
                      Set @WFlgPrzDscOk = 0
                    else
                      begin
                        if (@PFlgSnhEsp = 1) 
                          Set @PNomUsuDbq = @PNomUsuSnhEsp
                        else
                          Set @PNomUsuDbq = @WNomUsu
                        Set @PDesMsgDbq = @PDesMsg
                      end
                  end

              if @WFlgPrzDscOk = 0 
                begin
                  Set @PCmp    = 'EditQtdPrz'
                  Set @PCodRej = 'CAD'   -- ????
                  if @PDesMsg = '' 
                    Set @PDesMsg = 'Prazo/Desconto inválido'
                  Return
                end

            end       -- if (CharIndex(@op_TipPrc,';M;C;E;') = 0) and (@pv_CodCli > 0) 

          if @WQtdPrzPromoc > @WQtdPrzMaxAux 
            Set @WQtdPrzMaxAux = @WQtdPrzPromoc
          if @PQtdPrzMax > @WQtdPrzMaxAux 
            begin
              Set @PDesMsg = 'Prazo maior que o permitido'
              if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1)) 
                begin
                  Set @PCmp    = 'EditQtdPrz'
                  Set @PCodRej = 'PZX'
                  Return
                end
              else
                begin
                  if (@PFlgSnhEsp = 1) 
                    Set @PNomUsuDbq = @PNomUsuSnhEsp
                  else
                    Set @PNomUsuDbq = @WNomUsu
                  Set @PDesMsgDbq = @PDesMsg
                end
            end

          -- ver cond. maxima do fabricante exceto p/ promocao e cliente especial
          if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1))
            if (@pv_CodCli > 0) and (@PCodPromoc = 0) and (@cl_FlgCliEsp = 0) and (@pm_FlgLimComMaxFab = 1)
              begin
                if @PQtdPrzMax > @fb_QtdPrzMax 
                  Set @PQtdPrzMax = @fb_QtdPrzMax
                if @PPerDscPrz > @fb_PerDscPrz
                  Set @PPerDscPrz = @fb_PerDscPrz
                if @PPerDscVis > @fb_PerDscVis
                  Set @PPerDscVis = @fb_PerDscVis
              end

        end  -- if @pv_TipPrz = 'F' 

      -- criticas em comum @pv_TipPrz = 'F'  ou 'L'
      -- critica promocao   
      if @PCodPromoc > 0 
        begin
          if @PQtdPed < @WQtdMinPromoc 
            if @PFlgSnhEsp = 0
              if @pm_FlgBlqSugPrmQtdMin = 1    -- cond.Self normal automatica
                begin
                  Set @PCodPromoc = 0
                  --ComercDefaultPdvitSemPromocao(PIteDts,PPsqDts,PTipPrc,@pv_QtdPrzMed,PConFin,PPrcDif,PFlgRetMsg)   aqui
                end
              else
                begin
                  Set @PCmp    = 'EditQtdPedido'
                  Set @PCodRej = 'QTX'
                  Set @PDesMsg = 'Quant. menor que a mínima da promoção'
                  Return
                end
            else
              begin
                Set @PDesMsg = 'Quant. menor que a mínima da promoção'
                Set @PNomUsuDbq = @PNomUsuSnhEsp
                Set @PDesMsgDbq = @PDesMsg
              end
    
          if CharIndex(Substring(@pv_CodOriPdv,1,1),';M;T;W;') = 0   -- exceto Mobile, E-commerce, Web
            begin
              if @PQtdPed + @PQtdBon > @WQtdEstPromoc 
                begin
                  Set @PDesMsg = 'Quant. maiores que o estoque da promoção'
                  if not (@PFlgSnhEsp = 1) 
                    begin
                      Set @PCmp    = 'EditQtdPedido'
                      Set @PCodRej = 'QTX'
                      Return
                    end
                  else
                    begin
                      Set @PNomUsuDbq = @PNomUsuSnhEsp
                      Set @PDesMsgDbq = @PDesMsg
                    end
                end
              if (@WQtdPrzPromoc > 0) and (@PQtdPrzMax > @WQtdPrzPromoc)
                begin
                  Set @PDesMsg = 'Prazo maior que o permitido'
                  if not ((@PFlgSnhEsp = 1) or (@PNaoCriConCom = 1)) 
                    begin
                      Set @PCmp    = 'EditQtdPrz'
                      Set @PCodRej = 'PZX'
                      Return
                    end
                  else
                    begin
                      if (@PFlgSnhEsp = 1) 
                        Set @PNomUsuDbq = @PNomUsuSnhEsp
                      else
                        Set @PNomUsuDbq = @WNomUsu
                      Set @PDesMsgDbq = @PDesMsg
                    end
                end
            end
    
        end  -- if @PCodPromoc > 0

      -- critica precos   
      if @WPrcUniLiqPrm > 0 
        if @WPrcUniLiqPrm < @PPrcUniLiqPer 
          Set @PPrcUniLiqPer = @WPrcUniLiqPrm
      if @PPrcTab > 0 
        if @PPrcTab < @PPrcUniLiqPer 
          Set @PPrcUniLiqPer = @PPrcTab

      Set @PCodKitPrm = 0  -- para criticar precos minimo/permitido/venda bloqueada

    end  -- if @PFlgPolCom = 0

------------------------------------------------------------------------------------------------------------------------------------------------------

  if @PFlgPolCom = 1
    begin
      -- condicoes de comercializacao/ somente para vendas
      if @PCodKitPrm = 0
        begin

          -- critica verba somente em operações de venda
          if (@pv_TipSai = 'V') and (@PVlrVerbaTot = 0) 
            begin
              Set @PVlrVerbaTot = dbo.FN_VlrVerbaDisponPdv(@PCodEstabe,
                                                           @PNumPdv,
                                                           @PIdPolComIte,
                                                           @pr_CodFabric,
                                                           @PTipSai,
                                                           'D', '?')
            end

          -- critica pr. minimo com Markup
          if (@pv_TipGerVrbPdv <> 'P') and (@pv_TipRatBon <> '') and
             (@pv_FlgMrkCusCom = 1)  -- incluido em 08/06/2021 (DMD-6104): rever se realmente eh necessario
            begin
              if @PPrcCusMinComMarkup <= 0
                begin
                  Set @PCmp    = 'EditCodProduto'
                  Set @PCodRej = 'CAD'
                  Set @PDesMsg = 'Preço Mímino de Comercialização Inválido (Sem Markup)'
                  Return
                end

              if @PFlgBlqCriPrcVen = 0
                begin
                  if Round(@WPrcUniLiqPdv,4) < Round(@pr_PrcCusMedCom,4)
                    begin
                      Set @PCmp    = 'EditCodProduto'
                      Set @PCodRej = 'CAD'
                      Set @PDesMsg = 'Preço Unitário inferior ao Pr.Custo de Comercialização'
                      Return
                    end;
		      
                  if Round(@WPrcUniLiqPdv,4) < Round(@PPrcCusMinComMarkup,4) 
                    begin
                      Set @PCmp    = 'EditCodProduto'
                      Set @PCodRej = 'PU-'
                      Set @PDesMsg = 'Preço Unitário inferior ao Preço Mínimo de Comercialização'
                      Return
                    end
                end

            end  -- if (@pv_TipGerVrbPdv <> 'P') and (@pv_TipRatBon <> '')
          else
            begin
              --criticas p/ politicas sem markup

              -- corrige desconto escalonado da politica, se for o caso: aqui rever...
              if Exists(Select 1 From PCXPR Where Id_PolCom = @PIdPolComIte And Cod_Produt = @PCodPrd)
                begin
                   Set @PrcPolCom = IsNull(@PrcPolCom,0)
                   Set @PQtdPrzPolCom = IsNull(@PQtdPrzPolCom,0)
                   Set @PPerDscPolCom = IsNull(@PPerDscPolCom,0)
                   Set @PPerDscVisPolCom = IsNull(@PPerDscVisPolCom,0)

                   Select @PrcPolCom = Case When (@PrcPolCom = 0) and (IsNull(Prc_Promoc,0) > 0) then Prc_Promoc else @PrcPolCom end, 
                          @PQtdPrzPolCom = Case When @PQtdPrzPolCom = 0 then IsNull(Qtd_PrzMax,0) else @PQtdPrzPolCom end,
              
                          @PPerDscPolCom = Case
                                             When (IsNull(Qtd_Min5,0) > 0)   and (@PQtdPed >= IsNull(Qtd_Min5,0))   and (@PPerDscPolCom >= IsNull(Per_Dsc5,0))   then IsNull(Per_Dsc5,0)
                                             When (IsNull(Qtd_Min4,0) > 0)   and (@PQtdPed >= IsNull(Qtd_Min4,0))   and (@PPerDscPolCom >= IsNull(Per_Dsc4,0))   then IsNull(Per_Dsc4,0)
                                             When (IsNull(Qtd_Min3,0) > 0)   and (@PQtdPed >= IsNull(Qtd_Min3,0))   and (@PPerDscPolCom >= IsNull(Per_Dsc3,0))   then IsNull(Per_Dsc3,0)
                                             When (IsNull(Qtd_Min2,0) > 0)   and (@PQtdPed >= IsNull(Qtd_Min2,0))   and (@PPerDscPolCom >= IsNull(Per_Dsc2,0))   then IsNull(Per_Dsc2,0)
                                             When (IsNull(Qtd_Minimo,0) > 0) and (@PQtdPed >= IsNull(Qtd_Minimo,0)) and (@PPerDscPolCom >= IsNull(Per_Descon,0)) then IsNull(Per_Descon,0)
                                             Else @PPerDscPolCom 
                                           End,
              
                          @PPerDscVisPolCom = Case
                                                When (IsNull(Qtd_Min5,0) > 0)   and (@PQtdPed >= IsNull(Qtd_Min5,0))   and (@PPerDscVisPolCom >= IsNull(Per_DscVis5,0)) then IsNull(Per_DscVis5,0)
                                                When (IsNull(Qtd_Min4,0) > 0)   and (@PQtdPed >= IsNull(Qtd_Min4,0))   and (@PPerDscVisPolCom >= IsNull(Per_DscVis4,0)) then IsNull(Per_DscVis4,0)
                                                When (IsNull(Qtd_Min3,0) > 0)   and (@PQtdPed >= IsNull(Qtd_Min3,0))   and (@PPerDscVisPolCom >= IsNull(Per_DscVis3,0)) then IsNull(Per_DscVis3,0)
                                                When (IsNull(Qtd_Min2,0) > 0)   and (@PQtdPed >= IsNull(Qtd_Min2,0))   and (@PPerDscVisPolCom >= IsNull(Per_DscVis2,0)) then IsNull(Per_DscVis2,0)
                                                When (IsNull(Qtd_Minimo,0) > 0) and (@PQtdPed >= IsNull(Qtd_Minimo,0)) and (@PPerDscVisPolCom >= IsNull(Per_DscVis,0))  then IsNull(Per_DscVis,0)
                                                Else @PPerDscVisPolCom 
                                              End,
              
                          @PQtdPed = Case
                                       When (IsNull(Qtd_Min5,0) > 0) and (@PQtdPed >= IsNull(Qtd_Min5,0)) then 
                                         Case When (IsNull(Qtd_Max5,0) > 0) and (@PQtdPed > IsNull(Qtd_Max5,0))     then IsNull(Qtd_Max5,0)   Else @PQtdPed End
                                       When (IsNull(Qtd_Min4,0) > 0) and (@PQtdPed >= IsNull(Qtd_Min4,0)) then 
                                         Case When (IsNull(Qtd_Max4,0) > 0) and (@PQtdPed > IsNull(Qtd_Max4,0))     then IsNull(Qtd_Max4,0)   Else @PQtdPed End
                                       When (IsNull(Qtd_Min3,0) > 0) and (@PQtdPed >= IsNull(Qtd_Min3,0)) then 
                                         Case When (IsNull(Qtd_Max3,0) > 0) and (@PQtdPed > IsNull(Qtd_Max3,0))     then IsNull(Qtd_Max3,0)   Else @PQtdPed End
                                       When (IsNull(Qtd_Min2,0) > 0) and (@PQtdPed >= IsNull(Qtd_Min2,0)) then 
                                         Case When (IsNull(Qtd_Max2,0) > 0) and (@PQtdPed > IsNull(Qtd_Max2,0))     then IsNull(Qtd_Max2,0)   Else @PQtdPed End
                                       When (IsNull(Qtd_Minimo,0) > 0) and (@PQtdPed >= IsNull(Qtd_Minimo,0)) then 
                                         Case When (IsNull(Qtd_Maximo,0) > 0) and (@PQtdPed > IsNull(Qtd_Maximo,0)) then IsNull(Qtd_Maximo,0) Else @PQtdPed End
                                       Else @PQtdPed
                                     End
                     From PCXPR 
                     Where Id_PolCom = @PIdPolComIte
                     And Cod_Produt = @PCodPrd
                end

              Set @PPrcUniLiqPer = @PrcPolCom*(1-@PPerDscVisPolCom/100)

              -- critica preço se não gerar verba ou gera verba para acumular...
			  -- no pedido eletronico desconsiderar tipo de verba, se for o caso (opção para rejeitar preço na importação)
              if (@PFlgBlqCriPrcVen = 0) and
                 (Round(@WPrcUniLiqPdv,4) < Round(@PPrcUniLiqPer,4)) and
                 (Round(@WPrcUniLiqPdv,@pm_QtdDecPrcItePdv) < Round(@PPrcUniLiqPer,@pm_QtdDecPrcItePdv)) and
                 (Abs(Round(@PPrcUniLiqPer*10000,0) - Round(@WPrcUniLiqPdv*10000,0)) > 1)
                begin
                  Set @PDesMsg = 'Preço Unitário ('+cast(@WPrcUniLiqPdv as varchar) +') '+
                                 'inferior ao Permitido ('+cast(@PPrcUniLiqPer as varchar)+')'

                  if (@PFlgCriVrb = 1) and
                     ((Round(@PPrcUniLiqPer,@pm_QtdDecPrcItePdv) - Round(@WPrcUniLiqPdv,@pm_QtdDecPrcItePdv)) > @PVlrVerbaTot) and
                     ( (Substring(@pv_CodOriPdv,1,1) ='T') or 
                       ((Substring(@pv_CodOriPdv,1,1) <> 'T') and (@pv_TipGerVrbPdv <> 'P')) )
                    begin                         
                      Set @PDesMsg = @PDesMsg + '. Verba insuficiente para atender o item'
                      if @PFlgSnhEsp = 0
                        begin
                          Set @PCodRej = 'PU-'
                          Set @PCmp = 'EditPrcUnitario'
                          Return
                        end
                      else
                        begin
                          if @PFlgSnhEsp = 1 
                            Set @PNomUsuDbq = @PNomUsuSnhEsp
                          else
                            Set @PNomUsuDbq = @WNomUsu
                        end
                    end  --  if (@PFlgCriVrb = 1) and
                  else
                    begin
                      if @PFlgSnhEsp = 0
                        begin
                          Set @PCodRej = 'PU-'
                          Set @PCmp = 'EditPrcUnitario'
                          Return
                        end
                      else
                        begin
                          if @PFlgSnhEsp = 1 
                            Set @PNomUsuDbq = @PNomUsuSnhEsp
                          else
                            Set @PNomUsuDbq = @WNomUsu
                        end
                    end
                end  -- if (@PFlgBlqCriPrcVen = 0) and
              
            end  --criticas p/ politicas sem markup

          -- critica quantidade minima qdo for o caso  aqui rever
          if Exists(Select 1 From PCXPR Where Id_PolCom = @PIdPolComIte And Cod_Produt = @PCodPrd)
            begin
              Set @WDesMsg = ''
              Select @WDesMsg = Case
                                  When (@PPerDscPrz <= IsNull(Per_Dsc5,0)) and (@PPerDscPrz > IsNull(Per_Dsc4,0)) and
                                       (@PPerDscVis <= IsNull(Per_DscVis5,0)) and (@PPerDscVis > IsNull(Per_DscVis4,0)) then
                                    Case 
                                      When (IsNull(Qtd_Min5,0) > 0) and (@PQtdPed < IsNull(Qtd_Min5,0)) then 'Quantidade inferior ao Mínimo Permitido ('+cast(Qtd_Min5 as varchar)+')'
                                      When (IsNull(Qtd_Max5,0) > 0) and (@PQtdPed > IsNull(Qtd_Max5,0)) then 'Quantidade superior ao Máximo Permitido ('+cast(Qtd_Max5 as varchar)+')'
                                    End

                                  When (@PPerDscPrz <= IsNull(Per_Dsc4,0)) and (@PPerDscPrz > IsNull(Per_Dsc3,0)) and
                                       (@PPerDscVis <= IsNull(Per_DscVis4,0)) and (@PPerDscVis > IsNull(Per_DscVis3,0)) then
                                    Case 
                                      When (IsNull(Qtd_Min4,0) > 0) and (@PQtdPed < IsNull(Qtd_Min4,0)) then 'Quantidade inferior ao Mínimo Permitido ('+cast(Qtd_Min4 as varchar)+')'
                                      When (IsNull(Qtd_Max4,0) > 0) and (@PQtdPed > IsNull(Qtd_Max4,0)) then 'Quantidade superior ao Máximo Permitido ('+cast(Qtd_Max4 as varchar)+')'
                                    End

                                  When (@PPerDscPrz <= IsNull(Per_Dsc3,0)) and (@PPerDscPrz > IsNull(Per_Dsc2,0)) and
                                       (@PPerDscVis <= IsNull(Per_DscVis3,0)) and (@PPerDscVis > IsNull(Per_DscVis2,0)) then
                                    Case 
                                      When (IsNull(Qtd_Min3,0) > 0) and (@PQtdPed < IsNull(Qtd_Min3,0)) then 'Quantidade inferior ao Mínimo Permitido ('+cast(Qtd_Min3 as varchar)+')'
                                      When (IsNull(Qtd_Max3,0) > 0) and (@PQtdPed > IsNull(Qtd_Max3,0)) then 'Quantidade superior ao Máximo Permitido ('+cast(Qtd_Max3 as varchar)+')'
                                    End

                                  When (@PPerDscPrz <= IsNull(Per_Dsc2,0)) and (@PPerDscPrz > IsNull(Per_Descon,0)) and
                                       (@PPerDscVis <= IsNull(Per_DscVis2,0)) and (@PPerDscVis > IsNull(Per_DscVis,0)) then
                                    Case 
                                      When (IsNull(Qtd_Min2,0) > 0) and (@PQtdPed < IsNull(Qtd_Min2,0)) then 'Quantidade inferior ao Mínimo Permitido ('+cast(Qtd_Min2 as varchar)+')'
                                      When (IsNull(Qtd_Max2,0) > 0) and (@PQtdPed > IsNull(Qtd_Max2,0)) then 'Quantidade superior ao Máximo Permitido ('+cast(Qtd_Max2 as varchar)+')'
                                    End

                                  When (@PPerDscPrz <= IsNull(Per_Descon,0)) and
                                       (@PPerDscVis <= IsNull(Per_DscVis,0)) then
                                    Case 
                                      When (IsNull(Qtd_Minimo,0) > 0) and (@PQtdPed < IsNull(Qtd_Minimo,0)) then 'Quantidade inferior ao Mínimo Permitido ('+cast(Qtd_Minimo as varchar)+')'
                                      When (IsNull(Qtd_Maximo,0) > 0) and (@PQtdPed > IsNull(Qtd_Maximo,0)) then 'Quantidade superior ao Máximo Permitido ('+cast(Qtd_Maximo as varchar)+')'
                                    End

                                  Else ''
                                End
                 From PCXPR 
                 Where Id_PolCom = @PIdPolComIte
                 And Cod_Produt = @PCodPrd

              -- retirar esta critica por enquanto: é necessário no DmdPE senha para não criticar..... ou (senha especial)....
/*
              if @WDesMsg <> ''
                begin
                  if @PFlgSnhEsp = 0
                    begin
                      Set @PDesMsg = @WDesMsg
                      Set @PCmp    = 'EditQtdPedido'
                      Set @PCodRej = 'QTX'
                      Return
                    end
                  else
                    begin
                      if @PFlgSnhEsp = 1 
                        Set @PNomUsuDbq = @PNomUsuSnhEsp
                      else
                        Set @PNomUsuDbq = @WNomUsu
                    end
                end
*/
            end  -- if Exists(Select 1 From PCXPR Where Id_PolCom = @PIdPolComIte And Cod_Produt = @PCodPrd)

          if @PFlgCriVrb = 1
            begin
              Declare @WPrcUniLiqPol numeric(18,4),
                      @WVlrLiqIte numeric(18,4),
                      @WVlrLiqItePol numeric(18,4),
                      @WVlrLiqIteCusMed numeric(18,4),
                      @WVlrVrbIte numeric(18,4)
              
              -- critica possível verba "consumida"
              Set @WPrcUniLiqPol = @PrcPolCom*(1-@PPerDscPolCom/100)
              if @WPrcUniLiqPol = 0
                Set @WPrcUniLiqPol =  @WPrcUniLiqPdv
              
              Set @WVlrLiqIte = Round(@PQtdPed*@WPrcUniLiqPdv,2)
              Set @WVlrLiqItePol = Round(@PQtdPed*@WPrcUniLiqPol,2)
              
              if @PPrcCusMinComMarkup > 0 
                Set @WVlrLiqIteCusMed = Round(@PQtdPed*@PPrcCusMinComMarkup,2)
              else
                Set @WVlrLiqIteCusMed = @WVlrLiqIte
              
              Set @WVlrVrbIte = 0
              -- item bonificado
              if @PTipSai = 'B' 
                if (@pv_TipGerVrbPdv <> 'P') and (@pv_TipRatBon <> '') 
                  Set @WVlrVrbIte = @WVlrLiqIteCusMed
                else
                  Set @WVlrVrbIte = @WVlrLiqIte
              else
              -- item nao bonificado
              if (@pv_TipGerVrbPdv <> 'P') and (@pc_FlgMarkupCusCom = 1)
                Set @WVlrVrbIte = @WVlrLiqIteCusMed - @WVlrLiqIte
              else
                Set @WVlrVrbIte = @WVlrLiqItePol - @WVlrLiqIte
              
              -- o percentual de verba de Vend, Operad, ... é utilizado para acumular os valores não para criticar
              if (@PFlgCriVrb = 1) and 
                 (@WVlrVrbIte > 0) and (@WVlrVrbIte > @PVlrVerbaTot) and 
                 ((@pc_TipGerVrbPdv <> 'X') and (@pc_TipGerVrbPdv <> '')) 
                begin
                  if @PFlgSnhEsp = 0
                    begin
                      Set @PDesMsg = 'Verba disponível ('+cast(@PVlrVerbaTot as varchar)+') '+
                                     'insuficiente para atender o ítem ('+cast(@WVlrVrbIte as varchar)+')'
                      Set @PCodRej = '???'
                      Set @PCmp = 'EditPrcUnitario'
                      Return
                    end
                  else
                    begin
                      if @PFlgSnhEsp = 1
                        Set @PNomUsuDbq = @PNomUsuSnhEsp
                      else
                        Set @PNomUsuDbq = 'CONFIG. SISTEMA'
                      Set @PDesMsgDbq = @PDesMsg
                    end
                end
         
            end -- if @PFlgCriVrb = 1
        end  -- if @PCodKitPrm = 0
    end   -- if @PFlgPolCom = 1

  -- critica preco minimo, permitido e venda bloqueada 
  if @PCodKitPrm = 0
    begin

      -- calcula preço minimo
      if @PPrcMin = 0
        begin
          if @PFlgBlqCriPrcVen = 0 
            begin
              -- preco minimo de venda somente se nao utilizar preco de venda (-Custo, -customedio, - entrada)
              if @PPrcCusMinComMarkup > 0
                begin
                  Set @PPrcMin = @PPrcCusMinComMarkup
                  Set @PFlgBlqCriPrcVen = 1
                end;
          
              if CharIndex(@op_TipPrc,';M;C;E;') = 0
                if @pm_FlgCriPrcMinCusLiq = 1
                  begin
                    Set @PPrcMin = @pr_PrcCusLiqEnt*(1+@pm_PerAcrCriPrcMinCusLiq/100)
                    Set @PFlgBlqCriPrcVen = 0
                  end
                else
                if (@pm_FlgCriPrcMinCusMedCom = 1) and (@PFlgPolCom = 1)
                  begin
                    Set @PPrcMin = dbo.FN_PrcMinCom(@PCodEstabe,@PCodPrd)
                    Set @PFlgBlqCriPrcVen = 0
                  end
            end
        end

      if (@WPrcUniLiqPrm > 0) and (@WPrcUniLiqPrm < @PPrcMin) 
        Set @PPrcMin = @WPrcUniLiqPrm

      -- se estiver configurado critica preço minimo ( e Prc_CusMinComMarkup ?)
      if @PPrcMin > 0
        if (Round(@WPrcUniLiqPdv,4) < Round(@PPrcMin,4)) and
           (Round(@WPrcUniLiqPdv,@pm_QtdDecPrcItePdv) < Round(@PPrcMin,@pm_QtdDecPrcItePdv)) and
           (Abs(Round(@PPrcMin,4) - Round(@WPrcUniLiqPdv,4)) > 1) 
          begin
            if (@pm_FlgCriPrcMinCusLiq = 1) or
               (@pm_FlgCriPrcMinCusMedCom = 1) or
               (@pm_FlgCriPrcMinPmz = 1)
              begin
                Set @PDesMsg = 'Preço Unitário ('+cast(Round(@WPrcUniLiqPdv,@pm_QtdDecPrcItePdv) as varchar)+') '+
                               'inferior ao Pr.Mínimo ('+cast(Round(@PPrcMin,@pm_QtdDecPrcItePdv) as varchar)+')'

                 Set @PCodRej = 'PU-'
                 Set @PCmp    = 'EditPrcUnitario'
                 Return
              end
          end
      
      -- ver se existe bloqueio de venda  -- if @PCodKitPrm = 0
      Set @WFlgPrdBlq = 0
      Exec PR_VendaBloqueada @pv_CodTipPed, @PCodEstabe, @PCodPrd, @cl_CodGrp, @pv_CodCli, @pv_CodVdr, 
                                            @pv_TipFat, @PDesMsg output, @WFlgPrdBlq output
      if @WFlgPrdBlq = 1
        if @PFlgSnhEsp = 0
          begin
            Set @PCmp    = 'EditCodProduto'
            Set @PCodRej = 'VBQ'
            Return
          end
        else
          begin
            if @PFlgSnhEsp = 1
              Set @PNomUsuDbq = @PNomUsuSnhEsp
            else
              Set @PNomUsuDbq = @WNomUsu
          end

    end  -- if @PCodKitPrm = 0

-------------------------------------------------------

  Set @PQtdImpFat = (@PQtdPed+@PQtdBon)*1.0/@PFatCnvImpFat

  if (@PQtdPed+@PQtdBon) <> cast((@PQtdImpFat*@PFatCnvImpFat) as int)
    begin
      Set @PCmp    = 'EditQtdPedido'
      Set @PCodRej = 'QTX'
      Set @PDesMsg = 'Produto ('+cast(@PCodPrd as varchar)+'): Incompatibilidade na Impressão da N.F.(Quantidades) '
      Return
    end

  -- POCOM
  if Round((@PQtdPed+@PQtdBon)*@PPrcUni,4) <> Round(@PQtdImpFat*@PPrcUniImpFat,4) 
    begin
      Set @WPrcUni = Round((@PQtdImpFat*@PPrcUniImpFat)/(@PQtdPed+@PQtdBon),4)
      Set @PCmp    = 'EditPrcUnitario'
      Set @PCodRej = 'PUX'
      Set @PDesMsg = 'Incompatibilidade na Impressão da N.F. Preço Unitário Sugerido('+cast(@WPrcUni as varchar)+')'
      Return
    end

  -- desconto a vista nao pode ser menor que desc. a prazo
  if @PPerDscVis < @PPerDscPrz
    Set @PPerDscVis = @PPerDscPrz

  end  -- else (if not Exists(Select 1 From PRXES pr Inner Join PRODU p on pr.Cod_Produt = p.Codigo )

GO


SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraPedidoVendaPDE]
@PCodEstabe int,
@PCodLayout int,
@PNumCnpj varchar(14),
@PCodPedCli varchar(20),
@PNumDesdob int,
@PNumPdv int = NULL output,     -- se = 0 : cria novo pedido
@PMsgErr varchar(8000) output

AS

SET NOCOUNT ON

Set @PMsgErr = ''

if not Exists(Select 1 From dbo.PDECB 
              Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout And Num_Cnpj = @PNumCnpj And Cod_PedCli = @PCodPedCli And Num_Desdob = @PNumDesdob)
  Set @PMsgErr ='Pedido Eletrônico não existe'
else
if Exists(Select 1 From dbo.PDECB 
          Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout And Num_Cnpj = @PNumCnpj And Cod_PedCli = @PCodPedCli And Num_Desdob = @PNumDesdob
          And IsNull(Sta_Pedido,'') <> '0')
  Set @PMsgErr ='Pedido Eletrônico inválido (status)'
else
if not Exists(Select 1 From dbo.PDEIT 
              Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout And Num_Cnpj = @PNumCnpj And Cod_PedCli = @PCodPedCli And Num_Desdob = @PNumDesdob)
  Set @PMsgErr ='Pedido Eletrônico inválido (sem itens)'
else
  begin

    if @PNumPdv is null
      Set @PNumPdv = 0

    if not Exists(Select 1
                    From dbo.PDECB
                   Where Cod_Estabe = @PCodEstabe
                     And Cod_Layout = @PCodLayout
                     And Num_Cnpj   = @PNumCnpj
                     And Cod_PedCli = @PCodPedCli
                     And Num_Desdob = @PNumDesdob
                     And IsNull(Num_PedVen,0) > 0)
      begin  
        EXEC PR_ProxNumero 'Pedido_Venda', @PNumPdv output
      end  

    BEGIN TRANSACTION

    Set @PMsgErr = ''

    Declare @WCodDig int,
            @WTipFat varchar(3),
            @WTipPrc varchar(1),
            @WMsgAux varchar(100),
            @WNumSeqIte int,
            @WTipPrz varchar(1),
            @WNomUsuSnhEsp varchar(35),
            @WFlgBlqDscAutIte bit,
            @WFlgBlqAltPrcPol bit,
            @WTipImpPrcPdvCfg varchar(1),
            @WTipImpPrcPdv varchar(1),
            @WFlgTemVdrVnc bit,
            @WFlgUsaVdrPar bit,
            @WFlgSnhEsp bit,          
            @WFlgBlqCriConCom bit,    
            @WFlgBlqCriPrcVen bit,
            @WFlgBlqEstFisNeg bit,
            @WFlgCriVrb bit,
            @WFatCnvCxaFec int,			     
            @WPerDscArq numeric(8,4),
            @WPrcUniArq numeric(18,8),
            @WPerDsc numeric(8,4),
            @WPrcLiqArq numeric(18,8),
            @WDesLayout varchar(25),

            @WFlgBlqWms bit = 0,     -- nunca usa WMS
            @WFlgBlqPol bit = 0,     -- nunca usa politica
            @WFlgUsaWms bit = 0

    Declare @pm_FlgUsaPolComPdv bit = 0,
            @pm_PrzRefPrcVen int,
            @pm_FlgAltUnvItePdv bit,
            @pm_CodVdrPdvCon int,
            @pm_QtdDecPrcItePdv int,

            @pe_NumPedVen int,
            @pe_Layout varchar(20),
            @pe_CodOriPed varchar(1),
            @pe_TipPed varchar(1),
            @pe_CodPedCmpCli varchar(20),
            @pe_CodClient int, 
            @pe_CodVended int, 
            @pe_CodOperad int,
            @pe_IdPolCom int,
            @pe_CodTabPrz int,
            @pe_CodMtvRej varchar(3),
            @pe_CodGrpClp int,
            @pe_FlgFatPedIntegral bit

    -- PARAM
    Select @pm_FlgUsaPolComPdv = IsNull(FlgUsaPolComPdv,0),
           @pm_PrzRefPrcVen = IsNull(PrzRefPrcVen,0),
           @pm_FlgAltUnvItePdv = IsNull(FlgAltUnvItePdv,0),
		   @pm_CodVdrPdvCon = IsNull(CodVdrPdvCon,0),
           @pm_QtdDecPrcItePdv = IsNull(QtdDecPrcItePdv,0)
      From dbo.PARAM
      Where Cod_Estabe = @PCodEstabe

    -- PDECB
    Select @pe_NumPedVen = IsNull(Num_PedVen,0),
           @pe_CodOriPed = IsNull(Cod_OriPed,''),
           @pe_TipPed = IsNull(Tip_Pedido,''),
           @pe_CodPedCmpCli = IsNull(Cod_PedCmpCli,''),
           @pe_CodClient = IsNull(Cod_Client,0), 
           @pe_CodVended = IsNull(Cod_Vended,0), 
           @pe_CodOperad = IsNull(Cod_Operad,0), 
           @pe_IdPolCom = IsNull(Id_PolCom,0),
           @pe_CodTabPrz = IsNull(Cod_TabPrz,0),
		   @pe_CodMtvRej = IsNull(Cod_MtvRej,''),
           @pe_CodGrpClp = IsNull(Cod_GrpClp,0),
           @pe_FlgFatPedIntegral = ISNULL(Flg_FatPedIntegral, 0)
      From dbo.PDECB
     Where Cod_Estabe = @PCodEstabe
       And Cod_Layout = @PCodLayout
       And Num_Cnpj = @PNumCnpj
       And Cod_PedCli = @PCodPedCli
       And Num_Desdob = @PNumDesdob

    Set @WDesLayout = (Select Des_Layout From dbo.TBCLP Where Cod_Layout = @PCodLayout)

    -- TBLPG
    Set @WFlgBlqDscAutIte = 0
    Set @WTipImpPrcPdvCfg = ''
    Set @WFlgTemVdrVnc = 0
    Set @WFlgUsaVdrPar = 0

    if Exists(Select 1 From dbo.TBLPG Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout And Cod_Grupo = @pe_CodGrpClp)
      begin
        Select @WFlgBlqDscAutIte = IsNull(it.Flg_BlqDscAutIte,0),
               @WTipImpPrcPdvCfg = IsNull(it.Tip_ImpPrcPdv,0),
               @WFlgBlqAltPrcPol = IsNull(Flg_BlqAltPrcPol,0),
               @WFlgTemVdrVnc = Case 
                                  When Exists(Select top 1 Cod_Vended From dbo.LGXVD Where Cod_Estabe = it.Cod_Estabe and Cod_Layout = it.Cod_Layout and Cod_Grupo = it.Cod_Grupo) then Cast(1 as bit) 
                                  Else Cast(0 as bit) 
                                End,
               @WFlgUsaVdrPar = IsNull(Flg_UsaVdrPar,0)
          From dbo.TBLPG it
         Where it.Cod_Estabe = @PCodEstabe
           And it.Cod_Layout = @PCodLayout
           And it.Cod_Grupo = @pe_CodGrpClp
      end

    Set @WTipImpPrcPdv = @WTipImpPrcPdvCfg
    if @WTipImpPrcPdv = 'A'
      Set @WFlgBlqCriConCom = 1
    else
      Set @WFlgBlqCriConCom = 0

    if IsNull(@pe_NumPedVen,0) > 0
      Set @PNumPdv = @pe_NumPedVen

   if (@PNumPdv = 0) or (not Exists(Select Numero From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv))
      begin
        -- WMS
        Set @WFlgUsaWms = (Select dbo.FN_ModExtOk(HASHBYTES('MD5','WMS'),
		                                          HASHBYTES('MD5',(Select Num_Cnpj From dbo.ESTAB Where Cod_Estabe = @PCodEstabe))))

        if @pe_CodOriPed = '' Set @pe_CodOriPed = 'A'

        -- ajusta flags
        if @WFlgBlqWms = 1         -- nunca usa WMS
          Set @WFlgUsaWms = 0

        if @WFlgBlqPol = 1         -- nunca usa politica
          begin
            Set @pm_FlgUsaPolComPdv = 0
            Set @pe_IdPolCom = 0
          end
        
        Set @WTipFat = 'FAT'
        Set @WCodDig = 0
        Set @WFlgBlqWms = 0
        Set @WFlgBlqPol = 0

        Exec PR_IncluiPDVCB 'P', @PCodEstabe, @PNumPdv output, @pe_CodOriPed, @pe_CodClient, @WFlgUsaWms, @WTipFat,
                            @pe_CodVended, @pe_CodOperad, @WCodDig, @pe_IdPolCom, @pe_CodTabPrz, @PCodLayout,
                            @WFlgBlqWms, @WFlgBlqPol, @PMsgErr output

		Update dbo.PDECB
           Set Cod_MtvRej = 'CAD',
               Des_MtvRej = @PMsgErr
         Where Cod_Estabe = @PCodEstabe
           And Cod_Layout = @PCodLayout
           And Num_Cnpj   = @PNumCnpj
           And Cod_PedCli = @PCodPedCli
           And Num_Desdob = @PNumDesdob
           And @PMsgErr <> ''

        -- procedimento que simula EditCodClienteExit no EdPedVen
		-- já eh executado em PR_IncluiPDVCB
        --Exec PR_InfoDefaultPDVCB @PCodEstabe, @PNumPdv
      end  -- if @PNumPdv = 0

    Update pv
       Set pv.Status2 = 'X',    
           pv.Cod_PedCli = @PCodPedCli, 
           pv.Cod_PedCmpCli = Case 
                                When IsNull(pe.Cod_PedCmpCli,'') <> '' then IsNull(pe.Cod_PedCmpCli,'') 
                                Else @PCodPEdCli 
                              End,
           pv.Cod_PrjPde = IsNull(pe.Cod_Projeto,''),
           pv.Tip_Vencimento = '',
           pv.Observacao = pe.Observacao,     -- ''
           pv.Obs_NotFis = pe.Obs_NotFis,      -- ''
           pv.Qtd_Parcela = IsNull(pe.Qtd_Parcela,0), 
           pv.Qtd_PrzMed  = IsNull(pe.Qtd_PrzMed,0)*1.0,
           pv.Dat_LimEnvPrp = cast(pe.Dat_Encerra as smalldatetime)
      From dbo.PDVCB pv, dbo.PDECB pe
     Where pv.Cod_Estabe = @PCodEstabe
       And pv.Numero = @PNumPdv
       And pv.Status1 = 'P'     -- Pendente
       And ((pv.Status2 = 'A') or (pv.Status2 = 'X'))  -- em aberto    
       And pe.Cod_Estabe = @PCodEstabe
       And pe.Cod_Layout = @PCodLayout
       And pe.Num_Cnpj   = @PNumCnpj
       And pe.Cod_PedCli = @PCodPedCli
       And pe.Num_Desdob = @PNumDesdob

    -- registra num.pedido venda em PDECB (informação necessária ao incluir itens em PDVIT) em 25/08/2022
    Update dbo.PDECB
       Set Num_PedVen = @PNumPdv
     Where Cod_Estabe = @PCodEstabe
       And Cod_Layout = @PCodLayout
       And Num_Cnpj   = @PNumCnpj
       And Cod_PedCli = @PCodPedCli
       And Num_Desdob = @PNumDesdob

    -- inclui itens somente se pedido está "aberto"
    if Exists(Select Numero From dbo.PDVCB 
               Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv 
                 And Status1 = 'P' And ((Status2 = 'A') or (Status2 = 'X')))
      begin

        Declare @op_CfoNorInt int,
                @cl_Codigo int,
                @cl_FlgLicSauInv bit,
                @cl_FlgLicAnvInv bit,
                @pv_CodTipPed varchar(3)  -- 'PDV','COT'

        Select @WTipPrc = op.Tip_Prc,    -- ver tipo de transacao p/ escolher o preco a ser utilizado no pedido
               @op_CfoNorInt = IsNull(op.Cod_CfoNorInt,0),
               @WTipPrz = Substring(cb.Cod_OrigemPdv,2,1),
               @cl_Codigo = IsNull(cl.Codigo,0), 
               @cl_FlgLicSauInv = 0,
               @cl_FlgLicAnvInv = 0,
               @pv_CodTipPed = Case When cb.Tip_Pedido = 'C' then 'COT' Else'PDV' End
          From dbo.PDVCB cb 
               Left Outer Join dbo.TPOPE op on cb.Tip_Faturamento = op.Cod_Ope 
               Left Outer Join dbo.CLIEN cl on cb.Cod_Cliente = cl.Codigo 
         Where cb.Cod_Estabe = @PCodEstabe
           And cb.Numero = @PNumPdv
           And cb.Status1 = 'P'
           And ((cb.Status2 = 'A') or (cb.Status2 = 'X')) 

        -- flg licenças
        Set @cl_FlgLicSauInv = 0
        Set @cl_FlgLicAnvInv = 0
        if @cl_Codigo > 0
          begin
            Exec PR_AnalisaLicencaCliente @pv_CodTipPed, 'SAUDE',  @cl_Codigo, @cl_FlgLicSauInv output, @WMsgAux output
            Exec PR_AnalisaLicencaCliente @pv_CodTipPed, 'ANVISA', @cl_Codigo, @cl_FlgLicAnvInv output, @WMsgAux output
          end
         
        -- estoque fiscal
        Set @WFlgBlqEstFisNeg = 0
        if (IsNull((Select BlqEstFisNeg From dbo.PMEST Where Cod_Estabe = @PCodEstabe),0) = 1) and (@op_CfoNorInt > 0)
          Set @WFlgBlqEstFisNeg = 1

         -- coloca o pedido em processamento
        Update dbo.PDVCB 
           Set Status2 = 'X'
         Where Cod_Estabe = @PCodEstabe
           And Numero = @PNumPdv
           And Status2 <> 'X' 

        -- sequencial do item na PDVIT
        Set @WNumSeqIte = IsNull((Select max(Num_SeqDig) From dbo.PDVIT 
                                   Where Cod_Estabe = @PCodEstabe
                                     And Cod_Pedido = @PNumPdv),0) + 1

        -- inclui itens emm PDVIT
        Declare @WPFlgAchou bit,
                @WPLocFis varchar(15),
                @WPCodFab int,
                @WPFatCnvImpFat int,
                @WPPrcFab numeric(18,8),
                @WPPrcMaxCon numeric(18,8),
                @WPPrcRefFpb numeric(18,8),
                @WPPrcCusMinComMarkup numeric(18,8),
                @WPPrcTab numeric(18,8),
                @WPPrcTabBru numeric(18,8),
                @WPPrcUni numeric(18,8),
                @WPPrcMin numeric(18,8),
                @WPPrcUniLiqPer numeric(18,8),
                @WPFlgEmbDscPrc bit,
                @WPPerDscLin numeric(8,4),
                @WPPerDscPrz numeric(8,4),
                @WPPerDscVis numeric(8,4),
                @WPQtdPrzMax int,

                @WPPerDscPolCom numeric(8,4),
                @WPPerDscVisPolCom numeric(8,4),
                @WPPrcPolCom numeric(18,8),
                @WPQtdPrzPolCom int,
                @WPCodKitPrm int,
                @WPCodPromoc int,
                @WPFlgVerba bit,
                @WPFlgPolPrm bit,
                @WPVlrVrbDis numeric(18,4),

                @WPCodRej varchar(3),
                @WPDesMsg varchar(80),
                @WPCmp varchar(20),
                @WPNomUsuDbq varchar(35),
                @WPDesMsgDbq varchar(60),
                @WPQtdImpFat int, 
                @WPPrcUniImpFat numeric(18,8),
		        @WPCodLot varchar(20),
                @WPPrcUniPde numeric(18,8),
                @WPPerDscPde numeric(8,4),
                @WPCodPrjPde varchar(12),
                @WPNumSeqPdc varchar(6),
                @WPTipSai varchar(1),
                @WPC_PrcUni numeric(18,8),
                @WPC_PerDscIte numeric(8,4),
                @WPPrcUniLiqPdv numeric(18,8),
                @WPC_VlrDesconto numeric(18,8),
                @WPC_PrcTotal numeric(18,8),

                @WIte_Chave int = 0,
                @WIte_FlgDscInf bit,
                @WIte_FlgPrcInf bit,
                @WIte_FlgPrzInf bit,
                @WIte_FlgPolInf bit,
                @WIte_FlgBlqQtdPar bit,

				@WIte_CodPrdArq varchar(14),
		        @WIte_CodPrd int,
                @WIte_CodRej varchar(3),
                @WIte_FatCnvImpFat int,
                @WIte_FatAprPad smallint,
                @WIte_QtdPed int,
                @WIte_QtdBon int,
                @WIte_PrcUni numeric(18,4),
                @WIte_IdPolCom int,
                @WIte_PerDsc numeric(18,4),
                @WIte_PrcUniArq numeric(18,8),
                @WIte_PerDscArq numeric(8,4),

                @WIte_QtdPedInf int,
                @WIte_QtdBonInf int,
                @WIte_QtdSolInf int,
                @WIte_QtdAceInf int,
                @WIte_PrcUniInf numeric(18,8),
                @WIte_PerDscInf numeric(8,4),
                @WIte_DesUnvImpFat varchar(3),
				@WIte_DesAprImpFat varchar(12), 
                @WIte_PrcUniImpFat numeric(18,8),
                @WIte_CodProjeto varchar(12),
                @WIte_NumSeqPdc varchar(6),
                @WIte_TipSai varchar(1),
                @WIte_CodTipDsc varchar(1),
                @WIte_CodPrdEmbFec varchar(4), 
                @WIte_QtdEmbFec int,
                @WIte_PerDscEmbPrc numeric(8,4),

                @Wpr_PrcCusLiqEnt numeric(18,4),

                @pvit_CodLot varchar(20),
                @ap_FatCnvApr int,
                @ap_DesUnvApr varchar(3),
                @ap_DesApr varchar(12),

                @pc_FlgNegDsc bit,
                @pc_FlgBlqVerba bit,

				@WQtdPedAte int,
                @WQtdFisDsp int


        Declare @tb_PDEIT table(
          Chave int identity(1,1) primary key,
          Cod_PrdCli varchar(14), 
          Cod_Produt int, 
          Tip_Sai varchar(1), 
          Qtd_Pedido int, 
          Prc_Unitario numeric(18,4),
          Cod_TipDsc varchar(1), 
          Per_Desconto numeric(18,4), 
          Id_PolCom int, 
		  Cod_PrdEmbFec varchar(14),
          Qtd_Embala int,
          Fat_CnvImpFat int, 
          Fat_AprPad smallint,
          Des_UnvImpFat char(3),
          Des_AprImpFat varchar(12),
          Prc_UniImpFat numeric(18,8),
          Cod_Projeto varchar(12),
          Num_SeqPdc varchar(6),
          Per_DscEmbPrc numeric(18,4),
          Flg_PrcInf bit,
          Flg_DscInf bit,
          Flg_PrzInf bit,
          Flg_PolInf bit,
          Flg_BlqQtdPar bit,
          Prc_UnitarArq numeric(18,4),
          Per_DesconArq numeric(8,4)
        )

        -- seleciona registros candidatos
        Insert Into @tb_PDEIT
          Select Cod_PrdCli, IsNull(Cod_Produt,0), IsNull(Tip_Sai,''), IsNull(Qtd_Pedido,0), IsNull(Prc_Unitario,0), 
                 IsNull(Cod_TipDsc,''), IsNull(Per_Desconto,0), IsNull(Id_PolCom,0), IsNull(Cod_PrdEmbFec,''), IsNull(Qtd_Embala,0),
                 IsNull(Fat_CnvImpFat,0), IsNull(Fat_AprPad,0), IsNull(Des_UnvImpFat,''), IsNull(Des_AprImpFat,''), 
                 IsNull(Prc_UniImpFat,0), IsNull(Cod_Projeto,''), IsNull(Num_SeqPdc,''), IsNull(Per_DscEmbPrc,0),
				 IsNull(Flg_PrcInf,0), IsNull(Flg_DscInf,0), IsNull(Flg_PrzInf,0), IsNull(Flg_PolInf,0), IsNull(Flg_BlqQtdPar,0),
				 IsNull(Prc_UnitarArq,0), IsNull(Per_DesconArq,0)
            From dbo.PDEIT
           Where Cod_Estabe = @PCodEstabe
             And Cod_Layout = @PCodLayout
             And Num_Cnpj = @PNumCnpj
             And Cod_PedCli = @PCodPedCli
             And Num_Desdob = @PNumDesdob

        While Exists(Select 1 From @tb_PDEIT)
          BEGIN
            Select top 1 @WIte_Chave = t.Chave,
                         @WIte_CodPrdArq = t.Cod_PrdCli, 
                         @WIte_CodPrd = t.Cod_Produt,
                         @WIte_TipSai = t.Tip_Sai,
                         @WIte_QtdPed = t.Qtd_Pedido,
                         @WIte_PrcUni = t.Prc_Unitario,
                         @WIte_CodTipDsc = t.Cod_TipDsc, 
                         @WIte_PerDsc = t.Per_Desconto, 
                         @WIte_IdPolCom = t.Id_PolCom, 
                         @WIte_CodPrdEmbFec = t.Cod_PrdEmbFec, 
                         @WIte_QtdEmbFec = t.Qtd_Embala,
                         @WIte_FatCnvImpFat = t.Fat_CnvImpFat, 
                         @WIte_FatAprPad = t.Fat_AprPad, 
                         @WIte_DesUnvImpFat = t.Des_UnvImpFat, 
                         @WIte_DesAprImpFat = t.Des_AprImpFat, 
                         @WIte_PrcUniImpFat = t.Prc_UniImpFat, 
                         @WIte_CodProjeto = t.Cod_Projeto,
                         @WIte_NumSeqPdc = t.Num_SeqPdc,
                         @WIte_PerDscEmbPrc = t.Per_DscEmbPrc,
                         @WIte_FlgPrcInf = t.Flg_PrcInf, 
                         @WIte_FlgDscInf = t.Flg_DscInf, 
                         @WIte_FlgPrzInf = t.Flg_PrzInf, 
                         @WIte_FlgPolInf = t.Flg_PolInf, 
                         @WIte_FlgBlqQtdPar = t.Flg_BlqQtdPar,
                         @WIte_PrcUniArq = t.Prc_UnitarArq, 
                         @WIte_PerDscArq = t.Per_DesconArq
              From @tb_PDEIT t

            -- Tudofarma: Cod_TipDsc = '1' (industria) -> @WTipImpPrcPdv = 'A'
            if @WIte_CodTipDsc = '1' --desconto da industria
              begin
                Set @WIte_FlgDscInf = 1
                Set @WTipImpPrcPdv = @WTipImpPrcPdvCfg   -- aceita, rejeita ou ignora
              end
            else
            if @WIte_CodTipDsc = '0' --desconto distribuidor
              Set @WTipImpPrcPdv = 'I' 
				              
            Set @WIte_CodRej = ''
            Set @WQtdPedAte  = 0
            Set @WIte_QtdBon = 0
            if @WIte_FatCnvImpFat = 0 
              Set @WIte_FatCnvImpFat = 1
            if @WIte_FatAprPad = 0 
              Set @WIte_FatAprPad = 1

            if @WIte_CodPrd = 0 
              begin
                Set @WIte_CodRej = 'PRX'    -- produto invalido
              end

            -- inclui PDVIT
            if @WIte_CodPrd > 0
              begin

                Select @pvit_CodLot = IsNull(Cod_Lote,'') 
                  From dbo.PDVIT 
                 Where Cod_Estabe = @PCodEstabe
                   And Cod_Pedido = @PNumPdv
                   And Cod_Produto = @WIte_CodPrd
                 Order by Qtd_Pedido desc 

                if not Exists(Select Cod_Lote From dbo.PDVIT 
                               Where Cod_Estabe = @PCodEstabe
                                 And Cod_Pedido = @PNumPdv
                                 And Cod_Produto = @WIte_CodPrd) 
                  begin  

-------------------------  Confirmar se vem tudo calculado em PDEIT --------------------------------------------------------------------------------------------------------------------
                    if @WIte_FatCnvImpFat = 0 
                      Set @WIte_FatCnvImpFat = 1

                    if @WIte_FatAprPad = 0 
                      Set @WIte_FatAprPad = 1

                    if (@pm_FlgAltUnvItePdv = 1) and (@WIte_FatCnvImpFat = 1) and
                       Exists(Select Cod_Apr From dbo.PRXAP 
                               Where Cod_Produt = @WIte_CodPrd 
                                 And IsNull(Flg_Padrao,0) = 1 And IsNull(Fat_CnvApr,0) > 1) 
                      begin
                        Select @ap_DesApr = Des_Apr, 
                               @ap_FatCnvApr = IsNull(Fat_CnvApr,0), 
                               @ap_DesUnvApr = IsNull(Des_UnvApr,'') 
                          From dbo.PRXAP 
                         Where Cod_Produt = @WIte_CodPrd
                           And IsNull(Flg_Padrao,0) = 1 
                           And IsNull(Fat_CnvApr,0) > 1 

-----------------------------------------------------------------------------
                       Set @WIte_FatAprPad    = @ap_FatCnvApr
                       Set @WIte_FatCnvImpFat = @ap_FatCnvApr
                       Set @WIte_DesUnvImpFat = @ap_DesUnvApr
                       Set @WIte_DesAprImpFat = @ap_DesApr
                      end

                    if (@WIte_PrcUniImpFat = 0) and (@WIte_FatCnvImpFat > 1) 
                      Set @WIte_PrcUniImpFat = @WIte_PrcUni * @WIte_FatCnvImpFat

-------------------------------------------------------------------------------------------------------------

                    Set @WIte_QtdPedInf = @WIte_QtdPed*@WIte_FatAprPad
                    Set @WIte_QtdBonInf = @WIte_QtdBon*@WIte_FatAprPad
                    Set @WIte_PrcUniInf = @WIte_PrcUni/@WIte_FatAprPad
                    Set @WIte_PerDscInf = @WIte_PerDsc

--------------------------------------------------------------------------------------------------------------

                    if (@pe_IdPolCom = 0) and (@WIte_IdPolCom > 0)
                      begin
                        Set @pe_IdPolCom = @WIte_IdPolCom
                        --RegravaRegistroPdecb('POL')
                        Update dbo.PDECB
                           Set Id_PolCom = @pe_IdPolCom
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Layout = @PCodLayout
                           And Num_Cnpj = @PNumCnpj
                           And Cod_PedCli = @PCodPedCli
                           And Num_Desdob = @PNumDesdob
                      end

                    if (@WFlgTemVdrVnc = 1) and (@pe_CodVended = 0) 
                      begin
                        -- pega vendedor
                        if (@WIte_CodPrd > 0) and (@pe_CodClient > 0)
                          begin
                            Select @pe_CodVended = lg.Cod_Vended 
                              From dbo.LGXVD lg 
                                   Inner Join dbo.PRODU pr on pr.Codigo = @WIte_CodPrd
                             Where lg.Cod_Estabe = @PCodEstabe
                               And lg.Cod_Layout = @PCodLayOut
                               And lg.Cod_Grupo = @pe_CodGrpClp
                               And lg.Cod_Client = @pe_CodClient 
                               And lg.Cod_Fabric = pr.Cod_Fabricante
                          end
                         
                        if (@pe_CodVended = 0) and (@WFlgUsaVdrPar = 1)
                          Set @pe_CodVended = @pm_CodVdrPdvCon
                         
                        --RegravaRegistroPdecb('VDR')
                        Update dbo.PDECB
                           Set Cod_Vended = @pe_CodVended
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Layout = @PCodLayout
                           And Num_Cnpj = @PNumCnpj
                           And Cod_PedCli = @PCodPedCli
                           And Num_Desdob = @PNumDesdob
                           And @pe_CodVended > 0
                      end

-- @WIte_FatCnvImpFat, : pode ter sido alterado devido apresentação padrão: 
-- @WIte_QtdPedInf, 
-- @WIte_QtdBonInf
-- @WIte_PrcUniInf

                    Exec PR_InfoDefaultPDVIT @pm_FlgUsaPolComPdv, @PCodEstabe, @PNumPdv, @WIte_CodPrd, 
                                             @WIte_QtdPedInf, @WIte_QtdBonInf, @WIte_IdPolCom output, @WFlgBlqDscAutIte,
                                             @WPFlgAchou output,
                                             @WPLocFis output,
                                             @WPCodFab output,
                                             @WPPrcFab output,
                                             @WPPrcMaxCon output,
                                             @WPPrcRefFpb output,
                                             @WPPrcTab output,
                                             @WPPrcTabBru output,
                                             @WPFatCnvImpFat output,     -- ???? @WIte_FatCnvImpFat
                                             @WPPrcUni output,
                                             @WPPrcCusMinComMarkup output,
                                             @WPPerDscPolCom output,
                                             @WPPerDscVisPolCom output,
                                             @WPPrcPolCom output,
                                             @WPQtdPrzPolCom output,
                                             @WPFlgVerba output,
                                             @WPFlgPolPrm output,
                                             @WPCodKitPrm output,
                                             @WPCodPromoc output,
                                             @WPFlgEmbDscPrc output, 
                                             @WPQtdPrzMax output,
                                             @WPPerDscLin output,
                                             @WPPerDscPrz output,
                                             @WPPerDscVis output,
                                             @WPPrcUniLiqPer output

                    if @WPFlgAchou = 1
                      begin
                        if @pm_FlgUsaPolComPdv = 0
                          begin
                            if @WTipImpPrcPdv <> 'I' 
                              if (@WIte_FlgDscInf = 1) or (@WIte_FlgPrcInf = 1)
                                begin
                                  -- variaveis ref. desc. a ser considerado
                                  Set @WPerDscArq = 0
                                  if (@WIte_FlgDscInf = 1) and ((@WTipImpPrcPdv = 'A') or (@WTipImpPrcPdv = 'R')) and (IsNull(@WIte_PerDscEmbPrc,0) = 0) 
                                    Set @WPerDscArq = @WIte_PerDsc

                                  Set @WPrcUniArq = @WPPrcUni

                                  if (@WIte_FlgPrcInf = 1) and ((@WTipImpPrcPdv = 'A') or (@WTipImpPrcPdv = 'R'))
                                    Set @WPrcUniArq = @WIte_PrcUniInf

                                  if Isnull(@WPrcUniArq,0) = IsNull(@WPPrcUni,0)
                                    Set @WPerDsc = @WPerDscArq
                                  else
                                    begin
                                      Set @WPrcLiqArq = Round(@WPrcUniArq*(1-@WPerDscArq/100),@pm_QtdDecPrcItePdv)
                                      if @WPPrcUni > @WPrcLiqArq 
                                         Set @WPerDsc = Round((@WPPrcUni-@WPrcLiqArq)*100/@WPPrcUni,2)
                                      else
                                        Set @WPerDsc = @WIte_PerDscEmbPrc
                                    end

                                  Set @WPPrcUni = @WPrcUniArq
                                  Set @WPPerDscLin = @WPerDsc
                                  Set @WPPerDscPrz = @WPerDsc
                                  Set @WPPerDscVis = @WPerDsc
                                end
                          end  -- if @pm_FlgUsaPolComPdv = 0

                        if @pm_FlgUsaPolComPdv = 1
                          begin
                            Set @pc_FlgNegDsc = 0
                            Set @pc_FlgBlqVerba = 0
                            
                            Select @pc_FlgNegDsc = IsNull(Flg_NegDsc,0), 
                                   @pc_FlgBlqVerba = Case 
                                                       When ((IsNull(Flg_AcuVrbPos,0) = 0) and (IsNull(Flg_AcuVrbNeg,0) = 0)) then 1 
                                                       Else 0 
                                                     End
                              From dbo.POCOM 
                             Where Id_PolCom = @WIte_IdPolCom 

                            --  politica de comercialização (não alterava preço unitario), somente desconto, e, se estiver configurado para permitir negociação
                            if ((@pc_FlgNegDsc = 1) and (@WTipImpPrcPdv <> 'I'))
                              begin
                                if (@WIte_FlgDscInf = 1) or (@WIte_FlgPrcInf = 1) 
                                  begin
                                    -- variaveis ref. desc. a ser considerado
                                    Set @WPerDscArq = 0
                                    if (@WIte_FlgDscInf = 1) and ((@WTipImpPrcPdv = 'A') or (@WTipImpPrcPdv = 'R')) and (IsNull(@WIte_PerDscEmbPrc,0) = 0) 
                                      Set @WPerDscArq = @WIte_PerDsc
                            
                                    Set @WPrcUniArq = @WPPrcUni
                                    if (@WIte_FlgPrcInf = 1) and ((@WTipImpPrcPdv = 'A') or (@WTipImpPrcPdv = 'R')) 
                                      Set @WPrcUniArq = @WIte_PrcUniInf
                            
                                    --  verifica se permite alterar preço da politica
                                    if @WFlgBlqAltPrcPol = 0 
                                      begin
                                        Set @WPPrcUni = @WPrcUniArq
                                        Set @WPerDsc  = @WPerDscArq
                                      end
                                    else
                                      begin
                                        if Round(@WPrcUniArq,2) = Round(@WPPrcUni,2) 
                                          Set @WPerDsc = @WPerDscArq
                                        else
                                          begin
                                            Set @WPrcLiqArq = Round(@WPrcUniArq*(1-@WPerDscArq/100),@pm_QtdDecPrcItePdv)
                                            if @WPPrcUni > @WPrcLiqArq 
                                              Set @WPerDsc = Round((@WPPrcUni-@WPrcLiqArq)*100/@WPPrcUni,2)
                                            else
                                              Set @WPerDsc = @WIte_PerDscEmbPrc
                                          end
                                      end
                            
                                    Set @WPPerDscPrz = @WPerDsc
                                    Set @WPPerDscVis = @WPerDsc
                                  end
                              end  -- if ((@pc_FlgNegDsc = 1) and (@WTipImpPrcPdv <> 'I'))
                          end  -- if @pm_FlgUsaPolComPdv = 1

                        Set @WPCodLot = '*'

                        if @WIte_FatCnvImpFat = 0 
                          Set @WIte_FatCnvImpFat = 1
                       
                        -- estoque fiscal negativo
                        if @WFlgBlqEstFisNeg = 1
                          begin
                            Set @WQtdFisDsp = dbo.FN_SldFiscalDisponPrd(@PCodEstabe,@WIte_CodPrd)
                            if @WIte_QtdPedInf > @WQtdFisDsp
                              begin
                                if @WQtdFisDsp < 0 Set @WQtdFisDsp = 0
                                Set @WIte_QtdPedInf = @WQtdFisDsp
                              end
                          end

/* abaixo                       
                        if @WPFatCnvImpFat <> @WIte_FatCnvImpFat
                          Set @WPFatCnvImpFat = @WIte_FatCnvImpFat   -- em 23/08/2020

                        Set @WPQtdImpFat = Round((@WIte_QtdPedInf + @WIte_QtdBonInf)/@WIte_FatCnvImpFat,0)
                        Set @WPPrcUniImpFat = @WPPrcUni * @WIte_FatCnvImpFat
*/
                        Set @WPPrcUniPde = @WPPrcUni
                        if @WTipPrz = 'L' 
                          Set @WPPerDscPde = @WPPerDscLin  -- Per_Desconto
                        else
                          Set @WPPerDscPde = @WPPerDscPrz  -- Per_Descon

                        Set @WPCodPrjPde = @WIte_CodProjeto
                        Set @WPNumSeqPdc = @WIte_NumSeqPdc
                        Set @WPTipSai = @WIte_TipSai
                     
                        --  calcfields 
                        -- arredonda prc_unitario conforma parametro do sistema
                        Set @WPPrcUni = Round(@WPPrcUni,@pm_QtdDecPrcItePdv)  -- novo

                        if @WPFatCnvImpFat <> @WIte_FatCnvImpFat
                          Set @WPFatCnvImpFat = @WIte_FatCnvImpFat   -- em 23/08/2020
                        Set @WPQtdImpFat = Round((@WIte_QtdPedInf + @WIte_QtdBonInf)/@WIte_FatCnvImpFat,0)  -- calculado na trigger
                        Set @WPPrcUniImpFat = @WPPrcUni * @WIte_FatCnvImpFat  -- calculado na trigger

                        Set @WPC_PrcUni = @WPPrcUni
                        if @WTipPrz = 'L'
                          Set @WPC_PerDscIte = @WPPerDscLin
                        else
                          Set @WPC_PerDscIte = @WPPerDscPrz
                     
                        --  calcula preco unitario liquido
                        Set @WPPrcUniLiqPdv = @WPPrcUni*(1-@WPC_PerDscIte/100)
                        
                        Set @WPC_VlrDesconto = 0
                        if @WPFlgEmbDscPrc = 1
                          begin
                            if @WTipPrz = 'L'
                              Set @WPC_PrcUni = @WPPrcUni*(1-@WPPerDscLin/100)
                            else
                              Set @WPC_PrcUni = @WPPrcUni*(1-@WPPerDscPrz/100)
                        
                            Set @WPC_PerDscIte = 0
                          end
                        
                        Set @WPC_VlrDesconto = Round(@WIte_QtdPedInf*@WPC_PrcUni,2) - Round(@WIte_QtdPedInf*@WPC_PrcUni*(1-@WPC_PerDscIte/100),2)
                        
                        Set @WPC_PrcTotal = Round(@WIte_QtdPedInf*@WPC_PrcUni,2) - @WPC_VlrDesconto
                        
                        Set @WFlgSnhEsp = 0 
                        Set @WNomUsuSnhEsp = ''
                        Set @WFlgCriVrb = 0        -- coloquei

                       -- preço mínimo
                        Set @WPPrcMin = 0   -- calcula na critica
                        Set @WPVlrVrbDis = 0 -- calcula na critica

						-- tem que informar atual: @WPPrcPolCom, @WPQtdPrzPolCom, @WPPerDscPolCom, @WPPerDscVisPolCom  (InfoDefault)

                        --  normaliza campos: @WTipImpPrcPdv = (A)ceita, (R)ejeita, (I)gnora 
                        if @WTipImpPrcPdv = 'A'
                          Set @WFlgBlqCriConCom = 1
                        else
                          Set @WFlgBlqCriConCom = 0

                        if ((@WIte_FlgPrcInf = 1) or (@WIte_FlgDscInf = 1)) and 
                           (@WTipImpPrcPdv = 'A') 
                          Set @WFlgBlqCriPrcVen = 1 
                        else
                          Set @WFlgBlqCriPrcVen = 0

                        Exec PR_CriticaItemPDVIT @pm_FlgUsaPolComPdv, @PCodEstabe, @PNumPdv, @WIte_CodPrd, @WPTipSai,
                                                 @WIte_IdPolCom, @WIte_QtdPedInf output, @WIte_QtdBonInf, @WPQtdPrzMax output,
                                                 @WPPrcUni, @WPPerDscLin output, @WPPerDscPrz output, @WPPerDscVis output, 
                                                 @WPFatCnvImpFat, @WPQtdImpFat output, @WPPrcUniImpFat,
                                                 @WPPrcTabBru, @WPPrcTab output, @WPPrcUniLiqPer output, @WPPrcMin,
                                                 @WPCodKitPrm, @WPPrcCusMinComMarkup, 
                                                 @WPPrcPolCom output, @WPQtdPrzPolCom output, @WPPerDscPolCom output, @WPPerDscVisPolCom output, 
                                                 @WPFlgVerba output, @WPVlrVrbDis, @WFlgSnhEsp, @WNomUsuSnhEsp,
                                                 @WIte_FlgBlqQtdPar, @WFlgBlqCriConCom, @WFlgBlqCriPrcVen, @WFlgCriVrb, @WFlgBlqDscAutIte,
                                                 @WIte_QtdSolInf output, @WIte_QtdAceInf output, @WPFlgPolPrm output, @WPCodPromoc output, 
                                                 @WPCodRej output, @WPDesMsg output, @WPCmp output, @WPNomUsuDbq output, @WPDesMsgDbq  output

                    --Set @WIte_QtdPedInf = @WIte_QtdPed*@WIte_FatAprPad
                    --Set @WIte_QtdBonInf = @WIte_QtdBon*@WIte_FatAprPad
                    --Set @WIte_PrcUniInf = @WIte_PrcUni/@WIte_FatAprPad
---------------------------------------------------------------------------------------------------

                        if (@WPDesMsg = '') or (Substring(@WPCodRej,1,2) = 'PZ')  
                          begin
                            Set @WPCodRej = ''
                            Set @WPDesMsg = ''
                          end
                        else
                          begin
                            Set @WIte_QtdPedInf = 0
                            Set @WIte_QtdBonInf = 0
                          end

                        Insert Into PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai)
                          Values (@PCodEstabe, @PNumPdv, @WIte_CodPrd, @WPCodLot, @WPTipSai)

                        Update PDVIT
                           Set Num_SeqDig = @WNumSeqIte,
                               Qtd_Pedido = @WIte_QtdPedInf, 
                               Qtd_Bonificacao = @WIte_QtdBonInf, 
							   Id_PolCom = @WIte_IdPolCom, 
							   Loc_Fisica = @WPLocFis,   
							   Cod_Fabricante = @WPCodFab,
                               Qtd_PrzMax = @WPQtdPrzMax, 
							   Prc_Fabric = @WPPrcFab, 
							   Prc_MaxCon = @WPPrcMaxCon, 
							   Prc_RefFpb = @WPPrcRefFpb,   
							   Prc_Tabela = @WPPrcTab, 
							   Prc_TabBru = @WPPrcTabBru, 
                               Prc_Unitario = @WPPrcUni, 
							   Per_Desconto = @WPPerDscLin, 
							   Per_Descon = @WPPerDscPrz,   
							   Per_DscVis = @WPPerDscVis,  
							   Flg_Verba = @WPFlgVerba,  
							   Prc_CusMinComMarkup = @WPPrcCusMinComMarkup, 
                               Qtd_PrzPolCom = @WPQtdPrzPolCom, 
							   Prc_PolCom = @WPPrcPolCom, 
							   Per_DscPolCom = @WPPerDscPolCom, 
							   Per_DscVisPolCom = @WPPerDscVisPolCom,  
							   Cod_KitPrm = @WPCodKitPrm,    
							   Cod_Promocao = @WPCodPromoc,
                               Fat_CnvImpFat = @WIte_FatCnvImpFat, 
							   Qtd_ImpFat = @WPQtdImpFat, 
							   Prc_UniImpFat = @WPPrcUniImpFat, 
							   Des_UnvImpFat = @WIte_DesUnvImpFat, 
							   Des_AprImpFat = @WIte_DesAprImpFat, 
                               Prc_UniPde = @WPPrcUniPde, 
							   Per_DscPde = @WPPerDscPde, 
							   Cod_PrjPde = @WPCodPrjPde, 
							   Num_SeqPdc = @WPNumSeqPdc, 
                               Flg_PrcUniDsc = @WPFlgEmbDscPrc, 
							   C_PrcUni = @WPC_PrcUni, 
							   C_PerDscIte = @WPC_PerDscIte, 
							   C_VlrDesconto = @WPC_VlrDesconto, 
                               C_PrcTotal = @WPC_PrcTotal, 
							   Prc_UniLiqPer = @WPPrcUniLiqPer, 
							   Qtd_Solicitado = @WIte_QtdSolInf, 
							   Qtd_Acerto = @WIte_QtdAceInf,
                               Flg_PolPrm = @WPFlgPolPrm, 
							   Cod_MtvRej = @WPCodRej, 
							   Des_MtvRej = Substring(@WPDesMsg,1,80), 
							   Nom_UsuDesbloq = Substring(@WPNomUsuDbq,1,15), 
							   Des_MsgDesbloq = Substring(@WPDesMsgDbq,1,60)
                         Where Cod_Estabe  = @PCodEstabe
                           And Cod_Pedido  = @PNumPdv 
                           And Cod_Produto = @WIte_CodPrd 
                           And Cod_Lote    = @WPCodLot 
                           And Tip_Sai     = @WPTipSai

                        Set @WNumSeqIte = @WNumSeqIte + 1
   
                        --  abate quantidade atendida
                        Update it 
                           Set it.Qtd_Pedido = Round(it.Qtd_Pedido*(1-IsNull(lg.Per_AbatimQtd,0)/100),0) 
                          From dbo.PDVIT it 
                               Inner Join dbo.PDVCB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Cod_Pedido = cb.Numero 
                               Inner JOIN dbo.LGXGC lg on lg.Cod_Estabe = cb.Cod_Estabe and lg.Cod_Layout = @PCodLayout And
                                                          lg.Cod_Grupo = @pe_CodGrpClp and lg.Cod_GrpCli = cb.Cod_GrpCli 
                         Where cb.Cod_Estabe  = @PCodEstabe
                           And cb.Numero      = @PNumPdv
                           And it.Cod_Produto = @WIte_CodPrd 
                           And it.Cod_Lote    = @WPCodLot
                           And it.Tip_Sai     = @WPTipSai
                           And IsNull(lg.Per_AbatimQtd,0) > 0 
                           And it.Qtd_Pedido >= IsNull(lg.Qtd_AbatimMin,0) 

                        --  atualiza motivo qdo for o caso
                        Update it 
                           Set it.Cod_MtvRej = Case 
                                                 When it.Qtd_Pedido > 0 then 'ES-' 
                                                 Else 'ES0'
                                               End 
                          From dbo.PDVIT it 
                         Where it.Cod_Estabe = @PCodEstabe
                           And it.Cod_Pedido = @PNumPdv
                           And it.Cod_Produto = @WIte_CodPrd 
                           And it.Cod_Lote = @WPCodLot
                           And it.Tip_Sai = @WPTipSai
                           And it.Qtd_Pedido < it.Qtd_Solicitado 
                           And IsNull(it.Cod_MtvRej,'') = '' 
                      end  -- if @WPFlgAchou = 1
                    else
                      begin
                        Set @WIte_CodRej = 'PRX'    --  produto invalido
                      end

                  end  

                else
                  begin
                    -- acumula em PDVIT
                    Update dbo.PDVIT 
                       Set Qtd_Pedido = Qtd_Pedido + @WIte_QtdPedInf
                     Where Cod_Estabe = @PCodEstabe
                       And Cod_Pedido = @PNumPdv
                       And Cod_Produto = @WIte_CodPrd
                       And Cod_Lote = @pvit_CodLot
                  end

                -- registra falta e motivo de rejeicao
                Set @WFatCnvCxaFec = 1
                if (@WIte_CodPrdEmbFec <> '') and (@WIte_QtdEmbFec > 0) 
                  Set @WFatCnvCxaFec = @WIte_QtdEmbFec

                Exec PR_VerificaFaltasPdv false, @PCodEstabe, @PNumPdv, @WIte_CodPrd, @WFatCnvCxaFec, @WTipPrz,
                                          @WQtdPedAte output, @WIte_PrcUniInf output, @WIte_PerDscInf output, @WIte_CodRej output

              end  --if @WIte_CodPrd > 0
            else
              begin
                Set @WQtdPedAte = 0
              end

            -- aquix WQtdPedAte converter WIte_PrcUni
            if @WIte_PrcUni = 0
              Set @WIte_PrcUni = Round((@WIte_PrcUniInf*@WIte_FatAprPad),@pm_QtdDecPrcItePdv)

            if (@WIte_PrcUniImpFat = 0) and (@WIte_FatCnvImpFat > 1) 
              Set @WIte_PrcUniImpFat = Round((@WIte_PrcUniInf*@WIte_FatAprPad),@pm_QtdDecPrcItePdv) * @WIte_FatCnvImpFat

            Set @WQtdPedAte = @WQtdPedAte/@WIte_FatAprPad

/*
            -- Atualizar PDEIT.Cod_MtvRej : @WIte_CodRej
            Update dbo.PDEIT
               Set Qtd_Atendi    = @WQtdPedAte,
                   Prc_Unitario  = @WIte_PrcUni,
                   Per_Desconto  = @WIte_PerDsc,
                   Cod_MtvRej    = @WIte_CodRej,
                   Cod_MtvRejOri = @WIte_CodRej,
                   Fat_CnvImpFat = @WIte_FatCnvImpFat,
                   Fat_AprPad    = @WIte_FatAprPad,
                   Des_UnvImpFat = @WIte_DesUnvImpFat,
                   Des_AprImpFat = @WIte_DesAprImpFat,
                   Prc_UniImpFat = @WIte_PrcUniImpFat
             Where Cod_Estabe = @PCodEstabe
               And Cod_Layout = @PCodLayout
               And Num_Cnpj   = @PNumCnpj
               And Cod_PedCli = @PCodPedCli
               And Num_Desdob = @PNumDesdob
               And Cod_PrdCli = @WIte_CodPrdArq
*/
            Delete 
              From @tb_PDEIT 
             Where Chave = @WIte_Chave
          end

      end  

------------------------------------------------------------------------------------------------------------------------------------------------------
    -- Finaliza
    Update dbo.PDVCB 
       Set Status2 = 'A',
           Cod_LayoutPde = @PCodLayout,
           Des_LayoutPde = @WDesLayout
     Where Cod_Estabe = @PCodEstabe
       And Numero = @PNumPdv
       And Status2 = 'X'

    Update dbo.PDECB
       Set Sta_Pedido = '1', 
           Num_PedVen = @PNumPdv,
           Msg_Erro = Substring(@PMsgErr,1,400)
    Where Cod_Estabe = @PCodEstabe
      And Cod_Layout = @PCodLayout
      And Num_Cnpj   = @PNumCnpj
      And Cod_PedCli = @PCodPedCli
      And Num_Desdob = @PNumDesdob
      And Sta_Pedido = '0'

    Update dbo.PDEIT
       Set Cod_MtvRej    = 'PRX',
           Cod_MtvRejOri = 'PRX'
     Where Cod_Estabe = @PCodEstabe
       And Cod_Layout = @PCodLayout
       And Num_Cnpj   = @PNumCnpj
       And Cod_PedCli = @PCodPedCli
       And Num_Desdob = @PNumDesdob
       And Cod_Produt = 0

    Update it
       Set it.Cod_MtvRej    = ipv.CodMtvRej, 
	       it.Cod_MtvRejOri = ipv.CodMtvRej, 
	       --it.Des_MtvRej, 
		   it.Qtd_Atendi    = ipv.QtdPdv,
		   it.Prc_Unitario  = ipv.PrcUnitar,
		   it.Per_Desconto  = ipv.PerDescon,
		   it.Fat_CnvImpFat = ipv.FatCnvImp,
		   it.Fat_AprPad    = ipv.FatAprPad,
		   it.Des_UnvImpFat = ipv.DesUnvImp,
		   it.Des_AprImpFat = ipv.DesAprImp,
		   it.Prc_UniImpFat = ipv.PrcUniImp
      From dbo.PDECB cb
           Inner Join dbo.PDEIT it on cb.Cod_Estabe = it.Cod_Estabe and 
	                                  cb.Cod_Layout = it.Cod_Layout and
	                                  cb.Num_Cnpj = it.Num_Cnpj and
		                              cb.Cod_PedCli = it.Cod_PedCli and
      				                  cb.Num_Desdob = it.Num_Desdob
           Inner Join (Select Cod_Estabe, Cod_Pedido, Cod_Produto,
                              QtdPdv = sum(Qtd_Pedido+Qtd_Bonificacao),
                              CodMtvRej = max(IsNull(Cod_MtvRej,'')),
                              PrcUnitar = max(Prc_Unitario),
                              PerDescon = max(Per_Desconto),
                              FatCnvImp = max(Fat_CnvImpFat),
                              FatAPrPad = @WIte_FatAprPad,
                              DesUnvImp = max(Des_UnvImpFat),
                              DesAPrImp = max(Des_AprImpFat),
                              PrcUniImp = max(Prc_UniImpFat)
                         From dbo.PDVIT
                        Where Cod_Estabe = @PCodEstabe
                          And Cod_Pedido = @PNumPdv
                        Group by Cod_Estabe, Cod_Pedido, Cod_Produto) ipv on it.Cod_Estabe = ipv.Cod_Estabe and 
                                                                             cb.Num_PedVen = ipv.Cod_Pedido and 
                                                                             it.Cod_Produt = ipv.Cod_Produto 
     Where cb.Cod_Estabe = @PCodEstabe
       And cb.Cod_Layout = @PCodLayout
       And cb.Num_Cnpj   = @PNumCnpj
       And cb.Cod_PedCli = @PCodPedCli
       And cb.Num_Desdob = @PNumDesdob


    -- PDEIT.Qtd_Atendi deve está alimentado antes do cálculo do total
    declare @VlrTotal numeric(18,8)
	set @VlrTotal = 
			Round((Select Sum(Round(Qtd_Atendi*Prc_Unitario*(1-IsNull(Per_Desconto,0)/100),2)) 
				   From dbo.PDEIT 
				   Where Cod_Estabe = @PCodEstabe 
				     And Cod_Layout = @PCodLayout 
					 And Num_Cnpj = @PNumCnpj 
					 And Cod_PedCli = @PCodPedCli 
					 And Num_Desdob = @PNumDesdob),2)
	set @VlrTotal = ISNULL(@VlrTotal, 0)

    Update dbo.PDECB
       Set Vlr_Total = @VlrTotal
    Where Cod_Estabe = @PCodEstabe
      And Cod_Layout = @PCodLayout
      And Num_Cnpj   = @PNumCnpj
      And Cod_PedCli = @PCodPedCli
      And Num_Desdob = @PNumDesdob
      And ISNULL(Vlr_Total, 0) <> @VlrTotal


    --  verifica se pedido pode ser rejeitado
    Exec PR_RejeitaPDVCB @PCodEstabe, @PNumPdv, @pe_FlgFatPedIntegral, @WPCodRej output, @WPDesMsg output

    if @WPCodRej <> ''
      begin
        if Exists(Select Numero From dbo.PDVCB 
                   Where Cod_Estabe = @PCodEstabe
                     And Numero = @PNumPdv
                     And Status1 = 'P'
                     And ((Status2 = 'A') or (Status2 = 'X')))
          begin
            Delete From dbo.PDVCB 
              Where Cod_Estabe = @PCodEstabe
              And Numero = @PNumPdv
   
            Set @PNumPdv = 0

            -- zera qtds atendidas em PDEIT
            Update dbo.PDEIT 
               Set Qtd_Atendi = 0
             Where Cod_Estabe = @PCodEstabe
               And Cod_Layout = @PCodLayout
               And Num_Cnpj = @PNumCnpj
               And Cod_PedCli = @PCodPedCli
               And Num_Desdob = @PNumDesdob
   
            -- motivos de rejeicao
            if not ((@WDesLayout = 'CLAMED') or
                    (@WDesLayout = 'PDVLINK_TEUTO') or
                    (@WDesLayout = 'PDVLINK_AUGEFARMA') or 
                    (@WDesLayout = 'PDVLINK_INOVA') or 
                    (@WDesLayout = 'PDVLINK_REDEMED') or 
                    (@WDesLayout = 'PDVLINK_NATULAB') or
                    (@WDesLayout = 'WEBLINE') or 
					          (@WDesLayout = 'CALLFARMA') or
										(@WDesLayout = 'CLOSEUP')) 
              begin
                Update dbo.PDEIT 
                   Set Cod_MtvRej = @WPCodRej,
                       Des_MtvRej = Substring(@WPDesMsg,1,80)
                 Where Cod_Estabe = @PCodEstabe
                   And Cod_Layout = @PCodLayout
                   And Num_Cnpj   = @PNumCnpj
                   And Cod_PedCli = @PCodPedCli
                   And Num_Desdob = @PNumDesdob
                   And IsNull(Cod_MtvRej,'') = ''
              end  -- if not ((@WDesLayout = 'WEBLINE') or

            Update dbo.PDECB 
               Set Vlr_Total = 0,
                   Num_PedVen = 0, 
                   Cod_MtvRej = @WPCodRej, 
                   Des_MtvRej = Substring(@WPDesMsg,1,40)  
             Where Cod_Estabe = @PCodEstabe
               And Cod_Layout = @PCodLayout
               And Num_Cnpj   = @PNumCnpj
               And Cod_PedCli = @PCodPedCli
               And Num_Desdob = @PNumDesdob

          end  -- if Exists(Select Numero From dbo.PDVCB 
      end  -- if @WPCodRej <> ''

    if @@trancount > 0
      COMMIT TRANSACTION
  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_Verifica_Divergencia_PRXESxPRLOT_PRLTL]
@DesLocal varchar(80),  -- identificação da rotina
@CodEstabe int,         -- -1: todos os estabelecimentos
@CodProdut int = 0      --  0: todos os produtos

AS

SET NOCOUNT ON

if Exists(Select 1 From PARAM
           Where IsNull(FlgRegistraLogDivergencia,0) = 0)
  begin
    RETURN
  end


BEGIN

Declare @CodPrdIni int,
        @CodPrdFin int

if @CodProdut > 0
  begin
    Set @CodPrdIni = @CodProdut
    Set @CodPrdFin = @CodProdut
  end
else
  begin
    Set @CodPrdIni = 0
    Set @CodPrdFin = 2147483647
  end
  
if Exists(Select p.Cod_Produt
            From PRXES p 
          Where (( (@CodEstabe > -1 ) and (p.Cod_Estabe = @CodEstabe)  ) or 
                 ( (@CodEstabe = -1 ) and (p.Cod_Estabe > @CodEstabe)  ))
            And p.Cod_Produt between @CodPrdIni and @CodPrdFin
            And ((p.Qtd_Fisico <> dbo.FN_EstoqueFisicoPrdLote(p.Cod_Estabe, p.Cod_Produt, 'TODOS'))  or 
                 (p.Qtd_Dispon >  dbo.FN_EstoqueDisponivelPrdLote(p.Cod_Estabe, p.Cod_Produt, 'TODOS'))))
  begin
    
    Declare @Tab Table(
      Chave Int Identity(1,1) PRIMARY KEY
    
    , Cod_Estabe int
    , Cod_Produt int
    , Qtd_FisPrd int
    , Qtd_FisLot int
    , Qtd_Difere int
    )
    
    Insert Into @Tab
      Select p.Cod_Estabe,
	         p.Cod_Produt, p.Qtd_Fisico,
             QtdFisLot = dbo.FN_EstoqueFisicoPrdLote(p.Cod_Estabe, p.Cod_Produt, 'TODOS'),
             Diferenca = p.Qtd_Fisico - dbo.FN_EstoqueFisicoPrdLote(p.Cod_Estabe, p.Cod_Produt, 'TODOS')
        From dbo.PRXES p 
       Where (( (@CodEstabe > -1 ) and (p.Cod_Estabe = @CodEstabe)  ) or 
              ( (@CodEstabe = -1 ) and (p.Cod_Estabe > @CodEstabe)  ))
         And p.Cod_Produt between @CodPrdIni and @CodPrdFin
         And ((p.Qtd_Fisico <> dbo.FN_EstoqueFisicoPrdLote(p.Cod_Estabe, p.Cod_Produt, 'TODOS'))  or 
              (p.Qtd_Dispon >  dbo.FN_EstoqueDisponivelPrdLote(p.Cod_Estabe, p.Cod_Produt, 'TODOS')))

    Insert Into dbo.LOGDIVESTPRDLOT
      Select Cod_Estabe, Cod_Produt, Qtd_Difere, Qtd_FisPrd,
             Qtd_FisLot, @DesLocal, GetDate()
        From @Tab tb
       Where not Exists(Select 1 
                          From dbo.LOGDIVESTPRDLOT lg 
                         Where tb.Cod_Estabe = lg.Cod_Estabe 
                           and tb.Cod_Produt = lg.Cod_Produt 
                           and tb.Qtd_Difere = lg.Qtd_Difere
                           and tb.Qtd_FisPrd = lg.Qtd_FisPrd
                           and tb.Qtd_FisLot = lg.Qtd_FisLot)

  end  -- if Exists(

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_SolicitaLotesPDV]
@CodEstabe int,
@CodPed int,       -- num. do pedido
@QtdMesVctMin int  -- qtd meses vencimento minimo de lotes DESCARTAR  

AS

SET NOCOUNT ON 

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(Cast(Year(@Now) as varchar)+'-'+Cast(Month(@Now) as varchar)+'-'+Cast(Day(@Now) as varchar)+' 00:00:00' as smalldatetime)

Declare @FlgErr bit,
        @StrMsg varchar(400)

Set @FlgErr = 0
Set @StrMsg = IsNull((Select MsgErr = Case
                                        When CharIndex(Status2,';N;D;') > 0 then 'Pedido já faturado'
                                        When (Status1 <> 'P') or (Status2 <> 'F') then 'Pedido não está pendente/fechado'
                                        When IsNull(Bloqueio,'') <> '' then 'Pedido está bloqueado'
                                        When IsNull(Flg_Wms,0) = 0 then 'Pedido não permite solicitar lotes'
                                        Else ''
                                      End
                        From PDVCB
                       Where Cod_Estabe = @CodEstabe
                         And Numero = @CodPed),'')
if @StrMsg <> ''
  Set @FlgErr = 1


/*
-- retirar esta critica quando o sistema permitir solicitação de lote específico parcial
if (@FlgErr = 0) and
   Exists(Select top 1 1 From PDVLT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed)
  begin
    Set @FlgErr = 1
    Set @StrMsg = 'Pedido já solicitou lotes'
  end
*/

-- verifica se existe quantidades em PDVLT inválidas
if (@FlgErr = 0) and
   Exists(Select lt.Cod_Produt, lt.QtdLot, it.QtdIte 
             From (Select Cod_Produt, QtdLot = SUM(IsNull(Qtd_Lote,0)) 
                     From PDVLT 
                   Where Cod_Estabe = @CodEstabe
                     And Cod_Pedido = @CodPed
                     And IsNull(Qtd_Lote,0) > 0 
                   Group by Cod_Produt) lt 
                 Inner Join (Select Cod_Produto, QtdIte = SUM(IsNull(Qtd_Pedido,0)+Isnull(Qtd_Bonificacao,0)) 
                               From PDVIT 
                              Where Cod_Estabe = @CodEstabe
                                And Cod_Pedido = @CodPed
                                And (IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) > 0 
                              Group by Cod_Produto) it on it.Cod_Produto = lt.Cod_Produt 

           Where IsNull(lt.QtdLot,0) > IsNull(it.QtdIte,0))
  begin
    Set @FlgErr = 1
    Set @StrMsg = 'Existem itens em PDVLT com quantidades superiores de PDVIT '
  end

if (@FlgErr = 0) and
   Exists(Select Cod_Produto, Tip_Sai, count(*) From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed Group By Cod_Produto, Tip_Sai Having count(*) > 1)
  begin
    Set @FlgErr = 1
    Set @StrMsg = 'Existem produtos com mais de um lote'
  end

if (@FlgErr = 0) and
   Exists(Select z1.Cod_Zon, z2.Cod_Zon 
            From TBZON z1, TBZON z2
           Where z1.Cod_Estabe = z2.Cod_Estabe
             And z1.Cod_Dep = z2.Cod_Dep
             And z1.Cod_Estabe = @CodEstabe
             And z1.Cod_Zon > 0
             And z1.Cod_Zon <> z2.Cod_Zon 
             And ((z1.Num_RuaIni between z2.Num_RuaIni and z2.Num_RuaFim) or
                  (z1.Num_RuaFim between z2.Num_RuaIni and z2.Num_RuaFim)))
  begin
    Declare @WCodZon1 int,
            @WCodZon2 int

    Select top 1 @WCodZon1 = z1.Cod_Zon, @WCodZon2 = z2.Cod_Zon 
      From TBZON z1, TBZON z2
     Where z1.Cod_Estabe = z2.Cod_Estabe
       And z1.Cod_Dep = z2.Cod_Dep
       And z1.Cod_Estabe = @CodEstabe
       And z1.Cod_Zon > 0
       And z1.Cod_Zon <> z2.Cod_Zon 
       And ((z1.Num_RuaIni between z2.Num_RuaIni and z2.Num_RuaFim) or
            (z1.Num_RuaFim between z2.Num_RuaIni and z2.Num_RuaFim))    

    Set @FlgErr = 1
    Set @StrMsg = 'Endereços conflitantes entre as Zonas '+CAST(@WCodZon1 as varchar)+' e '+CAST(@WCodZon2 as varchar)
  end

-- critica cadastros, inconsistencias, embalagem padrao, apresentacao padrao, etc...
if @FlgErr = 0
  Exec PR_CriticaCadastrosVolumesWMS @CodEstabe, @CodPed, @FlgErr output, @StrMsg output

-- verifica reabastecimento do picking
if @FlgErr = 0
  Exec PR_VerificaAbastecimentoPedido @CodEstabe, @CodPed, @StrMsg output, @FlgErr output  


if @FlgErr = 1
  begin
    RAISERROR(@StrMsg,16,1)
    Return
  end
else
BEGIN
  Begin Transaction

    Declare @DesLoc varchar(80) = '(ANTES) PR_SolicitaLotesPDV pedido: '+cast(@CodPed as varchar)
    Exec PR_Verifica_Divergencia_PRXESxPRLOT_PRLTL @DesLoc, @CodEstabe, 0

    Declare @CodPrd int,
            @TipSai varchar(1),
            @IdPolLot int,
            @QtdPdv int,
            @QtdLot int,
            @QtdSld int,
            @QtdMov int,
            @FlgMov bit = 0,
            @CodLotTip varchar(20),
            @QtdTotTip int,
            @QtdPraTip int,
            @QtdDepTip int,
            @QtdFra int,
            @QtdEmbFec int,
            @QtdEmbFecCal int,
            @QtdCxaFec int,
            @QtdUndLot int,
            @QtdSldFiscal int,
            @QtdSolPulmao int,
            @cl_CodCliPag int,
            @cl_CodGrpCli int,
            @cl_QtdMesMinPrzVctLot int,
            @cl_FlgBlqLotVarPdv bit,
            @StrPrd varchar(100),
            @FlgIntWms bit = 0,
            @BlqEstFisNeg bit = 0,
            @FlgUndMin bit = 0,
            @StaIntWms varchar(1),
            @FlgTipVenFat bit = 0,
            @FlgPodeFechar bit = 0,
		    @Usuario varchar(15)

    Set @Usuario = dbo.FN_UsuarioInfarma()

    Select @FlgIntWms = IsNull(FlgIntegrWmsExt,0),
           @BlqEstFisNeg = IsNull(BlqEstFisNeg,0)   -- nao permite negativar estoque fiscal
      From PMEST 
     Where Cod_Estabe = @CodEstabe

    Select @FlgUndMin = IsNull(FlgAltUnvItePdv,0) 
      From PARAM 
     Where Cod_Estabe = @CodEstabe

    Select @StaIntWms = IsNull(cb.Sta_IntWms,''),
           @FlgTipVenFat = Case When ISNull(op.Cod_CfoNorInt,0) > 0 then 1 ELse 0 End
      From PDVCB cb
           Left Join TPOPE op on cb.Tip_Faturamento = op.Cod_Ope 
     Where cb.Cod_Estabe = @CodEstabe and cb.Numero = @CodPed

    Set @FlgErr = 0
    Set @StrMsg = ''
    Set @FlgPodeFechar = 0

    if @FlgIntWms = 0
      Set @FlgPodeFechar = 1
    else
    if @StaIntWms = ''
      begin
        Update PDVCB
           Set Sta_IntWMS = '0'
         Where Cod_Estabe = @CodEstabe 
           And Numero = @CodPed
           And IsNull(Sta_IntWMS,'') = ''

        Exec PR_WMSGerarXMLSaida @CodEstabe, @CodPed
      end

    if @FlgPodeFechar = 1
      begin 

        IF OBJECT_ID('tempdb..#ARQ_PDVIT') IS NOT NULL
          DROP TABLE #ARQ_PDVIT
        
        CREATE TABLE #ARQ_PDVIT
        (
            Chave int identity,
        	Cod_Produt int,
            Id_PolLot int,
            Qtd_Pdv int
        ) 

        IF OBJECT_ID('tempdb..#ARQ_PRLTL') IS NOT NULL
          DROP TABLE #ARQ_PRLTL
        
        CREATE TABLE #ARQ_PRLTL
        (
            Chave int identity,
        	Cod_Estabe smallint,
            Cod_Dep smallint,
            Num_Rua smallint, 
        	Num_Col smallint, 
        	Num_Niv smallint, 
        	Num_Apt smallint,
        	Tip_LocEnd varchar(1),
            Cod_Produt int,
        	Cod_Lote varchar(20),
            Cod_Fabricante int,
            Dat_Vencim smalldatetime,
            Dat_Entrada smalldatetime,
            Qtd_EmbFec int,
            C_QtdEmbFec int,
            Qtd_Saldo int,
            Qtd_SldPra int,
            Qtd_SldDep int
        ) 
        
        CREATE UNIQUE CLUSTERED INDEX IX_CL_ARQ_PRLTL ON #ARQ_PRLTL (Chave);
        CREATE NONCLUSTERED INDEX IX_CL_ARQ_PRLTL_Cod_Dep_Cod_Produto_Dat_Vencim ON #ARQ_PRLTL (Cod_Estabe, Cod_Produt, Dat_Vencim);


        -- popula #ARQ_PDVIT --------------------------------------------------
        Insert into #ARQ_PDVIT
          Select it.Cod_Produto, 
                 IdPolLot = Case
                              When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = it.Cod_Estabe and pl.Id_PolCom = it.Id_PolCom and pl.Cod_Produt = it.Cod_Produto) then it.Id_PolCom
                              Else 0
                            End,
                 sum(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) as QtdPdv
            From PDVIT it 
           Where it.Cod_Estabe = @CodEstabe 
             And it.Cod_Pedido = @CodPed
             And IsNull(it.Qtd_Pedido,0) > 0
           Group by it.Cod_Estabe, it.Cod_Produto, it.Id_PolCom

        -- desconta PDVLT já solicitado ---131370
		Declare @cr_CodPrd int,
                @cr_IdPolLot int,
                @cr_QtdLot int

        -- lotes já solicitados
        Declare PDVLT_Cr Cursor Local Fast_Forward For 

          Select Cod_Produt, Id_PolCOm
               , Qtd_Lote = sum(Qtd_Lote)
            From PDVLT
           Where Cod_Estabe = @CodEstabe
             And Cod_Pedido = @CodPed
           Group by Cod_Produt, Id_PolCom
           Order by Cod_Produt, Id_PolCom Desc

        Open PDVLT_Cr  
        Fetch Next From PDVLT_Cr Into @cr_CodPrd, @cr_IdPolLot, @QtdSld
        While @@FETCH_STATUS = 0
          begin
            Set @CodPrd = @cr_CodPrd

            While (@CodPrd = @cr_CodPrd) and (@@FETCH_STATUS = 0)  
              begin

                -- desconta lote diferenciado se houver
                if Exists(Select 1 From #ARQ_PDVIT Where Cod_Produt = @CodPrd 
                             And Id_PolLot = @cr_IdPolLot 
                             And @cr_IdPolLot > 0 And Qtd_Pdv > 0)
                  begin
                    Select @cr_QtdLot = Qtd_Pdv 
                      From #ARQ_PDVIT 
                     Where Cod_Produt = @CodPrd
                       And Id_PolLot = @cr_IdPolLot
                       And Qtd_Pdv > 0

                    if @cr_QtdLot > @QtdSld
                      Set @QtdMov = @QtdSld
                    else					  					                     
                      Set @QtdMov = @cr_QtdLot

                    Update #ARQ_PDVIT 
                       Set Qtd_Pdv = Qtd_Pdv - @QtdMov
                     Where Cod_Produt = @CodPrd
                       And Id_PolLot = @cr_IdPolLot
                       And @QtdMov >= Qtd_Pdv
                    if @@rowcount > 0
                      Set @QtdSld = @QtdSld - @QtdMov
                  end

                -- desconta restante
                if @QtdSld > 0
                  Set @FlgMov = 1
				   
                while (@QtdSld > 0) and (@FlgMov = 1) and
                      Exists(Select 1 From #ARQ_PDVIT Where Cod_Produt = @CodPrd And Qtd_Pdv > 0)
                  begin
                    Set @FlgMov = 0

                    Select top 1 
                           @cr_IdPolLot = Id_PolLot
                         , @cr_QtdLot = Qtd_Pdv 
                      From #ARQ_PDVIT 
                     Where Cod_Produt = @CodPrd
                       And Qtd_Pdv > 0
                     Order by Id_PolLot desc

                    if @cr_QtdLot > @QtdSld
                      Set @QtdMov = @QtdSld
                    else					  					                     
                      Set @QtdMov = @cr_QtdLot

                    Update #ARQ_PDVIT 
                       Set Qtd_Pdv = Qtd_Pdv - @QtdMov
                     Where Cod_Produt = @CodPrd
                       And Id_PolLot = @cr_IdPolLot
                       And @QtdMov <= Qtd_Pdv
                    if @@rowcount > 0
                      begin
                        Set @FlgMov = 1
                        Set @QtdSld = @QtdSld - @QtdMov
                      end

                  end -- while (@QtdSld > 0) and (@FlgMov = 1) and

                Fetch Next From PDVLT_Cr Into @cr_CodPrd, @cr_IdPolLot, @QtdSld

              end  -- While (@CodPrd = @cr_CodPrd) and (@@FETCH_STATUS = 0)

            Delete From #ARQ_PDVIT 
             Where Cod_Produt = @CodPrd
               And Qtd_Pdv = 0

          end  -- While @@FETCH_STATUS = 0
          
        Close PDVLT_Cr
        Deallocate PDVLT_Cr
        -- fim popula #ARQ_PRLTL -------------------------------------------------------

        -- popula #ARQ_PRLTL descontando abastecimentos pendentes
        Insert into #ARQ_PRLTL
          Select lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt,
                 dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua),
                 lt.Cod_Produt, lt.Cod_Lote, pr.Cod_Fabricante, lt.Dat_Vencim, lt.Dat_Entrada,
                 Qtd_EmbFec  = IsNull(lt.Qtd_EmbFec,0),
                 C_QtdEmbFec = IsNull(lt.C_QtdEmbFec,0),
                 Qtd_Saldo   = IsNull(lt.Qtd_Saldo,0)  - IsNull(ab.C_QtdMov,0),
                 Qtd_SldPra  = IsNull(lt.Qtd_SldPra,0) - IsNull(ab.C_QtdMov,0),
                 Qtd_SldDep  = IsNull(lt.Qtd_SldDep,0)
            From PRLTL lt Inner Join
                 PRODU pr on lt.Cod_Produt = pr.Codigo Left Join
                 ( Select it.Cod_Produt, it.Cod_Lote, it.Cod_Dep, it.Num_Rua, it.Num_Col, it.Num_Niv, it.Num_Apt,
                          C_QtdMov = sum(QTd_Mov)
                     From ABAIT it
                          Inner Join ABACB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Cod_Abaste = cb.Cod_Abaste
                    Where cb.Cod_Estabe = @CodEstabe
                      And cb.Cod_STa = 'A'
                    Group by it.Cod_Produt, it.Cod_Lote, it.Cod_Dep, it.Num_Rua, it.Num_Col, it.Num_Niv, it.Num_Apt
                 ) ab on lt.Cod_Produt = ab.Cod_Produt and lt.Cod_Lote = ab.Cod_Lote and
                         lt.Cod_Dep = ab.Cod_Dep and lt.Num_Rua = ab.Num_Rua and lt.Num_Col = ab.Num_Col and lt.Num_Niv = ab.Num_Niv and lt.Num_Apt = ab.Num_Apt
           Where lt.Cod_Estabe = @CodEstabe
             And (IsNull(lt.Qtd_Saldo,0) - IsNull(ab.C_QtdMov,0)) > 0
             And IsNull(lt.Qtd_EmbFec,0) > 0

        -- normaliza #ARQ_PRLTL
        Update #ARQ_PRLTL
           Set Qtd_SldDep = Qtd_SldDep + Abs(Qtd_SldPra),
               Qtd_SldPra = 0
         Where Qtd_SldPra < 0
        
		-- TBZON
        Update TBZON
           Set Num_Esteira = 1
         Where Cod_Estabe = @CodEstabe
           And ISNULL(Num_Esteira,0) = 0

        Declare @NumVol int,
                @to_CodCfoNorInt int,
                @to_TipOpe varchar(1),
                @pm_FlgBlqCnfTrf bit, 
                @pm_CodOpeWmsDef int,
                @DatVct smalldatetime,
                @DatEnt smalldatetime,
                @CodLot varchar(20),
                @CodLotEsp varchar(20),  -- lote especifico
				@QtdLotSel int,
                @LocEst varchar(1),
                @OrdDep varchar(1),
				@FlgPrePck bit,
                @CodDep int, 
                @CodDepAnt int, 
                @NumEst smallint,
                @NumEstAnt smallint,
                @NumRua int, 
                @NumCol int, 
                @NumNiv int, 
                @NumApt int, 
                @SldLot int,
                @FatCnvAprEmbPad int,
                @QtdPraLot int,
                @QtdDepLot int,
                @QtdDif int,
                @FlgDesord bit,
                @dx_CodLocFis varchar(15),
                @pr_VolUniMin numeric(18,8),  -- @pr_VolEmb
                @cx_CodCxaPad int,
                @cx_VolCxaPad numeric(18,4),
                @cx_NewCodCxaPad int,
                @VolMaxCxa numeric(18,4),
                @VolTotIte numeric(18,4),
                @VolAcu numeric(18,4),
                @QtdAteAcu int,
                @QtdAte int,
                @Per numeric(18,8)

        Select @cl_CodCliPag = Case 
                                 When IsNull(cl.Cod_CliPag,0) > 0 then cl.Cod_CliPag
                                 Else cl.Codigo
                               End,
               @cl_QtdMesMinPrzVctLot = IsNull(cl.Qtd_MesMinPrzVctLot,0),
               @cl_CodGrpCli = cl.Cod_GrpCli,
			   @cl_FlgBlqLotVarPdv = IsNull(Flg_BlqLotVarPdv,0)
          From CLIEN cl Inner Join PDVCB cb on (cb.Cod_Cliente = cl.Codigo)
         Where cb.Cod_Estabe = @CodEstabe 
           And cb.Numero = @CodPed
          
        if @cl_CodCliPag is null Set @cl_CodCliPag = 0
        if @cl_QtdMesMinPrzVctLot is null Set @cl_QtdMesMinPrzVctLot = 0
        if @cl_CodGrpCli is null Set @cl_CodGrpCli = 0
                     
        Select @to_CodCfoNorInt = IsNull(t.Cod_CfoNorInt,0),
               @to_TipOpe = IsNull(t.Tip_Ope,'')
          From TPOPE t Inner Join PDVCB p on (t.Cod_Ope = p.Tip_Faturamento)
         Where p.Cod_Estabe = @CodEstabe 
           And p.Numero = @CodPed

        Select @pm_FlgBlqCnfTrf = IsNull(FlgBlqCnfTrf,0), 
               @pm_CodOpeWmsDef = IsNull(CodOpeWmsDef,0) 
          From PMEST
         Where Cod_Estabe = @CodEstabe  


        -- pega o último volume de caixa fechada, se já existir
        Set @NumVol = IsNull((Select max(Num_Vol)
                                From PDVLT 
                               Where Cod_Estabe = @CodEstabe 
                                 And Cod_Pedido = @CodPed
                                 And ((Cod_LocFis = 'PRLTL') And (Qtd_CxaFec > 0))),0)	

        -- negativa volumes fracionados pré-existentes
        Update PDVLT
           Set Num_Vol = -1
         Where Cod_Estabe = @CodEstabe 
           And Cod_Pedido = @CodPed
           And ((Cod_LocFis <> 'PRLTL') or (Qtd_CxaFec > 0))


        -- elimina registro de conferencia existentes
        Delete from CPVIT Where Cod_Estabe = @CodEstabe And Num_PedCnf = @CodPed

        Delete from CPVCB Where Cod_Estabe = @CodEstabe And Num_PedCnf = @CodPed
          
        -- **************************************************  solicita lotes (CAIXA FECHADA) por vencimento do DEPOSITO FECHADO  ******************************************************************
        Declare PDVIT_Cr Cursor Local Fast_Forward For 

          Select Cod_Produt, Id_PolLot, Qtd_Pdv
            From #ARQ_PDVIT

        Open PDVIT_Cr  
        Fetch Next From PDVIT_Cr Into @CodPrd, @IdPolLot, @QtdPdv
        While @@FETCH_STATUS = 0  
          begin
            -- nao permite negativar estoque fiscal
            if (@BlqEstFisNeg = 1) and (@FlgTipVenFat = 1)
              begin
                Set @QtdSldFiscal = dbo.FN_SldFiscalDisponPrd(@CodEstabe,@CodPrd)
                if @QtdPdv > @QtdSldFiscal 
                  Set @QtdPdv = @QtdSldFiscal
              end

            if @FlgUndMin = 0
              begin
                Select @pr_VolUniMin = IsNull(Vol_Emb,0)
                  From PRODU
                 Where Codigo = @CodPrd
              end
            else
            -- volume da embalagem Unidade minima
              begin
                Select @pr_VolUniMin = IsNull(Vol_Emb/Fat_CnvApr,0)
                  From PRXAP
                 Where Cod_Produt = @CodPrd
				   And Flg_Padrao = 1
              end

            -- verifica atendimento lote especifico
			Set @QtdLotSel = 0

            Set @QtdFra = @QtdPdv  
            -------------------------------------------------------------------------------------------------------------------------------------------------------
            if @to_CodCfoNorInt > 0
              begin
                -- venda FAT estoque compartilhado
                Declare PRLTL_Cr Cursor Local Fast_Forward For 

                  Select '1' as CodLocEst, lt.OrdDep, lt.Dat_Vencim, lt.Flg_PrePck, lt.Dat_Entrada, lt.Cod_Lote, lt.Qtd_EmbFec, lt.Qtd_EmbFecCal, 
                         lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt, lt.Qtd_SldPra
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Produt, l1.Cod_Fabricante, l1.Dat_Vencim, Flg_PrePck=IsNull(e1.Flg_PrePck,0), l1.Dat_Entrada, l1.Cod_Lote, Qtd_EmbFec=IsNull(l1.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l1.C_QtdEmbFec,0),
                                 l1.Cod_Dep, l1.Num_Rua, l1.Num_Col, l1.Num_Niv, l1.Num_Apt, Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldPra=IsNull(l1.Qtd_SldPra,0) 
                            From #ARQ_PRLTL l1 Inner Join 
                                 DPXGC de on (l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli) Left Join
							     ENDDP e1 on (l1.Cod_Estabe = e1.Cod_Estabe and l1.Cod_Dep = e1.Cod_Dep and l1.Num_Rua = e1.Num_Rua and
								              l1.Num_Col = e1.Num_Col and l1.Num_Niv = e1.Num_Niv and l1.Num_Apt = e1.Num_Apt)
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_SldPra,0) >= IsNull(l1.C_QtdEmbFec,0)
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Produt, l2.Cod_Fabricante, l2.Dat_Vencim, Flg_PrePck=IsNull(e2.Flg_PrePck,0), l2.Dat_Entrada, l2.Cod_Lote, Qtd_EmbFec=IsNull(l2.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l2.C_QtdEmbFec,0), 
                                 l2.Cod_Dep, l2.Num_Rua, l2.Num_Col, l2.Num_Niv, l2.Num_Apt, Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldPra=IsNull(l2.Qtd_SldPra,0) 
                            From #ARQ_PRLTL l2 Left Join
							     ENDDP e2 on (l2.Cod_Estabe = e2.Cod_Estabe and l2.Cod_Dep = e2.Cod_Dep and l2.Num_Rua = e2.Num_Rua and
								              l2.Num_Col = e2.Num_Col and l2.Num_Niv = e2.Num_Niv and l2.Num_Apt = e2.Num_Apt)
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_SldPra,0) >= IsNull(l2.C_QtdEmbFec,0)
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Left Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = lt.Cod_Produt Left Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = lt.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
                     And IsNull(lt.Qtd_EmbFecCal,0) > 0 
                     And IsNull(lt.Qtd_Saldo,0) >= IsNull(lt.Qtd_EmbFecCal,0) 
                     And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     and IsNull(lt.Qtd_SldPra,0) > 0
                     and @QtdPdv >= IsNull(lt.Qtd_EmbFecCal,0) 
                  UNION ALL
                  Select '2' as CodLocEst, lt.OrdDep, lt.Dat_Vencim, lt.Flg_PrePck, lt.Dat_Entrada, lt.Cod_Lote, lt.Qtd_EmbFec, lt.Qtd_EmbFecCal,
                         lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt, IsNull(lt.Qtd_SldDep,0) 
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Produt, l1.Cod_Fabricante, l1.Dat_Vencim, Flg_PrePck=IsNull(e1.Flg_PrePck,0), l1.Dat_Entrada, l1.Cod_Lote, Qtd_EmbFec=IsNull(l1.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l1.C_QtdEmbFec,0),
                                 l1.Cod_Dep, l1.Num_Rua, l1.Num_Col, l1.Num_Niv, l1.Num_Apt, Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldDep=IsNull(l1.Qtd_SldDep,0) 
                            From #ARQ_PRLTL l1 Inner Join 
                                 DPXGC de on (l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli) Left Join
							     ENDDP e1 on (l1.Cod_Estabe = e1.Cod_Estabe and l1.Cod_Dep = e1.Cod_Dep and l1.Num_Rua = e1.Num_Rua and
								              l1.Num_Col = e1.Num_Col and l1.Num_Niv = e1.Num_Niv and l1.Num_Apt = e1.Num_Apt)
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_SldDep,0) >= IsNull(l1.C_QtdEmbFec,0) 
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Produt, l2.Cod_Fabricante, l2.Dat_Vencim, Flg_PrePck=IsNull(e2.Flg_PrePck,0), l2.Dat_Entrada, l2.Cod_Lote, Qtd_EmbFec=IsNull(l2.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l2.C_QtdEmbFec,0), 
                                 l2.Cod_Dep, l2.Num_Rua, l2.Num_Col, l2.Num_Niv, l2.Num_Apt, Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldDep=IsNull(l2.Qtd_SldDep,0) 
                            From #ARQ_PRLTL l2 Left Join
							     ENDDP e2 on (l2.Cod_Estabe = e2.Cod_Estabe and l2.Cod_Dep = e2.Cod_Dep and l2.Num_Rua = e2.Num_Rua and
								              l2.Num_Col = e2.Num_Col and l2.Num_Niv = e2.Num_Niv and l2.Num_Apt = e2.Num_Apt)
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_SldDep,0) >= IsNull(l2.C_QtdEmbFec,0)  
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Left Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = lt.Cod_Produt Left Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = lt.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd  
                     And IsNull(lt.Qtd_EmbFecCal,0) > 0 
                     And IsNull(lt.Qtd_Saldo,0) >= IsNull(lt.Qtd_EmbFecCal,0) 
                     And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_SldDep,0) > 0
                     And @QtdPdv >= IsNull(lt.Qtd_EmbFecCal,0) 
                   Order by OrdDep, CodLocEst, Dat_Vencim, Flg_PrePck desc, Num_Rua, Num_Niv, Num_Apt, Num_Col, Cod_Lote, Dat_Entrada
              end
            else
              begin
                -- venda ORC estoque compartilhado
                Declare PRLTL_Cr Cursor Local Fast_Forward For 
                  Select '2' as CodLocEst, lt.OrdDep, lt.Dat_Vencim, lt.Flg_PrePck, lt.Dat_Entrada, lt.Cod_Lote, lt.Qtd_EmbFec, lt.Qtd_EmbFecCal,
                         lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt, lt.Qtd_SldDep
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Produt, l1.Cod_Fabricante, l1.Dat_Vencim, Flg_PrePck=IsNull(e1.Flg_PrePck,0), l1.Dat_Entrada, l1.Cod_Lote, Qtd_EmbFec=IsNull(l1.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l1.C_QtdEmbFec,0), 
                                 l1.Cod_Dep, l1.Num_Rua, l1.Num_Col, l1.Num_Niv, l1.Num_Apt, Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldDep=IsNull(l1.Qtd_SldDep,0) 
                            From #ARQ_PRLTL l1 Inner Join 
                                 DPXGC de on (l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli) Left Join
							     ENDDP e1 on (l1.Cod_Estabe = e1.Cod_Estabe and l1.Cod_Dep = e1.Cod_Dep and l1.Num_Rua = e1.Num_Rua and
								              l1.Num_Col = e1.Num_Col and l1.Num_Niv = e1.Num_Niv and l1.Num_Apt = e1.Num_Apt)
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_SldDep,0) >= IsNull(l1.C_QtdEmbFec,0)
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Produt, l2.Cod_Fabricante, l2.Dat_Vencim, Flg_PrePck=IsNull(e2.Flg_PrePck,0), l2.Dat_Entrada, l2.Cod_Lote, Qtd_EmbFec=IsNull(l2.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l2.C_QtdEmbFec,0),
                                 l2.Cod_Dep, l2.Num_Rua, l2.Num_Col, l2.Num_Niv, l2.Num_Apt, Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldDep=IsNull(l2.Qtd_SldDep,0) 
                            From #ARQ_PRLTL l2 Left Join
							     ENDDP e2 on (l2.Cod_Estabe = e2.Cod_Estabe and l2.Cod_Dep = e2.Cod_Dep and l2.Num_Rua = e2.Num_Rua and
								              l2.Num_Col = e2.Num_Col and l2.Num_Niv = e2.Num_Niv and l2.Num_Apt = e2.Num_Apt)
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_SldDep,0) >= IsNull(l2.C_QtdEmbFec,0)
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Left Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = lt.Cod_Produt Left Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = lt.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
                     And IsNull(lt.Qtd_EmbFecCal,0) > 0 
                     And IsNull(lt.Qtd_Saldo,0) >= IsNull(lt.Qtd_EmbFecCal,0) 
                     And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_SldDep,0) > 0
                     And @QtdPdv >= IsNull(lt.Qtd_EmbFecCal,0) 
                  UNION ALL
                  Select '1' as CodLocEst, lt.OrdDep, lt.Dat_Vencim, lt.Flg_PrePck, lt.Dat_Entrada, lt.Cod_Lote, lt.Qtd_EmbFec, lt.Qtd_EmbFecCal,
                         lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt, lt.Qtd_SldPra
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Produt, l1.Cod_Fabricante, l1.Dat_Vencim, Flg_PrePck=IsNull(e1.Flg_PrePck,0), l1.Dat_Entrada, l1.Cod_Lote, Qtd_EmbFec=IsNull(l1.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l1.C_QtdEmbFec,0), 
                                 l1.Cod_Dep, l1.Num_Rua, l1.Num_Col, l1.Num_Niv, l1.Num_Apt, Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldPra=IsNull(l1.Qtd_SldPra,0) 
                            From #ARQ_PRLTL l1 Inner Join 
                                 DPXGC de on (l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli) Left Join
							     ENDDP e1 on (l1.Cod_Estabe = e1.Cod_Estabe and l1.Cod_Dep = e1.Cod_Dep and l1.Num_Rua = e1.Num_Rua and
								              l1.Num_Col = e1.Num_Col and l1.Num_Niv = e1.Num_Niv and l1.Num_Apt = e1.Num_Apt)
                           Where l1.Cod_Estabe = @CodEstabe 
                            And IsNull(l1.Qtd_SldPra,0) >= IsNull(l1.C_QtdEmbFec,0)
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Produt, l2.Cod_Fabricante, l2.Dat_Vencim, Flg_PrePck=IsNull(e2.Flg_PrePck,0), l2.Dat_Entrada, l2.Cod_Lote, Qtd_EmbFec=IsNull(l2.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l2.C_QtdEmbFec,0),
                                 l2.Cod_Dep, l2.Num_Rua, l2.Num_Col, l2.Num_Niv, l2.Num_Apt, Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldPra=IsNull(l2.Qtd_SldPra,0) 
                            From #ARQ_PRLTL l2 Left Join
							     ENDDP e2 on (l2.Cod_Estabe = e2.Cod_Estabe and l2.Cod_Dep = e2.Cod_Dep and l2.Num_Rua = e2.Num_Rua and
								              l2.Num_Col = e2.Num_Col and l2.Num_Niv = e2.Num_Niv and l2.Num_Apt = e2.Num_Apt)
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_SldPra,0) >= IsNull(l2.C_QtdEmbFec,0)
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Left Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = lt.Cod_Produt Left Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = lt.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
                     And IsNull(lt.Qtd_EmbFecCal,0) > 0 
                     And IsNull(lt.Qtd_Saldo,0) >= IsNull(lt.Qtd_EmbFecCal,0) 
                     And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_SldPra,0) > 0
                     And @QtdPdv >= IsNull(lt.Qtd_EmbFecCal,0) 
                   Order by OrdDep, CodLocEst desc, Dat_Vencim, Flg_PrePck desc, Num_Rua, Num_Niv, Num_Apt, Num_Col, Cod_Lote, Dat_Entrada
              end
            -------------------------------------------------------------------------------------------------------------------------------------------------------
            Open PRLTL_Cr
            Fetch Next From PRLTL_Cr Into @LocEst, @OrdDep, @DatVct, @FlgPrePck, @DatEnt, @CodLot, @QtdEmbFec, @QtdEmbFecCal,
                                          @CodDep, @NumRua, @NumCol, @NumNiv,@NumApt, @SldLot 
            While @@FETCH_STATUS = 0
              begin
                -- verifica lote unico
                Set @QtdLotSel = @QtdLotSel + 1
                if (@cl_FlgBlqLotVarPdv = 1) and (@QtdLotSel > 1)
                  Break

                if (@QtdFra > 0) and (@QtdFra >= @QtdEmbFecCal) and (@SldLot >= @QtdEmbFecCal) 
                  begin
                    if @SldLot < @QtdFra
                      Set @QtdCxaFec = @SldLot / @QtdEmbFecCal
                    else
                      Set @QtdCxaFec = @QtdFra / @QtdEmbFecCal
                    Set @QtdUndLot = @QtdCxaFec * @QtdEmbFecCal

                    -- decrementa saldo em PRLTL
                    Set @QtdPraLot = 0
                    Set @QtdDepLot = 0
                    if @LocEst = '1'
                      Set @QtdPraLot = @QtdUndLot
                    else
                      Set @QtdDepLot = @QtdUndLot

                    Update PRLTL
                       Set Qtd_SolPra = IsNull(Qtd_SolPra,0) + @QtdPraLot,
                           Qtd_SolDep = IsNull(Qtd_SolDep,0) + @QtdDepLot
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Produt = @CodPrd
                       And Cod_Lote = @CodLot
                       And Qtd_EmbFec = @QtdEmbFec 
                       And Cod_Dep =  @CodDep
                       And Num_Rua = @NumRua
                       And Num_Col = @NumCol
                       And Num_Niv = @NumNiv
                       And Num_Apt = @NumApt

                    Set @QtdFra = @QtdFra - @QtdUndLot
                    Set @SldLot = @SldLot - @QtdUndLot

                    -- grava registro em PDVLT 
                    Set @VolTotIte = @QtdUndLot*@pr_VolUniMin
                    Set @FlgDesord = 0

					if (@QtdPraLot+@QtdDepLot) > 0
                      begin
					    --Set @NumEst = IsNull((Select z.Num_Esteira From TBZON z Where z.Cod_Estabe = @CodEstabe and @NumRua between z.Num_RuaIni and z.Num_RuaFim),0)
						Set @NumEst = IsNull((Select z.Num_Esteira From TBZON z Where z.Cod_Estabe = @CodEstabe and Cod_Dep = @CodDep and @NumRua between z.Num_RuaIni and z.Num_RuaFim),0)

                        -- caixa fechada: sempre um novo volume
                        Set @NumVol = @NumVol + 1
                        if @NumVol = 0 Set @NumVol = 1

                        if Exists(Select 1 From PDVLT 
                                   Where Cod_Estabe = @CodEstabe 
                                     And Cod_Pedido = @CodPed And Num_Vol = @NumVol) 
                          Set @NumVol = @NumVol + 1

                        -- caixa fechada: PDVLT.Cod_LocFis = 'PRLTL',  PDVLT.Qtd_CxaFec > 0
                        Insert Into PDVLT (Cod_Estabe, Cod_Pedido, Num_Vol, Cod_Produt, Cod_Lote
                                        ,  Qtd_EmbFec, Fat_CnvAprEmbPad, Qtd_Lote, Qtd_CxaFec
                                        ,  Cod_Dep, Num_Esteira, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis
                                        ,  Qtd_LotePra, Qtd_LoteDep, Vol_TotIte, Id_PolCom, Flg_Desord, Flg_Manual
                                        ,  Cod_FunSep, Transacao)
                                   Values (@CodEstabe, @CodPed, @NumVol, @CodPrd, @CodLot
                                        ,  @QtdEmbFec, @QtdEmbFecCal, @QtdUndLot, @QtdCxaFec
                                        ,  @CodDep, @NumEst, @NumRua, @NumCol, @NumNiv, @NumApt, 'PRLTL'
                                        ,  @QtdPraLot, @QtdDepLot, @VolTotIte, @IdPolLot, @FlgDesord, 0
                                        ,  0, @Now )
                        if @@error <> 0
                          begin
                            Rollback Transaction
                            Return
                          end
                      end

                  end -- if (@QtdFra > 0) and (@QtdFra >= @QtdEmbFec) and (@SldLot >= @QtdEmbFec) 

                Fetch Next From PRLTL_Cr Into @LocEst, @OrdDep, @DatVct, @FlgPrePck, @DatEnt, @CodLot, @QtdEmbFec, @QtdEmbFecCal,
                                              @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @SldLot 
              end    -- While @@FETCH_STATUS = 0
              
            Close PRLTL_Cr
            Deallocate PRLTL_Cr

            Fetch Next From PDVIT_Cr Into @CodPrd, @IdPolLot, @QtdPdv
          end  -- While @@FETCH_STATUS = 0
          
        Close PDVIT_Cr
        Deallocate PDVIT_Cr
        
--------  FIM SOLICITA CAIXA FECHADA PULMAO --------------------------------------------------------------------------------------------------------------


        -- **************************************************  solicita lotes fracionados por vencimento do PICKING  ******************************************************************
        -- unico volume para fracionados
        Set @NumVol = @NumVol + 1

        -- ajusta volumes fracionados pré-existentes negativados
        Update PDVLT
           Set Num_Vol = @NumVol
         Where Cod_Estabe = @CodEstabe 
           And Cod_Pedido = @CodPed
           And Num_Vol < 0

        if @FlgUndMin = 0
          begin
            Declare PDVIT_Cr Cursor Local Fast_Forward For 
              Select x.Cod_Produt, x.IdPolLot, pr.Qtd_Embalagem, IsNull(pr.Vol_Emb,0), x.QtdFra
                
				From (Select it.Cod_Produt, it.IdPolLot, (it.QtdPdv-IsNull(d.QtdLot,0)) as QtdFra
                        From (Select a.Cod_Produt, 
                                     IdPolLot = Case
                                                  When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = @CodEstabe and pl.Id_PolCom = a.Id_PolLot and pl.Cod_Produt = a.Cod_Produt) then a.Id_PolLot
                                                  Else 0
                                                End,
                                     sum(IsNull(a.Qtd_Pdv,0)) as QtdPdv
                                From #ARQ_PDVIT a
                               Where IsNull(a.Qtd_Pdv,0) > 0
                               Group by a.Cod_Produt, a.Id_PolLot) it Left Outer Join

                             (Select b.Cod_Produt, 
                                     IdPolLot = Case
                                                  When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = b.Cod_Estabe and pl.Id_PolCom = b.Id_PolCom and pl.Cod_Produt = b.Cod_Produt) then b.Id_PolCom
                                                  Else 0
                                                End,
                                     sum(IsNull(b.Qtd_Lote,0)) as QtdLot
                                From PDVLT b
                               Where b.Cod_Estabe = @CodEstabe
                                 And b.Cod_Pedido = @CodPed
                                 And IsNull(b.Qtd_Lote,0) > 0 
                                 And IsNull(b.Qtd_CxaFec,0) > 0   
                               Group by b.Cod_Estabe, b.Cod_Produt, b.Id_PolCom) d on (it.Cod_Produt = d.Cod_Produt and it.IdPolLot = d.IdPolLot)
                            
                       Where (it.QtdPdv-IsNull(d.QtdLot,0)) > 0) x  

                     Inner Join PRODU pr on x.Cod_Produt = pr.Codigo
          end
        else
          begin
            -- trabalha com unidade minima
            Declare PDVIT_Cr Cursor Local Fast_Forward For 
              Select x.Cod_Produt, x.IdPolLot, pr.Qtd_Embalagem, IsNull(ap.Vol_Emb/ap.Fat_CnvApr,0), x.QtdFra

                From (Select it.Cod_Produt, it.IdPolLot, (it.QtdPdv-IsNull(d.QtdLot,0)) as QtdFra  -- it.Cod_Estabe, 
                        From (Select a.Cod_Produt, 
                                     IdPolLot = Case
                                                  When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = @CodEstabe and pl.Id_PolCom = a.Id_PolLot and pl.Cod_Produt = a.Cod_Produt) then a.Id_PolLot
                                                  Else 0
                                                End,
                                     sum(IsNull(a.Qtd_Pdv,0)) as QtdPdv
                                From #ARQ_PDVIT a
                               Where IsNull(a.Qtd_Pdv,0) > 0
                               Group by a.Cod_Produt, a.Id_PolLot) it Left Outer Join
                 
                             (Select b.Cod_Produt,
                                     IdPolLot = Case
                                                  When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = b.Cod_Estabe and pl.Id_PolCom = b.Id_PolCom and pl.Cod_Produt = b.Cod_Produt) then b.Id_PolCom
                                                  Else 0
                                                End,
                                     sum(IsNull(b.Qtd_Lote,0)) as QtdLot
                                From PDVLT b
                               Where b.Cod_Estabe = @CodEstabe
                                 And b.Cod_Pedido = @CodPed
                                 And IsNull(b.Qtd_Lote,0) > 0 
                                 And IsNull(b.Qtd_CxaFec,0) > 0   
                               Group by b.Cod_Estabe, b.Cod_Produt, b.Id_PolCom) d on (it.Cod_Produt = d.Cod_Produt and it.IdPolLot = d.IdPolLot)

                       Where (it.QtdPdv-IsNull(d.QtdLot,0)) > 0) x  

                     Inner Join PRODU pr on x.Cod_Produt = pr.Codigo
					 Inner Join PRXAP ap on pr.Codigo = ap.Cod_Produt and ap.Flg_Padrao = 1
          end
                 
        Open PDVIT_Cr
        Fetch Next From PDVIT_Cr Into @CodPrd, @IdPolLot, @QtdEmbFec, @pr_VolUniMin, @QtdFra
                           
        While @@FETCH_STATUS = 0
          begin
            -- nao permite negativar estoque fiscal
            if (@BlqEstFisNeg = 1) and (@FlgTipVenFat = 1)
              begin
                -- qtd solicitada anteriormente (cx fexhada)
                Set @QtdSolPulmao = IsNull((Select sum(Qtd_Lote) From PDVLT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed 
                                               And Cod_Produt = @CodPrd And Cod_LocFis = 'PRLTL'),0)
                Set @QtdSldFiscal = dbo.FN_SldFiscalDisponPrd(@CodEstabe,@CodPrd) - @QtdSolPulmao
                if @QtdSldFiscal < 0 Set @QtdSldFiscal = 0
                if @QtdFra > @QtdSldFiscal 
                  Set @QtdFra = @QtdSldFiscal
              end
 
            Set @QtdAteAcu = 0    -- acumulador por produto
           
            -- verifica atendimento lote unico
            Set @CodLotEsp = ''
            Set @QtdLotSel = 0
			if (@cl_FlgBlqLotVarPdv = 1) and 
               Exists(Select 1 From PDVLT WHere Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Cod_Produt = @CodPrd) 
              Set @CodLotEsp = (Select top 1 Cod_Lote From PDVLT WHere Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Cod_Produt = @CodPrd)

            -- fracionados solicita somente pelo vencimento --
            if @to_CodCfoNorInt > 0
              begin
                Declare PRLOT_Cr Cursor Local Fast_Forward For   
                  Select '1' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldPra, lt.Fat_CnvAprEmbPad
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldPra=IsNull(l1.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0) 
                            From PRLOT l1 Inner Join
                                 DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_Saldo,0) > 0 
                             and IsNull(l1.Qtd_SldPra,0) > 0
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldPra=IsNull(l2.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0)
                            From PRLOT l2 
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_Saldo,0) > 0 
                             And IsNull(l2.Qtd_SldPra,0) > 0
                          --And Cod_Dep not in (Select distinct Cod_Dep From DPXGC Where Cod_Estabe = @CodEstabe)) lt Inner Join 
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                         PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
					 And ((@CodLotEsp = '') or 
                          ((@CodLotEsp <> '') and (lt.Cod_Lote = @CodLotEsp)))
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_Saldo,0) > 0 
                     And IsNull(lt.Qtd_SldPra,0) > 0
                  UNION ALL
                  Select '2' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldDep, lt.Fat_CnvAprEmbPad
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldDep=IsNull(l1.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0) 
                            From PRLOT l1 Inner Join
                                 DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_Saldo,0) > 0 
                             And IsNull(l1.Qtd_SldDep,0) > 0
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldDep=IsNull(l2.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0)
                            From PRLOT l2 
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_Saldo,0) > 0 
                             And IsNull(l2.Qtd_SldDep,0) > 0
                          --And Cod_Dep not in (Select distinct Cod_Dep From DPXGC Where Cod_Estabe = @CodEstabe)) lt Inner Join 
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                         PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
					 And ((@CodLotEsp = '') or 
                          ((@CodLotEsp <> '') and (lt.Cod_Lote = @CodLotEsp)))
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_Saldo,0) > 0 
                     And IsNull(lt.Qtd_SldDep,0) > 0
                   Order by OrdDep, Dat_Vencim, CodLocEst
              end
            else
              begin
                Declare PRLOT_Cr Cursor Local Fast_Forward For 
                  Select '1' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldPra, lt.Fat_CnvAprEmbPad
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldPra=IsNull(l1.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0) 
                            From PRLOT l1 Inner Join
                                 DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_Saldo,0) > 0 
                             And IsNull(l1.Qtd_SldPra,0) > 0
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldPra=IsNull(l2.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0) 
                            From PRLOT l2 
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_Saldo,0) > 0 
                             And IsNull(l2.Qtd_SldPra,0) > 0
                          --And Cod_Dep not in (Select distinct Cod_Dep From DPXGC Where Cod_Estabe = @CodEstabe)) lt Inner Join 
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                         PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
					 And ((@CodLotEsp = '') or 
                          ((@CodLotEsp <> '') and (lt.Cod_Lote = @CodLotEsp)))
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_Saldo,0) > 0 
                     And IsNull(lt.Qtd_SldPra,0) > 0
                  UNION ALL
                  Select '2' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldDep, lt.Fat_CnvAprEmbPad
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldDep=IsNull(l1.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0)
                            From PRLOT l1 Inner Join
                                 DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_Saldo,0) > 0 
                             And IsNull(l1.Qtd_SldDep,0) > 0
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldDep=IsNull(l2.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0)
                            From PRLOT l2
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_Saldo,0) > 0 
                             And IsNull(l2.Qtd_SldDep,0) > 0
                             --And Cod_Dep not in (Select distinct Cod_Dep From DPXGC Where Cod_Estabe = @CodEstabe)) lt Inner Join 
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                         PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
					 And ((@CodLotEsp = '') or 
                          ((@CodLotEsp <> '') and (lt.Cod_Lote = @CodLotEsp)))
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_Saldo,0) > 0 
                     And IsNull(lt.Qtd_SldDep,0) > 0
                   Order by OrdDep, Dat_Vencim, CodLocEst desc
              end
            -------------------------------------------------------------------------------------------------------------------------------------------------------
            Open PRLOT_Cr
            Fetch Next From PRLOT_Cr Into @LocEst, @OrdDep, @CodDep, @DatVct, @CodLot, @SldLot, @FatCnvAprEmbPad

            Set @QtdAteAcu = 0
            
            While (@QtdAteAcu < @QtdFra) and (@@FETCH_STATUS = 0)
              begin
                -- verifica lote unico
                Set @QtdLotSel = @QtdLotSel + 1
                if (@cl_FlgBlqLotVarPdv = 1) and (@QtdLotSel > 1)
                  Break

                Set @QtdAte = @QtdFra - @QtdAteAcu
                -- se o saldo do lote nao atender a qtd.solicitada refazer a solicitacao proporcionalmente
                if @QtdAte > @SldLot
                  begin
                    Set @QtdAte = @SldLot
                  end
                 -- Atualiza saldo do lote
                Set @QtdPraLot = 0
                Set @QtdDepLot = 0
                if @LocEst = '1'
                  Set @QtdPraLot = @QtdAte
                else
                  Set @QtdDepLot = @QtdAte

                Update PRLOT
                   Set Qtd_SolPra = Qtd_SolPra + @QtdPraLot,
                       Qtd_SolDep = Qtd_SolDep + @QtdDepLot
                 Where Cod_Estabe = @CodEstabe 
                   And Cod_Dep = @CodDep
                   And Cod_Produt = @CodPrd
                   And Cod_Lote = @CodLot
 
                Set @QtdAteAcu = @QtdAteAcu + @QtdAte

                -- verifica se lote foi solicitado fora de ordem
                Set @FlgDesord = 0
                if (@DatVct is not Null) and (@cl_QtdMesMinPrzVctLot > 0) and 
                   (Exists(Select Cod_Lote From PRLOT Where Cod_Estabe = @CodEstabe And Cod_Dep = @CodDep And Cod_Produt = @CodPrd And Qtd_Saldo > 0 And Dat_Vencim < @DatVct))
                  Set @FlgDesord = 1
                           
                -- pega endereço de picking do produto
                Select @NumRua = dx.Num_Rua,
                       @NumCol = dx.Num_Col,   
                       @NumNiv = dx.Num_Niv,   
                       @NumApt = dx.Num_Apt,
                       @dx_CodLocFis = dx.Cod_LocFis,
                       @NumEst = ISNULL(z.Num_Esteira,0)   
                  From DPXPR dx Left Outer Join
                       TBZON z on (dx.Cod_Estabe = z.Cod_Estabe and dx.Num_Rua between z.Num_RuaIni and z.Num_RuaFim)
                 Where dx.Cod_Estabe = @CodEstabe
                   And dx.Cod_Dep = @CodDep
                   And dx.Cod_Produt = @CodPrd
                       
                -- grava/regrava registro em PDVLT 
                Set @VolTotIte = (@QtdPraLot+@QtdDepLot)*@pr_VolUniMin

                 -- aqui ??? Id_PolCOm ????
                if not Exists(Select 1 From PDVLT 
                               Where Cod_Estabe = @CodEstabe 
                                 And Cod_Pedido = @CodPed And Num_Vol = @NumVol 
                                 And Cod_Produt = @CodPrd And Cod_Lote = @CodLot)
                  Insert Into PDVLT (Cod_Estabe, Cod_Pedido, Num_Vol, Cod_Produt, Cod_Lote
                                  ,  Qtd_EmbFec, Fat_CnvAprEmbPad, Qtd_Lote, Qtd_CxaFec
                                  ,  Cod_Dep, Num_Esteira, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis
                                  ,  Qtd_LotePra, Qtd_LoteDep, Vol_TotIte, Id_PolCom, Flg_Desord, Flg_Manual
                                  ,  Cod_FunSep, Transacao)
                             Values (@CodEstabe, @CodPed,    @NumVol, @CodPrd,    @CodLot
                                  ,  @QtdEmbFec, @FatCnvAprEmbPad, 0,        0
                                  ,  @CodDep, @NumEst,     @NumRua, @NumCol, @NumNiv, @NumApt, @dx_CodLocFis
                                  , 0,           0,           0,          0,         @FlgDesord,  0
                                  , 0,          @Now)
                                          
                Update PDVLT
                   Set Qtd_Lote    = IsNull(Qtd_Lote,0)    + @QtdAte,
                       Vol_TotIte  = IsNull(Vol_TotIte,0)  + @VolTotIte,
                       Qtd_LotePra = IsNull(Qtd_LotePra,0) + @QtdPraLot,
                       Qtd_LoteDep = IsNull(Qtd_LoteDep,0) + @QtdDepLot
                 Where Cod_Estabe = @CodEstabe 
                   And Cod_Pedido = @CodPed 
                   And Num_Vol = @NumVol 
                   And Cod_Produt = @CodPrd 
                   And Cod_Lote = @CodLot

                Fetch Next From PRLOT_Cr Into @LocEst, @OrdDep, @CodDep, @DatVct, @CodLot, @SldLot, @FatCnvAprEmbPad

              end  -- While (@QtdAteAcu < @QtdFra) and (@@FETCH_STATUS = 0)
              
            Close PRLOT_Cr
            Deallocate PRLOT_Cr

            Fetch Next From PDVIT_Cr Into @CodPrd, @IdPolLot, @QtdEmbFec, @pr_VolUniMin, @QtdFra
          end    -- While @@FETCH_STATUS = 0
          
        Close PDVIT_Cr
        Deallocate PDVIT_Cr

        -- verifica se necessita conferencia de caixas fechadas em transferencias

        -- verifica se necessita corrigir quantidades do pedido em PDVIT
        Exec PR_Corrige_PDVITxPDVLT @CodEstabe, @CodPed
        if @@error <> 0
          begin
            Rollback Transaction
            Return
          end

        -- normaliza quantidades 1 e 2 entre PDVLT e PDVIT
        if @FlgErr = 0
          Exec PR_NormalizaPDVITxPDVLT @CodEstabe, @CodPed

        -- verifica resultado 
        if @FlgErr = 0
          Exec PR_DivergenciasPDVITxPDVLT @CodEstabe, @CodPed, @FlgErr output, @StrMsg output


        -- reorganiza volumes
        if @FlgErr = 0
          Exec PR_ReorganizaVolumesPDV @CodEstabe, @CodPed

        -- atualiza status PDVCB
        if @FlgErr = 0
          Update PDVCB
             Set Sta_SepLot = 'F'
           Where Cod_Estabe = @CodEstabe
             And Numero = @CodPEd

        IF OBJECT_ID('tempdb..#ARQ_PRLTL') IS NOT NULL
          DROP TABLE #ARQ_PRLTL

        IF OBJECT_ID('tempdb..#ARQ_PDVIT') IS NOT NULL
          DROP TABLE #ARQ_PDVIT

      end  -- if @FlgPodeFechar = 1

    if @FlgErr = 1
      begin
        RAISERROR(@StrMsg,16,1)
        Rollback Transaction
        Return
      end
    else
      begin
        Set @DesLoc = '(DEPOIS) PR_SolicitaLotesPDV pedido: '+cast(@CodPed as varchar)
        Exec PR_Verifica_Divergencia_PRXESxPRLOT_PRLTL @DesLoc, @CodEstabe, 0

        Commit Transaction
      end
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_FechaVales]
@CodEstabe int,
@NumLot int,
@TipFat varchar(3),     -- tipo de venda do pedido a ser gerado
@CodVdr int,            -- cod. vendedor do pedido a ser gerado
@CodOpe int,            -- cod. operador
@CodAgc int,            -- cod. agente cobrador
@CodTra int,            -- cod. transportadora
@DesUsu varchar(15),    -- usuario
@StaAltPrc varchar(1),  -- (S)- altera preco, (N)- mantem preco
@PedRet int output      -- codigo do pedido gerado

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime,
        @WFlgWMS bit

Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

Set @PedRet = 0
Set @WFlgWMS = null

if (Select count(*) From (Select distinct Flg_Wms From PDVCB Where Cod_Estabe = @CodEstabe And Num_Lote = @NumLot) x) > 1
  begin
    RAISERROR('Existem pedidos de natureza distintas (WMS) neste lote',16,1)
    Return
  end
else
if not Exists(Select 1 From PDVCB Where Cod_Estabe = @CodEstabe And Status1 <> 'C' And Num_Lote = @NumLot)
  begin
    RAISERROR('Não Existem pedidos vinculados a este lote',16,1)
    Return
  end
else
  begin
    if not Exists(Select 1 From PDVCB Where Cod_Estabe = @CodEstabe And Num_Lote = @NumLot And Flg_WMS = 1)
      Set @WFlgWMS = 0
    if not Exists(Select 1 From PDVCB Where Cod_Estabe = @CodEstabe And Num_Lote = @NumLot And Flg_WMS = 0)
      Set @WFlgWMS = 1
  end

if @WFlgWMS is not null
  begin
    Begin Transaction
  
      Declare @DesLoc varchar(80) = ''
      Set @DesLoc = '(ANTES) PR_FechaVales lote: '+cast(@NumLot as varchar)
      Exec PR_Verifica_Divergencia_PRXESxPRLOT_PRLTL @DesLoc, @CodEstabe, 0


      -- colocar campos de PARAM na memoria
      Declare @pm_PerCorPrcVen numeric(18,4),
              @pm_PrzRefPrcVen int,
              @pm_QtdDiaDupVis int,
              @pm_FlgPdvPrzFab bit,
              @pm_FlgPrzLinConFin bit,
              @pm_QtdDecPrcItePdv tinyint

      Select @pm_PerCorPrcVen = IsNull(PerCorPrcVen,0),
             @pm_PrzRefPrcVen = IsNull(PrzRefPrcVen,0),
             @pm_QtdDiaDupVis = IsNull(QtdDiaDupVis,0),
             @pm_FlgPdvPrzFab = IsNull(FlgPdvPrzFab,0),
             @pm_FlgPrzLinConFin = IsNull(FlgPrzLinConFin,0),
             @pm_QtdDecPrcItePdv = IsNull(QtdDecPrcItePdv,0)
        From PARAM
       Where Cod_Estabe = @CodEstabe 

      -- coloca campos TPOPE na memoria
      Declare @to_CodCfoNorInt smallint

      Select @to_CodCfoNorInt = Isnull(Cod_CfoNorInt,0)
        From TPOPE
       Where Cod_Ope = @TipFat 

      -- variaveis para PDVCB   
      Declare @PFlgTabPrg bit,
              @PCodOriPdv varchar(2),
              @PTipDscPdv varchar(1),
              @cb_CodRegTri int,
              @cb_TipCon varchar(1),
              @cb_CodCli int,
              @cb_FlgCre smallint,
              @cb_CodPolCom varchar(25),
              @cb_IdPolCom int
 
      --variaveis p/ campos de PDVIT
      Declare @it_CodPrd int,
              @it_CodLot varchar(20),
              @it_TipSai varchar(1),
              @it_CodPrm int,
              @it_QtdPed int,
              @it_QtdBon int,
              @it_QtdPra int,
              @it_QtdDep int,
              @it_LocFis varchar(15), 
              @it_CodFab int, 
              @it_PerDsc numeric(18,4), 
              @it_PrcUni numeric(18,8),
              @it_PrcTab numeric(18,4),
              @it_PrcTabBru numeric(18,4),
              @it_FlgDsc bit,
              @it_FlgPar bit,
              @it_PrzMax int, 
              @it_DscPrz numeric(18,4), 
              @it_DscVis numeric(18,4),
              @it_FlgPrcDsc bit, 
              @it_QtdSol int,
              @it_FatCnvImpFat int,
              @it_PrcMaxCon numeric(18,4), 
              @it_PrcFab numeric(18,4), 
              @it_NumSeqDig int,
              @it_NomUsuDbq varchar(15),
              @it_DesUnvImpFat varchar(3),
              @it_DesAprImpFat varchar(12),
              @it_IdPolCom int,
              @it_FlgVerba bit,
              @it_PrcPolCom numeric(18,8),
              @it_PerDscPolCom numeric(18,4), 
              @it_PerDscVisPolCom numeric(18,4), 
			  @it_CodKitPrm int,
              @P_PrcUni numeric(18,8),
              @P_PerDsc numeric(18,4), 
              @P_PrzMax int,
              @P_DscPrz numeric(18,4),
              @P_DscVis numeric(18,4),
              @a_QtdPed int,
              @a_QtdBon int,
              @a_PrcUni numeric(18,8),
              @a_PerDsc numeric(18,4), 
              @a_PrzMax int,
              @a_DscPrz numeric(18,4),
              @a_DscVis numeric(18,4)

      --variaveis p/ campos de PRODU
      Declare @pr_PrcVenLiq numeric(18,4),
              @pr_CtrPrc varchar(1)

      -- variaveis de trabalho
      Declare @WFlgCab bit,
              @WCodVal int,
              @WTipPrz varchar(1),
              @WStrVal varchar(20),
              @WPrzMax int,
              @WCtrPrc varchar(1),
              @WPrcUni numeric(18,8)

      --variaveis p/ campos de PDVLT WMS
      Declare @lt_NumVol int,
              @lt_CodLot varchar(20),
              @lt_QtdLot int,
              @lt_QtdCxaFec int,
              @lt_CodDep smallint,
              @lt_NumRua smallint,
              @lt_NumCol smallint,
              @lt_NumNiv smallint,
              @lt_NumApt smallint,
              @lt_CodLocFis varchar(15),
              @lt_QtdLotPra int,
              @lt_QtdLotDep int,
              @lt_VolTotIte numeric(18,4), 
              @lt_QtdEmbFec int

      -- variaveis de trabalho WMS
      Declare @WNumVol smallint,
              @WNumVolAnt smallint

      -- FECHAMENTO DE VALES (SEM WMS)
      Set @WFlgCab = 0
      Set @WStrVal = cast(@NumLot as varchar)

      -- Seleciona vales do lote
      Declare PDVCB_Cr Cursor Local Fast_Forward For 

        Select Numero
          From PDVCB 
         Where Cod_Estabe = @CodEstabe 
           And Tip_Faturamento = 'VAL'
           And Num_Lote = @NumLot
         Order by Numero

      Open PDVCB_Cr
      Fetch Next From PDVCB_Cr Into @WCodVal
      While @@FETCH_STATUS = 0
        begin
          -- bloqueia o vale
          Update PDVCB
             Set Qtd_Itens = Qtd_Itens + 0
           Where Cod_Estabe = @CodEstabe 
             And Numero = @WCodVal

          -- ultimo volume do pedido consolidado
		  Set @WNumVolAnt = IsNull((Select max(Num_Vol) From PDVLT 
                                     Where Cod_Estabe = @CodEstabe and Cod_Pedido = @PedRet),0)

          --  vale --> pedido
          Declare PDVIT_Cr Cursor Local Fast_Forward For 

            Select Cod_Produto, Cod_Lote, Tip_Sai, Cod_Promocao, 
                   Qtd_Pedido, Qtd_Bonificacao, Qtd_Pra, Qtd_Dep,
                   Loc_Fisica, Cod_Fabricante, Per_Desconto, Prc_Unitario, Desconto,
                   Flg_BlqInfPar, Qtd_PrzMax, Per_Descon, Per_DscVis, Flg_PrcUniDsc,
                   Qtd_Solicitado, Prc_Tabela, Prc_TabBru, Fat_CnvImpFat, Prc_MaxCon, Prc_Fabric, 
                   Num_SeqDig, Nom_UsuDesbloq, Des_UnvImpFat, Des_AprImpFat, Cod_KitPrm,
                   Id_PolCom, IsNull(Flg_Verba,0), Prc_PolCom, Per_DscPolCom, Per_DscVisPolCom
              From PDVIT 
             Where Cod_Estabe = @CodEstabe 
               And Cod_Pedido = @WCodVal and Qtd_Pedido > 0

          Open PDVIT_Cr
          Fetch Next From PDVIT_Cr Into @it_CodPrd, @it_CodLot, @it_TipSai, @it_CodPrm, 
                                        @it_QtdPed, @it_QtdBon, @it_QtdPra, @it_QtdDep,
                                        @it_LocFis, @it_CodFab, @it_PerDsc, @it_PrcUni, @it_FlgDsc,
                                        @it_FlgPar, @it_PrzMax, @it_DscPrz, @it_DscVis, @it_FlgPrcDsc,
                                        @it_QtdSol, @it_PrcTab, @it_PrcTabBru, @it_FatCnvImpFat, @it_PrcMaxCon, @it_PrcFab, 
                                        @it_NumSeqDig, @it_NomUsuDbq, @it_DesUnvImpFat, @it_DesAprImpFat, @it_CodKitPrm,
                                        @it_IdPolCom, @it_FlgVerba, @it_PrcPolCom, @it_PerDscPolCom, @it_PerDscVisPolCom
          While @@FETCH_STATUS = 0
            begin
              -- cria cabecalho do pedido
              if @WFlgCab = 0
                begin
                  Select @cb_CodCli = Cod_Cliente,
                         @cb_FlgCre = Flg_Credito,
                         @cb_CodRegTri = Cod_RegTri,
                         @cb_TipCon = Tip_Consumidor,
                         @cb_CodPolCom = Cod_PolCom,
                         @cb_IdPolCom = Id_PolCom
                    From PDVCB
                   Where Cod_Estabe = @CodEstabe 
                     And Numero = @WCodVal

                  if @pm_PerCorPrcVen > 0
                    Set @PFlgTabPrg = 1
                  else
                    Set @PFlgTabPrg = 0

                  -- Origem do Pedido: (V)ales  +  Tipo de  prazo: (F)abricante / (L)inear
                  if @pm_FlgPdvPrzFab = 1  -- prazo por fabricante
                    Set @WTipPrz = 'F'
                  else
                    Set @WTipPrz = 'L'
                  Set @PCodOriPdv = 'V' + @WTipPrz

                  -- se for consumidor e prazo default fabricante: ver se muda para linear
                  if (@cb_TipCon = 'F') and (@pm_FlgPdvPrzFab = 1)  and (@pm_FlgPrzLinConFin = 1)
                    Set @PCodOriPdv = Substring(@PCodOriPdv,1,1) + 'L'

                  if @WTipPrz = 'F'
                    Set @PTipDscPdv = (Select Tip_DscPdv From CLIEN Where Codigo = @cb_CodCli)
                  else
                    Set @PTipDscPdv = ''

                  -- cria cabecalho novo pedido com Tipo do bloqueio = 'SR' para nao decrementar saldo
                  EXEC PR_ProxNumero 'Pedido_Venda', @PedRet output
                  Insert into PDVCB (Cod_Estabe, Numero, Status1, Status2, Tip_Pedido)
                             Values (@CodEstabe, @PedRet, 'P', 'A', 'P')
                  if @@error <> 0
                    begin
                      Rollback Transaction
                      Return
                    end                   

                  Set @WFlgCab = 1
                  Update PDVCB
                     Set Num_Lote = @NumLot, 
                         Bloqueio = 'SR', 

                         Tip_Faturamento = @TipFat, 
                         Flg_TabProgres = @PFlgTabPrg,    
                         Tip_DscPdv = @PTipDscPdv, 
                         Cod_Cliente = @cb_CodCli,
                         Cod_OrigemPdv = @PCodOriPdv, 
                         Cod_Vendedor = @CodVdr, 
                         Cod_VendTlmkt = @CodOpe, 
                         Cod_Agente = @CodAgc, 
                         Cod_Transportadora = @CodTra, 
                         Cod_RegTri = @cb_CodRegTri, 
                         Tip_Consumidor = @cb_TipCon,
                         Cod_PolCom = @cb_CodPolCom, 
                         Id_PolCom = @cb_IdPolCom,

                         Flg_WMS = @WFlgWMS,  
                         Flg_JaFechado = 0, 
                         Qtd_ImpPnt = 1, 
                         Flg_ComisNormal = 1, 
                         Flg_Credito = @cb_FlgCre, 

                         Dat_Pedido = @Date, 
                         Hor_Entrada = @Now,  
                         Observacao = 'Fechamento de Vales. Lote: '+@WStrVal,  
                         Usuario = @DesUsu, 
                         Transacao = @Now
                   Where Cod_Estabe = @CodEstabe
                     And Numero = @PedRet

                end    -- if WFlgCab                        

              -- adiciona itens do vale ao pedido
              if @WFlgWMS = 1
                Set @it_CodLot = '*'                
              if IsNull(@it_FatCnvImpFat,0) = 0
                Set @it_FatCnvImpFat = 1

              -- preco de tabela cadastro
              Select @pr_PrcVenLiq = Case 
                                       When @to_CodCfoNorInt > 0 Then Round(p.Prc_Venda*(1-p.Per_DscAut/100),@pm_QtdDecPrcItePdv)
                                       Else Round(p.Prc_Venda*(1-p.Per_DscAutOrc/100),@pm_QtdDecPrcItePdv)
                                     End,
                     @pr_CtrPrc = Ctrl_Preco
                From PRXES p Inner Join
                     PRODU pr on p.Cod_Produt = pr.Codigo
               Where p.Cod_Estabe = @CodEstabe
                 And p.Cod_Produt = @it_CodPrd

              Set @WPrcUni = IsNull(@pr_PrcVenLiq,0)
              if @WPrcUni = 0
                Set @WPrcUni = @it_PrcUni

              -- preco de tabela progressivo
              if @PFlgTabPrg = 1 and @WTipPrz = 'F'
                begin
                  Set @WPrzMax = @it_PrzMax
                  Set @WCtrPrc = @pr_CtrPrc

                  if @WCtrPrc = 'C'    -- controle de preco: monitorado
                    if @WPrzMax >= @pm_PrzRefPrcVen
                      Set @WPrcUni = @pr_PrcVenLiq
                    else
                      Set @WCtrPrc = 'L'

                  if @WCtrPrc = 'L'    -- controle de preco: liberado
                    begin
                      -- verifica parametro de dias para venda a vista
                      if @WPrzMax <= @pm_QtdDiaDupVis
                        Set @WPrzMax = 0
                      Set @WPrcUni = @pr_PrcVenLiq*(1-((@pm_PrzRefPrcVen-@WPrzMax)*Round(@pm_PerCorPrcVen,2)/3000))
                    end;
                end
              Set @WPrcUni = Round(@WPrcUni,@pm_QtdDecPrcItePdv)

              if not Exists(Select Cod_Produto From PDVIT 
                             Where Cod_Estabe = @CodEstabe And Cod_Pedido = @PedRet 
                               And Cod_Produto = @it_CodPrd And Cod_Lote = @it_CodLot And Tip_Sai = @it_TipSai)
                begin
                  -- preco unitario
                  if @StaAltPrc = 'S'
                    Set @P_PrcUni = @WPrcUni
                  else
                    Set @P_PrcUni = @it_PrcUni

                  -- condicoes de comercializacao (prazo/desconto)
                  Set @P_PrzMax = 0
                  Set @P_DscPrz = 0
                  Set @P_DscVis = 0

                  if (@WTipPrz = 'F') or (@cb_IdPolCom > 0)
                    begin
                      EXEC PR_CondComercDefaultPDVIT @CodEstabe, @TipFat, @cb_CodCli, @it_CodFab, 
                                                     @P_PrzMax output, @P_DscPrz output, @P_DscVis output
                      if @it_PrzMax > 0
                        Set @P_PrzMax = @it_PrzMax
                      else
                        Set @P_PrzMax = 0
                      if @it_DscPrz > 0
                        Set @P_DscPrz = @it_DscPrz
                      else
                        Set @P_DscPrz = 0
                      if @it_DscVis > 0
                        Set @P_DscVis = @it_DscVis
                      else
                        Set @P_DscVis = 0
                    end

                  Insert into PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai,
                                     Qtd_Pedido, Qtd_Bonificacao, Qtd_Pra, Qtd_Dep,
                                     Loc_Fisica, Cod_Fabricante, Cod_Promocao, Cod_KitPrm,
                                     Per_Desconto, Prc_Unitario, Qtd_PrzMax, Per_Descon, Per_DscVis,
                                     Qtd_Solicitado, Flg_PrcUniDsc, Desconto, Flg_BlqInfPar, Prc_Tabela, Prc_TabBru,
                                     Fat_CnvImpFat, Prc_UniImpFat, Qtd_ImpFat,
                                     Prc_MaxCon, Prc_Fabric, Num_SeqDig, Nom_UsuDesbloq, Des_UnvImpFat, Des_AprImpFat,
                                     Id_PolCom, Flg_Verba, Prc_PolCom, Per_DscPolCom, Per_DscVisPolCom)
                             Values (@CodEstabe, @PedRet, @it_CodPrd, @it_CodLot, @it_TipSai,
                                     @it_QtdPed, @it_QtdBon, @it_QtdPra, @it_QtdDep,
                                     @it_LocFis, @it_CodFab, @it_CodPrm, @it_CodKitPrm,
                                     @it_PerDsc, @P_PrcUni, @P_PrzMax, @P_DscPrz, @P_DscVis,
                                     @it_QtdSol, @it_FlgPrcDsc, @it_FlgDsc, @it_FlgPar, @it_PrcTab, @it_PrcTabBru,
                                     @it_FatCnvImpFat, @P_PrcUni*@it_FatCnvImpFat, (@it_QtdPed+@it_QtdBon)*1.0/@it_FatCnvImpFat,
                                     @it_PrcMaxCon, @it_PrcFab, @it_NumSeqDig, @it_NomUsuDbq, @it_DesUnvImpFat ,@it_DesAprImpFat,
                                     @it_IdPolCom, @it_FlgVerba, @it_PrcPolCom, @it_PerDscPolCom, @it_PerDscVisPolCom)
                  if @@error <> 0
                    begin
                      Rollback Transaction
                      Return
                    end                   
                end  --  if not Exists(
              else
                begin
                  -- preco unitario
                  if @StaAltPrc = 'S'
                    begin
                      Set @P_PrcUni = @WPrcUni

                      Update PDVIT
                         Set Prc_Unitario = @P_PrcUni
                       Where Cod_Estabe = @CodEstabe 
                         and Cod_Pedido = @PedRet 
                         and Cod_Produto = @it_CodPrd and Cod_Lote = @it_CodLot
                         and Tip_Sai = @it_TipSai
                    end
                  else
                    begin
                      -- calcula preco, prazo e descontos medios
                      Select @a_QtdPed = IsNull(Qtd_Pedido,0), 
                             @a_QtdBon = IsNull(Qtd_Bonificacao,0),
                             @a_PrcUni = IsNull(Prc_Unitario,0), 
                             @a_PerDsc = IsNull(Per_Desconto,0), 
                             @a_PrzMax = IsNull(Qtd_PrzMax,0), 
                             @a_DscPrz = IsNull(Per_Descon,0), 
                             @a_DscVis = IsNull(Per_DscVis,0)
                        From PDVIT 
                       Where Cod_Estabe = @CodEstabe 
                         and Cod_Pedido = @PedRet 
                         and Cod_Produto = @it_CodPrd and Cod_Lote = @it_CodLot
                         and Tip_Sai = @it_TipSai

                      -- calcula preco medio unitario
                      Set @P_PrcUni = Round((@it_QtdPed*@it_PrcUni+@a_QtdPed*@a_PrcUni)/(@it_QtdPed+@a_QtdPed),@pm_QtdDecPrcItePdv)
  
                      -- calcula descontos medios
                      Set @P_PerDsc = Round((@it_QtdPed*@it_PrcUni*@it_PerDsc/100+@a_QtdPed*@a_PrcUni*@a_PerDsc/100)*100/(@P_PrcUni*(@it_QtdPed+@a_QtdPed)),2)
                      Set @P_DscPrz = Round((@it_QtdPed*@it_PrcUni*@it_DscPrz/100+@a_QtdPed*@a_PrcUni*@a_DscPrz/100)*100/(@P_PrcUni*(@it_QtdPed+@a_QtdPed)),2)
                      Set @P_DscVis = Round((@it_QtdPed*@it_PrcUni*@it_DscVis/100+@a_QtdPed*@a_PrcUni*@a_DscVis/100)*100/(@P_PrcUni*(@it_QtdPed+@a_QtdPed)),2)

                      -- calcula prazo medio
                      Set @P_PrzMax = Round((@it_PrzMax*@it_QtdPed*@it_PrcUni+@a_PrzMax*@a_QtdPed*@a_PrcUni)/(@it_QtdPed*@it_PrcUni+@a_QtdPed*@a_PrcUni),0)

                      Update PDVIT
                         Set Prc_Unitario = @P_PrcUni, 
                             Per_Desconto = @P_PerDsc,
                             Per_Descon = @P_DscPrz,
                             Per_DscVis = @P_DscVis,
                             Qtd_PrzMax = @P_PrzMax
                       Where Cod_Estabe = @CodEstabe     
                         and Cod_Pedido = @PedRet 
                         and Cod_Produto = @it_CodPrd and Cod_Lote = @it_CodLot
                         and Tip_Sai = @it_TipSai
                    end  

                  Update PDVIT
                     Set Qtd_Pedido = Qtd_Pedido + @it_QtdPed,
                         Qtd_Bonificacao = Qtd_Bonificacao + @it_QtdBon,
                         Qtd_Pra = Qtd_Pra + @it_QtdPra,
                         Qtd_Dep = Qtd_Dep + @it_QtdDep,
                         Qtd_Solicitado = Qtd_Solicitado + @it_QtdSol
                   Where Cod_Estabe = @CodEstabe     
                     and Cod_Pedido = @PedRet 
                     and Cod_Produto = @it_CodPrd and Cod_Lote = @it_CodLot
                     and Tip_Sai = @it_TipSai

                  -- normaliza valores p/ impressao da NF
                  Update PDVIT
                     Set Qtd_ImpFat = (Qtd_Pedido+Qtd_Bonificacao)*1.0/Fat_CnvImpFat,
                         Prc_UniImpFat = Prc_Unitario*Fat_CnvImpFat
                   Where Cod_Estabe = @CodEstabe    
                     and Cod_Pedido = @PedRet 
                     and Cod_Produto = @it_CodPrd and Cod_Lote = @it_CodLot
                     and Tip_Sai = @it_TipSai
                end

              -- insere lotes em PDVLT
              if @WFlgWMS = 1
                begin
                  Declare PDVLT_Cr Cursor Local Fast_Forward For 

                    Select Num_Vol, Cod_Lote, Qtd_Lote, Qtd_CxaFec, 
                           Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis,
                           Qtd_LotePra, Qtd_LoteDep, Vol_TotIte, Qtd_EmbFec
                      From PDVLT 
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Pedido = @WCodVal 
                       And Cod_Produt = @it_CodPrd
                     Order by Qtd_CxaFec

                  Open PDVLT_Cr
                  Fetch Next From PDVLT_Cr Into @lt_NumVol, @lt_CodLot, @lt_QtdLot, @lt_QtdCxaFec, 
                                                @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt, @lt_CodLocFis,
                                                @lt_QtdLotPra, @lt_QtdLotDep, @lt_VolTotIte, @lt_QtdEmbFec
                  While @@FETCH_STATUS = 0
                    begin
                      Set @WNumVol = @WNumVolAnt + @lt_NumVol

                      if not Exists(Select 1 From PDVLT 
                                     Where Cod_Estabe = @CodEstabe And Cod_Pedido = @PedRet and Num_Vol = @WNumVol
                                       and Cod_Produt = @it_CodPrd and Cod_Lote = @lt_CodLot)
                        begin
                          Insert into PDVLT (Cod_Estabe, Cod_Pedido, Num_Vol, Cod_Produt, Cod_Lote,
                                             Qtd_EmbFec, Qtd_Lote, Qtd_CxaFec,
                                             Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis,
                                             Qtd_LotePra, Qtd_LoteDep, Vol_TotIte)
                                     Values (@CodEstabe, @PedRet, @WNumVol, @it_CodPrd, @lt_CodLot,
                                             @lt_QtdEmbFec, 0, 0,
                                             @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt, @lt_CodLocFis,
                                             0, 0, 0)
                          if @@error <> 0
                            begin
                              Rollback Transaction
                              Return
                            end
                        end

                      Update PDVLT
                         Set Qtd_Lote = Qtd_Lote + @lt_QtdLot,
                             Qtd_CxaFec = Qtd_CxaFec + @lt_QtdCxaFec,
                             Qtd_LotePra = Qtd_LotePra + @lt_QtdLotPra,
                             Qtd_LoteDep = Qtd_LoteDep + @lt_QtdLotDep,
                             Vol_TotIte = Vol_TotIte + @lt_VolTotIte
                       Where Cod_Estabe = @CodEstabe     
                         and Cod_Pedido = @PedRet and Num_Vol = @WNumVol 
                         and Cod_Produt = @it_CodPrd and Cod_Lote = @lt_CodLot
             
                      Fetch Next From PDVLT_Cr Into @lt_NumVol, @lt_CodLot, @lt_QtdLot, @lt_QtdCxaFec, 
                                                    @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt, @lt_CodLocFis,
                                                    @lt_QtdLotPra, @lt_QtdLotDep, @lt_VolTotIte, @lt_QtdEmbFec
                    end    -- while

                  Close PDVLT_Cr
                  Deallocate PDVLT_Cr
                end

              Fetch Next From PDVIT_Cr Into @it_CodPrd, @it_CodLot, @it_TipSai, @it_CodPrm, 
                                            @it_QtdPed, @it_QtdBon, @it_QtdPra, @it_QtdDep,
                                            @it_LocFis, @it_CodFab, @it_PerDsc, @it_PrcUni, @it_FlgDsc,
                                            @it_FlgPar, @it_PrzMax, @it_DscPrz, @it_DscVis, @it_FlgPrcDsc,
                                            @it_QtdSol, @it_PrcTab, @It_PrcTabBru, @it_FatCnvImpFat, @it_PrcMaxCon, @it_PrcFab, 
                                            @it_NumSeqDig, @it_NomUsuDbq, @it_DesUnvImpFat, @it_DesAprImpFat, @it_CodKitPrm,
                                            @it_IdPolCom, @it_FlgVerba, @it_PrcPolCom, @it_PerDscPolCom, @it_PerDscVisPolCom
            end    -- while

          Close PDVIT_Cr
          Deallocate PDVIT_Cr

          -- cancela o vale
          Update PDVCB
             Set Status1 = 'C',
                 Bloqueio = 'SR'
           Where Cod_Estabe = @CodEstabe       
             And Numero = @WCodVal

          Fetch Next From PDVCB_Cr Into @WCodVal
        end    -- while

      Close PDVCB_Cr
      Deallocate PDVCB_Cr

      -- atualiza bloqueio do novo pedido
      Update PDVCB
         Set Bloqueio = ''
       Where Cod_Estabe = @CodEstabe 
         and Numero = @PedRet        

      -- registra divergencias no log
      Set @DesLoc = '(DEPOIS) PR_FechaVales lote: '+cast(@NumLot as varchar)
      Exec PR_Verifica_Divergencia_PRXESxPRLOT_PRLTL @DesLoc, @CodEstabe, 0

    Commit Transaction
  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ReprocessaQtdSolicPRODU]
@PCodEstabe int

AS

SET NOCOUNT ON
SET ANSI_WARNINGS OFF

BEGIN TRANSACTION

Declare @CodPrd int,
        @CodLot varchar(20),
        @QtdMov int,
        @QtdPra int,
        @QtdDep int,
        @CodPrm int,
        @QtdDis int,
        @QtdCxaFec int,
        @QtdEmbFec int,
        @CodDep smallint, 
        @NumRua smallint, 
        @NumCol smallint , 
        @NumNiv smallint, 
        @NumApt smallint,
        @DatVct smalldatetime

  Set @CodDep = IsNull((Select top 1 Cod_Dep From TBDEP Order by Cod_Dep),1)

-----------------------

-- Normaliza PRLOT/PRLTL
  Update PRLOT
     Set Cod_Dep = @CodDep
   Where Cod_Estabe = @PCodEstabe  
     And IsNull(Cod_Dep,0) < @CodDep
     And Not Exists (Select Cod_Estabe, @CodDep, Cod_Produt, Cod_Lote 
           Intersect
           Select Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote From PRLOT)
  
  Update PRLTL
     Set Cod_Dep = @CodDep
   Where Cod_Estabe = @PCodEstabe  
     And IsNull(Cod_Dep,0) < @CodDep
  
  Update PRLTL
     Set Qtd_EmbFec = 1
   Where Cod_Estabe = @PCodEstabe    
     And IsNull(Qtd_EmbFec,0) <= 0    
  
  Update l1
     Set l1.Dat_Vencim = l2.Dat_Vencim
    From PRLTL l1 Inner Join
         (Select Cod_Estabe, Cod_Produt, Cod_Lote, Dat_Vencim = max(Dat_Vencim), Dat_Fabric = max(Dat_Fabric)
            From PRLTL
           Where Cod_Estabe = @PCodEstabe 
             And Cod_Produt > 0
           Group by Cod_Estabe, Cod_Produt, Cod_Lote) l2 on (l1.Cod_Estabe = l2.Cod_Estabe and 
                                                             l1.Cod_Produt = l2.Cod_Produt and 
                                                             l1.Cod_Lote = l2.Cod_Lote)
   Where l1.Cod_Estabe = @PCodEstabe
     And IsNull(l1.Dat_Vencim,0) <> IsNull(l2.Dat_Vencim,0)       
  
  Update l1
     Set l1.Dat_Fabric = l2.Dat_Fabric
    From PRLTL l1 Inner Join
         (Select Cod_Estabe, Cod_Produt, Cod_Lote, Dat_Vencim = max(Dat_Vencim), Dat_Fabric = max(Dat_Fabric)
            From PRLTL
           Where Cod_Estabe = @PCodEstabe 
             and Cod_Produt > 0
           Group by Cod_Estabe, Cod_Produt, Cod_Lote) l2 on (l1.Cod_Estabe = l2.Cod_Estabe and 
                                                             l1.Cod_Produt = l2.Cod_Produt and 
                                                             l1.Cod_Lote = l2.Cod_Lote)
   Where l1.Cod_Estabe = @PCodEstabe
     And IsNull(l1.Dat_Fabric,0) <> IsNull(l2.Dat_Fabric,0)       
  
  Update l1
     Set l1.Dat_Vencim = l2.Dat_Vencim
    From PRLTL l1, PRLOT l2
   Where l1.Cod_Estabe = l2.Cod_Estabe
     And l1.Cod_Produt = l2.Cod_Produt
     And l1.Cod_Lote = l2.Cod_Lote
     And l1.Cod_Estabe = @PCodEstabe
     And IsNull(l1.Dat_Vencim,0) <> IsNull(l2.Dat_Vencim,0)
  
  Update l1
     Set l1.Dat_Fabric = l2.Dat_Fabric
    From PRLTL l1, PRLOT l2
   Where l1.Cod_Estabe = l2.Cod_Estabe
     And l1.Cod_Produt = l2.Cod_Produt
     And l1.Cod_Lote = l2.Cod_Lote
     And l1.Cod_Estabe = @PCodEstabe
     And IsNull(l1.Dat_Fabric,0) <> IsNull(l2.Dat_Fabric,0)
  
  Update l1
     Set l1.Dat_Vencim = l2.Dat_Vencim
    From PRLOT l1 Inner Join
         (Select Cod_Estabe,Cod_Produt, Cod_Lote, Dat_Vencim = max(Dat_Vencim), Dat_Fabric = max(Dat_Fabric)
            From PRLTL
           Where Cod_Estabe = @PCodEstabe 
             And Cod_Produt > 0
           Group by Cod_Estabe, Cod_Produt, Cod_Lote) l2 on (l1.Cod_Estabe = l2.Cod_Estabe and 
                                                             l1.Cod_Produt = l2.Cod_Produt and 
                                                             l1.Cod_Lote = l2.Cod_Lote)
   Where l1.Cod_Estabe = @PCodEstabe
     And IsNull(l1.Dat_Vencim,0) <> IsNull(l2.Dat_Vencim,0)       
  
  Update l1
     Set l1.Dat_Fabric = l2.Dat_Fabric
    From PRLOT l1 Inner Join
         (Select Cod_Estabe, Cod_Produt, Cod_Lote, Dat_Vencim = max(Dat_Vencim), Dat_Fabric = max(Dat_Fabric)
            From PRLTL
           Where Cod_Estabe = @PCodEstabe 
             And Cod_Produt > 0
           Group by Cod_Estabe, Cod_Produt, Cod_Lote) l2 on (l1.Cod_Estabe = l2.Cod_Estabe and 
                                                             l1.Cod_Produt = l2.Cod_Produt and 
                                                             l1.Cod_Lote = l2.Cod_Lote)
   Where l1.Cod_Estabe = @PCodEstabe 
     And IsNull(l1.Dat_Fabric,0) <> IsNull(l2.Dat_Fabric,0)       
  

  Delete lt
    From PRLOT lt
         Inner Join PRXES pr on lt.Cod_Estabe = pr.Cod_Estabe and lt.Cod_Produt = pr.Cod_Produt
   Where lt.Cod_Estabe = @PCodEstabe
     And lt.Qtd_Saldo > 0
     And pr.Qtd_Dispon = 0     
     And not Exists(Select 1 From PRSLD s Where pr.Cod_Estabe = s.Cod_Estabe and pr.Cod_Produt = s.Cod_Produt)

  -- se não existir, insere em PRLOT lotes de PRLTL
  Insert into PRLOT(Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Dat_Vencim, Dat_Fabric, Qtd_FisPra, Qtd_SolPra, Qtd_FisDep, Qtd_SolDep)
    Select distinct l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Cod_Lote, max(l1.Dat_Vencim), max(l1.Dat_Fabric), 0, 0, 0, 0
      From PRLTL l1 
     Where l1.Cod_Estabe = @PCodEstabe 
       And l1.Qtd_Fisico > 0
       And not Exists(Select 1 From PRLOT l2 
                       Where l1.Cod_Estabe = l2.Cod_Estabe and l1.Cod_Dep = l2.Cod_Dep
                         and l1.Cod_Produt = l2.Cod_Produt and l1.Cod_Lote = l2.Cod_Lote)
     Group by l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Cod_Lote

-- normaliza pRLOT
/*
  Update PRLOT
     Set Qtd_FisPra = Qtd_FisPra + Qtd_FisDep, 
         Qtd_FisDep = 0
   Where Cod_Estabe = @PCodEstabe
     And Qtd_FisDep < 0
*/

  Update PRLOT
     Set Qtd_FisPra = 0
  Where Cod_Estabe = @PCodEstabe
    And Qtd_FisPra < 0

  Update PRLOT
     Set Qtd_FisDep = 0
   Where Cod_Estabe = @PCodEstabe
     And Qtd_FisDep < 0

  Delete 
    From PRLTL
   Where Cod_Estabe = @PCodEstabe
     And IsNull(Qtd_Fisico,0) = 0

  Delete lt
    From PRLOT lt 
         Left Join PRLTL dp on ((lt.Cod_Estabe = dp.Cod_Estabe) and (lt.Cod_Produt = dp.Cod_Produt) and (lt.Cod_Lote = dp.Cod_Lote))
 Where lt.Cod_Estabe = @PCodEstabe     
   And lt.Qtd_Fisico = 0
   And IsNull(lt.Cod_Lote,'') = ''
   And IsNull(dp.Qtd_Fisico,0) = 0

  -- normalizando PDVLT e PRLTL e PRLOT
  Update PDVLT
     Set Num_Apt = 0
   Where Cod_Estabe = @PCodEstabe    
     And Num_Apt is null

  Update PRLTL
     Set Num_Apt = 0
   Where Cod_Estabe = @PCodEstabe    
     And Num_Apt is null

  Update PRLOT
     Set Cod_Lote = '*'
   Where Cod_Estabe = @PCodEstabe    
     And IsNull(Cod_Lote,'') = ''

  Update PRLTL
     Set Cod_Lote = '*'
   Where Cod_Estabe = @PCodEstabe    
     And IsNull(Cod_Lote,'') = ''


  -- normaliza quantidades dos estoques nos itens de pedido
  if Exists(Select top 1 1
              From PDVIT it
             Where it.Cod_Estabe = @PCodEstabe 
               And not Exists (Select 1 From PDVCB cb Where cb.Cod_Estabe = it.Cod_Estabe And cb.Numero = it.Cod_Pedido))
    begin
      Delete it
        From PDVIT it
       Where it.Cod_Estabe = @PCodEstabe 
         And not Exists (Select 1 From PDVCB cb Where cb.Cod_Estabe = it.Cod_Estabe And cb.Numero = it.Cod_Pedido)
    end
  
  if Exists(Select top 1 1
              From ORCIT it
             Where it.Cod_Estabe = @PCodEstabe 
               And not Exists (Select 1 From ORCCB cb Where cb.Cod_Estabe = it.Cod_Estabe And cb.Cod_Orcame = it.Cod_Orcame))
    begin
      Delete it
        From ORCIT it 
       Where it.Cod_Estabe = @PCodEstabe  
         And not Exists (Select 1 From ORCCB cb Where cb.Cod_Estabe = it.Cod_Estabe And cb.Cod_Orcame = it.Cod_Orcame)
    end

  if Exists(Select top 1 1
              From PDVLT it
             Where it.Cod_Estabe = @PCodEstabe 
               And not Exists (Select 1 From PDVCB cb Where cb.Cod_Estabe = it.Cod_Estabe And cb.Numero = it.Cod_Pedido))
    Delete it
      From PDVLT it 
    Where it.Cod_Estabe = @PCodEstabe 
      And not Exists (Select 1 From PDVCB cb Where cb.Cod_Estabe = it.Cod_Estabe And cb.Numero = it.Cod_Pedido)
    

  If object_id('tempdb..#PDVCB') Is Not Null
    Drop Table #PDVCB;

  Select Cod_Estabe, Numero Into #PDVCB
  From (
  Select Cb.Cod_Estabe, cb.Numero
    From PDVCB cb
   Where cb.Tip_Pedido <> 'C' And cb.Status1 <> 'P' And cb.Status2 <> 'A'
      And ( Exists(Select it.Cod_Pedido 
                     From PDVIT it
                    Where it.Cod_Estabe = cb.Cod_Estabe and it.Cod_Pedido = cb.Numero
                      And (Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0)) <> (Isnull(it.Qtd_Pra,0)+Isnull(it.Qtd_Dep,0)))) 
     And (cb.Flg_Calc = 0 Or cb.Flg_Calc Is Null)
  UNION 
  Select Cb.Cod_Estabe, cb.Numero
    From PDVCB cb
   Where cb.Tip_Pedido <> 'C' And cb.Status1 <> 'P' And cb.Status2 <> 'A'
      And ( Exists(Select it.Cod_Pedido 
                     From PDVLT it
                    Where it.Cod_Estabe = cb.Cod_Estabe and it.Cod_Pedido = cb.Numero
                      And Isnull(it.Qtd_Lote,0) <> (Isnull(it.Qtd_LotePra,0)+Isnull(it.Qtd_LoteDep,0)))) 
     And (cb.Flg_Calc = 0 Or cb.Flg_Calc Is Null)
  ) as X

  Update cb 
     Set Flg_Calc = 1
    From PDVCB cb
   JOIN #PDVCB T ON cb.Cod_Estabe = T.Cod_Estabe And cb.Numero = T.Numero


  if Exists(Select top 1 1
              From PDVCB cb 
                   inner Join PDVIT it on (cb.Cod_Estabe = it.Cod_Estabe  and cb.Numero = it.Cod_Pedido)
             Where cb.Cod_Estabe = @PCodEstabe
               and cb.Tip_Pedido = 'P'
               and IsNull(cb.Flg_WMS,0) = 1 
               and not Exists(Select 1 From PDVLT lt Where lt.Cod_Estabe = cb.Cod_Estabe and lt.Cod_Pedido = cb.Numero)
               and cb.Status1 = 'P'
               and cb.Status2 <> 'N'
               and IsNull(cb.Bloqueio,'') <> 'SR'
               and (Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0)) <> (Isnull(it.Qtd_Pra,0)+Isnull(it.Qtd_Dep,0)))
    begin
      Update it
         Set it.Qtd_Pra = 0,
             it.Qtd_Dep = 0
        From PDVCB cb 
             inner Join PDVIT it on (cb.Cod_Estabe = it.Cod_Estabe  and cb.Numero = it.Cod_Pedido)
       Where cb.Cod_Estabe = @PCodEstabe
         and cb.Tip_Pedido = 'P'
         and IsNull(cb.Flg_WMS,0) = 1 
         and not Exists(Select 1 From PDVLT lt Where lt.Cod_Estabe = cb.Cod_Estabe and lt.Cod_Pedido = cb.Numero)
         and cb.Status1 = 'P'
         and cb.Status2 <> 'N'
         and IsNull(cb.Bloqueio,'') <> 'SR'
         and (Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0)) <> (Isnull(it.Qtd_Pra,0)+Isnull(it.Qtd_Dep,0))
    end

  -- normaliza quantidades dos estoques nos itens de pedido em PDVIT
  if Exists(Select 1
              From PDVCB cb Inner Join
                   PDVIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Cod_Pedido
             Where cb.Cod_Estabe = @PCodEstabe
               And cb.Tip_Pedido = 'P'
               And cb.Status1 = 'P'
               And cb.Status2 <> 'N'
               And IsNull(cb.Bloqueio,'') <> 'SR'
               And (Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0)) <> (Isnull(it.Qtd_Pra,0)+Isnull(it.Qtd_Dep,0)))
    begin
      Update it
         Set it.Qtd_Pra = Case
                            when (Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0) > IsNull(it.Qtd_Dep,0)) then
                              Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0)-IsNull(it.Qtd_Dep,0)
                            else 0 
                          end
        From PDVCB cb Inner Join
             PDVIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Cod_Pedido
       Where cb.Cod_Estabe = @PCodEstabe
         And cb.Tip_Pedido = 'P'
         And cb.Status1 = 'P'
         And cb.Status2 <> 'N'
         And IsNull(cb.Bloqueio,'') <> 'SR'
         And (Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0)) <> (Isnull(it.Qtd_Pra,0)+Isnull(it.Qtd_Dep,0))
    end
    
  if Exists(Select top 1 1
              From PDVCB cb 
                   inner Join PDVIT it on (cb.Cod_Estabe = it.Cod_Estabe  and cb.Numero = it.Cod_Pedido)
             Where cb.Cod_Estabe = @PCodEstabe
               and cb.Tip_Pedido = 'P'
               and ( (IsNull(cb.Flg_WMS,0) = 0) or 
                     ( (IsNull(cb.Flg_WMS,0) = 1) and 
                       (not Exists(Select 1 From PDVLT lt Where lt.Cod_Estabe = cb.Cod_Estabe and lt.Cod_Pedido = cb.Numero) ) ))
               and cb.Status1 = 'P'
               and cb.Status2 <> 'N'
               and IsNull(cb.Bloqueio,'') <> 'SR'
               and (Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0)) <> (Isnull(it.Qtd_Pra,0)+Isnull(it.Qtd_Dep,0)))
    begin
      Update it
         Set it.Qtd_Dep = Case
                            when (Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0) > IsNull(it.Qtd_Pra,0)) then
                              Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0)-IsNull(it.Qtd_Pra,0)
                            else 0 
                          end
        From PDVCB cb inner Join 
             PDVIT it on (cb.Cod_Estabe = it.Cod_Estabe  and cb.Numero = it.Cod_Pedido)
       Where cb.Cod_Estabe = @PCodEstabe
         and cb.Tip_Pedido = 'P'
         and ( (IsNull(cb.Flg_WMS,0) = 0) or 
               ((IsNull(cb.Flg_WMS,0) = 1) and (not Exists(Select 1 From PDVLT lt Where lt.Cod_Estabe = cb.Cod_Estabe and lt.Cod_Pedido = cb.Numero))) )
         and cb.Status1 = 'P'
         and cb.Status2 <> 'N'
         and IsNull(cb.Bloqueio,'') <> 'SR'
         and (Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0)) <> (Isnull(it.Qtd_Pra,0)+Isnull(it.Qtd_Dep,0))
    end
  
  -- normaliza quantidades dos estoques nos itens de pedido em PDVLT
  if Exists(Select top 1 1 
              From PDVCB cb 
                   inner Join PDVLT it on (cb.Cod_Estabe = it.Cod_Estabe  and cb.Numero = it.Cod_Pedido)
             Where cb.Cod_Estabe = @PCodEstabe
               and cb.Tip_Pedido = 'P'
               and cb.Status1 = 'P'
               and cb.Status2 <> 'N'
               and cb.Status2 <> 'D'
               and IsNull(cb.Bloqueio,'') <> 'SR'
               and Isnull(it.Qtd_Lote,0) <> (Isnull(it.Qtd_LotePra,0)+Isnull(it.Qtd_LoteDep,0)))
    begin
      Update it
         Set it.Qtd_LotePra = Case
                                when (Isnull(it.Qtd_Lote,0) > IsNull(it.Qtd_LoteDep,0)) then
                                  Isnull(it.Qtd_Lote,0)-IsNull(it.Qtd_LoteDep,0)
                                else 0 
                              end
        From PDVCB cb 
             inner Join PDVLT it on (cb.Cod_Estabe = it.Cod_Estabe  and cb.Numero = it.Cod_Pedido)
       Where cb.Cod_Estabe = @PCodEstabe
         and cb.Tip_Pedido = 'P'
         and cb.Status1 = 'P'
         and cb.Status2 <> 'N'
         and cb.Status2 <> 'D'
         and IsNull(cb.Bloqueio,'') <> 'SR'
         and Isnull(it.Qtd_Lote,0) <> (Isnull(it.Qtd_LotePra,0)+Isnull(it.Qtd_LoteDep,0))
    end

  if Exists(Select top 1 1   
              From PDVCB cb 
                   inner Join PDVLT it on (cb.Cod_Estabe = it.Cod_Estabe  and cb.Numero = it.Cod_Pedido)
             Where cb.Cod_Estabe = @PCodEstabe
               and cb.Tip_Pedido = 'P'
               and cb.Status1 = 'P'
               and cb.Status2 <> 'N'
               and cb.Status2 <> 'D'
               and IsNull(cb.Bloqueio,'') <> 'SR'
               and Isnull(it.Qtd_Lote,0) <> (Isnull(it.Qtd_LotePra,0)+Isnull(it.Qtd_LoteDep,0)))
    begin
      Update it
         Set it.Qtd_LoteDep = Case
                                when (Isnull(it.Qtd_Lote,0) > IsNull(it.Qtd_LotePra,0)) then
                                  Isnull(it.Qtd_Lote,0)-IsNull(it.Qtd_LotePra,0)
                                else 0 
                              end
        From PDVCB cb 
             inner Join PDVLT it on (cb.Cod_Estabe = it.Cod_Estabe  and cb.Numero = it.Cod_Pedido)
       Where cb.Cod_Estabe = @PCodEstabe
         and cb.Tip_Pedido = 'P'
         and cb.Status1 = 'P'
         and cb.Status2 <> 'N'
         and cb.Status2 <> 'D'
         and IsNull(cb.Bloqueio,'') <> 'SR'
         and Isnull(it.Qtd_Lote,0) <> (Isnull(it.Qtd_LotePra,0)+Isnull(it.Qtd_LoteDep,0))
    end

  Update PDVCB
     Set Flg_Calc = 0
   Where Cod_Estabe = @PCodEstabe 
     and Flg_Calc = 1


  -- zerando solicitacoes em PRLOT
  Update PRLOT
     Set Qtd_SolPra = 0,
         Qtd_SolDep = 0
   Where Cod_Estabe = @PCodEstabe    
            
  -- zerando solicitacoes em PRLTL
  Update PRLTL
     Set Qtd_SolPra = 0,
         Qtd_SolDep = 0
   Where Cod_Estabe = @PCodEstabe    

  
  -- atualiza solicitacoes em PRLOT (RESERVAS)
  Insert Into PRLOT (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Qtd_FisPra, Qtd_FisDep)
    Select r.Cod_Estabe, r.Cod_Dep, r.Cod_Produto, r.Cod_Lote, 
           sum(Isnull(r.Qtd_Movimento,0)) as Qtd_ResPra, 
           sum(Isnull(r.Qtd_ResDep,0)) as Qtd_ResDep
      From RESER r
     Where r.Cod_Estabe = @PCodEstabe     
       And not Exists(Select 1 From PRLOT l 
                       Where (r.Cod_Estabe = l.Cod_Estabe) and (r.Cod_Dep = l.Cod_Dep)
                         and (r.Cod_Produto = l.Cod_Produt) and (r.Cod_Lote = l.Cod_Lote))
     Group by r.Cod_Estabe, r.Cod_Dep, r.Cod_Produto, r.Cod_Lote
  
  Update l
     Set l.Qtd_SolPra = l.Qtd_SolPra + r.QtdResPra,
         l.Qtd_SolDep = l.Qtd_SolDep + r.QtdResDep
    From PRLOT l 
         Inner Join (Select Cod_Estabe, Cod_Dep, Cod_Produto, Cod_Lote, 
                            sum(Isnull(Qtd_Movimento,0)) as QtdResPra, 
                            sum(Isnull(Qtd_ResDep,0)) as QtdResDep
                       From RESER 
                      Where Cod_Estabe = @PCodEstabe
                      Group by Cod_Estabe, Cod_Dep, Cod_Produto, Cod_Lote) r on (l.Cod_Estabe = r.Cod_Estabe and l.Cod_Dep = r.Cod_Dep 
                                                                            and  l.Cod_Produt = r.Cod_Produto and  l.Cod_Lote = r.Cod_Lote)
   Where l.Cod_Estabe = @PCodEstabe      

  -- atualiza solicitacoes em PRLOT (AVARIAS)
  Insert Into PRLOT (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Qtd_FisPra, Qtd_FisDep)
    Select a.Cod_Estabe, a.Cod_Dep, a.Cod_Produto, a.Cod_Lote, 
           sum(Isnull(a.Qtd_Movimento,0)) as Qtd_AvaPra, 
           sum(Isnull(a.Qtd_AvaDep,0)) as Qtd_AvaDep
      From AVARI a
     Where a.Cod_Estabe = @PCodEstabe 
       And not Exists(Select 1 From PRLOT l 
                       Where (a.Cod_Estabe = l.Cod_Estabe) and (a.Cod_Dep = l.Cod_Dep)
                         and (a.Cod_Produto = l.Cod_Produt) and (a.Cod_Lote = l.Cod_Lote))
     Group by a.Cod_Estabe, a.Cod_Dep, a.Cod_Produto, a.Cod_Lote
  
  Update l
     Set l.Qtd_SolPra = l.Qtd_SolPra + a.QtdAvaPra,
         l.Qtd_SolDep = l.Qtd_SolDep + a.QtdAvaDep
    From PRLOT l 
         Inner Join (Select Cod_Estabe, Cod_Dep, Cod_Produto, Cod_Lote, 
                            sum(Isnull(Qtd_Movimento,0)) as QtdAvaPra, 
                            sum(Isnull(Qtd_AvaDep,0)) as QtdAvaDep
                       From AVARI 
                      Where Cod_Estabe = @PCodEstabe
                      Group by Cod_Estabe, Cod_Dep, Cod_Produto, Cod_Lote) a on (l.Cod_Estabe = a.Cod_Estabe and l.Cod_Dep = a.Cod_Dep 
                                                                  and  l.Cod_Produt = a.Cod_Produto and  l.Cod_Lote = a.Cod_Lote)
   Where l.Cod_Estabe = @PCodEstabe      

  -- atualiza solicitacoes em PRLOT (PEDIDOS)
  Declare PDVIT_Cr Cursor Local For 
    Select it.Cod_Produto, it.Cod_Lote,
           sum(Isnull(it.Qtd_Pra,0)), sum(Isnull(it.Qtd_Dep,0))
      From PDVCB cb 
           Inner Join PDVIT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Numero = it.Cod_Pedido)
     Where cb.Cod_Estabe = @PCodEstabe
       and cb.Tip_Pedido = 'P'
       and IsNull(cb.Flg_WMS,0) = 0
       and cb.Status1 = 'P'
       and cb.Status2 <> 'N'
       and cb.Status2 <> 'D'
       and IsNull(cb.Bloqueio,'') <> 'SR'
       and (IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) > 0
     Group by it.Cod_Produto, it.Cod_Lote
    UNION ALL
    Select it.Cod_Produt, it.Cod_Lote,
           sum(Isnull(it.Qtd_Produt,0)), 0
    From ORCCB cb 
         Inner Join ORCIT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Cod_Orcame = it.Cod_Orcame)
   Where cb.Cod_Estabe = @PCodEstabe
     And cb.Sta_Movime = 'F'
     and IsNull(cb.Num_Docume,0) = 0
     and it.Tip_EntSai = 'S'
     And IsNull(cb.Cod_OriVen,'') <> 'DMD'
     and (IsNull(it.Qtd_Produt,0)) > 0
   Group by it.Cod_Produt, it.Cod_Lote
   Order by Cod_Produto, Cod_Lote
  Open PDVIT_Cr
  Fetch Next From PDVIT_Cr Into @CodPrd, @CodLot, @QtdPra, @QtdDep
  While @@FETCH_STATUS = 0
    begin
      if Not Exists(Select 1 From PRLOT 
                     Where Cod_Estabe = @PCodEstabe 
                       And Cod_Dep = @CodDep
                       And Cod_Produt = @CodPrd 
                       And Cod_Lote = @CodLot) 
        begin
          Set @DatVct = (Select Top 1 it.Dat_Vencim
                           from NFECB cb 
                                Inner Join NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Protocolo = it.Protocolo)
                          Where cb.Cod_Estabe = @PCodEstabe
                            And it.Cod_Produto = @CodPrd
                            And it.Cod_Lote = @CodLot
                            And cb.Status = 'F'
                          Order by it.Dat_Movimento desc)
          Insert Into PRLOT (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Dat_Vencim, Qtd_FisPra, Qtd_FisDep)
                     Values (@PCodEstabe, @CodDep, @CodPrd, @CodLot, @DatVct, 0, 0)
        end
  
      Update PRLOT
         Set Qtd_SolPra = Qtd_SolPra + @QtdPra,
             Qtd_SolDep = Qtd_SolDep + @QtdDep
       Where Cod_Estabe = @PCodEstabe    
         And Cod_Dep = @CodDep
         And (Cod_Produt = @CodPrd) and (Cod_Lote = @CodLot)
  
      Fetch Next From PDVIT_Cr Into @CodPrd, @CodLot, @QtdPra, @QtdDep
    end
  Close PDVIT_Cr
  Deallocate PDVIT_Cr
  
  -- atualiza solicitacoes em PRLOT/PRLTL (PEDIDOS - PDVLT)
  Declare PDVLT_Cr Cursor Local For 
    Select it.Cod_Produt, it.Cod_Lote, it.Qtd_CxaFec, it.Qtd_EmbFec,
           it.Cod_Dep, it.Num_Rua, it.Num_Col, it.Num_Niv, Num_Apt,
           sum(Isnull(it.Qtd_LotePra,0)),
           sum(Isnull(it.Qtd_LoteDep,0))
      From PDVCB cb 
           Inner Join PDVLT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Numero = it.Cod_Pedido)
     Where cb.Cod_Estabe = @PCodEstabe
       and cb.Tip_Pedido = 'P'
       and IsNull(cb.Flg_WMS,0) = 1
       and cb.Status1 = 'P'
       and cb.Status2 <> 'N'
       and cb.Status2 <> 'D'
       and IsNull(cb.Bloqueio,'') <> 'SR'
       and IsNull(it.Qtd_Lote,0) > 0
     Group by it.Cod_Produt, it.Cod_Lote, it.Qtd_CxaFec, it.Qtd_EmbFec,
              it.Cod_Dep, it.Num_Rua, it.Num_Col, it.Num_Niv, Num_Apt
     Order by it.Cod_Produt, it.Cod_Lote
  Open PDVLT_Cr
  Fetch Next From PDVLT_Cr Into @CodPrd, @CodLot, @QtdCxaFec, @QtdEmbFec, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @QtdPra, @QtdDep
  While @@FETCH_STATUS = 0
    begin
      if Not Exists(Select 1 From PRLOT 
                     Where Cod_Estabe = @PCodEstabe 
                       And Cod_Produt = @CodPrd 
                       And Cod_Dep = @CodDep
                       And Cod_Lote = @CodLot) 
        begin
          Set @DatVct = (Select Top 1 it.Dat_Vencim
                           from NFECB cb 
                                Inner Join NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Protocolo = it.Protocolo)
                          Where cb.Cod_Estabe = @PCodEstabe
                            And it.Cod_Produto = @CodPrd
                            And it.Cod_Lote = @CodLot
                            And cb.Status = 'F'
                          Order by it.Dat_Movimento desc)
          Insert Into PRLOT (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Dat_Vencim, Qtd_FisPra, Qtd_FisDep)
                     Values (@PCodEstabe, @CodDep, @CodPrd, @CodLot, @DatVct, 0, 0)
        end
  
      if @QtdCxaFec = 0
        begin
          Update PRLOT
             Set Qtd_SolPra = Qtd_SolPra + @QtdPra,
                 Qtd_SolDep = Qtd_SolDep + @QtdDep
           Where Cod_Estabe = @PCodEstabe    
             And Cod_Dep = @CodDep
             And (Cod_Produt = @CodPrd) and (Cod_Lote = @CodLot)
        end
  
      if @QtdCxaFec > 0
        begin
          Set @DatVct = (Select Dat_Vencim From PRLOT Where Cod_Estabe = @PCodEstabe And Cod_Dep = @CodDep And Cod_Produt = @CodPrd And Cod_Lote = @CodLot)
          if Not Exists(Select 1 From PRLTL 
                         Where Cod_Estabe = @PCodEstabe And Cod_Produt = @CodPrd and Cod_Lote = @CodLot
                           And Cod_Dep = @CodDep
                           And Num_Rua = @NumRua
                           And Num_Col = @NumCol
                           And Num_Niv = @NumNiv
                           And Num_Apt = @NumApt)
                           --And Qtd_EmbFec = @QtdEmbFec)
            begin
              Insert Into PRLTL(Cod_Estabe, Cod_Produt, Cod_Lote, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt,
                                Qtd_EmbFec, Dat_Vencim, Qtd_FisPra, Qtd_FisDep)
                         Values(@PCodEstabe, @CodPrd, @CodLot, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt,
                                @QtdEmbFec, @DatVct, 0, 0)
            end
  
          Update PRLTL
             Set Qtd_SolPra = Qtd_SolPra + @QtdPra,
                 Qtd_SolDep = Qtd_SolDep + @QtdDep
           Where Cod_Estabe = @PCodEstabe    
             And Cod_Produt = @CodPrd and Cod_Lote = @CodLot
             And Cod_Dep = @CodDep
             And Num_Rua = @NumRua
             And Num_Col = @NumCol
             And Num_Niv = @NumNiv
             And Num_Apt = @NumApt
        end
  
      Fetch Next From PDVLT_Cr Into @CodPrd, @CodLot, @QtdCxaFec, @QtdEmbFec, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @QtdPra, @QtdDep
    end
  Close PDVLT_Cr
  Deallocate PDVLT_Cr

  -- Reprocessando Transito
  Update PRXES
     Set Qtd_Transi = 0
   Where Cod_Estabe = @PCodEstabe      

  Declare PRODU_Cr Cursor Local For 
    Select it.Cod_Produto
      From PDCCB cb Inner Join 
           PDCIT it on (it.Cod_Estabe = cb.Cod_Estabe and it.Numero = cb.Numero)
     Where cb.Cod_Estabe = @PCodEstabe 
       And cb.Status = 'P' 
     Group by it.Cod_Produto
     Having sum(it.Qtd_Pedido+it.Qtd_Bonificacao-it.Qtd_Falta-it.Qtd_Fatura) > 0
  Open PRODU_Cr
  Fetch Next From PRODU_Cr Into @CodPrd
  While @@FETCH_STATUS = 0
    begin
      Update PRXES
         Set Qtd_Transi = (Select sum(it.Qtd_Pedido+it.Qtd_Bonificacao-it.Qtd_Falta-it.Qtd_Fatura)
                             From PDCCB cb Inner Join 
                                  PDCIT it on (it.Cod_Estabe = cb.Cod_Estabe and it.Numero = cb.Numero)
                            Where cb.Cod_Estabe = @PCodEstabe 
                              And cb.Status = 'P' 
                              and it.Cod_Produto = @CodPrd
                           Having sum(it.Qtd_Pedido+it.Qtd_Bonificacao-it.Qtd_Falta-it.Qtd_Fatura) > 0)
       Where Cod_Estabe = @PCodEstabe 
         And Cod_Produt = @CodPrd
      Fetch Next From PRODU_Cr Into @CodPrd
    end
  Close PRODU_Cr
  Deallocate PRODU_Cr



/*
-----------------------------------------------------------

-- normaliza produto sem lote
if Exists(Select Cod_Produt From PRXES
           Where Cod_Estabe = @PCodEstabe 
             And Qtd_Dispon > 0
             and Cod_Produt not in (Select distinct Cod_Produt From PRLOT Where Cod_Estabe = @PCodEstabe))
  begin   
    Declare PRODU_Cr Cursor Local Fast_Forward For 
      Select Cod_Produt, Qtd_Dispon
        From PRXES
       Where Cod_Estabe = @PCodEstabe 
         And Qtd_Dispon > 0
         and Cod_Produt not in (Select distinct Cod_Produt From PRLOT Where Cod_Estabe = @PCodEstabe)
    Open PRODU_Cr
    Fetch Next From PRODU_Cr Into @CodPrd, @QtdDis

    While @@FETCH_STATUS = 0
      begin
        Set @NumPrt = 0
        Set @NumPrt = (Select Top 1 it.Protocolo
                         from NFECB cb Inner Join 
                              NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Protocolo = it.Protocolo)
                        Where cb.Cod_Estabe = @PCodEstabe
                          And it.Cod_Produto = @CodPrd
                          And cb.Status = 'F'
                        Order by it.Dat_Movimento desc)
        if @NumPrt is null Set @NumPrt = 0               
         
        Set @CodLot = '' 
        Set @DatVct = null
        if @NumPrt > 0 
          begin
            Select @CodLot = it.Cod_Lote,
                   @DatVct = it.Dat_Vencim            
              From NFECB cb Inner Join
                   NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Protocolo = it.Protocolo)
             Where it.Cod_Estabe = @PCodEstabe
               And it.Protocolo = @NumPrt
               And it.Cod_Produto = @CodPrd
          end 
         
        if Ltrim(Rtrim(@CodLot)) = ''
          Set @CodLot = '*'

        Set @CodDep = (Select top 1 Cod_Dep 
                         From NELTL
                        Where Cod_Estabe = @PCodEstabe
                          And Num_Protoc = @NumPrt
                          And Cod_Produt = @CodPrd
                          And Cod_Lote = @CodLot)
                       
        if IsNull(@CodDep,0) = 0
          Set @CodDep = 1

        Insert Into PRLOT(Cod_Estabe,Cod_Dep,Cod_Produt,Cod_Lote,Dat_Vencim,Qtd_FisPra,Qtd_FisDep)
                   Values(@PCodEstabe,@CodDep,@CodPrd,@CodLot,@DatVct,@QtdDis,0)

        Fetch Next From PRODU_Cr Into @CodPrd, @QtdDis
      end
    Close PRODU_Cr
    Deallocate PRODU_Cr
  end
*/

  
  -- corrige saldo negativo em PRLOT
  if Exists(Select top 1 1 
              From PRLOT 
             Where Cod_Estabe = @PCodEstabe
               And ( (Qtd_Saldo < 0) or (Qtd_Fisico < 0) or 
                     (Qtd_SldPra < 0) or (Qtd_FisPra < 0) or 
                     (Qtd_SldDep < 0) or (Qtd_FisDep < 0) ))
    begin
      Update PRLOT
         Set Qtd_FisPra = Qtd_FisPra + Abs(Qtd_SldPra)
       Where Cod_Estabe = @PCodEstabe
         And Qtd_SldPra < 0
  
      Update PRLOT
         Set Qtd_FisDep = Qtd_FisDep + Abs(Qtd_SldDep)
       Where Cod_Estabe = @PCodEstabe
         And Qtd_SldDep < 0
    end

  -- corrige saldo negativo em PRLTL
  if Exists(Select Cod_Produt, Cod_Lote, Qtd_Fisico, Qtd_Solicitado, Qtd_Saldo 
              From PRLTL 
             Where Cod_Estabe = @PCodEstabe
               And ( (Qtd_Saldo < 0) or (Qtd_Fisico < 0) or 
                     (Qtd_SldPra < 0) or (Qtd_FisPra < 0) or 
                     (Qtd_SldDep < 0) or (Qtd_FisDep < 0) ))
    begin
      Update PRLTL
         Set Qtd_FisPra = Qtd_FisPra + Abs(Qtd_SldPra)
       Where Cod_Estabe = @PCodEstabe
         And Qtd_SldPra < 0
  
      Update PRLTL
         Set Qtd_FisDep = Qtd_FisDep + Abs(Qtd_SldDep)
       Where Cod_Estabe = @PCodEstabe
         And Qtd_SldDep < 0
    end


/*
-- verifica qtd.disponivel de PRXES com LOTES
-- Lotes > PRXES  e PRLOT atende diferenca (1)
if Exists(Select p.Cod_Produt
            From PRXES p Left Join
                 (Select Cod_Estabe, Cod_Produt, sum(Qtd_Saldo) as QtdSldFra, sum(Qtd_Solicitado) as QtdSolFra
                    From PRLOT 
                   Where Cod_Estabe = @PCodEstabe
                     And ((Qtd_Saldo > 0) or (Qtd_Solicitado > 0))
                   Group by Cod_Estabe, Cod_Produt) l on (p.Cod_Estabe = l.Cod_Estabe and p.Cod_Produt = l.Cod_Produt) Left Join
                 (Select Cod_Estabe, Cod_Produt, sum(Qtd_Saldo) as QtdSldDep, sum(Qtd_Solicitado) as QtdSolDep
                    From PRLTL
                   Where Cod_Estabe = @PCodEstabe
                     And ((Qtd_Saldo > 0) or (Qtd_Solicitado > 0))
                   Group by Cod_Estabe, Cod_Produt) d on (p.Cod_Estabe = d.Cod_Estabe and p.Cod_Produt = d.Cod_Produt)
           Where p.Cod_Estabe = @PCodEstabe 
             And (p.Qtd_Dispon+p.Qtd_Solici+p.Qtd_Reserv+p.Qtd_Avaria-IsNull(QtdSolFra,0)-IsNull(QtdSolDep,0)) < IsNull(l.QtdSldFra,0)+IsNull(d.QtdSldDep,0)
             And IsNull(l.QtdSldFra,0) >= IsNull(l.QtdSldFra,0)+IsNull(d.QtdSldDep,0)-(p.Qtd_Dispon+p.Qtd_Solici+p.Qtd_Reserv+p.Qtd_Avaria-IsNull(QtdSolFra,0)-IsNull(QtdSolDep,0))
             And p.Qtd_Fisico >= 0
             And p.Qtd_Dispon >= 0)
  begin
--    PRINT '===> Ajustando DIVERGENCIAS DE ESTOQUES: PRODU x PRLOT (1)- PRLOT > PRODU'
    Declare PRODU_Cr Cursor Local For 
      Select p.Cod_Produt,
             IsNull(l.QtdSldFra,0)+IsNull(d.QtdSldDep,0)-(p.Qtd_Dispon+p.Qtd_Solici+p.Qtd_Reserv+p.Qtd_Avaria-IsNull(QtdSolFra,0)-IsNull(QtdSolDep,0)) as Qtd_Dif                                                        
        From PRXES p Left Join
             (Select Cod_Estabe, Cod_Produt, sum(Qtd_Saldo) as QtdSldFra, sum(Qtd_Solicitado) as QtdSolFra
                From PRLOT 
               Where Cod_Estabe = @PCodEstabe
                 And ((Qtd_Saldo > 0) or (Qtd_Solicitado > 0))
               Group by Cod_Estabe, Cod_Produt) l on (p.Cod_Estabe = l.Cod_Estabe and p.Cod_Produt = l.Cod_Produt) Left Join
             (Select Cod_Estabe, Cod_Produt, sum(Qtd_Saldo) as QtdSldDep, sum(Qtd_Solicitado) as QtdSolDep
                From PRLTL
               Where Cod_Estabe = @PCodEstabe
                 And ((Qtd_Saldo > 0) or (Qtd_Solicitado > 0))
               Group by Cod_Estabe, Cod_Produt) d on (p.Cod_Estabe = d.Cod_Estabe and p.Cod_Produt = d.Cod_Produt)
       Where p.Cod_Estabe = @PCodEstabe 
         And (p.Qtd_Dispon+p.Qtd_Solici+p.Qtd_Reserv+p.Qtd_Avaria-IsNull(QtdSolFra,0)-IsNull(QtdSolDep,0)) < IsNull(l.QtdSldFra,0)+IsNull(d.QtdSldDep,0)
         And IsNull(l.QtdSldFra,0) >= IsNull(l.QtdSldFra,0)+IsNull(d.QtdSldDep,0)-(p.Qtd_Dispon+p.Qtd_Solici+p.Qtd_Reserv+p.Qtd_Avaria-IsNull(QtdSolFra,0)-IsNull(QtdSolDep,0))
         And p.Qtd_Fisico >= 0
         And p.Qtd_Dispon >= 0
       Order by p.Cod_Produt
    Open PRODU_Cr
    Fetch Next From PRODU_Cr Into @CodPrd, @QtdDif
    While @@FETCH_STATUS = 0
      begin
        -- tenta decrementar do estoque 2
        Declare PRLOT_Cr Cursor Local For 
          Select Cod_Dep, Cod_Lote, Qtd_SldDep
            From PRLOT
           Where Cod_Estabe = @PCodEstabe
             And Cod_Produt = @CodPrd
             and Qtd_SldDep > 0
           Order by Cod_Dep, Dat_Vencim
        Open PRLOT_Cr
        Fetch Next From PRLOT_Cr Into @CodDep, @CodLot, @QtdSldDep  
        While (@QtdDif > 0) and (@@FETCH_STATUS = 0)
          begin
            if @QtdSldDep >= @QtdDif
              Set @QtdMov = @QtdDif
            else
              Set @QtdMov = @QtdSldDep
            Update PRLOT
               Set Qtd_FisDep = Qtd_FisDep - @QtdMov
             Where Cod_Estabe = @PCodEstabe 
               And Cod_Dep = @CodDep
               And Cod_Produt = @CodPrd 
               and Cod_Lote = @CodLot
            Set @QtdDif = @QtdDif - @QtdMov
            Fetch Next From PRLOT_Cr Into @CodDep, @CodLot, @QtdSldDep
          end
        Close PRLOT_Cr
        Deallocate PRLOT_Cr

        -- se ainda houver diferenca, tenta decrementar do estoque 1
        if @QtdDif > 0 
          begin
            Declare PRLOT_Cr Cursor Local For 
              Select Cod_Dep, Cod_Lote, Qtd_SldPra
                From PRLOT
               Where Cod_Estabe = @PCodEstabe
                 And Cod_Produt = @CodPrd
                 and Qtd_SldPra > 0
               Order by Cod_Dep, Dat_Vencim
            Open PRLOT_Cr
            Fetch Next From PRLOT_Cr Into @CodDep, @CodLot, @QtdSldPra
            While (@QtdDif > 0) and (@@FETCH_STATUS = 0)
              begin
                if @QtdSldPra >= @QtdDif
                  Set @QtdMov = @QtdDif
                else
                  Set @QtdMov = @QtdSldPra
                Update PRLOT
                   Set Qtd_FisPra = Qtd_FisPra - @QtdMov
                 Where Cod_Estabe = @PCodEstabe 
                   And Cod_Dep = @CodDep
                   And Cod_Produt = @CodPrd 
                   and Cod_Lote = @CodLot
                Set @QtdDif = @QtdDif - @QtdMov
                Fetch Next From PRLOT_Cr Into @CodDep, @CodLot, @QtdSldPra
              end
            Close PRLOT_Cr
            Deallocate PRLOT_Cr
          end

        Fetch Next From PRODU_Cr Into @CodPrd, @QtdDif
      end
    Close PRODU_Cr
    Deallocate PRODU_Cr
  end
*/


  Exec PR_CorrigeEstoqueProdut @PCodEstabe, 0

COMMIT TRANSACTION
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

