CREATE VIEW [dbo].[V_POCOM] 

AS

SELECT Id_PolCom,
       Cod_PolCom,
       Descricao = IsNull(replace(Des_Detalhada,CHAR(13) + Char(10),' '),''),
       Dat_Cadastro = Case 
                      When Year(Dat_Cadastro) > '1901' Then Convert(Varchar,Dat_Cadastro,103) 
                      Else '0' 
                    End,
       Dat_Inicio = Case 
                      When Year(Dat_Inicio) > '1901' Then Convert(Varchar,Dat_Inicio,103) 
                      Else '0' 
                    End,
       Dat_Termino = Case 
                       When Year(Dat_Termino) > '1901' Then Convert(Varchar,Dat_Termino,103) 
                       Else '0' 
                     End,
       Qtd_Minimo,
       Qtd_IteMin,
       Vlr_Minimo,
       Prz_MedioMax = Qtd_PrzMax,
       Tip_Prazo = IsNull(Cod_TipPrz,''),
       Cod_TabPrc = Case When IsNull(Flg_UsaTabPrcCadCli,0) = 0 then Cod_TabPrc Else 0 End,
       Flq_NegocDesc = Cast(IsNull(Flg_NegDsc,0) as bit),
       Flg_Markup = Case
                      When IsNull(Flg_NegDsc,0) = 1 Then Cast(IsNull(Flg_MarkupCusCom,0) as bit)
                      Else Cast(0 as bit)
                    End,
       Flq_ExclLinhaGrp = Cast(IsNull(Flg_ExcCla,0) as bit),
       Flq_ExclFabric = Cast(IsNull(Flg_ExcFab,0) as bit),
       Flg_Promocao = Cast(IsNull(Flg_BlqCli,0) as bit),
       Per_AcrescimoAutPrc = IsNull(Per_AcrAutPrc,0),
       Per_DescontoAutPrc = IsNull(Per_DscAutPrc,0),
       Taxa_ReajustePrcPrz = Case 
                               When IsNull(Flg_PrcVenPrpPrz,0) = 1 Then IsNull(Per_CorPrcVenPrpPrz,0)
                               Else 0
                             End,
       Flg_BloqueiaUsoDeOutPol = Cast(IsNull(Flg_BlqPolDifItePdv,0) as bit),
       Flg_BloqueiaUsoPorOutPol = Cast(IsNull(Flg_BlqPolDifCabPdv,0) as bit),
       Flg_PolCfv = Cast(IsNull(Flg_Cfv,0) as bit),
       Flg_PolWeb = Cast(IsNull(Flg_Web,0) as bit),
	   Flg_PolEdi = Cast(IsNull(Flg_PedEle,0) as bit),
       Desc_FinExtra = IsNull(Per_DscFin,0),

	   Per_DscFinVis = IsNull(Per_DscFinVis,0),
	   Per_DscCom = IsNull(Per_DscCom,0),
	   Per_DscComVis = IsNull(Per_DscComVis,0),
       Flg_SugDscGlbPdv = Cast(IsNull(Flg_SugDscGlbPdv,0) as bit),

	   Flg_GeraVerbaPedidoVenda = Case
                                    When IsNull(Flg_NegDsc,0) = 1 Then Cast(IsNull(Flg_GerVrbPdv,0) as bit)
                                    Else Cast(0 as bit)
                                  End,
	   Tipo_VerbaPedidoVenda = Tip_VrbPdv,

       Tip_ControleVerba = IsNull(Controle_Saldo,'V'),
       Flg_AcumulaVerbaPositiva = Case
                                    When IsNull(Flg_NegDsc,0) = 1 Then Cast(IsNull(Flg_AcuVrbPos,0) as bit)
                                    Else Cast(0 as bit)
                                  End,
       Flg_AcumulaVerbaNegativa = Case
                                    When IsNull(Flg_NegDsc,0) = 1 Then Cast(IsNull(Flg_AcuVrbNeg,0) as bit)
                                    Else Cast(0 as bit)
                                  End,
       Flg_SaldoVerbaVendedor = Cast(IsNull(Flg_CtrPdvVrbVdr,0) as bit),

       Dat_Cadastro2 = Dat_Cadastro,
	   Dat_Inicio2 = Dat_Inicio,
	   Dat_Termino2 = Dat_Termino,
       Per_RedComVdr,
	   Flg_UsaTabPrcCadCli 
FROM POCOM 
WHERE Bloqueado = 0 
AND (IsNull(Flg_Cfv,0) = 1 OR IsNull(Flg_Web,0) = 1 OR IsNull(Flg_PedEle,0) = 1)
And ((Dat_Inicio is Null) or (cast(GETDATE() as date) >= cast(Dat_Inicio as date))) 
And ((Dat_Termino is Null) or (cast(GETDATE() as date) <= cast(Dat_Termino as date))) 
AND IsNull(Tip_PolCom,'') <> 'KIT'

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CriaTituloCTREC]
@NumPar int,               -- numero da parcela
@DatVct smalldatetime,     -- vencimento
@VlrDup numeric(18,4),     -- valor do titulo
@VlrDscCon numeric(18,4),  -- valor do desconto concedido
@VlrDscBonDup numeric(18,4),  -- valor do desconto ref. bonificacao nao descontada na NF
@VlrDscFin numeric(18,4),  -- vlr do desc financeiro
@VlrSbtEmb numeric(18,4),  -- vlr da subst tribut. embutida no valor
@VlrResEmb numeric(18,4),  -- vlr do ressarc tribut. embutido no valor
@PerDscAtc numeric(18,4),  -- perc. dec. por antecipacao,
@QtdDiaExtVct int,         -- dias extras para vencimento
@FlgDupExt bit,            -- duplicata extra
@CodPed int,
@CodEstabe int,            -- estabelecimento    
@SerNfs varchar(3),        -- serie da NF
@NumNfs int,               -- numero da NF
@IsnCtaFinDeb int,
@IsnCtaFinCre int,
@DesUsu varchar(35),       -- usuario
@CodDoc int output

AS

SET NOCOUNT ON

Begin Transaction

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now = GetDate()
Set @Date = cast(convert(char(8),GetDate(),112) as smalldatetime)


-- variaveis a gravar em CTEC
Declare @PPar varchar(1),
        @PTipDoc varchar(2),
        @PNumDoc varchar(15),
        @PCgcMtz varchar(8),
        @PDatVct smalldatetime,
        @PDatBasJur smalldatetime, 
        @PPerJur numeric(18,4),
        @PPerMul numeric(18,4),
        @PPerDscFin numeric(18,4),
        @PTipCob varchar(2),
        @PCodSrv varchar(2),
        @PDatDscAtc smalldatetime, 
        @PPerDscAtc numeric(18,4), 
        @PVlrDscAtc numeric(18,4),
        @PVlrComTlm numeric(18,4),
        @PVlrCom numeric(18,4), 
        @PVlrComSup numeric(18,4), 
        @PVlrComGer numeric(18,4), 
        @PVlrComSupOpe numeric(18,4), 
        @PVlrComGerOpe numeric(18,4), 
        @PVlrDup numeric(18,4),
        @PCodCntCus int,
        @PIdTransacao int,
		@PVlrIrf numeric(18,4)

-- colocar na memoria campos de NFSCB
Declare @cb_CodPed int,
        @cb_DatEmi smalldatetime,
        @cb_TipVct varchar(1),
        @cb_CodCli int,
        @cb_CodAgc int,
        @cb_CodOpe int,
        @cb_CodVdr int,
        @cb_CodSup int,
        @cb_CodGer int,
        @cb_CodSupOpe int,
        @cb_CodGerOpe int,
        @cb_CodOriNfs varchar(2),
        @cb_PerDscFin numeric(18,8),
        @cb_VlrSubTri numeric(18,4),
        @cb_VlrSbtRes numeric(18,4),
        @cb_VlrDscTri numeric(18,4),
        @cb_VlrRecSbt numeric(18,4),
        @cb_CodEst varchar(2),
        @cb_TipRetImp varchar(1),
        @cb_VlrTotNot numeric(18,4),
        @cb_QtdPrzMed numeric(18,4),
        @cb_VlrCom numeric(18,4),
        @cb_VlrComTlm numeric(18,4),
        @cb_VlrComSup numeric(18,4),
        @cb_VlrComGer numeric(18,4),
        @cb_VlrComSupOpe numeric(18,4),
        @cb_VlrComGerOpe numeric(18,4),
		@cb_VlrIrf numeric(18,4)
		
        
Select @cb_CodPed = Cod_Pedido, 
       @cb_DatEmi = Dat_Emissao,
       @cb_TipVct = Tip_Vencimento,
       @cb_CodCli = Cod_Cliente,
       @cb_CodAgc = Cod_Agente,
       @cb_CodOpe = Cod_VendTlmkt,
       @cb_CodVdr = Cod_Vendedor,
       @cb_CodSup = Cod_Supervisor,
       @cb_CodGer = Cod_Gerencia,
       @cb_CodSupOpe = Cod_SupOpe,
       @cb_CodGerOpe = Cod_GerOpe,
       @cb_CodOriNfs = Cod_OrigemNfs,
       @cb_PerDscFin = IsNull(Per_DescontoFin,0),
       @cb_VlrSubTri = IsNull(Vlr_SubsTrib,0),
       @cb_VlrSbtRes = IsNull(Vlr_SbtRes,0),
       @cb_VlrDscTri = IsNull(Vlr_DscTri,0),
       @cb_VlrRecSbt = IsNull(Vlr_RecSbt,0),
       @cb_CodEst = Estado,
       @cb_TipRetImp = Tip_RetImp,
       @cb_VlrTotNot =  IsNull(Vlr_TotalNota,0),
       @cb_QtdPrzMed = Qtd_PrzMed,
       @cb_VlrCom = IsNull(Vlr_Comissao,0),
       @cb_VlrComTlm = IsNull(Vlr_ComTlmkt,0),
       @cb_VlrComSup = IsNull(Vlr_ComSup,0),
       @cb_VlrComGer = IsNull(Vlr_ComGer,0),
       @cb_VlrComSupOpe = IsNull(Vlr_ComSupOpe,0),
       @cb_VlrComGerOpe = IsNull(Vlr_ComGerOpe,0),
	   @cb_VlrIrf = IsNull(Vlr_Irf,0)
	   
  From NFSCB
Where Cod_Estabe = @CodEstabe
And Ser_Nota = @SerNfs and Num_Nota = @NumNfs

-- colocar na memoria campos de PDVCB
Declare @pv_TipFat varchar(3),
        @pv_FlgVlrFin bit,
        @pv_TipVct varchar(1),
        @pv_ObsIntCtaRec varchar(400),
        @pv_QtdParcela int,
		@op_CodCfoNorInt int		
        
Select @pv_TipFat = cb.Tip_Faturamento,
       @pv_FlgVlrFin = cb.Flg_VlrFinanc,
       @pv_TipVct = cb.Tip_Vencimento,
       @pv_ObsIntCtaRec = Substring(cb.Obs_IntCtaRec,1,400),
	   @pv_QtdParcela = cb.Qtd_Parcela,
       @op_CodCfoNorInt = op.Cod_CfoNorInt
  From PDVCB cb Left Outer Join
       TPOPE op on (cb.Tip_Faturamento = op.Cod_Ope)
Where cb.Cod_Estabe = @CodEstabe
And cb.Numero = @cb_CodPed

-- colocar na memoria os campo em AGCOB
Declare @ag_FlgDscFinDspBan bit,
        @ag_VlrDspBolBan numeric(18,4)

-- despesa de boleto somente para banco
Select @ag_FlgDscFinDspBan = IsNull(Flg_DscFinDspBan,0),
       @ag_VlrDspBolBan = case 
                            When (Isnull(Flg_CobDspBolBanNtf,0) = 0) and (Tipo = 'BC') and 
                                 ((Select IsNull(Flg_BlqCobTxaBan,0) From CLIEN Where Codigo = @cb_CodCli) = 0) then Round(Isnull(Vlr_DspBolBan,0),2)
                            else 0
                          end
  From AGCOB
Where Codigo = @cb_CodAgc

-- colocar na memoria campos de PARAM
Declare @pm_QtdDiaDupApr int,
        @pm_PerTaxJurDia numeric(18,4),
        @pm_PerMulAtrPag numeric(18,4),
        @pm_PerDscMaxPrzDif numeric(18,4),
        @pm_FlgDscFinIstOutEst bit,
        @pm_QtdPrzMinDscAtcCtr int,
        @pm_QtdPrzDscAtcCtr int,
        @pm_ValDspBolBan numeric(18,4)

Select @pm_QtdDiaDupApr = QtdDiaDupApr,
       @pm_PerTaxJurDia = PerTaxJurDia,
       @pm_PerMulAtrPag = PerMulAtrPag,
       @pm_PerDscMaxPrzDif = PerDscMaxPrzDif,
       @pm_FlgDscFinIstOutEst = FlgDscFinIstOutEst,
       @pm_QtdPrzMinDscAtcCtr = QtdPrzMinDscAtcCtr,
       @pm_QtdPrzDscAtcCtr = QtdPrzDscAtcCtr
  From PARAM
Where Cod_Estabe = @CodEstabe

-- variaveis de trabalho
Declare @WStrPar varchar(26),
        @WPer numeric(18,8),
        @WCVlrTotNot numeric(18,4)

Set @CodDoc = 0

-- valor total do titulo
Set @PVlrDup = @VlrDup + @ag_VlrDspBolBan

Set @WStrPar = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
Set @PPar = Substring(@WStrPar,@NumPar,1)

if (@op_CodCfoNorInt is null) or (@op_CodCfoNorInt = 0)
  Set @PTipDoc = 'OR'
else
  Set @PTipDoc = 'DP'

Set @PNumDoc = cast(@NumNfs as varchar(15))
While len(@PNumDoc) < 6
  Set @PNumDoc = '0' + @PNumDoc

-- calcula vencimento provisorio p/ apresentacao
if @cb_TipVct = 'A'
  begin
    Set @PDatVct = @cb_DatEmi + @pm_QtdDiaDupApr
    Set @PPerJur = 0
    Set @PPerMul = 0
  end
else
  begin
    Set @PDatVct = @DatVct
    Set @PPerJur = @pm_PerTaxJurDia
    Set @PPerMul = @pm_PerMulAtrPag
  end
Set @PDatBasJur = @PDatVct
Set @PTipCob = (Select Cod_TipCobDef From AGCOB Where Codigo = @cb_CodAgc)
Set @PCgcMtz = (Select Cgc_Matriz From CLIEN Where Codigo = @cb_CodCli)
Set @PCodSrv = (Select b.Cod_EntNor From BANCO b, AGCOB a Where b.Codigo = a.Cod_Banco And a.Codigo = @cb_CodAgc)
Set @PCodCntCus = IsNull((Select CodCntCusCtaRec From PMFIN),0)

if (@pv_FlgVlrFin = 1) and (@pv_TipVct <> 'P')   -- nao ponderado (nao considerar valor da despesa do boleto)
  Set @PPerDscFin = Round((@VlrDscFin*100/@VlrDup),4)
else
  begin
    -- se duplicata extra..  
    if @FlgDupExt = 0
      Set @PPerDscFin = @cb_PerDscFin
    else
      if @cb_PerDscFin > @pm_PerDscMaxPrzDif
        Set @PPerDscFin = @pm_PerDscMaxPrzDif
  end

if @PPerDscFin is null
  Set @PPerDscFin = 0

-- conceder vlr.subs.trib como desc.financ. p/ orcamentos p/ outro estado
-- campo calculado da nota
-- valor real da NF p/ atualizar acumuladores do sistema
if @cb_TipRetImp = 'R'   -- imposto a recolher nao incluido no Total da NF
  Set @WCVlrTotNot = @cb_VlrTotNot + @cb_VlrSubTri + @cb_VlrSbtRes - @cb_VlrDscTri + @cb_VlrRecSbt
else
  Set @WCVlrTotNot = @cb_VlrTotNot

if @pm_FlgDscFinIstOutEst = 1
  if (@PTipDoc = 'OR') and (@cb_CodEst <> (Select Des_Estado From ESTAB Where Cod_Estabe = @CodEstabe))
    if (@cb_VlrSubTri+@cb_VlrSbtRes) > 0
      begin
        Set @WPer = Round((@cb_VlrSubTri+@cb_VlrSbtRes) * 100 / @WCVlrTotNot,4)
        Set @PPerDscFin = @PPerDscFin + @WPer
      end

-- calcular desconto antecipado (nao consider despesa do boleto)
Set @PDatDscAtc = null
Set @PPerDscAtc = 0
Set @PVlrDscAtc = 0
if @PPerDscFin = 0
  if (@PerDscAtc  > 0) and
     (cast(@cb_QtdPrzMed as int) >= @pm_QtdPrzMinDscAtcCtr) and
     (cast(@PDatVct - @cb_DatEmi as int) >= @pm_QtdPrzDscAtcCtr)
    begin
      Set @PDatDscAtc = @cb_DatEmi + @pm_QtdPrzDscAtcCtr
      Set @PPerDscAtc = @PerDscAtc
      Set @PVlrDscAtc = Round(@VlrDup * @PerDscAtc/100,2)
    end

-- calcula comissao proporcionalmente ao titulo
Set @PVlrCom    = @VlrDup * @cb_VlrCom / @WCVlrTotNot
Set @PVlrComTlm = @VlrDup * @cb_VlrComTlm / @WCVlrTotNot
Set @PVlrComSup = @VlrDup * @cb_VlrComSup / @WCVlrTotNot
Set @PVlrComGer = @VlrDup * @cb_VlrComGer / @WCVlrTotNot
Set @PVlrComSupOpe = @VlrDup * @cb_VlrComSupOpe / @WCVlrTotNot
Set @PVlrComGerOpe = @VlrDup * @cb_VlrComGerOpe / @WCVlrTotNot

-- se preciso recalcula desconto devido a a despesa do boleto
if (@PPerDscFin > 0) and (Round(@VlrDup,2) <> Round(@PVlrDup,2))
  begin
    Set @PPerDscFin = Round(@VlrDup* @PPerDscFin/@PVlrDup,4)
  end

-- despesa de boleto como desconto financeiro 
Select @ag_FlgDscFinDspBan = IsNull(Flg_DscFinDspBan,0),
       @ag_VlrDspBolBan = case 
                            When (Tipo = 'BC') and 
                              ((Select IsNull(Flg_BlqCobTxaBan,0) From CLIEN Where Codigo = @cb_CodCli) = 0) then Round(Isnull(Vlr_DspBolBan,0),2)
                            else 0
                          end
From AGCOB
Where Codigo = @cb_CodAgc

if (@ag_FlgDscFinDspBan = 1) and (@ag_VlrDspBolBan > 0)
  begin
    Set @WPer = Round(@ag_VlrDspBolBan*100/@PVlrDup,4)
    Set @PPerDscFin = @PPerDscFin + @WPer
  end

EXEC PR_ProxNumero 'Contas_Receber', @CodDoc output
if @@error <> 0
  begin
    if @@trancount > 0
      Rollback Transaction
    Return
  end
  
EXEC PR_ProxNumeroEstab @CodEstabe, 'Id_Transacao', @PIdTransacao output
if @@error <> 0
  begin
    if @@trancount > 0
      Rollback Transaction
    Return
  end

-- Validacao login usuario infarma  
if (@DesUsu='' or @DesUsu='SISTEMA')
  set @DesUsu = SubsTring(dbo.FN_UsuarioInfarma(),1,35)
  
-- Valor do IRRF em cada título
if (@pv_QtdParcela is null) or (@pv_QtdParcela = 0)
  Set @pv_QtdParcela = 1  
Set @PVlrIrf = Round(@cb_VlrIrf/@pv_QtdParcela,4)
  
Insert into CTREC
  (Tip_Documento, Num_Documento, Par_Documento, Status, Sta_ChqVnc, Dat_Registro, Dat_Emissao, Dat_Vencimento, Dat_BaseJuros, Dat_VctOri, Per_Juros, Per_MulAtrPag,
   Per_DescFinanc, Tip_Vencimento, Tip_Cobranca, Cod_Cliente, Cgc_Matriz, Cod_Agente, 
   Cod_VendTlmkt, Cod_Vendedor, Cod_Supervisor, Cod_Gerencia, Cod_SupOpe, Cod_GerOpe, Cod_Estabe, Ser_NfOrigem, Num_NfOrigem, Cod_OrigemCtr, 
   Dat_DscAtc, Per_DscAtc, Vlr_DscAtc, Vlr_ParTit, Vlr_OutAcr, Vlr_DescConced, Vlr_DscBonDup, Vlr_DscSubFat, Vlr_Documento, Vlr_Saldo, 
   Vlr_DspEmb, Vlr_SbtEmb, Vlr_ResEmb,
   Vlr_ComTlmkt, Vlr_Comissao, Vlr_ComSup, Vlr_ComGer, Vlr_ComSupOpe, Vlr_ComGerOpe,
   Vlr_ComPagTlmkt, Vlr_ComPag, Vlr_ComPagSup, Vlr_ComPagGer, Vlr_ComPagSupOpe, Vlr_ComPagGerOpe, Qtd_DiaExtVct, Cod_ServRem,
   Flg_EmiDup, Flg_LanAuto, Usuario, Transacao, Cod_Pedido, Cod_Documento, Isn_CtaFin, Isn_CtaFinCre, Cod_CntCus, Id_Transacao, Obs_Int, Vlr_Irf)
Values
  (@PTipDoc, @PNumDoc, @PPar, 'A', '', @Date, @cb_DatEmi, @PDatVct, @PDatBasJur, @PDatVct, @PPerJur,  @PPerMul, 
   @PPerDscFin, @cb_TipVct, @PTipCob, @cb_CodCli, @PCgcMtz, @cb_CodAgc, 
   @cb_CodOpe, @cb_CodVdr, @cb_CodSup, @cb_CodGer, @cb_CodSupOpe, @cb_CodGerOpe, @CodEstabe, @SerNfs, @NumNfs, @cb_CodOriNfs, 
   @PDatDscAtc, @PPerDscAtc, @PVlrDscAtc, @PVlrDup, 0, @VlrDscCon, @VlrDscBonDup, 0, @PVlrDup, @PVlrDup, 
   @ag_VlrDspBolBan, @VlrSbtEmb, @VlrResEmb,
   @PVlrComTlm, @PVlrCom, @PVlrComSup, @PVlrComGer, @PVlrComSupOpe, @PVlrComGerOpe, 
   0, 0, 0, 0, 0, 0, @QTdDiaExtVct, @PCodSrv, 
   0, 1, @DesUsu, GetDate(), @CodPed, @CodDoc, @IsnCtaFinDeb, @IsnCtaFinCre, @PCodCntCus, @PIdTransacao, @pv_ObsIntCtaRec, @PVlrIrf)
if @@error <> 0
  begin
    if @@trancount > 0
      Rollback Transaction
    Return
  end

if @@trancount > 0
  Commit Transaction
GO


SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ConcedeDescontosTitulosFat]
@CodEstabe int,   
@SerNfs varchar(3),
@NumNfs int,
@DesUsu varchar(35)

WITH RECOMPILE
AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now = GetDate()
Set @Date = cast(GetDate() as Date)

-- validar login infaram
if (@DesUsu = '' or @DesUsu = 'SISTEMA')
  Set @DesUsu = Substring(dbo.FN_UsuarioInfarma(),1,35)

if not Exists(Select 1
                From BXREC bx
                     Inner Join CTREC cr on bx.Cod_Estabe = cr.Cod_Estabe and bx.Cod_Documento = cr.Cod_Documento
               Where cr.Cod_Estabe = @CodEstabe 
                 And cr.Ser_NfOrigem = @SerNfs
                 And cr.Num_NfOrigem = @NumNfs)
  begin
    Begin Transaction
    
    -- coloca campos de NFSCB na memoria
    Declare @nf_CodCli int,
            @op_VlrMinDup numeric(18,4),
            @pm_FlgDscAutPrxFatCli bit
    
    Select @nf_CodCli = Cod_Cliente,
           @op_VlrMinDup = Round(Isnull(op.Vlr_MinDup,0),2),
           @pm_FlgDscAutPrxFatCli = IsNull(pm.FlgDscAutPrxFatCli,0)
      From NFSCB cb
           Inner Join PARAM pm on cb.Cod_Estabe = pm.Cod_Estabe 
           Left  Join TPOPE op on cb.Cod_Ope = op.Cod_Ope
     Where cb.Cod_Estabe = @CodEstabe 
       and cb.Ser_Nota = @SerNfs 
       and cb.Num_Nota = @NumNfs
    
    if @op_VlrMinDup = 0
      Set @op_VlrMinDup = 1.00
    
   
    -- variaveis de trabalho
    Declare @WAccVlrTotDscPer numeric(18,4),
            @WVlrDscCon numeric(18,4),
            @WVlrDscBonDup numeric(18,4),
            @WVlrMaxDscTit numeric(18,4),
            @WVlrDup numeric(18,4),
            @WCodDoc int,
            @WCodLan int,
            @WVlrLan numeric(18,4),
            @WCodVal int,
            @WDatEmi smalldatetime,
            @WSldVal numeric(18,4),
			@WVlrIrf numeric(18,4)
    

    -- estorna descontos concedidos anteriormente
    Exec PR_CancelaDescontosConcedidosCTREC @CodEstabe, @SerNfs, @NumNfs
    if @@error <> 0
     begin
       if @@trancount > 0
         Rollback Transaction
       Return
     end


    -- vales de credito do cliente
    -- cria tabela dos lotes do produto que serao utilizados
    Create Table #VALES_AUX
      (Cod_Vale int,
       Dat_Emissa smalldatetime,
       Val_Saldo numeric(18,4))
    
    Set @WAccVlrTotDscPer = 0
    if (@pm_FlgDscAutPrxFatCli = 1) and (Exists (Select top 1 1 
                                                   From Vales 
                                                  Where Cod_Estabe = @CodEstabe 
                                                    And Tip_Entid = 'CLI' And Cod_Entid = @nf_CodCli 
                                                    And Deb_Cre = 'C' And Dat_Pagame is null))
      begin
        -- calcula valor maximo que podera ser concedido como desconto
        Set @WVlrMaxDscTit = Isnull((Select sum(IsNull(Vlr_Documento,0)-IsNull(Vlr_DscBonDup,0)-@op_VlrMinDup)
                                       From CTREC
                                      Where Cod_Estabe = @CodEstabe 
                                        And Ser_NfOrigem = @SerNfs
                                        And Num_NfOrigem = @NumNfs),0)
                                     
        -- seleciona vales de crédito do cliente
        Declare Vales_Cr Cursor Local Fast_Forward For 
    
          Select Cod_Vale, Dat_Emissa, Val_Saldo 
            From Vales 
           Where Cod_Estabe = @CodEstabe 
             And Tip_Entid = 'CLI' And Cod_Entid = @nf_CodCli 
             And Deb_Cre = 'C' And Dat_Pagame is null
           Order by Dat_Emissa, Cod_Vale
    
        Open Vales_Cr
        Fetch Next From Vales_Cr into @WCodVal, @WDatEmi, @WSldVal
        While @@FETCH_STATUS = 0
          begin
            if (@WAccVlrTotDscPer + @WSldVal) <= @WVlrMaxDscTit
              begin
                -- quita o vale
                Set @WAccVlrTotDscPer = @WAccVlrTotDscPer + @WSldVal
                
                Update VALES
                   Set Dat_Pagame = @Date,
                       Val_Saldo = 0
                 Where Cod_Estabe = @CodEstabe
                   And Cod_Vale = @WCodVal
                  
                Insert Into #VALES_AUX (Cod_Vale, Dat_Emissa, Val_Saldo)
                                Values (@WCodVal, @WDatEmi, @WSldVal)
              end    
    
            Fetch Next From Vales_Cr into @WCodVal, @WDatEmi, @WSldVal
          end
        Close Vales_Cr
        Deallocate Vales_Cr
      end
    
    -- concede desconto
    Declare Ctrec_Cr Cursor Local Fast_Forward For 
    
      Select Cod_Documento, Vlr_Documento, IsNull(Vlr_DscBonDup,0), IsNull(Vlr_Irf,0)
        From CTREC 
       Where Cod_Estabe = @CodEstabe 
         And Ser_NfOrigem = @SerNfs
         And Num_NfOrigem = @NumNfs
       Order by Dat_Vencimento, Cod_Documento
    
    Open Ctrec_Cr
    Fetch Next From Ctrec_Cr into @WCodDoc, @WVlrDup, @WVlrDscBonDup, @WVlrIrf
    While @@FETCH_STATUS = 0
      begin
        Set @WVlrDscCon = 0
        if @WAccVlrTotDscPer > 0
          begin
            if @WAccVlrTotDscPer > (@WVlrDup-@WVlrDscBonDup-@op_VlrMinDup)
              Set @WVlrDscCon = @WVlrDup-@WVlrDscBonDup-@op_VlrMinDup
            else
              Set @WVlrDscCon = @WAccVlrTotDscPer
            Set @WAccVlrTotDscPer = @WAccVlrTotDscPer - @WVlrDscCon
          end
    
         Update CTREC
            Set Vlr_DescConced = @WVlrDscCon+@WVlrIrf
          Where Cod_Estabe = @CodEstabe
            And Cod_Documento = @WCodDoc
    
        Set @WVlrDscCon = @WVlrDscCon + @WVlrDscBonDup + @WVlrIrf						    
    
        if @WVlrDscCon > 0
          begin
            -- insere registros BXVAL
            Declare VALESAUX_Cr Cursor Local Fast_Forward For 
    
              Select Cod_Vale, Dat_Emissa, Val_Saldo
                From #VALES_AUX
               Where Val_Saldo > 0
               Order by Dat_Emissa, Cod_Vale 
    
            Open VALESAUX_Cr
            Fetch Next From VALESAUX_Cr Into @WCodVal, @WDatEmi, @WSldVal
            While (@@FETCH_STATUS = 0) and (@WVlrDscCon > 0)
              begin
                if @WVlrDscCon > @WSldVal       
                  Set @WVlrLan = @WSldVal
                else  
                  Set @WVlrLan = @WVlrDscCon
                  
                Update #VALES_AUX
                   Set Val_Saldo = Val_Saldo - @WVlrLan
                 Where Cod_Vale = @WCodVal
                
                Delete From #VALES_AUX
                 Where Val_Saldo = 0 
                  
                EXEC PR_ProxNumero 'Lancamento', @WCodLan output
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end
                
                Insert Into BXVAL (Cod_Estabe, Cod_Vale, Cod_Lancam, Dat_Lancam, Val_Lancam, Tip_Lancam, Cod_Docume, Usuario, Transacao)
                           Values (@CodEstabe, @WCodVal, @WCodLan, @Date, @WVlrLan, 'DCF', @WCodDoc, @DesUsu, @Now)      
                  
                Set @WVlrDscCon = @WVlrDscCon - @WVlrLan    
            
                Fetch Next From VALESAUX_Cr Into @WCodVal, @WDatEmi, @WSldVal
              end
            
            Close VALESAUX_Cr 
            Deallocate VALESAUX_Cr
    
          end                        
          
        Fetch Next From Ctrec_Cr into @WCodDoc, @WVlrDup, @WVlrDscBonDup, @WVlrIrf
      end
    Close Ctrec_Cr
    Deallocate Ctrec_Cr
    
    Drop Table #VALES_AUX
    
    if @@trancount > 0
      Commit Transaction
  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE TRIGGER [dbo].[TR_NELTL_AtualizaCampos] ON [dbo].[NELTL] 
FOR INSERT, UPDATE
AS

-- comando p/ corrigir erro delphi/ado: record was changed by another user
SET NOCOUNT ON 

if Update(Qtd_EmbFec) or Update(Qtd_Est)
  begin
    Update N
       Set N.Qtd_CxaFec = Case 
                            When (IsNull(pm.FlgAltUnvItePdv,0) = 0 and IsNull(I.Qtd_EmbFec,0) > 0) then I.Qtd_Est/I.Qtd_EmbFec
                            When (IsNull(pm.FlgAltUnvItePdv,0) = 1 and IsNull(I.Qtd_EmbFec,0) > 0) then I.Qtd_Est/(I.Qtd_EmbFec*IsNull(ap.Fat_CnvApr,1))
                            Else 0
                          End
      From Inserted I 
           inner Join dbo.NELTL N on N.Cod_Estabe = I.Cod_Estabe and N.Num_Protoc = I.Num_Protoc and N.Cod_Produt = I.Cod_Produt and N.Cod_Lote = I.Cod_Lote and 
                                     N.Cod_Dep = I.Cod_Dep and N.Num_Rua = I.Num_Rua and  N.Num_Col = I.Num_Col and N.Num_Niv = I.Num_Niv and N.Num_Apt = I.Num_Apt
           inner join dbo.PARAM pm on I.Cod_Estabe = pm.Cod_Estabe
           left  join dbo.PRXAP ap on I.Cod_Produt = ap.Cod_Produt and ap.Flg_Padrao = 1
  end

if (Update(Num_Rua) or Update(Num_Col) or Update(Num_Niv) or Update(Num_Apt)) and Not Exists(Select * From DELETED)
  begin
    Update N
       Set N.Num_RuaSug = I.Num_Rua,
           N.Num_ColSug = I.Num_Col,
           N.Num_NivSug = I.Num_Niv,
           N.Num_AptSug = I.Num_Apt
      From Inserted I 
           inner Join NELTL N on N.Cod_Estabe = I.Cod_Estabe and N.Num_Protoc = I.Num_Protoc and N.Cod_Produt = I.Cod_Produt and N.Cod_Lote = I.Cod_Lote and 
                                 N.Cod_Dep = I.Cod_Dep and N.Num_Rua = I.Num_Rua and  N.Num_Col = I.Num_Col and N.Num_Niv = I.Num_Niv and N.Num_Apt = I.Num_Apt
  end

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CalculaComisNFS]
@PCodEstabe int,        -- cod. estabelecimento
@PSerNot varchar(3),    -- serie da nota fiscal
@PNumNot int            -- num.da nota fiscal

AS

SET NOCOUNT ON 

-- notas de venda, fechada, e fechamento de comissao em aberto
if ((Select Tip_Saida From NFSCB Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot) = 'V') and
   ((Select Status From NFSCB Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot) = 'F') and
   ((Select ISNULL(Dat_FecCom,0) From NFSCB Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot) = 0)
  begin
    Begin Transaction

    -- variaveis de trabalho
    Declare @WCodTabComOpe int,
            @WCodTabComVdr int,
            @WCodPrm int, 
            @WCVlrTotNot numeric(18,4),
            @WVlrComVnd numeric(18,4),
            @WVlrComOpe numeric(18,4),
            @WVlrComSup numeric(18,4),
            @WVlrComGer numeric(18,4),
            @WVlrComSupOpe numeric(18,4),
            @WVlrComGerOpe numeric(18,4),
            @WVlrBasFre numeric(18,4),
            @WVlrLiqNot numeric(18,4),
            @WFlgNotRecSbt bit,
            @WPerRetBon numeric(18,4),
            @WTipSai varchar(1)

    -- campos para cabecalho da nota
    Declare @cb_CodCli int,
            @cb_CodPed int,
            @cb_DatEmi smalldatetime,
            @cb_PerDscCom numeric(18,4),
            @cb_PerDscFin numeric(18,4),
            @cb_QtdPrzMed numeric(18,4),
            @cb_PerComOpe numeric(18,4),
            @cb_PerComVnd numeric(18,4),
            @cb_PerComSup numeric(18,4),
            @cb_PerComGer numeric(18,4),
            @cb_PerComSupOpe numeric(18,4),
            @cb_PerComGerOpe numeric(18,4),
            @cb_CodOpe int,
            @cb_CodVdr int,
            @cb_CodSup int,
            @cb_CodGer int,
            @cb_CodSupOpe int,
            @cb_CodGerOpe int,
            @cb_TipVct varchar(1),
            @cb_TipRetImp varchar(1),
            @cb_VlrDscTri numeric(18,4),
            @cb_VlrSubTri numeric(18,4),
            @cb_VlrRecSbt numeric(18,4),
            @cb_VlrTotNot numeric(18,4),
            @cb_CodTra int,
            @cb_CodUF varchar(2),
            @sf_SerNot varchar(3),
            @sf_NumNot int,
            @cr_VlrDoc numeric(18,4)
                 
    -- campos para transportadora
    Declare @tr_Pessoa varchar(1),
            @tr_PerFrete numeric(18,4),
            @tr_VlrMin numeric(18,4),
            @tr_FlgCalFreVerMer bit

    -- campos para atualizar em NFSCB
    Declare @PFlgComNor bit,
            @PVlrComVnd numeric(18,4),
            @PVlrComOpe numeric(18,4),
            @PVlrComSup numeric(18,4),
            @PVlrComGer numeric(18,4),
            @PVlrComSupOpe numeric(18,4),
            @PVlrComGerOpe numeric(18,4),
            @PVlrComTra numeric(18,4)

    -- Campos para itens da nota
    Declare @it_CodPrd int,
            @it_CodLot varchar(20),
            @it_NumSeqIte int, 
            @it_TipSai varchar(1),
            @it_CodCfo int,
            @it_PerDsc numeric(18,4),
            @it_PerDesconto numeric (18,8),
            @it_CodPrm int, 
            @it_FlgPolPrm int, 
            @it_FlgDscIte bit,
            @it_FlgBlqInfPar bit,
            @it_PrcUni numeric (18,8),
            @it_PrcTab numeric (18,4),
            @it_VlrBasCom numeric(18,4),
            @it_IdPolCom int,
            @it_PerVrbPar numeric (18,4),
            @it_PerVrbBon numeric (18,4),
            @it_PerLucBru numeric (18,4)

    -- variaveis a atualizar em NFSIT
    Declare @P_FlgComNor bit,
            @P_PerComVnd numeric(18,4),
            @P_VlrComVnd numeric(18,4),
            @P_PerComOpe numeric(18,4),
            @P_VlrComOpe numeric(18,4),
            @P_PerComSup numeric(18,4),
            @P_VlrComSup numeric(18,4),
            @P_PerComGer numeric(18,4),
            @P_VlrComGer numeric(18,4),
            @P_PerComSupOpe numeric(18,4),
            @P_VlrComSupOpe numeric(18,4),
            @P_PerComGerOpe numeric(18,4),
            @P_VlrComGerOpe numeric(18,4),
            @P_PerComTra numeric(18,4),
            @P_VlrComTra numeric(18,4)

    -- normaliza campos NFSCB
    Update cb 
       Set cb.Cod_Supervisor = ve.Cod_Supervisor 
      From NFSCB cb Inner Join VENDE ve on cb.Cod_Vendedor = ve.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Ser_Nota = @PSerNot and cb.Num_Nota = @PNumNot       
       And ISNULL(cb.Cod_Supervisor,0) = 0
      
    Update cb 
       Set cb.Cod_Gerencia = su.Cod_Gerencia
      From NFSCB cb Inner Join VENDE ve on cb.Cod_Vendedor = ve.Codigo
                    Inner Join SUPER su on ve.Cod_Supervisor = su.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Ser_Nota = @PSerNot and cb.Num_Nota = @PNumNot       
       And ISNULL(cb.Cod_Gerencia,0) = 0

    Update cb 
       Set cb.Cod_SupOpe = ve.Cod_Supervisor 
      From NFSCB cb Inner Join VENDE ve on cb.Cod_VendTlmkt = ve.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Ser_Nota = @PSerNot and cb.Num_Nota = @PNumNot       
       And ISNULL(cb.Cod_SupOpe,0) = 0
      
    Update cb 
       Set cb.Cod_GerOpe = su.Cod_Gerencia
      From NFSCB cb Inner Join VENDE ve on cb.Cod_VendTlmkt = ve.Codigo
                    Inner Join SUPER su on ve.Cod_Supervisor = su.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Ser_Nota = @PSerNot and cb.Num_Nota = @PNumNot       
       And ISNULL(cb.Cod_GerOpe,0) = 0

    -- coloca campos de NFSCB na memoria
    Select @cb_CodCli = Cod_Cliente, 
           @cb_CodVdr = Cod_Vendedor, 
           @cb_CodOpe = Cod_VendTlmkt, 
           @cb_CodSup = Cod_Supervisor, 
           @cb_CodGer = Cod_Gerencia, 
           @cb_CodSupOpe = Cod_SupOpe, 
           @cb_CodGerOpe = Cod_GerOpe, 
           @cb_CodPed = Cod_Pedido,
           @cb_DatEmi = Dat_Emissao,
           @cb_PerDscCom = IsNull(Per_DescontoCom,0), 
           @cb_PerDscFin = IsNull(Per_DescontoFin,0), 
           @cb_TipVct = Tip_Vencimento, 
           @cb_QtdPrzMed = Qtd_PrzMed, 
           @cb_PerComOpe = IsNull(Per_ComOpe,0),
           @cb_PerComVnd = IsNull(Per_ComVnd,0),
           @cb_PerComSup = IsNull(Per_ComSup,0),
           @cb_PerComGer = IsNull(Per_ComGer,0),
           @cb_PerComSupOpe = IsNull(Per_ComSupOpe,0),
           @cb_PerComGerOpe = IsNull(Per_ComGerOpe,0),
           @cb_TipRetImp = Tip_RetImp, 
           @cb_CodTra = Cod_Transportadora,
		   @cb_CodUF = IsNull(Estado,''),
           @sf_SerNot = IsNull(Ser_NotSubFat,''),
           @sf_NumNot = Isnull(Num_NotSubFat,0)
      From NFSCB
     Where Cod_Estabe = @PCodEstabe 
       and Ser_Nota = @PSerNot and Num_Nota = @PNumNot       

    -- coloca campos de NFSCB/NSOCB na memoria especificos p/ calculo da comissao
    Set @WFlgNotRecSbt = 0   -- indica se a nf for recalculada por inclusao do sbt no preco
    if Exists(Select 1 From  NSOCB Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot)
      begin
        Set @WFlgNotRecSbt = 1
        Select @cb_VlrDscTri = IsNull(Vlr_DscTri,0), 
               @cb_VlrSubTri = IsNull(Vlr_SubsTrib,0)+IsNull(Vlr_SbtRes,0), 
               @cb_VlrRecSbt = IsNull(Vlr_RecSbt,0),
               @cb_VlrTotNot = IsNull(Vlr_TotalNota,0),
               @WVlrLiqNot   = IsNull(Vlr_LiqItens,0) - IsNull(Vlr_DescontoCom,0) - IsNull(Vlr_DscBon,0) - IsNull(Vlr_RepIcms,0) - IsNull(Vlr_DscTri,0)
          From NSOCB
         Where Cod_Estabe = @PCodEstabe 
           and Ser_Nota = @PSerNot and Num_Nota = @PNumNot       
      end
    else
      begin
        Set @WFlgNotRecSbt = 0
        Select @cb_VlrDscTri = IsNull(Vlr_DscTri,0), 
               @cb_VlrSubTri = IsNull(Vlr_SubsTrib,0)+IsNull(Vlr_SbtRes,0), 
               @cb_VlrRecSbt = IsNull(Vlr_RecSbt,0),
               @cb_VlrTotNot = IsNull(Vlr_TotalNota,0),
               @WVlrLiqNot   = dbo.FN_ValLiqNFS(Cod_Estabe,Ser_Nota,Num_Nota)
          From NFSCB
         Where Cod_Estabe = @PCodEstabe 
           and Ser_Nota = @PSerNot and Num_Nota = @PNumNot       
      end

    -- coloca campos da transportadora na memoria
    Select @tr_Pessoa = tr.Pessoa,
           @tr_PerFrete = Case 
                            When tx.Cod_Transp is null then IsNull(tr.Per_Frete,0) 
                            Else IsNull(tx.Per_Frete,0) 
                          End,
           @tr_VlrMin = Case 
                            When tx.Cod_Transp is null then IsNull(tr.Vlr_Minimo,0) 
                            Else IsNull(tx.Vlr_Minimo,0) 
                          End,
           @tr_FlgCalFreVerMer = Case 
                                   When tx.Cod_Transp is null then IsNull(tr.Flg_CalFreVlrMer,0) 
                                   Else IsNull(tx.Flg_CalFreVlrMer,0) 
                                 End
      From TRANS tr
           Left Join TRXUF tx on tr.Codigo = tx.Cod_Transp and tx.Cod_UF COLLATE DATABASE_DEFAULT = @cb_CodUF COLLATE DATABASE_DEFAULT 
     Where tr.Codigo = @cb_CodTra

    -- inicializa acumuladores  p/  cabecalho
    Set @PVlrComVnd = 0
    Set @PVlrComOpe = 0
    Set @PVlrComSup = 0
    Set @PVlrComGer = 0
    Set @PVlrComSupOpe = 0
    Set @PVlrComGerOpe = 0
    Set @PVlrComTra = 0   -- ???? recalcula para nf com sbt incluida no preco ????
    Set @PFlgComNor = 1

    -- pega tabela de comissao do vendedor e operador
    Set @WCodTabComOpe = (Select Cod_TabCom From VEXES Where Cod_Estabe = @PCodEstabe And Cod_Vended = @cb_CodOpe)
    Set @WCodTabComVdr = (Select Cod_TabCom From VEXES Where Cod_Estabe = @PCodEstabe And Cod_Vended = @cb_CodVdr)

    -- comissao de supervisor/gerencia do vendedor    
    Set @cb_PerComSup = (Select IsNull(Per_ComNor,0) From SUPER Where Codigo = @cb_CodSup)
    Set @cb_PerComGer = (Select IsNull(Per_ComNor,0) From GEREN Where Codigo = @cb_CodGer)

    -- comissao de supervisor/gerencia do operador
    Set @cb_PerComSupOpe = (Select IsNull(Per_ComNor,0) From SUPER Where Codigo = @cb_CodSupOpe)
    Set @cb_PerComGerOpe = (Select IsNull(Per_ComNor,0) From GEREN Where Codigo = @cb_CodGerOpe)

    -- calcula comissao dos itens
    Declare NFSIT_Cr Cursor Local Fast_Forward For 
      Select Cod_Produto, Cod_Lote, Num_SeqIte, ISNULL(Tip_Sai,''), ISNULL(Cod_Cfo,0),
			 IsNull(Vlr_TotItem,0)-IsNull(Vlr_RepIcms,0)-IsNull(Vlr_DescRateado,0)-IsNull(Vlr_DscTri,0), IsNull(Prc_Unitario,0), 
             IsNull(Prc_Tabela,0), IsNull(Flg_DscItePdv,0), IsNull(Flg_BlqInfPar,0), IsNull(Cod_Promocao,0), IsNull(Flg_PolPrm,0),
             IsNull(Per_Descon,0), IsNull(Per_Desconto,0), IsNull(Id_PolCom,0), IsNull(Per_VrbPar,0), IsNull(Per_VrbBon,0),
             IsNull(Per_LucBru,0)
        From NFSIT Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
    Open NFSIT_Cr
    Fetch Next From NFSIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte, @it_TipSai, @it_CodCfo, @it_VlrBasCom, @it_PrcUni, 
                                  @it_PrcTab, @it_FlgDscIte, @it_FlgBlqInfPar, @it_CodPrm, @it_FlgPolPrm,
                                  @it_PerDsc, @it_PerDesconto, @it_IdPolCom, @it_PerVrbPar, @it_PerVrbBon,
                                  @it_PerLucBru

    While @@FETCH_STATUS = 0
      begin
        -- verifica se a nf foi recalculada (sbt incluida no preco)
        if @WFlgNotRecSbt = 1
          begin
            Select @it_VlrBasCom = IsNull(Vlr_LiqItem,0)-IsNull(Vlr_SubsTrib,0)-IsNull(Vlr_RecSbt,0),   -- -Vlr_SbtRes  -Vlr_Ipi -Vlr_DespRateada +VlrBonRat
                   @it_PrcUni = IsNull(Prc_Unitario,0), 
                   @it_PerDesconto = IsNull(Per_Desconto,0)              
              From NSOIT
             Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot       
               And Cod_Produto = @it_CodPrd and Cod_Lote = @it_CodLot and Num_SeqIte = @it_NumSeqIte
          end

        Set @WPerRetBon = @it_PerVrbPar + @it_PerVrbBon 
        if (@it_TipSai = 'B') or (@it_CodCfo = 5910) or (@it_CodCfo = 6910)  
          Set @WTipSai = 'B'
        else  
          Set @WTipSai = ''

-- Set Vlr_LiqItem = Vlr_TotItem - Vlr_RepIcms - Vlr_DescRateado  - Vlr_DscTri 
--                   - Vlr_DscBonRat + Vlr_SubsTrib + Vlr_SbtRes + Vlr_RecSbt + Vlr_Ipi + Vlr_DespRateada
        
        Set @WCodPrm = IsNull(@it_CodPrm,0) + IsNull(@it_FlgPolPrm,0)
        EXEC PR_CalcComisItemSaida @PCodEstabe, @cb_CodPed, @it_CodPrd, @WTipSai, @cb_CodCli, @cb_DatEmi, @it_VlrBasCom,
                                   @it_PrcUni, @it_PrcTab, @it_FlgDscIte, @it_FlgBlqInfPar, @WCodPrm, @it_PerDsc, @it_PerDesconto, 
                                   @cb_PerDscCom, @cb_PerDscFin, @cb_TipVct, @cb_QtdPrzMed, @cb_PerComVnd, @WCodTabComVdr, @cb_PerComOpe, @WCodTabComOpe, 
                                   @cb_PerComSup, @cb_PerComGer, @cb_PerComSupOpe, @cb_PerComGerOpe, @it_IdPolCom, @WPerRetBon, @it_PerLucBru, @P_FlgComNor output, 
                                   @P_PerComOpe output, @P_PerComVnd output, @P_PerComSup output, @P_PerComGer output, @P_PerComSupOpe output, @P_PerComGerOpe output, 
                                   @P_VlrComOpe output, @P_VlrComVnd output, @P_VlrComSup output, @P_VlrComGer output, @P_VlrComSupOpe output, @P_VlrComGerOpe output

        -- calcula comissao de entrega  -- ???? recalcula para nf com sbt incluida no preco ????
        Set @P_PerComTra = 0
        Set @P_VlrComTra = 0
        if @tr_Pessoa = 'F'
          begin
            Select @P_PerComTra = Isnull(Per_ComEnt,0) From PRXES Where Cod_Estabe = @PCodEstabe and Cod_Produt = @it_CodPrd
            Set @P_VlrComTra = @it_VlrBasCom * @P_PerComTra/100
          end

        -- atualiza item da nota
        Update NFSIT
           Set Flg_ComisNormal = @P_FlgComNor,
               Per_Comissao = @P_PerComVnd,
               Per_ComTlmkt = @P_PerComOpe,
               Per_ComSup = @P_PerComSup,
               Per_ComGer = @P_PerComGer,
               Per_ComSupOpe = @P_PerComSupOpe,
               Per_ComGerOpe = @P_PerComGerOpe,
               Vlr_Comissao = @P_VlrComVnd,
               Vlr_ComTlmkt = @P_VlrComOpe,
               Vlr_ComSup = @P_VlrComSup,
               Vlr_ComGer = @P_VlrComGer,
               Vlr_ComSupOpe = @P_VlrComSupOpe,
               Vlr_ComGerOpe = @P_VlrComGerOpe,
               Per_ComTra = @P_PerComTra,
               Val_ComTra = @P_VlrComTra
         Where Cod_Estabe = @PCodEstabe 
           and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
           and Cod_Produto = @it_CodPrd and Cod_Lote = @it_CodLot and Num_SeqIte = @it_NumSeqIte

        -- atualiza tip_sai do item
        Update NFSIT
           Set Tip_Sai = @WTipSai
         Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
           and Cod_Produto = @it_CodPrd and Cod_Lote = @it_CodLot and Num_SeqIte = @it_NumSeqIte
           And IsNull(Tip_Sai,'') <> @WTipSai   

        -- acumula valores p/  cabecalho
        Set @PVlrComVnd = @PVlrComVnd + @P_VlrComVnd
        Set @PVlrComOpe = @PVlrComOpe + @P_VlrComOpe
        Set @PVlrComSup = @PVlrComSup + @P_VlrComSup
        Set @PVlrComGer = @PVlrComGer + @P_VlrComGer
        Set @PVlrComSupOpe = @PVlrComSupOpe + @P_VlrComSupOpe
        Set @PVlrComGerOpe = @PVlrComGerOpe + @P_VlrComGerOpe
        Set @PVlrComTra = @PVlrComTra + @P_VlrComTra
        if @P_FlgComNor = 0
          Set @PFlgComNor = 0

        Fetch Next From NFSIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte, @it_TipSai, @it_CodCfo, @it_VlrBasCom, @it_PrcUni, 
                                      @it_PrcTab, @it_FlgDscIte, @it_FlgBlqInfPar, @it_CodPrm, @it_FlgPolPrm,
                                      @it_PerDsc, @it_PerDesconto, @it_IdPolCom, @it_PerVrbPar, @it_PerVrbBon,
                                      @it_PerLucBru									   
      end
    Close NFSIT_Cr 
    Deallocate NFSIT_Cr

    -- calcula frete p/ pessoa juridica (somente se nao foi recalculada por sbt no preco)
    if @tr_Pessoa <> 'F'
      begin
        if @tr_FlgCalFreVerMer = 1
          Set @WVlrBasFre = @WVlrLiqNot
        else
          Set @WVlrBasFre = @cb_VlrTotNot

        Set @PVlrComTra = Round(@WVlrBasFre*@tr_PerFrete/100,2)
        if Round(@PVlrComTra*100,2) < Round(@tr_VlrMin*100,2)
          Set @PVlrComTra = @tr_VlrMin
      end

    -- Atualiza acumuladores em NFSCB
    Update NFSCB
       Set Vlr_Comissao = Round(@PVlrComVnd,2),
           Vlr_ComTlmkt = Round(@PVlrComOpe,2),
           Vlr_ComSup = Round(@PVlrComSup,2),          
           Vlr_ComGer = Round(@PVlrComGer,2),          
           Vlr_ComSupOpe = Round(@PVlrComSupOpe,2),          
           Vlr_ComGerOpe = Round(@PVlrComGerOpe,2),          
           Val_ComTra = Case
                          When @tr_Pessoa = 'F' Then Round(@PVlrComTra,2)
                          Else Val_ComTra 
                        End,
           Flg_ComisNormal = @PFlgComNor
     Where Cod_Estabe = @PCodEstabe 
       and Ser_Nota = @PSerNot and Num_Nota = @PNumNot

    -- atualiza contas a receber  
    -- campo calculado: valor real da nota
    if @cb_TipRetImp = 'R'
      Set @WCVlrTotNot = @cb_VlrTotNot + @cb_VlrSubTri - @cb_VlrDscTri + @cb_VlrRecSbt
    else
      Set @WCVlrTotNot = @cb_VlrTotNot

    Set @WVlrComVnd = Round(@PVlrComVnd,2)
    Set @WVlrComOpe = Round(@PVlrComOpe,2)
    Set @WVlrComSup = Round(@PVlrComSup,2)
    Set @WVlrComGer = Round(@PVlrComGer,2)
    Set @WVlrComSupOpe = Round(@PVlrComSupOpe,2)
    Set @WVlrComGerOpe = Round(@PVlrComGerOpe,2)
    
    -- qg somente para garantir divisao por 0
    if @WCVlrTotNot = 0
      begin
        Set @WCVlrTotNot = 1
        Set @WVlrComVnd = 0
        Set @WVlrComOpe = 0
        Set @WVlrComSup = 0
        Set @WVlrComGer = 0
        Set @WVlrComSupOpe = 0
        Set @WVlrComGerOpe = 0
      end

    -- atualiza titulos relacionados
    Update CTREC
       Set Cod_Vendedor = @cb_CodVdr,
           Cod_VendTlmkt = @cb_CodOpe,
           Cod_Supervisor = @cb_CodSup,
           Cod_Gerencia = @cb_CodGer,
           Cod_SupOpe = @cb_CodSupOpe,
           Cod_GerOpe = @cb_CodGerOpe,
           Vlr_Comissao = Vlr_Documento * @WVlrComVnd / @WCVlrTotNot,
           Vlr_ComTlmkt = Vlr_Documento * @WVlrComOpe / @WCVlrTotNot,
           Vlr_ComSup = Vlr_Documento * @WVlrComSup / @WCVlrTotNot,
           Vlr_ComGer = Vlr_Documento * @WVlrComGer / @WCVlrTotNot,
           Vlr_ComSupOpe = Vlr_Documento * @WVlrComSupOpe / @WCVlrTotNot,
           Vlr_ComGerOpe = Vlr_Documento * @WVlrComGerOpe / @WCVlrTotNot
     Where Cod_Estabe = @PCodEstabe 
       And Ser_NfOrigem = @PSerNot and Num_NfOrigem = @PNumNot

    -- atualiza titulos do sfaturamento
    if (@PSerNot = 'ORC') and (@sf_NumNot > 0)
      begin
        if @sf_SerNot = ''
          Set @sf_SerNot = (Select ModeloNotaFiscal From PARAM Where Cod_Estabe = @PCodEstabe)
        if Exists(Select Num_Nota From NFSCB Where Cod_Estabe = @PCodEstabe and Ser_Nota = @sf_SerNot and Num_Nota = @sf_NumNot)
          begin
            -- atualza NFSCB sfat
            Update NFSCB
               Set Cod_Vendedor = @cb_CodVdr,
                   Cod_VendTlmkt = @cb_CodOpe,
                   Cod_Supervisor = @cb_CodSup,
                   Cod_Gerencia = @cb_CodGer,
                   Cod_SupOpe = @cb_CodSupOpe,
                   Cod_GerOpe = @cb_CodGerOpe
             Where Cod_Estabe = @PCodEstabe 
               and Ser_Nota = @sf_SerNot and Num_Nota = @sf_NumNot       
            -- atualiza CTREC sfat
            Update CTREC
               Set Cod_Vendedor = @cb_CodVdr,
                   Cod_VendTlmkt = @cb_CodOpe,
                   Cod_Supervisor = @cb_CodSup,
                   Cod_Gerencia = @cb_CodGer,
                   Cod_SupOpe = @cb_CodSupOpe,
                   Cod_GerOpe = @cb_CodGerOpe,
                   Vlr_Comissao = Vlr_Documento * @WVlrComVnd / @WCVlrTotNot,
                   Vlr_ComTlmkt = Vlr_Documento * @WVlrComOpe / @WCVlrTotNot,
                   Vlr_ComSup = Vlr_Documento * @WVlrComSup / @WCVlrTotNot,
                   Vlr_ComGer = Vlr_Documento * @WVlrComGer / @WCVlrTotNot,
                   Vlr_ComSupOpe = Vlr_Documento * @WVlrComSupOpe / @WCVlrTotNot,
                   Vlr_ComGerOpe = Vlr_Documento * @WVlrComGerOpe / @WCVlrTotNot
             Where Cod_Estabe = @PCodEstabe 
               And Ser_NfOrigem = @sf_SerNot and Num_NfOrigem = @sf_NumNot
          end    -- Exists
      end  
  
    Commit Transaction
  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CalculaComisPDV]
@CodEstabe int,
@NumPed int      -- num.do pedido

AS

SET NOCOUNT ON 

if (Select Flg_CalCom From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @NumPed) = 1
  begin
    Begin Transaction

    -- variaveis de trabalho
    Declare @WCodTabComOpe int,
            @WCodTabComVdr int,
            @WCodPrm int, 
            @WVlrBasFre numeric(18,4),
            @WVlrLiqNot numeric(18,4),
            @WFlgNotFis bit,
			@WQtdTot int,
            @WEstCli varchar(2),
            @WPerFrete numeric(18,4),
            @WPerDspTot numeric(18,4),
            @WVlrComiss numeric(18,4),
            @WQtdPrdVrb int,
            @WPerRetBon numeric(18,4),
            @WTipSai varchar(1),  -- 'B' = bonificacao
			@WVlrIcmTri numeric(18,4)

    -- campos para cabecalho da nota
    Declare @cb_TipFat varchar(3),
            @cb_TipSaiPdv varchar(1),
            @cb_CodCli int,
            @cb_DatEmi smalldatetime,
            @cb_PerDscCom numeric(18,4),
            @cb_PerDscFin numeric(18,4),
            @cb_QtdPrzMed numeric(18,4),
            @cb_PerComOpe numeric(18,4),
            @cb_PerComVnd numeric(18,4),
            @cb_PerComSup numeric(18,4),
            @cb_PerComGer numeric(18,4),
            @cb_PerComSupOpe numeric(18,4),
            @cb_PerComGerOpe numeric(18,4),
            @cb_CodOpe int,
            @cb_CodVdr int,
            @cb_CodSup int,
            @cb_CodGer int,
            @cb_CodSupOpe int,
            @cb_CodGerOpe int,
            @cb_TipVct varchar(1),
            @cb_VlrDscTri numeric(18,4),
            @cb_VlrSubTri numeric(18,4),
			@cb_VlrSbtRes numeric(18,4),
            @cb_VlrDscCom numeric(18,4),
            @cb_VlrLiqIte numeric(18,4),
            @cb_VlrRepIcm numeric(18,4),
            @cb_VlrTotNot numeric(18,4),
            @cb_CodTra int,
            @cb_FlgGerRetBon bit
            
    -- campos para TPOPE
    Declare @to_CodCfoNor smallint,
            @to_CodCfoSbt smallint,
            @cf_TipNotFis varchar(1)

    -- campos para transportadora
    Declare @tr_Pessoa varchar(1),
            @tr_PerFrete numeric(18,4),
            @tr_VlrMin numeric(18,4),
            @tr_FlgCalFreVerMer bit

    -- campos para atualizar em PDVCB
    Declare @PFlgComNor bit,
            @PVlrComVnd numeric(18,4),
            @PVlrComOpe numeric(18,4),
            @PVlrComSup numeric(18,4),
            @PVlrComGer numeric(18,4),
            @PVlrComSupOpe numeric(18,4),
            @PVlrComGerOpe numeric(18,4),
            @PVlrComTra numeric(18,4)

    -- Campos para itens da nota
    Declare @it_CodPrd int,
            @it_CodLot varchar(20),
            @it_TipSai varchar(1),
            @it_PerDsc numeric(18,4),
            @it_PerDesconto numeric (18,4),
            @it_CodPrm int, 
            @it_FlgPolPrm int, 
            @it_FlgDscIte bit,
            @it_FlgBlqInfPar bit,
            @it_PrcUni numeric (18,8),
            @it_PrcTab numeric (18,4),
            @it_VlrTot numeric (18,4),
            @it_VlrBasCom numeric(18,4),
            @it_VlrSubTri numeric (18,4),
            @it_VlrSbtRes numeric (18,4),
            @it_TipBasRnt varchar(1),
            @it_PrcBasRnt numeric(18,4),
            @it_TipLis varchar(1),
            @it_VlrIcm numeric(18,4),
            @it_AlqIcm numeric(18,4),
            @it_VlrIcmParDes numeric(18,4),
            @it_QtdPed int,
            @it_QtdBon int,
            @it_Cst varchar(2),
            @it_PerRedBasCalIcm numeric(18,4),
            @it_IdPolCom int,
            @it_VlrPis numeric(18,4),
            @it_VlrCof numeric(18,4),
            @it_VlrIpi numeric(18,4),
            @it_VlrBasTri numeric(18,4),
            @it_FlgUsaDebPresum bit,
            @it_AlqIcmPresum numeric(18,4),
            @it_PerLucBru numeric(18,4)

    -- variaveis a atualizar em PDVIT
    Declare @P_FlgComNor bit,
            @P_PerComVnd numeric(18,4),
            @P_VlrComVnd numeric(18,4),
            @P_PerComOpe numeric(18,4),
            @P_VlrComOpe numeric(18,4),
            @P_PerComSup numeric(18,4),
            @P_VlrComSup numeric(18,4),
            @P_PerComGer numeric(18,4),
            @P_VlrComGer numeric(18,4),
            @P_PerComSupOpe numeric(18,4),
            @P_VlrComSupOpe numeric(18,4),
            @P_PerComGerOpe numeric(18,4),
            @P_VlrComGerOpe numeric(18,4),
            @P_PerComTra numeric(18,4),
            @P_VlrComTra numeric(18,4),
            @P_PerVrbPar numeric(18,4), 
            @P_VlrVrbPar numeric(18,4), 
            @P_PerVrbBon numeric(18,4),
            @P_VlrVrbBon numeric(18,4),
            @P_PerRnt numeric(18,4)

    -- coloca campos de ESTAB/PARAM na memoria
    Declare @em_CodTipLuc varchar(2),
            @em_CodEst varchar(2),
			@em_FlgContriSubstituido bit,
            @pm_PerDesOpe numeric(18,4),
            @pm_PerDesFre numeric(18,4),
            @pm_PerDesCof numeric(18,4),
            @pm_PerDesIrpj numeric(18,4),
            @pm_PerDesConSoc numeric(18,4),
            @pm_PerDesPis numeric(18,4),
            @pm_FlgContribSubstituto bit,
            @pm_FlgBlqIcmTriCalRntPrdSbtFnt bit,
            @pm_FlgBlqDifalCalRnt bit

    Select @em_CodEst = Des_Estado,
           @em_CodTipLuc = IsNull(Cod_TipLucro,''),
		   @em_FlgContriSubstituido = IsNull(Flg_ContriSubstituido,0)
      From ESTAB
     Where Cod_Estabe = @CodEstabe

    Select @pm_PerDesOpe = IsNull(PerDesOpe,0),
           @pm_PerDesFre = IsNull(PerDesFre,0),
           @pm_PerDesPis = Case
                             When @em_CodTipLuc = 'LR' Then IsNull(PerDesPisLucRea,0) 
                             When @em_CodTipLuc = 'LP' Then IsNull(PerDesPisLucPre,0) 
                             Else 0
                           End,
           @pm_PerDesCof = Case
                             When @em_CodTipLuc = 'LR' Then IsNull(PerDesCofLucRea,0) 
                             When @em_CodTipLuc = 'LP' Then IsNull(PerDesCofLucPre,0) 
                             Else 0
                           End,
           @pm_PerDesIrpj = IsNull(PerDesIrpj,0),
           @pm_PerDesConSoc = IsNull(PerDesConSoc,0),
           @pm_FlgContribSubstituto = IsNull(FlgContribSubstituto,0),
           @pm_FlgBlqIcmTriCalRntPrdSbtFnt = IsNull(FlgBlqIcmTriCalRntPrdSbtFnt,0),
           @pm_FlgBlqDifalCalRnt = IsNull(FlgBlqDifalCalRnt,0)
      From PARAM
     Where Cod_Estabe = @CodEstabe

    -- normaliza campos PDVCB
    Update cb 
       Set cb.Cod_Supervisor = ve.Cod_Supervisor 
      From PDVCB cb 
	       Inner Join VENDE ve on cb.Cod_Vendedor = ve.Codigo
     Where cb.Cod_Estabe = @CodEstabe 
       And cb.Numero = @NumPed       
       And IsNull(cb.Cod_Supervisor,0) <> IsNull(ve.Cod_Supervisor,0)
      
    Update cb 
       Set cb.Cod_Gerencia = su.Cod_Gerencia
      From PDVCB cb 
	       Inner Join VENDE ve on cb.Cod_Vendedor = ve.Codigo 
		   Inner Join SUPER su on ve.Cod_Supervisor = su.Codigo
     Where cb.Cod_Estabe = @CodEstabe 
       And cb.Numero = @NumPed       
       And IsNull(cb.Cod_Gerencia,0) <> IsNull(su.Cod_Gerencia,0)

    Update cb 
       Set cb.Cod_SupOpe = ve.Cod_Supervisor 
      From PDVCB cb 
	       Inner Join VENDE ve on cb.Cod_VendTlmkt = ve.Codigo
     Where cb.Cod_Estabe = @CodEstabe 
       And cb.Numero = @NumPed       
       And IsNull(cb.Cod_SupOpe,0) <> IsNull(ve.Cod_Supervisor,0)
      
    Update cb 
       Set cb.Cod_GerOpe = su.Cod_Gerencia
      From PDVCB cb 
	       Inner Join VENDE ve on cb.Cod_VendTlmkt = ve.Codigo 
		   Inner Join SUPER su on ve.Cod_Supervisor = su.Codigo
     Where cb.Cod_Estabe = @CodEstabe 
       And cb.Numero = @NumPed       
       And IsNull(cb.Cod_GerOpe,0) <> IsNull(su.Cod_Gerencia,0)

    -- coloca campos de PDVCB na memoria
    Select @cb_TipFat = cb.Tip_Faturamento,
           @cb_TipSaiPdv = Tip_SaiPdv,
           @cb_CodCli = IsNull(cb.Cod_Cliente,0), 
           @cb_CodVdr = cb.Cod_Vendedor, 
           @cb_CodOpe = cb.Cod_VendTlmkt, 
           @cb_CodSup = cb.Cod_Supervisor, 
           @cb_CodGer = cb.Cod_Gerencia, 
           @cb_CodSupOpe = cb.Cod_SupOpe,
           @cb_CodGerOpe = cb.Cod_GerOpe, 
           @cb_DatEmi = cb.Dat_Pedido,
           @cb_PerDscCom = cb.Per_DescontoCom, 
           @cb_PerDscFin = cb.Per_DescontoFin, 
           @cb_TipVct = cb.Tip_Vencimento, 
           @cb_QtdPrzMed = cb.Qtd_PrzMed, 
           @cb_PerComOpe = cb.Per_ComOpe,
           @cb_PerComVnd = cb.Per_ComVnd,
           @cb_PerComSup = cb.Per_ComSup,
           @cb_PerComGer = cb.Per_ComGer,
           @cb_PerComSupOpe = cb.Per_ComSupOpe,
           @cb_PerComGerOpe = cb.Per_ComGerOpe,
           @cb_VlrDscTri = cb.Vlr_DscTri, 
           @cb_VlrSubTri = cb.Vlr_SubsTrib, 
           @cb_VlrSbtRes = cb.Vlr_SbtRes, 
           @cb_VlrDscCom = cb.C_VlrDesconto, 
           @cb_VlrLiqIte = cb.Vlr_LiqItens,
           @cb_VlrRepIcm = cb.Vlr_RepIcms,
           @cb_VlrTotNot = cb.C_VlrPedido,  
           @cb_CodTra = IsNull(cb.Cod_Transportadora,0),
           @cb_FlgGerRetBon = IsNull(Flg_GerRetBon,0),
           @WEstCli = case 
                        When IsNull(cb.Cod_Cliente,0) > 0 then cl.Cod_Estado
                        else @em_CodEst
                      end
      From PDVCB cb Left Outer Join CLIEN cl on cb.Cod_Cliente = cl.Codigo
     Where cb.Cod_Estabe = @CodEstabe 
       And cb.Numero = @NumPed       

    -- colococa campos de TPOPE na memoria
    Select @to_CodCfoSbt = case 
                             When @WEstCli = @em_CodEst then 
		        			   Case 
                                 When @em_FlgContriSubstituido = 1 and IsNull(Cod_CfoSbtIntSubstituido,0) > 0 then Cod_CfoSbtIntSubstituido
			                     Else Isnull(Cod_CfoSbtInt,0)
	 				           End
                             else
                               Case 
	                             When @em_FlgContriSubstituido = 1 and IsNull(Cod_CfoSbtExtSubstituido,0) > 0 then Cod_CfoSbtExtSubstituido
					             Else Isnull(Cod_CfoSbtExt,0)
					           End
                       end,
           @to_CodCfoNor = case 
                             When @WEstCli = @em_CodEst then Isnull(Cod_CfoNorInt,0)
                             else Isnull(Cod_CfoNorExt,0)
                           end
      From TPOPE
     Where Cod_Ope = @cb_TipFat

    -- coloca campos da transportadora na memoria
    Select @tr_Pessoa = tr.Pessoa,
           @tr_PerFrete = Case 
                            When tx.Cod_Transp is null then IsNull(tr.Per_Frete,0) 
                            Else IsNull(tx.Per_Frete,0) 
                          End,
           @tr_VlrMin = Case 
                            When tx.Cod_Transp is null then IsNull(tr.Vlr_Minimo,0) 
                            Else IsNull(tx.Vlr_Minimo,0) 
                          End,
           @tr_FlgCalFreVerMer = Case 
                                   When tx.Cod_Transp is null then IsNull(tr.Flg_CalFreVlrMer,0) 
                                   Else IsNull(tx.Flg_CalFreVlrMer,0) 
                                 End
      From TRANS tr
           Left Join TRXUF tx on tr.Codigo = tx.Cod_Transp and tx.Cod_UF COLLATE DATABASE_DEFAULT = @WEstCli COLLATE DATABASE_DEFAULT 
     Where tr.Codigo = @cb_CodTra

    -- p/ calculo da rentabilidade
    Set @WFlgNotFis = 0
    if (@to_CodCfoNor > 0) or (@to_CodCfoSbt > 0)
      Set @WFlgNotFis = 1

    -- inicializa acumuladores  p/  cabecalho
    Set @PVlrComVnd = 0
    Set @PVlrComOpe = 0
    Set @PVlrComSup = 0
    Set @PVlrComGer = 0
    Set @PVlrComSupOpe = 0
    Set @PVlrComGerOpe = 0
    Set @PVlrComTra = 0
    Set @PFlgComNor = 1

    -- pega tabela de comissao do vendedor e operador
    Set @WCodTabComOpe = (Select Cod_TabCom From VEXES Where Cod_Estabe = @CodEstabe And Cod_Vended = @cb_CodOpe)
    Set @WCodTabComVdr = (Select Cod_TabCom From VEXES Where Cod_Estabe = @CodEstabe And Cod_VEnded = @cb_CodVdr)

    -- comissao de supervisor/gerencia do vendedor    
    Set @cb_PerComSup = (Select IsNull(Per_ComNor,0) From SUPER Where Codigo = @cb_CodSup)
    Set @cb_PerComGer = (Select IsNull(Per_ComNor,0) From GEREN Where Codigo = @cb_CodGer)

    -- comissao de supervisor/gerencia do operador    
    Set @cb_PerComSupOpe = (Select IsNull(Per_ComNor,0) From SUPER Where Codigo = @cb_CodSupOpe)
    Set @cb_PerComGerOpe = (Select IsNull(Per_ComNor,0) From GEREN Where Codigo = @cb_CodGerOpe)
    
    -- calcula comissao dos itens: 
    Declare PDVIT_Cr Cursor Local Fast_Forward For 
      Select it.Cod_Produto, it.Cod_Lote, it.Tip_Sai, it.C_PrcTotal, 
             Case   -- comissao na considera desconto bonificaao rateado
               When IsNull(it.Desconto,0) = 1  then (it.C_PrcTotal - IsNull(it.Vlr_RepIcms,0) - IsNull(it.Vlr_DscTri,0))
               Else (it.C_PrcTotal*(1-IsNull(cb.Per_DescontoCom,0)/100) - IsNull(it.Vlr_RepIcms,0) - IsNull(it.Vlr_DscTri,0))
             End, IsNull(it.Vlr_SubsTrib,0), IsNull(it.Vlr_SbtRes,0), IsNull(it.Per_RntBru,0),
             it.Prc_Unitario, it.Prc_Tabela, it.Flg_PrcUniDsc, it.Flg_BlqInfPar, it.Cod_Promocao, it.Flg_PolPrm, it.Per_Descon, it.Per_Desconto, 
             it.Tip_BasRnt, it.Prc_BasRnt, it.Tip_Aux, IsNull(it.Vlr_IcmsTri,0), it.Alq_Icms, IsNull(it.Qtd_Pedido,0), IsNull(it.Qtd_Bonificacao,0), 
             it.Ctrl_Tributacao, IsNull(it.Per_RedBasCalIcm,0), IsNull(it.Id_PolCom,0), IsNull(it.Vlr_Pis,0), IsNull(it.Vlr_Cofins,0), IsNull(it.Vlr_Ipi,0), 
			 it.Vlr_BasTri, IsNull(it.Flg_UsaDebPresum,0), IsNull(it.Alq_IcmPresum,0), IsNull(it.Vlr_IcmParDes,0)
        From PDVIT it 
             Inner Join PDVCB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Cod_Pedido = cb.Numero		     
       Where it.Cod_Estabe = @CodEstabe 
         And it.Cod_Pedido = @NumPed 
         And IsNull(it.Qtd_Pedido,0) > 0
    Open PDVIT_Cr
    Fetch Next From PDVIT_Cr Into @it_CodPrd, @it_CodLot, @it_TipSai, @it_VlrTot,
	                              @it_VlrBasCom, @it_VlrSubTri, @it_VlrSbtRes, @it_PerLucBru,
                                  @it_PrcUni, @it_PrcTab, @it_FlgDscIte, @it_FlgBlqInfPar, @it_CodPrm, @it_FlgPolPrm, @it_PerDsc, @it_PerDesconto, 
                                  @it_TipBasRnt, @it_PrcBasRnt, @it_TipLis, @it_VlrIcm, @it_AlqIcm, @it_QtdPed, @it_QtdBon, 
                                  @it_Cst, @it_PerRedBasCalIcm, @it_IdPolCom, @it_VlrPis, @it_VlrCof, @it_VlrIpi,
								  @it_VlrBasTri, @it_FlgUsaDebPresum, @it_AlqIcmPresum, @it_VlrIcmParDes
    While @@FETCH_STATUS = 0
      begin
        ---- verbas de bonfificações para clientes
        Set @P_PerVrbPar = 0
        Set @P_VlrVrbPar = 0
        Set @P_PerVrbBon = 0
        Set @P_VlrVrbBon = 0
        if (@cb_FlgGerRetBon = 1) and (@cb_CodCli > 0)
          begin
            -- bonificacao de produto 
            -- obtem quantidade total do produto no pedido
            Set @WQtdPrdVrb = IsNull((Select sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0))
                                        From PDVIT 
                                       Where Cod_Estabe = @CodEstabe 
                                         And Cod_Pedido = @NumPed
                                         And Cod_Produto = @it_CodPrd 
                                         And Qtd_Pedido > 0),0)

            Set @WPerRetBon = IsNull((Select top 1 it.Per_RetBon 
                                        From PRBCB cb Inner Join PRBIT it on cb.Id_PRBCB = it.Id_PRBCB
                                       Where @cb_DatEmi between cb.Dat_Ini and cb.Dat_Fim
                                         And cb.Cod_Produt = @it_CodPrd
                                         And Qtd_Minima <= @WQtdPrdVrb
                                       Order by it.Qtd_Minima desc),0)
                                            
            Set @P_PerVrbBon = @WPerRetBon
            Set @P_VlrVrbBon = Round(@it_VlrTot*@WPerRetBon/100,2,1)
                  
            -- bonificacao de parceria
            Set @WPerRetBon = IsNull((Select top 1 Per_RetBon
                                        From ((Select top 1 '3' as Num_Ord, cb.Per_RetBon, cb.Numero
                                                 From PARCE cb
                                                Where cb.Status = '0'
                                                  And cb.CodCli = @cb_CodCli
                                                Order by cb.Numero desc) 
                                              UNION
                                              (Select top 1 '2' as Num_Ord, it.Per_RetBon, cb.Numero
                                                 From PARCE cb Inner Join 
                                                      PARBF it on (cb.Numero = it.Cod_Parcer) Inner Join
                                                      PRODU pr on (it.Cod_Fabric = pr.Cod_Fabricante) 
                                                Where cb.Status = '0'
                                                  And cb.CodCli = @cb_CodCli
                                                  And pr.Codigo = @it_CodPrd
                                                Order by cb.Numero desc) 
                                              UNION
                                              (Select top 1 '1' as Num_Ord, it.Per_RetBon, cb.Numero
                                                 From PARCE cb Inner Join 
                                                      PARBP it on (cb.Numero = it.Cod_Parcer)
                                                Where cb.Status = '0'
                                                  And cb.CodCli = @cb_CodCli
                                                  And it.Cod_Produt = @it_CodPrd
                                                Order by cb.Numero desc)) x
                                       Order by Num_Ord),0)                    
            Set @P_PerVrbPar = @WPerRetBon
            Set @P_VlrVrbPar = Round(@it_VlrTot*@WPerRetBon/100,2,1)
          end
          
        -- calcula comissao
        Set @WPerRetBon = @P_PerVrbPar + @P_PerVrbBon
        if (@it_TipSai = 'B') or (@cb_TipSaiPdv = 'B')  
          Set @WTipSai = 'B'
        else  
          Set @WTipSai = ''

        Set @WCodPrm = IsNull(@it_CodPrm,0) + IsNull(@it_FlgPolPrm,0)
        EXEC PR_CalcComisItemSaida @CodEstabe, @NumPed, @it_CodPrd, @WTipSai, @cb_CodCli, @cb_DatEmi, @it_VlrBasCom, 
                                   @it_PrcUni, @it_PrcTab, @it_FlgDscIte, @it_FlgBlqInfPar, 
                                   @WCodPrm, @it_PerDsc, @it_PerDesconto, @cb_PerDscCom, @cb_PerDscFin, @cb_TipVct, 
                                   @cb_QtdPrzMed, @cb_PerComVnd, @WCodTabComVdr, @cb_PerComOpe, @WCodTabComOpe, 
                                   @cb_PerComSup, @cb_PerComGer, @cb_PerComSupOpe, @cb_PerComGerOpe,  @it_IdPolCom, @WPerRetBon, @it_PerLucBru, @P_FlgComNor output, 
                                   @P_PerComOpe output, @P_PerComVnd output, @P_PerComSup output, @P_PerComGer output, @P_PerComSupOpe output, @P_PerComGerOpe output,
                                   @P_VlrComOpe output, @P_VlrComVnd output, @P_VlrComSup output, @P_VlrComGer output, @P_VlrComSupOpe output, @P_VlrComGerOpe output

        -- calcula comissao de entrega
        Set @P_PerComTra = 0
        Set @P_VlrComTra = 0
        if @tr_Pessoa = 'F'
          begin
            Select @P_PerComTra = Isnull(Per_ComEnt,0) From PRXES Where Cod_Estabe = @CodEstabe and Cod_Produt = @it_CodPrd
            Set @P_VlrComTra = @it_VlrBasCom * @P_PerComTra/100
          end

        -- recalcula rentabilidade
        Set @P_PerRnt = 0

        Set @WQtdTot = @it_QtdPed + @it_QtdBon

        Set @WVlrComiss = @P_VlrComVnd + @P_VlrComOpe + @P_VlrComSup + @P_VlrComGer + @P_VlrComSupOpe + @P_VlrComGerOpe + @P_VlrComTra

		if @tr_PerFrete > 0
          Set @WPerFrete = @tr_PerFrete
        else
          Set @WPerFrete = -1

        -- verifique qual aliquota de icm utilizar no calculo da rentabilidade
        Set @WVlrIcmTri = @it_VlrIcm
        if (@it_FlgUsaDebPresum = 1) and (@it_VlrIcm > 0)
          begin
            Set @WVlrIcmTri = @it_VlrBasTri*@it_AlqIcmPresum*(1-0/100)/100
          end

        -- ICMS tributavel + Dfal
        if @pm_FlgBlqDifalCalRnt = 0
          Set @WVlrIcmTri = @WVlrIcmTri + @it_VlrIcmParDes

        Set @P_PerRnt = dbo.FN_PerRentabilidade (@it_TipBasRnt, @CodEstabe, @WFlgNotFis, @cb_DatEmi, @it_CodPrd, @WQtdTot, @it_VlrBasTri, 
                                                 @it_PrcBasRnt, @it_VlrPis, @it_VlrCof, @it_VlrIpi, @WVlrIcmTri, 
                                                 @it_VlrSubTri, @it_VlrSbtRes, @WVlrComiss, @WPerFrete, @P_PerVrbPar+@P_PerVrbBon)

        -- atualiza item da nota
        Update PDVIT
           Set Per_ComTlmkt = @P_PerComOpe,
               Per_Comissao = @P_PerComVnd,
               Per_ComSup = @P_PerComSup,
               Per_ComGer = @P_PerComGer,
               Per_ComSupOpe = @P_PerComSupOpe,
               Per_ComGerOpe = @P_PerComGerOpe,
               Per_ComTra = @P_PerComTra,
               Vlr_ComTlmkt = @P_VlrComOpe,
               Vlr_Comissao = @P_VlrComVnd,
               Vlr_ComSup = @P_VlrComSup,
               Vlr_ComGer = @P_VlrComGer,
               Vlr_ComSupOpe = @P_VlrComSupOpe,
               Vlr_ComGerOpe = @P_VlrComGerOpe,
               Val_ComTra = @P_VlrComTra,
               Per_VrbPar = @P_PerVrbPar, 
               Vlr_VrbPar = @P_VlrVrbPar,
               Per_VrbBon = @P_PerVrbBon,
               Vlr_VrbBon = @P_VlrVrbBon,
               Per_Rnt = @P_PerRnt
         Where Cod_Estabe = @CodEstabe 
           And Cod_Pedido = @NumPed
           And Cod_Produto = @it_CodPrd
           And Cod_Lote = @it_CodLot
           And Tip_Sai = @it_TipSai

        -- acumula valores p/  cabecalho
        Set @PVlrComVnd = @PVlrComVnd + @P_VlrComVnd
        Set @PVlrComOpe = @PVlrComOpe + @P_VlrComOpe
        Set @PVlrComSup = @PVlrComSup + @P_VlrComSup
        Set @PVlrComGer = @PVlrComGer + @P_VlrComGer
        Set @PVlrComSupOpe = @PVlrComSupOpe + @P_VlrComSupOpe
        Set @PVlrComGerOpe = @PVlrComGerOpe + @P_VlrComGerOpe
        Set @PVlrComTra = @PVlrComTra + @P_VlrComTra
        if @P_FlgComNor = 0
          Set @PFlgComNor = 0

        Fetch Next From PDVIT_Cr Into @it_CodPrd, @it_CodLot, @it_TipSai, @it_VlrTot,
                                      @it_VlrBasCom, @it_VlrSubTri, @it_VlrSbtRes, @it_PerLucBru,
                                      @it_PrcUni, @it_PrcTab, @it_FlgDscIte, @it_FlgBlqInfPar, @it_CodPrm, @it_FlgPolPrm, @it_PerDsc, @it_PerDesconto, 
                                      @it_TipBasRnt, @it_PrcBasRnt, @it_TipLis, @it_VlrIcm, @it_AlqIcm, @it_QtdPed, @it_QtdBon, 
                                      @it_Cst, @it_PerRedBasCalIcm, @it_IdPolCom, @it_VlrPis, @it_VlrCof, @it_VlrIpi,
                                      @it_VlrBasTri, @it_FlgUsaDebPresum, @it_AlqIcmPresum, @it_VlrIcmParDes
      end
    Close PDVIT_Cr 
    Deallocate PDVIT_Cr

    -- calcula frete p/ pessoa juridica
    if @tr_Pessoa <> 'F'
      begin
        Set @WVlrLiqNot = @cb_VlrLiqIte - @cb_VlrDscCom - @cb_VlrRepIcm - @cb_VlrDscTri
        if @tr_FlgCalFreVerMer = 1
          Set @WVlrBasFre = @WVlrLiqNot
        else
          Set @WVlrBasFre = @cb_VlrTotNot

        Set @PVlrComTra = Round(@WVlrBasFre*@tr_PerFrete/100,2)
        if Round(@PVlrComTra*100,2) < Round(@tr_VlrMin*100,2)
          Set @PVlrComTra = @tr_VlrMin
      end

    -- Atualiza acumuladores em PDVCB
    Update PDVCB
       Set Vlr_Comissao = Round(@PVlrComVnd,2),
           Vlr_ComTlmkt = Round(@PVlrComOpe,2),
           Vlr_ComSup = Round(@PVlrComSup,2),
           Vlr_ComGer = Round(@PVlrComGer,2),
           Vlr_ComSupOpe = Round(@PVlrComSupOpe,2),
           Vlr_ComGerOpe = Round(@PVlrComGerOpe,2),
           Val_ComTra = Round(@PVlrComTra,2),
           Per_Rnt = case 
                       when (Select sum(Vlr_BasTri) from PDVIT Where Cod_Estabe = @CodEstabe  and Cod_Pedido = @NumPed And Qtd_Pedido > 0) > 0 then
                         (Select Sum(Per_Rnt*Vlr_BasTri)/sum(Vlr_BasTri) from PDVIT Where Cod_Estabe = @CodEstabe and Cod_Pedido = @NumPed And Qtd_Pedido > 0)
                       else -100.0
                     end
     Where Cod_Estabe = @CodEstabe 
       And Numero = @NumPed
 
    Commit Transaction
  end

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_Saida_Excesso_Lotes]
@CodEstabe int

AS

SET NOCOUNT ON 

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

BEGIN
  Begin Transaction

  Declare @QtdTotSai int,
          @QtdFra int,
          @QtdSobra int,
          @QtdEmbFecCal int,
          @QtdCxaFec int,
          @QtdUndLot int,
          @NumRuaIniDiv int,
          @NumRuaFimDiv int,

          @CodPrd int,
          @CodLot varchar(20),
          @CodDep int, 
          @NumRua int, 
          @NumCol int, 
          @NumNiv int, 
          @NumApt int, 
          @SldPra int,
          @SldDep int

  -- dar saída da zona de divergências em PRLTL
  Set @NumRuaIniDiv = 0
  Set @NumRuaFimDiv = 0
  Select top 1 
         @NumRuaIniDiv = zn.Num_RuaIni, 
         @NumRuaFimDiv = zn.Num_RuaFim
    From PMEST pm
         inner join TBZON zn on pm.Cod_Estabe = zn.Cod_Estabe and pm.CodZonDiv = zn.Cod_Zon
   Where pm.Cod_Estabe = @CodEstabe


  -- transefre para zona de divergência PRLTL inconsistentes----------------------------
  Declare PRLTL_Cr Cursor Local Fast_Forward For 

    Select lt.Cod_Produt, lt.Cod_Lote, lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt, 
           lt.C_QtdEmbFec, lt.Qtd_SldPra, lt.Qtd_SldDep, Qtd_Sobra=Qtd_Saldo%Qtd_EmbFec
      From PRLTL lt
     Where lt.Cod_Estabe = @CodEstabe
       And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
       And lt.Qtd_Saldo > 0
       And lt.Qtd_Saldo%lt.Qtd_EmbFec > 0
     Order by Cod_Produt, Cod_lote

  Open PRLTL_Cr
  Fetch Next From PRLTL_Cr Into @CodPrd, @CodLot, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, 
                                @QtdEmbFecCal, @SldPra, @SldDep, @QtdSobra
  While @@FETCH_STATUS = 0
    begin
      -- dar saída em Dep
      if (@QtdSobra > 0) and (@SldDep > 0)
        begin
          Set @QtdUndLot = Case 
                             When @SldDep < @QtdSobra Then @SldDep
                             Else @QtdSobra
                           End
          if Exists(Select 1 From PRLTL
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Produt = @CodPrd
                       And Cod_Lote = @CodLot
                       And Cod_Dep = @CodDep
                       And Num_Rua = @NumRua
                       And Num_Col = @NumCol
                       And Num_Niv = @NumNiv
                       And Num_Apt = @NumApt
                       And Qtd_SldDep >= @QtdUndLot
                       And Qtd_FisDep >= @QtdUndLot)
            begin
              -- dar saída em PRLTL
              Update PRLTL
                 Set Qtd_FisDep = IsNull(Qtd_FisDep,0) - @QtdUndLot
               Where Cod_Estabe = @CodEstabe 
                 And Cod_Produt = @CodPrd
                 And Cod_Lote = @CodLot
                 And Cod_Dep = @CodDep
                 And Num_Rua = @NumRua
                 And Num_Col = @NumCol
                 And Num_Niv = @NumNiv
                 And Num_Apt = @NumApt
                 And IsNull(Qtd_FisDep,0) >= @QtdUndLot
              if @@rowcount = 0
                begin
                  Rollback Transaction
                  Return
                end

              -- dá entrada em zona de divergência PRLTL
              if not Exists(Select 1 From PRLTL 
                             Where Cod_Estabe = @CodEstabe 
                               And Cod_Produt = @CodPrd
                               And Cod_Lote = @CodLot
                               And Cod_Dep = @CodDep
                               And Num_Rua = @NumRuaIniDiv
                               And Num_Col = 1
                               And Num_Niv = 1
                               And Num_Apt = 0)
                Insert Into PRLTL (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Num_Rua, Num_Col, Num_Niv, Num_Apt, Qtd_FisPra, Qtd_FisDep)
                           Values (@CodEstabe, @CodDep, @CodPrd, @CodLot, @NumRuaIniDiv, 1, 1, 0, 0, 0)

              Update dp
                 Set dp.Qtd_FisPra = IsNull(dp.Qtd_FisPra,0) + @QtdUndLot,
                     dp.Qtd_EmbFec = 1,
                     dp.Dat_Vencim = pk.Dat_Vencim,
                     dp.Dat_Fabric = pk.Dat_Fabric
                From PRLTL dp
				     left join PRLOT pk on (dp.Cod_Estabe = pk.Cod_Estabe and dp.Cod_Dep = pk.Cod_Dep and
                                            dp.Cod_Produt = pk.Cod_Produt and dp.Cod_Lote = pk.Cod_Lote)
               Where dp.Cod_Estabe = @CodEstabe 
                 And dp.Cod_Produt = @CodPrd
                 And dp.Cod_Lote = @CodLot
                 And dp.Cod_Dep = @CodDep
                 And dp.Num_Rua = @NumRuaIniDiv
                 And dp.Num_Col = 1
                 And dp.Num_Niv = 1
                 And dp.Num_Apt = 0

              Set @QtdSobra = @QtdSobra - @QtdUndLot

            end  -- if Exists(
        end  -- if (@QtdSobra > 0) and (@SldDep > 0)

      -- dar saída em Pra
      if (@QtdSobra > 0) and (@SldPra > 0)
        begin
          Set @QtdUndLot = Case 
                             When @SldPra < @QtdSobra Then @SldPra
                             Else @QtdSobra
                           End

          if Exists(Select 1 From PRLTL
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Produt = @CodPrd
                       And Cod_Lote = @CodLot
                       And Cod_Dep = @CodDep
                       And Num_Rua = @NumRua
                       And Num_Col = @NumCol
                       And Num_Niv = @NumNiv
                       And Num_Apt = @NumApt
                       And Qtd_SldPra >= @QtdUndLot
                       And Qtd_FisPra >= @QtdUndLot)
            begin
              -- dar saída em PRLTL
              Update PRLTL
                 Set Qtd_FisPra = IsNull(Qtd_FisPra,0) - @QtdUndLot
               Where Cod_Estabe = @CodEstabe 
                 And Cod_Produt = @CodPrd
                 And Cod_Lote = @CodLot
                 And Cod_Dep = @CodDep
                 And Num_Rua = @NumRua
                 And Num_Col = @NumCol
                 And Num_Niv = @NumNiv
                 And Num_Apt = @NumApt
                 And IsNull(Qtd_FisPra,0) >= @QtdUndLot
              if @@rowcount = 0
                begin
                  Rollback Transaction
                  Return
                end

              -- dá entrada em divergências
              if not Exists(Select 1 From PRLTL 
                             Where Cod_Estabe = @CodEstabe 
                               And Cod_Produt = @CodPrd
                               And Cod_Lote = @CodLot
                               And Cod_Dep = @CodDep
                               And Num_Rua = @NumRuaIniDiv
                               And Num_Col = 1
                               And Num_Niv = 1
                               And Num_Apt = 0)
                Insert Into PRLTL (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Num_Rua, Num_Col, Num_Niv, Num_Apt, Qtd_FisPra, Qtd_FisDep)
                           Values (@CodEstabe, @CodDep, @CodPrd, @CodLot, @NumRuaIniDiv, 1, 1, 0, 0, 0)

              Update dp
                 Set dp.Qtd_FisPra = IsNull(dp.Qtd_FisPra,0) + @QtdUndLot,
                     dp.Qtd_EmbFec = 1,
                     dp.Dat_Vencim = pk.Dat_Vencim,
                     dp.Dat_Fabric = pk.Dat_Fabric
                From PRLTL dp
				     left join PRLOT pk on (dp.Cod_Estabe = pk.Cod_Estabe and dp.Cod_Dep = pk.Cod_Dep and
                                            dp.Cod_Produt = pk.Cod_Produt and dp.Cod_Lote = pk.Cod_Lote)
               Where dp.Cod_Estabe = @CodEstabe 
                 And dp.Cod_Produt = @CodPrd
                 And dp.Cod_Lote = @CodLot
                 And dp.Cod_Dep = @CodDep
                 And dp.Num_Rua = @NumRuaIniDiv
                 And dp.Num_Col = 1
                 And dp.Num_Niv = 1
                 And dp.Num_Apt = 0

              Set @QtdFra = @QtdFra - @QtdUndLot
            end
        end -- if @QtdSobra > 0

      Fetch Next From PRLTL_Cr Into @CodPrd, @CodLot, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, 
                                    @QtdEmbFecCal, @SldPra, @SldDep, @QtdSobra

    end    -- While @@FETCH_STATUS = 0

  Close PRLTL_Cr
  Deallocate PRLTL_Cr


  -- dá saida de lotes em excesso  (PRLOT+PRLTL > PRXES)
  Declare PRODU_Cr Cursor Local Fast_Forward For 

    Select p.Cod_Produt, 
           C_QtdSaiTotLotes = dbo.FN_EstoqueFisicoPrdLote(p.Cod_Estabe, p.Cod_Produt, 'TODOS') - p.Qtd_Fisico
      From PRXES p 
     Where p.Cod_Estabe = @CodEstabe
       And ((p.Qtd_Fisico < dbo.FN_EstoqueFisicoPrdLote(p.Cod_Estabe, p.Cod_Produt, 'TODOS'))  or 
            (p.Qtd_Dispon >  dbo.FN_EstoqueDisponivelPrdLote(p.Cod_Estabe, p.Cod_Produt, 'TODOS')))
       And dbo.FN_EstoqueDisponivelPrdLote(p.Cod_Estabe, p.Cod_Produt, 'TODOS') >= (p.Qtd_Fisico - dbo.FN_EstoqueFisicoPrdLote(p.Cod_Estabe, p.Cod_Produt, 'TODOS'))
     Order by p.Cod_Produt

  Open PRODU_Cr  
  Fetch Next From PRODU_Cr Into @CodPrd, @QtdTotSai
  While @@FETCH_STATUS = 0  
    begin
      Set @QtdFra = @QtdTotSai  

      -- dar saída da zona de divergências em PRLTL de lotes conforme regra do sistema -----------------------------------------------
      Declare PRLTL_Cr Cursor Local Fast_Forward For 

        Select lt.Cod_Lote, lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt, 
               lt.C_QtdEmbFec, lt.Qtd_SldPra, lt.Qtd_SldDep
          From PRLTL lt
         Where lt.Cod_Estabe = @CodEstabe 
