           And IsNull(lt.Qtd_Saldo,0) > 0
           And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'X'
           And lt.Num_Rua between @NumRuaIniDiv and @NumRuaFimDiv
         Order by lt.Dat_Vencim, lt.Num_Rua, lt.Num_Niv, lt.Num_Apt, lt.Num_Col, lt.Cod_Lote, lt.Dat_Entrada
   
      Open PRLTL_Cr
      Fetch Next From PRLTL_Cr Into @CodLot, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, 
