                                 Else @QtdFra
                               End
   
              if Exists(Select 1 From PRLTL
                         Where Cod_Estabe = @CodEstabe 
                           And Cod_Produt = @CodPrd
                           And Cod_Lote = @CodLot
                           And Cod_Dep = @CodDep
                           And Num_Rua = @NumRua
                           And Num_Col = @NumCol
                           And Num_Niv = @NumNiv
                           And Num_Apt = @NumApt
                           And Qtd_SldDep >= @QtdUndLot
                           And Qtd_FisDep >= @QtdUndLot)
                  begin
                    -- dar saída em PRLTL
                    Update PRLTL
                       Set Qtd_FisDep = IsNull(Qtd_FisDep,0) - @QtdUndLot
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Produt = @CodPrd
                       And Cod_Lote = @CodLot
                       And Cod_Dep = @CodDep
                       And Num_Rua = @NumRua
                       And Num_Col = @NumCol
                       And Num_Niv = @NumNiv
                       And Num_Apt = @NumApt
                       And IsNull(Qtd_FisDep,0) >= @QtdUndLot
                    if @@rowcount = 0
                      begin
                        Rollback Transaction
                        Return
                      end
   
                    Set @QtdFra = @QtdFra - @QtdUndLot
                  end
              end -- if (@QtdFra > 0) and (@QtdFra >= @QtdEmbFec) and (@SldDep >= @QtdEmbFec) 
   
   
            -- dar saída em Pra
            if @QtdFra > 0
              begin
                Set @QtdUndLot = Case 
                                   When @SldPra < @QtdFra Then @SldPra
                                   Else @QtdFra
                                 End
   
                if Exists(Select 1 From PRLTL
                           Where Cod_Estabe = @CodEstabe 
                             And Cod_Produt = @CodPrd
                             And Cod_Lote = @CodLot
                             And Cod_Dep = @CodDep
                             And Num_Rua = @NumRua
                             And Num_Col = @NumCol
                             And Num_Niv = @NumNiv
                             And Num_Apt = @NumApt
                             And Qtd_SldPra >= @QtdUndLot
                             And Qtd_FisPra >= @QtdUndLot)
                  begin
                    -- dar saída em PRLTL
                    Update PRLTL
                       Set Qtd_FisPra = IsNull(Qtd_FisPra,0) - @QtdUndLot
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Produt = @CodPrd
                       And Cod_Lote = @CodLot
                       And Cod_Dep = @CodDep
                       And Num_Rua = @NumRua
                       And Num_Col = @NumCol
                       And Num_Niv = @NumNiv
                       And Num_Apt = @NumApt
                       And IsNull(Qtd_FisPra,0) >= @QtdUndLot
                    if @@rowcount = 0
                      begin
