                        Return
                      end
   
                    Set @QtdFra = @QtdFra - @QtdUndLot
                  end
              end -- if (@QtdFra > 0) and (@QtdFra >= @QtdEmbFec) and (@SldPra >= @QtdEmbFec) 
   
  	      Fetch Next From PRLTL_Cr Into @CodLot, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, 
