        end    -- While @@FETCH_STATUS = 0
   
      Close PRLTL_Cr
      Deallocate PRLTL_Cr
   
   
      -- dar saída pulmão em PRLTL conforme regra do sistema --------------------------------------------------------
      Declare PRLTL_Cr Cursor Local Fast_Forward For 
        Select lt.Cod_Lote, lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt, 
               lt.C_QtdEmbFec, lt.Qtd_SldPra, lt.Qtd_SldDep
          From PRLTL lt
         Where lt.Cod_Estabe = @CodEstabe 
           And lt.Cod_Produt = @CodPrd
           And IsNull(lt.Qtd_Saldo,0) > 0
           And IsNull(lt.C_QtdEmbFec,0) > 0 
           And IsNull(lt.Qtd_Saldo,0) >= IsNull(lt.C_QtdEmbFec,0) 
           And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
         Order by lt.Dat_Vencim, lt.Num_Rua, lt.Num_Niv, lt.Num_Apt, lt.Num_Col, lt.Cod_Lote, lt.Dat_Entrada
   
      Open PRLTL_Cr
      Fetch Next From PRLTL_Cr Into @CodLot, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, 
                                    @QtdEmbFecCal, @SldPra, @SldDep 
      While @@FETCH_STATUS = 0
        begin
   
          -- dar saída em Dep
          if (@QtdFra > 0) and (@QtdFra >= @QtdEmbFecCal) and (@SldDep >= @QtdEmbFecCal) 
            begin
              Set @QtdCxaFec = Case 
                                 When @SldDep < @QtdFra Then @SldDep / @QtdEmbFecCal
                                 Else @QtdFra / @QtdEmbFecCal
                               End
              Set @QtdUndLot = @QtdCxaFec * @QtdEmbFecCal
   
              if Exists(Select 1 From PRLTL
                         Where Cod_Estabe = @CodEstabe 
                           And Cod_Produt = @CodPrd
                           And Cod_Lote = @CodLot
                           And Cod_Dep = @CodDep
                           And Num_Rua = @NumRua
                           And Num_Col = @NumCol
                           And Num_Niv = @NumNiv
                           And Num_Apt = @NumApt
                           And Qtd_SldDep >= @QtdUndLot
                           And Qtd_FisDep >= @QtdUndLot)
                  begin
                    -- dar saída em PRLTL
                    Update PRLTL
                       Set Qtd_FisDep = IsNull(Qtd_FisDep,0) - @QtdUndLot
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Produt = @CodPrd
                       And Cod_Lote = @CodLot
                       And Cod_Dep = @CodDep
                       And Num_Rua = @NumRua
                       And Num_Col = @NumCol
                       And Num_Niv = @NumNiv
                       And Num_Apt = @NumApt
                       And IsNull(Qtd_FisDep,0) >= @QtdUndLot
                    if @@rowcount = 0
                      begin
