              begin
                Set @QtdCxaFec = Case 
                                   When @SldPra < @QtdFra Then @SldPra / @QtdEmbFecCal
                                   Else @QtdFra / @QtdEmbFecCal
                                 End
                Set @QtdUndLot = @QtdCxaFec * @QtdEmbFecCal
   
                if Exists(Select 1 From PRLTL
                           Where Cod_Estabe = @CodEstabe 
                             And Cod_Produt = @CodPrd
                             And Cod_Lote = @CodLot
                             And Cod_Dep = @CodDep
                             And Num_Rua = @NumRua
                             And Num_Col = @NumCol
                             And Num_Niv = @NumNiv
                             And Num_Apt = @NumApt
                             And Qtd_SldPra >= @QtdUndLot
                             And Qtd_FisPra >= @QtdUndLot)
                  begin
                    -- dar saída em PRLTL
                    Update PRLTL
                       Set Qtd_FisPra = IsNull(Qtd_FisPra,0) - @QtdUndLot
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Produt = @CodPrd
                       And Cod_Lote = @CodLot
                       And Cod_Dep = @CodDep
                       And Num_Rua = @NumRua
                       And Num_Col = @NumCol
                       And Num_Niv = @NumNiv
                       And Num_Apt = @NumApt
                       And IsNull(Qtd_FisPra,0) >= @QtdUndLot
                    if @@rowcount = 0
                      begin
