                        Return
                      end
   
                    Set @QtdFra = @QtdFra - @QtdUndLot
                  end
              end -- if (@QtdFra > 0) and (@QtdFra >= @QtdEmbFec) and (@SldPra >= @QtdEmbFec) 
   
          Fetch Next From PRLTL_Cr Into @CodLot, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, 
                                        @QtdEmbFecCal, @SldPra, @SldDep 
        end
   
      Close PRLTL_Cr
      Deallocate PRLTL_Cr

   
      -- dar saída da qualquer zona de quarentena em PRLTL de lotes conforme regra do sistema -----------------------------------------------
      Declare PRLTL_Cr Cursor Local Fast_Forward For 

        Select lt.Cod_Lote, lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt, 
               lt.C_QtdEmbFec, lt.Qtd_SldPra, lt.Qtd_SldDep
          From PRLTL lt
         Where lt.Cod_Estabe = @CodEstabe 
           And lt.Cod_Produt = @CodPrd
           And IsNull(lt.Qtd_Saldo,0) > 0
           And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'X'
         Order by lt.Dat_Vencim, lt.Num_Rua, lt.Num_Niv, lt.Num_Apt, lt.Num_Col, lt.Cod_Lote, lt.Dat_Entrada
   
      Open PRLTL_Cr
