        end    -- While @@FETCH_STATUS = 0
   
      Close PRLTL_Cr
      Deallocate PRLTL_Cr

   
      -- dar saída picking em PRLOT conforme regra do sistema --------------------------------------------------------
      -- verifica se necessita abastecimento no picking
      if @QtdFra > 0
        begin
          While Exists(Select 1
                        From PRLOT pk
                       Where pk.Cod_Estabe = @CodEstabe 
                         And pk.Cod_Produt = @CodPrd
                         And Exists(Select 1
                                      From PRLTL dp
                                     Where dp.Cod_Estabe = @CodEstabe 
                                       And dp.Cod_Produt = @CodPrd
                                       And IsNull(dp.Qtd_Saldo,0) > 0
                                       And IsNull(dp.C_QtdEmbFec,0) > 0 
                                       And IsNull(dp.Qtd_Saldo,0) >= IsNull(dp.C_QtdEmbFec,0) 
                                       And dbo.FN_TipLocEnd(dp.Cod_Estabe, dp.Cod_Dep, dp.Num_Rua) = 'D')
                       Group by pk.Cod_Estabe, pk.Cod_Produt
                       Having sum(pk.Qtd_Saldo) < @QtdFra)
            begin
              -- seleciona 1 endereço do depósito
              Select top 1
                     @CodLot = dp.Cod_Lote, 
                     @CodDep  = dp.Cod_Dep,
                     @NumRua  = dp.Num_Rua, 
                     @NumCol  = dp.Num_Col,
                     @NumNiv  = dp.Num_Niv, 
                     @NumApt  = dp.Num_Apt, 
                     @QtdEmbFecCal = dp.C_QtdEmbFec, 
                     @SldPra = dp.Qtd_SldPra, 
                     @SldDep = dp.Qtd_SldDep
                From PRLOT pk
                     cross apply (Select top 1 
                                         lt.Cod_Lote, lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt, 
                                         lt.C_QtdEmbFec, lt.Qtd_SldPra, lt.Qtd_SldDep
                                    From PRLTL lt
                                   Where lt.Cod_Estabe = pk.Cod_Estabe
                                     And lt.Cod_Produt = pk.Cod_Produt
                                     And IsNull(lt.Qtd_Saldo,0) > 0
                                     And IsNull(lt.C_QtdEmbFec,0) > 0 
                                     And IsNull(lt.Qtd_Saldo,0) >= IsNull(lt.C_QtdEmbFec,0) 
                                     And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
                                   Order by lt.Dat_Vencim, lt.Num_Rua, lt.Num_Niv, lt.Num_Apt, lt.Num_Col, lt.Cod_Lote, lt.Dat_Entrada) dp
               Where pk.Cod_Estabe = @CodEstabe 
                 And pk.Cod_Produt = @CodPrd
                 And pk.Qtd_Saldo < @QtdFra
   
              if (@SldPra < @QtdEmbFecCal) and
                 (@SldDep < @QtdEmbFecCal)
                Break
   
              -- dá saída em PRLTL
              if @SldDep > 0
                Update PRLTL
                   Set Qtd_FisDep = IsNull(Qtd_FisDep,0) - @QtdEmbFecCal
                 Where Cod_Estabe = @CodEstabe 
                   And Cod_Produt = @CodPrd
                   And Cod_Lote = @CodLot
                   And Cod_Dep = @CodDep
                   And Num_Rua = @NumRua
                   And Num_Col = @NumCol
                   And Num_Niv = @NumNiv
                   And Num_Apt = @NumApt
              else
              if @SldPra > 0
                Update PRLTL
                   Set Qtd_FisPra = IsNull(Qtd_FisPra,0) - @QtdEmbFecCal
                 Where Cod_Estabe = @CodEstabe 
                   And Cod_Produt = @CodPrd
                   And Cod_Lote = @CodLot
                   And Cod_Dep = @CodDep
                   And Num_Rua = @NumRua
                   And Num_Col = @NumCol
                   And Num_Niv = @NumNiv
                   And Num_Apt = @NumApt
   
              -- dá entrada em PRLOT
              Update PRLOT
                 Set Qtd_FisPra = IsNull(Qtd_FisPra,0) + @QtdEmbFecCal
               Where Cod_Estabe = @CodEstabe 
                 And Cod_Produt = @CodPrd
                 And Cod_Lote = @CodLot
                 And Cod_Dep = @CodDep
            end  -- While Exists(
        end  -- if @QtdFra > 0
   
      Declare PRLTL_Cr Cursor Local Fast_Forward For 
        Select lt.Cod_Lote, lt.Cod_Dep, 0 as Num_Rua, 0 as Num_Col, 0 as Num_Niv, 0 as Num_Apt, 
               1 as C_QtdEmbFec, lt.Qtd_SldPra, lt.Qtd_SldDep
          From PRLOT lt
         Where lt.Cod_Estabe = @CodEstabe 
           And lt.Cod_Produt = @CodPrd
           And IsNull(lt.Qtd_Saldo,0) > 0
         Order by lt.Dat_Vencim, lt.Cod_Lote, lt.Dat_Entrada
   
      Open PRLTL_Cr
      Fetch Next From PRLTL_Cr Into @CodLot, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, 
                                    @QtdEmbFecCal, @SldPra, @SldDep 
      While @@FETCH_STATUS = 0
        begin
          -- dar saída em Dep
          if @QtdFra > 0
            begin
              Set @QtdUndLot = Case 
                                 When @SldDep < @QtdFra Then @SldDep
                                 Else @QtdFra
                               End
   
              if Exists(Select 1 From PRLOT
                         Where Cod_Estabe = @CodEstabe 
                           And Cod_Produt = @CodPrd
                           And Cod_Lote = @CodLot
                           And Cod_Dep = @CodDep
                           And Qtd_SldDep >= @QtdUndLot
                           And Qtd_FisDep >= @QtdUndLot)
                  begin
                    -- dar saída em PRLOT
                    Update PRLOT
                       Set Qtd_FisDep = IsNull(Qtd_FisDep,0) - @QtdUndLot
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Produt = @CodPrd
                       And Cod_Lote = @CodLot
                       And Cod_Dep = @CodDep
                       And IsNull(Qtd_FisDep,0) >= @QtdUndLot
                    if @@rowcount = 0
                      begin
                        Rollback Transaction
                        Return
                      end
   
                    Set @QtdFra = @QtdFra - @QtdUndLot
                  end
              end -- if @QtdFra > 0
   
   
            -- dar saída em Pra
            if @QtdFra > 0
              begin
                Set @QtdUndLot = Case 
                                   When @SldPra < @QtdFra Then @SldPra
                                   Else @QtdFra
                                 End
   
                if Exists(Select 1 From PRLOT
                           Where Cod_Estabe = @CodEstabe 
                             And Cod_Produt = @CodPrd
                             And Cod_Lote = @CodLot
                             And Cod_Dep = @CodDep
                             And Qtd_SldPra >= @QtdUndLot
                             And Qtd_FisPra >= @QtdUndLot)
                  begin
                    -- dar saída em PRLOT
                    Update PRLOT
                       Set Qtd_FisPra = IsNull(Qtd_FisPra,0) - @QtdUndLot
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Produt = @CodPrd
                       And Cod_Lote = @CodLot
                       And Cod_Dep = @CodDep
                       And IsNull(Qtd_FisPra,0) >= @QtdUndLot
                    if @@rowcount = 0
                      begin
                        Rollback Transaction
                        Return
                      end
   
                    Set @QtdFra = @QtdFra - @QtdUndLot
                  end
              end -- if @QtdFra > 0
   
          Fetch Next From PRLTL_Cr Into @CodLot, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, 
                                        @QtdEmbFecCal, @SldPra, @SldDep 
        end
   
      Close PRLTL_Cr
      Deallocate PRLTL_Cr

      Fetch Next From PRODU_Cr Into @CodPrd, @QtdTotSai
    end  -- While @@FETCH_STATUS = 0
          
  Close PRODU_Cr
  Deallocate PRODU_Cr
        
  Commit Transaction
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_InventarioProcessaEstoque]
@CodEstabe int,
@NumSeqBal int,
@CodMveEnt int = 12,
@CodMveSai int = 22,
@Login varchar(15) 

AS

SET NOCOUNT ON
SET ANSI_WARNINGS OFF

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

-- ESTOQUES DE PRODUTOS RESERVADOS, AVARIADOS e SOLICITADOS POR PEDIDOS NAO SAO CONSIDERADOS

Declare @WNumCtg int,
        @WFlgOk bit,
        @WMsgErr varchar(60) ,
        @WTipMveEnt varchar(1),
        @WTipMveSai varchar(1),
        @WMaxDatMov smalldatetime,
        @WCodDep smallint,
        @WCodPrd int

-- verifica data da ultima movimentacao em PRSLD
Set @WMaxDatMov = (Select max(Dat_Movime) From PRSLD Where Cod_Estabe = @CodEstabe)

-- verifica codigos de movimentacao                 
Set @WTipMveEnt = (Select Tip_Movimento From TPMVE  Where Codigo = @CodMveEnt) 
Set @WTipMveSai = (Select Tip_Movimento From TPMVE  Where Codigo = @CodMveSai) 
-- tem que existir a 1a. contagem
Set @WNumCtg = (Select distinct top 1 Num_Contag From BALIT Where Cod_Estabe = @CodEstabe And Num_SeqBal = @NumSeqBal Order by Num_Contag)

if @Date < @WMaxDatMov
  RAISERROR('Existe(m) registro(s) de movimento(s) com data superior à data do processamento',16,1)
else
if @WTipMveEnt <> 'E'
  RAISERROR('Código de movimentação de entrada inválida',16,1)
else
if @WTipMveSai <> 'S'
  RAISERROR('Código de movimentação de saída inválida',16,1)
else
if @WNumCtg <> 1
  RAISERROR('Existe Contagem inválida',16,1)
else
  begin
    -- normaliza BALIT    
    Update BALIT
       Set Cod_MovEst = 0,
           Qtd_Acerto = 0,
           Qtd_EstPra = 0, 
           Qtd_EstDep = 0,
           Tip_Movim = ''
     Where Cod_Estabe = @CodEstabe 
       And Num_SeqBal = @NumSeqBal 
       And IsNull(Flg_Proces,0) = 0
    
    Set @WFlgOk = 1
    Set @WMsgErr = ''
    Set @WNumCtg = (Select Max(Num_Contag) From BALIT Where Cod_Estabe = @CodEstabe And Num_SeqBal = @NumSeqBal)

    if @WNumCtg > 1
      begin
        -- se existem mais de 1 contagem verificar diferencas entre contagem 1 e outras
        -- itens com contagens diferentes
        if Exists(Select b1.Cod_Produt, b1.Cod_Lote, 
                         b1.Cod_Dep, b1.Num_Rua, b1.Num_Col, b1.Num_Niv, b1.Num_Apt
                    From BALIT b1
                   Where b1.Cod_Estabe = @CodEstabe 
                     And b1.Num_SeqBal = @NumSeqBal 
                     And b1.Num_Contag = 1
                     And b1.Cod_Local = 1
                     And IsNull(b1.Flg_Proces,0) = 0
                     And b1.Qtd_Produt <> (Select Qtd_Produt
                                             From BALIT 
                                            Where Cod_Estabe = @CodEstabe 
                                              And Num_SeqBal = @NumSeqBal 
                                              And Cod_Produt = b1.Cod_Produt
                                              And Cod_Lote = b1.Cod_Lote
                                              And Cod_Dep = b1.Cod_Dep
                                              And Num_Rua =  b1.Num_Rua
                                              And Num_Col = b1.Num_Col
                                              And Num_Niv = b1.Num_Niv
                                              And Num_Apt =  b1.Num_Apt
                                              And Cod_Local = b1.Cod_Local
                                              And Num_Contag = 2))
          begin
            Set @WFlgOk = 0
            Set @WMsgErr = 'Inconsistência(s) entre contagens 1 e 2)'
          end

        -- itens com lotes em 1 não existem em 2
        if @WFlgOk = 1	
          if Exists(Select b1.Cod_Produt, b1.Cod_Lote,
                           b1.Cod_Dep, b1.Num_Rua, b1.Num_Col, b1.Num_Niv, b1.Num_Apt
                      From BALIT b1 Left Outer Join
                           BALIT b2 on (b1.Cod_Estabe = b2.Cod_Estabe and b1.Num_SeqBal = b2.Num_SeqBal and
                                        b1.Cod_Produt = b2.Cod_Produt and b1.Cod_Lote = b2.Cod_Lote and
                                        b1.Cod_Dep = b2.Cod_Dep and b1.Num_Rua = b2.Num_Rua and 
                                        b1.Num_Col = b2.Num_Col and b1.Num_Niv = b2.Num_Niv and 
                                        b1.Num_Apt = b2.Num_Apt and b1.Cod_Local = b2.Cod_Local and
                                        b2.Num_Contag = 2)
                     Where b1.Cod_Estabe = @CodEstabe 
                       And b1.Num_SeqBal = @NumSeqBal 
                       And b1.Num_Contag = 1
                       And b1.Cod_Local = 1
                       And IsNull(b1.Flg_Proces,0) = 0
                       And b2.Cod_Produt is null)
            begin
              Set @WFlgOk = 0
              Set @WMsgErr = 'Falta(m) iten(s)/lote(s) na contagem 2'
            end

        -- itens com lotes em 2 não existem em 1
        if @WFlgOk = 1
          if Exists(Select b2.Cod_Produt, b2.Cod_Lote,
                           b2.Cod_Dep, b2.Num_Rua, b2.Num_Col, b2.Num_Niv, b2.Num_Apt
                      From BALIT b2 Left Outer Join
                           BALIT b1 on (b2.Cod_Estabe = b1.Cod_Estabe and b2.Num_SeqBal = b1.Num_SeqBal and
                                        b2.Cod_Produt = b1.Cod_Produt and b2.Cod_Lote = b1.Cod_Lote and
                                        b2.Cod_Dep = b1.Cod_Dep and b2.Num_Rua = b1.Num_Rua and 
                                        b2.Num_Col = b1.Num_Col and b2.Num_Niv = b1.Num_Niv and 
                                        b2.Num_Apt = b1.Num_Apt and b2.Cod_Local = b1.Cod_Local and
                                        b1.Num_Contag = 1 and b1.Cod_Local = 1 and IsNull(b1.Flg_Proces,0) = 0)
                     Where b2.Cod_Estabe = @CodEstabe 
                       And b2.Num_SeqBal = @NumSeqBal 
                       And b2.Num_Contag = 2
                       And b2.Cod_Local = 1
                       And b1.Cod_Produt is null)
            begin
              Set @WFlgOk = 0
              Set @WMsgErr = 'Falta(m) iten(s) na contagem 1'
            end

      end   -- if @WNumCtg > 1
   
    -- verifica DIVERGENCIAS DE ESTOQUES
    if @WFlgOk = 1    
      begin
        -- Normaliza datas em BALIT
        Update l1
           Set l1.Dat_VctLot = l2.Dat_Vencim,
               l1.Dat_Fabric = l2.Dat_Fabric
          From BALIT l1 Inner Join
               (Select Cod_Estabe, Cod_Produt, Cod_Lote, Dat_Vencim = max(Dat_VctLot), Dat_Fabric = max(Dat_Fabric)
                  From BALIT
                 Where Cod_Estabe = @CodEstabe
                   And Num_SeqBal = @NumSeqBal
                 Group by Cod_Estabe, Cod_Produt, Cod_Lote) l2 on l1.Cod_Estabe = l2.Cod_Estabe 
                                                              and l1.Cod_Produt = l2.Cod_Produt and l1.Cod_Lote = l2.Cod_Lote
         Where l1.Cod_Estabe = @CodEstabe 
           And l1.Num_SeqBal = @NumSeqBal
           And ((IsNull(l1.Dat_VctLot,0) <> IsNull(l2.Dat_Vencim,0)) or 
                (IsNull(l1.Dat_Fabric,0) <> IsNull(l2.Dat_Fabric,0)))       
        
        Update l1
           Set l1.Dat_VctLot = l2.Dat_Vencim,
               l1.Dat_Fabric = l2.Dat_Fabric
          From BALIT l1, PRLOT l2
         Where l1.Cod_Estabe = l2.Cod_Estabe
           And l1.Cod_Dep = l2.Cod_Dep
           And l1.Cod_Produt = l2.Cod_Produt
           And l1.Cod_Lote = l2.Cod_Lote
           And l1.Cod_Estabe = @CodEstabe 
           And l1.Num_SeqBal = @NumSeqBal
           And ((IsNull(l1.Dat_VctLot,0) <> IsNull(l2.Dat_Vencim,0)) or
                (IsNull(l1.Dat_Fabric,0) <> IsNull(l2.Dat_Fabric,0)))

        -- Normaliza PRLOT, PRLTL
        Update PRLOT
           Set Qtd_FisPra = 0
         Where Cod_Estabe = @CodEstabe  
           And ((Qtd_FisPra < 0) or (Qtd_FisPra is null))

        Update PRLOT
           Set Qtd_FisDep = 0
         Where Cod_Estabe = @CodEstabe  
           And ((Qtd_FisDep < 0) or (Qtd_FisDep is null))
      
        Update PRLTL
           Set Qtd_FisPra = 0
         Where Cod_Estabe = @CodEstabe  
           And ((Qtd_FisPra < 0) or (Qtd_FisPra is null))

        Update PRLTL
           Set Qtd_FisDep = 0
         Where Cod_Estabe = @CodEstabe  
           And ((Qtd_FisDep < 0) or (Qtd_FisDep is null))
       
        -- elimina lotes diferentes do mesmo produto no mesmo endereço (procura deixar pelo menos 1) 
        Delete lt
          From PRLTL lt Inner Join
               (Select Cod_Estabe, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_Produt, DatVct = MAX(Dat_Vencim), qtd = COUNT(*)
                  From PRLTL
                 Where Cod_Estabe = @CodEstabe
                 Group by Cod_Estabe, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_Produt
                Having COUNT(*) > 1) x on (lt.Cod_Estabe = x.Cod_Estabe and 
                                           lt.Cod_Dep = x.Cod_Dep and lt.Num_Rua = x.Num_Rua and 
                                           lt.Num_Col = x.Num_Col and lt.Num_Niv = x.Num_Niv and 
                                           lt.Num_Apt = x.Num_Apt and lt.Cod_Produt = x.Cod_produt)
         Where lt.Cod_Estabe = @CodEstabe                                 
           And lt.Qtd_Fisico = 0 
           and lt.Dat_Vencim < x.DatVct
      end

    -- verifica itens com depositos invalidos  
    if @WFlgOk = 1
      if Exists(Select it.Cod_Dep, it.Cod_Produt
                  From BALIT it Inner Join
                       BALCB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Num_SeqBal = cb.Num_SeqBal
                 Where it.Cod_Estabe = @CodEstabe
                   And it.Num_SeqBal = @NumSeqBal
                   And it.Num_Contag = 1
                   And it.Cod_Local = 1
                   And IsNull(it.Flg_Proces,0) = 0
                   And IsNull(it.Cod_Dep,0) <> IsNull(cb.Cod_Dep,0))
      begin          
        Set @WFlgOk = 0
        Set @WMsgErr = 'Existem itens inventariados de outros depósitos'
      end  

    -- verifica produtos sem endereços Picking  
    if @WFlgOk = 1
      if Exists(Select it.Cod_Dep, it.Cod_Produt,
                       QtdBal = IsNull(it.Qtd_Produt,0),
                       FlgAutDiv = IsNull(Flg_AutDiv,0),
                       QtdSldTot = IsNull(lt.Qtd_SldPra,0)+IsNull(lt.Qtd_SldDep,0),
                       dp.Cod_Produt, dp.Num_Rua, dp.Num_Col, dp.Num_Niv, dp.Num_Apt
                  From BALIT it Inner Join
                       PRLTL lt on (it.Cod_Estabe = lt.Cod_Estabe and 
                                    it.Cod_Produt = lt.Cod_Produt and it.Cod_Lote = lt.Cod_Lote and 
                                    it.Cod_Dep = lt.Cod_Dep and it.Num_Rua = lt.Num_Rua and it.Num_Col = lt.Num_Col and 
                                    it.Num_Niv = lt.Num_Niv and it.Num_Apt = lt.Num_Apt) Left Outer Join
                       DPXPR dp on it.Cod_Estabe = dp.Cod_Estabe and it.Cod_Dep = dp.Cod_Dep and it.Cod_Produt = dp.Cod_Produt              
                 Where it.Cod_Estabe = @CodEstabe
                   And it.Num_SeqBal = @NumSeqBal
                   And it.Num_Contag = 1
                   And it.Cod_Local = 1
                   And IsNull(it.Flg_Proces,0) = 0
                   -- itens com acerto de saida
                   And (IsNull(lt.Qtd_SldPra,0)+IsNull(lt.Qtd_SldDep,0)) > IsNull(it.Qtd_Produt,0)
                   and IsNull(Flg_AutDiv,0) = 1
                   And dp.Cod_Produt is null)
      begin          
        Set @WFlgOk = 0
        
        Select top 1 @WCodDep = it.Cod_Dep, 
                     @WCodPrd = it.Cod_Produt
                From BALIT it Inner Join
                     PRLTL lt on (it.Cod_Estabe = lt.Cod_Estabe and 
                                  it.Cod_Produt = lt.Cod_Produt and it.Cod_Lote = lt.Cod_Lote and 
                                  it.Cod_Dep = lt.Cod_Dep and it.Num_Rua = lt.Num_Rua and it.Num_Col = lt.Num_Col and 
                                  it.Num_Niv = lt.Num_Niv and it.Num_Apt = lt.Num_Apt) Left Outer Join
                     DPXPR dp on it.Cod_Estabe = dp.Cod_Estabe and it.Cod_Dep = dp.Cod_Dep and it.Cod_Produt = dp.Cod_Produt              
               Where it.Cod_Estabe = @CodEstabe
                 And it.Num_SeqBal = @NumSeqBal
                 And it.Num_Contag = 1
                 And it.Cod_Local = 1
                 And IsNull(it.Flg_Proces,0) = 0
                 -- itens com acerto de saida
                 And (IsNull(lt.Qtd_SldPra,0)+IsNull(lt.Qtd_SldDep,0)) > IsNull(it.Qtd_Produt,0)
                 and IsNull(Flg_AutDiv,0) = 1
                 And dp.Cod_Produt is null        
        
        Set @WMsgErr = 'Produto('+cast(@WCodPrd as varchar)+') s/ender.Picking dep.('+cast(@WCodDep as varchar)+')'
      end  
      
    if @WFlgOk = 0
      RAISERROR(@WMsgErr,16,1)
    else
      begin
        Begin Transaction
          Declare @CodPrd int,
                  @CodLot varchar(20),
                  @QtdBal int,
                  @DatVct smalldatetime,
                  @DatFab smalldatetime,
                  @CodDep smallint,
                  @NumRua smallint,
                  @NumCol smallint,
                  @NumNiv smallint,
                  @NumApt smallint,
                  @QtdEmbFec int,
                  @NumPag int,
                  @NumSeqIte int,
                  @FlgAutDiv bit,
                  @SldPra int,
                  @SldDep int,
                  @WQtdSldTot int,
                  @WQtdDif int,
                  @WQtdMov int,
                  @WQtdPra int,
                  @WQtdDep int,
                  @WFlgEstFis bit,
                  @WNumRuaPck smallint,
                  @WNumColPck smallint,
                  @WNumNivPck smallint,
                  @WNumAptPck smallint,
                  @WCodOri varchar(20),
                  @WCodAcr int,
                  @QtdSldAntPra int,
                  @QtdSldAntDep int,
                  @WQtdMovPra int,
                  @WQtdMovDep int

          -- antes de processar tenta corrigir algum estoque inconsistente em PRXES
          Set @CodPrd = 0
          while Exists(Select top 1 b.Cod_Produt 
                         From BALIT b
                              inner join PRXES p on b.Cod_Estabe = p.Cod_Estabe and b.Cod_Produt = p.Cod_Produt
                        Where b.Cod_Estabe = @CodEstabe 
                          And b.Num_SeqBal = @NumSeqBal 
                          And b.Num_Contag = 1
                          And b.Cod_Local = 1
                          And IsNull(b.Flg_Proces,0) = 0
                          And b.Cod_Produt > @CodPrd
                          And p.Qtd_Fisico <> dbo.FN_EstoqueFisicoPrdLote(p.Cod_Estabe,p.Cod_Produt,'TODOS')
                        Order by b.Cod_Produt)
            begin
              Select top 1 @CodPrd = b.Cod_Produt 
                From BALIT b
                     inner join PRXES p on b.Cod_Estabe = p.Cod_Estabe and b.Cod_Produt = p.Cod_Produt
               Where b.Cod_Estabe = @CodEstabe 
                 And b.Num_SeqBal = @NumSeqBal 
                 And b.Num_Contag = 1
                 And b.Cod_Local = 1
                 And IsNull(b.Flg_Proces,0) = 0
                 And b.Cod_Produt > @CodPrd
                 And p.Qtd_Fisico <> dbo.FN_EstoqueFisicoPrdLote(p.Cod_Estabe,p.Cod_Produt,'TODOS')
               Order by b.Cod_Produt

              Exec PR_CorrigeEstoqueProdut @CodEstabe, @CodPrd
              if @@error <> 0
                begin
                  Rollback Transaction
                  Return
                end
            end


          -- verifica se for implantacao de estoque (fiscal)
          Set @WFlgEstFis = 0  

          if not Exists(Select top 1 Cod_Produt From PRXES Where Cod_Estabe = @CodEstabe And Qtd_Dispon > 0)
            Set @WFlgEstFis = 1  -- estoque fiscal
         
          if (@WFlgEstFis = 0) and ((Select IsNull(FlgAlerta,0) From PARAM Where Cod_Estabe = @CodEstabe) = 1)
            Set @WFlgEstFis = 1  -- estoque fiscal

          -- inclui registros em BALIT de lotes que serao zerados (lotes iniciais que foram alterados na "digitação") 
          Insert Into BALIT (Cod_Estabe, Num_SeqBal, Cod_Produt, Cod_Lote, Cod_Local, Num_Contag, Cod_MovEst,
                             Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Dat_VctLot, Dat_Fabric,
                             Qtd_Produt, Flg_AutDiv, Cod_LoteOri, Num_Pagina, Num_SeqIte) 
             Select distinct Cod_Estabe, Num_SeqBal, Cod_Produt, Cod_LoteOri, 1, 1, @CodMveSai, 
                             Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Dat_VctLot, Dat_Fabric,
                             0, Flg_AutDiv, Cod_LoteOri, Num_Pagina, 
                             IsNull((Select max(Num_SeqIte) From BALIT Where Cod_Estabe = @CodEstabe And Num_SeqBal = @NumSeqBal),0)+1 
               From BALIT
              Where Cod_Estabe = @CodEstabe
                And Num_SeqBal = @NumSeqBal
                And Num_Contag = 1
                And Cod_Local = 1
                And IsNull(Flg_Proces,0) = 0
                And (ISNull(Cod_Lote,'') <> IsNull(Cod_LoteOri,'') And IsNull(Cod_LoteOri,'') <> '') -- DMD-7196 
                And IsNull(Flg_AutDiv,0) = 1
          if (@@error <> 0)
            begin
              Rollback Transaction
              Return
            end

------------------------------  D E P O S I T O --------------------------------------------------------------------            
          if Exists(Select Num_SeqBal
                      From BALCB
                     Where Cod_Estabe = @CodEstabe
                       And Num_SeqBal = @NumSeqBal
                       And IsNull(Flg_Proces,0) = 0
                       And Tip_Balanc = 'D') 
            begin
              -- inclui itens de BALIT com lotes inexistentes em PRLTL
              Insert into PRLTL (Cod_Estabe, Cod_Produt, Cod_Lote, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, 
                                 Qtd_EmbFec, Dat_Vencim, Dat_Fabric, Qtd_FisPra, Qtd_SolPra, Qtd_FisDep, Qtd_SolDep)
                Select distinct b.Cod_Estabe, b.Cod_Produt, b.Cod_Lote, b.Cod_Dep, b.Num_Rua, b.Num_Col, b.Num_Niv, b.Num_Apt,  
                                b.Qtd_EmbFec, b.Dat_VctLot, b.Dat_Fabric, 0, 0, 0, 0
                  From BALIT b Left Outer Join
                       PRLTL l on (b.Cod_Estabe = l.Cod_Estabe and 
                                   b.Cod_Produt = l.Cod_Produt and b.Cod_Lote = l.Cod_Lote and 
                                   b.Cod_Dep = l.Cod_Dep and b.Num_Rua = l.Num_Rua and b.Num_Col = l.Num_Col and 
                                   b.Num_Niv = l.Num_Niv and b.Num_Apt = l.Num_Apt)
                 Where b.Cod_Estabe = @CodEstabe 
                   And b.Num_SeqBal = @NumSeqBal 
                   And b.Num_Contag = 1
                   And b.Cod_Local = 1
                   And IsNull(b.Flg_Proces,0) = 0
                   And l.Cod_Produt is null
              if (@@error <> 0)
                begin
                  Rollback Transaction
                  Return
                end

              -- atualiza estoque disponivel atual de PRLTL em BALIT
              Update it
                 Set it.Qtd_SldEst = IsNull(lt.Qtd_SldPra,0)+IsNull(lt.Qtd_SldDep,0) 
                From BALIT it Inner Join
                     PRLTL lt on (it.Cod_Estabe = lt.Cod_Estabe and 
                                  it.Cod_Produt = lt.Cod_Produt and it.Cod_Lote = lt.Cod_Lote and 
                                  it.Cod_Dep = lt.Cod_Dep and it.Num_Rua = lt.Num_Rua and it.Num_Col = lt.Num_Col and 
                                  it.Num_Niv = lt.Num_Niv and it.Num_Apt = lt.Num_Apt)
               Where it.Cod_Estabe = @CodEstabe
                 And it.Num_SeqBal = @NumSeqBal
                 And it.Num_Contag = 1
                 And it.Cod_Local = 1
                 And IsNull(it.Flg_Proces,0) = 0
            
              Declare BALIT_Cr Cursor Local For 
                Select it.Cod_Produt, it.Cod_Lote, it.Qtd_Produt, it.Dat_VctLot, it.Dat_Fabric,
                       it.Cod_Dep, it.Num_Rua, it.Num_Col, it.Num_Niv, it.Num_Apt, it.Qtd_EmbFec,
                       it.Num_Pagina, it.Num_SeqIte, IsNull(Flg_AutDiv,0),
                       IsNull(lt.Qtd_SldPra,0), IsNull(lt.Qtd_SldDep,0) 
                  From BALIT it Inner Join
                       PRLTL lt on (it.Cod_Estabe = lt.Cod_Estabe and 
                                    it.Cod_Produt = lt.Cod_Produt and it.Cod_Lote = lt.Cod_Lote and 
                                    it.Cod_Dep = lt.Cod_Dep and it.Num_Rua = lt.Num_Rua and it.Num_Col = lt.Num_Col and 
                                    it.Num_Niv = lt.Num_Niv and it.Num_Apt = lt.Num_Apt)
                 Where it.Cod_Estabe = @CodEstabe
                   And it.Num_SeqBal = @NumSeqBal
                   And it.Num_Contag = 1
                   And it.Cod_Local = 1
                   And IsNull(it.Flg_Proces,0) = 0
                      
              Open BALIT_Cr
              Fetch Next From BALIT_Cr Into @CodPrd, @CodLot, @QtdBal, @DatVct, @DatFab,
                                            @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @QtdEmbFec,
                                            @NumPag, @NumSeqIte, @FlgAutDiv,
                                            @SldPra, @SldDep
              While @@FETCH_STATUS = 0
                begin
                  Set @WQtdSldTot = @SldPra + @SldDep
                  
                  if @QtdBal = @WQtdSldTot
                    begin
                      Update BALIT
                         Set Flg_Proces = 1,
                             Tip_Movim = 'X',
                             Cod_MovEst = 0,
                             Qtd_Acerto = 0,
                             Qtd_EstPra = 0, 
                             Qtd_EstDep = 0,
                             Transacao = @Now
                       Where Cod_Estabe = @CodEstabe
                         And Num_SeqBal = @NumSeqBal
                         And Cod_Produt = @CodPrd
                         And Cod_Lote = @CodLot
                         And Num_Contag = 1
                         And Cod_Local = 1
                         And Cod_Dep = @CodDep
                         And Num_Rua = @NumRua
                         And Num_Col = @NumCol
                         And Num_Niv = @NumNiv
                         And Num_Apt = @NumApt 

                      Update PRLTL
                         Set Dat_Vencim = @DatVct,
                             Dat_Fabric = @DatFab,
                             Qtd_EmbFec = @QtdEmbFec
                       Where Cod_Estabe = @CodEstabe      
                         And Cod_Produt = @CodPrd And Cod_Lote = @CodLot
                         And Cod_Dep = @CodDep And Num_Rua = @NumRua
                         And Num_Col = @NumCol And Num_Niv = @NumNiv
                         And Num_Apt = @NumApt
                         And ((Dat_Vencim <> @DatVct) or 					  
                              (Dat_Fabric <> @DatFab) or 					  
                              (Qtd_EmbFec <> @QtdEmbFec))
                    end
                    
                  -- poe endereco picking na memoria
                  Set @WNumRuaPck = 0
                  Select @WNumRuaPck = Num_Rua, 
                         @WNumColPck = Num_Col, 
                         @WNumNivPck = Num_Niv, 
                         @WNumAptPck = Num_Apt 
                    From DPXPR
                   Where Cod_Estabe = @CodEstabe 
                     And Cod_Dep = @CodDep
                     And Cod_Produt = @CodPrd

                  -- DAR SAIDA NO ESTOQUE (1)
                  if (@WQtdSldTot > @QtdBal) and (@FlgAutDiv = 1)
                    begin
                      if @WNumRuaPck = 0
                        begin
                          Set @WMsgErr = 'Produto('+cast(@CodPrd as varchar)+') s/ender.Picking dep.('+cast(@CodDep as varchar)+')'
                          RAISERROR(@WMsgErr,16,1)
                          Rollback Transaction
                          Return
                        end
                    
                      Set @WQtdDif = @WQtdSldTot - @QtdBal
                      Set @WQtdPra = 0
                      Set @WQtdDep = 0

                      if (@WQtdDif > 0) and (@SldDep > 0)
                        begin
                          Set @WQtdDep = Case 
                                           when @SldDep >= @WQtdDif then @WQtdDif 
                                           else @SldDep 
                                         End
			              Set @WQtdDif = @WQtdDif - @WQtdDep   
                        end
                      
                      if (@WQtdDif > 0) and (@SldPra > 0)
                        begin
                          Set @WQtdPra = Case 
                                           when @SldPra >= @WQtdDif then @WQtdDif 
                                           else @SldPra 
                                         End
                          Set @WQtdDif = @WQtdDif - @WQtdPra   
                        end
                        
                      -- transferencia de saida do deposito
                      Update PRLTL
                         Set Qtd_FisPra = Qtd_FisPra - @WQtdPra,
                             Qtd_FisDep = Qtd_FisDep - @WQtdDep,
                             Dat_Vencim = @DatVct,
                             Dat_Fabric = @DatFab,
                             Qtd_EmbFec = @QtdEmbFec
                       Where Cod_Estabe = @CodEstabe      
                         And Cod_Produt = @CodPrd And Cod_Lote = @CodLot
                         And Cod_Dep = @CodDep And Num_Rua = @NumRua
                         And Num_Col = @NumCol And Num_Niv = @NumNiv
                         And Num_Apt = @NumApt
                         And Qtd_SldPra >= @WQtdPra
                         And Qtd_SldDep >= @WQtdDep
                      if @@ROWCOUNT > 0 
                        begin
                          -- registra log de saida
                          Set @WCodOri = 'TRF_EST'
                          Set @WQtdMov = (@WQtdPra + @WQtdDep) * (-1)
                          Exec PR_InserePRLOG @CodEstabe, @CodPrd, @CodLot, @CodDep, 
                                              @NumRua, @NumCol, @NumNiv, @NumApt,
                                              @WQtdMov, @WCodOri, '', @NumSeqBal, '', '', @Login
                          if @@error <> 0 
                            begin
                              Rollback Transaction
                              Return
                            end 
                            
                          -- da entrada picking  
                          Update PRLOT
                             Set Qtd_FisPra = Qtd_FisPra + @WQtdPra,
                                 Qtd_FisDep = Qtd_FisDep + @WQtdDep                         
                           Where Cod_Estabe = @CodEstabe      
                             And Cod_Dep = @CodDep
                             And Cod_Produt = @CodPrd 
                             And Cod_Lote = @CodLot

                          -- registra transferencia de entrada
                          Set @WQtdMov = @WQtdPra + @WQtdDep
                          Exec PR_InserePRLOG @CodEstabe, @CodPrd, @CodLot, @CodDep, 
                                              @WNumRuaPck, @WNumColPck, @WNumNivPck, @WNumAptPck,
                                              @WQtdMov, @WCodOri, '', @NumSeqBal, '', '', @Login
                          if @@error <> 0 
                            begin
                              Rollback Transaction
                              Return
                            end 

                          -- da saida picking (acerto)   
                          Exec PR_ProxNumero 'Acerto', @WCodAcr output
                          if @@error <> 0
                            begin
                              Rollback Transaction
                              Return
                            end
                  
                          Insert into ACERT (Cod_Estabe, Numero, Dat_Movimento, 
                                             Cod_Produto, Cod_Lote, Dat_Vencimento, Dat_Fabric,
                                             Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt,
                                             Qtd_Acerto, Qtd_AceDep, Cod_TipMov, Num_SeqBal, Flg_NotFis, Historico, Usuario, Transacao)
                                    Values  (@CodEstabe, @WCodAcr, @Date, 
                                             @CodPrd, @CodLot, @DatVct, @DatFab,
                                             @CodDep, @WNumRuaPck, @WNumColPck, @WNumNivPck, @WNumAptPck,
                                             @WQtdPra, @WQtdDep, @CodMveSai, @NumSeqBal, 0, 'BALANCO', @Login, GetDate())
                          if @@error <> 0
                            begin
                              Rollback Transaction
                              Return
                            end

                          Update BALIT
                             Set Flg_Proces = 1,
                                 Tip_Movim = 'S',
                                 Cod_MovEst = @CodMveSai,
                                 Qtd_Acerto = @WQtdPra + @WQtdDep,
                                 Qtd_EstPra = @WQtdPra, 
                                 Qtd_EstDep = @WQtdDep,
                                 Transacao = @Now
                           Where Cod_Estabe = @CodEstabe
                            And Num_SeqBal = @NumSeqBal
                            And Cod_Produt = @CodPrd
                            And Cod_Lote = @CodLot
                            And Num_Contag = 1
                            And Cod_Local = 1
                            And Cod_Dep = @CodDep
                            And Num_Rua = @NumRua
                            And Num_Col = @NumCol
                            And Num_Niv = @NumNiv
                            And Num_Apt = @NumApt 

                        end  -- if @@ROWCOUNT > 0 

                    end  -- if (@WQtdSldTot > @QtdBal) and (@FlgAutDiv = 1)

                  -- DAR ENTRADA NO ESTOQUE (2)
                  if (@QtdBal > @WQtdSldTot) and (@FlgAutDiv = 1)
                    begin
                      if @WNumRuaPck = 0
                        begin
                          Set @WMsgErr = 'Produto('+cast(@CodPrd as varchar)+') s/ender.Picking dep.('+cast(@CodDep as varchar)+')'
                          RAISERROR(@WMsgErr,16,1)
                          Rollback Transaction
                          Return
                        end
                   
                      Set @WQtdDif = @QtdBal - @WQtdSldTot
                      
                      Exec PR_ProxNumero 'Acerto', @WCodAcr output
                      if @@error <> 0
                        begin
                          Rollback Transaction
                          Return
                        end
                    
                      Insert into ACERT (Cod_Estabe, Numero, Dat_Movimento, 
                                         Cod_Produto, Cod_Lote, Dat_Vencimento, Dat_Fabric,
                                         Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt,
                                         Qtd_Acerto, Qtd_AceDep, Cod_TipMov, Num_SeqBal, Flg_NotFis, Historico, Usuario, Transacao)
                                Values  (@CodEstabe, @WCodAcr, @Date, 
                                         @CodPrd, @CodLot, @DatVct, @DatFab,
                                         @CodDep, @WNumRuaPck, @WNumColPck, @WNumNivPck, @WNumAptPck,
                                         @WQtdDif, 0, @CodMveEnt, @NumSeqBal, 0, 'BALANCO', @Login, GetDate())
                      if @@error <> 0
                        begin
                          Rollback Transaction
                          Return
                        end
				    
                      -- transfere picking para deposito
                      Update PRLOT
                         Set Qtd_FisPra = Qtd_FisPra - @WQtdDif
                       Where Cod_Estabe = @CodEstabe  
                         And Cod_Dep = @CodDep
                         And Cod_Produt = @CodPrd 
                         And Cod_Lote = @CodLot
                         And Qtd_SldPra >= @WQtdDif
                      if @@ROWCOUNT > 0
                        begin
                          -- registra log de saida
                          Set @WCodOri = 'TRF_EST'
                          Set @WQtdMov = @WQtdDif * (-1)
                          Exec PR_InserePRLOG @CodEstabe, @CodPrd, @CodLot, @CodDep, 
                                              @WNumRuaPck, @WNumColPck, @WNumNivPck, @WNumAptPck,
                                              @WQtdMov, @WCodOri, '', @NumSeqBal, '', '', @Login
                          if @@error <> 0 
                            begin
                              Rollback Transaction
                              Return
                            end 
                        
                          -- transferencia de entrada
                          Update PRLTL
                             Set Qtd_FisPra = Qtd_FisPra + @WQtdDif,
                                 Dat_Vencim = @DatVct,
                                 Dat_Fabric = @DatFab,
                                 Qtd_EmbFec = @QtdEmbFec
                           Where Cod_Estabe = @CodEstabe      
                             And Cod_Produt = @CodPrd And Cod_Lote = @CodLot
                             And Cod_Dep = @CodDep And Num_Rua = @NumRua
                             And Num_Col = @NumCol And Num_Niv = @NumNiv
                             And Num_Apt = @NumApt
				    
                          -- registra log de entrada
                          Set @WQtdMov = @WQtdDif
                          Exec PR_InserePRLOG @CodEstabe, @CodPrd, @CodLot, @CodDep, 
                                              @NumRua, @NumCol, @NumNiv, @NumApt,
                                              @WQtdMov, @WCodOri, '', @NumSeqBal, '', '', @Login
                          if @@error <> 0 
                            begin
                              Rollback Transaction
                              Return
                            end 
				    
                          Update BALIT
                             Set Flg_Proces = 1,
                                 Tip_Movim = 'E',
                                 Cod_MovEst = @CodMveEnt,
                                 Qtd_Acerto = @WQtdDif,
                                 Qtd_EstPra = @WQtdDif, 
                                 Qtd_EstDep = 0,
                                 Transacao = @Now
                           Where Cod_Estabe = @CodEstabe
                             And Num_SeqBal = @NumSeqBal
                             And Cod_Produt = @CodPrd
                             And Cod_Lote = @CodLot
                             And Num_Contag = 1
                             And Cod_Local = 1
                             And Cod_Dep = @CodDep
                             And Num_Rua = @NumRua
                             And Num_Col = @NumCol
                             And Num_Niv = @NumNiv
                             And Num_Apt = @NumApt 
                        end 
                    end

                  Fetch Next From BALIT_Cr Into @CodPrd, @CodLot, @QtdBal, @DatVct, @DatFab,
                                                @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @QtdEmbFec,
                                                @NumPag, @NumSeqIte, @FlgAutDiv,
                                                @SldPra, @SldDep
                end
              Close BALIT_Cr
              Deallocate BALIT_Cr
              
              -- encerra inventario
              Exec PR_InventarioEncerramento @CodEstabe, @NumSeqBal, @Login 
              if @@error <> 0
                begin
                  Rollback Transaction
                  Return
                end

            end  -- if Exists(
            
          else
          
-------------------------------  P I C K I N G  --------------------------------------------------------------------            
          if Exists(Select Num_SeqBal
                      From BALCB
                     Where Cod_Estabe = @CodEstabe
                       And Num_SeqBal = @NumSeqBal
                       And IsNull(Flg_Proces,0) = 0
                       And Tip_Balanc = 'P') 
            begin
              -- inclui itens de BALIT com lotes inexistentes em PRLOT
              Insert into PRLOT (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Dat_Vencim, Dat_Fabric, Qtd_FisPra, Qtd_SolPra, Qtd_FisDep, Qtd_SolDep)
                Select distinct b.Cod_Estabe, b.Cod_Dep, b.Cod_Produt, b.Cod_Lote, b.Dat_VctLot, b.Dat_Fabric, 0, 0, 0, 0
                  From BALIT b Left Outer Join
                       PRLOT l on (b.Cod_Estabe = l.Cod_Estabe and b.Cod_Dep = l.Cod_Dep and b.Cod_Produt = l.Cod_Produt and b.Cod_Lote = l.Cod_Lote)
                 Where b.Cod_Estabe = @CodEstabe 
                   And b.Num_SeqBal = @NumSeqBal 
                   And b.Num_Contag = 1
                   And b.Cod_Local = 1
                   And IsNull(b.Flg_Proces,0) = 0
                   And l.Cod_Produt is null
              if (@@error <> 0)
                begin
                  Rollback Transaction
                  Return
                end
  
              -- atualiza estoque disponivel atual de PRLOT em BALIT
              Update it
                 Set it.Qtd_SldEst = IsNull(lt.Qtd_SldPra,0)+IsNull(lt.Qtd_SldDep,0) 
                From BALIT it Inner Join
                     PRLOT lt on (it.Cod_Estabe = lt.Cod_Estabe and it.Cod_Dep = lt.Cod_Dep and 
                                  it.Cod_Produt = lt.Cod_Produt and it.Cod_Lote = lt.Cod_Lote)
               Where it.Cod_Estabe = @CodEstabe
                 And it.Num_SeqBal = @NumSeqBal
                 And it.Num_Contag = 1
                 And it.Cod_Local = 1
                 And IsNull(it.Flg_Proces,0) = 0
            
              Declare BALIT_Cr Cursor Local For 
                Select it.Cod_Produt, it.Cod_Lote, it.Qtd_Produt, it.Dat_VctLot, it.Dat_Fabric,
                       it.Cod_Dep, it.Num_Rua, it.Num_Col, it.Num_Niv, it.Num_Apt, it.Qtd_EmbFec,
                       it.Num_Pagina, it.Num_SeqIte, IsNull(Flg_AutDiv,0),
                       IsNull(lt.Qtd_SldPra,0), IsNull(lt.Qtd_SldDep,0) 
                  From BALIT it Inner Join
                       PRLOT lt on (it.Cod_Estabe = lt.Cod_Estabe and it.Cod_Dep = lt.Cod_Dep and 
                                    it.Cod_Produt = lt.Cod_Produt and it.Cod_Lote = lt.Cod_Lote)
                 Where it.Cod_Estabe = @CodEstabe
                   And it.Num_SeqBal = @NumSeqBal
                   And it.Num_Contag = 1
                   And it.Cod_Local = 1
                   And IsNull(it.Flg_Proces,0) = 0
                      
              Open BALIT_Cr
              Fetch Next From BALIT_Cr Into @CodPrd, @CodLot, @QtdBal, @DatVct, @DatFab,
                                            @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @QtdEmbFec,
                                            @NumPag, @NumSeqIte, @FlgAutDiv,
                                            @SldPra, @SldDep
              While @@FETCH_STATUS = 0
                begin
                  Set @WQtdSldTot = @SldPra + @SldDep
                  
                  if @QtdBal = @WQtdSldTot
                    begin
                      Update BALIT
                         Set Flg_Proces = 1,
                             Tip_Movim = 'X',
                             Cod_MovEst = 0,
                             Qtd_Acerto = 0,
                             Qtd_EstPra = 0, 
                             Qtd_EstDep = 0,
                             Transacao = @Now
                       Where Cod_Estabe = @CodEstabe
                         And Num_SeqBal = @NumSeqBal
                         And Cod_Produt = @CodPrd
                         And Cod_Lote = @CodLot
                         And Num_Contag = 1
                         And Cod_Local = 1
                         And Cod_Dep = @CodDep
                         And Num_Rua = @NumRua
                         And Num_Col = @NumCol
                         And Num_Niv = @NumNiv
                         And Num_Apt = @NumApt 
                    end

                  -- DAR SAIDA NO ESTOQUE (1)
                  if (@WQtdSldTot > @QtdBal) and (@FlgAutDiv = 1)
                    begin
                      Set @WQtdDif = @WQtdSldTot - @QtdBal
                      Set @WQtdPra = 0
                      Set @WQtdDep = 0

                      if (@WQtdDif > 0) and (@SldDep > 0)
                        begin
                          Set @WQtdDep = Case 
                                           when @SldDep >= @WQtdDif then @WQtdDif 
                                           else @SldDep 
                                         End
                          Set @WQtdDif = @WQtdDif - @WQtdDep   
                        end
                      
                      if (@WQtdDif > 0) and (@SldPra > 0)
                        begin
                          Set @WQtdPra = Case 
                                           when @SldPra >= @WQtdDif then @WQtdDif 
                                           else @SldPra 
                                         End
                          Set @WQtdDif = @WQtdDif - @WQtdPra   
                        end
                        
                      -- da saida picking (acerto)   
                      if Exists(Select 1 From PRLOT 
                                 Where Cod_Estabe = @CodEstabe 
                                   And Cod_Dep = @CodDep
                                   And Cod_Produt = @CodPrd And Cod_Lote = @CodLot 
                                   And Qtd_SldPra >= @WQtdPra 
                                   And Qtd_SldDep >= @WQtdDep)
                        begin
                          Exec PR_ProxNumero 'Acerto', @WCodAcr output
                          if @@error <> 0
                            begin
                              Rollback Transaction
                              Return
                            end
                  
                          Insert into ACERT (Cod_Estabe, Numero, Dat_Movimento, 
                                             Cod_Produto, Cod_Lote, Dat_Vencimento, Dat_Fabric,
                                             Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt,
                                             Qtd_Acerto, Qtd_AceDep, Cod_TipMov, Num_SeqBal, Flg_NotFis, Historico, Usuario, Transacao)
                                    Values  (@CodEstabe, @WCodAcr, @Date, 
                                             @CodPrd, @CodLot, @DatVct, @DatFab,
                                             @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt,
                                             @WQtdPra, @WQtdDep, @CodMveSai, @NumSeqBal, 0, 'BALANCO', @Login, GetDate())
                          if @@error <> 0
                            begin
                              Rollback Transaction
                              Return
                            end

                          Update BALIT
                             Set Flg_Proces = 1,
                                 Tip_Movim = 'S',
                                 Cod_MovEst = @CodMveSai,
                                 Qtd_Acerto = @WQtdPra + @WQtdDep,
                                 Qtd_EstPra = @WQtdPra, 
                                 Qtd_EstDep = @WQtdDep,
                                 Transacao = @Now
                           Where Cod_Estabe = @CodEstabe
                             And Num_SeqBal = @NumSeqBal
                             And Cod_Produt = @CodPrd
                             And Cod_Lote = @CodLot
                             And Num_Contag = 1
                             And Cod_Local = 1
                             And Cod_Dep = @CodDep
                             And Num_Rua = @NumRua
                             And Num_Col = @NumCol
                             And Num_Niv = @NumNiv
                             And Num_Apt = @NumApt 

                        end  -- if Exists(

                    end  -- if (@WQtdSldTot > @QtdBal) and (@FlgAutDiv = 1)

                  -- DAR ENTRADA NO ESTOQUE (2)
                  if (@QtdBal > @WQtdSldTot) and (@FlgAutDiv = 1)
                    begin
                      Set @WQtdDif = @QtdBal - @WQtdSldTot
                      
                      -- da entrada no picking (acerto) 
                      Exec PR_ProxNumero 'Acerto', @WCodAcr output
                      if @@error <> 0
                        begin
                          Rollback Transaction
                          Return
                        end
                  
                      Insert into ACERT (Cod_Estabe, Numero, Dat_Movimento, 
                                         Cod_Produto, Cod_Lote, Dat_Vencimento, Dat_Fabric,
                                         Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt,
                                         Qtd_Acerto, Qtd_AceDep, Cod_TipMov, Num_SeqBal, Flg_NotFis, Historico, Usuario, Transacao)
                                Values  (@CodEstabe, @WCodAcr, @Date, 
                                         @CodPrd, @CodLot, @DatVct, @DatFab,
                                         @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt,
                                         @WQtdDif, 0, @CodMveEnt, @NumSeqBal, 0, 'BALANCO', @Login, GetDate())
                      if @@error <> 0
                        begin
                          Rollback Transaction
                          Return
                        end

                      Update BALIT
                         Set Flg_Proces = 1,
                             Tip_Movim = 'E',
                             Cod_MovEst = @CodMveEnt,
                             Qtd_Acerto = @WQtdDif,
                             Qtd_EstPra = @WQtdDif, 
                             Qtd_EstDep = 0,
                             Transacao = @Now
                       Where Cod_Estabe = @CodEstabe
                         And Num_SeqBal = @NumSeqBal
                         And Cod_Produt = @CodPrd
                         And Cod_Lote = @CodLot
                         And Num_Contag = 1
                         And Cod_Local = 1
                         And Cod_Dep = @CodDep
                         And Num_Rua = @NumRua
                         And Num_Col = @NumCol
                         And Num_Niv = @NumNiv
                         And Num_Apt = @NumApt 
                    end

                  Fetch Next From BALIT_Cr Into @CodPrd, @CodLot, @QtdBal, @DatVct, @DatFab,
                                                @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @QtdEmbFec,
                                                @NumPag, @NumSeqIte, @FlgAutDiv,
                                                @SldPra, @SldDep
                end
              Close BALIT_Cr
              Deallocate BALIT_Cr
              
              -- encerra inventario
              Exec PR_InventarioEncerramento @CodEstabe, @NumSeqBal, @Login 
              if @@error <> 0
                begin
                  Rollback Transaction
                  Return
                end

            end  -- if Exists(
          

          -- iguala estoque entre PRXES e PRLOT
          -- dá entrada/saída em PRXES em estoques divergentes
          if Exists(Select top 1 b.Cod_Produt 
                      From BALIT b
                           inner join PRXES p on b.Cod_Estabe = p.Cod_Estabe and b.Cod_Produt = p.Cod_Produt
                     Where b.Cod_Estabe = @CodEstabe 
                       And b.Num_SeqBal = @NumSeqBal 
                       And b.Num_Contag = 1
                       And b.Cod_Local = 1
                       And IsNull(b.Flg_Proces,0) = 1
                       And p.Qtd_Fisico <> dbo.FN_EstoqueFisicoPrdLote(p.Cod_Estabe,p.Cod_Produt,'TODOS'))
            begin
              Declare PRSLD_Cr Cursor Local Fast_Forward For 
	     
                Select distinct b.Cod_Produt,
		 	          QtdDif =  p.Qtd_Fisico - dbo.FN_EstoqueFisicoPrdLote(p.Cod_Estabe,p.Cod_Produt,'TODOS')
                  From BALIT b
                       inner join PRXES p on b.Cod_Estabe = p.Cod_Estabe and b.Cod_Produt = p.Cod_Produt
                 Where b.Cod_Estabe = @CodEstabe 
                   And b.Num_SeqBal = @NumSeqBal 
                   And b.Num_Contag = 1
                   And b.Cod_Local = 1
                   And IsNull(b.Flg_Proces,0) = 1
                   And p.Qtd_Fisico <> dbo.FN_EstoqueFisicoPrdLote(p.Cod_Estabe,p.Cod_Produt,'TODOS')	    
		 
              Open PRSLD_Cr
              Fetch Next From PRSLD_Cr Into @CodPrd, @WQtdDif
              While @@FETCH_STATUS = 0
                begin
                  -- pega o ultimo movimento do produto
                  Select top 1 @QtdSldAntPra = IsNull(Qtd_SldPra,0), 
                               @QtdSldAntDep = IsNull(Qtd_SldDep,0)
                    From PRSLD 
                   Where Cod_Estabe = @CodEstabe
                     and Cod_Produt = @CodPrd 
                     and Dat_Movime <= @Date
                   Order By Dat_Movime desc
		 
                  if not Exists(Select Cod_Produt from PRSLD 
                                 Where Cod_Estabe = @CodEstabe and Cod_Produt = @CodPrd and Dat_Movime = @Date)
                    begin
                      Insert into PRSLD (Cod_Estabe, Cod_Produt, Dat_Movime, Qtd_SldPra,    Qtd_SldDep) 
                                 Values (@CodEstabe, @CodPrd,    @Date,      @QtdSldAntPra, @QtdSldAntDep) 
                      if (@@error <> 0)
                        begin
                          Rollback Transaction
                          Return
                        end
                    end
		 
                  -- dá saída em PRXES
                  if @WQtdDif > 0
                    begin
                      -- ver se pode retirar de entradas "manuais"
                      Declare @WQtdExcEnt int = 0
                      Select @WQtdExcEnt = Case
                                             When (IsNull(Qtd_InfEntInv,0) > 0) and (Qtd_EntOut >= Qtd_InfEntInv) then
                                               Case 
                                                 When IsNull(Qtd_InfEntInv,0) > @WQtdDif then @WQtdDif 
                                                 Else Qtd_InfEntInv 
                                               End
                                             Else  0
                                           End
                        From PRSLD
                       Where Cod_Estabe = @CodEstabe
                         and Cod_Produt = @CodPrd
                         and Dat_Movime = @Date
				   
                      if @WQtdExcEnt > 0
                        begin
                          Update PRSLD
                             Set Qtd_EntOut = Qtd_EntOut - @WQtdExcEnt,
                                 Qtd_InfEntInv = Qtd_InfEntInv - @WQtdExcEnt,
                                 @WQtdDif = @WQtdDif - @WQtdExcEnt
                           Where Cod_Estabe = @CodEstabe
                             and Cod_Produt = @CodPrd
                             and Dat_Movime = @Date
                        end


                    -- registra qtd ajustada "manualmente" em PRXES devido inconsistência 
                    if @WQtdDif > 0
                      begin
                        Update PRSLD 
                           Set Qtd_SaiOut = Qtd_SaiOut + @WQtdDif,
                               Qtd_InfSaiInv = IsNull(Qtd_InfSaiInv,0) + @WQtdDif
                         Where Cod_Estabe = @CodEstabe
                           and Cod_Produt = @CodPrd
                           and Dat_Movime = @Date
                      end
		          
                      -- saldos atuais
                      Select @SldPra = Qtd_SldPra, 
                             @SldDep = Qtd_SldDep
                        From PRSLD
                       Where Cod_Estabe = @CodEstabe
                         and Cod_Produt = @CodPrd
                         and Dat_Movime = @Date
		          
                      Set @WQtdMovDep = 0
                      Set @WQtdMovPra = 0
		          
                      -- repõe qtd subtraídas de outras entradas
                      Set @WQtdDif = @WQtdDif + @WQtdExcEnt

                      if (@SldDep > 0) and (@WQtdDif > 0)
                        begin
                          Set @WQtdMovDep = Case 
                                              when @SldDep < @WQtdDif then @SldDep 
                                              else @WQtdDif 
                                            End
                          Set @WQtdDif = @WQtdDif - @WQtdMovDep
                        end
                     
                      if (@SldPra > 0) and (@WQtdDif > 0)
                        begin
                          Set @WQtdMovPra = Case 
                                              when @SldPra < @WQtdDif then @SldPra 
                                              else @WQtdDif 
                                            End
                          Set @WQtdDif = @WQtdDif - @WQtdMovPra
                        end
		          
                      Update PRSLD 
                         Set Qtd_SldDep = Qtd_SldDep - @WQtdMovDep,
                             Qtd_SldPra = Qtd_SldPra - @WQtdMovPra
                       Where Cod_Estabe = @CodEstabe 
                         and Cod_Produt = @CodPrd
                         and Dat_Movime = @Date
		          
                      Update PRXES
                         Set Qtd_Fisico = Qtd_Fisico - @WQtdMovDep - @WQtdMovPra
                       Where Cod_Estabe = @CodEstabe 
                         And Cod_Produt = @CodPrd
		 
                    end  -- if @WQtdDif > 0
		 
                  -- dá entrada em PRXES
                  if @WQtdDif < 0
                    begin
                      Set @WQtdDif = Abs(@WQtdDif)  
		 
                      -- ver se pode retirar de saidas "manuais"
                      Declare @WQtdExcSai int = 0
                      Select @WQtdExcSai = Case
                                             When (IsNull(Qtd_InfSaiInv,0) > 0) and (Qtd_SaiOut >= Qtd_InfSaiInv) then
                                               Case 
                                                 When IsNull(Qtd_InfSaiInv,0) > @WQtdDif then @WQtdDif 
                                                 Else Qtd_InfSaiInv 
                                               End
                                             Else  0
                                           End
                        From PRSLD
                       Where Cod_Estabe = @CodEstabe
                         and Cod_Produt = @CodPrd
                         and Dat_Movime = @Date
			  
                      if @WQtdExcSai > 0
                        begin
                          Update PRSLD
                             Set Qtd_SaiOut = Qtd_SaiOut - @WQtdExcSai,
                                 Qtd_InfSaiInv = Qtd_InfSaiInv - @WQtdExcSai,
                                 @WQtdDif = @WQtdDif - @WQtdExcSai
                           Where Cod_Estabe = @CodEstabe
                             and Cod_Produt = @CodPrd
                             and Dat_Movime = @Date
                        end
			  
			  
                      -- registra qtd ajustada "manualmente" em PRXES devido inconsistência 
                      if @WQtdDif > 0
                        begin
                          Update PRSLD 
                             Set Qtd_EntOut = Qtd_EntOut + @WQtdDif,
                                 Qtd_InfEntInv = IsNull(Qtd_InfEntInv,0) + @WQtdDif
                           Where Cod_Estabe = @CodEstabe
                             and Cod_Produt = @CodPrd
                             and Dat_Movime = @Date
                        end


                      -- repõe qtd subtraídas de outras entradas
                      Set @WQtdDif = @WQtdDif + @WQtdExcSai

                      Update PRSLD 
                         Set Qtd_SldPra = Qtd_SldPra + @WQtdDif
                       Where Cod_Estabe = @CodEstabe 
                         and Cod_Produt = @CodPrd
                         and Dat_Movime = @Date
		          
                      Update PRXES
                         Set Qtd_Fisico = Qtd_Fisico + @WQtdDif
                       Where Cod_Estabe = @CodEstabe 
                         And Cod_Produt = @CodPrd
		 
                    end  -- if @WQtdDif < 0
		 
                  Fetch Next From PRSLD_Cr Into @CodPrd, @WQtdDif
                end
              Close PRSLD_Cr
              Deallocate PRSLD_Cr
            end  -- if Exists(Select top 1 b.Cod_Produto 

        Commit Transaction
      end   
  end
GO

