CREATE VIEW [dbo].[V_CTREC] AS

SELECT ct.Cod_Cliente,
       ct.Cod_Estabe,
	   ct.Num_Documento,
	   ct.Par_Documento,
	   ct.Vlr_Documento,
	   Convert(Varchar,ct.Dat_Emissao,103)    as Dat_Emissao,
       Convert(Varchar,ct.Dat_Emissao,103)    as Dat_Processamento,
	   Convert(VarChar,ct.Dat_Vencimento,103) as Dat_Vencimento,
	   ct.Tip_Documento,
	   ct.Vlr_Saldo,
       ct.Vlr_DescConced,
       ct.Per_Juros,
       ct.Num_Bloqueto,
       ct.Cod_Documento,
       ct.Cod_Vendedor,
	   es.Des_RazSoc                          as Estabelecimento,
	   es.Num_Cnpj,
       Case
         When (IsNull(es.Num_Endere, '') <> '') and (IsNull(es.Cpl_Endere, '') <> '') then
           Rtrim(Ltrim(es.Des_Endere)) + ', ' + Rtrim(Ltrim(es.Num_Endere)) + ', ' + Rtrim(Ltrim(es.Cpl_Endere))
         When (IsNull(es.Num_Endere, '') <> '') then
           Rtrim(Ltrim(es.Des_Endere)) + ', ' + Rtrim(Ltrim(es.Num_Endere))
         When (IsNull(es.Cpl_Endere, '') <> '') then
           Rtrim(Ltrim(es.Des_Endere)) + ', ' + Rtrim(Ltrim(es.Cpl_Endere))
         Else Rtrim(Ltrim(es.Des_Endere))
       End                                    as End_Estab,
	   es.Des_Bairro                          as Bairro_Estab,
	   es.Des_Cidade                          as Cidade_Estab,
	   es.Des_Estado                          as UF_Estab,
	   es.Num_Cep                             as Cep_Estab,
	   cl.Razao_Social                        as Cliente,
	   cl.Cgc_Cpf,
       Case
         When (IsNull(cl.Numero,'') <> '') and (IsNull(cl.Complemento,'') <> '') then
           Rtrim(Ltrim(cl.Endereco))+', '+Rtrim(Ltrim(cl.Numero))+', '+Rtrim(Ltrim(cl.Complemento))
         When (IsNull(cl.Numero,'') <> '') then
           Rtrim(Ltrim(cl.Endereco))+', '+Rtrim(Ltrim(cl.Numero))
         When (IsNull(cl.Complemento,'') <> '') then
           Rtrim(Ltrim(cl.Endereco))+', '+Rtrim(Ltrim(cl.Complemento))
         Else Rtrim(Ltrim(cl.Endereco))
       End                                    as End_Clien,
       IsNull(ba.Descricao, '')               as Bairro_Clien,
       IsNull(ci.Descricao,'')                as Cidade_Clien,
       cl.Cod_Estado                          as UF_Clien,
       cl.Cep                                 as Cep_Clien,
       ag.Cod_Carteira,
       ag.Tipo,
       ag.Cod_Aceite,
       ag.Cod_Agencia,
       ag.Num_Conta,
       ag.Per_MsgBlo1,
       ag.Per_MsgBlo2,
       ag.Per_MsgBlo3,
	   Cod_Barras = ISNULL(ct.Cod_Barra, ''),
	   ct.Cod_Supervisor
FROM CTREC ct
     INNER JOIN ESTAB es ON (es.Cod_Estabe = ct.Cod_Estabe)
     INNER JOIN CLIEN cl ON (cl.Codigo = ct.Cod_Cliente)
     LEFT OUTER JOIN CIDAD ci ON ((cl.Cod_Estado = ci.Cod_Estado) AND (cl.Cod_Cidade = ci.Codigo))
     LEFT OUTER JOIN BAIRR ba ON ((cl.Cod_Estado = ba.Cod_Estado) AND (cl.Cod_Cidade = ba.Cod_Cidade) AND (ba.Codigo = cl.Cod_Bairro))
     LEFT OUTER JOIN AGCOB ag ON (ct.Cod_Agente = ag.Codigo )
WHERE ct.Status = 'A'
AND ct.Cod_Cliente IN (Select cl.Codigo
                       From CLIEN cl
                            Inner Join ENXES es on cl.Cgc_Cpf = es.Num_CgcCpf
                            Inner Join VENDE ve on es.Cod_Vendedor = ve.Codigo
                       Where ve.Flg_Export = 1
                       Union 
                       Select cl2.Codigo
                       From CLXVE c2 
                            Inner Join CLIEN cl2 ON (c2.Cod_Client = cl2.Codigo) 
                            Inner Join VENDE ve2 ON (c2.Cod_Vended = ve2.Codigo) 
                       Where ve2.Flg_Export = 1)
GO

