SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_Reprocessa_ACFOR]
@PCodEstabe int,
@PMes int,
@PAno int

AS

SET NOCOUNT ON

BEGIN TRANSACTION

/*
Notas candidatas: Status = 'C', Status = 'F'
                  Flg_MovEst = 1 ou  Flg_MovEst = 0 e Num_NotSubFat = 0
-- considerar somente Status = 'F' por que as NF canceladas são atualizadas também pela data da emissão não pela data do cancelamento

if Exists(Select top 1 1 From NFSCB 
           Where Cod_Estabe = @PCodEstabe
             And ( (IsNull(Flg_MovEst,0) = 1) or ((IsNull(Flg_MovEst,0) = 0) and (IsNull(Num_NotSubFat,0) = 0)) ) 
             And ( ((Status = 'F') and (YEAR(Dat_Emissao) = @PAno)) or 
	   	           ((Status = 'C') and (YEAR(Dat_Cancelamento) = @PAno)) )
             And ( ((Status = 'F') and (MONTH(Dat_Emissao) = @PMes)) or 
		           ((Status = 'C') and (MONTH(Dat_Cancelamento) = @PMes))) )

ACFOR:  acumulador mensal
*/

-- ACUMULA ACFOR (mensal)

--------------------------------------------------------  SAIDAS  ------------------------------------------------------------------------
-- insere registro de saidas em ACFOR
Insert Into ACFOR (Cod_Estabe, Cod_Fornecedor, Ano_Movimento, Mes_Movimento)
  Select cb.Cod_Estabe, pr.Cod_Fabricante, YEAR(cb.Dat_Emissao), MONTH(Dat_Emissao)
    From NFSCB cb
         Inner Join NFSIT it on (cb.Cod_Estabe = it.Cod_Estabe) and 
                                (cb.Ser_Nota = it.Ser_Nota) and 
                                (cb.Num_Nota = it.Num_Nota)
         Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
         Left  Join ACFOR ac on (cb.Cod_Estabe = ac.Cod_Estabe) and 
                                (pr.Cod_Fabricante = ac.Cod_Fornecedor) and
	                            (YEAR(cb.Dat_Emissao) = ac.Ano_Movimento) and
			                    (MONTH(cb.Dat_Emissao) = ac.Mes_Movimento)
     Where cb.Cod_Estabe = @PCodEstabe
       And IsNull(cb.Flg_MovEst,0) = 1
       And cb.Status = 'F'
       And YEAR(cb.Dat_Emissao) = @PAno
       And MONTH(cb.Dat_Emissao) = @PMes
       And ac.Cod_Estabe is null
     Group by cb.Cod_Estabe, pr.Cod_Fabricante, YEAR(cb.Dat_Emissao), MONTH(cb.Dat_Emissao)

-- itens de venda
Update ac
   Set ac.Qtd_UniVen    = IsNull(iv.QtdMov,0),
       ac.Vlr_LiqPrdVen = IsNull(iv.VlrLiq,0)
  From ACFOR ac 
       Left Join (Select cb.Cod_Estabe, pr.Cod_Fabricante, Ano_Emi = YEAR(cb.Dat_Emissao), Mes_Emi = MONTH(cb.Dat_Emissao), 
                         QtdMov = sum(IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0)),
                         VlrLiq = Case
                                    When sum(IsNull(it.Vlr_LiqVenIte,0)) > 0 then sum(IsNull(it.Vlr_LiqVenIte,0))
                                    Else sum(IsNull(it.Vlr_LiqItem,0)-IsNull(it.Vlr_SubsTrib,0)-IsNull(it.Vlr_SbtRes,0)-IsNull(it.Vlr_RecSbt,0)-IsNull(it.Vlr_SubsTribEmb,0)-
                                             IsNull(it.Vlr_DespRateada,0)-IsNull(it.Vlr_DspExt,0))
                                  End
                    From NFSCB cb
                         Inner Join NFSIT it on (cb.Cod_Estabe = it.Cod_Estabe) and 
                                                (cb.Ser_Nota = it.Ser_Nota) and 
                                                (cb.Num_Nota = it.Num_Nota)
                         Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
                   Where cb.Cod_Estabe = @PCodEstabe
                     And cb.Status = 'F'
                     And cb.Tip_Saida = 'V'
                     And IsNull(cb.Flg_MovEst,0) = 1
                     And YEAR(cb.Dat_Emissao)  = @PAno
                     And MONTH(cb.Dat_Emissao) = @PMes
                   Group by cb.Cod_Estabe, pr.Cod_Fabricante, YEAR(cb.Dat_Emissao), MONTH(cb.Dat_Emissao)) iv on (ac.Cod_Estabe     = iv.Cod_Estabe) and 
                                                                                                                 (ac.Cod_Fornecedor = iv.Cod_Fabricante) and
                                                                                                                 (ac.Ano_Movimento  = iv.Ano_Emi) and
                                                                                                                 (ac.Mes_Movimento  = iv.Mes_Emi)
 Where ac.Cod_Estabe = @PCodEstabe
   And ac.Ano_Movimento = @PAno
   And ac.Mes_Movimento = @PMes
   And ( (IsNull(ac.Qtd_UniVen,0)    <> IsNull(iv.QtdMov,0)) or 
         (IsNull(ac.Vlr_LiqPrdVen,0) <> IsNull(iv.VlrLiq,0)) )

-- itens de devolucao
Update ac
   Set ac.Qtd_UniSaiDev = IsNull(iv.QtdMov,0),
       ac.Vlr_LiqSaiDev = IsNull(iv.VlrLiq,0)
  From ACFOR ac 
       Left Join (Select cb.Cod_Estabe, pr.Cod_Fabricante, Ano_Emi = YEAR(cb.Dat_Emissao), Mes_Emi = MONTH(cb.Dat_Emissao),   
                         QtdMov = sum(IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0)),
                         VlrLiq = Case
                                    When sum(IsNull(it.Vlr_LiqVenIte,0)) > 0 then sum(IsNull(it.Vlr_LiqVenIte,0))
                                    Else sum(IsNull(it.Vlr_LiqItem,0)-IsNull(it.Vlr_SubsTrib,0)-IsNull(it.Vlr_SbtRes,0)-IsNull(it.Vlr_RecSbt,0)-IsNull(it.Vlr_SubsTribEmb,0)-
                                             IsNull(it.Vlr_DespRateada,0)-IsNull(it.Vlr_DspExt,0))
                                  End
                    From NFSCB cb
                         Inner Join NFSIT it on (cb.Cod_Estabe = it.Cod_Estabe) and 
                                                (cb.Ser_Nota = it.Ser_Nota) and 
                                                (cb.Num_Nota = it.Num_Nota)
                         Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
                   Where cb.Cod_Estabe = @PCodEstabe
                     And cb.Status = 'F'
                     And cb.Tip_Saida = 'D'
                     And IsNull(cb.Flg_MovEst,0) = 1
                     And YEAR(cb.Dat_Emissao)  = @PAno
                     And MONTH(cb.Dat_Emissao) = @PMes
                   Group by cb.Cod_Estabe, pr.Cod_Fabricante, YEAR(cb.Dat_Emissao), MONTH(cb.Dat_Emissao)) iv on (ac.Cod_Estabe     = iv.Cod_Estabe) and 
                                                                                                                 (ac.Cod_Fornecedor = iv.Cod_Fabricante) and
                                                                                                                 (ac.Ano_Movimento  = iv.Ano_Emi) and
                                                                                                                 (ac.Mes_Movimento  = iv.Mes_Emi)
     Where ac.Cod_Estabe = @PCodEstabe
       And ac.Ano_Movimento = @PAno
       And ac.Mes_Movimento = @PMes
       And ( (IsNull(ac.Qtd_UniSaiDev,0) <> IsNull(iv.QtdMov,0)) or 
             (IsNull(ac.Vlr_LiqSaiDev,0) <> IsNull(iv.VlrLiq,0)) )
    
-- itens de transferencia
Update ac
   Set ac.Qtd_UniSaiTrf = IsNull(iv.QtdMov,0),
       ac.Vlr_LiqSaiTrf = IsNull(iv.VlrLiq,0)
  From ACFOR ac 
       Left Join (Select cb.Cod_Estabe, pr.Cod_Fabricante, Ano_Emi = YEAR(cb.Dat_Emissao), Mes_Emi = MONTH(cb.Dat_Emissao),  
                         QtdMov = sum(IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0)),
                         VlrLiq = Case
                                    When sum(IsNull(it.Vlr_LiqVenIte,0)) > 0 then sum(IsNull(it.Vlr_LiqVenIte,0))
                                    Else sum(IsNull(it.Vlr_LiqItem,0)-IsNull(it.Vlr_SubsTrib,0)-IsNull(it.Vlr_SbtRes,0)-IsNull(it.Vlr_RecSbt,0)-IsNull(it.Vlr_SubsTribEmb,0)-
                                             IsNull(it.Vlr_DespRateada,0)-IsNull(it.Vlr_DspExt,0))
                                  End
                    From NFSCB cb
                         Inner Join NFSIT it on (cb.Cod_Estabe = it.Cod_Estabe) and 
                                                (cb.Ser_Nota = it.Ser_Nota) and 
                                                (cb.Num_Nota = it.Num_Nota)
                         Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
                   Where cb.Cod_Estabe = @PCodEstabe
                     And cb.Status = 'F'
                     And cb.Tip_Saida = 'T'
                     And IsNull(cb.Flg_MovEst,0) = 1
                     And YEAR(cb.Dat_Emissao)  = @PAno
                     And MONTH(cb.Dat_Emissao) = @PMes
                   Group by cb.Cod_Estabe, pr.Cod_Fabricante, YEAR(cb.Dat_Emissao), MONTH(cb.Dat_Emissao)) iv on (ac.Cod_Estabe     = iv.Cod_Estabe) and 
                                                                                                                 (ac.Cod_Fornecedor = iv.Cod_Fabricante) and
                                                                                                                 (ac.Ano_Movimento  = iv.Ano_Emi) and
                                                                                                                 (ac.Mes_Movimento  = iv.Mes_Emi)
 Where ac.Cod_Estabe = @PCodEstabe
   And ac.Ano_Movimento = @PAno
   And ac.Mes_Movimento = @PMes
   And ( (IsNull(ac.Qtd_UniSaiTrf,0) <> IsNull(iv.QtdMov,0)) or 
         (IsNull(ac.Vlr_LiqSaiTrf,0) <> IsNull(iv.VlrLiq,0)) )
    
-- itens outras saidas
Update ac
   Set ac.Qtd_UniOutSai = IsNull(iv.QtdMov,0),
       ac.Vlr_LiqSaiOut = IsNull(iv.VlrLiq,0)
  From ACFOR ac 
       Left Join (Select cb.Cod_Estabe, pr.Cod_Fabricante, Ano_Emi = YEAR(cb.Dat_Emissao), Mes_Emi = MONTH(cb.Dat_Emissao),  
                         QtdMov = sum(IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0)),
                         VlrLiq = Case
                                    When sum(IsNull(it.Vlr_LiqVenIte,0)) > 0 then sum(IsNull(it.Vlr_LiqVenIte,0))
                                    Else sum(IsNull(it.Vlr_LiqItem,0)-IsNull(it.Vlr_SubsTrib,0)-IsNull(it.Vlr_SbtRes,0)-IsNull(it.Vlr_RecSbt,0)-IsNull(it.Vlr_SubsTribEmb,0)-
                                             IsNull(it.Vlr_DespRateada,0)-IsNull(it.Vlr_DspExt,0))
                                  End
                    From NFSCB cb
                         Inner Join NFSIT it on (cb.Cod_Estabe = it.Cod_Estabe) and 
                                                (cb.Ser_Nota = it.Ser_Nota) and 
                                                (cb.Num_Nota = it.Num_Nota)
                         Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
                   Where cb.Cod_Estabe = @PCodEstabe
                     And cb.Status = 'F'
                     And ( (cb.Tip_Saida <> 'V') and (cb.Tip_Saida <> 'D') and (cb.Tip_Saida <> 'T') )
                     And IsNull(cb.Flg_MovEst,0) = 1
                     And YEAR(cb.Dat_Emissao)  = @PAno
                     And MONTH(cb.Dat_Emissao) = @PMes
                   Group by cb.Cod_Estabe, pr.Cod_Fabricante, YEAR(cb.Dat_Emissao), MONTH(cb.Dat_Emissao)) iv on (ac.Cod_Estabe     = iv.Cod_Estabe) and 
                                                                                                                 (ac.Cod_Fornecedor = iv.Cod_Fabricante) and
                                                                                                                 (ac.Ano_Movimento  = iv.Ano_Emi) and
                                                                                                                 (ac.Mes_Movimento  = iv.Mes_Emi)
            
			
			
 Where ac.Cod_Estabe = @PCodEstabe
   And ac.Ano_Movimento = @PAno
   And ac.Mes_Movimento = @PMes
   And ( (IsNull(ac.Qtd_UniOutSai,0) <> IsNull(iv.QtdMov,0)) or 
         (IsNull(ac.Vlr_LiqSaiOut,0) <> IsNull(iv.VlrLiq,0)) )

--------------------------------------------------------  ENTRADAS  ------------------------------------------------------------------------
-- insere registro de entradas em ACFOR
Insert Into ACFOR (Cod_Estabe, Cod_Fornecedor, Ano_Movimento, Mes_Movimento)
  Select cb.Cod_Estabe, pr.Cod_Fabricante, Ano_Mov = YEAR(cb.Dat_Movimento), Mes_Mov = MONTH(cb.Dat_Movimento)
    From NFECB cb
         Inner Join NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe) and 
                                (cb.Protocolo = it.Protocolo)
         Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
         Left  Join ACFOR ac on (cb.Cod_Estabe = ac.Cod_Estabe) and 
                                (pr.Cod_Fabricante = ac.Cod_Fornecedor) and
	                            (YEAR(cb.Dat_Movimento) = ac.Ano_Movimento) and
			                    (MONTH(cb.Dat_Movimento) = ac.Mes_Movimento)
   Where cb.Cod_Estabe = @PCodEstabe
     And cb.Status = 'F'
     And IsNull(cb.Flg_MovEst,0) = 1
     And YEAR(cb.Dat_Movimento)  = @PAno
     And MONTH(cb.Dat_Movimento) = @PMes
     And ac.Cod_Estabe is null
   Group by cb.Cod_Estabe, pr.Cod_Fabricante, YEAR(cb.Dat_Movimento), MONTH(cb.Dat_Movimento)


-- itens de compra
Update ac
   Set ac.Qtd_UniCom = IsNull(iv.QtdMov,0),
       ac.Vlr_Nfe    = IsNull(iv.VlrLiq,0)
  From ACFOR ac 
       Left Join (Select cb.Cod_Estabe, pr.Cod_Fabricante, Ano_Mov = YEAR(cb.Dat_Movimento), Mes_Mov = MONTH(cb.Dat_Movimento), 
                         QtdMov = sum(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)),
                         VlrLiq = Sum(IsNull(it.Vlr_LiqIte,0))
                    From NFECB cb
                         Inner Join NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe) and 
                                                (cb.Protocolo = it.Protocolo)
                         Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
                   Where cb.Cod_Estabe = @PCodEstabe
                     And cb.Status = 'F'
                     And cb.Tip_NF = 'C'
                     And IsNull(cb.Flg_MovEst,0) = 1
                     And YEAR(cb.Dat_Movimento)  = @PAno
                     And MONTH(cb.Dat_Movimento) = @PMes
                   Group by cb.Cod_Estabe, pr.Cod_Fabricante, YEAR(cb.Dat_Movimento), MONTH(cb.Dat_Movimento)) iv on (ac.Cod_Estabe     = iv.Cod_Estabe) and 
                                                                                                                     (ac.Cod_Fornecedor = iv.Cod_Fabricante) and
                                                                                                                     (ac.Ano_Movimento  = iv.Ano_Mov) and
                                                                                                                     (ac.Mes_Movimento  = iv.Mes_Mov)
 Where ac.Cod_Estabe = @PCodEstabe
   And ac.Ano_Movimento = @PAno
   And ac.Mes_Movimento = @PMes
   And ( (IsNull(ac.Qtd_UniCom,0) <> IsNull(iv.QtdMov,0)) or 
         (IsNull(ac.Vlr_Nfe,0)    <> IsNull(iv.VlrLiq,0)) )

-- itens de devolucao
Update ac
   Set ac.Qtd_UniEntDev = IsNull(iv.QtdMov,0),
       ac.Vlr_NfeDev    = IsNull(iv.VlrLiq,0)
  From ACFOR ac 
       Left Join (Select cb.Cod_Estabe, pr.Cod_Fabricante, Ano_Mov = YEAR(cb.Dat_Movimento), Mes_Mov = MONTH(cb.Dat_Movimento),   
                         QtdMov = sum(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)),
                         VlrLiq = sum(IsNull(it.Vlr_LiqIte,0))
                    From NFECB cb
                         Inner Join NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe) and 
                                                (cb.Protocolo = it.Protocolo)
                         Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
                   Where cb.Cod_Estabe = @PCodEstabe
                     And cb.Status = 'F'
                     And cb.Tip_NF = 'D'
                     And IsNull(cb.Flg_MovEst,0) = 1
                     And YEAR(cb.Dat_Movimento)  = @PAno
                     And MONTH(cb.Dat_Movimento) = @PMes
                   Group by cb.Cod_Estabe, pr.Cod_Fabricante, YEAR(cb.Dat_Movimento), MONTH(cb.Dat_Movimento)) iv on (ac.Cod_Estabe     = iv.Cod_Estabe) and 
                                                                                                                     (ac.Cod_Fornecedor = iv.Cod_Fabricante) and
                                                                                                                     (ac.Ano_Movimento  = iv.Ano_Mov) and
                                                                                                                     (ac.Mes_Movimento  = iv.Mes_Mov)
 Where ac.Cod_Estabe = @PCodEstabe
   And ac.Ano_Movimento  = @PAno
   And ac.Mes_Movimento = @PMes
   And ( (IsNull(ac.Qtd_UniEntDev,0) <> IsNull(iv.QtdMov,0)) or 
         (IsNull(ac.Vlr_NfeDev,0)    <> IsNull(iv.VlrLiq,0)) )
    
-- itens de transferencia
Update ac
   Set ac.Qtd_UniEntTrf = IsNull(iv.QtdMov,0),
       ac.Vlr_NfeTrf    = IsNull(iv.VlrLiq,0)
  From ACFOR ac 
       Left Join (Select cb.Cod_Estabe, pr.Cod_Fabricante, Ano_Mov = YEAR(cb.Dat_Movimento), Mes_Mov = MONTH(cb.Dat_Movimento),  
                         QtdMov = sum(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)),
                         VlrLiq = sum(IsNull(it.Vlr_LiqIte,0))
                    From NFECB cb
                         Inner Join NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe) and 
                                                (cb.Protocolo = it.Protocolo)
                         Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
                   Where cb.Cod_Estabe = @PCodEstabe
                     And cb.Status = 'F'
                     And cb.Tip_NF = 'T'
                     And IsNull(cb.Flg_MovEst,0) = 1
                     And YEAR(cb.Dat_Movimento)  = @PAno
                     And MONTH(cb.Dat_Movimento) = @PMes
                   Group by cb.Cod_Estabe, pr.Cod_Fabricante, YEAR(cb.Dat_Movimento), MONTH(cb.Dat_Movimento)) iv on (ac.Cod_Estabe     = iv.Cod_Estabe) and 
                                                                                                                     (ac.Cod_Fornecedor = iv.Cod_Fabricante) and
                                                                                                                     (ac.Ano_Movimento  = iv.Ano_Mov) and
                                                                                                                     (ac.Mes_Movimento  = iv.Mes_Mov)
 Where ac.Cod_Estabe = @PCodEstabe
   And ac.Ano_Movimento  = @PAno
   And ac.Mes_Movimento = @PMes
   And ( (IsNull(ac.Qtd_UniEntTrf,0) <> IsNull(iv.QtdMov,0)) or 
         (IsNull(ac.Vlr_NfeTrf,0)    <> IsNull(iv.VlrLiq,0)) )
    
-- itens outras entradas
Update ac
   Set ac.Qtd_UniOutEnt = IsNull(iv.QtdMov,0),
       ac.Vlr_NfeOut    = IsNull(iv.VlrLiq,0)
  From ACFOR ac 
       Left Join (Select cb.Cod_Estabe, pr.Cod_Fabricante, Ano_Mov = YEAR(cb.Dat_Movimento), Mes_Mov = MONTH(cb.Dat_Movimento),  
                         QtdMov = sum(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)),
                         VlrLiq = sum(IsNull(it.Vlr_LiqIte,0))
                    From NFECB cb
                         Inner Join NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe) and 
                                                (cb.Protocolo = it.Protocolo)
                         Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
                   Where cb.Cod_Estabe = @PCodEstabe
                     And cb.Status = 'F'
                     And ( (cb.Tip_NF <> 'C') and (cb.Tip_NF <> 'D') and (cb.Tip_NF <> 'T') )
                     And IsNull(cb.Flg_MovEst,0) = 1
                     And YEAR(cb.Dat_Movimento)  = @PAno
                     And MONTH(cb.Dat_Movimento) = @PMes
                   Group by cb.Cod_Estabe, pr.Cod_Fabricante, YEAR(cb.Dat_Movimento), MONTH(cb.Dat_Movimento)) iv on (ac.Cod_Estabe     = iv.Cod_Estabe) and 
                                                                                                                     (ac.Cod_Fornecedor = iv.Cod_Fabricante) and
                                                                                                                     (ac.Ano_Movimento  = iv.Ano_Mov) and
                                                                                                                     (ac.Mes_Movimento  = iv.Mes_Mov)
 Where ac.Cod_Estabe = @PCodEstabe
   And ac.Ano_Movimento  = @PAno
   And ac.Mes_Movimento = @PMes
   And ( (IsNull(ac.Qtd_UniOutEnt,0) <> IsNull(iv.QtdMov,0)) or 
         (IsNull(ac.Vlr_NfeOut,0)    <> IsNull(iv.VlrLiq,0)) )

if @@trancount > 0
  COMMIT TRANSACTION
GO

/*************************************************************************************************/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ReprocessaEstoquePulmao]
@PCodEstabe int

AS

SET NOCOUNT ON 

Begin Transaction

-- normaliza NEXML
Delete x
From NEXML x 
     Left Join NFECB cb on x.Cod_Estabe = cb.Cod_Estabe and x.Num_Protoc = cb.Protocolo
Where x.Cod_Estabe = @PCodEstabe
And IsNull(cb.Status,'') <> 'A' 
And IsNull(cb.Status,'') <> 'P'
And IsNull(cb.Tip_NF,'') <> 'C'
And IsNull(cb.Tip_NF,'') <> 'D'

Insert Into NEXML (Cod_Estabe, Num_Protoc)
  Select cb.Cod_Estabe, cb.Protocolo
  From NFECB cb
       Left Outer Join NEXML x on cb.Cod_Estabe = x.Cod_Estabe and cb.Protocolo = x.Num_Protoc
  WHere cb.Cod_Estabe = @PCodEstabe
  And cb.Status in ('A', 'P')  
  And cb.Tip_NF in ('C', 'D')  
  And x.Num_Protoc is null


if Exists(Select top 1 pr.Qtd_Pulmao, ne.QtdTot
          From PRXES pr
               Left Join (Select it.Cod_Estabe, it.Cod_Produto, QtdTot=sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0))
                          From NFEIT it
                               Inner Join NFECB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Protocolo = cb.Protocolo
                               Inner Join NEXML x on cb.Cod_Estabe = x.Cod_Estabe and cb.Protocolo = x.Num_Protoc
                          Where it.Cod_Estabe = @PCodEstabe
                          Group by it.Cod_Estabe, it.Cod_Produto) ne on pr.Cod_Estabe = ne.Cod_Estabe and pr.Cod_Produt = ne.Cod_Produto 
          Where pr.Cod_Estabe = @PCodEstabe
          And pr.Qtd_Pulmao <> IsNull(ne.QtdTot,0))
  begin
    -- zera quantidades
    Update PRXES
      Set Qtd_Pulmao = 0
      Where Cod_Estabe = @PCodEstabe
      And Qtd_Pulmao <> 0

    Delete From NEXML Where Cod_Estabe = @PCodEstabe

    Insert Into NEXML (Cod_Estabe, Num_Protoc)
      Select cb.Cod_Estabe, cb.Protocolo
      From NFECB cb
           Left Outer Join NEXML x on cb.Cod_Estabe = x.Cod_Estabe and cb.Protocolo = x.Num_Protoc
      WHere cb.Cod_Estabe = @PCodEstabe
      And cb.Status in ('A', 'P')      
	  And cb.Tip_NF in ('C', 'D')  
      And x.Num_Protoc is null

    Update pr
      Set pr.Qtd_Pulmao = ne.QtdTot
    From PRXES pr
         Inner Join (Select it.Cod_Estabe, it.Cod_Produto, QtdTot=sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0))
                     From NFEIT it
                          Inner Join NFECB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Protocolo = cb.Protocolo
                          Inner Join NEXML x on cb.Cod_Estabe = x.Cod_Estabe and cb.Protocolo = x.Num_Protoc
                      Where it.Cod_Estabe = @PCodEstabe
                      Group by it.Cod_Estabe, it.Cod_Produto) ne on pr.Cod_Estabe = ne.Cod_Estabe and pr.Cod_Produt = ne.Cod_Produto 
    Where pr.Cod_Estabe = @PCodEstabe

  end

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_DescriOrigemPedVen]
(
  @PCodOrigem char(1)
)
RETURNS varchar(20) 

AS

BEGIN
  -- Declarar variável de retorno da function
  DECLARE @DesOri varchar(20) = ''
  
  Set @DesOri = Case 
                  When @PCodOrigem = 'A' Then 'Ativo'
                  When @PCodOrigem = 'P' Then 'Receptivo'
                  When @PCodOrigem = 'M' Then 'Móvel'
                  When @PCodOrigem = 'T' Then 'Eletronico/EDI' 
                  When @PCodOrigem = 'W' Then 'Internet/WEB' 
                  When @PCodOrigem = 'H' Then 'Hospitalar'
                  When @PCodOrigem = 'G' Then 'Consignação'
                  When @PCodOrigem = 'D' Then 'por Desdobramento'
                  When @PCodOrigem = 'V' Then 'por Vales'
                  When @PCodOrigem = 'C' Then 'por Cotação'
                  Else '???'
                End

  -- Retorna o resultado da function
  RETURN IsNull(@DesOri,'')

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].PR_UltimaEntradaTermoAcordo
@PCodEstabe integer,
@PCodPrd integer,
@PCodLot varchar(20),
@PDatRef smalldatetime,                 -- dat emissão da NF saida
@PDatFim smalldatetime,                 -- data final do periodo
@PFlgUsaInfCad bit,                     -- usa informaçoes de compra do cadastro de produtos se não encontrar registros em NFECB/NFEIT
@PNumNotUltEnt integer output,
@PPrcUltEnt numeric(18,4) output, 
@PAlqUltEnt numeric(18,4) output,
@PFlgSbtEnt bit output,
@PCodReg varchar(3) output

AS

SET NOCOUNT ON

BEGIN TRANSACTION

Declare @Mes smallint,
        @Ano smallint,
        @PrcUniMed numeric(18,4),
        @PrcUniAnt numeric(18,4),
        @QtdAnt int,
        @PrcUniAtu numeric(18,4),
        @QtdAtu int,
        @CodUfOri varchar(2), 
        @NumNot int, 
        @PrcUni numeric(18,4),
        @QtdPed int, 
        @QtdBon int, 
        @PerDscIte numeric(18,4),
        @VlrDscRat numeric(18,4), 
        @VlrDscTri numeric(18,4), 
        @VlrDspRat numeric(18,4),
        @VlrIpi numeric(18,4),
        @AlqIcm numeric(18,4),
        @VlrBasTri numeric(18,4),
        @VlrSbt numeric(18,4),

        @pr_PrcUltEnt numeric(18,4), 
        @pr_PerDscUltEnt numeric(18,4), 
        @rx_AlqIcmExtReg numeric(18,4),  
        @rx_TipPrcBasSbtEnt varchar(1), 
        @fo_CodUfCom varchar(2)

Set @PNumNotUltEnt = 0
Set @PPrcUltEnt = 0
Set @PAlqUltEnt = 0
Set @PFlgSbtEnt = 0
Set @PCodReg = ''    -- INT- int,  NNE- Norte Nordeste Centro Oeste e Espirito Santo, SSE - Sul sudeste exceto Espirito Santo

Set @Ano = 0
Set @Mes = 0

Set @PrcUniMed = 0
Set @PrcUniAnt = 0
Set @QtdAnt = 0

if Exists(Select 1 From NFECB cb
                   Inner Join NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo) 
          Where cb.Cod_Estabe = @PCodEstabe
          And cb.Status = 'F'
          And ((cb.Tip_NF = 'C') or (cb.Tip_NF = 'T')) 
          And it.Cod_Produto = @PCodPrd
          --And it.Cod_Lote = @PCodLot
          And cb.Dat_Movimento <= @PDatFim)
  begin

    Select Top 1 @Mes = Month(cb.Dat_Movimento), 
                 @Ano = Year(cb.Dat_Movimento)
    From NFECB cb 
         Inner Join NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo) 
    Where cb.Cod_Estabe = @PCodEstabe
    And cb.Status = 'F'
    And ((cb.Tip_NF = 'C') or (cb.Tip_NF = 'T')) 
    And it.Cod_Produto = @PCodPrd
    --And it.Cod_Lote = @PCodLot
    And cb.Dat_Movimento <= @PDatFim
    Order by cb.Dat_Movimento desc 

    Declare NOTCB_Cr Cursor Local Fast_Forward For 
      Select cb.Cod_UfOrigem, cb.Numero, it.Prc_Unitario, it.Qtd_Pedido, it.Qtd_Bonificacao, it.Per_DescItem, 
             it.Vlr_DescRateado, IsNull(it.Vlr_DscTri,0), it.Vlr_DespRateada, it.Vlr_Ipi, it.Alq_Icms, 
             it.Vlr_BasTri, (IsNull(it.Vlr_SubsTrib,0)+IsNull(it.Vlr_SbtRes,0)+IsNull(it.Vlr_DifTri,0)) as VlrSbt 
      From NFECB cb Inner Join NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo) 
      Where cb.Cod_Estabe = @PCodEstabe
      And cb.Status = 'F'
      And ((cb.Tip_NF = 'C') or (cb.Tip_NF = 'T')) 
      And it.Cod_Produto = @PCodPrd
      -- And it.Cod_Lote = @PCodLot
      -- And cb.Dat_Movimento <= @PDatSai   retirei em 25/09/2018  nf mais proxima à data da saída
    And Month(cb.Dat_Movimento) = @Mes
    And Year(cb.Dat_Movimento) = @Ano
    Order by cb.Dat_Movimento desc, cb.Protocolo desc 
 
    Open NOTCB_Cr
    Fetch Next From NOTCB_Cr Into @CodUfOri, @NumNot, @PrcUni, @QtdPed, @QtdBon, @PerDscIte,
	                              @VlrDscRat, @VlrDscTri, @VlrDspRat, @VlrIpi, @AlqIcm,
								  @VlrBasTri, @VlrSbt
    While @@FETCH_STATUS = 0
      begin
        Set @PrcUniAtu = (@PrcUni * @QtdPed * (1-@PerDscIte/100)) - @VlrDscRat - @VlrDscTri + @VlrDspRat + @VlrIpi
        Set @QtdAtu = @QtdPed + @QtdBon

        Set @PrcUniAtu = Round(@PrcUniAtu/@QtdAtu,4)

        if @PPrcUltEnt = 0 
          begin
            if @PNumNotUltEnt = 0 
              Set @PNumNotUltEnt = @NumNot
            Set @PPrcUltEnt = @PrcUniAtu
            Set @PAlqUltEnt = @AlqIcm
            Set @PFlgSbtEnt = 0
            if @VlrSbt > 0 
              Set @PFlgSbtEnt = 1

            if Upper(@CodUfOri) = (Select Upper(Des_Estado) From ESTAB Where Cod_Estabe = @PCodEstabe)
              Set @PCodReg = 'INT'   -- procedente do proprio estado
            else
            if CharIndex(Upper(@CodUfOri),'MG;RJ;SP;PR;SC;RS') > 0 
              Set @PCodReg = 'SSE'   -- procedente do Sul e Sudeste, exceto Espirito Santo
            else
              Set @PCodReg = 'NNE'   -- procedente do Norte, Nordeste, Centro-Oeste e Espirito Santo
          end;

        Set @PrcUniMed = ((@PrcUniAnt*@QtdAnt)+(@PrcUniAtu*@QtdAtu))/(@QtdAnt+@QtdAtu)

        Set @PrcUniAnt = @PrcUniMed
        Set @QtdAnt = @QtdAnt + @QtdAtu

        Fetch Next From NOTCB_Cr Into @CodUfOri, @NumNot, @PrcUni, @QtdPed, @QtdBon, @PerDscIte,
	                                  @VlrDscRat, @VlrDscTri, @VlrDspRat, @VlrIpi, @AlqIcm,
		    						  @VlrBasTri, @VlrSbt
      end

    Close NOTCB_Cr
    Deallocate NOTCB_Cr

    if @PrcUniMed > @PPrcUltEnt
      Set @PPrcUltEnt = @PrcUniMed

  end  -- if Exists(Select 1 From NFECB cb

-- pega o preco no cadastro
if (@PPrcUltEnt = 0) and (@PFlgUsaInfCad = 1) and
   Exists(Select 1
          From PRXES pr 
               Inner Join PRODU p on pr.Cod_Produt = p.Codigo 
               Inner Join FBXES fb on p.Cod_Fabricante = fb.Cod_Fabric and pr.Cod_Estabe = fb.Cod_Estabe
               Left Join FORNE fo on fb.Cod_ForPref = fo.Codigo 
               Left Join ENXES es on pr.Cod_Estabe = es.Cod_Estabe and fo.Cgc_Cpf = es.Num_CgcCpf 
               Left Join RTXCT rx on ((es.Cod_RegTri = rx.Cod_RegTri) and (pr.Cod_ClaTri = rx.Cod_ClaTri)) 
          Where pr.Cod_Estabe = @PCodEstabe
          And pr.Cod_Produt = @PCodPrd)
  begin
    Select @pr_PrcUltEnt = pr.Prc_UltEnt, 
	       @pr_PerDscUltEnt = pr.Per_DscUltEnt, 
		   @rx_AlqIcmExtReg = IsNull(rx.Alq_IcmExtReg,99), 
		   @rx_TipPrcBasSbtEnt = IsNull(rx.Tip_PrcBasSbtEnt,'?'), 
		   @fo_CodUfCom = IsNull(fo.Estado_Com,'??') 
    From PRXES pr 
         Inner Join PRODU p on pr.Cod_Produt = p.Codigo 
         Inner Join FBXES fb on p.Cod_Fabricante = fb.Cod_Fabric and pr.Cod_Estabe = fb.Cod_Estabe
         Left Join FORNE fo on fb.Cod_ForPref = fo.Codigo
         Left Join ENXES es on pr.Cod_Estabe = es.Cod_Estabe and fo.Cgc_Cpf = es.Num_CgcCpf 
         Left Join RTXCT rx on ((es.Cod_RegTri = rx.Cod_RegTri) and (pr.Cod_ClaTri = rx.Cod_ClaTri)) 
    Where pr.Cod_Estabe = @PCodEstabe
    And pr.Cod_Produt = @PCodPrd

    Set @PPrcUltEnt = Round(@pr_PrcUltEnt*(1-@pr_PerDscUltEnt/100),4)

    if Upper(@fo_CodUfCom) = '??'
      Set @PCodReg = '???' 
	else
    if Upper(@fo_CodUfCom) = (Select Upper(Des_Estado) From ESTAB Where Cod_Estabe = @PCodEstabe)
      Set @PCodReg = 'INT'   -- procedente do proprio estado
    else
    if CharIndex(Upper(@fo_CodUfCom),'MG;RJ;SP;PR;SC;RS') > 0 
       Set @PCodReg = 'SSE'   -- procedente do Sul e Sudeste, exceto Espirito Santo
    else
       Set @PCodReg = 'NNE'   -- procedente do Norte, Nordeste, Centro-Oeste e Espirito Santo

    Set @PAlqUltEnt = @rx_AlqIcmExtReg

	if (@rx_TipPrcBasSbtEnt <> 'X') and (@rx_TipPrcBasSbtEnt <> 'O')
      Set @PFlgSbtEnt = 1
    else
      Set @PFlgSbtEnt = 0
  end

-- ultima caso pega qualquer ultima entrada mais proximo à saída
if (@PPrcUltEnt = 0) and (@PFlgUsaInfCad = 1) and
   Exists(Select 1 From NFECB cb Inner Join NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo) 
          Where cb.Cod_Estabe = @PCodEstabe
          And cb.Status = 'F'
          And it.Cod_Produto = @PCodPrd
          And cb.Dat_Movimento <= @PDatRef)
  begin
    Select top 1 @CodUfOri = cb.Cod_UfOrigem, 
                 @NumNot = cb.Numero, 
                 @PrcUni = it.Prc_Unitario, 
                 @QtdPed = it.Qtd_Pedido, 
                 @QtdBon = it.Qtd_Bonificacao, 
                 @PerDscIte = it.Per_DescItem, 
                 @VlrDscRat = it.Vlr_DescRateado, 
                 @VlrDscTri = IsNull(it.Vlr_DscTri,0), 
                 @VlrDspRat = it.Vlr_DespRateada, 
                 @VlrIpi = it.Vlr_Ipi, 
                 @AlqIcm = it.Alq_Icms, 
                 @VlrBasTri = it.Vlr_BasTri, 
                 @VlrSbt = (IsNull(it.Vlr_SubsTrib,0)+IsNull(it.Vlr_SbtRes,0)+IsNull(it.Vlr_DifTri,0))
      From NFECB cb 
	       Inner Join NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo) 
    Where cb.Cod_Estabe = @PCodEstabe
    And cb.Status = 'F'
    And it.Cod_Produto = @PCodPrd
    And cb.Dat_Movimento <= @PDatRef
    Order by cb.Dat_Movimento desc, cb.Protocolo desc 

    Set @PNumNotUltEnt = @NumNot
    Set @PPrcUltEnt = Round(( (@PrcUni*@QtdPed*(1-@PerDscIte/100)) - @VlrDscRat - @VlrDscTri + @VlrDspRat + @VlrIpi) / (@QtdPed+@QtdBon),4)
    Set @PAlqUltEnt = @AlqIcm
    Set @PFlgSbtEnt = 0
    if @VlrSbt > 0 Set @PFlgSbtEnt = 1

    if Upper(@CodUfOri) = (Select Upper(Des_Estado) From ESTAB Where Cod_Estabe = @PCodEstabe)
      Set @PCodReg = 'INT'   -- procedente do proprio estado
    else
    if CharIndex(Upper(@CodUfOri),'MG;RJ;SP;PR;SC;RS') > 0 
      Set @PCodReg = 'SSE'   -- procedente do Sul e Sudeste, exceto Espirito Santo
    else
      Set @PCodReg = 'NNE'   -- procedente do Norte, Nordeste, Centro-Oeste e Espirito Santo

  end

COMMIT TRANSACTION
GO


SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CancelaMovNFECB]
@PCodEstabe int,
@PNumPrt int,
@PNomUsu varchar(15)

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = cast(convert(char(8),GetDate(),112) as smalldatetime)

-- verifica se lote pode ficcar negativo
if ((Select IsNull(Flg_WMS,0) From NFECB Where Cod_Estabe = @PCodEstabe and Protocolo = @PNumPrt) = 0) and
   Exists(Select i.Cod_Produto, i.Cod_Lote
            From NFEIT i
                 Inner Join (Select Cod_Estabe, Cod_Produt, Cod_Lote, 
                                    Qtd_FisPra = SUM(IsNull(Qtd_FisPra,0)), Qtd_SldPra = SUM(IsNull(Qtd_SldPra,0)) 
                             From PRLOT 
                             Group by Cod_Estabe, Cod_Produt, Cod_Lote) l ON ((i.Cod_Estabe = l.Cod_Estabe) and (i.Cod_Produto = l.Cod_Produt) and (i.Cod_Lote = l.Cod_Lote))
            Where i.Cod_Estabe = @PCodEstabe and i.protocolo = @PNumPrt
            And i.Cod_Cfo > 0
            And (((i.Qtd_Pedido+i.Qtd_Bonificacao) > l.Qtd_FisPra) or ((i.Qtd_Pedido+i.Qtd_Bonificacao) > l.Qtd_SldPra))
          Union
          Select i.Cod_Produto, i.Cod_Lote
            From NFEIT i
                 Inner Join (Select Cod_Estabe, Cod_Produt, Cod_Lote, 
                                    Qtd_FisDep = SUM(IsNull(Qtd_FisDep,0)), Qtd_SldDep = SUM(IsNull(Qtd_SldDep,0)) 
                             From PRLOT 
                             Group by Cod_Estabe, Cod_Produt, Cod_Lote) l ON ((i.Cod_Estabe = l.Cod_Estabe) and (i.Cod_Produto = l.Cod_Produt) and (i.Cod_Lote = l.Cod_Lote))
            Where i.Cod_Estabe = @PCodEstabe and i.protocolo = @PNumPrt
            And i.Cod_Cfo = 0
            And (((i.Qtd_Pedido+i.Qtd_Bonificacao) > l.Qtd_FisDep) or ((i.Qtd_Pedido+i.Qtd_Bonificacao) > l.Qtd_SldDep)))
  RAISERROR('Esta operação acarretará em lote negativo em um ou mais ítens',16,1)
else
if ((Select IsNull(Flg_WMS,0) From NFECB Where Cod_Estabe = @PCodEstabe and Protocolo = @PNumPrt) = 1) and
   Exists(Select i.Cod_Produt, i.Cod_Lote
            From NELTL i
                 Inner Join NFECB cb on ((cb.Cod_Estabe = i.Cod_Estabe) and (cb.protocolo = i.Num_Protoc))
                 Left Outer Join PRLTL l ON ((i.Cod_Estabe = l.Cod_Estabe) and
                                             (i.Cod_Produt = l.Cod_Produt) and (i.Cod_Lote = l.Cod_Lote) and 
                                             (i.Cod_Dep = l.Cod_Dep) and (i.Num_Rua = l.Num_Rua) and 
                                             (i.Num_Col = l.Num_Col) and (i.Num_Niv = l.Num_Niv) and 
                                             (i.Num_Apt = l.Num_Apt) and (i.Qtd_EmbFec = l.Qtd_EmbFec))
		         Left Outer Join PRLOT t ON ((i.Cod_Estabe = t.Cod_Estabe) and (i.Cod_Produt = t.Cod_Produt) and
                                             (i.Cod_Lote = t.Cod_Lote) and (i.Cod_Dep = t.Cod_Dep))
            Where i.Cod_Estabe = @PCodEstabe and i.Num_Protoc = @PNumPrt
            And cb.Cod_Cfo > 0
			And ((i.Qtd_Est > IsNull(l.Qtd_FisPra, 0)+IsNull(t.Qtd_FisPra, 0)) or (i.Qtd_Est > IsNull(l.Qtd_SldPra, 0)+IsNull(t.Qtd_SldPra, 0)))
          Union
          Select i.Cod_Produt, i.Cod_Lote
            From NELTL i
                 Inner Join NFECB cb on ((cb.Cod_Estabe = i.Cod_Estabe) and (cb.protocolo = i.Num_Protoc))
                 Left Outer Join PRLTL l ON ((i.Cod_Estabe = l.Cod_Estabe) and
                                             (i.Cod_Produt = l.Cod_Produt) and (i.Cod_Lote = l.Cod_Lote) and 
                                             (i.Cod_Dep = l.Cod_Dep) and (i.Num_Rua = l.Num_Rua) and 
                                             (i.Num_Col = l.Num_Col) and (i.Num_Niv = l.Num_Niv) and 
                                             (i.Num_Apt = l.Num_Apt) and (i.Qtd_EmbFec = l.Qtd_EmbFec))
		         Left Outer Join PRLOT t ON ((i.Cod_Estabe = t.Cod_Estabe) and (i.Cod_Produt = t.Cod_Produt) and
                                             (i.Cod_Lote = t.Cod_Lote) and (i.Cod_Dep = t.Cod_Dep))
            Where i.Cod_Estabe = @PCodEstabe and i.Num_Protoc = @PNumPrt
            And cb.Cod_Cfo = 0
			And ((i.Qtd_Est > IsNull(l.Qtd_FisDep, 0)+IsNull(t.Qtd_FisDep, 0)) or (i.Qtd_Est > IsNull(l.Qtd_SldDep, 0)+IsNull(t.Qtd_SldDep, 0)))
			)
  RAISERROR('Esta operação acarretará em lote negativo em um ou mais ítens',16,1)
else
  begin
    Begin Transaction

    -- estorna quantidades
    Declare @CodCfo int,
            @CodPrd int,
            @CodLot varchar(20),
            @DatMov smalldatetime,
            @QtdPed int,
            @QtdBon int,
            @PrcUni numeric(18,8),
            @QtdPrm int,
            @QtdMov int,
            @QtdPra int,
            @QtdDep int,
            @ValLiq numeric(18,4),
            @ValCusMed numeric(18,4),
            @ValPrcFab numeric(18,4),
            @VlrVerbaVdr numeric(18,4),
            @VlrVerbaSup numeric(18,4),
            @VlrVerbaOpe numeric(18,4),
            @VlrVerbaFor numeric(18,4),
            @CodPrm int,
            @FlgWms bit,
            @TipLoc varchar(1),
            @CodDep smallint,
            @NumRua smallint,
            @NumCol smallint,
            @NumNiv smallint,
            @NumApt smallint,
            @QtdEmbFec int,
            @QtdEst int,
            @TipNfe varchar(1),
            @FlgMovEst bit,
            @CodEmiFor int,
            @CodEmiTra int,
            @CodEmiCli int,
            @CodVdr int,
            @CodVdrTlmkt int,
            @CodSup int,
            @ValNot numeric(18,4),
            @CodOri varchar(20),
            @IdConsig int = 0,
            @NumSeqCtr smallint = 0,
            @NumSeqDev smallint = 0,
            @FlgFaturaConsig bit = 0,  -- gera fatura de consignados quando for NF de devolução simbólica
            @CodTipDevCng varchar(3),
			@Usuario varchar(15),
			@QtdMovSld int
	
	-- Auditoria usuario infarma ou banco
	Set @Usuario = dbo.FN_UsuarioInfarma()

    Update NFECB
      Set Status = 'C',
          Dat_Cancelamento = @Date,
          Usuario = @Usuario,
          Transacao = GetDate()
      Where Cod_Estabe = @PCodEstabe 
      and Protocolo = @PNumPrt

    Select @CodCfo = cb.Cod_Cfo,
           @TipNfe = cb.Tip_NF,
           @DatMov = cb.Dat_Movimento,
           @FlgWMS = IsNull(cb.Flg_WMS,0),
           @FlgMovEst = IsNull(cb.Flg_MovEst,0),
           @CodEmiFor = IsNull(cb.Cod_EmiFornec,0),
           @CodEmiTra = IsNull(cb.Cod_EmiTransp,0),
           @CodEmiCli = IsNull(cb.Cod_EmiCliente,0),
           @ValNot = IsNull(cb.Vlr_Nota,0),
           @FlgFaturaConsig = Case 
                                When (cb.Tip_NF = 'D') and 
                                     (IsNull(dv.Id_Consig,0) > 0) and (dv.Tip_Devolu = 'S') then 1 
                                Else 0 
                              End,
           @IdConsig  = Case 
                          When (cb.Tip_NF = 'D') and (IsNull(dv.Id_Consig,0) > 0) then cb.Id_Consig 
                          Else 0 
                        End,
           @NumSeqCtr = Case 
                          When (cb.Tip_NF = 'D') and (IsNull(dv.Id_Consig,0) > 0) then cb.Num_SeqCtr 
                          Else 0 
                        End,
           @NumSeqDev = Case 
                          When (cb.Tip_NF = 'D') and (IsNull(dv.Id_Consig,0) > 0) then cb.Num_SeqDev 
                          Else 0 
                        End,
           @CodVdr = IsNull(cb.Cod_Vendedor,0), 
           @CodVdrTlmkt = IsNull(cb.Cod_VendTlmkt,0),
           @CodSup = IsNull(ve.Cod_Supervisor,0)
      From NFECB cb
           left join VENDE ve on cb.Cod_Vendedor = ve.Codigo
           Left Join CNGDC dv on cb.Cod_Estabe = dv.Cod_Estabe and cb.Id_Consig  = dv.Id_Consig and
                                 cb.Num_SeqCtr = dv.Num_Sequen and cb.Num_SeqDev = dv.Num_SeqDev 
      Where cb.Cod_Estabe = @PCodEstabe 
      and cb.Protocolo = @PNumPrt

    Declare NFEIT_Cr Cursor Local Fast_Forward For 
      Select Cod_Produto, Cod_Lote, Qtd_Pedido, Qtd_Bonificacao, Prc_Unitario,
             Vlr_LiqIte, Qtd_Promocao, IsNull(Vlr_DscIte2,0),
             (Qtd_Pedido+Qtd_Bonificacao)*IsNull(Prc_CustoMedio,0), (Qtd_Pedido+Qtd_Bonificacao)*IsNull(Prc_Fabric,0),
             IsNull(Vlr_Verba,0), IsNull(Vlr_VrbOpe,0), IsNull(Vlr_VrbSup,0)
        From NFEIT
        Where Cod_Estabe = @PCodEstabe 
        and Protocolo = @PNumPrt

    Open NFEIT_Cr
    Fetch Next From NFEIT_Cr
      Into @CodPrd, @CodLot, @QtdPed, @QtdBon, @PrcUni,
           @ValLiq, @QtdPrm, @VlrVerbaFor, @ValCusMed, @ValPrcFab,
           @VlrVerbaVdr, @VlrVerbaOpe, @VlrVerbaSup

    While @@FETCH_STATUS = 0
      begin
        Set @QtdMov = @QtdPed + @QtdBon

        if @FlgWMS = 0 
          begin
			Set @CodDep = IsNull((Select min(Cod_Dep) From TBDEP),1)
            Set @QtdPra = 0
            Set @QtdDep = 0
            if @CodCfo > 0
              Set @QtdPra = @QtdMov * (-1)
            else
              Set @QtdDep = @QtdMov * (-1)
            Exec PR_AtualizaSaldoEstoque 'NF', @PCodEstabe, @CodDep, @CodPrd, @CodLot, @DatMov, 'E', @TipNfe, @QtdPra, 0, @QtdDep, 0
            if @@error <> 0
              begin
                if @@trancount > 0
                  Rollback Transaction
                Return
              end
          end
        else
		  begin
			Set @QtdMovSld = @QtdMov

		    While @QtdMovSld > 0
              begin		

				Declare NELTL_Cr Cursor Local Fast_Forward For 
				  Select Tip_Local, Qtd_EmbFec, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Qtd_Est
					From NELTL
					Where Cod_Estabe = @PCodEstabe 
					and Num_Protoc = @PNumPrt
					And Cod_Produt = @CodPrd
				   And Cod_Lote = @CodLot

				Open NELTL_Cr
				Fetch Next From NELTL_Cr
				  Into @TipLoc, @QtdEmbFec, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @QtdEst
				While @@FETCH_STATUS = 0 and (@QtdMovSld > 0)
				  begin
					if Ltrim(Rtrim(@TipLoc)) = ''
					  Set @TipLoc = dbo.FN_TipLocEnd(@PCodEstabe,@CodDep,@NumRua)

					if @QtdEst > @QtdMovSld
					  Set @QtdEst = @QtdMovSld
				  
					Set @QtdPra = 0
					Set @QtdDep = 0
					if @CodCfo > 0
					  Set @QtdPra = @QtdEst * (-1)
					else
					  Set @QtdDep = @QtdEst * (-1)

					if @TipLoc = 'P'
					  begin
						Exec PR_AtualizaSaldoEstoque 'NF', @PCodEstabe, @CodDep, @CodPrd, @CodLot, @DatMov, 'E', @TipNfe, @QtdPra, 0, @QtdDep, 0
					  end
					else
					  begin
						Exec PR_AtualizaSaldoEstoqueGrosso @PCodEstabe, @CodPrd, @CodLot, @QtdEmbFec, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @DatMov, 'E', @TipNfe, @QtdPra, 0, @QtdDep, 0
					  end
					if @@error <> 0
					  begin
						Rollback Transaction
						Return
					  end
                  
					-- registra log saida
					Set @CodOri = 'CAN_NFE'

                    -- registra log saida
                    Set @QtdMov = @QtdEst * (-1)
                    Exec PR_InserePRLOG @PCodEstabe, @CodPrd, @CodLot, @CodDep, 
                                        @NumRua, @NumCol, @NumNiv, @NumApt,
                                        @QtdMov, @CodOri, '', @PNumPrt, '', '', @Usuario
                    if @@error <> 0 
                      begin
                        if @@trancount > 0
                          Rollback Transaction
                        Return
                      end 
                
                    Set @QtdMovSld = @QtdMovSld - ((@QtdPra * (-1)) + (@QtdDep * (-1)))
                    
                    Fetch Next From NELTL_Cr
                      Into @TipLoc, @QtdEmbFec, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @QtdEst
                  end
                Close NELTL_Cr
                Deallocate NELTL_Cr
              end  
          end

        -- da saida na promocao
        if @QtdPrm > 0
          begin
            Select @CodPrm = Cod_Promocao From PRXES Where Cod_Estabe = @PCodEstabe And Cod_Produt = @CodPrd
            Set @QtdPrm = @QtdPrm*(-1)
            if IsNull(@CodPrm,0) > 0
              EXEC PR_GravaPrmMv @PCodEstabe, @CodPrm, @CodPrd, @DatMov, 'D', '', @PNumPrt, @QtdPrm
          end

        Set @QtdMov = @QtdPed + @QtdBon

        -- atualiza estatisticas de produtos
        Exec PR_AcuEntNfeItePrd @PCodEstabe, @TipNfe, 'C', @CodPrd, @DatMov, @QtdMov, @ValLiq, @ValCusMed, @ValPrcFab
        if @@error <> 0
          begin
            if @@trancount > 0
              Rollback Transaction
            Return
          end

        -- atualiza estatisticas de fabricantes
        Exec PR_AcuEntNfeIteFor @PCodEstabe, @TipNfe, 'C', @CodPrd, @DatMov, @QtdMov, @ValLiq
        if @@error <> 0
          begin
            if @@trancount > 0
              Rollback Transaction
            Return
          end

        -- atualiza estatisticas de clientes (devolução)
        if @CodEmiCli > 0
          begin
            Exec PR_AcuEntNfeIteCli @PCodEstabe, @TipNfe, 'C', @CodEmiCli, @DatMov, @QtdMov, @ValLiq
            if @@error <> 0
              begin
                if @@trancount > 0
                  RollBack Transaction
                Return
              end
          end

        -- atualiza estatisticas de Vendedores (devolução)
        if @CodVdr > 0
          begin
            Exec PR_AcuEntNfeIteVen @PCodEstabe, @TipNfe, 'C', @CodVdr, @DatMov, @QtdMov, @ValLiq
            if @@error <> 0
              begin
                if @@trancount > 0
                  RollBack Transaction
                Return
              end
          end

        -- verba (cancelamento de devolução)
        Declare @pc_Controle_Saldo varchar(1) = '?',
                @CodFab int = 0

        Set @CodFab = (Select Cod_Fabricante From PRODU Where Codigo = @CodPrd)

        Set @pc_Controle_Saldo = IsNull((Select top 1 pc.Controle_Saldo
                                           From NEREF r 
                                                Inner Join NFSIT it on (r.Tip_EntSai = 'S' and 
                                                                        r.Cod_Estabe = it.Cod_Estabe and 
                                                                        r.Ser_DocRef = it.Ser_Nota and 
                                                                        r.Num_DocRef = it.Num_Nota and
                                                                        it.Cod_Produto = @CodPrd and
                                                                        it.Cod_Lote = @CodLot)
                                                Inner join POCOM pc on pc.Id_PolCom = it.Id_PolCom
                                          Where r.Cod_Estabe = @PCodEstabe
                                            And r.Protocolo = @PNumPrt),'?')

        if @pc_Controle_Saldo = 'V' -- Vendedor/Operador
          begin
            -- repõe verba vendedor
            if (@VlrVerbaVdr <> 0) and (@TipNfe = 'D')
              begin
                Set @VlrVerbaVdr = @VlrVerbaVdr
                Exec PR_AtualizaSaldoVBSLD @PCodEstabe, @CodVdr, @DatMov, 0, @CodPrd, @CodLot, 'E', @TipNfe, '',   '', @PNumPrt, @VlrVerbaVdr, 'DEVOLUCAO NF', @Usuario
                if (@@error <> 0)
                  begin
                    if @@trancount > 0
                      RollBack Transaction
                    Return
                  end
              end
       
            -- atualiza verba Operador
            if (@VlrVerbaOpe <> 0) and (@TipNfe = 'D') and (IsNull(@CodVdrTlmkt, 0) > 0)
              begin
                Set @VlrVerbaOpe = @VlrVerbaOpe
                Exec PR_AtualizaSaldoVBSLD @PCodEstabe, @CodVdrTlmkt, @DatMov, 0, @CodPrd, @CodLot, 'E', @TipNfe, '',   '', @PNumPrt, @VlrVerbaOpe, 'DEVOLUCAO NF', @Usuario
                if (@@error <> 0)
                  begin
                    if @@trancount > 0
                      RollBack Transaction
                    Return
                  end
              end
       
            -- atualiza verba Supervisor
            if (@VlrVerbaSup <> 0) and (@TipNfe = 'D') and (IsNull(@CodSup, 0) > 0)
              begin
                Set @VlrVerbaSup = @VlrVerbaSup
                Exec PR_AtualizaSaldoVBSSD  @PCodEstabe, @CodSup, @DatMov, 0, @CodPrd, @CodLot, 'E', @TipNfe, '',   '', @PNumPrt, @VlrVerbaSup, 'DEVOLUCAO NF', @Usuario
                if (@@error <> 0)
                  begin
                    if @@trancount > 0
                      RollBack Transaction
                    Return
                  end
              end
          end  -- if @pc_Controle_Saldo = 'V' -- Vendedor/Operador
       
        if @pc_Controle_Saldo = 'F' -- Fabricante
          begin
            -- atualiza verba vendedor
            if (@VlrVerbaVdr <> 0) and (@TipNfe = 'D') and (IsNull(@CodVdr, 0) > 0)
              begin
                Set @VlrVerbaVdr = @VlrVerbaVdr
                Exec PR_AtualizaSaldoVBFSL @PCodEstabe, @CodVdr, @CodFab, @DatMov, 0, @CodPrd, @CodLot, 'E', @TipNfe, '',   '', @PNumPrt, @VlrVerbaVdr, 'DEVOLUCAO NF', @Usuario
                if (@@error <> 0)
                  begin
                    if @@trancount > 0
                      RollBack Transaction
                    Return
                  end
              end
       
            -- atualiza verba Operador
            if (@VlrVerbaOpe <> 0) and (@TipNfe = 'D') and (IsNull(@CodVdrTlmkt, 0) > 0)
              begin
                Set @VlrVerbaOpe = @VlrVerbaOpe
                Exec PR_AtualizaSaldoVBFSL @PCodEstabe, @CodVdrTlmkt, @CodFab, @DatMov, 0, @CodPrd, @CodLot, 'E', @TipNfe, '',   '', @PNumPrt, @VlrVerbaOpe, 'DEVOLUCAO NF', @Usuario
                if (@@error <> 0)
                  begin
                    if @@trancount > 0
                      RollBack Transaction
                    Return
                  end
              end
          end  -- if @pc_Controle_Saldo = 'F' -- Fabricante


        -- atualiza verba fornecedor
        if (@VlrVerbaFor <> 0) and (@CodEmiFor > 0)
          begin
            Set @VlrVerbaFor = -@VlrVerbaFor
            Exec PR_AtualizaSaldoVBFSD @PCodEstabe, @CodEmiFor, @DatMov, 0, @CodPrd, @CodLot, 'E', @TipNfe, '', @PNumPrt, @VlrVerbaFor, 'CANCELAMENTO NF', 'SISTEMA'
            if (@@error <> 0)
              begin
                if @@trancount > 0
                  Rollback Transaction
                Return
              end
          end

        -- atualiza itens na tabela de consignações
        if (@IdConsig > 0) and (@NumSeqCtr > 0) and (dbo.FN_CfopConsigValido(@CodCfo) = 1) 
          begin
            -- NDS = devolucaosimbolica : @FlgFaturaConsig = 1
            -- NDE = devolucao efetiva
            if @FlgFaturaConsig = 1 
              Set @CodTipDevCng = 'NDS'
            else
              Set @CodTipDevCng = 'NDE'

            Set @QtdMov = @QtdPed + @QtdBon

            Exec PR_GravaMovimeCNGMV @PCodEstabe, @IdConsig, @CodPrd, @CodLot,
                                     @DatMov, 'E', @CodTipDevCng, '', @PNumPrt, '', 'C',
                                     @QtdMov, @PrcUni
            if (@@error <> 0)
              begin
                if @@trancount > 0 
                  Rollback Transaction
                Return
              end
          end

        Fetch Next From NFEIT_Cr
          Into @CodPrd, @CodLot, @QtdPed, @QtdBon, @PrcUni,
               @ValLiq, @QtdPrm, @VlrVerbaFor, @ValCusMed, @ValPrcFab,
               @VlrVerbaVdr, @VlrVerbaOpe, @VlrVerbaSup

      end
  
    Close NFEIT_Cr
    Deallocate NFEIT_Cr

    -- cancela duplicatas
    Delete rt
    From PAGRT rt Inner Join
         PAGCT ct on rt.Cod_Estabe = ct.Cod_Estabe And rt.Cod_CtaPag = ct.Cod_CtaPag
    Where ct.Cod_Estabe = @PCodEstabe 
    And ct.Cod_PrtNfe = @PNumPrt

    Delete From PAGCT
      Where Cod_Estabe = @PCodEstabe 
      And Cod_PrtNfe = @PNumPrt

    -- estorna VALES/PCMOV
    Exec PR_EstornaFinNFE @PCodEstabe, @PNumPrt, @Usuario
    if @@error <> 0
      begin
        if @@trancount > 0
          Rollback Transaction
        Return
      end

    -- localiza e cancela a entrada do pedido
    Update pdc
      Set pdc.Dat_Entrada = null
      From PDCCB pdc Inner Join 
           NFECB nfe on pdc.Cod_Estabe = nfe.Cod_Estabe and pdc.Numero = nfe.Cod_Pedido
      Where nfe.Cod_Estabe = @PCodEstabe 
      and nfe.Protocolo = @PNumPrt

    -- acumulador da empresa
    Exec PR_AcuEntNfeCabEmp @PCodEstabe, @PNumPrt, @TipNfe, 'C', @DatMov
    if @@error <> 0
      begin
        if @@trancount > 0
          Rollback Transaction
        Return
      end

    if (@IdConsig > 0) and (@NumSeqCtr > 0)
      begin
        Exec PR_FaturaConsignacao 'E', @PCodEstabe, '', @PNumPrt, @IdConsig, @NumSeqCtr
        if (@@error <> 0)
          begin
            if @@trancount > 0
              Rollback Transaction
            Return
          end
      end

    if @@trancount > 0
      Commit Transaction
  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_FechaNFS]
@PCodEstabe int,
@PSerNot varchar(3),
@PNumNot int,
@PNumSel bigint,
@PNumFrm int

AS

SET ANSI_WARNINGS OFF
SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as Date)

if (Select Status From NFSCB Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota  = @PNumNot) = 'F'
  begin
    RAISERROR('Nota Fiscal já fechada',16,1)
    Return
  end
else
  begin

    -- pegar dados de venda de consignação
    Declare @ns_CodCfo int = 0,
            @ns_CodDep smallint = 0,
            @ns_FlgBlqTrfEstFis bit = 0,
	        @ns_IdConsig int = 0,
            @ns_NumSeqCtr smallint = 0, 
            @ns_NumSeqDev smallint = 0,
            @FlgOpeVdo bit = 0,          -- indica op.triangular, venda à ordem
            @IdOpeVdo int = 0,               -- id da op.triangular
            @SerNotVincOpeVdo varchar(3) = '',
            @NumNotVincOpeVdo int = 0,
            @FlgDevolOpeVdo bit = 0,     -- indica se é devolução op.triangular
            @FlgErr bit = 0,
            @MsgErr varchar(8000) = '',
    		@MsgAlerta varchar(100) = ''
    
    Select @ns_CodCfo = IsNull(ns.Cod_Cfo1,0),
           @ns_CodDep = Case 
                          When IsNull(ns.Cod_DepMovEst,0) = 0 then 
                            IsNull((Select min(Cod_Dep) From TBDEP Where Cod_Estabe = @PCodEstabe),1) 
                          Else IsNull(ns.Cod_DepMovEst,0)
                        End,
           @ns_FlgBlqTrfEstFis = IsNull(cf.Flg_BlqTrfEstFis,0),
	       @ns_IdConsig  = ns.Id_Consig,
           @ns_NumSeqCtr = ns.Num_SequenciaCtr, 
           @ns_NumSeqDev = ns.Num_SeqDev,
           @FlgOpeVdo = IsNull(op.Flg_OpeVdo,0)
      From NFSCB ns
           Left Join TPOPE op on ns.Cod_Ope = op.Cod_Ope
           Left Join TBCFO cf on ns.Cod_Cfo1 = cf.Codigo 
     Where ns.Cod_Estabe = @PCodEstabe
       And Ser_Nota = @PSerNot
       And Num_Nota = @PNumNot

    if CharIndex(cast(@ns_CodCfo as varchar),';5112;5114;6112;6114;') = 0 
      begin
        Set @ns_IdConsig  = 0
        Set @ns_NumSeqCtr = 0
        Set @ns_NumSeqDev = 0
      end

    if Exists(Select it.Num_SeqIte, it.Cod_Produto, it.Cod_Lote, lf.Num_Rua, lf.Num_Col, lf.Num_Niv, lf.Num_Apt, 
                     QtdPed = IsNull(it.Qtd_Produto,0)+ISNULL(it.Qtd_Bonificacao,0), 
                     QtdLot = IsNull(lt.Qtd_Saldo,0) 
              From NFSCB cb Inner Join 
                   NFSIT it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Ser_Nota = it.Ser_Nota) and (cb.Num_Nota = it.Num_Nota)) Left Outer Join 
                   NFSLT lf on it.Cod_Estabe = lf.Cod_Estabe and it.Ser_Nota = lf.Ser_Nota and it.Num_Nota = lf.Num_Nota and 
                               it.Cod_Produto = lf.Cod_Produto and it.Cod_Lote = lf.Cod_Lote and it.Num_SeqIte = lf.Num_SeqIte Left Outer Join 
                   PRLTL lt on lf.Cod_Estabe = lt.Cod_Estabe and lf.Cod_Produto = lt.Cod_Produt and lf.Cod_Lote = lt.Cod_Lote and lf.Cod_Dep = lt.Cod_Dep and 
                               lf.Num_Rua = lt.Num_Rua and lf.Num_Col = lt.Num_Col and lf.Num_Niv = lt.Num_Niv and lf.Num_Apt = lt.Num_Apt 
              Where cb.Cod_Estabe = @PCodEstabe 
              and cb.Ser_Nota = @PSerNot 
              and cb.Num_Nota = @PNumNot 
              and ISNULL(cb.Flg_MovEst,0) = 1
              And ISNULL(cb.Flg_WMS,0) = 1
              And (ISNULL(it.Qtd_Produto,0)+ISNULL(it.Qtd_Bonificacao,0)) > ISNULL(lt.Qtd_Saldo,0)) 
      begin
        Set @FlgErr = 1
        Set @MsgErr = 'Estoque(Armazenagem) insuficente de lote de Produto para completar a operação'
      end

    if Exists(Select it.Cod_Produto, it.Cod_Lote, IsNull(lt.Qtd_Saldo,0) as QtdSldLot, 
                     Sum(IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0)) as QtdTot 
              From NFSCB cb Inner Join 
                   NFSIT it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Ser_Nota = it.Ser_Nota) and (cb.Num_Nota = it.Num_Nota)) Left Outer Join 
                   (Select l1.Cod_Estabe, l1.Cod_Produt, l1.Cod_Lote, Qtd_Saldo=sum(l1.Qtd_Saldo)
                     From (Select Cod_Estabe, Cod_Produt, Cod_Lote, Qtd_Saldo
                             From PRLOT
                            Where Cod_Estabe = @PCodEstabe
                              And Cod_Dep = @ns_CodDep
                              And Qtd_Saldo > 0
                           UNION ALL
                           Select Cod_Estabe, Cod_Produt = Cod_Produto, Cod_Lote, Qtd_Saldo=IsNull(Qtd_Movimento,0)+IsNull(Qtd_ResDep,0)
                             From RESER 
                            Where Cod_Estabe = @PCodEstabe
                              And @ns_IdConsig > 0
                              And IsNull(Id_Consig,0)  = @ns_IdConsig
                              And IsNull(Num_SeqCtr,0) = @ns_NumSeqCtr
                              And IsNull(Num_SeqDev,0) = @ns_NumSeqDev  
                          ) l1
                    Group by l1.Cod_Estabe, l1.Cod_Produt, l1.Cod_Lote) lt on ((it.Cod_Estabe = lt.Cod_Estabe) and (it.Cod_Produto = lt.Cod_Produt) and (it.Cod_Lote = lt.Cod_Lote))
              Where cb.Cod_Estabe = @PCodEstabe 
              and cb.Ser_Nota = @PSerNot 
              and cb.Num_Nota = @PNumNot 
              and ISNULL(cb.Flg_MovEst,0) = 1
              and ISNULL(cb.Flg_WMS,0) = 0
              Group by it.Cod_Produto, it.Cod_Lote, lt.Qtd_Saldo
              Having Sum(IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0)) > IsNull(lt.Qtd_Saldo,0)) 
      begin
        Set @FlgErr = 1
        Set @MsgErr = 'Estoque(Picking) insuficente de lote de Produto para completar a operação'
      end

    -- critica op.triangular
    if @FlgOpeVdo = 1				
      begin
        Exec PR_CriticaOperacaoTriangular @PCodEstabe, @PNumNot, @PSerNot, 'S', @MsgAlerta output, @MsgErr output
		if @MsgErr <> ''
          Set @FlgErr = 1
      end


    if @FlgErr = 1
      begin
        RAISERROR(@MsgErr,16,1)
        Return
      end
    else 
    BEGIN
      Begin Transaction
      -- bloqueia cab da nota
      Update NFSCB 
         Set Qtd_Itens = 0,
             Qtd_PagNf = 0
       Where Cod_Estabe = @PCodEstabe 
         and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
  
      -- variaveis de campos do cabecalho
      Declare @PDatEmi smalldatetime,
              @cb_TipSai varchar(1),
              @cb_StaNot varchar(1),
              @cb_CodRegTri int,
              @cb_CodOpe varchar(3),
              @cb_CodCli int,
              @cb_CodFun int,
              @cb_CodFor int,
              @cb_CodVdr int,
              @cb_CodCfo int,
              @cb_ValNot numeric(18,4),
              @cb_FlgMovEst bit,
              @cb_FlgWMS bit,
              @cb_IdTransacao int,

              @cb_CodCliDevVdo int = 0,
              @cb_CodFunDevVdo int = 0,
              @cb_CodForDevVdo int = 0,
              @cb_CodTraDevVdo int = 0,
              @cb_NumPrtDevVdo int = 0,
              @cb_NumPrtDevVnc int = 0,
              @cb_IdOpeVdoDev  int = 0,

              @WCodDoc int,
              @WValMov numeric(18,4),
              @WCodEmiFor int,
              @WValVrbFor numeric(18,4),
              @WFlgOpeInt bit,
              @Usuario varchar(15)
  
      Select @PDatEmi = @Date,
             @cb_TipSai = cb.Tip_Saida,
             @cb_StaNot = cb.Status,
             @cb_CodRegTri = IsNull(cb.Cod_RegTri,0),
             @cb_CodOpe = IsNull(cb.Cod_Ope,''),
             @cb_CodCli = IsNull(cb.Cod_Cliente,0),
             @cb_CodFun = IsNull(cb.Cod_Funcionario,0),
             @cb_CodFor = IsNull(cb.Cod_Fornecedor,0),
             @cb_CodVdr = IsNull(cb.Cod_Vendedor,0),
             @cb_CodCfo = Isnull(cb.Cod_Cfo1,0),
             @cb_ValNot = IsNull(cb.Vlr_TotalNota,0),
             @cb_FlgMovEst = IsNull(cb.Flg_MovEst,0),
             @cb_FlgWMS = IsNull(cb.Flg_WMS,0),
             @cb_IdTransacao = IsNull(cb.Id_Transacao,0)
        From NFSCB cb
       Where cb.Cod_Estabe = @PCodEstabe 
         and cb.Ser_Nota = @PSerNot 
         and cb.Num_Nota = @PNumNot
  
      Set @Usuario = dbo.FN_UsuarioInfarma()

      -- registra documentos relacionados
      Exec PR_RegistraNSREF @PCodEstabe, @PSerNot, @PNumNot
      if @@error <> 0
        begin
          if @@trancount > 0 
            Rollback Transaction
          Return
        end

      if @FlgOpeVdo = 1
        Exec PR_IncluiOPVDO @PCodEstabe, @PNumNot, @PSerNot, 'S', @IdOpeVdo output

      Set @cb_CodCliDevVdo = 0
      Set @cb_CodForDevVdo = 0
      Set @cb_CodFunDevVdo = 0
      Set @cb_CodTraDevVdo = 0

      if @IdOpeVdo > 0
        Select top 1 
               @SerNotVincOpeVdo = IsNull(rf.Ser_DocRef,0),
               @NumNotVincOpeVdo = IsNull(rf.Num_DocRef,0),
               @FlgDevolOpeVdo   = Case
                                     When cb.Tip_Saida  = 'D' then 1
                                     When cbv.Tip_Saida = 'D' then 1
                                     Else 0
                                   End,
               @cb_CodCliDevVdo  = Case 
                                     When cbv.Tip_Saida = 'D' then IsNull(cbv.Cod_Cliente,0) 
                                     Else 0
                                   End,
               @cb_CodFunDevVdo  = Case 
                                     When cbv.Tip_Saida = 'D' then IsNull(cbv.Cod_Funcionario,0)
                                     Else 0
                                   End,
               @cb_CodForDevVdo  = Case 
                                     When cbv.Tip_Saida = 'D' then IsNull(cbv.Cod_Fornecedor,0)
                                     Else 0
                                   End
          From NFSCB cb
               inner Join NSREF rf  on cb.Cod_Estabe = rf.Cod_Estabe
                                   and cb.Ser_Nota = rf.Ser_Nota 
                                   and cb.Num_Nota = rf.Num_Nota 
                                   and rf.Tip_EntSai = 'S' 
               inner Join NFSCB cbv on cbv.Cod_Estabe = rf.Cod_Estabe
                                   and cbv.Ser_Nota = rf.Ser_DocRef
                                   and cbv.Num_Nota = rf.Num_DocRef
         Where cb.Cod_Estabe = @PCodEstabe
           And cb.Ser_Nota = @PSerNot
           And cb.Num_Nota = @PNumNot

      Declare @cl_CodEst varchar(2),
  	          @cl_TipCon char(1),
              @uf_FlgRegSubTri bit,
              @Uf_BlqInsEstSbtNfs bit,
              @uf_NumInscriSbt varchar(15),
              @em_CodEst varchar(2),
              @pm_NumItePagNfs int,
              @pm_FlgCtrSelFis bit
  
      Select @cl_CodEst = Cod_Estado,
             @cl_TipCon = Tipo_Consumidor
        From CLIEN
       Where Codigo = @cb_CodCli
  
      if @cl_TipCon is null Set @cl_TipCon = '?'
  
      Select @em_CodEst = Des_Estado
        From ESTAB
       Where Cod_Estabe = @PCodEstabe
  
      Select @pm_NumItePagNfs = Isnull(NumItePagNfs,0),
             @pm_FlgCtrSelFis = FlgCtrSelFis
        From PARAM
       Where Cod_Estabe = @PCodEstabe
  
      -- operacao interna ou externa
      if @cl_CodEst = @em_CodEst
        Set @WFlgOpeInt = 1
      else
        Set @WFlgOpeInt = 0
  
      -- coloca campos de UFXES na memoria
      Select @uf_FlgRegSubTri = IsNull(Flg_RegSubTri,0),
             @Uf_BlqInsEstSbtNfs = IsNull(Flg_BlqNumInscriSubTriNfs,0),
             @uf_NumInscriSbt = case 
                                  when (IsNull(Num_InscriSubTri,'') <> '.') and (IsNull(Num_InscriSubTri,'') <> '')  then IsNull(Num_InscriSubTri,'')
                                  else ''
                                end
        From UFXES
       Where Cod_Estabe = @PCodEstabe
         And Cod_UF = @cl_CodEst
  
      if @uf_FlgRegSubTri is null Set @uf_FlgRegSubTri = 0
      if @Uf_BlqInsEstSbtNfs is null Set @Uf_BlqInsEstSbtNfs = 0
      if @uf_NumInscriSbt is null Set @uf_NumInscriSbt = ''
  
      -- coloca campos de RGTRI na memoria
      Declare @rt_FlgDscIcmOrgPub bit,
              @rt_FlgDscIcmOrgPubAcr bit
  
      Select @rt_FlgDscIcmOrgPub = IsNull(Flg_DscIcmOrgPub,0),
             @rt_FlgDscIcmOrgPubAcr = IsNull(Flg_DscIcmOrgPubAcr,0)
        From RGTRI
       Where Cod_RegTri = @cb_CodRegTri
  
      if @rt_FlgDscIcmOrgPub is null
        Set @rt_FlgDscIcmOrgPub = 0
      if @rt_FlgDscIcmOrgPubAcr is null
        Set @rt_FlgDscIcmOrgPubAcr = 0


      Declare @WQtdMov int,
              @WQtdAcc int,
              @PQtdIte int,
              @PQtdPgNf int,
              @PNumInscriSbtEmiUfd varchar(15)
  
      Set @PQtdIte = 0
      Set @PQtdPgNf = 1
  	Set @PNumInscriSbtEmiUfd = ''
  
      Declare @it_CodPrd int,
              @it_CodLot varchar(20),
              @it_SeqIte int, 
              @it_TipSai varchar(1),
              @it_QtdPrd int,
              @it_QtdBon int,
              @it_PrcUni numeric(18,8),
              @PQtdPra int,
              @PQtdDep int,
              @lt_QtdSldPra int,
              @lt_QtdSldDep int,
              @lt_CodDep smallint,
              @lt_NumRua smallint,
              @lt_NumCol smallint,
              @lt_NumNiv smallint,
              @lt_NumApt smallint,
              @lt_QtdEmbFec int,
  
              @WQtdDep int,
              @WQtdPra int,
              @WQtdTot int,
              @WFlgEmpPra bit,
              @WFlgEmpDep bit,
              @WCodOri varchar(20),
              @WCodTipSaiCng varchar(3)
              
      -- normaliza fator de conversao      
      Update NFSIT
         Set Fat_CnvImpFat = 1
       Where Cod_Estabe = @PCodEstabe
         And Ser_Nota = @PSerNot
         And Num_Nota = @PNumNot
         And ISNULL(Fat_CnvImpFat,0) = 0 
          
      Update NFSIT
         Set Qtd_ImpFat = Cast(Qtd_Produto+Qtd_Bonificacao as numeric(18,4))/Fat_CnvImpFat
       Where Cod_Estabe = @PCodEstabe
         And Ser_Nota = @PSerNot
         And Num_Nota = @PNumNot
         And Round(Qtd_ImpFat*100,0) <> Round((Cast(Qtd_Produto+Qtd_Bonificacao as numeric(18,4))/Fat_CnvImpFat)*100,0) 
  
      Update NFSIT
         Set Prc_UniImpFat = Prc_Unitario*Fat_CnvImpFat
       Where Cod_Estabe = @PCodEstabe
         And Ser_Nota = @PSerNot
         And Num_Nota = @PNumNot
         And Round(Prc_UniImpFat*10000,0) <> Round(Prc_Unitario*Fat_CnvImpFat*10000,0)
      
      -- registra p.unitario e desconto pedido venda
      Update NFSIT
         Set Prc_UniPdv = Prc_Unitario,
             Per_DscPdv = Per_Desconto
       Where Cod_Estabe = @PCodEstabe
         And Ser_Nota = @PSerNot
         And Num_Nota = @PNumNot
    
      -- registra custos medio
      Update it 
         Set it.Vlr_CusIte = pr.Prc_CusMed,
             it.Vlr_CusComIte = Case 
                                  When IsNull(pr.Prc_CusMedCom,0) > 0 Then IsNull(pr.Prc_CusMedCom,0) 
                                  Else IsNull(pr.Prc_CusMed,0) 
                                End
       From NFSIT it Inner Join 
            PRXES pr on it.Cod_Estabe = pr.Cod_Estabe And it.Cod_Produto = pr.Cod_Produt 
      Where it.Cod_Estabe = @PCodEstabe
        And it.Ser_Nota = @PSerNot
        And it.Num_Nota = @PNumNot
      
    
      Set @WCodOri = ''
      
      -- se houver movimentacao de estoque:
      if @cb_FlgMovEst = 1
        begin
          if @cb_FlgWMS = 1
            begin
              -- configura cod. origem
              if @cb_TipSai = 'V'
                Set @WCodOri = 'SAI_VEN'
              else  
              if @cb_TipSai = 'D'
                Set @WCodOri = 'SAI_DEV'
              else  
              if @cb_TipSai = 'T'
                Set @WCodOri = 'SAI_TRF'
              else  
              if @cb_TipSai = 'O'
                Set @WCodOri = 'SAI_OUT'
            
              Declare NFSIT_Cr Cursor Local Fast_Forward For 
                Select it.Cod_Produto, it.Cod_Lote, it.Num_SeqIte, IsNull(it.Tip_Sai,''), it.Qtd_Produto, it.Qtd_Bonificacao, 
                       it.Prc_Unitario, IsNull(lt.Qtd_SldPra,0), IsNull(lt.Qtd_SldDep,0), IsNull(lt.Qtd_EmbFec,0), 
                       lf.Cod_Dep, lf.Num_Rua, lf.Num_Col, lf.Num_Niv, lf.Num_Apt
                  From NFSIT it Inner Join 
                       NFSLT lf on it.Cod_Estabe = lf.Cod_Estabe and it.Ser_Nota = lf.Ser_Nota and it.Num_Nota = lf.Num_Nota and 
                                   it.Cod_Produto = lf.Cod_Produto and it.Cod_Lote = lf.Cod_Lote and it.Num_SeqIte = lf.Num_SeqIte Left Outer Join 
                       PRLTL lt on lf.Cod_Estabe = lt.Cod_Estabe and lf.Cod_Produto = lt.Cod_Produt and lf.Cod_Lote = lt.Cod_Lote and lf.Cod_Dep = lt.Cod_Dep and 
                                   lf.Num_Rua = lt.Num_Rua and lf.Num_Col = lt.Num_Col and lf.Num_Niv = lt.Num_Niv and lf.Num_Apt = lt.Num_Apt 
                 Where it.Cod_Estabe = @PCodEstabe 
                   and it.Ser_Nota = @PSerNot 
                   and it.Num_Nota = @PNumNot
            end 
          else
            begin  -- não WMS
              -- se for o caso, elimina reserva ref. consignacao
              Delete From RESER 
               Where Cod_Estabe = @PCodEstabe
                 And @ns_IdConsig > 0
                 And IsNull(Id_Consig,0)  = @ns_IdConsig
                 And IsNull(Num_SeqCtr,0) = @ns_NumSeqCtr
                 And IsNull(Num_SeqDev,0) = @ns_NumSeqDev  
  
              Declare NFSIT_Cr Cursor Local Fast_Forward For 
                Select it.Cod_Produto, it.Cod_Lote, it.Num_SeqIte, IsNull(it.Tip_Sai,''), it.Qtd_Produto, it.Qtd_Bonificacao, 
                       it.Prc_Unitario, IsNull(lt.Qtd_SldPra,0), IsNull(lt.Qtd_SldDep,0), 0, 
                       IsNull(lt.Cod_Dep,1), 0, 0, 0, 0
                  From NFSIT it Left Outer Join 
                       PRLOT lt on ((it.Cod_Estabe = lt.Cod_Estabe) and (lt.Cod_Dep = @ns_CodDep) and (it.Cod_Produto = lt.Cod_Produt) and (it.Cod_Lote = lt.Cod_Lote))
                 Where it.Cod_Estabe = @PCodEstabe 
                   and it.Ser_Nota = @PSerNot 
                   and it.Num_Nota = @PNumNot 
            end
  
          Open NFSIT_Cr
          Fetch Next From NFSIT_Cr
            Into @it_CodPrd, @it_CodLot, @it_SeqIte, @it_TipSai, @it_QtdPrd, @it_QtdBon, @it_PrcUni,
                 @lt_QtdSldPra, @lt_QtdSldDep, @lt_QtdEmbFec, @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt
  
          While @@FETCH_STATUS = 0
            begin
              Set @PQtdPra = 0
              Set @PQtdDep = 0
              Set @WQtdAcc = @it_QtdPrd+@it_QtdBon
              if @cb_CodCfo > 0 
                begin
                  if @lt_QtdSldPra >= @WQtdAcc
                    Set @WQtdMov = @WQtdAcc
                  else
                    Set @WQtdMov = @lt_QtdSldPra
                  Set @PQtdPra = @PQtdPra + @WQtdMov
                  Set @lt_QtdSldPra = @lt_QtdSldPra - @WQtdMov
                  Set @WQtdAcc = @WQtdAcc - @WQtdMov
                end
              else
                begin
                  if @lt_QtdSldDep >= @WQtdAcc
                    Set @WQtdMov = @WQtdAcc
                  else
                    Set @WQtdMov = @lt_QtdSldDep
                  Set @PQtdDep = @PQtdDep + @WQtdMov
                  Set @lt_QtdSldDep = @lt_QtdSldDep - @WQtdMov
                  Set @WQtdAcc = @WQtdAcc - @WQtdMov
                end
             
              if (@WQtdAcc > 0) and (@lt_QtdSldPra > 0)
                begin
                  if @lt_QtdSldPra >= @WQtdAcc
                    Set @WQtdMov = @WQtdAcc
                  else
                    Set @WQtdMov = @lt_QtdSldPra
                  Set @PQtdPra = @PQtdPra + @WQtdMov
                  Set @lt_QtdSldPra = @lt_QtdSldPra - @WQtdMov          
                  Set @WQtdAcc = @WQtdAcc - @WQtdMov
                end
  
              if (@WQtdAcc > 0) and (@lt_QtdSldDep > 0)
                begin
                  if @lt_QtdSldDep >= @WQtdAcc
                    Set @WQtdMov = @WQtdAcc
                  else
                    Set @WQtdMov = @lt_QtdSldDep
                  Set @PQtdDep = @PQtdDep + @WQtdMov
                  Set @lt_QtdSldDep = @lt_QtdSldDep - @WQtdMov          
                  Set @WQtdAcc = @WQtdAcc - @WQtdMov
                end
  
              if (@PQtdPra+@PQtdDep) <> (@it_QtdPrd+@it_QtdBon)
                begin
                  if @@trancount > 0 
                    Rollback Transaction
                  RAISERROR('Inconsistência entre quantidade saída e quantidade dos lotes',16,1)
                  Return
                end
  
              -- normaliza campos
              if @PQtdPra is null
                Set @PQtdPra = 0
              if @PQtdDep is null
                Set @PQtdDep = 0
              if (@PQtdPra+@PQtdDep) <> (@it_QtdPrd+@it_QtdBon)
                begin
                  Set @PQtdPra = @it_QtdPrd + @it_QtdBon - @PQtdDep
                end
            
              -- atualiza quantidades de lotes
              Update NFSIT
                 Set Qtd_Pra = @PQtdPra,
                     Qtd_Dep = @PQtdDep,
                     Transacao = @Now
               Where Cod_Estabe = @PCodEstabe 
                 and Ser_Nota = @PSerNot 
                 and Num_Nota = @PNumNot              
                 and Cod_Produto = @it_CodPrd
                 and Cod_Lote = @it_CodLot
                 and Num_SeqIte = @it_SeqIte
                
              if @cb_FlgWMS = 1
                Update NFSLT
                   Set Qtd_LotePra = @PQtdPra,
                       Qtd_LoteDep = @PQtdDep,
                       Transacao = @Now
                 Where Cod_Estabe = @PCodEstabe 
                   and Ser_Nota = @PSerNot 
                   and Num_Nota = @PNumNot              
                   and Cod_Produto = @it_CodPrd
                   and Cod_Lote = @it_CodLot
                   and Num_SeqIte = @it_SeqIte
                
              -- configura flag de emprestimo de estoque
              Set @WFlgEmpPra = 0
              Set @WFlgEmpDep = 0
              if (@cb_CodCfo > 0) and (@PQtdDep > 0)
                Set @WFlgEmpDep = 1 
              if (@cb_CodCfo = 0) and (@PQtdPra > 0)
                Set @WFlgEmpPra = 1 
  
              -- atualiza saldo estoque
              Set @WQtdPra = @PQtdPra * (-1)       
              Set @WQtdDep = @PQtdDep * (-1)       
              
              if @cb_FlgWMS = 1
                begin
                  -- registra log saida
                  Set @WQtdTot = @WQtdPra + @WQtdDep
                  
                  Exec PR_InserePRLOG @PCodEstabe, @it_CodPrd, @it_CodLot, @lt_CodDep, 
                                      @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt,
                                      @WQtdTot, @WCodOri, '', @PSerNot, @PNumNot, '', @Usuario
                  if @@error <> 0
                    begin
                      if @@trancount > 0 
                        Rollback Transaction
                      Return
                    end    
                  
                  EXEC PR_AtualizaSaldoEstoqueGrosso @PCodEstabe, @it_CodPrd, @it_CodLot, @lt_QtdEmbFec, @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt,
                                                     @PDatEmi, 'S', @cb_TipSai, @WQtdPra, @WFlgEmpPra, @WQtdDep, @WFlgEmpDep
                end                                     
              else
                EXEC PR_AtualizaSaldoEstoque 'NF', @PCodEstabe, @lt_CodDep, @it_CodPrd, @it_CodLot, @PDatEmi, 'S', @cb_TipSai, @WQtdPra, @WFlgEmpPra, @WQtdDep, @WFlgEmpDep
              if @@error <> 0
                begin
                  if @@trancount > 0 
                    Rollback Transaction
                  Return
                end
  
              -- estorno de verba do fornecedor aqui 1
              Set @WValVrbFor = 0
              Set @WCodEmiFor = 0
  
              if (@cb_TipSai = 'D') and (@cb_FlgMovEst = 1) and
                 Exists(Select top 1 1  -- NF Entrada de compra vinculada
                          From NSREF r
                               Inner Join NFECB cb on r.Cod_Estabe = cb.Cod_Estabe and r.Num_DocRef = cb.Protocolo
                               Inner Join NFEIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Protocolo = it.Protocolo And it.Cod_Produto = @it_CodPrd And it.Cod_Lote = @it_CodLot
                         Where r.Cod_Estabe = @PCodEstabe
                           And r.Ser_Nota = @PSerNot
                           And r.Num_Nota = @PNumNot
                           And r.Tip_EntSai = 'E'
                           And cb.Cod_EmiFornec > 0
                           And IsNull(it.Vlr_DscIte2,0) <> 0
                           And it.Qtd_Pedido > 0)
                begin
                  Select top 1 @WCodEmiFor = cb.Cod_EmiFornec,
  				             @WValVrbFor = (it.Vlr_DscIte2/it.Qtd_Pedido)
                   From NSREF r
                        Inner Join NFECB cb on r.Cod_Estabe = cb.Cod_Estabe and r.Num_DocRef = cb.Protocolo
                        Inner Join NFEIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Protocolo = it.Protocolo And it.Cod_Produto = @it_CodPrd And it.Cod_Lote = @it_CodLot
                  Where r.Cod_Estabe = @PCodEstabe
                    And r.Ser_Nota = @PSerNot
                    And r.Num_Nota = @PNumNot
                    And r.Tip_EntSai = 'E'
                    And cb.Cod_EmiFornec > 0
                    And IsNull(it.Vlr_DscIte2,0) <> 0
                    And it.Qtd_Pedido > 0
                end
  
              -- Op.Triangular  aqui ???
              if (@WCodEmiFor = 0) and
                 (@FlgDevolOpeVdo = 1) and (@cb_FlgMovEst = 0) and
                 Exists(Select top 1 1  -- NF Entrada de compra vinculada à NF de saída vinculada
                          From NSREF r
                               Inner Join NFECB cb on r.Cod_Estabe = cb.Cod_Estabe and r.Num_DocRef = cb.Protocolo
                               Inner Join NFEIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Protocolo = it.Protocolo And it.Cod_Produto = @it_CodPrd And it.Cod_Lote = @it_CodLot
                         Where r.Cod_Estabe = @PCodEstabe
                           And r.Ser_Nota = @SerNotVincOpeVdo
                           And r.Num_Nota = @NumNotVincOpeVdo
                           And r.Tip_EntSai = 'E'
                           And cb.Cod_EmiFornec > 0
                           And IsNull(it.Vlr_DscIte2,0) <> 0
                           And it.Qtd_Pedido > 0)
                begin
                  Select top 1 @WCodEmiFor = cb.Cod_EmiFornec,
  				             @WValVrbFor = (it.Vlr_DscIte2/it.Qtd_Pedido)
                   From NSREF r
                        Inner Join NFECB cb on r.Cod_Estabe = cb.Cod_Estabe and r.Num_DocRef = cb.Protocolo
                        Inner Join NFEIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Protocolo = it.Protocolo And it.Cod_Produto = @it_CodPrd And it.Cod_Lote = @it_CodLot
                  Where r.Cod_Estabe = @PCodEstabe
                    And r.Ser_Nota = @SerNotVincOpeVdo
                    And r.Num_Nota = @NumNotVincOpeVdo
                    And r.Tip_EntSai = 'E'
                    And cb.Cod_EmiFornec > 0
                    And IsNull(it.Vlr_DscIte2,0) <> 0
                    And it.Qtd_Pedido > 0
                end

              -- estorna verba fornecedor
              if (@WValVrbFor <> 0) and (@WCodEmiFor > 0)
                begin
                  Set @WValVrbFor = -Round(@WValVrbFor*@it_QtdPrd,2)
                  Exec PR_AtualizaSaldoVBFSD @PCodEstabe, @WCodEmiFor, @PDatEmi, 0, @it_CodPrd, @it_CodLot, 'S', @cb_TipSai, @PSerNot, @PNumNot, @WValVrbFor, 'DEVOLUÇÃO NF', 'SISTEMA'
                  if (@@error <> 0)
                    begin
                      if @@trancount > 0 
                        Rollback Transaction
                      Return
                    end
                end
  
              -- grava movimento relativo a venda(somente) em consignação: CFOP: 5112/6112, 5113/6113, 5114/6114 
              if (@ns_IdConsig > 0) and (@ns_NumSeqCtr > 0) and (dbo.FN_CfopConsigValido(@cb_CodCfo) = 1) 
                begin
                  if dbo.FN_TipoNFConsig(@cb_CodCfo) = 'V'
                    Set @WCodTipSaiCng = 'NFF'
  				else
                    Set @WCodTipSaiCng = 'NFR'
  
                  Exec PR_GravaMovimeCNGMV @PCodEstabe, @ns_IdConsig, @it_CodPrd, @it_CodLot,
                                           @PDatEmi, 'S', @WCodTipSaiCng, @PSerNot, @PNumNot, @it_TipSai, 'F', 
                                           @WQtdMov, @it_PrcUni
                  if (@@error <> 0)
                    begin
                      if @@trancount > 0 
                        Rollback Transaction
                      Return
                    end
                end
  
              Fetch Next From NFSIT_Cr
                Into @it_CodPrd, @it_CodLot, @it_SeqIte, @it_TipSai, @it_QtdPrd, @it_QtdBon, @it_PrcUni,  
                     @lt_QtdSldPra, @lt_QtdSldDep, @lt_QtdEmbFec, @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt
  
              Set @PQtdIte = @PQtdIte + 1
            end
  
          Close NFSIT_Cr
          Deallocate NFSIT_Cr
  
        end  -- if @cb_FlgMovEst = 1
  
      if @PQtdIte = 0
        Set @PQtdIte = Isnull((Select count(*) From NFSIT Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot),0)
  
      if @PQtdIte > 0
        Set @PQtdPgNf = Ceiling(@PQtdIte*1.00 /@pm_NumItePagNfs)
  
      Update NMFIS
         Set Formulario_M1 = @PNumFrm + @PQtdPgNf - 1,
             Selo_Fiscal = case 
                             When @Pm_FlgCtrSelFis = 1 then @PNumSel + @PQtdPgNf - 1
                             else Selo_Fiscal + 0
                           end
       Where Cod_Estabe = @PCodEstabe                  
  
      -- registra Insc.Est. ST do emitente na UF destino em op. interestaduais
      if (@WFlgOpeInt = 0) and (@uf_FlgRegSubTri= 1) and (@uf_BlqInsEstSbtNfs = 0)
        Set @PNumInscriSbtEmiUfd = @uf_NumInscriSbt
      else
        Set @PNumInscriSbtEmiUfd = ''
  
      Update NFSCB
         Set Dat_Emissao = @PDatEmi,
             Qtd_Itens = @PQtdIte,
             Qtd_PagNf = @PQtdPgNf,
             Num_Formulario = (Select Formulario_M1 from NMFIS Where Cod_Estabe = @PCodEstabe),
             Flg_BlqTrfEstFis = IsNull(@ns_FlgBlqTrfEstFis,0),
             Cod_Agente = (Select CodAgeCobCar from PARAM Where Cod_Estabe = @PCodEstabe),
             Num_InscriSubTriEmiUfd = @PNumInscriSbtEmiUfd,
             Status = 'F',
             Id_OpeVdo = @IdOpeVdo,
             Transacao = @Now,
             Ser_Selo = case 
                          When @Pm_FlgCtrSelFis = 1 then (Select SerieSeloFiscal from PARAM Where Cod_Estabe = @PCodEstabe)
                          else null
                        end,
             Num_Selo = case 
                          When @Pm_FlgCtrSelFis = 1 then (Select Selo_Fiscal from NMFIS Where Cod_Estabe = @PCodEstabe)
                          else 0
                        end
       Where Cod_Estabe = @PCodEstabe 
         and Ser_Nota = @PSerNot 
         and Num_Nota = @PNumNot
  
      if @IdOpeVdo > 0
        Update NFSCB
           Set Id_OpeVdo = @IdOpeVdo
         Where Cod_Estabe = @PCodEstabe 
           and Ser_Nota = @SerNotVincOpeVdo
           and Num_Nota = @NumNotVincOpeVdo

      --  atualiza CFOp dos itens
      if Exists(Select top 1 Cod_Cfo From NFSIT
                 Where Cod_Estabe = @PCodEstabe 
                  and Ser_Nota = @PSerNot 
                  and Num_Nota = @PNumNot 
                  and IsNull(Cod_Cfo,0) = 0)
        begin
          Exec PR_AtualizaCFOpItemNf @PCodEstabe, @PSerNot, @PNumNot
          if @@error <> 0
            begin
              if @@trancount > 0 
                Rollback Transaction
              Return
            end
        end
  
      if @PQtdIte > 0
        begin
          -- atualiza Cfop do cabecalho com o do item de maior valor
          Exec PR_AtualizaCfopNFSCB @PCodEstabe, @PSerNot, @PNumNot
          if @@error <> 0
            begin
              if @@trancount > 0 
                Rollback Transaction
              Return
            end
        end
  
      -- ver se transfere saldos de PRSLD
      Exec PR_TransfEstNFS @PCodEstabe, @PSerNot, @PNumNot
      if @@error <> 0
        begin
          if @@trancount > 0 
            Rollback Transaction
          Return
        end
  
      -- atualiza estatisticas
      Exec PR_AtualizaEstatisticasNFS @PCodEstabe, @PSerNot, @PNumNot, 'F'
      if @@error <> 0
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end
  
      -- recalcula NF se orgao publico com desconto ICMS
      if ((@rt_FlgDscIcmOrgPub = 1) or (@rt_FlgDscIcmOrgPubAcr = 1)) and ((@cl_TipCon = 'P') or (@cl_TipCon = 'E') or (@cl_TipCon = 'M'))
        begin
          EXEC PR_RecalculaNFSCB @PCodEstabe, @PSerNot, @PNumNot
          if (@@error <> 0)
            begin
              if @@trancount > 0 
                Rollback Transaction
              Return
            end
        end  
  
      Select @cb_ValNot = IsNull(Vlr_TotalNota,0)
        From NFSCB
       Where Cod_Estabe = @PCodEstabe 
         and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
     
      -- gera vales (devolucao)
      -- coloca campos TPOPE na memoria
      Declare @to_IsnCtaFinDeb int,
              @to_IsnCtaFinCre int,
              @to_IsnCtaFinCreInterv int,
              @to_IsnCtaFinDebInterv int,
              @WTipEntid varchar(3),
              @WCodEntid int,
              @WIsnCtaFinEntid int,
              @pm_FlgUsaInterv bit

      Select @pm_FlgUsaInterv = IsNull(FlgUsaInterv,0)
        From PMFIN
                  
      Select @to_IsnCtaFinDeb = ISNULL(Isn_CtaFinDeb,0),
             @to_IsnCtaFinCre = ISNULL(Isn_CtaFinCre,0)
        From TPOPE
       Where Cod_Ope = @cb_CodOpe
        
      Set @WTipEntid = ''
      Set @WCodEntid = 0
      Set @WIsnCtaFinEntid = 0

	  Declare @WCodCliAux int = 0,
              @WCodFunAux int = 0,
              @WCodForAux int = 0

     --------------------------------------------------------------------------------------------------

      if ((@cb_TipSai = 'D') or (@FlgDevolOpeVdo = 1)) and (@cb_FlgMovEst = 1) 
        begin
		  -- qual entidade gerar vale de débito
          -- OP.Triangular gerar vale de débito para entidade que gerou lançamento financeiro em PAGCT
          Set @cb_NumPrtDevVdo = 0
          Set @cb_NumPrtDevVnc = 0
          Set @cb_IdOpeVdoDev = 0

          if @FlgDevolOpeVdo = 1 
            begin
              -- verifica NFE vinculadas
              if Exists(Select top 1 cb.Protocolo  -- NF Entrada vinculada
                          From NSREF r
                               Inner Join NFECB cb on r.Cod_Estabe = cb.Cod_Estabe and r.Num_DocRef = cb.Protocolo
                         Where r.Cod_Estabe = @PCodEstabe
                           And r.Ser_Nota = @PSerNot
                           And r.Num_Nota = @PNumNot
                           And r.Tip_EntSai = 'E'
                           And IsNull(cb.Id_OPeVdo,0) > 0)
                begin
                  Select top 1 @cb_NumPrtDevVdo = cb.Protocolo,  -- NF Entrada vinculada
                               @cb_IdOpeVdoDev  = cb.Id_OpeVdo
                    From NSREF r
                         Inner Join NFECB cb on r.Cod_Estabe = cb.Cod_Estabe and r.Num_DocRef = cb.Protocolo
                   Where r.Cod_Estabe = @PCodEstabe
                     And r.Ser_Nota = @PSerNot
                     And r.Num_Nota = @PNumNot
                     And r.Tip_EntSai = 'E'
                     And IsNull(cb.Id_OPeVdo,0) > 0
      	    
                  if Exists (Select 1 From PAGCT Where Cod_Estabe = @PCodEstabe and Cod_PrtNfe = @cb_NumPrtDevVdo)
                    Select top 1 @cb_CodForDevVdo = cb.Cod_EmiFornec,
                                 @cb_CodCliDevVdo = cb.Cod_EmiCliente,
                                 @cb_CodTraDevVdo = cb.Cod_EmiTransp
                      From NFECB cb
                     Where Cod_Estabe = @PCodEstabe
                       And Protocolo = @cb_NumPrtDevVdo
                  else
                  if Exists(Select top 1 1
                              From NFECB cb
                             Where Cod_Estabe = @PCodEstabe
                               And Id_OPeVdo = @cb_IdOpeVdoDev
	   	    		         And Protocolo <> @cb_NumPrtDevVdo
                               And Exists (Select 1 From PAGCT Where Cod_Estabe = @PCodEstabe and Cod_PrtNfe = cb.Protocolo))
                    begin
                      Select top 1 @cb_CodForDevVdo = cb.Cod_EmiFornec,
                                   @cb_CodCliDevVdo = cb.Cod_EmiCliente,
                                   @cb_CodTraDevVdo = cb.Cod_EmiTransp
                        From NFECB cb
                       Where Cod_Estabe = @PCodEstabe
                         And Id_OPeVdo = @cb_IdOpeVdoDev
	   	    		   And Protocolo <> @cb_NumPrtDevVdo
                         And Exists (Select 1 From PAGCT Where Cod_Estabe = @PCodEstabe and Cod_PrtNfe = cb.Protocolo)
                    end
      	    
                end -- if Exists(

              else
              -- verifica NFE vinculadas à NFS vinculada
              if Exists(Select top 1 cb.Protocolo  -- NF Entrada vinculada
                          From NSREF r
                               Inner Join NFECB cb on r.Cod_Estabe = cb.Cod_Estabe and r.Num_DocRef = cb.Protocolo
                         Where r.Cod_Estabe = @PCodEstabe
                           And r.Ser_Nota = @SerNotVincOpeVdo
                           And r.Num_Nota = @NumNotVincOpeVdo
                           And r.Tip_EntSai = 'E'
                           And IsNull(cb.Id_OPeVdo,0) > 0)
                begin
                  Select top 1 @cb_NumPrtDevVdo = cb.Protocolo,  -- NF Entrada vinculada
                               @cb_IdOpeVdoDev  = cb.Id_OpeVdo
                    From NSREF r
                         Inner Join NFECB cb on r.Cod_Estabe = cb.Cod_Estabe and r.Num_DocRef = cb.Protocolo
                   Where r.Cod_Estabe = @PCodEstabe
                     And r.Ser_Nota = @SerNotVincOpeVdo
                     And r.Num_Nota = @NumNotVincOpeVdo
                     And r.Tip_EntSai = 'E'
                     And IsNull(cb.Id_OPeVdo,0) > 0
      	    
                  if Exists (Select 1 From PAGCT Where Cod_Estabe = @PCodEstabe and Cod_PrtNfe = @cb_NumPrtDevVdo)
                    Select top 1 @cb_CodForDevVdo = cb.Cod_EmiFornec,
                                 @cb_CodCliDevVdo = cb.Cod_EmiCliente,
                                 @cb_CodTraDevVdo = cb.Cod_EmiTransp
                      From NFECB cb
                     Where Cod_Estabe = @PCodEstabe
                       And Protocolo = @cb_NumPrtDevVdo
                  else
                  if Exists(Select top 1 1
                              From NFECB cb
                             Where Cod_Estabe = @PCodEstabe
                               And Id_OPeVdo = @cb_IdOpeVdoDev
	   	    		         And Protocolo <> @cb_NumPrtDevVdo
                               And Exists (Select 1 From PAGCT Where Cod_Estabe = @PCodEstabe and Cod_PrtNfe = cb.Protocolo))
                    begin
                      Select top 1 @cb_CodForDevVdo = cb.Cod_EmiFornec,
                                   @cb_CodCliDevVdo = cb.Cod_EmiCliente,
                                   @cb_CodTraDevVdo = cb.Cod_EmiTransp
                        From NFECB cb
                       Where Cod_Estabe = @PCodEstabe
                         And Id_OPeVdo = @cb_IdOpeVdoDev
	   	    		   And Protocolo <> @cb_NumPrtDevVdo
                         And Exists (Select 1 From PAGCT Where Cod_Estabe = @PCodEstabe and Cod_PrtNfe = cb.Protocolo)
                    end
      	    
                end -- if Exists(

            end  --  if @FlgDevolOpeVdo = 1 
		  -- fim da entidade ref. NFE que gerou Financeiro (PAGCT) -----------------


          if ((@cb_CodCliDevVdo > 0) or (@cb_CodFunDevVdo > 0) or (@cb_CodForDevVdo > 0))
            begin
              Set @WCodCliAux = @cb_CodCliDevVdo
              Set @WCodForAux = @cb_CodForDevVdo
              Set @WCodFunAux = @cb_CodFunDevVdo
            end
          else
            begin
              Set @WCodCliAux = @cb_CodCli
              Set @WCodForAux = @cb_CodFor
              Set @WCodFunAux = @cb_CodFun
            end

          if @WCodCliAux > 0  
            begin
              Set @WTipEntid = 'CLI'
              Set @WCodEntid = @WCodCliAux
              Set @WIsnCtaFinEntid = IsNull((Select Isn_CtaFin From CLIEN Where Codigo = @WCodCliAux),0)
            end
          else  
          if @WCodForAux > 0
            begin
              Set @WTipEntid = 'FOR'
              Set @WCodEntid = @WCodForAux
              Set @WIsnCtaFinEntid = IsNull((Select Isn_CtaFin From FORNE Where Codigo = @WCodForAux),0)
            end
          else
          if @WCodFunAux > 0  
            begin
              Set @WTipEntid = 'FUN'
              Set @WCodEntid = @WCodFunAux
              Set @WIsnCtaFinEntid = IsNull((Select Isn_CtaFin From FUNCI Where Codigo = @WCodFunAux),0)
            end
          else
          if @cb_CodTraDevVdo > 0  
            begin
              Set @WTipEntid = 'TRA'
              Set @WCodEntid = @cb_CodTraDevVdo
              Set @WIsnCtaFinEntid = IsNull((Select Isn_CtaFin From TRANS Where Codigo = @WCodFunAux),0)
            end

          -- plano de contas
          Set @to_IsnCtaFinCreInterv = 0
          Set @to_IsnCtaFinDebInterv = 0
          if @pm_FlgUsaInterv = 1
            begin
              if (@to_IsnCtaFinCre = (Select IsnCtaFinRecCli From PMFIN)) and (@WCodCliAux > 0)
                Set @to_IsnCtaFinCreInterv = @WIsnCtaFinEntid
                        
              if (@to_IsnCtaFinCre = (Select IsnCtaFinPagFor From PMFIN)) and (@WCodForAux > 0)
                Set @to_IsnCtaFinCreInterv = @WIsnCtaFinEntid
                        
              if (@to_IsnCtaFinCre = (Select IsnCtaFinPagFun From PMFIN)) and (@WCodFunAux > 0)
                Set @to_IsnCtaFinCreInterv = @WIsnCtaFinEntid
                    
              if (@to_IsnCtaFinCre = (Select IsnCtaFinPagTra From PMFIN)) and (@cb_CodTraDevVdo > 0)
                Set @to_IsnCtaFinCreInterv = @WIsnCtaFinEntid
					    
              if @to_IsnCtaFinCreInterv > 0
                Set @to_IsnCtaFinCre = @to_IsnCtaFinCreInterv 
                    


              if (@to_IsnCtaFinDeb = (Select IsnCtaFinRecCli From PMFIN)) and (@WCodCliAux > 0)
                Set @to_IsnCtaFinDebInterv = @WIsnCtaFinEntid
                        
              if (@to_IsnCtaFinDeb = (Select IsnCtaFinPagFor From PMFIN)) and (@WCodForAux > 0)
                Set @to_IsnCtaFinDebInterv = @WIsnCtaFinEntid
                        
              if (@to_IsnCtaFinDeb = (Select IsnCtaFinPagFun From PMFIN)) and (@WCodFunAux > 0)
                Set @to_IsnCtaFinDebInterv = @WIsnCtaFinEntid

              if (@to_IsnCtaFinDeb = (Select IsnCtaFinPagTra From PMFIN)) and (@cb_CodTraDevVdo > 0)
                Set @to_IsnCtaFinDebInterv = @WIsnCtaFinEntid
                        
              if @to_IsnCtaFinDebInterv > 0
                Set @to_IsnCtaFinDeb = @to_IsnCtaFinDebInterv 
                    
      
              if not Exists(Select 1 From PCFIN Where Isn_CtaFin = @to_IsnCtaFinCre And Tip_CtaFin = 'A')
                Set @to_IsnCtaFinCre = 0
              if not Exists(Select 1 From PCFIN Where Isn_CtaFin = @to_IsnCtaFinDeb And Tip_CtaFin = 'A')
                Set @to_IsnCtaFinDeb = 0
      
              if (@to_IsnCtaFinDeb = 0) or (@to_IsnCtaFinCre = 0)
                begin
                  if @@trancount > 0 
                    Rollback Transaction
                  RAISERROR('Pelo menos uma conta gerencial envolvida é inválida',16,1)
                  Return
                end              
               
              if (@cb_TipSai = 'D') and (@cb_FlgMovEst = 1) and
                 not Exists(Select pm.IsnCtaFinRecVal 
                            From PMFIN pm Inner Join
                                 PCFIN pc on pm.IsnCtaFinRecVal  = pc.Isn_CtaFin
                            Where pc.Tip_CtaFin = 'A')     
                begin
                  if @@trancount > 0 
                    Rollback Transaction
                  RAISERROR('Parâmetro Financeiro Conta (CREDITOS A RECEBER) não configurada',16,1)
                  Return
                end              
            end  -- if @pm_FlgUsaInterv = 1
          else
            begin
              Set @to_IsnCtaFinCre = 0
              Set @to_IsnCtaFinDeb = @WIsnCtaFinEntid
            end

          -- Parametro: Creditos a receber
          if @pm_FlgUsaInterv = 1
            Set @to_IsnCtaFinDeb = (Select pm.IsnCtaFinRecVal 
                                      From PMFIN pm Inner Join
                                           PCFIN pc on pm.IsnCtaFinRecVal  = pc.Isn_CtaFin
                                     Where pc.Tip_CtaFin = 'A')
  
          EXEC PR_ProxNumero 'Vale', @WCodDoc output
          if @@error <> 0
            begin
              if @@trancount > 0 
                Rollback Transaction
              Return
            end
  
          -- inclui vale
          Insert into VALES
            (Cod_Estabe, Cod_Vale, Des_Vale, Tip_Entid, Cod_Entid, Dat_Emissa, Val_Vale, Deb_Cre, 
             Cod_CtrLanAut, Ser_CtrLanAut, Num_CtrLanAut, Isn_CtaFinEntid, Isn_CtaFinDeb, Isn_CtaFinCre, Usuario, Transacao)
          Values
            (@PCodEstabe, @WCodDoc,'NFS Devolucao: '+@PSerNot+'/'+cast(@PNumNot as varchar), @WTipEntid, @WCodEntid, @Date, @cb_ValNot, 'D',
             'DNS', @PSerNot, @PNumNot, @WIsnCtaFinEntid, @to_IsnCtaFinDeb, @to_IsnCtaFinCre, @Usuario, @Now)

        end  -- if (@cb_TipSai = 'D') and (@cb_FlgMovEst = 1)
      else
        begin

          if ((@cb_CodCliDevVdo > 0) or (@cb_CodFunDevVdo > 0) or (@cb_CodForDevVdo > 0))
            begin
              Set @WCodCliAux = @cb_CodCliDevVdo
              Set @WCodForAux = @cb_CodForDevVdo
              Set @WCodFunAux = @cb_CodFunDevVdo
            end
          else
            begin
              Set @WCodCliAux = @cb_CodCli
              Set @WCodForAux = @cb_CodFor
              Set @WCodFunAux = @cb_CodFun
            end

          if @WCodCliAux > 0  
            begin
              Set @WTipEntid = 'CLI'
              Set @WCodEntid = @WCodCliAux
              Set @WIsnCtaFinEntid = IsNull((Select Isn_CtaFin From CLIEN Where Codigo = @WCodCliAux),0)
            end
          else  
          if @WCodForAux > 0
            begin
              Set @WTipEntid = 'FOR'
              Set @WCodEntid = @WCodForAux
              Set @WIsnCtaFinEntid = IsNull((Select Isn_CtaFin From FORNE Where Codigo = @WCodForAux),0)
            end
          else
          if @WCodFunAux > 0  
            begin
              Set @WTipEntid = 'FUN'
              Set @WCodEntid = @WCodFunAux
              Set @WIsnCtaFinEntid = IsNull((Select Isn_CtaFin From FUNCI Where Codigo = @WCodFunAux),0)
            end

          -- plano de contas
          Set @to_IsnCtaFinCreInterv = 0
          Set @to_IsnCtaFinDebInterv = 0
          if @pm_FlgUsaInterv = 1
            begin
              if (@to_IsnCtaFinCre = (Select IsnCtaFinRecCli From PMFIN)) and (@WCodCliAux > 0)
                Set @to_IsnCtaFinCreInterv = @WIsnCtaFinEntid
                        
              if (@to_IsnCtaFinCre = (Select IsnCtaFinPagFor From PMFIN)) and (@WCodForAux > 0)
                Set @to_IsnCtaFinCreInterv = @WIsnCtaFinEntid
                        
              if (@to_IsnCtaFinCre = (Select IsnCtaFinPagFun From PMFIN)) and (@WCodFunAux > 0)
                Set @to_IsnCtaFinCreInterv = @WIsnCtaFinEntid
                        
              if @to_IsnCtaFinCreInterv > 0
                Set @to_IsnCtaFinCre = @to_IsnCtaFinCreInterv 
                    
                    
              if (@to_IsnCtaFinDeb = (Select IsnCtaFinRecCli From PMFIN)) and (@WCodCliAux > 0)
                Set @to_IsnCtaFinDebInterv = @WIsnCtaFinEntid
                        
              if (@to_IsnCtaFinDeb = (Select IsnCtaFinPagFor From PMFIN)) and (@WCodForAux > 0)
                Set @to_IsnCtaFinDebInterv = @WIsnCtaFinEntid
                        
              if (@to_IsnCtaFinDeb = (Select IsnCtaFinPagFun From PMFIN)) and (@WCodFunAux > 0)
                Set @to_IsnCtaFinDebInterv = @WIsnCtaFinEntid
                        
              if @to_IsnCtaFinDebInterv > 0
                Set @to_IsnCtaFinDeb = @to_IsnCtaFinDebInterv 
                    
      
              if not Exists(Select 1 From PCFIN Where Isn_CtaFin = @to_IsnCtaFinCre And Tip_CtaFin = 'A')
                Set @to_IsnCtaFinCre = 0
              if not Exists(Select 1 From PCFIN Where Isn_CtaFin = @to_IsnCtaFinDeb And Tip_CtaFin = 'A')
                Set @to_IsnCtaFinDeb = 0
      
              if (@to_IsnCtaFinDeb = 0) or (@to_IsnCtaFinCre = 0)
                begin
                  if @@trancount > 0 
                    Rollback Transaction
                  RAISERROR('Pelo menos uma conta gerencial envolvida é inválida',16,1)
                  Return
                end              
     
              if (@cb_TipSai = 'D') and (@cb_FlgMovEst = 1) and            
                 not Exists(Select pm.IsnCtaFinRecVal 
                            From PMFIN pm Inner Join
                                 PCFIN pc on pm.IsnCtaFinRecVal  = pc.Isn_CtaFin
                            Where pc.Tip_CtaFin = 'A')     
                begin
                  if @@trancount > 0 
                    Rollback Transaction
                  RAISERROR('Parâmetro Financeiro Conta (CREDITOS A RECEBER) não configurada',16,1)
                  Return
                end              
            end  -- if @pm_FlgUsaInterv = 1
          else
            begin
              Set @to_IsnCtaFinCre = 0
              Set @to_IsnCtaFinDeb = @WIsnCtaFinEntid
            end



          if not Exists(Select Cod_Documento From CTREC Where Cod_Estabe = @PCodEstabe and Ser_NfOrigem = @PSerNot and Num_NfOrigem = @PNumNot)
            begin
              if @cb_IdTransacao = 0  
                begin
                  EXEC PR_ProxNumeroEstab @PCodEstabe, 'Id_Transacao', @cb_IdTransacao output
          
                  Update NFSCB
                     Set Id_Transacao = @cb_IdTransacao
                   Where Cod_Estabe = @PCodEstabe  
                     And Ser_Nota = @PSerNot
                     And Num_Nota = @PNumNot 
                end
  
              Set @WValMov = @cb_ValNot
              Exec PR_AtualizaPCMOV 'I', @PCodEstabe, @to_IsnCtaFinCre, @PDatEmi, 'NFSCB', 'NFS', @PSerNot, @PNumNot, 0, @cb_IdTransacao, @WValMov
  
              Set @WValMov = -@cb_ValNot
              Exec PR_AtualizaPCMOV 'I', @PCodEstabe, @to_IsnCtaFinDeb, @PDatEmi, 'NFSCB', 'NFS', @PSerNot, @PNumNot, 0, @cb_IdTransacao, @WValMov
            end
         else
           begin
             -- classifica contas financeiras CTREC
             Exec PR_ClassificaCtaFinNFS @cb_CodOpe, @WTipEntid, @WCodEntid, @to_IsnCtaFinDeb output, @to_IsnCtaFinCre output
  
             Update CTREC 
                Set Isn_CtaFin = @to_IsnCtaFinDeb,
                    Isn_CtaFinCre = @to_IsnCtaFinCre
              Where Cod_Estabe = @PCodEstabe
                And Ser_NfOrigem = @PSerNot
                And Num_NfOrigem = @PNumNot
           end
        end
  
      -- registra tributacao embutida no titulo a receber
      Exec PR_CalculaSbtEmbCTREC @PCodEstabe, @PSerNot, @PNumNot
      if @@error <> 0
        begin
          if @@trancount > 0 
            Rollback Transaction
          Return
        end
  
      -- atualiza itens na tabela de consignações
      if (@ns_IdConsig > 0) and (@ns_NumSeqCtr > 0)
        begin
          Exec PR_FaturaConsignacao 'S', @PCodEstabe, @PSerNot, @PNumNot, @ns_IdConsig, @ns_NumSeqCtr
          if (@@error <> 0)
            begin
              if @@trancount > 0 
                Rollback Transaction
              Return
            end
        end
  
      if @@trancount > 0 
        Commit Transaction
    END
  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ExcluiCancelaPDVLT]
@PCodEstabe int,
@PNumPdv int,
@PNomUsu varchar(25)

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

Declare @MsgErr varchar(800),
        @cb_Status1 varchar(1),
        @cb_Status2 varchar(1),
        @FlgIntWms bit = 0,
        @StaIntWms varchar(1),
		@FlgPodeCancelar bit,
		@FlgAtuQtdSolici bit

Select @cb_Status1 = Status1,
       @cb_Status2 = Status2,
       @StaIntWms = IsNull(Sta_IntWms,'')	        
  From PDVCB
 Where Cod_Estabe = @PCodEstabe
   And Numero = @PNumPdv

Select @FlgIntWms = IsNull(FlgIntegrWmsExt,0) 
  From PMEST 
 Where Cod_Estabe = @PCodEstabe

Set @MsgErr = ''

if not Exists(Select top 1 z.Cod_Dep, z.Num_RuaIni 
                From TBZON z 
                     inner join PMEST p on z.Cod_Estabe = p.Cod_Estabe and z.Cod_Zon = p.CodZonCan 
               Where z.Cod_Estabe = @PCodEstabe
                 And dbo.FN_TipLocEnd(z.Cod_Estabe, z.Cod_Dep, z.Num_RuaIni) = 'X')
  Set @MsgErr = 'Zona de Quarentena(cancelamentos) não configurada ou inválida'
else
if @cb_Status1 = 'C'
  Set @MsgErr = 'Pediddo já cancelado'
else
if @cb_Status2 = 'N'
  Set @MsgErr = 'Pediddo já faturado'
else
if not Exists(Select top 1 Cod_Pedido From PDVLT Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PNumPdv)
  Set @MsgErr = 'Pediddo não solicitou lotes'
else
if not ((@cb_Status1 = 'P') and (@cb_Status2 = 'F'))
  Set @MsgErr = 'Pediddo não nã está pendente/fechado'


if @MsgErr <> ''
  RAISERROR(@MSgErr,16,1)
else
BEGIN
  BEGIN TRANSACTION

  Set @FlgPodeCancelar = 0

  if (@FlgIntWms = 0) and (@StaIntWms = '')
    Set @FlgPodeCancelar = 1
  else
  if @FlgIntWms = 1
    begin
      if @StaIntWms = '4'
        Set @FlgPodeCancelar = 1
      else
        begin
          Update PDVCB
             Set Sta_IntWMS = '3'
           Where Cod_Estabe = @PCodEstabe 
             And Numero = @PNumPdv
             And IsNull(Sta_IntWMS,'') = ''

		  Exec PR_WMSGerarXMLEntradaCanPDV @PCodEstabe, @PNumPdv

        end
    end


  if @FlgPodeCancelar = 1
    begin
      Declare @WCodDep smallint,
              @WNumRua smallint,
              @WNumCol smallint,
              @WNumNiv smallint,
              @WNumApt smallint,
              @WDatVct smalldatetime,
              @WDatFab smalldatetime,
              @WCodOri varchar(20),
              @WQtdTrfTot int,
              @it_CodPrm int,

	          @lt_CodPrd int,
              @lt_CodLot varchar(20),
              @lt_QtdLot int,
              @lt_QtdPra int,
              @lt_QtdDep int,
              @lt_QtdCxaFec int,
              @lt_QtdEmbFec int,
              @lt_CodDep smallint,
              @lt_NumRua smallint,
              @lt_NumCol smallint,
              @lt_NumNiv smallint,
              @lt_NumApt smallint

      -- pega depósito/rua da zona de quarentena
      Select top 1 
             @WCodDep = z.Cod_Dep, 
             @WNumRua = z.Num_RuaIni 
        From TBZON z 
             inner join PMEST p on z.Cod_Estabe = p.Cod_Estabe and z.Cod_Zon = p.CodZonCan 
      Where z.Cod_Estabe = @PCodEstabe
        And dbo.FN_TipLocEnd(z.Cod_Estabe, z.Cod_Dep, z.Num_RuaIni) = 'X'

      Declare PDVLT_Cr Cursor Local Fast_Forward For 
        Select Cod_Produt, Cod_Lote, Qtd_Lote, Qtd_CxaFec, Qtd_EmbFec, Qtd_LotePra, Qtd_LoteDep, 
               Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt
          From PDVLT
         Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PNumPdv

      Open PDVLT_Cr
      Fetch Next From PDVLT_Cr
        Into @lt_CodPrd, @lt_CodLot, @lt_QtdLot, @lt_QtdCxaFec, @lt_QtdEmbFec, @lt_QtdPra, @lt_QtdDep, 
             @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt

      While @@FETCH_STATUS = 0
        begin
          if @lt_QtdPra is null
            Set @lt_QtdPra = 0
          if @lt_QtdDep is null
            Set @lt_QtdDep = 0
          if (@lt_QtdPra+@lt_QtdDep) <> @lt_QtdLot
            begin
              Set @lt_QtdPra = @lt_QtdLot - @lt_QtdDep
            end

          -- Transfere quantidades para zona de cancelamentos
          if (@lt_QtdCxaFec > 0) and (@FlgIntWms = 0)   -- deposito FECHADO
            begin
              Set @WNumCol = 0
              Set @WNumNiv = 0
              Set @WNumApt = 0
            end
          else
            begin
              Set @WNumCol = 1
              Set @WNumNiv = 1
              if (Select QtdNivEndPck From PMEST Where Cod_Estabe = @PCodEstabe) = 3
                Set @WNumApt = 0
              else
                Set @WNumApt = 1
            end

          -- se nao existir o lote, cria
          if (Select Count(*) From PRLTL 
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Produt = @lt_CodPrd and Cod_Lote = @lt_CodLot 
                 and Qtd_EmbFec = @lt_QtdEmbFec and Cod_Dep = @WCodDep 
                 and Num_Rua = @WNumRua and Num_Col = @WNumCol 
                 and Num_Niv = @WNumNiv and Num_Apt = @WNumApt) = 0
            begin
               -- pega o vencimento do lote
              Set @WDatVct = null
              Set @WDatFab = null
              if (@lt_QtdCxaFec > 0) and (@FlgIntWms = 0)  -- deposito FECHADO
                begin
                  Select @WDatVct = Dat_Vencim,
                         @WDatFab = Dat_Fabric
                    From PRLTL 
                   Where Cod_Estabe = @PCodEstabe 
                     And Cod_Produt = @lt_CodPrd and Cod_Lote = @lt_CodLot
                     And Qtd_EmbFec = @lt_QtdEmbFec And Cod_Dep = @lt_CodDep 
                     And Num_Rua = @lt_NumRua and Num_Col = @lt_NumCol 
                     And Num_Niv = @lt_NumNiv and Num_Apt = @lt_NumApt
                end
              else
                begin
                  Select @WDatVct = Dat_Vencim,
                         @WDatFab = Dat_Fabric
                    From PRLOT 
                   Where Cod_Estabe = @PCodEstabe 
                     And Cod_Dep = @lt_CodDep 
                     And Cod_Produt = @lt_CodPrd 
                     and Cod_Lote = @lt_CodLot
                end
 
              while Exists(Select * From PRLTL 
                            Where Cod_Estabe = @PCodEstabe 
                              And Cod_Produt = @lt_CodPrd and Cod_Lote = @lt_CodLot 
                              and Cod_Dep = @WCodDep and Num_Rua = @WNumRua 
                              and Num_Col = @WNumCol and Num_Niv = @WNumNiv 
                              and Num_Apt = @WNumApt)
                begin
                  Set @WNumNiv = @WNumNiv + 1
                end
 
              Insert into PRLTL (Cod_Estabe, Cod_Produt, Cod_Lote, Qtd_EmbFec, Dat_Vencim, Dat_Fabric, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Dat_Entrada, Qtd_FisPra, Qtd_SolPra,Qtd_FisDep,Qtd_SolDep)
                         Values (@PCodEstabe, @lt_CodPrd, @lt_CodLot, @lt_QtdEmbFec, @WDatVct, @WDatFab, @WCodDep, @WNumRua, @WNumCol, @WNumNiv, @WNumApt, @Date, 0, 0, 0, 0)
              if @@error <> 0
                begin
                  Rollback Transaction
                  Return
                end
           
            end -- if (Select Count(*) From PRLTL 

          -- cancela solicitacao/fisico
          if (@lt_QtdCxaFec > 0) and (@FlgIntWms = 0) -- depositO FECHADO
            begin
              Update PRLTL
                 Set Qtd_SolPra = Qtd_SolPra -  @lt_QtdPra
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Produt = @lt_CodPrd and Cod_Lote = @lt_CodLot
                 And Qtd_EmbFec = @lt_QtdEmbFec
                 And Cod_Dep = @lt_CodDep
                 And Num_Rua = @lt_NumRua and Num_Col = @lt_NumCol
                 And Num_Niv = @lt_NumNiv
                 And Num_Apt = @lt_NumApt
                 And @lt_QtdPra > 0
 
              Update PRLTL
                 Set Qtd_SolDep = Qtd_SolDep -  @lt_QtdDep
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Produt = @lt_CodPrd and Cod_Lote = @lt_CodLot
                 And Qtd_EmbFec = @lt_QtdEmbFec
                 And Cod_Dep = @lt_CodDep
                 And Num_Rua = @lt_NumRua and Num_Col = @lt_NumCol
                 And Num_Niv = @lt_NumNiv
                 And Num_Apt = @lt_NumApt
                 And @lt_QtdDep > 0
 
              Update PRLTL
                 Set Qtd_FisPra = Qtd_FisPra - @lt_QtdPra
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Produt = @lt_CodPrd and Cod_Lote = @lt_CodLot
                 And Qtd_EmbFec = @lt_QtdEmbFec
                 And Cod_Dep = @lt_CodDep
                 And Num_Rua = @lt_NumRua and Num_Col = @lt_NumCol
                 And Num_Niv = @lt_NumNiv
                 And Num_Apt = @lt_NumApt
                 And @lt_QtdPra > 0
 
              Update PRLTL
                 Set Qtd_FisDep = Qtd_FisDep - @lt_QtdDep
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Produt = @lt_CodPrd and Cod_Lote = @lt_CodLot
                 And Qtd_EmbFec = @lt_QtdEmbFec
                 And Cod_Dep = @lt_CodDep
                 And Num_Rua = @lt_NumRua and Num_Col = @lt_NumCol
                 And Num_Niv = @lt_NumNiv
                 And Num_Apt = @lt_NumApt
                 And @lt_QtdDep > 0
            end
          else
            begin
              Update PRLOT
                 Set Qtd_SolPra = Qtd_SolPra -  @lt_QtdPra
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Dep = @lt_CodDep 
                 And Cod_Produt = @lt_CodPrd 
                 and Cod_Lote = @lt_CodLot
                 And @lt_QtdPra > 0
 
              Update PRLOT
                 Set Qtd_SolDep = Qtd_SolDep -  @lt_QtdDep
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Dep = @lt_CodDep 
                 And Cod_Produt = @lt_CodPrd 
                 and Cod_Lote = @lt_CodLot
                 And @lt_QtdDep > 0
 
              Update PRLOT
                 Set Qtd_FisPra = Qtd_FisPra -  @lt_QtdPra
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Dep = @lt_CodDep 
                 And Cod_Produt = @lt_CodPrd 
                 and Cod_Lote = @lt_CodLot
                 And @lt_QtdPra > 0
 
              Update PRLOT
                 Set Qtd_FisDep = Qtd_FisDep -  @lt_QtdDep
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Dep = @lt_CodDep 
                 And Cod_Produt = @lt_CodPrd 
                 and Cod_Lote = @lt_CodLot
                 And @lt_QtdDep > 0
            end

          -- cancela solicitacao em PRODU
          Set @it_CodPrm = 0
          Select @it_CodPrm = Cod_Promocao
           From PDVIT 
          Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PNumPdv 
            And Cod_Produto = @lt_CodPrd and Cod_Lote = '*'
 
          Update PRXES 
             Set Qtd_Solici = case 
                                when Qtd_Solici > @lt_QtdLot then Qtd_Solici - @lt_QtdLot
                                else 0
                              end
           Where Cod_Estabe = @PCodEstabe 
             And Cod_Produt = @lt_CodPrd
 
          Update PRXES 
             Set Qtd_PrmSolici = case 
                                   when Qtd_PrmSolici > @lt_QtdLot then Qtd_PrmSolici - @lt_QtdLot
                                   else 0
                                 end                                       
           Where Cod_Estabe = @PCodEstabe 
             And Cod_Produt = @lt_CodPrd and (@it_CodPrm > 0 and not @it_CodPrm is null)
			
		  set @FlgAtuQtdSolici = 1;
 
          -- transfere para zona de cancelados
          if @FlgIntWms = 0
            begin
              Update PRLTL
                 Set Qtd_FisPra = Qtd_FisPra +  @lt_QtdPra
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Produt = @lt_CodPrd and Cod_Lote = @lt_CodLot
                 And Qtd_EmbFec = @lt_QtdEmbFec
                 And Cod_Dep = @WCodDep
                 And Num_Rua = @WNumRua And Num_Col = @WNumCol
                 And Num_Niv = @WNumNiv And Num_Apt = @WNumApt
                 And @lt_QtdPra > 0
 
              Update PRLTL
                 Set Qtd_FisDep = Qtd_FisDep +  @lt_QtdDep
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Produt = @lt_CodPrd and Cod_Lote = @lt_CodLot
                 And Qtd_EmbFec = @lt_QtdEmbFec
                 And Cod_Dep = @WCodDep
                 And Num_Rua = @WNumRua And Num_Col = @WNumCol
                 And Num_Niv = @WNumNiv And Num_Apt = @WNumApt
                 And @lt_QtdDep > 0
 
              Set @WCodOri = 'CAN_PDV'
 
              -- registra log saida
              Set @WQtdTrfTot = (@lt_QtdPra + @lt_QtdDep) * (-1)
              Exec PR_InserePRLOG @PCodEstabe, @lt_CodPrd, @lt_CodLot, @lt_CodDep, 
                                  @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt,
                                  @WQtdTrfTot, @WCodOri, '', @PNumPdv, '', '', @PNomUsu
              if @@error <> 0 
                begin
                  Rollback Transaction
                  Return
                end 
 
              -- registra log entrada
              Set @WQtdTrfTot = @lt_QtdPra + @lt_QtdDep
              Exec PR_InserePRLOG @PCodEstabe, @lt_CodPrd, @lt_CodLot, @WCodDep, 
                                  @WNumRua, @WNumCol, @WNumNiv, @WNumApt,
                                  @WQtdTrfTot, @WCodOri, '', @PNumPdv, '', '', @PNomUsu
              if @@error <> 0 
                begin
                  Rollback Transaction
                  Return
                end

            end
	    
          Fetch Next From PDVLT_Cr
            Into @lt_CodPrd, @lt_CodLot, @lt_QtdLot, @lt_QtdCxaFec, @lt_QtdEmbFec, @lt_QtdPra, @lt_QtdDep, 
                 @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt

        end  -- While @@FETCH_STATUS = 0
  
      Close PDVLT_Cr
      Deallocate PDVLT_Cr
 
      -- cancela o pedido
      Delete From PDVLT
       Where Cod_Estabe = @PCodEstabe 
         And Cod_Pedido = @PNumPdv
 
      Exec PR_CancelaPDV @PCodEstabe, @PNumPdv, @PNomUsu, @FlgAtuQtdSolici
      if @@error <> 0
        begin
          Rollback Transaction
          Return
        end

      -- atualiza status integracao WMS
      Update PDVCB
         Set Sta_IntWMS = '6'
       Where Cod_Estabe = @PCodEstabe 
         And Numero = @PNumPdv
         And IsNull(Sta_IntWMS,'') <> ''

      -- Elimina a conferencia
      Delete From CPVIT
       Where Cod_Estabe = @PCodEstabe 
         And Num_PedCnf = @PNumPdv
 
      Delete From CPVCB
       Where Cod_Estabe = @PCodEstabe 
         And Num_PedCnf = @PNumPdv
 
    end  -- if @FlgPodeCancelar = 1

  if @@trancount > 0
    COMMIT TRANSACTION
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ExcluiCancelaNFSCB]
@PCodEstabe int,
@PSerNot varchar(3),
@PNumNot int,
@PCodMve int,
@PNomUsu varchar(15),
@PFlgCanPdv bit

AS

SET NOCOUNT ON
SET ANSI_WARNINGS OFF

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

Declare @cb_FlgWms bit,
        @cb_StaNot varchar(1),
        @cb_TipNot varchar(1),
        @cb_CodCfo int,
        @cb_DatEmi smalldatetime,
        @cb_MovEst bit,
        @cb_CodCli int,
        @cb_CodVdr int,
        @cb_CodOpe int,
        @cb_CodSup int,
        @cb_CodPdv int,
        @cb_SubFat int,
        @cb_ValDebVrbVdr numeric(18,4),
        @cb_ValNot numeric(18,4),
        @cb_CodFun int,
        @cb_CodFor int,
        @cb_CodCtr int,
        @cb_IdConsig int,
        @cb_NumSeqCtr int, 
        @cb_StaIntWms varchar(1),
        @cb_Usuario varchar(15),
        @cr_CodDoc int,
        @pm_FlgIntWms bit = 0,
    @FlgPodeCancelar bit,
        @va_IsnCtaFinDeb int,
        @va_IsnCtaFinCre int,
        @va_DatMovime smalldatetime,
        @va_NumSequen int,     
        @pm_FlgUsaInterv bit,
        @WMsg varchar(128),
        @WFlgErr bit,
        @WQtdEmbFec int,
        @WCodDepCan smallint,
        @WNumRuaCan smallint,
        @WNumCol smallint,
        @WNumNiv smallint,
        @WNumApt smallint,
        @WDatVct smalldatetime,
        @WDatFab smalldatetime,
        @WTipDes varchar(3),
        @WCodDes int,
        @WCodDoc int,
        @CodTipSaiCng varchar(3) = '',
    @pc_CtlSld varchar(1)

-- Validacao login usuario infarma  
if (@PNomUsu='' or @PNomUsu='SISTEMA')
  set @PNomUsu = dbo.FN_UsuarioInfarma()

-- coloca campos na memoria
Select @pm_FlgUsaInterv = IsNull(FlgUsaInterv,0)
  From PMFIN

Select @pm_FlgIntWms = IsNull(FlgIntegrWmsExt,0) 
  From PMEST Where Cod_Estabe = @PCodEstabe

Select @cb_FlgWms = IsNull(cb.Flg_Wms,0),
       @cb_StaIntWms = IsNull(cb.Sta_IntWms,''),          
       @cb_StaNot = cb.Status,
       @cb_TipNot = cb.Tip_Saida,
       @cb_CodCfo = Isnull(cb.Cod_Cfo1,0),
       @cb_DatEmi = cb.Dat_Emissao,
       @cb_MovEst = IsNull(cb.Flg_MovEst,0),
       @cb_CodCli = IsNull(cb.Cod_Cliente,0),
       @cb_CodFun = IsNull(cb.Cod_Funcionario,0),
       @cb_CodFor = IsNull(cb.Cod_Fornecedor,0),
       @cb_CodVdr = cb.Cod_Vendedor,
       @cb_CodOpe = IsNull(cb.Cod_VendTlmkt, 0),
       @cb_CodSup = cb.Cod_Supervisor,
       @cb_CodPdv = cb.Cod_Pedido,
       @cb_SubFat = cb.Num_NotSubFat,
       @cb_ValDebVrbVdr = IsNull(cb.Vlr_DebVrbVdr,0),
       @cb_ValNot = IsNull(cb.Vlr_TotalNota,0),
       @cb_CodCtr = IsNull(cb.Cod_Contrato,0),
       @cb_IdConsig = IsNull(cb.Id_Consig,0),
       @cb_NumSeqCtr = IsNull(cb.Num_SequenciaCtr,0), 
       @cb_Usuario = cb.Usuario,
     @pc_CtlSld = pc.Controle_Saldo
  From NFSCB cb
       Left Join POCOM pc on pc.Id_PolCom = cb.Id_PolCom
 Where cb.Cod_Estabe = @PCodEstabe and cb.Ser_Nota = @PSerNot and cb.Num_Nota = @PNumNot

if @cb_StaNot = 'C'
  RAISERROR('Nota já cancelada',16,1)
else
if (@cb_FlgWms = 1) and 
   not Exists(Select top 1 z.Cod_Dep, z.Num_RuaIni 
                From TBZON z 
                     inner join PMEST p on z.Cod_Estabe = p.Cod_Estabe and z.Cod_Zon = p.CodZonCan 
               Where z.Cod_Estabe = @PCodEstabe
                 And dbo.FN_TipLocEnd(z.Cod_Estabe, z.Cod_Dep, z.Num_RuaIni) = 'X'
                 And z.Cod_Dep > 0 And z.Num_RuaIni > 0)
  RAISERROR('Zona de Quarentena(cancelamentos) não configurada ou inválida',16,1)
else

BEGIN
  BEGIN TRANSACTION

  Set @FlgPodeCancelar = 0

  if (@cb_FlgWms = 0) or (@cb_MovEst = 0)
    Set @FlgPodeCancelar = 1
  else
  if (@pm_FlgIntWms = 0) and (@cb_StaIntWms = '')
    Set @FlgPodeCancelar = 1
  else
  if @pm_FlgIntWms = 1
    begin
      if @cb_StaIntWms = '4'
        begin
          Set @FlgPodeCancelar = 1
          Set @PFlgCanPdv = (Select IsNull(Flg_CanPdv,0) From NFSCB
                              Where Cod_Estabe = @PCodEstabe 
                                And Ser_Nota = @PSerNot
                                And Num_Nota = @PNumNot)
        end
      else
        begin
          Update NFSCB
             Set Sta_IntWMS = '3'
           Where Cod_Estabe = @PCodEstabe 
             And Ser_Nota = @PSerNot
             And Num_Nota = @PNumNot
             And IsNull(Sta_IntWMS,'') = ''

          Update NFSCB
             Set Flg_CanPdv = @PFlgCanPdv,
           Usuario = @PNomUsu
           Where Cod_Estabe = @PCodEstabe 
             And Ser_Nota = @PSerNot
             And Num_Nota = @PNumNot

          Exec PR_WMSGerarXMLEntradaCanNFS @PCodEstabe, @PSerNot, @PNumNot

        end
    end

  if @FlgPodeCancelar = 1
    begin
              
      if (@cb_StaNot = 'A') and (@cb_TipNot <> 'V')
        begin
          -- exclui os itens
          Delete from NFSIT 
           Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot

          -- exclui as duplicatas
          Delete from CTREC
           Where Cod_Estabe = @PCodEstabe
             And Ser_NfOrigem = @PSerNot and Num_NfOrigem = @PNumNot

          -- se a nota tiver sido a ultima, exclui, senao cancela
          if @PSerNot = 'XXX'
            begin
              Delete from NFSCB
               Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
            end
          else
          if (Select Nota_Fiscal_M1 from NMFIS Where Cod_Estabe = @PCodEstabe) = @PNumNot
            begin
              Update NMFIS
                 Set Nota_Fiscal_M1 = @PNumNot - 1
               Where Cod_Estabe = @PCodEstabe
              
              Delete from NFSCB
               Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
            end
          else
            begin
              Update NFSCB
                 Set Status = 'C',
                     Dat_Cancelamento = @Date,
                     Flg_CanPdv = @PFlgCanPdv,
                     Usuario = @PNomUsu,
                     Transacao = GetDate()
               Where Cod_Estabe = @PCodEstabe 
                 and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
            end
        end
      else
      if (@cb_StaNot = 'F') and (@cb_MovEst = 0)
        begin
          -- cancela titulos
          Exec PR_CancelaDevolveTitulosCTREC @PCodEstabe, @PSerNot, @PNumNot, @PNomUsu, 'C', 0, 0
          if @@error <> 0
            begin
              if @@trancount > 0
                Rollback Transaction
              Return
            end

          -- cancela o cabeçalho
          Update NFSCB
             Set Status = 'C',
                 Dat_Cancelamento = @Date,
                 Flg_CanPdv = @PFlgCanPdv,
                 Usuario = @PNomUsu,
                 Transacao = GetDate()
           Where Cod_Estabe = @PCodEstabe 
             and Ser_Nota = @PSerNot and Num_Nota = @PNumNot

          -- transfere saldos de PRSLD
          EXEC PR_TransfEstNFS @PCodEstabe, @PSerNot, @PNumNot
          if @@error <> 0
            begin
              if @@trancount > 0
                Rollback Transaction
              Return
            end

          -- se for o caso cancela os desc. sub.fat na Nf origem (ORC)
          if (@PSerNot <> 'ORC') and (@cb_SubFat > 0)
            begin
              Declare CTREC_Cr Cursor Local Fast_Forward For 
                Select Cod_Documento
                  From CTREC
                 Where Cod_Estabe = @PCodEstabe
                   And Ser_NfOrigem = 'ORC' and Num_NfOrigem = @cb_SubFat
                  
              Open CTREC_Cr
              Fetch Next From CTREC_Cr
                Into @cr_CodDoc
              While @@FETCH_STATUS = 0
                begin
                  Update CTREC
                     Set Vlr_DscSubFat = 0
                   Where Cod_Estabe = @PCodEstabe
                     And Cod_Documento = @cr_CodDoc

                  -- atualiza saldo contas a receber
                  EXEC PR_AtualizaCtrec @PCodEstabe, @cr_CodDoc,0
                  if @@error <> 0
                    begin
                      if @@trancount > 0
                        Rollback Transaction
                      Return
                    end

                  Fetch Next From CTREC_Cr
                    Into @cr_CodDoc
                end
              Close CTREC_Cr
              Deallocate CTREC_Cr
            end
        end
      else
      if @Cb_StaNot = 'F' and @Cb_MovEst = 1
        if not Exists(Select Codigo from TPMVE Where Codigo = @PCodMve)
          begin
            Set @WMsg = 'O código para o Tipo de Movimento "'+Cast(@PCodMve as varchar(2))+
                                    '-Entrada por Cancelamento de NF" não foi '+
                                    'cadastrado em Tipos de Movimentação de Estoque'
            RAISERROR(@WMsg,16,1)
          end
        else
          begin
            Declare @it_CodPrd int,
                    @it_CodLot varchar(20),
                    @it_SeqIte int,
                    @it_TipSai varchar(1),
                    @it_QtdPrd int,
                    @it_QtdBon int,
                    @it_PrcUni numeric(18,8),
                    @it_QtdPra int,
                    @it_QtdDep int,
                    @it_VlrVrbPolVdr numeric(18,4),
          @it_VlrVrbPolOpe numeric(18,4),
                    @it_VlrVrbPolSup numeric(18,4),
                    @it_VlrVrbPar numeric(18,4),
                    @it_VlrVrbBon numeric(18,4),
                    @it_IdPolCom int,
                    @it_PrcFab numeric(18,4), 
                    @it_PrcUniPde numeric(18,4), 
                    @it_PerDscPde numeric(18,4),
                    @it_CodCfo int,
          @it_CodFab int,

                    @WCodOri varchar(20),
                    @WQtdMov int,
                    @WDatCan smalldatetime,
                    @WCodAcr int,
                    @WDesHst varchar(40),
                    @WQtdItePdv int,
                    @WQtdIteNfs int,
                    @WDivItens int,
                    @WFlgReaPdvOk bit,
                    @WQtdPra int ,
                    @WQtdDep int,
                    @WValMov numeric(18,4),
                    @WCodFor int,
                    @WValEdi numeric(18,4),
                    @WValBru numeric(18,4),
                    
                    @WNumRuaPck smallint,
                    @WNumColPck smallint,
                    @WNumNivPck smallint,
                    @WNumAptPck smallint

            -- pega depósito/rua da zona de quarentena(cancelamento)
            Select top 1 
                   @WCodDepCan = z.Cod_Dep, 
                   @WNumRuaCan = z.Num_RuaIni 
              From TBZON z 
                   inner join PMEST p on z.Cod_Estabe = p.Cod_Estabe and z.Cod_Zon = p.CodZonCan 
             Where z.Cod_Estabe = @PCodEstabe
               And dbo.FN_TipLocEnd(z.Cod_Estabe, z.Cod_Dep, z.Num_RuaIni) = 'X'

            -- se nao for cancelar pedido ver se esta ok pdv x nfs
            Set @WFlgReaPdvOk = 0
            if @PFlgCanPdv = 0
              begin
                Set @WQtdItePdv = IsNull((Select count(*) from PDVIT Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @cb_CodPdv and Qtd_Pedido > 0),0)
                Set @WQtdIteNfs = IsNull((Select count(*) from NFSIT Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot),0)

                -- O mesmo produto pode ser dividido em lotes diferentes na nota
        Select @WDivItens = Count(1) 
                  From (Select Cod_Produto,Sum(Qtd_Pedido) as Qtd 
                          From PDVIT 
                         Where Cod_Estabe = @PCodEstabe 
                           And Cod_Pedido = @cb_CodPdv and Qtd_Pedido > 0
                         Group By Cod_Produto) p Full Join 
                       (Select Cod_Produto,Sum(Qtd_Produto) as Qtd 
                          From NFSIT 
                         Where Cod_Estabe = @PCodEstabe 
                           And Ser_Nota = @PSerNot and Num_Nota = @PNumNot
                         Group By Cod_Produto) n On p.Cod_Produto = n.Cod_Produto
         Where IsNull(p.Qtd,0) <> IsNull(n.Qtd,0)
        
                if (@WDivItens = 0) and (@WQtdItePdv > 0) and (@WQtdIteNfs > 0)
                  Set @WFlgReaPdvOk = 1
                else
                  begin
                    Set @WMsg = 'Divergencia entre itens do pedido e da nota. Pedido deve ser cancelado'
                    RAISERROR(@WMsg,16,1)
                  end
              end

            Update NFSCB
               Set Status = 'C',
                   Dat_Cancelamento = @Date,
                   Flg_CanPdv = @PFlgCanPdv,
                   Usuario = @PNomUsu,
                   Transacao = GetDate()
             Where Cod_Estabe = @PCodEstabe 
               and Ser_Nota = @PSerNot and Num_Nota = @PNumNot

            Set @WFlgErr = 0
            Set @WDatCan = @Date
            Set @WDesHst = 'CANCELAMENTO NF '+@PSerNot+' '+cast(@PNumNot as varchar)

            Declare NFSIT_Cr Cursor Local Fast_Forward For 
              Select it.Cod_Produto, it.Cod_Lote, it.Num_SeqIte, it.Qtd_Produto, it.Qtd_Bonificacao, it.Prc_Unitario,
                     IsNull(it.Cod_Cfo,0), IsNull(it.Prc_Fabric,0), IsNull(it.Prc_UniPde,0), IsNull(it.Per_DscPde,0), 
                     IsNull(it.Qtd_Pra,0), IsNull(it.Qtd_Dep,0), IsNull(it.Vlr_Verba,0), IsNull(it.Vlr_VrbOpe,0), IsNull(it.Vlr_VrbSup,0), IsNull(it.Vlr_VrbPar,0), 
                     IsNull(it.Vlr_VrbBon,0), IsNull(it.Id_PolCom,0), pr.Cod_Fabricante
                From NFSIT it 
                     Inner Join NFSCB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Ser_Nota = cb.Ser_Nota and it.Num_Nota = cb.Num_Nota
                     Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
               Where cb.Cod_Estabe = @PCodEstabe and cb.Ser_Nota = @PSerNot and cb.Num_Nota = @PNumNot and cb.Flg_MovEst = 1

            Open NFSIT_Cr
            Fetch Next From NFSIT_Cr
              Into @it_CodPrd, @it_CodLot, @it_SeqIte, @it_QtdPrd, @it_QtdBon, @it_PrcUni,
                   @it_CodCfo, @it_PrcFab, @it_PrcUniPde, @it_PerDscPde,  
                   @it_QtdPra, @it_QtdDep, @it_VlrVrbPolVdr, @it_VlrVrbPolOpe, @it_VlrVrbPolSup, @it_VlrVrbPar, 
                   @it_VlrVrbBon, @it_IdPolCom, @it_CodFab 

            While (@@FETCH_STATUS = 0) and (@WFlgErr = 0)
              begin
                if (@it_QtdPra+@it_QtdDep) <> (@it_QtdPrd+@it_QtdBon)
                  Set @it_QtdPra = @it_QtdPrd + @it_QtdBon - @it_QtdDep

                Set @WNumCol = 0
                Set @WNumNiv = 0
                Set @WNumApt = 0
                Set @WDatVct = null
                Set @WDatFab = null
                Set @WQtdEmbFec = 1

                -- pega o vencimento do lote
                Select @WDatVct = Dat_Vencim, 
                       @WDatFab = Dat_Fabric 
                  From PRLOT 
                 Where Cod_Estabe = @PCodEstabe 
                   And Cod_Dep = @WCodDepCan
                   And Cod_Produt = @it_CodPrd 
                   and Cod_Lote = @it_CodLot

                if @WDatVct is null
                  Set @WDatVct = (Select top 1 Dat_Vencim From PRLTL Where Cod_Estabe = @PCodEstabe and Cod_Produt = @it_CodPrd and Cod_Lote = @it_CodLot And Cod_Dep = @WCodDepCan)
                if @WDatFab is null
                  Set @WDatFab = (Select top 1 Dat_Fabric From PRLTL Where Cod_Estabe = @PCodEstabe and Cod_Produt = @it_CodPrd and Cod_Lote = @it_CodLot And Cod_Dep = @WCodDepCan)

                -- verifica e ajusta se for emprestimo de estoque
                if (@cb_CodCfo > 0) and (@it_QtdDep > 0)
                  Set @it_QtdDep = @it_QtdDep * (-1) 
                if (@cb_CodCfo = 0) and (@it_QtdPra > 0)
                  Set @it_QtdPra = @it_QtdPra * (-1) 

                -- gera um acerto. o saldo é atualizado pela trigger
                Set @WNumRuaPck = 0
                Set @WNumColPck = 0
                Set @WNumNivPck = 0
                Set @WNumAptPck = 0
                
                Select @WNumRuaPck = Num_Rua, 
                       @WNumColPck = Num_Col, 
                       @WNumNivPck = Num_Niv, 
                       @WNumAptPck = Num_Apt 
                  From DPXPR 
                 Where Cod_Estabe = @PCodEstabe 
                   And Cod_Dep = @WCodDepCan
                   And Cod_Produt = @it_CodPrd

                Exec PR_ProxNumero 'Acerto', @WCodAcr output
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end
                  
                Insert into ACERT (Cod_Estabe, Numero, Dat_Movimento, 
                                   Cod_Produto, Cod_Lote, Dat_Vencimento, Dat_Fabric,
                                   Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt,
                                   Qtd_Acerto, Qtd_AceDep, Cod_TipMov, Cod_OriMov, Historico, Usuario, Transacao)
                            Values(@PCodEstabe, @WCodAcr, @WDatCan,
                                   @it_CodPrd, @it_CodLot, @WDatVct, @WDatFab, 
                                   @WCodDepCan, @WNumRuaPck, @WNumColPck, @WNumNivPck, @WNumAptPck,
                                   @it_QtdPra, @it_QtdDep, @PCodMve, 'NF', @WDesHst,  @PNomUsu, GetDate())
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end

                -- se WMS transfere para Zona de cancelamentos se não estiver integrado
                if (@cb_FlgWms = 1) and (@pm_FlgIntWms = 0)
                  begin
                    -- se nao existir o lote, cria
                    if (Select Count(*) From PRLTL 
                         Where Cod_Estabe = @PCodEstabe 
                           and Cod_Produt = @it_CodPrd and Cod_Lote = @it_CodLot
                           and Cod_Dep = @WCodDepCan and Num_Rua = @WNumRuaCan 
                           and Num_Col = @WNumCol and Num_Niv = @WNumNiv 
                           and Num_Apt = @WNumApt) = 0
                      begin
                        Insert into PRLTL (Cod_Estabe, Cod_Produt, Cod_Lote, Qtd_EmbFec, Dat_Vencim, Dat_Fabric, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Dat_Entrada, Qtd_FisPra, Qtd_SolPra,Qtd_FisDep,Qtd_SolDep)
                                   Values (@PCodEstabe, @it_CodPrd, @it_CodLot, @WQtdEmbFec, @WDatVct, @WDatFab, @WCodDepCan, @WNumRuaCan, @WNumCol, @WNumNiv, @WNumApt, @Date, 0, 0, 0, 0)
                        if @@error <> 0
                          begin
                            if @@trancount > 0
                              Rollback Transaction
                            Return
                          end
                      end

                    -- tira de PRLOT
                    Update PRLOT
                       Set Qtd_FisPra = Qtd_FisPra - Abs(@it_QtdPra)
                     Where Cod_Estabe = @PCodEstabe 
                       And Cod_Dep = @WCodDepCan
                       And Cod_Produt = @it_CodPrd 
                       and Cod_Lote = @it_CodLot
                       And Abs(@it_QtdPra) > 0
                       And Qtd_SldPra >= Abs(@it_QtdPra)
                       And @WFlgErr = 0
                    if (@@rowcount = 0) and (Abs(@it_QtdPra) > 0) and (@WFlgErr = 0)
                      begin
                        Set @WFlgErr = 1
                        Set @WMsg = 'Estoque insuficiente no Picking a transferir p/ zona de cancelamentos'
                      end

                    Update PRLOT
                       Set Qtd_FisDep = Qtd_FisDep - Abs(@it_QtdDep)
                     Where Cod_Estabe = @PCodEstabe
                       And Cod_Dep = @WCodDepCan 
                       And Cod_Produt = @it_CodPrd 
                       and Cod_Lote = @it_CodLot
                       And Abs(@it_QtdDep) > 0
                       And Qtd_SldDep >= Abs(@it_QtdDep)
                       And @WFlgErr = 0
                    if (@@rowcount = 0) and (Abs(@it_QtdDep) > 0) and (@WFlgErr = 0)
                      begin
                        Set @WFlgErr = 1
                        Set @WMsg = 'Estoque insuficiente no Picking a transferir p/ zona de cancelamentos'
                      end

                    -- transfere para zona de cancelados
                    Update PRLTL
                       Set Qtd_FisPra = Qtd_FisPra +  Abs(@it_QtdPra)
                     Where Cod_Estabe = @PCodEstabe 
                       And Cod_Produt = @it_CodPrd and Cod_Lote = @it_CodLot
                       And Cod_Dep = @WCodDepCan
                       And Num_Rua = @WNumRuaCan 
                       And Num_Col = @WNumCol
                       And Num_Niv = @WNumNiv
                       And Num_Apt = @WNumApt
                       And Abs(@it_QtdPra) > 0
                       And @WFlgErr = 0
                    if (@@rowcount = 0) and (Abs(@it_QtdPra) > 0) and (@WFlgErr = 0)
                      begin
                        Set @WFlgErr = 1
                        Set @WMsg = 'Erro na transferencia p/ zona de cancelamentos (endereço inexistente)'
                      end

                    Update PRLTL
                       Set Qtd_FisDep = Qtd_FisDep +  Abs(@it_QtdDep)
                     Where Cod_Estabe = @PCodEstabe 
                       And Cod_Produt = @it_CodPrd and Cod_Lote = @it_CodLot
                       And Cod_Dep = @WCodDepCan
                       And Num_Rua = @WNumRuaCan 
                       And Num_Col = @WNumCol
                       And Num_Niv = @WNumNiv
                       And Num_Apt = @WNumApt
                       And Abs(@it_QtdDep) > 0
                       And @WFlgErr = 0
                    if (@@rowcount = 0) and (Abs(@it_QtdDep) > 0) and (@WFlgErr = 0)
                      begin
                        Set @WFlgErr = 1
                        Set @WMsg = 'Erro na transferencia p/ zona de cancelamentos (endereço inexistente)'
                      end
                      
                    -- registra log entrada
                    Set @WCodOri = 'TRF_EST'

                    -- registra log transferencia picking p/ zona de cancelamento
                    -- saida picking
                    Set @WQtdMov = (Abs(@it_QtdPra) + Abs(@it_QtdDep)) * (-1)
                    Exec PR_InserePRLOG @PCodEstabe, @it_CodPrd, @it_CodLot, @WCodDepCan, 
                                        @WNumRuaPck, @WNumColPck, @WNumNivPck, @WNumAptPck,
                                        @WQtdMov, @WCodOri, '', @PSerNot, @PNumNot, '', @PNomUsu
                    if @@error <> 0 
                      begin
                        if @@trancount > 0
                          Rollback Transaction
                        Return
                      end 
                    
                    -- entrada na zona de cancelamento
                    Set @WQtdMov = Abs(@it_QtdPra) + Abs(@it_QtdDep)
                    Exec PR_InserePRLOG @PCodEstabe, @it_CodPrd, @it_CodLot, @WCodDepCan, 
                                        @WNumRuaCan, @WNumCol, @WNumNiv, @WNumApt,
                                        @WQtdMov, @WCodOri, '', @PSerNot, @PNumNot, '', @PNomUsu
                    if @@error <> 0 
                      begin
                        if @@trancount > 0
                          Rollback Transaction
                        Return
                      end 
                      
                  end    -- @cb_FlgWms = 1

                -- re-solicita pedido se for reabrir
                if (@WFlgReaPdvOk = 1 ) and (@WFlgErr = 0)
                  if ((@cb_FlgWms = 0) and (Exists(Select Cod_Pedido From PDVIT Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @cb_CodPdv And Cod_Produto = @it_CodPrd And Cod_Lote = @it_CodLot And Qtd_Pedido > 0))) or
                     ((@cb_FlgWms = 1) and (Exists(Select Cod_Pedido From PDVIT Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @cb_CodPdv And Cod_Produto = @it_CodPrd And Cod_Lote = '*' And Qtd_Pedido > 0)))
                    begin

                      if @cb_FlgWms = 0
                        Select @WQtdPra = Qtd_Pra,
                               @WQtdDep = Qtd_Dep
                          From PDVIT 
                         Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @cb_CodPdv And Cod_Produto = @it_CodPrd And Cod_Lote = @it_CodLot
                      else
                        Select @WQtdPra = Qtd_Pedido,
                               @WQtdDep = Qtd_Bonificacao
                          From PDVIT 
                         Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @cb_CodPdv And Cod_Produto = @it_CodPrd And Cod_Lote = '*'

                      if @WQtdPra is null
                        Set @WQtdPra = 0
                      if @WQtdDep is null
                        Set @WQtdDep = 0

                      if @cb_FlgWms = 0
                        begin
                          if @WQtdPra > 0
                            begin
                              Update PRLOT 
                                 Set Qtd_SolPra = Qtd_SolPra + @WQtdPra
                               Where Cod_Estabe = @PCodEstabe 
                                 /*And Cod_Dep = @WCodDepCan        DMD-8136*/
                                 And Cod_Produt = @it_CodPrd 
                                 and Cod_Lote = @it_CodLot
                                 And Qtd_SldPra >= @WQtdPra
                              if @@rowcount = 0
                                begin
                                  Set @WFlgErr = 1
                                  Set @WMsg = 'Inconsistencia nos lotes. Pedido deve ser cancelado'
                                end
                            end
                          if @WQtdDep > 0
                            begin
                              Update PRLOT 
                                 Set Qtd_SolDep = Qtd_SolDep + @WQtdDep
                               Where Cod_Estabe = @PCodEstabe 
                                 /*And Cod_Dep = @WCodDepCan        DMD-8136*/
                                 And Cod_Produt = @it_CodPrd 
                                 and Cod_Lote = @it_CodLot
                                 And Qtd_SldDep >= @WQtdDep
                              if @@rowcount = 0
                                begin
                                  Set @WFlgErr = 1
                                  Set @WMsg = 'Inconsistencia nos lotes. Pedido deve ser cancelado'
                                end
                          end
                        end

                      Update PRXES
                         Set Qtd_Solici = Qtd_Solici + @WQtdPra + @WQtdDep
                       Where Cod_Estabe = @PCodEstabe 
                         And Cod_Produt = @it_CodPrd
                    end                

                  else
                    begin
                      Set @WFlgErr = 1
                      Set @WMsg = 'Item inexistente no pedido: '+cast(@it_CodPrd as varchar)+'/'+@it_CodLot+'. Pedido deve ser cancelado'
                    end                

                if @WFlgErr = 0 
                  begin
                    -- identifica bonificacao  
                    Set @it_TipSai = ''
                    if (@it_CodCfo = 5910) or (@it_CodCfo = 6910)
                      Set @it_TipSai = 'B'
                      
                    if @cb_CodCli > 0 
                      begin
                         -- atualiza verbas do cliente 
                        if ((@it_VlrVrbPar <> 0) or (@it_VlrVrbBon <> 0)) and (@cb_TipNot = 'V') and (@it_TipSai = '')
                          begin
                            Set @it_VlrVrbPar = -@it_VlrVrbPar
                            Set @it_VlrVrbBon = -@it_VlrVrbBon
                            
                            Exec PR_AtualizaSaldoVBCSD @PCodEstabe, @cb_CodCli, @WDatCan, 0, @it_CodPrd, @it_CodLot, 'S', 'C', @PSerNot, @PNumNot, @it_VlrVrbPar, @it_VlrVrbBon, 'CANCELAMENTO NF', 'SISTEMA'
                            if (@@error <> 0)
                              begin
                                if @@trancount > 0
                                  Rollback Transaction
                                Return
                              end
                          end
                      end
 
                     -- grava movimento relativo a remessa/venda em consignação: CFOP: 5917/6917,  5112/6112, 5113/6113, 5114/6114 
                    if (@cb_IdConsig > 0) and (@cb_NumSeqCtr > 0) and (dbo.FN_CfopConsigValido(@cb_CodCfo) = 1)
                      begin
                        if dbo.FN_TipoNFConsig(@cb_CodCfo) = 'R'
                          Set @CodTipSaiCng = 'NFR'
                        else
                          Set @CodTipSaiCng = 'NFF'

                        Exec PR_GravaMovimeCNGMV @PCodEstabe, @cb_IdConsig, @it_CodPrd, @it_CodLot,
                                                 @cb_DatEmi, 'S', @CodTipSaiCng, @PSerNot, @PNumNot, @it_TipSai, 'C', 
                                                 @WQtdMov, @it_PrcUni
                        if (@@error <> 0)
                          begin
                            if @@trancount > 0
                              Rollback Transaction
                            Return
                          end
                      end

                    -- verba
                    -- @pc_CtlSld já está com controle da política do cabeçalho (default)
                    if Exists (Select 1 From POCOM Where Id_PolCom = @it_IdPolCom)
                      Select @pc_CtlSld = pc.Controle_Saldo
                        From POCOM pc
                       Where pc.Id_PolCom = @it_IdPolCom

                    if @pc_CtlSld = 'V' -- Vendedor/Operador
                      begin
                        -- atualiza verba de politica para vendedor  cuidado que pode ser NF de bonificacao tb
            if (@it_VlrVrbPolVdr <> 0) and (@cb_CodVdr >  0)
                          begin
                            Set @it_VlrVrbPolVdr = -@it_VlrVrbPolVdr
                            Exec PR_AtualizaSaldoVBSLD @PCodEstabe, @cb_CodVdr, @WDatCan, 0, @it_CodPrd, @it_CodLot, @it_TipSai, 'S', 'C', @PSerNot, @PNumNot, @it_VlrVrbPolVdr, 'CANCELAMENTO NF', 'SISTEMA'
                            if (@@error <> 0)
                              begin
                                if @@trancount > 0
                                  Rollback Transaction
                                Return
                              end
                          end

            -- atualiza verba de politica para Operador. Cuidado que pode ser NF de bonificação tb
            if (@it_VlrVrbPolOpe <> 0) and (@cb_CodOpe > 0)
              begin
              Set @it_VlrVrbPolOpe = -@it_VlrVrbPolOpe
              Exec PR_AtualizaSaldoVBSLD @PCodEstabe, @cb_CodOpe, @WDatCan, 0, @it_CodPrd, @it_CodLot, @it_TipSai, 'S', 'C', @PSerNot, @PNumNot, @it_VlrVrbPolOpe, 'CANCELAMENTO NF', 'SISTEMA'
              if (@@error <> 0)
                begin
                                if @@trancount > 0
                                  Rollback Transaction
                Return
                end
              end

                        -- atualiza verba de politica para supervidsor
            if (@it_VlrVrbPolSup <> 0) and (@cb_CodSup > 0)
                          begin
                            Set @it_VlrVrbPolSup = -@it_VlrVrbPolSup
                            Exec PR_AtualizaSaldoVBSSD @PCodEstabe, @cb_CodSup, @WDatCan, 0, @it_CodPrd, @it_CodLot, @it_TipSai, 'S', 'C', @PSerNot, @PNumNot, @it_VlrVrbPolSup, 'CANCELAMENTO NF', 'SISTEMA'
                            if (@@error <> 0)
                              begin
                                if @@trancount > 0
                                  Rollback Transaction
                                Return
                              end
                          end
                      end  -- if @pc_CtlSld = 'V' -- Vendedor/Operador

                    if @pc_CtlSld = 'F' -- Fabricante
                      begin
                        -- atualiza verba de politica para Vendedor. Cuidado que pode ser NF de bonificação tb
            if (@it_VlrVrbPolVdr <> 0) and (@cb_CodVdr > 0)
              begin
              Set @it_VlrVrbPolVdr = -@it_VlrVrbPolVdr
              Exec PR_AtualizaSaldoVBFSL @PCodEstabe, @cb_CodVdr, @it_CodFab, @WDatCan, 0, @it_CodPrd, @it_CodLot, @it_TipSai, 'S', 'C', @PSerNot, @PNumNot, @it_VlrVrbPolVdr, 'CANCELAMENTO NF', 'SISTEMA'
              if (@@error <> 0)
                begin
                                if @@trancount > 0
                                  Rollback Transaction
                Return
                end
              end
                      
            -- atualiza verba de politica para Operador. Cuidado que pode ser NF de bonificação tb
            if (@it_VlrVrbPolOpe <> 0) and (@cb_CodOpe > 0)
              begin
              Set @it_VlrVrbPolOpe = -@it_VlrVrbPolOpe
              Exec PR_AtualizaSaldoVBFSL @PCodEstabe, @cb_CodOpe, @it_CodFab, @WDatCan, 0, @it_CodPrd, @it_CodLot, @it_TipSai, 'S', 'C', @PSerNot, @PNumNot, @it_VlrVrbPolOpe, 'CANCELAMENTO NF', 'SISTEMA'
              if (@@error <> 0)
                begin
                                if @@trancount > 0
                                  Rollback Transaction
                Return
                end
              end
            end  -- if @pc_CtlSld = 'F' -- Fabricante

                    -- verba fornecedor   
                    Set @WValBru = Round(@it_QtdPrd*@it_PrcFab,2)
                    Set @WValEdi = Round(@it_QtdPrd*@it_PrcUniPde*(1-@it_PerDscPde/100),2)
                    if @WValEdi > 0
                      begin
                        Set @WValMov = @WValBru - @WValEdi
                        Set @WCodFor = IsNull((Select fb.Cod_ForPref From PRODU pr Inner Join FBXES fb on pr.Cod_Fabricante = fb.Cod_Fabric and @PCodEstabe = fb.Cod_Estabe
                                                Where pr.Codigo = @it_CodPrd),0)
                        if (@WCodFor > 0) and (@WValMov > 0) and (@it_TipSai = '')
                          begin
                            Set @WValMov = -@WValMov
                            Exec PR_AtualizaSaldoVBFSD @PCodEstabe, @WCodFor, @WDatCan, 0, @it_CodPrd, @it_CodLot, 'S', 'X', @PSerNot, @PNumNot, @WValMov, 'SAIDA NF', 'SISTEMA'
                            if (@@error <> 0)
                              begin
                                if @@trancount > 0
                                  Rollback Transaction
                                Return
                              end
                          end
                      end
                      
                  end

                Fetch Next From NFSIT_Cr
                  Into @it_CodPrd, @it_CodLot, @it_SeqIte, @it_QtdPrd, @it_QtdBon, @it_PrcUni,
                       @it_CodCfo, @it_PrcFab, @it_PrcUniPde, @it_PerDscPde,
                       @it_QtdPra, @it_QtdDep, @it_VlrVrbPolVdr, @it_VlrVrbPolOpe, @it_VlrVrbPolSup, @it_VlrVrbPar, 
                       @it_VlrVrbBon, @it_IdPolCom, @it_CodFab 
              end
            Close NFSIT_Cr
            Deallocate NFSIT_Cr

            if @WFlgErr = 1
              begin
                if @WMsg <> ''
                  RAISERROR(@WMsg,16,1)
                if @@trancount > 0
                  Rollback Transaction
                Return
              end

            -- cancela os titulos
            Exec PR_CancelaDevolveTitulosCTREC @PCodEstabe, @PSerNot, @PNumNot, @PNomUsu, 'C', 0, 0
            if @@error <> 0
              begin
                if @@trancount > 0
                  Rollback Transaction
                Return
              end

            -- atualiza estatisticas da nota: cabeçalho e itens
            Exec PR_AtualizaEstatisticasNFS @PCodEstabe, @PSerNot, @PNumNot, 'C'
            if @@error <> 0
              begin
                if @@trancount > 0
                  Rollback Transaction
                Return
              end

            -- atualiza verbas
            if @cb_ValDebVrbVdr > 0
              begin
                Exec PR_AtualizaSaldoVBSLD @PCodEstabe, @cb_CodVdr, @WDatCan, 0, 0, '', '', 'S', 'C', @PSerNot, @PNumNot, @cb_ValDebVrbVdr, 'CANCELAMENTO NF', 'SISTEMA'
                if (@@error <> 0)
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end
              end



            -- cancela o pedido
            if (@PFlgCanPdv = 1) and Exists(Select Numero From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @cb_CodPdv and Status1 <> 'C')
              begin
                Update PDVCB
                   Set Bloqueio = 'SR'
                 Where Cod_Estabe = @PCodEstabe 
                   And Numero = @cb_CodPdv and Status1 <> 'C'

                Exec PR_CancelaPDV @PCodEstabe, @Cb_CodPdv, @PNomUsu, 0
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end
              end

            -- reabre o pedido
            if (@PFlgCanPdv = 0) and (@WFlgReaPdvOk = 1)
              begin
                Update PDVCB
                   Set Status1 = 'P',
                       Status2 = 'A',
                       Cod_SerNfs = null,
                       Cod_NumNfsIni = null,
                       Cod_NumNfsFim = null,
                       Cod_FunSeparador = 0,
                       Cod_FunConferidor = 0,
                       Cod_FunEmbalador = 0,
                       Qtd_Volumes = 0,
                       Qtd_Peso = 0,
                       Hor_PreNota = null,
                       Hor_Fatura = null,
                       Hor_Saida = null,
                       Hor_ConferIni = null,         
                       Hor_ConferFim = null         
                 Where Cod_Estabe = @PCodEstabe 
                   And Numero = @cb_CodPdv

                -- Elimina Solicitacao de Lotes
                Delete From PDVLT
                 Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @cb_CodPdv

                -- Elimina a conferencia
                Delete From CPVIT
                 Where Cod_Estabe = @PCodEstabe And Num_PedCnf = @cb_CodPdv

                Delete From CPVCB
                 Where Cod_Estabe = @PCodEstabe And Num_PedCnf = @cb_CodPdv
  
                -- tem que excluir nota nao fiscal
                if @cb_CodCfo = 0
                  begin
                    Delete from NFSIT 
                     Where Cod_Estabe = @PCodEstabe 
                       and Ser_Nota = @PSerNot and Num_Nota = @PNumNot

                    Delete from NFSCB
                     Where Cod_Estabe = @PCodEstabe 
                      and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
                  end
                else
                  begin
                    Update NFSCB
                       Set Cod_Pedido = 0
                     Where Cod_Estabe = @PCodEstabe 
                       and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
                  end
              end  -- -- reabre o pedido

            -- atualiza contratos
            if (@cb_CodCtr > 0) and (@cb_NumSeqCtr > 0)
              begin
                Exec PR_RetornarItensCtrHospitalar @PCodEstabe, @cb_CodCtr, @cb_NumSeqCtr 
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end
              end

            -- atualiza itens na tabela de consignações
            if (@cb_IdConsig > 0) and (@cb_NumSeqCtr > 0)
              begin
                Exec PR_FaturaConsignacao 'S', @PCodEstabe, @PSerNot, @PNumNot, @cb_IdConsig, @cb_NumSeqCtr
                if (@@error <> 0)
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end
              end

            -- estorna vale
            if (@cb_TipNot = 'D') and ((@cb_CodCli > 0) or (@cb_CodFun > 0) or (@cb_CodFor > 0))
              begin
                if @cb_CodCli > 0
                  begin
                    Set @WTipDes = 'CLI'
                    Set @WCodDes = @cb_CodCli
                  end
                else
                if @cb_CodFun > 0
                  begin
                    Set @WTipDes = 'FUN'
                    Set @WCodDes = @cb_CodFun
                  end
                else
                if @cb_CodFor > 0
                  begin
                    Set @WTipDes = 'FOR'
                    Set @WCodDes = @cb_CodFor
                  end
                  
                if Exists(Select Cod_Vale From VALES
                           Where Cod_Estabe = @PCodEstabe 
                             And Cod_CtrLanAut = 'DNS'
                             And Num_CtrLanAut = @PNumNot
                             And Tip_Entid = @WTipDes
                             And Cod_Entid = @WCodDes
                             And Deb_Cre = 'D'
                             And Round(Val_Vale,2) = Round(@cb_ValNot,2))
                  begin
                    Delete From VALES
                     Where Cod_Estabe = @PCodEstabe 
                       And Cod_CtrLanAut = 'DNS'
                       And Num_CtrLanAut = @PNumNot
                       And Tip_Entid = @WTipDes
                       And Cod_Entid = @WCodDes
                       And Deb_Cre = 'D'
                       And Round(Val_Vale,2) = Round(@cb_ValNot,2)
                    if @@ROWCOUNT = 0
            begin                  
                        Set @va_IsnCtaFinDeb = 0
                        Set @va_IsnCtaFinCre = 0

                        -- pega contas gerenciais invertidas
                        if @pm_FlgUsaInterv = 1 
                          begin
                            Select @va_IsnCtaFinDeb = IsNull(Isn_CtaFinCre,0), 
                                   @va_IsnCtaFinCre = IsNull(Isn_CtaFinDeb,0)
                              From VALES
                             Where Cod_Estabe = @PCodEstabe 
                               And Cod_CtrLanAut = 'DNS'
                               And Num_CtrLanAut = @PNumNot
                               And Tip_Entid = @WTipDes
                               And Cod_Entid = @WCodDes
                               And Deb_Cre = 'D'
                          end
                  
                        -- inclui vale
                        EXEC PR_ProxNumero 'Vale', @WCodDoc output
                        if @@error <> 0
                          begin
                            if @@trancount > 0
                              Rollback Transaction
                            Return
                          end

                        Insert into VALES
                          (Cod_Estabe, Cod_Vale, Des_Vale, Tip_Entid, Cod_Entid, Dat_Emissa, Val_Vale, Deb_Cre, 
                           Cod_CtrLanAut, Num_CtrLanAut, Isn_CtaFinDeb, Isn_CtaFinCre, Usuario, Transacao)
                        Values
                          (@PCodEstabe, @WCodDoc,'NFS Cancelamento Devolucao: '+@PSerNot+'/'+cast(@PNumNot as varchar), @WTipDes, @WCodDes, @Date, @cb_ValNot, 'C',
                           'DNS', @PNumNot, @va_IsnCtaFinDeb, @va_IsnCtaFinCre, @cb_Usuario,@Now)
                      end
                  end
              end  -- estorna vale
              
          end
          
      -- exclui lançamentos em PCMOV
      while exists(Select Isn_CtaFin 
                     From PCMOV
                    Where Cod_Estabe = @PCodEstabe
                      And Nom_Tabela = 'NFSCB'
                      And Tip_Docume = 'NFS'
                      And Ser_Docume = @PSerNot
                      And Num_Docume = @PNumNot)
        begin
          Select top 1 @va_IsnCtaFinDeb = Isn_CtaFin, 
                       @va_DatMovime = Dat_Movime,
                       @va_NumSequen = Num_Sequen    
            From PCMOV
           Where Cod_Estabe = @PCodEstabe
             And Nom_Tabela = 'NFSCB'
             And Tip_Docume = 'NFS'
             And Ser_Docume = @PSerNot
             And Num_Docume = @PNumNot
    
          -- elimina registro em PCMOV
          Delete From PCMOV
           Where Cod_Estabe = @PCodEstabe
             And Nom_Tabela = 'NFSCB'
             And Tip_Docume = 'NFS'
             And Ser_Docume = @PSerNot
             And Num_Docume = @PNumNot
             And Isn_CtaFin = @va_IsnCtaFinDeb

          -- reprocessa saldo PCMOV
          Exec PR_ReprocessaPCMOV @va_IsnCtaFinDeb, @va_DatMovime
        end             

    end -- if @FlgPodeCancelar = 1

  if @@trancount > 0
    COMMIT TRANSACTION
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE TRIGGER [dbo].[TR_FS_NFXML_InsertUpdate] ON [dbo].[FS_NFXML] 
FOR INSERT, UPDATE
NOT FOR REPLICATION
AS

SET NOCOUNT ON 

if Update(Des_Cstat)
  begin

	DECLARE @ArqXML       varchar(max),
            @ArqXMLCancel varchar(max),
            @CodEstab     int,	
            @NumNota      int,		    
            @SerNota      varchar(3),
            @CodCStat     smallint,
            @DesCstat     varchar(4),
            @DesXMotivo   varchar(255),
            @TipNf        varchar(1),
            @ChvNfe       varchar(50),
            @DesXJust     varchar(200),
            @NumProtoc    int,
            @Usuario      varchar(15),
            @FlgCanPdv    bit
	
    Select @ArqXML  = x.Xml_Nfeproc, 
           @CodEstab = x.Cod_Estabe,
           @SerNota = x.Ser_Nota,
           @NumNota = x.Num_Nota, 
           @NumProtoc = x.Protocolo,
           @CodCstat = CAST(i.Des_Cstat as smallint),
           @DesCstat = i.Des_Cstat, 
           @DesXMotivo = substring(x.Des_XMotivo,1,255), 
           @TipNf = x.Tip_Nf,
           @ArqXMLCancel = x.Xml_Inu_can, 
           @ChvNfe = x.Chv_Nfe, 
           @DesXJust = x.Des_XJust,
           @FlgCanPdv = x.Flg_CanPdv
      From Inserted I 
           Inner Join FS_NFXML x On x.Seq_Xml = I.Seq_Xml and x.Cod_Estabe = I.Cod_Estabe

	-- Usuario Infarma/Banco	 
	set @Usuario = substring(dbo.FN_UsuarioInfarma(),1,15)

	-- Garantir que imprima para impressora padrão mesmo se não configurar DMD.ini
	Update a 
       Set a.Des_Impressora = (Select top 1 DesImpNotFis from PARAM Where Cod_Estabe = @CodEstab)
	  From FS_NFXML a
           Inner Join Inserted I On a.Cod_Estabe = I.Cod_Estabe and a.Seq_Xml = I.Seq_Xml
 	 Where ltrim(rtrim(isnull(I.Des_Impressora,''))) = ''
	   And IsNull(I.Flg_Impresso,0) = 0
	
    if @TipNf = 'S'
      begin		
        Update NFSCB 
           Set Arquivo = @ArqXML,
               Ret_CStat = @CodCstat,
               Ret_XMotivo = @DesXMotivo,
               Xml_Cancelamento = @ArqXMLCancel,
               Chv_Acesso = @ChvNfe,
               Des_JusCan = @DesXJust,
 	 		   Flg_Storage = '0',
			   Usuario = @Usuario
        Where Cod_Estabe= @CodEstab
          And Ser_Nota  = @SerNota 
          And Num_Nota  = @NumNota 

        if CHARINDEX(@DesCstat,';101;151;135;155;205;301;302;303;') > 0
          begin
            if CHARINDEX(@DesCstat,';205;301;302;303;') > 0
              begin
                Set @FlgCanPdv = 1
              end

			-- Forçar o cancelamento do documento com integração WMS
			-- Se está ativa a integração já informa com status de processado pelo X3
			-- Se não deve limpar o status 
			if IsNull( (Select FlgIntegrWmsExt From PMEST Where Cod_Estabe = @CodEstab),0 ) = 1
			  Update NFSCB 
                 Set Sta_IntWms = '4'
			   Where Cod_Estabe = @CodEstab And Ser_Nota = @SerNota and Num_Nota = @NumNota
			else
			  Update NFSCB 
                 Set Sta_IntWms = ''
			   Where Cod_Estabe = @CodEstab And Ser_Nota = @SerNota and Num_Nota = @NumNota

            Exec PR_ExcluiCancelaNFSCB @CodEstab, @SerNota, @NumNota, 15, @Usuario, @FlgCanPdv
          end
		 else if @DesCstat = '100'
		  begin
			Exec PR_RegistraEmailXml @CodEstab, @SerNota, @NumNota
		  end

        end
		
    if @TipNf = 'E'
      begin		
        Update NFECB 
           Set Arquivo = @ArqXML,
               Ret_CStat = @CodCstat,
               Ret_XMotivo = @DesXMotivo,
               Xml_Cancelamento = @ArqXMLCancel,
               Chv_Acesso = @ChvNfe,
               Des_JusCan = @DesXJust,
               Flg_Storage = '0',
               Usuario = @Usuario
		 Where Cod_Estabe = @CodEstab		
           And Protocolo  = @NumProtoc 

        if @DesCstat = '101' or @DesCstat = '151' or @DesCstat = '135' or @DesCstat = '155' or @DesCstat = '302'
          begin
            Exec PR_CancelaMovNFECB @CodEstab,@NumProtoc,@Usuario
          end
      end
  end

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE TRIGGER [dbo].[TR_PRLOT_AtualizaSaldoDisponivel] ON [dbo].[PRLOT] 
FOR INSERT, UPDATE, DELETE
NOT FOR REPLICATION 
AS

-- comando p/ corrigir erro delphi/ado: record was changed by another user
SET NOCOUNT ON 

Declare @FlgAtu bit

Update L
   Set L.Fat_CnvAprEmbPad = ap.Fat_CnvApr
  From PRLOT L   
       Inner Join PARAM pm on L.Cod_Estabe = pm.Cod_Estabe
       Inner Join PRXAP ap on L.Cod_Produt = ap.Cod_Produt and ap.Flg_Padrao = 1
       Inner Join Inserted I on L.Cod_Estabe = I.Cod_Estabe and L.Cod_Dep = I.Cod_Dep and 
	                            L.Cod_Produt = I.Cod_Produt and L.Cod_Lote = I.Cod_Lote
 Where Case When IsNull(pm.FlgAltUnvItePdv,0) = 1 then ap.Fat_CnvApr
            Else 1
       End <> L.Fat_CnvAprEmbPad

Set @FlgAtu = 0

if Update(Qtd_FisPra) or Update(Qtd_SolPra)
  begin
    Set @FlgAtu = 1
    Update L
       Set L.Qtd_SldPra = IsNull(I.Qtd_FisPra,0) - IsNull(I.Qtd_SolPra,0)
      From Inserted I 
           inner Join PRLOT L on L.Cod_Estabe = I.Cod_Estabe and L.Cod_Dep = I.Cod_Dep and L.Cod_Produt = I.Cod_Produt and L.Cod_Lote = I.Cod_Lote
  end

if Update(Qtd_FisDep) or Update(Qtd_SolDep)
  begin
    Set @FlgAtu = 1
    Update L
       Set L.Qtd_SldDep = IsNull(I.Qtd_FisDep,0) - IsNull(I.Qtd_SolDep,0)
      From Inserted I 
           inner Join PRLOT L on L.Cod_Estabe = I.Cod_Estabe and L.Cod_Dep = I.Cod_Dep and L.Cod_Produt = I.Cod_Produt and L.Cod_Lote = I.Cod_Lote
  end

if @FlgAtu = 1
  begin
    Update L
       Set L.Qtd_Fisico = IsNull(I.Qtd_FisPra,0) + IsNull(I.Qtd_FisDep,0),
           L.Qtd_Solicitado = IsNull(I.Qtd_SolPra,0) + IsNull(I.Qtd_SolDep,0),
           L.Qtd_Saldo = IsNull(I.Qtd_FisPra,0) - IsNull(I.Qtd_SolPra,0) + IsNull(I.Qtd_FisDep,0) - IsNull(I.Qtd_SolDep,0)
      From Inserted I 
           inner Join PRLOT L on L.Cod_Estabe = I.Cod_Estabe and L.Cod_Dep = I.Cod_Dep and L.Cod_Produt = I.Cod_Produt and L.Cod_Lote = I.Cod_Lote
  end

-- Atualiza quantidades em DPXPR (em 29/11/2016)
Insert into DPXPR(Cod_Estabe, Cod_Dep, Cod_Produt)
  Select distinct I.Cod_Estabe, I.Cod_Dep, I.Cod_Produt
    From Inserted I 
         inner Join PRLOT L on L.Cod_Estabe = I.Cod_Estabe and L.Cod_Dep = I.Cod_Dep and L.Cod_Produt = I.Cod_Produt and L.Cod_Lote = I.Cod_Lote
   Where not Exists(Select 1 From DPXPR dp
                      Where I.Cod_Estabe = dp.Cod_Estabe And I.Cod_Dep = dp.Cod_Dep and I.Cod_Produt = dp.Cod_Produt)

Update P
   Set P.Qtd_Fisico = IsNull(x.QtdFis,0)+IsNull(y.QtdFis,0)
  From DPXPR P  
       inner join Inserted I on (P.Cod_Estabe = I.Cod_Estabe And P.Cod_Dep = I.Cod_Dep And P.Cod_Produt = I.Cod_Produt) 
       left  join (Select Cod_Estabe, Cod_Dep, Cod_Produt, Sum(Qtd_Fisico) as QtdFis
                     From PRLTL 
                    Where Qtd_Saldo > 0
                    Group by Cod_Estabe, Cod_Dep, Cod_Produt) x on (P.Cod_Estabe = x.Cod_Estabe and P.Cod_Dep = x.Cod_Dep and P.Cod_Produt = x.Cod_Produt)
       left  join (Select Cod_Estabe, Cod_Dep, Cod_Produt, Sum(Qtd_Fisico) as QtdFis
                     From PRLOT
                    Where Qtd_Saldo > 0
                    Group by Cod_Estabe, Cod_Dep, Cod_Produt) y on (P.Cod_Estabe = y.Cod_Estabe and P.Cod_Dep = y.Cod_Dep and P.Cod_Produt = y.Cod_Produt)
 Where @FlgAtu = 1

-- ATualiza Vencto prox. lote em PRXES
Update P
   Set P.Dat_PrxVctLot = l.Dat_Vencim
  From PRXES P  
       inner join Inserted I on (P.Cod_Estabe = I.Cod_Estabe And P.Cod_Produt = I.Cod_Produt) 
       left  join (Select Cod_Estabe, Cod_Produt, Dat_Vencim = MIN(Dat_Vencim) 
                     From PRLOT 
                    Where Qtd_Saldo > 0 
                    Group by Cod_Estabe, Cod_Produt) l on ((P.Cod_Estabe = l.Cod_Estabe) and (P.Cod_Produt = l.Cod_Produt)) 
 Where @FlgAtu = 1

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-----------------------------------------------------------------------------------------------------------
----  Rotina para reprocessar custos custos em (PRXES, HSPRC, NFEIT, NFSIT)  de                        ----
----  NF Entradas a partir da data base definida                                                       ----
----  PRXES: Prc_CusLiqEnt, Prc_CusLiqEntDep, Prc_CusMed, Prc_CusMedCom, Prc_CusMedPra, Prc_CusMedDep  ----
----  HSPRC: Vlr_CusLiqPra, Vlr_CusLiqDep,    Vlr_CusMed, Vlr_CusMedCom, Vlr_CusMedPra, Vlr_CusMedDep  ----
----  NFEIT: Prc_CusMedAnt, Prc_CustoMedio                                                             ----  
----  NFSIT: Vlr_CusIte                                                                                ----
-----------------------------------------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[PR_ReprocessaCustosEntrada]
@PCodEstabe int,
@PMesMov smallint,        -- mes inicial
@PAnoMov smallint,        -- ano inicial
@PCodPrd int,             -- 0 = todos os produtos
@PFlgBlqAltUltPrcCMC Bit  -- 1 = Bloqueia alteração do ultimo custo comercial do produto

AS

SET NOCOUNT ON

SET DATEFORMAT ymd

BEGIN

  Declare @DatRef smalldatetime,  -- data inicial
          @DatBas smalldatetime,
          @CodPrdIni int,
          @CodPrdFin int,
          @CodPrd int,
          @NumSeq int,
          @DatMov smalldatetime,
          @DatMovAnt smalldatetime,
          @DatUltEnt smalldatetime,
          @DatUltEntPra smalldatetime,
          @DatUltEntDep smalldatetime,
          @QtdSldPraAnt int,
          @QtdSldDepAnt int,
          @QtdSldDiaAnt int,
          @NumPrt int, 
          @PrcVenPrd numeric (18,4),
          @VlrPrcVenHis numeric (18,4),
          @QtdEnt int,
          @VlrBasCalSubTriUni numeric(18,4),
          @CusLiqPraAnt numeric (18,4), 
          @CusLiqDepAnt numeric (18,4), 
          @CusMedGerAnt numeric (18,4),
          @CusMedComAnt numeric (18,4),
          @CusMedPraAnt numeric (18,4),
          @CusMedDepAnt numeric (18,4),
          @VlrBasCalSubTriEntMedAnt numeric(18,4),
          @CusLiqPraNew numeric (18,4), 
          @CusLiqDepNew numeric (18,4), 
          @CusMedGerNew numeric (18,4),
          @CusMedComNew numeric (18,4),
          @CusMedPraNew numeric (18,4),
          @CusMedDepNew numeric (18,4),
          @VlrBasCalSubTriEntMedNew numeric(18,4),
          @CodCfoCab int, 
          @CodCfoIte int, 
          @CusLiqUni numeric (18,4),
          @CusLiqComUni numeric (18,4),
          @PrcUniMed numeric (18,4),
          @DscUniMed numeric (8,4)

  -- CFOp bonificacao
  Declare @KCfoBonEntInt int = 1910,
          @KCfoBonEntExt int = 2910		         

  Set @DatRef = Cast(Cast(@PAnoMov as varchar)+'-'+Cast(@PMesMov as varchar)+'-01 00:00:00' as smalldatetime)

  BEGIN TRY
    BEGIN TRANSACTION

    -- desabilita triggers de PRODU que atualiza historico de precos
    ALTER TABLE PRODU DISABLE TRIGGER ALL
    ALTER TABLE PRXES DISABLE TRIGGER ALL

    -----------------------------------------------------------------------
    -- seleciona itens de nota de entrada a partir da data de movimento  --
    -----------------------------------------------------------------------
    Set @CodPrdIni = 0
    Set @CodPrdFin = 999999999
	if @PCodPrd > 0
      begin
        Set @CodPrdIni = @PCodPrd
        Set @CodPrdFin = @PCodPrd
      end


    Declare HSPRC_Cr Cursor Local For 
    
      Select distinct it.Cod_Produto, pr.Dat_UltCompra, pr.Dat_UltEntDep, pr.Prc_Venda
        From NFECB cb 
             Inner Join NFEIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Protocolo = it.Protocolo
             Inner Join PRXES pr on it.Cod_Estabe = pr.Cod_Estabe and it.Cod_Produto = pr.Cod_Produt
       Where cb.Cod_Estabe = @PCodEstabe
         and cb.Status = 'F'
         and cb.Flg_MovEst = 1 
         and cb.Flg_AtuPrcCus = 1 
         and IsNull(cb.Dat_Movimento,0) > 0
         and cb.Dat_Movimento >= @DatRef
         and it.Cod_Produto between @CodPrdIni and @CodPrdFin
       Order by it.Cod_Produto
    
    Open HSPRC_Cr
    Fetch Next From HSPRC_Cr Into @CodPrd, @DatUltEntPra, @DatUltEntDep, @PrcVenPrd
    While @@FETCH_STATUS = 0
      begin
        Set @DatMov = null

        -- Normaliza registros em NFEIT
        Update it
           Set it.Dat_Movimento = cb.Dat_Movimento
          From NFECB cb 
               Inner Join NFEIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Protocolo = it.Protocolo
         Where cb.Cod_Estabe = @PCodEstabe     
           and cb.Status = 'F'
           and cb.Flg_MovEst = 1 
           and cb.Flg_AtuPrcCus = 1 
           and cb.Dat_Movimento >= @DatRef
           and it.Cod_Produto = @CodPrd
           and IsNull(it.Dat_Movimento,0) <> cb.Dat_Movimento

        -- ultima entrada do produto
        Select top 1 @DatMov = it.Dat_Movimento,
                     @CodCfoCab = cb.Cod_Cfo
          From NFECB cb 
               Inner Join NFEIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Protocolo = it.Protocolo
         Where cb.Cod_Estabe = @PCodEstabe     
           and cb.Status = 'F'
           and cb.Flg_MovEst = 1 
           and cb.Flg_AtuPrcCus = 1 
           and it.Cod_Produto = @CodPrd
         Order by cb.Dat_Movimento desc

        -- normaliza registros em NFEIT        
        if @DatMov is not null
          begin
            if @CodCfoCab > 0 
              Set @DatUltEnt = @DatUltEntPra 
            else
              Set @DatUltEnt = @DatUltEntDep
    
            -- verifica data minima inicial processamento
            if @DatMov > @DatRef
              begin
                Select top 1 @DatMov = it.Dat_Movimento
                  From NFECB cb 
                       Inner Join NFEIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Protocolo = it.Protocolo
                 Where cb.Cod_Estabe = @PCodEstabe     
                   and cb.Status = 'F'
                   and cb.Flg_MovEst = 1 
                   and cb.Flg_AtuPrcCus = 1 
                   and cb.Dat_Movimento >= @DatRef
                   and it.Cod_Produto = @CodPrd
                 Order by it.Dat_Movimento
              end
              
            Set @DatBas = @DatMov   

            -- seleciona itens de nota de entrada a partir da data base ordenadaos pela data
            Declare TABLE_Cr Cursor Local For 
           
              Select cb.Cod_Cfo, it.Dat_Movimento, it.Protocolo, it.Cod_Cfo,
                     sum(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0)),
                     sum(it.Cus_LiqUni*it.Qtd_Pedido)/sum(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0)),
                     case 
                       When IsNull(it.Vlr_DscIte2,0) > 0 then sum(it.Cus_LiqUni*it.Qtd_Pedido+it.Vlr_DscIte2)/sum(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0))
                       Else sum(it.Cus_LiqUni*it.Qtd_Pedido)/sum(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0))
                     end,
                     sum(it.Prc_Unitario*(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0)))/sum(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0)),
                     sum(it.Per_DescItem*it.Prc_Unitario*(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0)))/sum(it.Prc_Unitario*(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0))),
                     case
                       When ((cb.Tip_NF = 'C') or (cb.Tip_NF = 'T') or (cb.Cod_Cfo = @KCfoBonEntExt) or (cb.Cod_Cfo = @KCfoBonEntInt)) 
                         then sum(it.Vlr_BasSubsTrib)/sum(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0))
                       Else 0
                     end
                From NFEIT it 
                     Inner Join NFECB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Protocolo = cb.Protocolo
               Where cb.Cod_Estabe = @PCodEstabe     
                 and cb.Status = 'F'
                 and cb.Flg_MovEst = 1 
                 and cb.Flg_AtuPrcCus = 1 
                 and cb.Dat_Movimento >= @DatBas
                 and it.Cod_Produto = @CodPrd
               Group by cb.Cod_Cfo, it.Dat_Movimento, it.Protocolo, it.Cod_Cfo, cb.Tip_NF, it.Vlr_DscIte2
               Order by it.Dat_Movimento, it.Protocolo
           
            Open TABLE_Cr
            Fetch Next From TABLE_Cr Into @CodCfoCab, @DatMov, @NumPrt, @CodCfoIte, 
                                          @QtdEnt, @CusLiqUni, @CusLiqComUni, @PrcUniMed, @DscUniMed, @VlrBasCalSubTriUni
            While @@FETCH_STATUS = 0
              begin
           
                Set @DatMovAnt = @DatMov

                -- saldos anteriores mais proximos à data da entrada
                Set @QtdSldPraAnt = 0 
                Set @QtdSldDepAnt = 0
                Set @QtdSldDiaAnt = 0

                if Exists(Select 1 
                            From PRSLD
                           Where Cod_Estabe = @PCodEstabe 
                             And Cod_Produt = @CodPrd
                             And Dat_Movime < @DatMov)
                  Select Top 1 @QtdSldPraAnt = IsNull(Qtd_SldPra,0), 
                               @QtdSldDepAnt = IsNull(Qtd_SldDep,0), 
                               @QtdSldDiaAnt = IsNull(Qtd_SldAtu,0)
                    From PRSLD
                   Where Cod_Estabe = @PCodEstabe 
                     And Cod_Produt = @CodPrd
                     And Dat_Movime < @DatMov
                   Order by Dat_Movime desc
           
                if @QtdSldPraAnt < 0 Set @QtdSldPraAnt = 0
                if @QtdSldDepAnt < 0 Set @QtdSldDepAnt = 0
                if @QtdSldDiaAnt < 0 Set @QtdSldDiaAnt = 0

                -- inclui HSPRC
                if not Exists(Select 1 From HSPRC Where Cod_Estabe = @PCodEstabe and Cod_Produto = @CodPrd and Dat_Alteracao = @DatMov)
                  Exec PR_IncluiHSPRC @PCodEstabe, @CodPrd, @DatMov, @NumSeq output   

                -- custos medios imediatamente anteriores a data do movimennto
                Set @CusLiqPraAnt = 0
                Set @CusLiqDepAnt = 0
                Set @CusMedGerAnt = 0
                Set @CusMedComAnt = 0
                Set @CusMedPraAnt = 0
                Set @CusMedDepAnt = 0
                Set @VlrBasCalSubTriEntMedAnt = 0

                if Exists(Select 1
                            From HSPRC
                           Where Cod_Estabe = @PCodEstabe     
                             And Cod_Produto = @CodPrd
                             And Dat_Alteracao < @DatMov)
                  Select Top 1 @CusLiqPraAnt = IsNull(Vlr_CusLiqPra,0), 
                               @CusLiqDepAnt = IsNull(Vlr_CusLiqDep,0), 
                               @CusMedGerAnt = IsNull(Vlr_CusMed,0),
                               @CusMedComAnt = IsNull(Vlr_CusMedCom,0),
                               @CusMedPraAnt = IsNull(Vlr_CusMedPra,0), 
                               @CusMedDepAnt = IsNull(Vlr_CusMedDep,0),
                               @VlrBasCalSubTriEntMedAnt = IsNull(Vlr_BasCalSubTriEntMed,0)
                    From HSPRC
                   Where Cod_Estabe = @PCodEstabe     
                     And Cod_Produto = @CodPrd
                     And Dat_Alteracao < @DatMov
                   Order by Dat_Alteracao desc, Seq_Alteracao desc
           
                if @CusLiqPraAnt < 0 Set @CusLiqPraAnt = 0
                if @CusLiqDepAnt < 0 Set @CusLiqDepAnt = 0
                if @CusMedGerAnt < 0 Set @CusMedGerAnt = 0
                if @CusMedComAnt < 0 Set @CusMedComAnt = 0
                if @CusMedPraAnt < 0 Set @CusMedPraAnt = 0
                if @CusMedDepAnt < 0 Set @CusMedDepAnt = 0
                if @VlrBasCalSubTriEntMedAnt < 0 Set @VlrBasCalSubTriEntMedAnt = 0
           
                While (@DatMovAnt = @DatMov) and (@@FETCH_STATUS = 0)
                  begin
                    if @CodCfoCab > 0
                      Update pr
                         Set pr.Prc_CusLiqEnt = @CusLiqUni,
                             pr.Prc_EntAnt    = pr.Prc_UltEnt,
                             pr.Per_DscEntAnt = pr.Per_DscUltEnt,
                             pr.Qtd_EntAnt    = pr.Qtd_UltEnt,
                             pr.Dat_EntAnt    = pr.Dat_UltCompra,
                             pr.Prc_UltEnt    = @PrcUniMed,
                             pr.Per_DscUltEnt = @DscUniMed,
                             pr.Qtd_UltEnt    = @QtdEnt,
                             pr.Dat_UltCompra = @DatMov
                        From PRXES pr
                       Where pr.Cod_Estabe = @PCodEstabe And pr.Cod_Produt = @CodPrd
                    else
                      Update pr
                         Set pr.Prc_CusLiqEntDep = @CusLiqUni,
                             pr.Prc_EntAntDep    = pr.Prc_UltEntDep,
                             pr.Per_DscEntAntDep = pr.Per_DscUltEntDep,
                             pr.Qtd_EntAntDep    = pr.Qtd_UltEntDep,
                             pr.Dat_EntAntDep    = pr.Dat_UltEntDep,
                             pr.Prc_UltEntDep    = @PrcUniMed,
                             pr.Per_DscUltEntDep = @DscUniMed,
                             pr.Qtd_UltEntDep    = @QtdEnt,
                             pr.Dat_UltEntDep    = @DatMov
                        From PRXES pr
                       Where pr.Cod_Estabe = @PCodEstabe And pr.Cod_Produt = @CodPrd

                    -- atualiza registro de entrada
                    Update NFEIT
                       Set Qtd_FisAnt = @QtdSldDiaAnt,
--                           Vlr_BasCalSubTriEntMedAnt = @VlrBasCalSubTriEntMedAnt,
                           Prc_CusMedAnt = @CusMedGerAnt
                     Where Cod_Estabe = @PCodEstabe
                       And Protocolo = @NumPrt
                       And Cod_Produto = @CodPrd
                       And ((Qtd_FisAnt <> @QtdSldDiaAnt) or (Prc_CusMedAnt <> @CusMedGerAnt))
                
                    Update HSPRC
                       Set Vlr_CusLiqPra = @CusLiqPraAnt,
                           Vlr_CusLiqDep = @CusLiqDepAnt,
                           Vlr_CusMed    = @CusMedGerAnt,
                           Vlr_CusMedCom = Case 
                                             When @PFlgBlqAltUltPrcCMC = 0 then @CusMedComAnt 
                                             Else Vlr_CusMedCom 
                                           End,
                           Vlr_CusMedPra = @CusMedPraAnt,
                           Vlr_CusMedDep = @CusMedDepAnt
--                           Vlr_BasCalSubTriEntMed = @VlrBasCalSubTriEntMedAnt
                     Where Cod_Estabe = @PCodEstabe
                       and Cod_Produto = @CodPrd 
                       and Dat_Alteracao >= @DatMov
                       And ((Vlr_CusMed <> @CusMedGerAnt) or (Vlr_CusMedCom <> @CusMedComAnt) or 
                            (Vlr_CusMedPra <> @CusMedPraAnt) or (Vlr_CusMedDep <> @CusMedDepAnt))

                
                     -- zera saldo se o custo anterior estiver zerado
                    if @CusMedGerAnt = 0
                      Set @QtdSldDiaAnt = 0
                    if @CusMedPraAnt = 0
                      Set @QtdSldPraAnt = 0
                    if @CusMedDepAnt = 0
                      Set @QtdSldDepAnt = 0
                
                    -- custos a calcular
                    Set @CusLiqPraNew = 0
                    Set @CusLiqDepNew = 0
                    Set @CusMedGerNew = 0
                    Set @CusMedComNew = 0
                    Set @CusMedPraNew = 0
                    Set @CusMedDepNew = 0
                
/*               
                    Set @VlrBasCalSubTriEntMedNew = 0

                   -- base de calculo media ST
                    if @VlrBasCalSubTriUni > 0
                      begin
                        Set @VlrBasCalSubTriEntMedNew = (@VlrBasCalSubTriEntMedAnt*@QtdSldDiaAnt + @VlrBasCalSubTriUni*@QtdEnt)/(@QtdSldDiaAnt+@QtdEnt)

                        Update PRXES
                          Set Vlr_BasCalSubTriEntMed = @VlrBasCalSubTriEntMedNew
                        Where Cod_Estabe = @PCodEstabe
                        And Cod_Produt = @CodPrd
                        And @VlrBasCalSubTriEntMedNew > 0
                        And Vlr_BasCalSubTriEntMed <> @VlrBasCalSubTriEntMedNew

                        Update HSPRC
                          Set Vlr_BasCalSubTriEntMed = @VlrBasCalSubTriEntMedNew
                        Where Cod_Estabe = @PCodEstabe
                        And Cod_Produto = @CodPrd 
                        And Dat_Alteracao >= @DatMov
                        And @VlrBasCalSubTriEntMedNew > 0
                        And Vlr_BasCalSubTriEntMed <> @VlrBasCalSubTriEntMedNew
                      end 
*/

                    -- custo medio gerencial
                    -- verifica tipo de bonificacao
                    if ((@CodCfoCab <> @KCfoBonEntInt) and (@CodCfoCab <> @KCfoBonEntExt)) and  -- nao eh nf de bonificacao
                       ((@CodCfoIte = @KCfoBonEntInt) or (@CodCfoIte = @KCfoBonEntExt)) 
                      begin
                        Set @CusMedGerNew = (@CusMedGerAnt*@QtdSldDiaAnt)/(@QtdSldDiaAnt+@QtdEnt)
                        Set @CusMedComNew = (@CusMedComAnt*@QtdSldDiaAnt)/(@QtdSldDiaAnt+@QtdEnt)
                      end
                    else
                      begin
                        Set @CusMedGerNew = (@CusMedGerAnt*@QtdSldDiaAnt+@CusLiqUni*@QtdEnt)/(@QtdSldDiaAnt+@QtdEnt)
                        Set @CusMedComNew = (@CusMedComAnt*@QtdSldDiaAnt+@CusLiqComUni*@QtdEnt)/(@QtdSldDiaAnt+@QtdEnt)
                      end

                    Update PRXES
                       Set Prc_CusMed = @CusMedGerNew
                     Where Cod_Estabe = @PCodEstabe
                       And Cod_Produt = @CodPrd
                       And @CusMedGerNew > 0
                       And Prc_CusMed <> @CusMedGerNew
                
                    
		            if @PFlgBlqAltUltPrcCMC = 0
                      Update PRXES
                         Set Prc_CusMedCom = @CusMedComNew
                       Where Cod_Estabe = @PCodEstabe
                         And Cod_Produt = @CodPrd
                         And @CusMedComNew > 0
                         And Prc_CusMedCom <> @CusMedComNew

                    Update it
                       Set it.Vlr_CusIte = @CusMedGerNew
                      From NFSIT it 
                           Inner Join NFSCB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Ser_Nota = cb.Ser_Nota and it.Num_Nota = cb.Num_Nota
                     Where it.Cod_Estabe = @PCodEstabe
                       And it.Cod_Produto = @CodPrd
                       And cb.Dat_Emissao >= @DatMov
                       And it.Vlr_CusIte <> @CusMedGerNew
                
                    Update HSPRC
                       Set Vlr_CusMed = @CusMedGerNew
                     Where Cod_Estabe = @PCodEstabe
                       And Cod_Produto = @CodPrd 
                       And Dat_Alteracao >= @DatMov
                       And @CusMedGerNew > 0
                       And Vlr_CusMed <> @CusMedGerNew

		            if @PFlgBlqAltUltPrcCMC = 0
                      Update HSPRC
                         Set Vlr_CusMedCom = @CusMedComNew 
                       Where Cod_Estabe = @PCodEstabe
                         And Cod_Produto = @CodPrd 
                         And Dat_Alteracao >= @DatMov
                         And @CusMedComNew > 0
                         And Vlr_CusMedCom <> @CusMedComNew
                
                    -- custo medio 1
                    if @CodCfoCab > 0
                      begin
                        Update PRXES
                           Set Prc_CusLiqEnt = @CusLiqUni,
                               Dat_UltCompra = @DatMov,
                               Qtd_UltEnt = @QtdEnt
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Produt = @CodPrd
                
                        -- verifica tipo de bonificacao
                        if ((@CodCfoCab <> @KCfoBonEntInt) and (@CodCfoCab <> @KCfoBonEntExt)) and  -- nao eh nf de bonificacao
                           ((@CodCfoIte = @KCfoBonEntInt) or (@CodCfoIte = @KCfoBonEntExt)) 
                          begin
                            Set @CusLiqPraNew = (@CusLiqPraAnt*@QtdSldPraAnt)/(@QtdSldPraAnt+@QtdEnt)
                            Set @CusMedPraNew = (@CusMedPraAnt*@QtdSldPraAnt)/(@QtdSldPraAnt+@QtdEnt)
                          end
                        else
                          begin
                            Set @CusLiqPraNew = (@CusLiqPraAnt*@QtdSldPraAnt+@CusLiqUni*@QtdEnt)/(@QtdSldPraAnt+@QtdEnt)
                            Set @CusMedPraNew = (@CusMedPraAnt*@QtdSldPraAnt+@CusLiqUni*@QtdEnt)/(@QtdSldPraAnt+@QtdEnt)
                          end
                
                        Update PRXES
                           Set Prc_CusMedPra = @CusMedPraNew
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Produt = @CodPrd
                           And @CusMedPraNew > 0
                           And Prc_CusMedPra <> @CusMedPraNew
                
                        Update HSPRC
                           Set Vlr_CusMedPra = @CusMedPraNew,
                               Vlr_CusLiqPra = @CusLiqUni
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Produto = @CodPrd 
                           And Dat_Alteracao >= @DatMov
                           And @CusMedPraNew > 0
                           And ((Vlr_CusMedPra <> @CusMedPraNew) or (Vlr_CusLiqPra <> @CusLiqUni))
                      end

                    else              
                    -- custo medio 2
                      begin
                        Update PRXES
                           Set Prc_CusLiqEntDep = @CusLiqUni,
                               Dat_UltEntDep = @DatMov,
                               Qtd_UltEntDep = @QtdEnt
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Produt = @CodPrd
                        
                        Set @CusLiqDepNew = (@CusLiqDepAnt*@QtdSldDepAnt+@CusLiqUni*@QtdEnt)/(@QtdSldDepAnt+@QtdEnt)
                        Set @CusMedDepNew = (@CusMedDepAnt*@QtdSldDepAnt+@CusLiqUni*@QtdEnt)/(@QtdSldDepAnt+@QtdEnt)

                        Update PRXES
                           Set Prc_CusMedDep = @CusMedDepNew
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Produt = @CodPrd
                           And @CusMedDepNew > 0
                           And Prc_CusMedDep <> @CusMedDepNew
          
                        Update HSPRC
                           Set Vlr_CusMedDep = @CusMedDepNew,
                               Vlr_CusLiqDep = @CusLiqUni
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Produto = @CodPrd 
                           And Dat_Alteracao >= @DatMov
                           And @CusMedDepNew > 0
                           And ((Vlr_CusMedDep <> @CusMedDepNew) or (Vlr_CusLiqDep <> @CusLiqUni))
                      end

                    -- atualiza itens da nota   
                    Update it
                       Set it.Prc_CustoMedio = pr.Prc_CusMed
                      From NFEIT it 
                           Inner Join PRXES pr on it.Cod_Estabe = pr.Cod_Estabe and it.Cod_Produto = pr.Cod_Produt
                     Where it.Cod_Estabe = @PCodEstabe 
                       and it.Protocolo = @NumPrt
                       And it.Cod_Produto = @CodPrd

                    -- acumula p/ proxima entrada do dia
                    Set @QtdSldDiaAnt = @QtdSldDiaAnt + @QtdEnt 
                    if @CodCfoCab > 0
                      Set @QtdSldPraAnt = @QtdSldPraAnt + @QtdEnt
                    else
                      Set @QtdSldDepAnt = @QtdSldDepAnt + @QtdEnt   

                    Set @CusLiqPraAnt = @CusLiqPraNew
                    Set @CusLiqDepAnt = @CusLiqDepNew
                    Set @CusMedGerAnt = @CusMedGerNew
                    Set @CusMedComAnt = @CusMedComNew
                    Set @CusMedPraAnt = @CusMedPraNew
                    Set @CusMedDepAnt = @CusMedDepNew

                    Fetch Next From TABLE_Cr Into @CodCfoCab, @DatMov, @NumPrt, @CodCfoIte, 
                                                  @QtdEnt, @CusLiqUni, @CusLiqComUni, @PrcUniMed, @DscUniMed, @VlrBasCalSubTriUni

                  end  -- While (@DatMovAnt = @DatMov) and (@@FETCH_STATUS = 0)

              end -- While @@FETCH_STATUS = 0  
            Close TABLE_Cr
            Deallocate TABLE_Cr

          end  -- if @DatMov is not null
/*
        else
          begin
            Set @VlrPrcVenHis = null
            Select Top 1 @VlrPrcVenHis = Vlr_PrcVen
              From HSPRC
              Where Cod_Estabe = @PCodEstabe     
              And Cod_Produto = @CodPrd
              Order by Dat_Alteracao desc
            
            if IsNull(@VlrPrcVenHis,0) <> IsNull(@PrcVenPrd,0)
              begin
                PRINT '!!!!!!!!!!!!!!!!!!  D E L E T A R  !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!'
              end    
          end  
*/
        Fetch Next From HSPRC_Cr Into @CodPrd, @DatUltEntPra, @DatUltEntDep, @PrcVenPrd
      end
    
    Close HSPRC_Cr
    Deallocate HSPRC_Cr

    -- habilita triggers
    ALTER TABLE PRODU ENABLE TRIGGER ALL
    ALTER TABLE PRXES ENABLE TRIGGER ALL

    if @@trancount > 0
      COMMIT TRANSACTION
  END TRY
  BEGIN CATCH
    if @@trancount > 0
      ROLLBACK TRANSACTION
    -- habilita triggers
    ALTER TABLE PRODU ENABLE TRIGGER ALL
    ALTER TABLE PRXES ENABLE TRIGGER ALL
  END CATCH

END
GO


--========================= ATUALIZA DADOS ==============================================================
SET NOCOUNT ON

if Exists(Select 1
            From VBSLD
           Where Cod_Movime = 'Z'
             And Num_Protoc = -1)
  Update VBSLD
     Set Dat_Movime = Case When DAY(Dat_Movime) = 1 then Dat_Movime-1 Else Dat_Movime End, 
         Des_Movime = 'ZERA SALDO DO MÊS', 
	     Num_Protoc =  999999999
   Where Cod_Movime = 'Z'
     And Num_Protoc = -1
GO

if Exists(Select 1
            From VBFSL
           Where Cod_Movime = 'Z'
             And Num_Protoc = -1)
  Update VBFSL
     Set Dat_Movime = Case When DAY(Dat_Movime) = 1 then Dat_Movime-1 Else Dat_Movime End, 
         Des_Movime = 'ZERA SALDO DO MÊS', 
         Num_Protoc =  999999999
   Where Cod_Movime = 'Z'
     And Num_Protoc = -1
GO


Update TPOPE
  Set Flg_CalPisCof = 1
Where Cod_CfoNorInt > 0
  And ((Tip_OPe = 'V') or (Tip_Ope = 'C'))
  And IsNull(Flg_CalPisCof,0) = 0
GO

Update TPOPE
  Set Flg_CalRepIcmInt = 0
Where Flg_CalRepIcmInt is null
GO

Update PARAM
   Set FlgRegistraLogDivergencia = 0
 Where FlgRegistraLogDivergencia is null
GO

Insert into DPXPR(Cod_Estabe, Cod_Dep, Cod_Produt)
  Select distinct L.Cod_Estabe, L.Cod_Dep, L.Cod_Produt
    From PRLOT L
   Where not Exists(Select 1 From DPXPR dp
                      Where L.Cod_Estabe = dp.Cod_Estabe And L.Cod_Dep = dp.Cod_Dep and L.Cod_Produt = dp.Cod_Produt)
GO

Insert into DPXPR(Cod_Estabe, Cod_Dep, Cod_Produt)
  Select distinct i.Cod_Estabe, d.Cod_Dep, i.Cod_Produt
    From CPVIT i
         inner join CPVCB c on i.Cod_Estabe = c.Cod_Estabe and i.Num_PedCnf = c.Num_PedCnf and i.Num_VolCnf = c.Num_VolCnf
         outer apply (Select top 1 x.Cod_Dep 
                        From DPXPR x 
                       Where x.Cod_Estabe = i.Cod_Estabe and
                             x.Cod_Produt = i.Cod_Produt
                       Order by x.Cod_Dep) d 
   Where c.Sta_PedCnf = '0'
   And not Exists(Select 1 From DPXPR dp
                      Where i.Cod_Estabe = dp.Cod_Estabe and i.Cod_Produt = dp.Cod_Produt)
GO


