GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_Corrige_PDVITxCPVIT]
@CodEstabe int,
@CodPed int

AS

SET NOCOUNT ON

Begin Transaction

Declare @FlgErr bit,
        @pm_FlgCtlLotSai bit,
        @QtdIteCnf int,
        @QtdLotCnf int,
        @CodLotUni varchar(20),
        @FlgRecalcula  bit,
        @CodDep smallint
        
Set @CodDep = IsNull((Select min(Cod_Dep) From TBDEP),1)
Set @FlgErr = 0
Set @FlgRecalcula = 0
-- verifica flag para registrar lotes na conferencia
Select @pm_FlgCtlLotSai = FlgCtlLotSai From PARAM Where Cod_Estabe = @CodEstabe

-- total de itens na conferencia
Set @QtdIteCnf = (Select count (*) from CPVIT Where Cod_Estabe = @CodEstabe And Num_PedCnf = @CodPed)
-- total de lotes na conferencia
Set @QtdLotCnf = (Select count(distinct Cod_Lote) From CPVIT Where Cod_Estabe = @CodEstabe And Num_PedCnf = @CodPed)
if @QtdIteCnf = 1
  Set @CodLotUni = (Select Cod_Lote From CPVIT Where Cod_Estabe = @CodEstabe And Num_PedCnf = @CodPed)
else
  Set @CodLotUni = 'VARIOS'


-- seleciona produtos constantes no pedido com quantidades maiores que na conferencia
Declare @WCodPrdExc int,
        @WQtdExc int,
        @WQtdAcc int,
        @WCodLot varchar(20),
        @WQtdPed int,
        @WQtdBon int,
        @WQtdPedExc int,
        @WQtdBonExc int

Declare QUERY_Cr Cursor Local Fast_Forward For 
Select v.Cod_Produto, 
       sum(v.Qtd_Pedido+v.Qtd_Bonificacao) - 
       (Select sum(Qtd_Produt) From CPVIT Where Cod_Estabe = @CodEstabe And Num_PedCnf = @CodPed And Cod_Produt = v.Cod_Produto Group by Cod_Produt) 
  From PDVIT v 
Where v.Cod_Estabe = @CodEstabe 
And v.Cod_Pedido = @CodPed
group by v.Cod_Produto
having sum(v.Qtd_Pedido+v.Qtd_Bonificacao) >
       (Select sum(Qtd_Produt) From CPVIT Where Cod_Estabe = @CodEstabe And Num_PedCnf = @CodPed And Cod_Produt = v.Cod_Produto Group by Cod_Produt) 
Union
Select Cod_Produto, sum(Qtd_Pedido+Qtd_Bonificacao) 
  From PDVIT  
Where Cod_Estabe = @CodEstabe 
And Cod_Pedido = @CodPed
and (Qtd_Pedido+Qtd_Bonificacao) > 0
and Cod_Produto not in (Select distinct Cod_Produt From CPVIT Where Cod_Estabe = @CodEstabe And Num_PedCnf = @CodPed) 
group by Cod_Produto
Order by Cod_Produto

-- elimina excedentes      
Open QUERY_Cr
Fetch Next From QUERY_Cr Into @WCodPrdExc, @WQtdExc
While @@FETCH_STATUS = 0
  begin
    Set @WQtdAcc = 0
    -- seleciona itens dos pedidos por ordem de vencimento do lote
    Declare PDVIT_Cr Cursor Local Fast_Forward For 
    Select i.Cod_Lote, i.Qtd_Pedido, i.Qtd_Bonificacao
      From PDVIT i,  PRLOT l
    Where i.Cod_Estabe = l.Cod_Estabe 
    And l.Cod_Dep = @CodDep
    And i.Cod_Produto = l.Cod_Produt 
    And i.Cod_Lote = l.Cod_Lote
    And i.Cod_Estabe = @CodEstabe
    And i.Cod_Pedido = @CodPed
    And i.Cod_Produto = @WCodPrdExc
    order by l.dat_vencim

    Open PDVIT_Cr
    Fetch Next From PDVIT_Cr Into @WCodLot, @WQtdPed, @WQtdBon
    While (@@FETCH_STATUS = 0) and (@WQtdAcc < @WQtdExc)
      begin
        Set @WQtdPedExc = 0
        Set @WQtdBonExc = 0

        if @WQtdBon > 0
          if (@WQtdAcc+@WQtdBon) > @WQtdExc
            begin
              Set @WQtdBonExc = @WQtdExc
              Set @WQtdAcc = @WQtdAcc + @WQtdExc
            end
          else
            begin
              Set @WQtdBonExc = @WQtdBon
              Set @WQtdAcc = @WQtdAcc + @WQtdBon
            end

        if @WQtdPed > 0
          if (@WQtdAcc+@WQtdPed) > @WQtdExc
            begin
              Set @WQtdPedExc = @WQtdExc
              Set @WQtdAcc = @WQtdAcc + @WQtdExc
            end
          else
            begin
              Set @WQtdPedExc = @WQtdPed
              Set @WQtdAcc = @WQtdAcc + @WQtdPed
            end

        -- atualiza pedido
        if (@WQtdPedExc > 0) or (@WQtdBonExc > 0)              
          begin
            Set @FlgRecalcula = 1
            Update PDVIT
              Set Qtd_Pedido = Qtd_Pedido-@WQtdPedExc,
                  Qtd_Bonificacao = Qtd_Bonificacao-@WQtdBonExc
            Where Cod_Estabe = @CodEstabe 
            And Cod_Pedido = @CodPed
            And Cod_Produto = @WCodPrdExc
            And Cod_Lote = @WCodLot

            -- normaliza valores p/ impressao da NF
            Update PDVIT
              Set Qtd_ImpFat = (Qtd_Pedido+Qtd_Bonificacao)*1.0/Fat_CnvImpFat
            Where Cod_Estabe = @CodEstabe 
            And Cod_Pedido = @CodPed
            And Cod_Produto = @WCodPrdExc
            And Cod_Lote = @WCodLot
            if (@@error <> 0)
              begin
                Rollback Transaction
                Return
              end
          end            

        Fetch Next From PDVIT_Cr Into @WCodLot, @WQtdPed, @WQtdBon
      end
     
    Close PDVIT_Cr
    Deallocate PDVIT_Cr

    Fetch Next From QUERY_Cr Into @WCodPrdExc, @WQtdExc
  end

Close QUERY_Cr
Deallocate QUERY_Cr

if @FlgRecalcula = 1
  begin
    Exec PR_CalculaVencPDV @CodEstabe, @CodPed
    if @@error <> 0
      begin
        Rollback Transaction
        Return
      end

  end

-- faz as tranferencias de lotes se: existem mais de 1 lote ou existe somente 1 lote diferente de '*'
if (@FlgErr = 0) and (@pm_FlgCtlLotSai = 1) and ((@QtdLotCnf > 1) or ((@QtdLotCnf = 1) and (@CodLotUni <> '*')))
  begin
    -- coloca o pedido em modo de calculo  (nao solicita lotes dos itens)
    Update PDVCB
      Set Flg_Calc = 1
    Where Cod_Estabe = @CodEstabe 
    And Numero = @CodPed

    Update CPVCB
      Set Qtd_IteCnf = Qtd_IteCnf + 0
    Where Cod_Estabe = @CodEstabe 
    And Num_PedCnf = @CodPed

    -- variaveis para salvar valores iniciais do pedido para serem usados qdo incluir uma nova linha (lote)
    Declare @CODPRD int, 
            @CODLOT varchar(20), 
            @LOCFIS varchar(15), 
            @CODFAB int, 
            @PRCTAB numeric(18,4), 
            @PRCTABBRU numeric(18,4), 
            @PRCUNI numeric(18,8), 
            @PERDSC numeric(18,4), 
            @FLGPRCUNIDSC bit, 
            @PRZMAX int, 
            @DSCPRZ numeric(18,4), 
            @DSCVIS numeric(18,4), 
            @CODPRM int,
            @CODKITPRM int,
            @FATCNVIMPFAT int,
            @PRCMAXCON numeric(18,4), 
            @PRCFAB numeric(18,4), 
            @NUMSEQDIG int,
            @NOMUSUDBQ varchar(15),
            @DESUNVIMPFAT char(3),
            @DESAPRIMPFAT varchar(12),
            @IDPOLCOM int,
            @FLGVERBA bit,
            @PRCPOLCOM numeric(18,8), 
            @PERDSCPOLCOM numeric(18,4), 
            @PERDSCVISPOLCOM numeric(18,4), 
            @it_CodPrd int,  
            @it_CodLot varchar(20), 
            @it_LocFis varchar(15), 
            @it_CodFab int,  
            @WQtdAux int,
            @it_QtdPed int, 
            @it_QtdPra int, 
            @it_QtdDep int, 
            @it_QtdDif int, 
            @it_QtdDifPra int, 
            @it_QtdDifDep int, 
            @WSldLot int, 
            @WLotDis int, 
            @WLotDisPra int, 
            @WLotDisDep int, 
            @WLotAux varchar(20),
            @WLocEst varchar(1),
            @WDatVct smalldatetime,
            @it_PrcUni numeric(18,8), 
            @it_PerDsc numeric(18,4), 
            @it_FlgPrcUniDsc bit, 
            @it_PrzMax int, 
            @it_DscPrz numeric(18,4), 
            @it_DscVis numeric(18,4),
            @cf_CodPrd int, 
            @cf_CodLot varchar(20), 
            @cf_QtdCnf int,
            @to_CodCfoNorInt int

    -- ver cfop para prioridade de estoque
    Select @to_CodCfoNorInt = t.Cod_CfoNorInt
      From TPOPE t Inner Join PDVCB p on (t.Cod_Ope = p.Tip_Faturamento)
    Where p.Cod_Estabe = @CodEstabe 
    And p.Numero = @CodPed

    -- separa todos os produtos do pedido
    Declare PRODU_Cr Cursor Local Fast_Forward For 
      Select distinct Cod_Produto
        From PDVIT
      Where Cod_Estabe = @CodEstabe 
      And Cod_Pedido = @CodPed
      and (Qtd_Pedido+Qtd_Bonificacao) > 0
      Order by Cod_Produto

    Open PRODU_Cr

    Fetch Next From PRODU_Cr Into @CODPRD

    While @@FETCH_STATUS = 0
      begin
        -- guarda valores iniciais do produto
        Select top 1
            @LOCFIS = Loc_Fisica,
            @CODFAB = Cod_Fabricante,
            @PRCTAB = Prc_Tabela,
            @PRCTABBRU = Prc_TabBru,
            @PRCUNI = Prc_Unitario,
            @PERDSC = Per_Desconto,
            @FLGPRCUNIDSC = Flg_PrcUniDsc,
            @PRZMAX = Qtd_PrzMax,
            @DSCPRZ = Per_Descon,
            @DSCVIS = Per_DscVis,
            @CODPRM = Cod_Promocao,
			@CODKITPRM = Cod_KitPrm,
            @FATCNVIMPFAT = Fat_CnvImpFat,
            @PRCMAXCON = Prc_MaxCon,
            @PRCFAB = Prc_Fabric,
            @NUMSEQDIG = Num_SeqDig,
            @NOMUSUDBQ = Nom_UsuDesbloq,
            @DESUNVIMPFAT = Des_UnvImpFat,
            @DESAPRIMPFAT = Des_AprImpFat,
            @IDPOLCOM = Id_PolCom,
            @FLGVERBA = IsNull(Flg_Verba,0),
            @PRCPOLCOM = Prc_PolCom, 
            @PERDSCPOLCOM = Per_DscPolCom, 
            @PERDSCVISPOLCOM = Per_DscVisPolCom 
          From PDVIT
        Where Cod_Estabe = @CodEstabe 
        And Cod_Pedido = @CodPed
        and Cod_Produto = @CODPRD

        -- bloqueia PRODU
        Update PRXES
          Set Qtd_Fisico = Qtd_Fisico + 0
        Where Cod_Estabe = @CodEstabe 
        And Cod_Produt = @CODPRD
        if @@error <> 0
          begin
            Rollback Transaction
            Return
          end

        -- devolve itens do produto em PDVIT em desacordo com CPVIT
        Declare PDVIT_Cr Cursor Local Fast_Forward For 
          -- seleciona itens em PDVIT com mesmo lote e quantidades maiores que em CPVIT
          Select v.Cod_Lote, (v.Qtd_Pedido+v.Qtd_Bonificacao) as Qtd_Ped, v.Qtd_Pra, v.Qtd_Dep, c.Qtd_Produt
            From PDVIT v, CPVIT c
          Where v.Cod_Estabe = c.Cod_Estabe 
          and   v.Cod_Pedido = c.Num_PedCnf
          and   v.Cod_Produto = c.Cod_Produt
          and   v.Cod_Estabe = @CodEstabe
          and   v.Cod_Pedido = @CodPed
          and   v.Cod_Produto = @CODPRD
          and   v.Cod_Lote = c.Cod_Lote
          and   (v.Qtd_Pedido+v.Qtd_Bonificacao) > c.Qtd_Produt
          -- seleciona itens em PDVIT com lotes inexistentes em CPVIT
          Union
          Select distinct v.Cod_Lote, (v.Qtd_Pedido+v.Qtd_Bonificacao) as Qtd_Ped, v.Qtd_Pra, v.Qtd_Dep, 0
            From PDVIT v, CPVIT c
          Where v.Cod_Estabe = c.Cod_Estabe 
          and   v.Cod_Pedido = c.Num_PedCnf
          and   v.Cod_Produto = c.Cod_Produt
          and   v.Cod_Estabe = @CodEstabe
          and   v.Cod_Pedido = @CodPed
          and   v.Cod_Produto = @CODPRD
          and   v.Cod_Lote not in (Select distinct Cod_Lote From CPVIT Where Cod_Estabe = @CodEstabe And Num_PedCnf = @CodPed and Cod_Produt = @CODPRD)
          and   (v.Qtd_Pedido+v.Qtd_Bonificacao) > 0
          Order by v.Cod_Lote

        Open PDVIT_Cr
        Fetch Next From PDVIT_Cr Into @it_CodLot, @it_QtdPed, @it_QtdPra, @it_QtdDep, @cf_QtdCnf
        While @@FETCH_STATUS = 0
          begin
            if @it_QtdPra is null
              Set @it_QtdPra = 0
            if @it_QtdDep is null
              Set @it_QtdDep = 0
            if (@it_QtdPra+@it_QtdDep) <> @it_QtdPed
              begin
                Set @it_QtdPra = @it_QtdPed - @it_QtdDep
              end

            -- calcula o excesso em PDVIT
            Set @it_QtdDif = @cf_QtdCnf - @it_QtdPed  -- sempre negativo
            Set @it_QtdDifPra = 0
            Set @it_QtdDifDep = 0

            -- distribui deferenca entre estoques
            while ((@it_QtdDifPra+@it_QtdDifDep) <> @it_QtdDif) and ((@it_QtdPra+@it_QtdDep) > 0)
              begin
                if @to_CodCfoNorInt > 0
                  begin
                    if @it_QtdPra > 0
                      begin
                        Set @it_QtdDifPra = @it_QtdDifPra - 1
                        Set @it_QtdPra = @it_QtdPra - 1
                      end
                    else
                    if @it_QtdDep > 0
                      begin
                        Set @it_QtdDifDep = @it_QtdDifDep - 1
                        Set @it_QtdDep = @it_QtdDep - 1
                      end
                  end
                else
                  begin
                    if @it_QtdDep > 0
                      begin
                        Set @it_QtdDifDep = @it_QtdDifDep - 1
                        Set @it_QtdDep = @it_QtdDep - 1
                      end
                    else
                    if @it_QtdPra > 0
                      begin
                        Set @it_QtdDifPra = @it_QtdDifPra - 1
                        Set @it_QtdPra = @it_QtdPra - 1
                      end
                  end
              end

            -- assegura diferenca
            if (@it_QtdDifPra+@it_QtdDifDep) <> @it_QtdDif
              if @to_CodCfoNorInt > 0
                Set @it_QtdDifPra = @it_QtdDif - @it_QtdDifDep
              else
                Set @it_QtdDifDep = @it_QtdDif - @it_QtdDifPra

            if @cf_QtdCnf <> 0
              begin
                Update PDVIT
                  Set Qtd_Pedido = Qtd_Pedido + @it_QtdDif,
                      Qtd_Solicitado = Qtd_Solicitado + @it_QtdDif,
                      Qtd_Pra = Qtd_Pra + @it_QtdDifPra,
                      Qtd_Dep = Qtd_Dep + @it_QtdDifDep
                Where Cod_Estabe = @CodEstabe 
                And Cod_Pedido = @CodPed
                And Cod_Produto = @CODPRD
                And Cod_Lote = @it_CodLot

                -- normaliza valores p/ impressao da NF
                Update PDVIT
                  Set Qtd_ImpFat = (Qtd_Pedido+Qtd_Bonificacao)*1.0/Fat_CnvImpFat
                Where Cod_Estabe = @CodEstabe 
                And Cod_Pedido = @CodPed
                And Cod_Produto = @CODPRD
                And Cod_Lote = @it_CodLot
              end
            else
              begin
                Delete From PDVIT
                Where Cod_Estabe = @CodEstabe 
                And Cod_Pedido = @CodPed
                And Cod_Produto = @CODPRD
                And Cod_Lote = @it_CodLot
              end 

            -- atualiza PRLOT
            Update PRLOT
              Set Qtd_SolPra = Qtd_SolPra + @it_QtdDifPra
            Where Cod_Estabe = @CodEstabe 
            And Cod_Dep = @CodDep
            And Cod_Produt = @CODPRD and  Cod_Lote = @it_CodLot
            And @it_QtdDifPra <> 0

            Update PRLOT
              Set Qtd_SolDep = Qtd_SolDep + @it_QtdDifDep
            Where Cod_Estabe = @CodEstabe 
            And Cod_Dep = @CodDep
            And Cod_Produt = @CODPRD and  Cod_Lote = @it_CodLot
            And @it_QtdDifDep <> 0

            Fetch Next From PDVIT_Cr Into @it_CodLot, @it_QtdPed, @it_QtdPra, @it_QtdDep, @cf_QtdCnf
          end
        Close PDVIT_Cr
        Deallocate PDVIT_Cr

        -- insere itens de CPVIT em PDVIT
        -- selecionas intens da conferencia
        Declare CPVIT_Cr Cursor Local Fast_Forward For 
          -- seleciona itens com mesmo lote e quantidades conferida maior que pedido
          Select c.Cod_Lote, c.Qtd_Produt, (v.Qtd_Pedido+v.Qtd_Bonificacao) as Qtd_Ped
            From CPVIT c, PDVIT v
          Where c.Cod_Estabe = v.Cod_Estabe 
          And   c.Num_PedCnf = v.Cod_Pedido
          and   c.Cod_Produt = v.Cod_Produto
          and   c.Cod_Estabe = @CodEstabe
          and   c.Num_PedCnf = @CodPed
          and   c.Cod_Produt = @CODPRD
          and   c.Cod_Lote = v.Cod_Lote
          and   c.Qtd_Produt > (v.Qtd_Pedido+v.Qtd_Bonificacao)
          -- seleciona itens com lotes inexistentes em PDVIT
          Union
          Select distinct c.Cod_Lote, c.Qtd_Produt, 0 as Qtd_Ped
            From CPVIT c, PDVIT v
          Where c.Cod_Estabe = v.Cod_Estabe 
          And   c.Num_PedCnf = v.Cod_Pedido
          and   c.Cod_Produt = v.Cod_Produto
          and   c.Cod_Estabe = @CodEstabe
          and   c.Num_PedCnf = @CodPed
          and   c.Cod_Produt = @CODPRD
          and   c.Cod_Lote not in (Select distinct Cod_Lote From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed and Cod_Produto = @CODPRD)
          -- seleciona itens inexistentes em PDVIT
          Union
          Select c.Cod_Lote, c.Qtd_Produt, 0 as Qtd_Ped
            From CPVIT c
          Where c.Cod_Estabe = @CodEstabe 
          And c.Num_PedCnf = @CodPed
          and c.Cod_Produt = @CODPRD
          and c.Cod_Produt not in (Select distinct Cod_Produto From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed)
          Order by c.Cod_Lote

        Open CPVIT_Cr
        Fetch Next From CPVIT_Cr Into @cf_CodLot, @cf_QtdCnf, @it_QtdPed
        While @@FETCH_STATUS = 0
          begin
            -- calcula quantidade a incluir
            Set @it_QtdDif = @cf_QtdCnf - @it_QtdPed
            Set @it_QtdDifPra = 0
            Set @it_QtdDifDep = 0

            -- ATUALIZA PRLOT           
            Set @WSldLot = @it_QtdDif
            if not Exists(Select * From PRLOT Where Cod_Estabe = @CodEstabe And Cod_Dep = @CodDep And Cod_Produt = @CODPRD and Cod_Lote = @cf_CodLot)
              begin
                Insert into PRLOT (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Qtd_FisPra, Qtd_SolPra, Qtd_FisDep, Qtd_SolDep)
                           values (@CodEstabe, @CodDep, @CODPRD, @cf_CodLot, 0,0,0,0)
                if (@@error <> 0)
                  begin
                    Rollback Transaction
                    Return
                  end
              end
      
            -- atualiza lote se existe saldo
            if Exists(Select * From PRLOT Where Cod_Estabe = @CodEstabe And Cod_Dep = @CodDep And Cod_Produt = @CODPRD and  Cod_Lote = @cf_CodLot And Qtd_Saldo > 0)
              begin
                Select @WLotDis = Qtd_Saldo,
                       @WLotDisPra = Qtd_SldPra,
                       @WLotDisDep = Qtd_SldDep
                  From PRLOT 
                Where Cod_Estabe = @CodEstabe 
                And Cod_Dep = @CodDep
                And Cod_Produt = @CODPRD and Cod_Lote = @cf_CodLot 
                And Qtd_Saldo > 0

                if @WLotDis >=  @it_QtdDif
                  begin
                    Set @WSldLot = @WSldLot - @it_QtdDif
                  end
                else
                  begin
                    Set @WSldLot = @WSldLot - @WLotDis
                  end

                while ((@it_QtdDifPra+@it_QtdDifDep) <> @it_QtdDif) and ((@WLotDisPra+@WLotDisDep) > 0)
                  begin
                    if @to_CodCfoNorInt > 0
                      begin
                        if @WLotDisPra > 0
                          begin
                            Set @it_QtdDifPra = @it_QtdDifPra + 1
                            Set @WLotDisPra = @WLotDisPra - 1
                          end
                        else
                        if @WLotDisDep > 0
                          begin
                            Set @it_QtdDifDep = @it_QtdDifDep + 1
                            Set @WLotDisDep = @WLotDisDep - 1
                          end
                      end
                    else
                      begin
                        if @WLotDisDep > 0
                          begin
                            Set @it_QtdDifDep = @it_QtdDifDep + 1
                            Set @WLotDisDep = @WLotDisDep - 1
                          end
                        else
                        if @WLotDisPra > 0
                          begin
                            Set @it_QtdDifPra = @it_QtdDifPra + 1
                            Set @WLotDisPra = @WLotDisPra - 1
                          end
                      end
                  end

                Update PRLOT
                  Set Qtd_SolPra = Qtd_SolPra + @it_QtdDifPra
                Where Cod_Estabe = @CodEstabe 
                And Cod_Dep = @CodDep
                And Cod_Produt = @CODPRD and  Cod_Lote = @cf_CodLot
                And @it_QtdDifPra > 0

                Update PRLOT
                  Set Qtd_SolDep = Qtd_SolDep + @it_QtdDifDep
                Where Cod_Estabe = @CodEstabe 
                And Cod_Dep = @CodDep
                And Cod_Produt = @CODPRD and  Cod_Lote = @cf_CodLot
                And @it_QtdDifDep > 0
              end

            -- se o saldo ainda for insufuciente
            -- remanejar quantidade de outro lote do produto para atender a solicitacao
            if @WSldLot > 0
              begin
                if @to_CodCfoNorInt > 0
                  begin
                    Declare PRLOT_Cr Cursor Local Fast_Forward For 
                      Select '1' as CodLocEst, Dat_Vencim, Cod_Lote, Qtd_SldPra 
                        From PRLOT Where Cod_Estabe = @CodEstabe And Cod_Dep = @CodDep 
                      And Cod_Produt = @CODPRD and Cod_Lote <> @cf_CodLot
                      And Qtd_SldPra > 0
                      Union
                      Select '2' as CodLocEst, Dat_Vencim, Cod_Lote, Qtd_SldDep 
                        From PRLOT Where Cod_Estabe = @CodEstabe And Cod_Dep = @CodDep 
                      And Cod_Produt = @CODPRD and Cod_Lote <> @cf_CodLot
                      And Qtd_SldDep > 0
                      Order by CodLocEst, Dat_Vencim
                  end
                else
                  begin
                    Declare PRLOT_Cr Cursor Local Fast_Forward For 
                      Select '2' as CodLocEst, Dat_Vencim, Cod_Lote, Qtd_SldDep 
                        From PRLOT Where Cod_Estabe = @CodEstabe And Cod_Dep = @CodDep 
                      And Cod_Produt = @CODPRD and Cod_Lote <> @cf_CodLot
                      And Qtd_SldDep > 0
                      Union
                      Select '1' as CodLocEst, Dat_Vencim, Cod_Lote, Qtd_SldPra 
                        From PRLOT Where Cod_Estabe = @CodEstabe And Cod_Dep = @CodDep
                      And Cod_Produt = @CODPRD and Cod_Lote <> @cf_CodLot
                      And Qtd_SldPra > 0
                      Order by CodLocEst desc, Dat_Vencim 
                  end

                Open PRLOT_Cr
                Fetch Next From PRLOT_Cr Into @WLocEst, @WDatVct, @WLotAux, @WLotDis 
                While (@WSldLot > 0) and (@@FETCH_STATUS = 0)
                  begin
                    if @WLotDis >= @WSldLot
                      Set @WQtdAux = @WSldLot
                    else
                      Set @WQtdAux = @WLotDis

                    -- transfere quantidades entre lotes
                    if @WLocEst = '1'
                      begin
                        Set @it_QtdDifPra = @it_QtdDifPra + @WQtdAux

                        Update PRLOT
                          Set Qtd_FisPra = Qtd_FisPra - @WQtdAux
                        Where Cod_Estabe = @CodEstabe 
                        And Cod_Dep = @CodDep
                        And Cod_Produt = @CODPRD and Cod_Lote = @WLotAux

                        Update PRLOT
                          Set Qtd_FisPra = Qtd_FisPra + @WQtdAux
                        Where Cod_Estabe = @CodEstabe 
                        And Cod_Dep = @CodDep
                        And Cod_Produt = @CODPRD and  Cod_Lote = @cf_CodLot

                        Update PRLOT
                          Set Qtd_SolPra = Qtd_SolPra + @WQtdAux
                        Where Cod_Estabe = @CodEstabe 
                        And Cod_Dep = @CodDep
                        And Cod_Produt = @CODPRD and  Cod_Lote = @cf_CodLot
                      end
                    else
                      begin
                        Set @it_QtdDifDep = @it_QtdDifDep + @WQtdAux

                        Update PRLOT
                          Set Qtd_FisDep = Qtd_FisDep - @WQtdAux
                        Where Cod_Estabe = @CodEstabe 
                        And Cod_Dep = @CodDep
                        And Cod_Produt = @CODPRD and Cod_Lote = @WLotAux

                        Update PRLOT
                          Set Qtd_FisDep = Qtd_FisDep + @WQtdAux
                        Where Cod_Estabe = @CodEstabe 
                        And Cod_Dep = @CodDep
                        And Cod_Produt = @CODPRD and  Cod_Lote = @cf_CodLot

                        Update PRLOT
                          Set Qtd_SolDep = Qtd_SolDep + @WQtdAux
                        Where Cod_Estabe = @CodEstabe 
                        And Cod_Dep = @CodDep
                        And Cod_Produt = @CODPRD and  Cod_Lote = @cf_CodLot
                      end

                    Set @WSldLot = @WSldLot - @WQtdAux

                    Fetch Next From PRLOT_Cr Into @WLocEst, @WDatVct, @WLotAux, @WLotDis 
                  end
                Close PRLOT_Cr
                Deallocate PRLOT_Cr
              end  -- if @WSldLot > 0

            -- assegura diferenca
            if (@it_QtdDifPra+@it_QtdDifDep) <> @it_QtdDif
              if @to_CodCfoNorInt > 0
                Set @it_QtdDifPra = @it_QtdDif - @it_QtdDifDep
              else
                Set @it_QtdDifDep = @it_QtdDif - @it_QtdDifPra

            -- insere registro em PDVIT
            if (Select count(*) From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed and Cod_Produto = @CODPRD and Cod_Lote = @cf_CodLot) > 0
              begin
                Update PDVIT
                  Set Qtd_Pedido = Qtd_Pedido + @it_QtdDif,
                      Qtd_Solicitado = Qtd_Solicitado + @it_QtdDif,
                      Qtd_Pra = Qtd_Pra + @it_QtdDifPra,
                      Qtd_Dep = Qtd_Dep + @it_QtdDifDep
                Where Cod_Estabe = @CodEstabe 
                And Cod_Pedido = @CodPed 
                and Cod_Produto = @CODPRD and Cod_Lote = @cf_CodLot
              end
            else
              begin
                Insert into PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Qtd_Pedido, Qtd_Bonificacao, 
                                   Qtd_Pra, Qtd_Dep, Loc_Fisica, Cod_Fabricante, Cod_Promocao, Cod_KitPrm,
                                   Per_Desconto, Prc_Unitario, Qtd_PrzMax, Per_Descon, Per_DscVis,
                                   Qtd_Solicitado, Flg_PrcUniDsc, Prc_Tabela, Prc_TabBru, Prc_MaxCon, Prc_Fabric,
                                   Num_SeqDig, Nom_UsuDesbloq, Des_UnvImpFat, Des_AprImpFat,
                                   Id_PolCom, Flg_Verba, Prc_PolCom, Per_DscPolCom, Per_DscVisPolCom)
                           Values (@CodEstabe, @CodPed, @CODPRD, @cf_CodLot, @cf_QtdCnf, 0, 
                                   @it_QtdDifPra, @it_QtdDifDep, @LOCFIS, @CODFAB, @CodPrm, @CODKITPRM,
                                   @PERDSC, @PRCUNI, @PRZMAX, @DSCPRZ, @DSCVIS,
                                   @cf_QtdCnf, @FLGPRCUNIDSC, @PRCTAB, @PRCTABBRU, @PRCMAXCON, @PRCFAB,
                                   @NUMSEQDIG, @NOMUSUDBQ, @DESUNVIMPFAT, @DESAPRIMPFAT,
                                   @IDPOLCOM, @FLGVERBA, @PRCPOLCOM, @PERDSCPOLCOM, @PERDSCVISPOLCOM)
                if (@@error <> 0)
                  begin
                    Rollback Transaction
                    Return
                  end
              end

            -- normaliza valores p/ impressao da NF
            Update PDVIT
              Set Qtd_ImpFat = (Qtd_Pedido+Qtd_Bonificacao)*1.0/@FATCNVIMPFAT,
                  Fat_CnvImpFat = @FATCNVIMPFAT,
                  Prc_UniImpFat = Prc_Unitario * @FATCNVIMPFAT
              Where Cod_Estabe = @CodEstabe 
              And Cod_Pedido = @CodPed 
              and Cod_Produto = @CODPRD and Cod_Lote = @cf_CodLot

            Fetch Next From CPVIT_Cr Into @cf_CodLot, @cf_QtdCnf, @it_QtdPed
          end
        Close CPVIT_Cr
        Deallocate CPVIT_Cr

        Fetch Next From PRODU_Cr Into @CODPRD
      end

    Close PRODU_Cr
    Deallocate PRODU_Cr

    --  tira o pedido do modo de calculo
    Update PDVCB
      Set Flg_Calc = 0
    Where Cod_Estabe = @CodEstabe 
    And Numero = @CodPed
  end

Commit Transaction

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CorrigeLoteItemPDVLT]
@PCodEstabe int,
@PCodPed int,
@PNumVol int,
@PCodDep smallint,
@PCodPrd int,
@PCodLot varchar(20),
@PCodAltLot varchar(20),
@PCodMveEnt int,
@PCodMveSai int

AS

SET NOCOUNT ON
SET ANSI_WARNINGS OFF

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
             @Date smalldatetime
Set @Now = GetDate()
Set @Date = cast(GetDate() as date)

Declare @WQtdPed int,
        @WQtdPraAnt int,
        @WQtdDepAnt int,
        @WTipMveEnt varchar(1),
        @WTipMveSai varchar(1),
        @WQtdEmbFec int,
        @WCodZon smallint,
        @WCodDep smallint,
        @WNumRua smallint,
        @WNumCol smallint,
        @WNumNiv smallint,
        @WNumApt smallint,
        @WDatVct smalldatetime,
        @WDatFab smalldatetime

-- quantidade total do item
Select @WQtdPed = Isnull(Qtd_Lote,0),
       @WQtdPraAnt = Isnull(Qtd_LotePra,0),
       @WQtdDepAnt = Isnull(Qtd_LoteDep,0)
  From PDVLT 
Where Cod_Estabe = @PCodEstabe 
and Cod_Pedido = @PCodPed and Num_Vol = @PNumVol 
and Cod_Produt = @PCodPrd and Cod_Lote = @PCodLot 
if (@WQtdPraAnt+@WQtdDepAnt) <> @WQtdPed
  begin
    Set @WQtdPraAnt = @WQtdPed - @WQtdDepAnt
  end        

-- verifica codigos de movimentacao                 
Set @WTipMveEnt = (Select Tip_Movimento From TPMVE Where Codigo = @PCodMveEnt) 
Set @WTipMveSai = (Select Tip_Movimento From TPMVE Where Codigo = @PCodMveSai) 

-- verifica endereco de divergencias
Select @WCodDep = IsNull(z.Cod_Dep,0),
       @WCodZon = IsNull(z.Cod_Zon,0),
       @WNumRua = IsNull(z.Num_RuaIni,0) 
  From PMEST p
       Outer Apply (Select top 1 s.Cod_Dep, s.Cod_Zon, s.Num_RuaIni
	                  From TBZON s
                     Where s.Cod_Estabe = p.Cod_Estabe
                       And s.Cod_Zon = IsNull(p.CodZonDiv,0)
                       And dbo.FN_TipLocEnd(s.Cod_Estabe, s.Cod_Dep, s.Num_RuaIni) = 'X'
                     Order by s.Cod_Dep) z
 Where p.Cod_Estabe = @PCodEstabe 
 
Set @WNumCol = 0
Set @WNumNiv = 0
Set @WNumApt = 0

if (@WQtdPraAnt < 0) or (@WQtdDepAnt < 0)
  RAISERROR('Quantidades atribuídas inválidas',16,1)
else
if @WCodZon = 0
  RAISERROR('Zona para Divergências não configurada',16,1)
else
if @WNumRua = 0
  RAISERROR('Zona para Divergências invalida (produção)',16,1)
else
if (Select IsNull(Qtd_CxaFec,0) From PDVLT Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PCodPed And Num_Vol = @PNumVol And Cod_Produt = @PCodPrd And Cod_Lote = @PCodLot) > 0
  RAISERROR('Produto/Lote caixa fechada',16,1)
else
if Exists(Select * From PDVLT Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PCodPed and Num_Vol = @PNumVol and Cod_Produt = @PCodPrd and Cod_Lote = @PCodAltLot)
  RAISERROR('Lote já existe no pedido',16,1)
else
if  not Exists(Select Cod_Lote from PRLOT Where Cod_Estabe = @PCodEstabe And Cod_Dep = @PCodDep And Cod_Produt = @PCodPrd and Cod_Lote = @PCodLot)
  RAISERROR('Lote  substituído não existe',16,1)
else
if  not Exists(Select Cod_Lote from PRLOT Where Cod_Estabe = @PCodEstabe And Cod_Dep = @PCodDep And Cod_Produt = @PCodPrd and Cod_Lote = @PCodAltLot)
  RAISERROR('Lote  substituto não existe',16,1)
else
if ((Select Qtd_SolPra from PRLOT Where Cod_Estabe = @PCodEstabe And Cod_Dep = @PCodDep And Cod_Produt = @PCodPrd and Cod_Lote = @PCodLot) < @WQtdPraAnt) or
   ((Select Qtd_SolDep from PRLOT Where Cod_Estabe = @PCodEstabe And Cod_Dep = @PCodDep And Cod_Produt = @PCodPrd and Cod_Lote = @PCodLot) < @WQtdDepAnt) 
  RAISERROR('Quantidade solicitada do Lote substituído insuficiente',16,1)
else
if (Select IsNull(Qtd_Saldo,0) From PRLOT Where Cod_Estabe = @PCodEstabe And Cod_Dep = @PCodDep And Cod_Produt = @PCodPrd and Cod_Lote = @PCodAltLot) < (@WQtdPraAnt+@WQtdDepAnt)
  RAISERROR('Saldo do Lote  substituto insuficiente',16,1)
else
if @WTipMveEnt <> 'E'
  RAISERROR('Código de movimentação de entrada inválida',16,1)
else
if @WTipMveSai <> 'S'
  RAISERROR('Código de movimentação de saída inválida',16,1)
else
if (@PCodAltLot <> '') and (@PCodAltLot <> @PCodLot )
  begin
    Begin Transaction
      Declare @cb_FlgCal bit,
              @to_CodCfoNorInt int,
              @WMsg varchar(128),
              @WFlgErr bit,
              @WQtdTotSol int,
              @WAccQtdSol int,
              @WAccQtdPra int,
              @WAccQtdDep int,
              @WQtdMov int,
              @WQtdSldPra int,
              @WQtdSldDep int,

              @pl_CodDep smallint,
              @pl_NumRua smallint,
              @pl_NumCol smallint,
              @pl_NumNiv smallint,
              @pl_NumApt smallint,
              @pl_QtdLot integer,
              @pl_QtdLotPra integer,
              @pl_QtdLotDep integer,
              @pl_QtdCxaFec integer,
              @pl_QtdEmbFec integer

      Select @pl_CodDep = Cod_Dep,
             @pl_NumRua = Num_Rua,
             @pl_NumCol = Num_Col,
             @pl_NumNiv = Num_Niv,
             @pl_NumApt = Num_Apt,
             @pl_QtdLot = Qtd_Lote,
             @pl_QtdLotPra = Qtd_LotePra,
             @pl_QtdLotDep = Qtd_LoteDep,
             @pl_QtdCxaFec = Qtd_CxaFec,
             @pl_QtdEmbFec = Qtd_EmbFec
        From PDVLT
      Where Cod_Estabe = @PCodEstabe 
      And Cod_Pedido = @PCodPed
      And Num_Vol = @PNumVol
      And Cod_Produt = @PCodPrd
      And Cod_Lote = @PCodLot

      if @pl_QtdCxaFec = 0
        begin

          -- bloqueia os lotes dos produtos envolvidos na operacao
          Update PRLOT
            Set Qtd_Saldo = Qtd_Saldo + 0         
          Where Cod_Estabe = @PCodEstabe 
          And Cod_Dep = @PCodDep
          And Cod_Produt = @PCodPrd
          And Cod_Lote = @PCodAltLot
          And Qtd_Saldo >= (@WQtdPraAnt+@WQtdDepAnt)
          if @@rowcount = 0
            begin
              Rollback Transaction
              Return
            end

          -- guarda flag original
          Select @cb_FlgCal = IsNull(Flg_Calc,0) From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @PCodPed

          -- coloca campos de tabela na memoria
          Select @to_CodCfoNorInt = t.Cod_CfoNorInt
            From TPOPE t Inner Join PDVCB p on (t.Cod_Ope = p.Tip_Faturamento)
          Where p.Cod_Estabe = @PCodEstabe 
          And p.Numero = @PCodPed

          -- muda flag no cabecalho para nao disparar trigger em PDVIT
          Update PDVCB
            Set Flg_Calc = 1
          Where Cod_Estabe = @PCodEstabe 
          And Numero = @PCodPed
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end

          -- devolve o lote anterior
          Update PRLOT
            Set Qtd_SolPra = Qtd_SolPra - @WQtdPraAnt
          Where Cod_Estabe = @PCodEstabe 
          And Cod_Dep = @PCodDep
          And Cod_Produt = @PCodPrd 
          And  Cod_Lote = @PCodLot
          And @WQtdPraAnt > 0
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end

          Update PRLOT
            Set Qtd_SolDep = Qtd_SolDep -  @WQtdDepAnt
          Where Cod_Estabe = @PCodEstabe 
          And Cod_Dep = @PCodDep
          And Cod_Produt = @PCodPrd 
          And  Cod_Lote = @PCodLot
          And @WQtdDepAnt > 0
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end

          -- transfere o lote anterior para area de divergencias
          Set @WFlgErr = 0
          Set @WMsg = ''

          -- se nao existir o lote, cria
          if not Exists(Select * From PRLTL 
                        Where Cod_Estabe = @PCodEstabe 
                        and Cod_Produt = @PCodPrd and Cod_Lote = @PCodLot 
                        and Cod_Dep = @WCodDep and Num_Rua = @WNumRua 
                        and Num_Col = @WNumCol and Num_Niv = @WNumNiv 
                        and Num_Apt = @WNumApt)
            begin
              Set @WDatVct = null
              Set @WDatFab = null
              Set @WQtdEmbFec = 1

              -- pega o vencimento do lote
              Select @WDatVct = Dat_Vencim, 
                     @WDatFab = Dat_Fabric 
                From PRLOT 
              Where Cod_Estabe = @PCodEstabe 
              And Cod_Dep = @PCodDep
              And Cod_Produt = @PCodPrd 
              and Cod_Lote = @PCodLot

              if @WDatVct is null
                Set @WDatVct = (Select top 1 Dat_Vencim From PRLTL Where Cod_Estabe = @PCodEstabe And Cod_Produt = @PCodPrd and Cod_Lote = @PCodLot And Cod_Dep = @WCodDep)
              if @WDatFab is null
                Set @WDatFab = (Select top 1 Dat_Fabric From PRLTL Where Cod_Estabe = @PCodEstabe And Cod_Produt = @PCodPrd and Cod_Lote = @PCodLot And Cod_Dep = @WCodDep)

              Insert into PRLTL (Cod_Estabe, Cod_Produt, Cod_Lote, Qtd_EmbFec, Dat_Vencim, Dat_Fabric, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Dat_Entrada, Qtd_FisPra, Qtd_SolPra,Qtd_FisDep,Qtd_SolDep)
                         Values (@PCodEstabe, @PCodPrd, @PCodLot, @WQtdEmbFec, @WDatVct, @WDatFab, @WCodDep, @WNumRua, @WNumCol, @WNumNiv, @WNumApt, @Date, 0, 0, 0, 0)
              if @@error <> 0
                begin
                  Rollback Transaction
                  Return
                end
            end

          -- tira de PRLOT
          Update PRLOT
            Set Qtd_FisPra = Qtd_FisPra - @WQtdPraAnt
          Where Cod_Estabe = @PCodEstabe 
          And Cod_Dep = @PCodDep
          And Cod_Produt = @PCodPrd 
          and  Cod_Lote = @PCodLot
          And @WQtdPraAnt > 0
          And Qtd_SldPra >= @WQtdPraAnt
          And @WFlgErr = 0
          if (@@rowcount = 0) and (@WQtdPraAnt > 0) and (@WFlgErr = 0)
            begin
              Set @WFlgErr = 1
              Set @WMsg = 'Estoque insuficiente no Picking a transferir p/ zona de divergências'
            end

          Update PRLOT
            Set Qtd_FisDep = Qtd_FisDep - @WQtdDepAnt
          Where Cod_Estabe = @PCodEstabe 
          And Cod_Dep = @PCodDep
          And Cod_Produt = @PCodPrd 
          and Cod_Lote = @PCodLot
          And @WQtdDepAnt > 0
          And Qtd_SldDep >= @WQtdDepAnt
          And @WFlgErr = 0
          if (@@rowcount = 0) and (@WQtdDepAnt > 0) and (@WFlgErr = 0)
            begin
              Set @WFlgErr = 1
              Set @WMsg = 'Estoque insuficiente no Picking a transferir p/ zona de divergências'
            end

          -- transfere para zona de cancelados
          Update PRLTL
            Set Qtd_FisPra = Qtd_FisPra +  @WQtdPraAnt
          Where Cod_Estabe = @PCodEstabe 
          And Cod_Produt = @PCodPrd and Cod_Lote = @PCodLot
          And Cod_Dep = @WCodDep
          And Num_Rua = @WNumRua 
          And Num_Col = @WNumCol
          And Num_Niv = @WNumNiv
          And Num_Apt = @WNumApt
          And @WQtdPraAnt > 0
          And @WFlgErr = 0
          if (@@rowcount = 0) and (@WQtdPraAnt > 0) and (@WFlgErr = 0)
            begin
              Set @WFlgErr = 1
              Set @WMsg = 'Erro na transferencia p/ zona de divergências (endereço inexistente)'
            end
          Update PRLTL
            Set Qtd_FisDep = Qtd_FisDep +  @WQtdDepAnt
          Where Cod_Estabe = @PCodEstabe 
          And Cod_Produt = @PCodPrd and Cod_Lote = @PCodLot
          And Cod_Dep = @WCodDep
          And Num_Rua = @WNumRua 
          And Num_Col = @WNumCol
          And Num_Niv = @WNumNiv
          And Num_Apt = @WNumApt
          And @WQtdDepAnt > 0
          And @WFlgErr = 0
          if (@@rowcount = 0) and (@WQtdDepAnt > 0) and (@WFlgErr = 0)
            begin
              Set @WFlgErr = 1
              Set @WMsg = 'Erro na transferencia p/ zona de divergências (endereço inexistente)'
            end

          if @WFlgErr = 1
            begin
              if @WMsg <> ''
                RAISERROR(@WMsg,16,1)
              Rollback Transaction
              Return
            end

          -- solicita novo lote
          Select @WQtdSldPra = IsNull(Qtd_SldPra,0),
                 @WQtdSldDep = IsNull(Qtd_SldDep,0)
            From PRLOT
          Where Cod_Estabe = @PCodEstabe 
          And Cod_Dep = @PCodDep
          And Cod_Produt = @PCodPrd
          And Cod_Lote = @PCodAltLot

          Set @WQtdTotSol = @WQtdPraAnt+@WQtdDepAnt
          Set @WAccQtdSol = 0
          Set @WAccQtdPra = 0
          Set @WAccQtdDep = 0
          if @to_CodCfoNorInt > 0
            begin
              -- solicita o que for possivel do lote
              if @WQtdSldPra > 0
                begin
                  if @WQtdSldPra > @WQtdTotSol
                    Set @WQtdMov = @WQtdTotSol
                  else
                    Set @WQtdMov = @WQtdSldPra
                  Set @WAccQtdPra = @WAccQtdPra + @WQtdMov
                  Set @WAccQtdSol = @WAccQtdSol + @WQtdMov
                  Update PRLOT
                    Set Qtd_SolPra = Qtd_SolPra + @WQtdMov
                  Where Cod_Estabe = @PCodEstabe 
                  And Cod_Dep = @PCodDep
                  And Cod_Produt = @PCodPrd
                  And Cod_Lote = @PCodAltLot
                  if @@error <> 0
                    begin
                      Rollback Transaction
                      Return
                    end
                end
              -- ver se precisa solicitar outro lote
              if @WAccQtdSol < @WQtdTotSol
                if @WQtdSldDep > 0
                  begin
                    if @WQtdSldDep > (@WQtdTotSol-@WAccQtdSol) 
                      Set @WQtdMov = @WQtdTotSol-@WAccQtdSol
                    else
                      Set @WQtdMov = @WQtdSldDep
                    Set @WAccQtdDep = @WAccQtdDep + @WQtdMov
                    Set @WAccQtdSol = @WAccQtdSol + @WQtdMov
                  Update PRLOT
                    Set Qtd_SolDep = Qtd_SolDep + @WQtdMov
                  Where Cod_Estabe = @PCodEstabe 
                  And Cod_Dep = @PCodDep
                  And Cod_Produt = @PCodPrd
                  And Cod_Lote = @PCodAltLot
                  if @@error <> 0
                    begin
                      Rollback Transaction
                      Return
                    end
                  end
            end
          else
            begin
              -- solicita o que for possivel do lote
              if @WQtdSldDep > 0
                begin
                  if @WQtdSldDep > @WQtdTotSol
                    Set @WQtdMov = @WQtdTotSol
                  else
                    Set @WQtdMov = @WQtdSldDep
                  Set @WAccQtdDep = @WAccQtdDep + @WQtdMov
                  Set @WAccQtdSol = @WAccQtdSol + @WQtdMov
                Update PRLOT
                  Set Qtd_SolDep = Qtd_SolDep + @WQtdMov
                Where Cod_Estabe = @PCodEstabe 
                And Cod_Dep = @PCodDep
                And Cod_Produt = @PCodPrd
                And Cod_Lote = @PCodAltLot
                if @@error <> 0
                  begin
                    Rollback Transaction
                    Return
                  end
                end
              -- ver se precisa solicitar outro lote
              if @WAccQtdSol < @WQtdTotSol
                if @WQtdSldPra > 0
                  begin
                    if @WQtdSldPra > (@WQtdTotSol-@WAccQtdSol) 
                      Set @WQtdMov = @WQtdTotSol-@WAccQtdSol
                    else
                      Set @WQtdMov = @WQtdSldPra
                    Set @WAccQtdPra = @WAccQtdPra + @WQtdMov
                    Set @WAccQtdSol = @WAccQtdSol + @WQtdMov
                    Update PRLOT
                      Set Qtd_SolPra = Qtd_SolPra + @WQtdMov
                    Where Cod_Estabe = @PCodEstabe 
                    And Cod_Dep = @PCodDep
                    And Cod_Produt = @PCodPrd
                    And Cod_Lote = @PCodAltLot
                    if @@error <> 0
                      begin
                        Rollback Transaction
                        Return
                      end
                  end
            end

          if @WAccQtdSol <> @WQtdTotSol
            begin
              Rollback Transaction
              Return
            end
            
          -- corrige o lote
          Update PDVLT
            Set Cod_Lote = @PCodAltLot,
                Qtd_LotePra = @WAccQtdPra,
                Qtd_LoteDep = @WAccQtdDep
          Where Cod_Estabe = @PCodEstabe     
          And Cod_Pedido = @PCodPed and Num_Vol = @PNumVol 
          and Cod_Produt = @PCodPrd and Cod_Lote = @PCodLot 
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end

         -- retorna flag anterior
         Update PDVCB
           Set Flg_Calc = @cb_FlgCal
         Where Cod_Estabe = @PCodEstabe 
         And Numero = @PCodPed 
         if @@error <> 0
            begin
              Rollback Transaction
              Return
            end
          
        end

    Commit Transaction
  end

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CancelaECF]
@PCodEstab int,
@PSerNot varchar(3),
@PNumNot int,
@PNomUsu varchar(15),
@PCodDep smallint,
@PCodCli int,
@PCodVdr int

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = cast(GetDate() as date)

Declare @WMsg varchar(128),
        @WDatVct smalldatetime,
        @WDatFab smalldatetime

if @PCodDep = 0 
  Set @PCodDep = (Select top 1 lt.Cod_Dep
                    From PRLOT lt
                         inner join NFSIT it on it.Cod_Estabe = lt.Cod_Estabe and 
                                                it.Cod_Produto = lt.Cod_Produt and 
                                                it.Cod_Lote = lt.Cod_Lote
                   Where it.Cod_Estabe = @PCodEstab
                     And it.Ser_Nota = @PSerNot
                     And it.Num_Nota = @PNumNot)

if not Exists(Select Codigo from TPMVE Where Codigo = 15)
  begin
    Set @WMsg = 'O código para o Tipo de Movimento "15-Entrada por Cancelamento de NF" não foi '+
                'cadastrado em Tipos de Movimentação de Estoque'
    RAISERROR(@WMsg,16,1)
  end
else
  begin
    Begin Transaction
      Declare @it_CodPrd int,
              @it_CodLot varchar(20),
              @it_QtdPrd int,
              @it_QtdBon int,
              @it_QtdPra int,
              @it_QtdDep int,

              @WDatCan smalldatetime,
              @WCodAcr int,
              @WDesHst varchar(40),
              @WFlgPdvOk bit,
              @WQtdPra int ,
              @WQtdDep int

      Update NFSCB
         Set Status = 'C',
             Dat_Cancelamento = @Date,
             Usuario = @PNomUsu,
             Transacao = GetDate()
       Where Cod_Estabe = @PCodEstab 
         and Ser_Nota = @PSerNot 
         and Num_Nota = @PNumNot
      
      Set @WDatCan = @Date
      Set @WDesHst = 'CANCELAMENTO CUPOM - '+@PSerNot+' '+Cast(@PNumNot as varchar)
      
      Declare NFSIT_Cr Cursor Local Fast_Forward For 

        Select it.Cod_Produto, it.Cod_Lote, it.Qtd_Produto, it.Qtd_Bonificacao, IsNull(it.Qtd_Pra,0), IsNull(it.Qtd_Dep,0)
          From NFSIT it 
               Inner Join NFSCB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Ser_Nota = cb.Ser_Nota and it.Num_Nota = cb.Num_Nota
         Where cb.Cod_Estabe = @PCodEstab 
           And cb.Ser_Nota = @PSerNot 
           And cb.Num_Nota = @PNumNot 
           And cb.Flg_MovEst = 1
      
      Open NFSIT_Cr
      Fetch Next From NFSIT_Cr Into @it_CodPrd, @it_CodLot, @it_QtdPrd, @it_QtdBon, @it_QtdPra, @it_QtdDep
      While (@@FETCH_STATUS = 0)
        begin
          if (@it_QtdPra+@it_QtdDep) <> (@it_QtdPrd+@it_QtdBon)
            Set @it_QtdPra = @it_QtdPrd + @it_QtdBon - @it_QtdDep
      
          Set @WDatVct = null
          Set @WDatFab = null
      
          -- pega o vencimento do lote
          Select @WDatVct = Dat_Vencim,
                 @WDatFab = Dat_Fabric
            From PRLOT 
           Where Cod_Estabe = @PCodEstab 
             And Cod_Dep = @PCodDep
             And Cod_Produt = @it_CodPrd 
             and Cod_Lote = @it_CodLot
      
          if @WDatVct is null
            Set @WDatVct = (Select top 1 Dat_Vencim From PRLTL Where Cod_Estabe = @PCodEstab And Cod_Produt = @it_CodPrd and Cod_Lote = @it_CodLot And Cod_Dep = @PCodDep)
          if @WDatFab is null
            Set @WDatFab = (Select top 1 Dat_Fabric From PRLTL Where Cod_Estabe = @PCodEstab And Cod_Produt = @it_CodPrd and Cod_Lote = @it_CodLot And Cod_Dep = @PCodDep)
      
          -- gera um acerto. o saldo é atualizado pela trigger
          Exec PR_ProxNumero 'Acerto', @WCodAcr output
          if @@error <> 0
            begin
              if @@trancount > 0
                Rollback Transaction
              Return
            end
          Insert into ACERT (Cod_Estabe, Numero, Cod_Dep, Dat_Movimento, Cod_Produto, Cod_Lote, Dat_Vencimento, Dat_Fabric,
                             Qtd_Acerto, Qtd_AceDep, Cod_TipMov, Cod_OriMov, Historico, Usuario, Transacao)
                     Values (@PCodEstab, @WCodAcr, @PCodDep, @WDatCan, @it_CodPrd, @it_CodLot, @WDatVct, @WDatFab,
                             @it_QtdPra, @it_QtdDep, 15, 'NF', @WDesHst, @PNomUsu, GetDate())
          if @@error <> 0
            begin
              if @@trancount > 0
                Rollback Transaction
              Return
            end
      
          Fetch Next From NFSIT_Cr
            Into @it_CodPrd, @it_CodLot, @it_QtdPrd, @it_QtdBon, @it_QtdPra, @it_QtdDep
        end
      Close NFSIT_Cr
      Deallocate NFSIT_Cr
      
      -- atualiza estatisticas da nota
      Exec PR_AtualizaEstatisticasNFS @PCodEstab, @PSerNot, @PNumNot, 'C'
      if @@error <> 0
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end
       
    if @@trancount > 0
      Commit Transaction
  end

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_SolicitaLoteProduto]
@PCodEstabe int,
@PCodPed int,
@PFlgLotEsp bit,
@PCodPrd int,
@PCodLot varchar(20),
@PTipSai varchar(1),
@PCodPrm int,
@PCodKitPrm int,
@PQtdPed int,
@PQtdBon int,
@PFatCnvImpFat int,
@PFlgLotNaoFra bit

AS

SET NOCOUNT ON

Set DateFormat ymd

Begin Transaction

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now = GetDate()
Set @Date = Cast(Cast(Year(@Now) as varchar)+'-'+Cast(Month(@Now) as varchar)+'-'+Cast(Day(@Now) as varchar)+' 00:00:00' as smalldatetime)

if @PQtdPed is null 
  Set @PQtdPed = 0
if @PQtdBon is null 
  Set @PQtdBon = 0
if IsNull(@PFatCnvImpFat,0) = 0
  Set @PFatCnvImpFat = 1
  
-- corrige saldos negativos
if Exists(Select Cod_Produt
          From PRLOT 
          Where Cod_Estabe = @PCodEstabe
          And Cod_Produt = @PCodPrd
          And ((Qtd_SolPra < 0) or (Qtd_SolDep < 0)))
  begin
    Update PRLOT
      Set Qtd_SolPra = 0
    Where Cod_Estabe = @PCodEstabe
    And Cod_Produt = @PCodPrd
    And Qtd_SolPra < 0
    
    Update PRLOT
      Set Qtd_SolDep = 0
    Where Cod_Estabe = @PCodEstabe
    And Cod_Produt = @PCodPrd
    And Qtd_SolDep < 0
  end

if Exists(Select Cod_Produt
          From PRLOT 
          Where Cod_Estabe = @PCodEstabe
          And Cod_Produt = @PCodPrd
          And ((Qtd_Saldo < 0) or (Qtd_Fisico < 0) or (Qtd_SldPra < 0) or (Qtd_FisPra < 0) or (Qtd_SldDep < 0) or (Qtd_FisDep < 0)))
  begin
    Update PRLOT
      Set Qtd_FisPra = Qtd_FisPra + Abs(Qtd_SldPra)
    Where Cod_Estabe = @PCodEstabe
    And Cod_Produt = @PCodPrd
    And Qtd_SldPra < 0
    
    Update PRLOT
      Set Qtd_FisDep = Qtd_FisDep + Abs(Qtd_SldDep)
    Where Cod_Estabe = @PCodEstabe
    And Cod_Produt = @PCodPrd
    And Qtd_SldDep < 0
  end
  
-- garante bloqueio do registro
Update PRXES
  Set Qtd_Solici = 0
Where Cod_Estabe = @PCodEstabe 
And Cod_Produt = @PCodPrd
And Qtd_Solici < 0

Update PRXES
  Set Qtd_PrmSolici = 0
Where Cod_Estabe = @PCodEstabe 
And Cod_Produt = @PCodPrd
And Qtd_PrmSolici < 0
  
Update PRXES
  Set Qtd_Solici = Qtd_Solici + 0
Where Cod_Estabe = @PCodEstabe
And Cod_Produt = @PCodPrd

Declare @CodDep smallint,
        @QtdPedAju int,
        @QtdBonAju int,
        @FatBon numeric(18,4),
        @PedSol int,
        @BonSol int,
        @LotAux varchar(20),
        @LotAlt varchar(20),
        @CodLotEsp varchar(20),  -- lote especifico
        @lt_LocEst varchar(1),
        @lt_DatVct smalldatetime,
        @lt_CodLot varchar(20),
        @lt_SldLot int,
        @AccQtdAte int,
        @AccBonAte int,
        @QtdDsp int,
		@QtdLotDsp int,
        @QtdDspPrd int,
        @QtdDspLot int,
        @QtdDspPrm int,
        @QtdEmbFec int,
        @FlgPrdForLin bit,
        @PerQtp numeric(18,4),
        @PerQtpAcu numeric(18,4),
        @pm_FlgPerCmpEst bit,
        @to_CodCfoNorInt int,
		@cl_CodCliPag int,
		@cl_QtdMesMinPrzVctLot int,
        @CodMtvRej varchar(3),
        @QtdSolPrdIni int,
        @WAccQtdTot int,
        @WQtdPra int,
        @WQtdDep int
        
-- sem WMS: deposito unico
Set @CodDep = IsNull((Select min(Cod_Dep) 
                        From TBDEP 
                       Where Cod_Estabe = @PCodEstabe),1)

-- coloca campos de tabela na memoria
Select @pm_FlgPerCmpEst = Isnull(FlgPerCmpEst,0)
From PARAM
Where Cod_Estabe = @PCodEstabe
  
Select @to_CodCfoNorInt = t.Cod_CfoNorInt
From TPOPE t 
     Inner Join PDVCB p on (t.Cod_Ope = p.Tip_Faturamento)
Where p.Cod_Estabe = @PCodEstabe
And p.Numero = @PCodPed

Select @cl_CodClipag = IsNull(cl.Cod_CliPag,0),
       @cl_QtdMesMinPrzVctLot = IsNull(Qtd_MesMinPrzVctLot,0)
From PDVCB cb
     Left Outer Join CLIEN cl on (cb.Cod_Cliente = cl.Codigo)
Where cb.Cod_Estabe = @PCodEstabe
And cb.Numero = @PCodPed

-- variaveis para salvar valores iniciais do pedido para serem usados qdo incluir uma nova linha (lote)
Declare @it_LocFis varchar(15), 
        @it_CodFab int, 
        @it_PerDsc numeric(18,4), 
        @it_PrcUni numeric(18,8), 
        @it_PrcTab numeric(18,4), 
        @it_PrcTabBru numeric(18,4), 
        @it_FlgPrcUniDsc bit, 
        @it_PrzMax int, 
        @it_DscPrz numeric(18,4), 
        @it_DscVis numeric(18,4),
        @it_QtdSol int,
        @it_PrcMaxCon numeric(18,4), 
        @it_PrcFab numeric(18,4), 
        @it_NumSeqDig int,
        @it_NomUsuDbq varchar(15),
        @it_DesUnvImpFat char(3),
        @it_DesAprImpFat varchar(12),
        @it_IdPolCom int,
        @it_FlgVerba bit, 
        @it_PrcPolCom numeric(18,8), 
        @it_PerDscPolCom numeric(18,4), 
        @it_PerDscVisPolCom numeric(18,4),
        @it_QtdPrzPolCom int,
        @it_FlgPolPrm bit,
        @it_PrcUniLiqPer numeric(18,4),
        @it_PrcLiqUltEnt numeric(18,4),
        @it_PrcRefFpb numeric(18,4),
        @it_PrcUniPde numeric(18,4), 
        @it_PerDscPde numeric(18,4), 
        @it_CodPrjPde varchar(12),
        @it_NumSeqPdc varchar(6),
        @it_PerVrbPar numeric(18,4), 
        @it_PerVrbBon numeric(18,4), 
        @it_VlrBonificacao numeric(18,4),
        @it_VlrDscBonRat numeric(18,4),
        @it_PrcCusMinComMarkup numeric(18,4),
        @it_VlrBasVerba numeric(18,4),
        @IdPolLot int   -- politica com lote especifico

        
Select @it_LocFis = it.Loc_Fisica,
       @it_CodFab = it.Cod_Fabricante,
       @it_QtdSol = IsNull(it.Qtd_Solicitado,0),
       @it_PerDsc = it.Per_Desconto,
       @it_PrcUni = it.Prc_Unitario,
       @it_PrcTab = it.Prc_Tabela,
       @it_PrcTabBru = it.Prc_TabBru,
       @it_FlgPrcUniDsc = it.Flg_PrcUniDsc,
       @it_PrzMax = it.Qtd_PrzMax,
       @it_DscPrz = it.Per_Descon,
       @it_DscVis = it.Per_DscVis,
       @it_PrcMaxCon = it.Prc_MaxCon,
       @it_PrcFab = it.Prc_Fabric,
       @it_NumSeqDig = it.Num_SeqDig,
       @it_NomUsuDbq = it.Nom_UsuDesbloq,
       @it_DesUnvImpFat = it.Des_UnvImpFat,
       @it_DesAprImpFat = it.Des_AprImpFat,
       @it_IdPolCom = it.Id_PolCom,
       @IdPolLot = Case
                     When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = it.Cod_Estabe and pl.Id_PolCom = it.Id_PolCom and pl.Cod_Produt = it.Cod_Produto) then it.Id_PolCom
                     Else 0
                   End,
       @it_FlgVerba = IsNull(it.Flg_Verba,0), 
       @it_PrcPolCom = it.Prc_PolCom, 
       @it_PerDscPolCom = it.Per_DscPolCom, 
       @it_PerDscVisPolCom = it.Per_DscVisPolCom,
       @it_QtdPrzPolCom = it.Qtd_PrzPolCom,
       @it_FlgPolPrm = ISNULL(it.Flg_PolPrm,0),
       @it_PrcUniLiqPer = it.Prc_UniLiqPer,
       @it_PrcLiqUltEnt = it.Prc_LiqUltEnt,
       @it_PrcRefFpb = it.Prc_RefFpb,
       @it_CodPrjPde = it.Cod_PrjPde,
       @it_PerDscPde = it.Per_DscPde,
       @it_PrcUniPde = it.Prc_UniPde,
       @it_NumSeqPdc = it.Num_SeqPdc,
       @it_PerVrbPar = IsNull(it.Per_VrbPar,0), 
       @it_PerVrbBon = IsNull(it.Per_VrbBon,0), 
       @it_VlrBonificacao = ISNULL(it.Vlr_Bonificacao,0),
       @it_VlrDscBonRat = ISNULL(it.Vlr_DscBonRat,0),
       @it_PrcCusMinComMarkup = ISNULL(it.Prc_CusMinComMarkup,0),
       @it_VlrBasVerba = ISNULL(it.Vlr_BasVerba,0)
From PDVIT it
Where it.Cod_Estabe = @PCodEstabe 
And it.Cod_Pedido = @PCodPed 
And it.Cod_Produto = @PCodPrd 
And it.Cod_Lote = @PCodLot
And it.Tip_Sai = @PTipSai

if @it_QtdSol = 0
  Set @it_QtdSol = @PQtdPed + @PQtdBon

-- exclui o regitro de origem
Delete From PDVIT
Where Cod_Estabe = @PCodEstabe 
And Cod_Pedido = @PCodPed 
And Cod_Produto = @PCodPrd 
And Cod_Lote = @PCodLot
And Tip_Sai = @PTipSai

Set @AccQtdAte = 0
Set @AccBonAte = 0

Set @QtdDspLot = (Select sum(IsNull(Qtd_Saldo,0)) From PRLOT Where Cod_Estabe = @PCodEstabe And Qtd_Saldo > 0 And Cod_Produt = @PCodPrd)

Select @FlgPrdForLin = Case 
                         When Flag_ImprClassif1 = 'N' then 1 
                         Else 0 
                       End, 
       @QtdEmbFec = IsNull(Qtd_Embalagem,1)
From PRODU 
Where Codigo = @PCodPrd

if @QtdEmbFec = 0
  Set @QtdEmbFec = 1

Select @QtdDspPrd = dbo.FN_EstoqueDisponivelPrd(Cod_Estabe,Cod_Produt),
       @QtdSolPrdIni = ISNULL(Qtd_Solici,0),
       @QtdDspPrm = IsNull(Qtd_PrmDispon,0)
From PRXES 
Where Cod_Estabe = @PCodEstabe 
And Cod_Produt = @PCodPrd

if IsNull(@QtdDspLot,0) < IsNull(@QtdDspPrd,0)
  Set @QtdDsp = IsNull(@QtdDspLot,0)
else
  Set @QtdDsp = IsNull(@QtdDspPrd,0)
  
-- verifica estoque disponivel para promocao
if (@PCodPrm > 0) and 
   (Charindex((Select Substring(Cod_OrigemPdv,1,1) From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @PCodPed),';M;T;W;') > 0) 
  if IsNull((Select Flg_BlqCtrQtdPrm From PRMCB Where Codigo = @PCodPrm),0) = 0
    begin
      if @QtdDspPrm < 0 
        Set @QtdDspPrm = 0 
      if @QtdDspPrm < @QtdDsp
        Set @QtdDsp = @QtdDspPrm
    end
  
Set @lt_CodLot = '*'  
Set @CodMtvRej = ''

Set @QtdLotDsp = dbo.FN_QtdLoteDisponivel (@PCodEstabe, @cl_CodCliPag, @PCodPrd, @Date, @cl_QtdMesMinPrzVctLot, @IdPolLot)

-- verifica se existe lote para atendimento
if (@QtdDsp > 0) and (@QtdLotDsp = 0)
  begin
    Set @QtdDsp = 0
    Set @CodMtvRej = 'LT-'
  end

if @QtdLotDsp < @QtdDsp 
  Set @QtdDsp = @QtdLotDsp

if @QtdDsp > 0
  begin
    -- acumulador total de solicitacoes do produto
    Set @WAccQtdTot = 0

    if @PQtdPed+@PQtdBon > 0 
      Set @PerQtp = @PQtdPed*100/(@PQtdPed+@PQtdBon)
    else
      Set @PerQtp = 0

    -- ajusta quantidades conforme estoque disponivel
    Set @QtdPedAju = @PQtdPed
    Set @QtdBonAju = @PQtdBon
    if @QtdDsp < (@PQtdPed+@PQtdBon)
      begin
        if @PQtdBon > 0
          begin
            Set @FatBon = @PQtdBon*1.0/@PQtdPed*1.0
            Set @QtdBonAju = @FatBon*@QtdDsp/(1+@FatBon+0.05)
            Set @QtdPedAju = @QtdBonAju/@FatBon
          end
        else
          Set @QtdPedAju = @QtdDsp
      end

    -- inclui novo(s) registro(s) conforme disponibilidade dos lotes
    -- solicita lote especifico ou pelo vencimento
	if @PFlgLotEsp = 1
	  Set @CodLotEsp = @PCodLot
	else
	  Set @CodLotEsp = ''

    -- solicita lote por vencimento
    if @to_CodCfoNorInt > 0
      begin
        -- venda FAT
		if @pm_FlgPerCmpEst = 0  
          begin
            Declare PRLOT_Cr Cursor Local Fast_Forward For
              Select '1' as CodLocEst, lt.Dat_Vencim, lt.Cod_Lote, 
                     SldLot = Case 
                                When @PFlgLotNaoFra = 1 Then lt.Qtd_SldPra/@QtdEmbFec*@QtdEmbFec
                                Else lt.Qtd_SldPra 
                              End  
              From PRLOT lt Inner Join
                   PRODU pr on pr.Codigo = lt.Cod_Produt Left Outer Join
                   CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                   CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
              Where lt.Cod_Estabe = @PCodEstabe
              And lt.Cod_Dep = @CodDep
              And lt.Cod_Produt = @PCodPrd 
              And ( ((@PFlgLotEsp = 1) and (lt.Cod_Lote  = @CodLotEsp)) or 
                    ((@PFlgLotEsp = 0) and (lt.Cod_Lote <> @CodLotEsp)) )
              And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                          (lt.Dat_Vencim >= Case
                                                              When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                              When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                              Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                            End))) or
                    ((@IdPolLot > 0) and 
                     Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
              And lt.Qtd_Saldo > 0 
              And lt.Qtd_SldPra > 0
              Order by CodLocEst, lt.Dat_Vencim
          end
        else
          begin
            -- compartilha estoque
            Declare PRLOT_Cr Cursor Local Fast_Forward For 
              Select lt.CodLocEst, lt.Dat_Vencim, lt.Cod_Lote, lt.SldLot
              From ( Select '1' as CodLocEst, l1.Cod_Estabe, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote,
                            SldLot = Case 
                                       When @PFlgLotNaoFra = 1 Then l1.Qtd_SldPra/@QtdEmbFec*@QtdEmbFec
                                       Else l1.Qtd_SldPra 
                                     End  
                     From PRLOT l1 
                     Where l1.Cod_Estabe = @PCodEstabe
                     And l1.Cod_Dep = @CodDep
                     And l1.Cod_Produt = @PCodPrd 
                     And l1.Qtd_Saldo > 0 
                     And l1.Qtd_SldPra > 0
                     Union
                     Select '2' as CodLocEst, l2.Cod_Estabe, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                            SldLot = Case 
                                       When @PFlgLotNaoFra = 1 Then l2.Qtd_SldDep/@QtdEmbFec*@QtdEmbFec
                                      Else l2.Qtd_SldDep 
                                     End  
                     From PRLOT l2 
                     Where l2.Cod_Estabe = @PCodEstabe
                     And l2.Cod_Dep = @CodDep
                     And l2.Cod_Produt = @PCodPrd 
                     And l2.Qtd_Saldo > 0 
                     And l2.Qtd_SldDep > 0 ) lt Inner Join
                   PRODU pr on pr.Codigo = lt.Cod_Produt Left Outer Join
                   CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                   CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
              Where 1 = 1
              And ( ((@PFlgLotEsp = 1) and (lt.Cod_Lote  = @CodLotEsp)) or 
                    ((@PFlgLotEsp = 0) and (lt.Cod_Lote <> @CodLotEsp)) )
              And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                          (lt.Dat_Vencim >= Case
                                                              When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                              When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                              Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                            End))) or
                    ((@IdPolLot > 0) and 
                     Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
              Order by lt.CodLocEst, lt.Dat_Vencim
          end
      end
    else
      begin
        -- venda ORC
        if @pm_FlgPerCmpEst = 0
          begin
            Declare PRLOT_Cr Cursor Local Fast_Forward For
              Select '2' as CodLocEst, lt.Dat_Vencim, lt.Cod_Lote,
                     SldLot = Case 
                                When @PFlgLotNaoFra = 1 Then Qtd_SldDep/@QtdEmbFec*@QtdEmbFec
                                Else lt.Qtd_SldDep 
                              End  
              From PRLOT lt Inner Join
                   PRODU pr on pr.Codigo = lt.Cod_Produt Left Outer Join
                   CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                   CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
              Where lt.Cod_Estabe = @PCodEstabe
              And lt.Cod_Dep = @CodDep
              And lt.Cod_Produt = @PCodPrd 
              And ( ((@PFlgLotEsp = 1) and (lt.Cod_Lote  = @CodLotEsp)) or 
                    ((@PFlgLotEsp = 0) and (lt.Cod_Lote <> @CodLotEsp)) )
              And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                          (lt.Dat_Vencim >= Case
                                                              When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                              When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                              Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                            End))) or
                    ((@IdPolLot > 0) and 
                     Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
              And lt.Qtd_Saldo > 0 
              And lt.Qtd_SldDep > 0
              Order by CodLocEst, lt.Dat_Vencim
          end
        else
          begin
            -- compartilha estoque
            Declare PRLOT_Cr Cursor Local Fast_Forward For
              Select lt.CodLocEst, lt.Dat_Vencim, lt.Cod_Lote, lt.SldLot
              From ( Select '2' as CodLocEst, l2.Cod_Estabe, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote,
                            SldLot = Case 
                                       When @PFlgLotNaoFra = 1 Then l2.Qtd_SldDep/@QtdEmbFec*@QtdEmbFec
                                       Else l2.Qtd_SldDep 
                                     End  
                     From PRLOT l2
                     Where l2.Cod_Estabe = @PCodEstabe
                     And l2.Cod_Dep = @CodDep
                     And l2.Cod_Produt = @PCodPrd 
                     And l2.Qtd_Saldo > 0 
                     And l2.Qtd_SldDep > 0
                     Union
                     Select '1' as CodLocEst, l1.Cod_Estabe, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote,
                            SldLot = Case 
                                       When @PFlgLotNaoFra = 1 Then l1.Qtd_SldPra/@QtdEmbFec*@QtdEmbFec
                                       Else l1.Qtd_SldPra 
                                     End  
                     From PRLOT l1 
                     Where l1.Cod_Estabe = @PCodEstabe
                     And l1.Cod_Dep = @CodDep
                     And l1.Cod_Produt = @PCodPrd 
                     And l1.Qtd_Saldo > 0 
                     And l1.Qtd_SldPra > 0 ) lt Inner Join
                   PRODU pr on pr.Codigo = lt.Cod_Produt Left Outer Join
                   CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                   CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
              Where 1 = 1
              And ( ((@PFlgLotEsp = 1) and (lt.Cod_Lote  = @CodLotEsp)) or 
                    ((@PFlgLotEsp = 0) and (lt.Cod_Lote <> @CodLotEsp)) )
              And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                          (lt.Dat_Vencim >= Case
                                                              When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                              When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                              Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                            End))) or
                    ((@IdPolLot > 0) and 
                     Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
              Order by lt.CodLocEst desc, lt.Dat_Vencim
          end
      end

    Open PRLOT_Cr
    Fetch Next From PRLOT_Cr Into @lt_LocEst, @lt_DatVct, @lt_CodLot, @lt_SldLot 

    While (@AccQtdAte+@AccBonAte < @QtdPedAju+@QtdBonAju) and (@@FETCH_STATUS = 0)
      begin
        Set @PedSol = @QtdPedAju - @AccQtdAte
        Set @BonSol = @QtdBonAju - @AccBonAte

        -- se o saldo do lote nao atender a qtd.solicitada refazer a solicitacao proporcionalmente
        if @PedSol+@BonSol > @lt_SldLot
          begin
            Set @PedSol = Round(@lt_SldLot*@PerQtp/100,0)
            Set @BonSol = @lt_SldLot-@PedSol
          end

        -- garante as quantidades solicitadas
        if (@PedSol = 0) or ((@AccQtdAte+@PedSol) > @QtdPedAju) or ((@AccBonAte+@BonSol) > @QtdBonAju)
          Break

        -- Atualiza saldo do lote
        Set @WQtdPra = 0
        Set @WQtdDep = 0
        
        if @lt_LocEst = '1'
          begin
            Update PRLOT
              Set Qtd_SolPra = Qtd_SolPra + @PedSol + @BonSol
            Where Cod_Estabe = @PCodEstabe
            And Cod_Dep = @CodDep
            And Cod_Produt = @PCodPrd
            And Cod_Lote = @lt_CodLot
            Set @WQtdPra = @PedSol + @BonSol
            Set @WAccQtdTot = @WAccQtdTot + @WQtdPra
          end
        else
          begin
            Update PRLOT
              Set Qtd_SolDep = Qtd_SolDep + @PedSol + @BonSol
            Where Cod_Estabe = @PCodEstabe
            And Cod_Dep = @CodDep
            And Cod_Produt = @PCodPrd
            And Cod_Lote = @lt_CodLot
            Set @WQtdDep = @PedSol + @BonSol
            Set @WAccQtdTot = @WAccQtdTot + @WQtdDep
          end
       
        -- incrementa saldo solicitado em PRXES
        Update PRXES 
          Set Qtd_Solici = Qtd_Solici + @PedSol + @BonSol
        Where Cod_Estabe = @PCodEstabe
        And Cod_Produt = @PCodPrd
      
        Update PRXES
          Set Qtd_PrmSolici = Qtd_PrmSolici + @PedSol + @BonSol
        Where Cod_Estabe = @PCodEstabe
        And Cod_Produt = @PCodPrd 
        And IsNull(@PCodPrm,0) > 0


        Set @AccQtdAte = @AccQtdAte + @PedSol
        Set @AccBonAte = @AccBonAte + @BonSol

        -- atualiza qtd atendida e o lote ativo
        if Exists(Select Cod_Produto From PDVIT 
                  Where Cod_Estabe = @PCodEstabe
                  And Cod_Pedido = @PCodPed 
                  and Cod_Produto = @PCodPrd 
                  and Cod_Lote = @lt_CodLot
                  and Tip_Sai = @PTipSai)
          begin
            Update PDVIT
              Set Qtd_Pedido = Qtd_Pedido + @PedSol,
                  Qtd_Bonificacao = Qtd_Bonificacao + @BonSol,
                  Qtd_Solicitado = Qtd_Solicitado + @PedSol + @BonSol,
                  Qtd_Pra = Qtd_Pra + @WQtdPra,
                  Qtd_Dep = Qtd_Dep + @WQtdDep   
            Where Cod_Estabe = @PCodEstabe
            and Cod_Pedido = @PCodPed 
            and Cod_Produto = @PCodPrd 
            and Cod_Lote = @lt_CodLot
            and Tip_Sai = @PTipSai
          end
        else
          begin
            Insert into PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai, Qtd_Pedido, Qtd_Bonificacao, Loc_Fisica, Cod_Fabricante, 
                               Cod_Promocao, Cod_KitPrm, Per_Desconto, Prc_Unitario, Qtd_PrzMax, Per_Descon, Per_DscVis, 
                               Qtd_Solicitado, Flg_PrcUniDsc, Prc_Tabela, Prc_TabBru, Qtd_Pra, Qtd_Dep, Prc_MaxCon, Prc_Fabric,
                               Num_SeqDig, Nom_UsuDesbloq, Des_UnvImpFat, Des_AprImpFat, 
                               Id_PolCom, Flg_Verba, Prc_PolCom, Per_DscPolCom, Per_DscVisPolCom,
                               Qtd_PrzPolCom, Flg_PolPrm, Prc_UniLiqPer, Prc_LiqUltEnt, Prc_RefFpb,
                               Cod_PrjPde, Prc_UniPde, Per_DscPde, Num_SeqPdc, Per_VrbPar, Per_VrbBon,
                               Vlr_Bonificacao, Vlr_DscBonRat, Prc_CusMinComMarkup, Vlr_BasVerba)
                       
                       Values (@PCodEstabe, @PCodPed, @PCodPrd, @lt_CodLot, @PTipSai, @PedSol, @BonSol, @it_LocFis, @it_CodFab, 
                               @PCodPrm, @PCodKitPrm, @it_PerDsc, @it_PrcUni, @it_PrzMax, @it_DscPrz, @it_DscVis, 
                               @PedSol+@BonSol, @it_FlgPrcUniDsc, @it_PrcTab, @it_PrcTabBru, @WQtdPra, @WQtdDep, @it_PrcMaxCon, @it_PrcFab,
                               @it_NumSeqDig, @it_NomUsuDbq, @it_DesUnvImpFat, @it_DesAprImpFat, 
                               @it_IdPolCom, @it_FlgVerba, @it_PrcPolCom, @it_PerDscPolCom, @it_PerDscVisPolCom,
                               @it_QtdPrzPolCom, @it_FlgPolPrm, @it_PrcUniLiqPer, @it_PrcLiqUltEnt, @it_PrcRefFpb,
                               @it_CodPrjPde, @it_PrcUniPde, @it_PerDscPde, @it_NumSeqPdc, @it_PerVrbPar, @it_PerVrbBon,
                               @it_VlrBonificacao, @it_VlrDscBonRat, @it_PrcCusMinComMarkup, @it_VlrBasVerba)
          if @@error <> 0
              begin
                Rollback Transaction
                Return
              end
          end

        -- decrementa quantidade solicitada inicial
        Set @it_QtdSol = @it_QtdSol - @PedSol - @BonSol
        Set @LotAlt = @lt_CodLot

        -- normaliza valores
        Update PDVIT
          Set Qtd_ImpFat = (Qtd_Pedido+Qtd_Bonificacao)*1.0/@PFatCnvImpFat,
              Fat_CnvImpFat = @PFatCnvImpFat,
              Prc_UniImpFat = Prc_Unitario * @PFatCnvImpFat
        Where Cod_Estabe = @PCodEstabe
        and Cod_Pedido = @PCodPed 
        And Cod_Produto = @PCodPrd 
        And Cod_Lote = @lt_CodLot
        And Tip_Sai = @PTipSai

        -- calcula tributos      
        EXEC PR_CalcTributPdvit @PCodEstabe, @PCodPed, @PCodPrd, @lt_CodLot, @PTipSai
        if @@error <> 0
          begin
            Rollback Transaction
            Return
          end

        Fetch Next From PRLOT_Cr Into @lt_LocEst, @lt_DatVct, @lt_CodLot, @lt_SldLot 
      end
    Close PRLOT_Cr
    Deallocate PRLOT_Cr

    -- verifica bonificacao
    if @PQtdBon > 0
      begin
        if @AccQtdAte + @AccBonAte > 0 
          Set @PerQtpAcu = @AccQtdAte*100/(@AccQtdAte+@AccBonAte)
        else
          Set @PerQtpAcu = 0
        if Round(@PerQtpAcu*100,0) <> Round(@PerQtp*100,0)
          begin
            Set @AccQtdAte = 0
            Set @AccBonAte = 0
--            Rollback Transaction A 
            Rollback Transaction 
            Return
          end
      end

/*    
    -- incrementa saldo solicitado
    Update PRXES 
      Set Qtd_Solici = Qtd_Solici + @AccQtdAte + @AccBonAte
    Where Cod_Estabe = @PCodEstabe
    And Cod_Produt = @PCodPrd
      
    Update PRXES
      Set Qtd_PrmSolici = Qtd_PrmSolici + @AccQtdAte + @AccBonAte
    Where Cod_Estabe = @PCodEstabe
    And Cod_Produt = @PCodPrd 
    And IsNull(@PCodPrm,0) > 0
*/
  end

-- registra faltas
if @AccQtdAte+@AccBonAte < @PQtdPed+@PQtdBon
  begin
    Set @LotAux = '*'
    Set @LotAux = @lt_CodLot
        
    if @CodMtvRej = ''
      if @QtdDsp > 0
        Set @CodMtvRej = 'ES-'   -- estoque insuficiente
      else
      if @FlgPrdForLin = 1
        Set @CodMtvRej = 'PR-'   -- produto descontinuado
      else
        Set @CodMtvRej = 'ES0'   -- estoque zero
    
    if Exists(Select Cod_Produto From PDVIT Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @PCodPed and Cod_Produto = @PCodPrd and Cod_Lote = @LotAux and Tip_Sai = @PTipSai)
      begin
        Update PDVIT
          Set Qtd_Solicitado = Qtd_Solicitado + @PQtdPed + @PQtdBon - @AccQtdAte - @AccBonAte,
              Cod_MtvRej = @CodMtvRej
        Where Cod_Estabe = @PCodEstabe
        and Cod_Pedido = @PCodPed 
        and Cod_Produto = @PCodPrd 
        and Cod_Lote = @LotAux
        and Tip_Sai = @PTipSai
      end
    else
      begin
        Insert into PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai, Qtd_Pedido, Qtd_Bonificacao, Loc_Fisica, Cod_Fabricante, 
                           Cod_Promocao, Cod_KitPrm, Per_Desconto, Prc_Unitario, Qtd_PrzMax, Per_Descon, Per_DscVis, 
                           Qtd_Solicitado, Flg_PrcUniDsc, Prc_Tabela, Prc_TabBru, Qtd_Pra, Qtd_Dep,
                           Prc_MaxCon, Prc_Fabric, Num_SeqDig, Nom_UsuDesbloq, Des_UnvImpFat, Des_AprImpFat,
                           Id_PolCom, Flg_Verba, Prc_PolCom, Per_DscPolCom, Per_DscVisPolCom, Cod_MtvRej,
                           Qtd_PrzPolCom, Flg_PolPrm, Prc_UniLiqPer, Prc_LiqUltEnt, Prc_RefFpb,
                           Cod_PrjPde, Prc_UniPde, Per_DscPde, Num_SeqPdc, Per_VrbPar, Per_VrbBon,
                           Vlr_Bonificacao, Vlr_DscBonRat, Prc_CusMinComMarkup, Vlr_BasVerba)
                           
                   Values (@PCodEstabe, @PCodPed, @PCodPrd, @LotAux, @PTipSai, 0, 0, @it_LocFis, @it_CodFab, 
                           @PCodPrm, @PCodKitPrm, @it_PerDsc, @it_PrcUni, @it_PrzMax, @it_DscPrz, @it_DscVis, 
                           @PQtdPed+@PQtdBon-@AccQtdAte-@AccBonAte, @it_FlgPrcUniDsc, @it_PrcTab, @it_PrcTabBru, 0, 0,
                           @it_PrcMaxCon, @it_PrcFab, @it_NumSeqDig, @it_NomUsuDbq, @it_DesUnvImpFat, @it_DesAprImpFat,
                           @it_IdPolCom, @it_FlgVerba, @it_PrcPolCom, @it_PerDscPolCom, @it_PerDscVisPolCom, @CodMtvRej,
                           @it_QtdPrzPolCom, @it_FlgPolPrm, @it_PrcUniLiqPer, @it_PrcLiqUltEnt, @it_PrcRefFpb,
                           @it_CodPrjPde, @it_PrcUniPde, @it_PerDscPde, @it_NumSeqPdc, @it_PerVrbPar, @it_PerVrbBon,
                           @it_VlrBonificacao, @it_VlrDscBonRat, @it_PrcCusMinComMarkup, @it_VlrBasVerba)
                           
        if @@error <> 0
          begin
            Rollback Transaction
            Return
          end
      end

    -- decrementa quantidade solicitada inicial
    Set @it_QtdSol = @it_QtdSol - @PQtdPed - @PQtdBon + @AccQtdAte + @AccBonAte
    Set @LotAlt = @LotAux

    -- normaliza valores
    Update PDVIT
      Set Qtd_ImpFat = (Qtd_Pedido+Qtd_Bonificacao)*1.0/@PFatCnvImpFat,
          Fat_CnvImpFat = @PFatCnvImpFat,
          Prc_UniImpFat = Prc_Unitario * @PFatCnvImpFat
    Where Cod_Estabe = @PCodEstabe
    And Cod_Pedido = @PCodPed 
    And Cod_Produto = @PCodPrd 
    And Cod_Lote = @LotAux
    And Tip_Sai = @PTipSai

    -- calcula tributos      
    EXEC PR_CalcTributPdvit @PCodEstabe, @PCodPed, @PCodPrd, @LotAux, Tip_Sai
    if @@error <> 0
      begin
        Rollback Transaction
        Return
      end

  end

-- ajusta quantidade solicitada
if @it_QtdSol < 0
  Set @it_QtdSol = 0
if @it_QtdSol > 0 
  begin
    Update PDVIT
      Set Qtd_Solicitado = Qtd_Solicitado + @it_QtdSol
    Where Cod_Estabe = @PCodEstabe
    and Cod_Pedido = @PCodPed 
    And Cod_Produto = @PCodPrd 
    And Cod_Lote = @LotAlt
    And Tip_Sai = @PTipSai
  end

if (@QtdSolPrdIni + @WAccQtdTot) <>
   IsNull((Select IsNull(Qtd_Solici,0) From PRXES Where Cod_Estabe = @PCodEstabe And Cod_Produt = @PCodPrd),0) 
  begin
    RAISERROR('Erro na solicitação do Produto',16,1)
    Rollback Transaction
  end  
else
  Commit Transaction

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_SolicitaLoteProdutoECF]
@CodEstabe int,
@FlgLotEsp bit,
@CodPrd int,
@CodLot varchar(20),
@CodPrm int,
@QtdPrd int

AS

SET NOCOUNT ON

Begin Transaction

-- garante bloqueio do registro
Update PRXES
  Set Qtd_Solici = Qtd_Solici + 0
Where Cod_Estabe = @CodEstabe 
And Cod_Produt = @CodPrd
if @@error <> 0
  begin
    Rollback Transaction
    Return
  end

Declare @CodDep smallint,
        @QtdPedAju int,
        @PedSol int,
        @DatVct smalldatetime,
        @LotAux varchar(20),
        @LocEst varchar(1),
        @SldLot int,
        @QtdAteAcu int,
        @QtdDspPrd int,
        @QtdDspLot int,
        @QtdDsp int,
        @PerQtp numeric(18,4),
        @pm_FlgPerCmpEst bit

-- sem WMS: deposito unico
Set @CodDep = IsNull((Select min(Cod_Dep) 
                        From TBDEP 
                       Where Cod_Estabe = @CodEstabe),1)

-- coloca campos de tabela na memoria
Select @pm_FlgPerCmpEst = Isnull(FlgPerCmpEst,0)
  From PARAM
Where Cod_Estabe = @CodEstabe

Set @QtdAteAcu = 0
Set @QtdDspPrd = (Select dbo.FN_EstoqueDisponivelPrd(Cod_Estabe,Cod_Produt) From PRXES Where Cod_Estabe = @CodEstabe And Cod_Produt = @CodPrd)
Set @QtdDspLot = (Select sum(IsNull(Qtd_Saldo,0)) From PRLOT Where Cod_Estabe = @CodEstabe And Qtd_Saldo > 0 And Cod_Produt = @CodPrd)

if IsNull(@QtdDspLot,0) < IsNull(@QtdDspPrd,0)
  Set @QtdDsp = IsNull(@QtdDspLot,0)
else
  Set @QtdDsp = IsNull(@QtdDspPrd,0)

if @QtdDsp > 0
  begin
    if @QtdPrd > 0 
      Set @PerQtp = @QtdPrd*100/@QtdPrd
    else
      Set @PerQtp = 0

    -- ajusta quantidades conforme estoque disponivel
    Set @QtdPedAju = @QtdPrd
    if @QtdDsp < @QtdPrd
      Set @QtdPedAju = @QtdDsp

    -- solicita lote especifico ou pelo vencimento
    if @FlgLotEsp = 0
      begin
        -- solicita lote por vencimento
        if @pm_FlgPerCmpEst = 0  
          begin
            -- nao compartilha estoque
            Declare PRLOT_Cr Cursor Local Fast_Forward For 
              Select '1' as CodLocEst, Dat_Vencim, Cod_Lote, Qtd_SldPra 
                From PRLOT 
              Where Cod_Estabe = @CodEstabe 
              And Cod_Dep = @CodDep
              And Cod_Produt = @CodPrd 
              And Qtd_Saldo > 0 
              And Qtd_SldPra > 0
              Order by CodLocEst, Dat_Vencim
          end
        else
          begin
            -- compartilha estoque
            Declare PRLOT_Cr Cursor Local Fast_Forward For 
              Select '1' as CodLocEst, Dat_Vencim, Cod_Lote, Qtd_SldPra 
                From PRLOT 
              Where Cod_Estabe = @CodEstabe 
              And Cod_Dep = @CodDep
              And Cod_Produt = @CodPrd 
              And Qtd_Saldo > 0 
              And Qtd_SldPra > 0
              Union All
              Select '2' as CodLocEst, Dat_Vencim, Cod_Lote, Qtd_SldDep 
                From PRLOT 
              Where Cod_Estabe = @CodEstabe 
              And Cod_Dep = @CodDep
              And Cod_Produt = @CodPrd 
              And Qtd_Saldo > 0 
              And Qtd_SldDep > 0
              Order by CodLocEst, Dat_Vencim
          end
      end
    else
      begin
        -- solicita lote especifico
        if @pm_FlgPerCmpEst = 0
          begin
            Declare PRLOT_Cr Cursor Local Fast_Forward For 
              Select '1' as CodLocEst, Dat_Vencim, Cod_Lote, Qtd_SldPra 
                From PRLOT 
              Where Cod_Estabe = @CodEstabe 
              And Cod_Dep = @CodDep
              And Cod_Produt = @CodPrd 
              And Cod_Lote = @CodLot 
              And Qtd_Saldo > 0 
              And Qtd_SldPra > 0
              Order by CodLocEst, Dat_Vencim
          end
        else
          begin
            Declare PRLOT_Cr Cursor Local Fast_Forward For 
              Select '1' as CodLocEst, Dat_Vencim, Cod_Lote, Qtd_SldPra 
                From PRLOT 
              Where Cod_Estabe = @CodEstabe 
              And Cod_Dep = @CodDep
              And Cod_Produt = @CodPrd 
              And Cod_Lote = @CodLot 
              And Qtd_Saldo > 0 
              And Qtd_SldPra > 0
              Union All
              Select '2' as CodLocEst, Dat_Vencim, Cod_Lote, Qtd_SldDep 
                From PRLOT 
              Where Cod_Estabe = @CodEstabe 
              And Cod_Dep = @CodDep
              And Cod_Produt = @CodPrd 
              And Cod_Lote = @CodLot 
              And Qtd_Saldo > 0
              And Qtd_SldDep > 0
              Order by CodLocEst, Dat_Vencim
          end
      end 

    Open PRLOT_Cr
    Fetch Next From PRLOT_Cr Into @LocEst, @DatVct, @LotAux, @SldLot 
    While (@QtdAteAcu < @QtdPedAju) and (@@FETCH_STATUS = 0)
      begin
        Set @PedSol = @QtdPedAju - @QtdAteAcu
        -- se o saldo do lote nao atender a qtd.solicitada refazer a solicitacao proporcionalmente
        if @PedSol > @SldLot
          Set @PedSol = Round(@SldLot*@PerQtp/100,0)

        -- garante as quantidades solicitadas
        if (@PedSol = 0) or ((@QtdAteAcu+@PedSol) > @QtdPedAju)
          Break

        -- Atualiza saldo do lote
        if @LocEst = '1'
          begin
            Update PRLOT
              Set Qtd_SolPra = Qtd_SolPra + @PedSol
            Where Cod_Estabe = @CodEstabe 
            And Cod_Dep = @CodDep
            And Cod_Produt = @CodPrd
            And Cod_Lote = @LotAux
          end
        else
          begin
            Update PRLOT
              Set Qtd_SolDep = Qtd_SolDep + @PedSol
            Where Cod_Estabe = @CodEstabe
            And Cod_Dep = @CodDep
            And Cod_Produt = @CodPrd
            And Cod_Lote = @LotAux
          end
          
        -- incrementa saldo solicitado PRXES
        Update PRXES
          Set Qtd_Solici = Qtd_Solici + @PedSol
        Where Cod_Estabe = @CodEstabe 
        And Cod_Produt = @CodPrd

        Update PRXES
          Set Qtd_PrmSolici = Qtd_PrmSolici + @PedSol
        Where Cod_Estabe = @CodEstabe 
        And Cod_Produt = @CodPrd 
        and IsNull(@CodPrm,0) > 0
          
        Set @QtdAteAcu = @QtdAteAcu + @PedSol
        Fetch Next From PRLOT_Cr Into @LocEst, @DatVct, @LotAux, @SldLot 
      end
    Close PRLOT_Cr
    Deallocate PRLOT_Cr
    
/*
    -- incrementa saldo solicitado PRXES
    Update PRXES
      Set Qtd_Solici = Qtd_Solici + @QtdAteAcu
    Where Cod_Estabe = @CodEstabe 
    And Cod_Produt = @CodPrd

    Update PRXES
      Set Qtd_PrmSolici = Qtd_PrmSolici + @QtdAteAcu
    Where Cod_Estabe = @CodEstabe 
    And Cod_Produt = @CodPrd and (@CodPrm > 0 and not @CodPrm is null)
*/

  end

Commit Transaction

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_RemanejaLotes_PDVIT]
@CodEstabe int,
@CodPed int

AS

SET NOCOUNT ON

Declare @FlgErr bit,
        @MsgErr varchar(50),
        @QtdIteCnf int,
        @QtdLotCnf int,
        @CodLotUni varchar(20),
        @WCodPedNeg int,
        @CodDep smallint

Set @WCodPedNeg = @CodPed * (-1)
Set @FlgErr = 0
-- sem WMS: deposito unico
Set @CodDep = IsNull((Select min(Cod_Dep) 
                        From TBDEP 
                       Where Cod_Estabe = @CodEstabe),1)

-- total de itens na conferencia
Set @QtdIteCnf = (Select count (*) from CPVIT Where Cod_Estabe = @CodEstabe And Num_PedCnf = @WCodPedNeg And Num_VolCnf = 1)
-- total de lotes na conferencia
Set @QtdLotCnf = (Select count(distinct Cod_Lote) From CPVIT Where Cod_Estabe = @CodEstabe And Num_PedCnf = @WCodPedNeg And Num_VolCnf = 1)
if @QtdIteCnf = 1
  Set @CodLotUni = (Select Cod_Lote From CPVIT Where Cod_Estabe = @CodEstabe And Num_PedCnf = @WCodPedNeg And Num_VolCnf = 1)
else
  Set @CodLotUni = 'VARIOS'
  
Select top 1 @FlgErr = 1,
       @MsgErr = 'Produto inválido ('+cast(Cod_Produt as varchar)+') ' 
  From CPVIT 
 Where Cod_Estabe = @CodEstabe 
   And Num_PedCnf = @WCodPedNeg 
   And Num_VolCnf = 1 
   And Cod_Produt not in (Select distinct Cod_Produto From PDVIT 
                           Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
                             And Cod_Pedido > 0 And IsNull(Tip_Sai,'') <> 'B')

Select top 1 
       @FlgErr = 1, 
       @MsgErr = 'Produto ('+cast(c.Cod_Produto as varchar)+') c/quantidade inválida '
  From (Select Cod_Produto = Cod_Produt, Qtd_Produto = sum(Qtd_Produt)
          From CPVIT
         Where Cod_Estabe = @CodEstabe 
           And Num_PedCnf = @WCodPedNeg
           And Num_VolCnf = 1  
         Group by Cod_Produt) c Left Join
       (Select Cod_Produto, Qtd_Produto = sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0))
          From PDVIT
         Where Cod_Estabe = @CodEstabe 
           And Cod_Pedido = @CodPed
           And IsNull(Tip_Sai,'') <> 'B'
         Group by Cod_Produto) p on c.Cod_Produto = p.Cod_Produto
 Where c.Qtd_Produto <> IsNull(p.Qtd_Produto,0)      
   And @FlgErr = 0

if @FlgErr = 1
  RAISERROR(@MsgErr,16,1)
else  
-- faz as tranferencias de lotes se: existem mais de 1 lote ou existe somente 1 lote diferente de '*'
if (@FlgErr = 0) and  ((@QtdLotCnf > 1) or ((@QtdLotCnf = 1) and (@CodLotUni <> '*')))
begin
  Begin Transaction  
  
    -- coloca o pedido em modo de calculo  (nao solicita lotes dos itens)
    Update PDVCB
       Set Flg_Calc = 1
     Where Cod_Estabe = @CodEstabe 
       And Numero = @CodPed

     -- assegura recalculo de tributos 
    Update PDVCB
       Set Flg_CriIteFec = 0
     Where Cod_Estabe = @CodEstabe 
       And Numero = @CodPed
       And IsNull(Flg_CriIteFec,0) = 1

    Update CPVCB
       Set Qtd_IteCnf = Qtd_IteCnf + 0
     Where Cod_Estabe = @CodEstabe 
       And Num_PedCnf = @WCodPedNeg
       And Num_VolCnf = 1

    -- variaveis para salvar valores iniciais do pedido para serem usados qdo incluir uma nova linha (lote)
    Declare @CODPRD int, 
                 @LOCFIS varchar(15), 
                 @CODFAB int, 
                 @PRCTAB numeric(18,4), 
                 @PRCTABBRU numeric(18,4), 
                 @PRCUNI numeric(18,8), 
                 @PERDSC numeric(18,4), 
                 @FLGPRCUNIDSC bit, 
                 @PRZMAX int, 
                 @DSCPRZ numeric(18,4), 
                 @DSCVIS numeric(18,4), 
                 @CODPRM int,
				 @CODKITPRM int,
                 @FATCNVIMPFAT int,
                 @PRCMAXCON numeric(18,4), 
                 @PRCFAB numeric(18,4), 
                 @NUMSEQDIG int,
                 @NOMUSUDBQ varchar(15),
                 @DESUNVIMPFAT char(3),
                 @DESAPRIMPFAT varchar(12),
                 @IDPOLCOM int,
                 @FLGVERBA bit, 
                 @PRCPOLCOM numeric(18,8), 
                 @PERDSCPOLCOM numeric(18,4), 
                 @PERDSCVISPOLCOM numeric(18,4), 
		         @TIPSAI varchar(1), 
                 @it_CodLot varchar(20), 
                 @it_LocFis varchar(15), 
                 @it_CodFab int, 
                 @WQtdAux int,
                 @it_QtdPed int, 
                 @it_QtdPra int, 
                 @it_QtdDep int, 
                 @it_QtdDif int, 
                 @it_QtdDifPra int, 
                 @it_QtdDifDep int, 
                 @WSldLot int, 
                 @WLotDis int, 
                 @WLotDisPra int, 
                 @WLotDisDep int, 
                 @WLotAux varchar(20),
                 @WLocEst varchar(1),
                 @WDatVct smalldatetime,
                 @it_PrcUni numeric(18,8), 
                 @it_PerDsc numeric(18,4), 
                 @it_FlgPrcUniDsc bit, 
                 @it_PrzMax int, 
                 @it_DscPrz numeric(18,4), 
                 @it_DscVis numeric(18,4),
                 @cf_CodPrd int, 
                 @cf_CodLot varchar(20), 
                 @cf_QtdCnf int,
                 @to_CodCfoNorInt int

    -- ver cfop para prioridade de estoque
    Select @to_CodCfoNorInt = t.Cod_CfoNorInt
      From TPOPE t Inner Join PDVCB p on (t.Cod_Ope = p.Tip_Faturamento)
     Where p.Cod_Estabe = @CodEstabe 
       And p.Numero = @CodPed

    -- fazer ajustes por produto
    Declare PRODU_Cr Cursor Local Fast_Forward For
      Select distinct Cod_Produt
        From CPVIT 
       Where Cod_Estabe = @CodEstabe 
         And Num_PedCnf = @WCodPedNeg
         And Num_VolCnf = 1 
       Order by Cod_Produt

    Open PRODU_Cr
    Fetch Next From PRODU_Cr Into @CODPRD
    While @@FETCH_STATUS = 0
      begin
        -- guarda valores iniciais do produto
        Select top 1
            @LOCFIS = Loc_Fisica,
            @CODFAB = Cod_Fabricante,
            @PRCTAB = Prc_Tabela,
            @PRCTABBRU = Prc_TabBru,
            @PRCUNI = Prc_Unitario,
            @PERDSC = Per_Desconto,
            @FLGPRCUNIDSC = Flg_PrcUniDsc,
            @PRZMAX = Qtd_PrzMax,
            @DSCPRZ = Per_Descon,
            @DSCVIS = Per_DscVis,
            @CODPRM = Cod_Promocao,
			@CODKITPRM = Cod_KitPrm,
            @FATCNVIMPFAT = Fat_CnvImpFat,
            @PRCMAXCON = Prc_MaxCon,
            @PRCFAB = Prc_Fabric,
            @NUMSEQDIG = Num_SeqDig,
            @NOMUSUDBQ = Nom_UsuDesbloq,
            @DESUNVIMPFAT = Des_UnvImpFat,
            @DESAPRIMPFAT = Des_AprImpFat,
            @IDPOLCOM = Id_PolCom,
            @FLGVERBA = IsNull(Flg_Verba,0), 
            @PRCPOLCOM = Prc_PolCom, 
            @PERDSCPOLCOM = Per_DscPolCom, 
            @PERDSCVISPOLCOM = Per_DscVisPolCom,
	        @TIPSAI = Tip_Sai
          From PDVIT
        Where Cod_Estabe = @CodEstabe 
        And Cod_Pedido = @CodPed
        and Cod_Produto = @CODPRD

        -- bloqueia PRODU
        Update PRXES
          Set Qtd_Fisico = Qtd_Fisico + 0
        Where Cod_Estabe = @CodEstabe 
        And Cod_Produt = @CODPRD

        -- devolve itens do produto em PDVIT em desacordo com CPVIT
        Declare PDVIT_Cr Cursor Local Fast_Forward For
          -- seleciona itens em PDVIT com mesmo lote e quantidades maiores que em CPVIT
          Select v.Cod_Lote, (v.Qtd_Pedido+v.Qtd_Bonificacao) as Qtd_Ped, v.Qtd_Pra, v.Qtd_Dep, c.Qtd_Produt
            From PDVIT v, CPVIT c
          Where v.Cod_Estabe = @CodEstabe 
          And   v.Cod_Pedido = @CodPed
          and   c.Num_PedCnf = @WCodPedNeg
          And   c.Num_VolCnf = 1
          And   c.Cod_Estabe = @CodEstabe
          and   v.Cod_Produto = @CODPRD
          and   c.Cod_Produt = @CODPRD
          and   v.Cod_Lote = c.Cod_Lote
          and   (v.Qtd_Pedido+v.Qtd_Bonificacao) > c.Qtd_Produt
          -- seleciona itens em PDVIT com lotes inexistentes em CPVIT
          Union
          Select distinct v.Cod_Lote, (v.Qtd_Pedido+v.Qtd_Bonificacao) as Qtd_Ped, v.Qtd_Pra, v.Qtd_Dep, 0
            From PDVIT v, CPVIT c
          Where v.Cod_Estabe = @CodEstabe 
          And   v.Cod_Pedido = @CodPed
          and   c.Num_PedCnf = @WCodPedNeg
          And   c.Num_VolCnf = 1
          And   c.Cod_Estabe = @CodEstabe
          and   v.Cod_Produto = @CODPRD
          and   c.Cod_Produt = @CODPRD
          and   v.Cod_Lote not in (Select distinct Cod_Lote From CPVIT Where Cod_Estabe = @CodEstabe And Num_PedCnf = @WCodPedNeg and Num_VolCnf = 1 and Cod_Produt = @CODPRD)
          and   (v.Qtd_Pedido+v.Qtd_Bonificacao) > 0
          Order by v.Cod_Lote

        Open PDVIT_Cr
        Fetch Next From PDVIT_Cr Into @it_CodLot, @it_QtdPed, @it_QtdPra, @it_QtdDep, @cf_QtdCnf
        While @@FETCH_STATUS = 0
          begin
            if @it_QtdPra is null
              Set @it_QtdPra = 0
            if @it_QtdDep is null
              Set @it_QtdDep = 0
            if (@it_QtdPra+@it_QtdDep) <> @it_QtdPed
              begin
                Set @it_QtdPra = @it_QtdPed - @it_QtdDep
              end

            -- calcula o excesso em PDVIT
            Set @it_QtdDif = @cf_QtdCnf - @it_QtdPed  -- sempre negativo
            Set @it_QtdDifPra = 0
            Set @it_QtdDifDep = 0

            -- distribui deferenca entre estoques
            while ((@it_QtdDifPra+@it_QtdDifDep) <> @it_QtdDif) and ((@it_QtdPra+@it_QtdDep) > 0)
              begin
                if @to_CodCfoNorInt > 0
                  begin
                    if @it_QtdPra > 0
                      begin
                        Set @it_QtdDifPra = @it_QtdDifPra - 1
                        Set @it_QtdPra = @it_QtdPra - 1
                      end
                    else
                    if @it_QtdDep > 0
                      begin
                        Set @it_QtdDifDep = @it_QtdDifDep - 1
                        Set @it_QtdDep = @it_QtdDep - 1
                      end
                  end
                else
                  begin
                    if @it_QtdDep > 0
                      begin
                        Set @it_QtdDifDep = @it_QtdDifDep - 1
                        Set @it_QtdDep = @it_QtdDep - 1
                      end
                    else
                    if @it_QtdPra > 0
                      begin
                        Set @it_QtdDifPra = @it_QtdDifPra - 1
                        Set @it_QtdPra = @it_QtdPra - 1
                      end
                  end
              end

            -- assegura diferenca
            if (@it_QtdDifPra+@it_QtdDifDep) <> @it_QtdDif
              if @to_CodCfoNorInt > 0
                Set @it_QtdDifPra = @it_QtdDif - @it_QtdDifDep
              else
                Set @it_QtdDifDep = @it_QtdDif - @it_QtdDifPra

            if @cf_QtdCnf <> 0
              begin
                Update PDVIT
                  Set Qtd_Pedido = Qtd_Pedido + @it_QtdDif,
                        Qtd_Solicitado = Qtd_Solicitado + @it_QtdDif,

                        Qtd_Pra = Qtd_Pra + @it_QtdDifPra,
                        Qtd_Dep = Qtd_Dep + @it_QtdDifDep
                Where Cod_Estabe = @CodEstabe 
                And Cod_Pedido = @CodPed
                And Cod_Produto = @CODPRD
                And Cod_Lote = @it_CodLot

                -- normaliza valores p/ impressao da NF
                Update PDVIT
                  Set Qtd_ImpFat = (Qtd_Pedido+Qtd_Bonificacao)*1.0/@FATCNVIMPFAT,
                        Fat_CnvImpFat = @FATCNVIMPFAT,
                        Prc_UniImpFat = Prc_Unitario * @FATCNVIMPFAT
                Where Cod_Estabe = @CodEstabe 
                And Cod_Pedido = @CodPed
                And Cod_Produto = @CODPRD
                And Cod_Lote = @it_CodLot
              end
            else
              begin
                Delete From PDVIT
                Where Cod_Estabe = @CodEstabe 
                And Cod_Pedido = @CodPed
                And Cod_Produto = @CODPRD
                And Cod_Lote = @it_CodLot
              end 

            -- atualiza PRLOT
            Update PRLOT
              Set Qtd_SolPra = Qtd_SolPra + @it_QtdDifPra
            Where Cod_Estabe = @CodEstabe 
            And Cod_Dep = @CodDep
            And Cod_Produt = @CODPRD 
            and Cod_Lote = @it_CodLot
            And @it_QtdDifPra <> 0

            Update PRLOT
              Set Qtd_SolDep = Qtd_SolDep + @it_QtdDifDep
            Where Cod_Estabe = @CodEstabe 
            And Cod_Dep = @CodDep
            And Cod_Produt = @CODPRD 
            and Cod_Lote = @it_CodLot
            And @it_QtdDifDep <> 0

            Fetch Next From PDVIT_Cr Into @it_CodLot, @it_QtdPed, @it_QtdPra, @it_QtdDep, @cf_QtdCnf
          end
        Close PDVIT_Cr
        Deallocate PDVIT_Cr

        -- insere itens de CPVIT em PDVIT
        -- selecionas intens da conferencia
        Declare CPVIT_Cr Cursor Local Fast_Forward For
          -- seleciona itens com mesmo lote e quantidades conferida maior que pedido
          Select c.Cod_Lote, c.Qtd_Produt, (v.Qtd_Pedido+v.Qtd_Bonificacao) as Qtd_Ped
            From CPVIT c, PDVIT v
          Where c.Cod_Estabe = @CodEstabe 
          And   c.Num_PedCnf = @WCodPedNeg
          And   c.Num_VolCnf = 1
          And   v.Cod_Estabe = @CodEstabe
          and   v.Cod_Pedido = @CodPed
          and   c.Cod_Produt = @CODPRD
          and   v.Cod_Produto = @CODPRD
          and   c.Cod_Lote = v.Cod_Lote
          and   c.Qtd_Produt > (v.Qtd_Pedido+v.Qtd_Bonificacao)
          -- seleciona itens com lotes inexistentes em PDVIT
          Union
          Select distinct c.Cod_Lote, c.Qtd_Produt, 0 as Qtd_Ped
            From CPVIT c, PDVIT v
          Where c.Cod_Estabe = @CodEstabe 
          And   c.Num_PedCnf = @WCodPedNeg
          And   c.Num_VolCnf = 1
          And   v.Cod_Estabe = @CodEstabe
          and   v.Cod_Pedido = @CodPed
          and   c.Cod_Produt = @CODPRD
          and   v.Cod_Produto = @CODPRD
          and   c.Cod_Lote not in (Select distinct Cod_Lote From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed and Cod_Produto = @CODPRD)
          -- seleciona itens inexistentes em PDVIT
          Union
          Select c.Cod_Lote, c.Qtd_Produt, 0 as Qtd_Ped
            From CPVIT c
          Where c.Cod_Estabe = @CodEstabe 
          And   c.Num_PedCnf = @WCodPedNeg
          And   c.Num_VolCnf = 1
          and   c.Cod_Produt = @CODPRD
          and   c.Cod_Produt not in (Select distinct Cod_Produto From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed)
          Order by c.Cod_Lote

        Open CPVIT_Cr
        Fetch Next From CPVIT_Cr Into @cf_CodLot, @cf_QtdCnf, @it_QtdPed
        While @@FETCH_STATUS = 0
          begin
            -- calcula quantidade a incluir
            Set @it_QtdDif = @cf_QtdCnf - @it_QtdPed
            Set @it_QtdDifPra = 0
            Set @it_QtdDifDep = 0

            -- ATUALIZA PRLOT           
            Set @WSldLot = @it_QtdDif
            if not Exists(Select * From PRLOT Where Cod_Estabe = @CodEstabe And Cod_Dep = @CodDep And Cod_Produt = @CODPRD and Cod_Lote = @cf_CodLot)
              begin
                Insert into PRLOT (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Qtd_FisPra, Qtd_SolPra, Qtd_FisDep, Qtd_SolDep)
                           values (@CodEstabe, @CodDep, @CODPRD, @cf_CodLot, 0,0,0,0)
                if (@@error <> 0)
                  begin
                    Rollback Transaction
                    Return
                  end
              end
      
            -- atualiza lote se existe saldo
            if Exists(Select * From PRLOT Where Cod_Estabe = @CodEstabe And Cod_Dep = @CodDep And Cod_Produt = @CODPRD and  Cod_Lote = @cf_CodLot And Qtd_Saldo > 0)
              begin
                Select @WLotDis = Qtd_Saldo,
                       @WLotDisPra = Qtd_SldPra,
                       @WLotDisDep = Qtd_SldDep
                  From PRLOT 
                Where Cod_Estabe = @CodEstabe 
                And Cod_Dep = @CodDep 
                And Cod_Produt = @CODPRD 
                and Cod_Lote = @cf_CodLot 
                And Qtd_Saldo > 0

                if @WLotDis >=  @it_QtdDif
                  begin
                    Set @WSldLot = @WSldLot - @it_QtdDif
                  end
                else
                  begin
                    Set @WSldLot = @WSldLot - @WLotDis
                  end

                while ((@it_QtdDifPra+@it_QtdDifDep) <> @it_QtdDif) and ((@WLotDisPra+@WLotDisDep) > 0)
                  begin
                    if @to_CodCfoNorInt > 0
                      begin
                        if @WLotDisPra > 0
                          begin
                            Set @it_QtdDifPra = @it_QtdDifPra + 1
                            Set @WLotDisPra = @WLotDisPra - 1
                          end
                        else
                        if @WLotDisDep > 0
                          begin
                            Set @it_QtdDifDep = @it_QtdDifDep + 1
                            Set @WLotDisDep = @WLotDisDep - 1
                          end
                      end
                    else
                      begin
                        if @WLotDisDep > 0
                          begin
                            Set @it_QtdDifDep = @it_QtdDifDep + 1
                            Set @WLotDisDep = @WLotDisDep - 1
                          end
                        else
                        if @WLotDisPra > 0
                          begin
                            Set @it_QtdDifPra = @it_QtdDifPra + 1
                            Set @WLotDisPra = @WLotDisPra - 1
                          end
                      end
                  end

                Update PRLOT
                  Set Qtd_SolPra = Qtd_SolPra + @it_QtdDifPra
                Where Cod_Estabe = @CodEstabe 
                And Cod_Dep = @CodDep 
                And Cod_Produt = @CODPRD 
                and Cod_Lote = @cf_CodLot
                And @it_QtdDifPra > 0

                Update PRLOT
                  Set Qtd_SolDep = Qtd_SolDep + @it_QtdDifDep
                Where Cod_Estabe = @CodEstabe 
                And Cod_Dep = @CodDep 
                And Cod_Produt = @CODPRD 
                and Cod_Lote = @cf_CodLot
                And @it_QtdDifDep > 0
              end

            -- se o saldo ainda for insufuciente
            -- remanejar quantidade de outro lote do produto para atender a solicitacao
            if @WSldLot > 0
              begin
                if @to_CodCfoNorInt > 0
                  begin
                    Declare PRLOT_Cr Cursor Local Fast_Forward For 
                      Select '1' as CodLocEst, Dat_Vencim, Cod_Lote, Qtd_SldPra 
                        From PRLOT 
                      Where Cod_Estabe = @CodEstabe 
                      And Cod_Dep = @CodDep 
                      And Cod_Produt = @CODPRD 
                      and Cod_Lote <> @cf_CodLot
                      And Qtd_SldPra > 0
                      Union
                      Select '2' as CodLocEst, Dat_Vencim, Cod_Lote, Qtd_SldDep 
                        From PRLOT 
                      Where Cod_Estabe = @CodEstabe 
                      And Cod_Dep = @CodDep 
                      And Cod_Produt = @CODPRD 
                      and Cod_Lote <> @cf_CodLot
                      And Qtd_SldDep > 0
                      Order by CodLocEst, Dat_Vencim
                  end
                else
                  begin
                    Declare PRLOT_Cr Cursor Local Fast_Forward For 
                      Select '2' as CodLocEst, Dat_Vencim, Cod_Lote, Qtd_SldDep 
                        From PRLOT 
                      Where Cod_Estabe = @CodEstabe 
                      And Cod_Dep = @CodDep 
                      And Cod_Produt = @CODPRD 
                      and Cod_Lote <> @cf_CodLot
                      And Qtd_SldDep > 0
                      Union
                      Select '1' as CodLocEst, Dat_Vencim, Cod_Lote, Qtd_SldPra 
                        From PRLOT 
                      Where Cod_Estabe = @CodEstabe 
                      And Cod_Dep = @CodDep 
                      And Cod_Produt = @CODPRD 
                      and Cod_Lote <> @cf_CodLot
                      And Qtd_SldPra > 0
                      Order by CodLocEst desc, Dat_Vencim 
                  end

                Open PRLOT_Cr
                Fetch Next From PRLOT_Cr Into @WLocEst, @WDatVct, @WLotAux, @WLotDis 
                While (@WSldLot > 0) and (@@FETCH_STATUS = 0)
                  begin
                    if @WLotDis >= @WSldLot
                      Set @WQtdAux = @WSldLot
                    else
                      Set @WQtdAux = @WLotDis

                    -- transfere quantidades entre lotes
                    if @WLocEst = '1'
                      begin
                        Set @it_QtdDifPra = @it_QtdDifPra + @WQtdAux

                        Update PRLOT
                          Set Qtd_FisPra = Qtd_FisPra - @WQtdAux
                        Where Cod_Estabe = @CodEstabe 
                        And Cod_Dep = @CodDep 
                        And Cod_Produt = @CODPRD 
                         and Cod_Lote = @WLotAux

                        Update PRLOT
                          Set Qtd_FisPra = Qtd_FisPra + @WQtdAux
                        Where Cod_Estabe = @CodEstabe 
                        And Cod_Dep = @CodDep 
                        And Cod_Produt = @CODPRD 
                        and Cod_Lote = @cf_CodLot

                        Update PRLOT
                          Set Qtd_SolPra = Qtd_SolPra + @WQtdAux
                        Where Cod_Estabe = @CodEstabe 
                        And Cod_Dep = @CodDep 
                        And Cod_Produt = @CODPRD 
                        and Cod_Lote = @cf_CodLot
                      end
                    else
                      begin
                        Set @it_QtdDifDep = @it_QtdDifDep + @WQtdAux

                        Update PRLOT
                          Set Qtd_FisDep = Qtd_FisDep - @WQtdAux
                        Where Cod_Estabe = @CodEstabe 
                        And Cod_Dep = @CodDep 
                        And Cod_Produt = @CODPRD 
                        and Cod_Lote = @WLotAux

                        Update PRLOT
                          Set Qtd_FisDep = Qtd_FisDep + @WQtdAux
                        Where Cod_Estabe = @CodEstabe 
                        And Cod_Dep = @CodDep 
                        And Cod_Produt = @CODPRD 
                        and Cod_Lote = @cf_CodLot

                        Update PRLOT
                          Set Qtd_SolDep = Qtd_SolDep + @WQtdAux
                        Where Cod_Estabe = @CodEstabe 
                        And Cod_Dep = @CodDep 
                        And Cod_Produt = @CODPRD 
                        and Cod_Lote = @cf_CodLot

                      end

                    Set @WSldLot = @WSldLot - @WQtdAux

                    Fetch Next From PRLOT_Cr Into @WLocEst, @WDatVct, @WLotAux, @WLotDis 
                  end

                Close PRLOT_Cr
                Deallocate PRLOT_Cr
              end  -- if @WSldLot > 0

            -- assegura diferenca
            if (@it_QtdDifPra+@it_QtdDifDep) <> @it_QtdDif
              if @to_CodCfoNorInt > 0
                Set @it_QtdDifPra = @it_QtdDif - @it_QtdDifDep
              else
                Set @it_QtdDifDep = @it_QtdDif - @it_QtdDifPra

            -- insere registro em PDVIT
            if (Select count(*) From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed and Cod_Produto = @CODPRD and Cod_Lote = @cf_CodLot) > 0
              begin
                Update PDVIT
                  Set Qtd_Pedido = Qtd_Pedido + @it_QtdDif,
                      Qtd_Solicitado = Qtd_Solicitado + @it_QtdDif,
                      Qtd_Pra = Qtd_Pra + @it_QtdDifPra,
                      Qtd_Dep = Qtd_Dep + @it_QtdDifDep
                Where Cod_Estabe = @CodEstabe 
                And Cod_Pedido = @CodPed 
                and Cod_Produto = @CODPRD and Cod_Lote = @cf_CodLot
              end
            else
              begin
                Insert into PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Qtd_Pedido, Qtd_Bonificacao, 
                                   Qtd_Pra, Qtd_Dep, Loc_Fisica, Cod_Fabricante, Cod_Promocao, Cod_KitPrm,
                                   Per_Desconto, Prc_Unitario, Qtd_PrzMax, Per_Descon, Per_DscVis,
                                   Qtd_Solicitado, Flg_PrcUniDsc,Prc_Tabela, Prc_TabBru, Prc_MaxCon, Prc_Fabric,
                                   Num_SeqDig, Nom_UsuDesbloq, Des_UnvImpFat, Des_AprImpFat,
                                   Id_PolCom, Flg_Verba, Prc_PolCom, Per_DscPolCom, Per_DscVisPolCom,
                                   Tip_Sai)
                           Values (@CodEstabe, @CodPed, @CODPRD, @cf_CodLot, @cf_QtdCnf, 0, 
                                   @it_QtdDifPra, @it_QtdDifDep, @LOCFIS, @CODFAB, @CodPrm, @CODKITPRM,
                                   @PERDSC, @PRCUNI, @PRZMAX, @DSCPRZ, @DSCVIS,
                                   @cf_QtdCnf, @FLGPRCUNIDSC, @PRCTAB, @PRCTABBRU, @PRCMAXCON, @PRCFAB,
                                   @NUMSEQDIG, @NOMUSUDBQ, @DESUNVIMPFAT, @DESAPRIMPFAT, 
                                   @IDPOLCOM, @FLGVERBA, @PRCPOLCOM, @PERDSCPOLCOM, @PERDSCVISPOLCOM,
				                   IsNull(@TIPSAI,''))
                if (@@error <> 0)
                  begin
                    Rollback Transaction
                    Return
                  end
              end

            -- normaliza valores p/ impressao da NF
            Update PDVIT
              Set Qtd_ImpFat = (Qtd_Pedido+Qtd_Bonificacao)*1.0/@FATCNVIMPFAT,
                  Fat_CnvImpFat = @FATCNVIMPFAT,
                  Prc_UniImpFat = Prc_Unitario * @FATCNVIMPFAT
            Where Cod_Estabe = @CodEstabe 
            And Cod_Pedido = @CodPed 
            and Cod_Produto = @CODPRD and Cod_Lote = @cf_CodLot

            Fetch Next From CPVIT_Cr Into @cf_CodLot, @cf_QtdCnf, @it_QtdPed
          end
        Close CPVIT_Cr
        Deallocate CPVIT_Cr

        Fetch Next From PRODU_Cr Into @CODPRD
      end
    Close PRODU_Cr
    Deallocate PRODU_Cr            

    --  tira o pedido do modo de calculo
    Update PDVCB
      Set Flg_Calc = 0
    Where Cod_Estabe = @CodEstabe 
    And Numero = @CodPed

    if Exists(Select c.CodPrd
                From (Select CodPrd = Cod_Produt, QtdPrd = sum(IsNull(Qtd_Produt,0))
                        From CPVIT 
                      Where Cod_Estabe = @CodEstabe 
                      And Num_PedCnf = @WCodPedNeg
                      And Num_VolCnf = 1 
                      Group by Cod_Produt) c  Inner Join
                     (Select CodPrd = Cod_Produto, QtdPrd = sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0))
                        From PDVIT
                      Where Cod_Estabe = @CodEstabe 
                      And Cod_Pedido = @CodPed
                      Group by Cod_Produto) p on c.CodPrd = p.CodPrd  
              Where c.QtdPrd <> p.QtdPrd)
      Rollback Transaction
    else                
      begin   
        -- Elimina os registros da conferencia
        Delete From CPVCB
        Where Cod_Estabe = @CodEstabe 
        And Num_PedCnf = @WCodPedNeg
        And Num_VolCnf = 1

        Commit Transaction
      end
end

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE TRIGGER [dbo].[TR_ACERT_AtualizaEstoque] ON [dbo].[ACERT]
FOR INSERT
NOT FOR REPLICATION
AS

SET NOCOUNT ON

Declare @CodEstabe int
      , @CodPrd int
      , @CodLot varchar(20)
      , @DatMov smalldatetime
      , @DatVct smalldatetime
      , @DatFab smalldatetime
      , @CodOriMov varchar(2)
      , @QtdAcrPra int
      , @QtdAcrDep int
      , @EntSai varchar(1)
      , @FlgErr bit
      , @QtdSldPra int
      , @QtdSldDep int
      , @QtdMovPra int
      , @QtdMovDep int
      , @QtdMovTot int
      , @FlgEmpPra bit
      , @FlgEmpDep bit
      , @NumAcr int
      , @DesOri varchar(20)
      , @CodDep smallint
      , @NumRua smallint
      , @NumCol smallint
      , @NumNiv smallint
      , @NumApt smallint
      , @NomUsu varchar(35)
      , @Msg varchar(200)

-- inicializa variaveis
Select @NumAcr = Numero
     , @CodEstabe = Cod_Estabe
     , @CodPrd = Cod_Produto
     , @CodLot = Cod_Lote
     , @DatMov = Dat_Movimento
     , @CodOriMov = IsNull(Cod_OriMov,'')
     , @DatVct = Dat_Vencimento
     , @DatFab = Dat_Fabric
     , @QtdAcrPra = Isnull(Qtd_Acerto,0)
     , @QtdAcrDep = Isnull(Qtd_AceDep,0)
     , @CodDep = IsNull(Cod_Dep,1)
     , @NumRua = IsNull(Num_Rua,0)
     , @NumCol = IsNull(Num_Col,0)
     , @NumNiv = IsNull(Num_Niv,0)
     , @NumApt = IsNull(Num_Apt,0)
     , @NomUsu = IsNull(Usuario,'')
  From Inserted

-- configura flag de emprestimo de estoque
-- arranjo para poder extornar em PRSLD o estoque correto qdo do cancelamento de uma NF
Set @FlgEmpPra = 0
Set @FlgEmpDep = 0
Set @QtdMovPra = @QtdAcrPra
Set @QtdMovDep = @QtdAcrDep
if @QtdMovPra < 0
  begin
    Set @QtdMovPra = @QtdAcrPra * (-1)
    Set @FlgEmpPra = 1
  end
if @QtdMovDep < 0
  begin
    Set @QtdMovDep = @QtdAcrDep * (-1)
    Set @FlgEmpDep = 1
  end

-- verifica se é E / S
Select @EntSai = tp.Tip_Movimento 
  From TPMVE tp
       Inner Join Inserted i on tp.Codigo = i.Cod_TipMov

if @EntSai = 'S'
  begin
    Set @QtdMovPra = @QtdMovPra * (-1)
    Set @QtdMovDep = @QtdMovDep * (-1)
  end

Set @FlgErr = 0

Begin Transaction
-- se nao existir o cadastro do lote, cria o registro (se for entrada). O saldo é atualizado na PR_AtualizaSadoEstoque
if not Exists(Select 1 
                From PRLOT 
               Where Cod_Estabe = @CodEstabe and Cod_Dep = @CodDep 
                 And Cod_Produt = @CodPrd and Cod_Lote = @CodLot)
  if @EntSai = 'S'
    Set @FlgErr = 1
  else
    begin
      Insert into PRLOT (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote)
        Values (@CodEstabe, @CodDep, @CodPrd, @CodLot)

      Update PRLOT
         Set Dat_Vencim = @DatVct
           , Dat_Fabric = @DatFab
           , Qtd_FisPra = 0
           , Qtd_SolPra = 0
           , Qtd_FisDep = 0
           ,Qtd_SolDep = 0
       Where Cod_Estabe = @CodEstabe and Cod_Dep = @CodDep 
         And Cod_Produt = @CodPrd and Cod_Lote = @CodLot
    end
else
  if @EntSai = 'S'
    begin
      -- ver se existe lote suficiente para saida
      Select @QtdSldPra = IsNull(Qtd_SldPra,0),
             @QtdSldDep = IsNull(Qtd_SldDep,0)
        From PRLOT 
       Where Cod_Estabe = @CodEstabe And Cod_Dep = @CodDep
         and Cod_Produt = @CodPrd and Cod_Lote = @CodLot 

      if (@QtdSldPra < -@QtdMovPra) or (@QtdSldDep < -@QtdMovDep)
        Set @FlgErr = 1
    end
  else
    begin
      Update PRLOT
         Set Dat_Vencim = @DatVct
           , Dat_Fabric = @DatFab
       Where Cod_Estabe = @CodEstabe And Cod_Dep = @CodDep
         And Cod_Produt = @CodPrd And Cod_Lote = @CodLot
        And ((Dat_Vencim is null) or (Dat_Vencim <> @DatVct) or
             (Dat_Fabric is null) or (Dat_Fabric <> @DatFab))
    end

if @FlgErr = 1
  begin
    set @Msg  = 'Saída para lote inexistente / ou saldo do lote insuficiente: Produto: '+convert(varchar(9),@CodPrd)+' Lote: '+@CodLot
    RAISERROR(@Msg ,16,1)
    Rollback Transaction
    Return
  end
else
  begin
    EXEC PR_AtualizaSaldoEstoque @CodOriMov, @CodEstabe, @CodDep, @CodPrd, @CodLot, @DatMov, 
                                 @EntSai, 'O', @QtdMovPra, @FlgEmpPra, @QtdMovDep, @FlgEmpDep
    if (@@error <> 0)
      begin
        Rollback Transaction
        Return
      end
      
    -- registra log   
    Set @DesOri = 'ACE_EST'
    if @EntSai = 'S'
      Set @QtdMovTot = (@QtdAcrPra + @QtdAcrDep) * (-1)
    else  
      Set @QtdMovTot = @QtdAcrPra + @QtdAcrDep
    Exec PR_InserePRLOG @CodEstabe, @CodPrd, @CodLot, @CodDep
                      , @NumRua, @NumCol, @NumNiv, @NumApt
                      , @QtdMovTot, @DesOri, '', @NumAcr, '', '', @NomUsu
    if @@error <> 0 
      begin
        Rollback Transaction
        Return
      end 

    Update A
       Set A.Prc_CustoMedio = P.Prc_CusMed
      From Inserted I 
           inner Join ACERT A on A.Cod_Estabe = I.Cod_Estabe and A.Numero = I.Numero 
           inner Join PRXES p on P.Cod_Estabe = I.Cod_Estabe And p.Cod_Produt = I.Cod_Produto

    Commit Transaction
  end
GO

/*************************************************************************************************/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_BalanGeraNotas]
@CodEstabe int,
@NumSeqBal int,
@CodCliBal int,
@FlgGerDif bit,
@FlgGerSai bit,
@CodOpeSai varchar(3),
@FlgGerEnt bit,
@CodOpeEnt varchar(3),
@TipPrc varchar(1)   -- (F)iscal, (G)erencial

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = cast(GetDate() as Date)

if (@FlgGerDif = 1) and Exists(Select 1 From BALCB Where Cod_Estabe = @CodEstabe And Num_SeqBal = @NumSeqBal and ((IsNull(Num_Nota,0) > 0) or (IsNull(Protocolo,0) > 0)))
  begin
    RAISERROR('NFs j� foram geradas',16,1)
    Return
  end

if (@FlgGerSai = 1) and not Exists(Select 1 From BALCB Where Cod_Estabe = @CodEstabe And Num_SeqBal = @NumSeqBal and IsNull(Num_Nota,0) = 0)
  begin
    RAISERROR('NF de sa�da j� foi gerada',16,1)
    Return
  end

if (@FlgGerEnt = 1) and not Exists(Select 1 From BALCB Where Cod_Estabe = @CodEstabe And IsNull(Protocolo,0) = 0)
  begin
    RAISERROR('NF de Entrada j� foi gerada',16,1)
    Return
  end

if not Exists(Select 1 From CLIEN Where Codigo = @CodCliBal)
  begin
    RAISERROR('Cliente inv�lido',16,1)
    Return
  end

if ((@FlgGerSai = 1) or (@FlgGerDif = 1)) and not Exists(Select 1 From TPOPE Where Cod_Ope = @CodOpeSai)
  begin
    RAISERROR('Tipo de Opera��o de sa�da inv�lido',16,1)
    Return
  end

if ((@FlgGerEnt = 1) or (@FlgGerDif = 1)) and not Exists(Select 1 From TPOPE Where Cod_Ope = @CodOpeEnt)
  begin
    RAISERROR('Tipo de Opera��o de entrada inv�lido',16,1)
    Return
  end

BEGIN
  BEGIN TRANSACTION

  Declare @NumPrt int,
          @NumPdv int,
          @SerNot varchar(3),
          @NumNot int,
          @NumSeqIte int,
          @QtdMaxIteNot int,  
          @QtdIteBal int,  
          @QtdNot int,
          @QtdRes int,
          @AccQtdIte int,
          @AccQtdMov int,
          @CodPrd int,
          @CodLot varchar(20),
          @QtdMov int,
          @QtdLot int,
          @QtdReg int,
          @PrcUni numeric(18,4),
          @WSerSelFis varchar(2),
          @pm_QtdDecPrcItePdv tinyint,
          @pm_FlgCtrSelFis bit,
          @pm_CodVdrPdvCon int,
          @op_TipOpe varchar(1), 
          @op_CodCfo int,
          @op_FlgBlqTrfEstFis bit,
          @cb_CodRegTri int,
		  @Usuario varchar(35),
		  @CodTransp int

  -- usuario infarma auditoria
  Set @Usuario = dbo.FN_UsuarioInfarma()

  Select @pm_QtdDecPrcItePdv = ISNULL(QtdDecPrcItePdv,2),
         @WSerSelFis = Case 
                         When ISNULL(FlgCtrSelFis,0) = 1 then SerieSeloFiscal
                         Else ''
                       End,
         @pm_CodVdrPdvCon = ISNULL(CodVdrPdvCon,0)              
    From PARAM
   Where Cod_Estabe = @CodEstabe

  -- qtd max de itens na NF 
  Set @QtdMaxIteNot = 500

  -- Transportadora da ENXES do cliente(Sa�da)
  if @FlgGerSai = 1
	begin
	  Select @CodTransp = Cod_Transp
        From ENXES
       Where Cod_Estabe = @CodEstabe
         and Cod_Client = @CodCliBal
	end
	  
  -- cria tabela temporaria dos lotes do produto que serao utilizados
  Create Table #BALIT_AUX
       (Cod_Produt int,
        Cod_Lote varchar(20),
        Qtd_Produt int,
        Prc_Unitar numeric(18,4))

  -- Gera Notas de Saida ----------------------------------------------------------------------------------------  
  if (@FlgGerSai = 1) or (@FlgGerDif = 1)
    begin
      -- gera arq. auxiliar com itens da NF a gerar
      Delete From #BALIT_AUX

      if @FlgGerSai = 1 
        begin
          -- todos os itens de saida
          Insert Into #BALIT_AUX (Cod_Produt, Cod_Lote, Qtd_Produt, Prc_Unitar)        
            Select it.Cod_Produt, it.Cod_Lote, it.Qtd_EstPra,
                   Case
                     When @TipPrc = 'F' then Case  
                                               When pr.Prc_CusMedPra > 0 then ROUND(pr.Prc_CusMedPra,@pm_QtdDecPrcItePdv)
                                               When pr.Prc_CusMed > 0 then ROUND(pr.Prc_CusMed,@pm_QtdDecPrcItePdv)
                                               When pr.Prc_CusLiqEnt > 0 then ROUND(pr.Prc_CusLiqEnt,@pm_QtdDecPrcItePdv)
                                               Else 0.01
                                             End
                     When @TipPrc = 'G' then Case 
                                               When pr.Prc_CusMed > 0 then ROUND(pr.Prc_CusMed,@pm_QtdDecPrcItePdv)
                                               When pr.Prc_CusMedPra > 0 then ROUND(pr.Prc_CusMedPra,@pm_QtdDecPrcItePdv)
                                               When pr.Prc_CusLiqEnt > 0 then ROUND(pr.Prc_CusLiqEnt,@pm_QtdDecPrcItePdv)
                                               Else 0.01
                                             End  
                   End 
              From BALIT it  
                   Inner Join PRXES pr on it.Cod_Estabe = pr.Cod_Estabe and it.Cod_Produt = pr.Cod_Produt
             Where it.Cod_Estabe = @CodEstabe
               And it.Num_SeqBal = @NumSeqBal
               And it.Num_Contag = 1
               And it.Tip_Movim = 'S'
               And it.Qtd_EstPra > 0
        end
      else
        begin
          -- saidas somente das diferencas entre saidas e entradas
          DECLARE ITENS_Cr CURSOR Local Fast_Forward For 
     
            Select b.Cod_Produt, Qtd_DifSai = IsNull(s.Qtd_Est,0) - IsNull(e.Qtd_Est,0),
                   Case
                     When @TipPrc = 'F' then Case  
                                               When pr.Prc_CusMedPra > 0 then ROUND(pr.Prc_CusMedPra,@pm_QtdDecPrcItePdv)
                                               When pr.Prc_CusMed > 0 then ROUND(pr.Prc_CusMed,@pm_QtdDecPrcItePdv)
                                               When pr.Prc_CusLiqEnt > 0 then ROUND(pr.Prc_CusLiqEnt,@pm_QtdDecPrcItePdv)
                                               Else 0.01
                                             End
                     When @TipPrc = 'G' then Case 
                                               When pr.Prc_CusMed > 0 then ROUND(pr.Prc_CusMed,@pm_QtdDecPrcItePdv)
                                               When pr.Prc_CusMedPra > 0 then ROUND(pr.Prc_CusMedPra,@pm_QtdDecPrcItePdv)
                                               When pr.Prc_CusLiqEnt > 0 then ROUND(pr.Prc_CusLiqEnt,@pm_QtdDecPrcItePdv)
                                               Else 0.01
                                             End  
                   End
              From (Select distinct Cod_Estabe, Cod_Produt
                      From BALIT
                     Where Cod_Estabe = @CodEstabe
                       And Num_SeqBal = @NumSeqBal
                       And Num_Contag = 1
                       And Qtd_EstPra > 0) b 
                   Inner Join PRXES pr on b.Cod_Estabe = pr.Cod_Estabe and b.Cod_Produt = pr.Cod_Produt 
                   Left  Join (Select Cod_Estabe, Cod_Produt, Qtd_Est = sum(Qtd_EstPra)
                                 From BALIT
                                Where Cod_Estabe = @CodEstabe
                                  And Num_SeqBal = @NumSeqBal
                                  And Num_Contag = 1
                                  And Tip_Movim = 'S'
                                  And Qtd_EstPra > 0
                                Group by Cod_Estabe, Cod_Produt) s on b.Cod_Estabe = s.Cod_Estabe and b.Cod_Produt = s.Cod_Produt 
                   Left  Join (Select Cod_Estabe, Cod_Produt, Qtd_Est = sum(Qtd_EstPra)
                                 From BALIT
                                Where Cod_Estabe = @CodEstabe
                                  And Num_SeqBal = @NumSeqBal
                                  And Num_Contag = 1
                                  And Tip_Movim = 'E'
                                  And Qtd_EstPra > 0
                                Group by Cod_Estabe, Cod_Produt) e on b.Cod_Estabe = e.Cod_Estabe and b.Cod_Produt = e.Cod_Produt
             Where (IsNull(s.Qtd_Est,0) - IsNull(e.Qtd_Est,0)) > 0

          OPEN ITENS_Cr
          FETCH NEXT FROM ITENS_Cr INTO @CodPrd, @QtdMov, @PrcUni
          WHILE @@FETCH_STATUS = 0
          BEGIN
            Set @AccQtdMov = @QtdMov
            
            -- lotes de itens inventariados a movimentar
            DECLARE LOTES_Cr CURSOR Local Fast_Forward For 
            
              Select Cod_Lote, Qtd_EstPra
                From BALIT
               Where Cod_Estabe = @CodEstabe
                 And Num_SeqBal = @NumSeqBal
                 And Num_Contag = 1
                 And Tip_Movim = 'S'
                 And Qtd_EstPra > 0
                 And Cod_Produt = @CodPrd
               Order by Dat_VctLot, Qtd_EstPra desc
            
            OPEN LOTES_Cr
            FETCH NEXT FROM LOTES_Cr INTO @CodLot, @QtdLot
            WHILE (@@FETCH_STATUS = 0) AND (@AccQtdMov > 0)
            BEGIN
              if @QtdLot > @AccQtdMov
                Set @QtdReg = @AccQtdMov
              else   
                Set @QtdReg = @QtdLot
              if @QtdReg > 0
                begin
                  Insert Into #BALIT_AUX (Cod_Produt, Cod_Lote, Qtd_Produt, Prc_Unitar)        
                                  Values (@CodPrd, @CodLot, @QtdReg, @PrcUni)
                  if @@error <> 0
                    begin
                      if @@trancount > 0
                        Rollback Transaction
                      Return
                    end
                end  
              Set @AccQtdMov = @AccQtdMov - @QtdReg
              FETCH NEXT FROM LOTES_Cr INTO @CodLot, @QtdLot
            END
            
            CLOSE LOTES_Cr
            DEALLOCATE LOTES_Cr     
            
            FETCH NEXT FROM ITENS_Cr INTO @CodPrd, @QtdMov, @PrcUni
          END

          CLOSE ITENS_Cr
          DEALLOCATE ITENS_Cr     
          
        end

      Set @QtdIteBal = IsNull((Select COUNT(*) From #BALIT_AUX),0)
      
      if @QtdIteBal > 0
        begin

          Select @op_TipOpe = op.Tip_Ope, 
                 @op_CodCfo = op.Cod_CfoNorInt,
                 @op_FlgBlqTrfEstFis = IsNull(cf.Flg_BlqTrfEstFis,0)
            From TPOPE op
                 left join TBCFO cf on op.Cod_CfoNorInt = cf.Codigo
           Where op.Cod_Ope = @CodOpeSai

          -- quantidade de NF a gerar
          Set @QtdNot = CEILING(CAST(@QtdIteBal AS Numeric)/@QtdMaxIteNot)                 

          -- se qtd de itens da ultima NF < 100 aumenta qtd max de itens na NF para suportar resto
          Set @QtdRes = @QtdIteBal % @QtdMaxIteNot
          if (@QtdRes < 50) and (@QtdNot > 1)
            begin
              Set @QtdNot = @QtdNot - 1
              Set @QtdMaxIteNot = @QtdMaxIteNot + CEILING(CAST(@QtdRes AS Numeric)/@QtdNot)                 
            end
       
          Set @AccQtdIte = 0  
     
          DECLARE BALIT_Cr CURSOR Local Fast_Forward For 
     
            Select Cod_Produt, Cod_Lote, Qtd_Produt, Prc_Unitar
            From #BALIT_AUX

          OPEN BALIT_Cr
          FETCH NEXT FROM BALIT_Cr INTO @CodPrd, @CodLot, @QtdMov, @PrcUni
          WHILE @@FETCH_STATUS = 0
          BEGIN
            -- grava novo cabe�alho de NF
            if @AccQtdIte = 0
              begin
                -- Pega novo numero temporario (protocolo)
                EXEC PR_ProxNumero 'Protocolo', @NumPrt output
 
                Set @SerNot = 'XXX'
                Set @NumNot = @NumPrt

                EXEC PR_ProxNumero 'Pedido_Venda', @NumPdv output

                -- grava cabecalho
                Insert Into NFSCB (Cod_Estabe, Ser_Nota, Num_Nota, Num_SeqBal, Flg_MovEst, Cod_Cliente)
                           Values (@CodEstabe, @SerNot,  @NumNot,  @NumSeqBal, 0, @CodCliBal)      
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end

                -- grava campos na nota
                Update cb
                   Set cb.Cod_Ope = @CodOpeSai, 
                       cb.Cod_Cfo1 = @op_CodCfo, 
                       cb.Flg_BlqTrfEstFis = @op_FlgBlqTrfEstFis,
                       cb.Esp_Nota = 'NF', 
                       cb.Status = 'A',  
                       cb.Tip_Saida = @op_TipOpe, 
                       cb.Tip_OutSai = Case When @op_TipOpe = 'O' then 'P' Else null End, 
                       cb.Dat_Emissao = @Date,      
                       cb.Flg_RetEnt = 1,          
                       cb.Qtd_PagNF = 1,         
                       cb.Ser_Selo = @WSerSelFis, 
                       cb.Cod_FinNfe = '1',    
                       cb.Tip_Frete =  '1',       
                       cb.Cod_Pedido = @NumPdv,    
                       cb.Cod_Vendedor = @pm_CodVdrPdvCon, 
                       cb.Cod_ZonMovEst = null,                                           
                       cb.Cod_Transportadora = @CodTransp,
                       cb.Cod_Fornecedor = 0,
                       cb.Cod_Funcionario = 0,
                       cb.Cod_RegTri = en.Cod_RegTri,
                       cb.Cgc = cl.Cgc_Cpf,
                       cb.Cgf = cl.Cgf,
                       cb.Endereco = SUBSTRING(dbo.FN_EnderecoCompleto(cl.Endereco, cl.Numero, cl.Complemento),1,50),
                       cb.Bairro = ba.Descricao,
                       cb.Cidade = ci.Descricao,
                       cb.Estado = cl.Cod_Estado,
                       cb.Cep = cl.Cep,
                       cb.Cod_CidIbge= ci.Cod_CidIbge,
                       cb.Cod_Cidade = cl.Cod_Cidade,
                       cb.Cod_MacroReg = ba.Cod_MacroReg, 
                       cb.Cod_MicroReg = ba.Cod_MicroReg,
                       cb.Usuario = @Usuario, 
                       cb.Transacao = @Now
                  From NFSCB cb 
                       Left Join CLIEN cl on (cb.Cod_Cliente = cl.Codigo) 
                       Left Join CIDAD ci on ((cl.Cod_Estado = ci.Cod_Estado) and (cl.Cod_Cidade = ci.Codigo))  
                       Left Join BAIRR ba on ((cl.Cod_Estado = ba.Cod_Estado) and (cl.Cod_Cidade = ba.Cod_Cidade) and (cl.Cod_Bairro = ba.Codigo))  
                       Left Join ENXES en on ((cb.Cod_Estabe = en.Cod_Estabe) and (cl.Cgc_Cpf = en.Num_CgcCpf)) 
                 Where cb.Cod_Estabe = @CodEstabe
                   And cb.Ser_Nota = @SerNot
                   And cb.Num_Nota = @NumNot
            
                Select @cb_CodRegTri = Cod_RegTri
                  From NFSCB
                 Where Cod_Estabe = @CodEstabe
                   And Ser_Nota = @SerNot
                   And Num_Nota = @NumNot
  
                -- grava numero temporario em BALCB
                Update BALCB
                   Set Ser_Nota = @SerNot,
                       Num_Nota = @NumNot
                 Where Cod_Estabe = @CodEstabe 
                   and Num_SeqBal = @NumSeqBal

                Set @NumSeqIte = 0
              end

            -- grava itens da nota
            Set @NumSeqIte = @NumSeqIte + 1
         
            Insert Into NFSIT (Cod_Estabe, Ser_Nota, Num_Nota, Cod_Produto, Cod_Lote, Num_SeqIte, Qtd_Produto, Qtd_Bonificacao, Prc_Unitario, Per_Desconto, Fat_CnvImpFat, Prc_UniImpFat) 
                       Values (@CodEstabe, @SerNot,  @NumNot,  @CodPrd,     @CodLot,  @NumSeqIte, @QtdMov,     0,               @PrcUni,      0,            1,             @PrcUni)
        
            -- atualiza campos do item da nota
            Update NFSIT
               Set Vlr_BruItem = Round(Prc_Unitario*(Qtd_Produto+Qtd_Bonificacao),2),
                   Vlr_TotItem = Round(Qtd_Produto*(Prc_Unitario*(1-Per_Desconto/100)),2),
                   Vlr_DescItem = 0
             Where Cod_Estabe = @CodEstabe
               And Ser_Nota = @SerNot
               And Num_Nota = @NumNot 
               And Cod_Produto = @CodPrd 
               And Cod_Lote = @CodLot 
               And Num_SeqIte = @NumSeqIte
        
            -- calcula tributacao
            Exec PR_CalcTributNFSIT @CodEstabe, @SerNot, @NumNot, @CodPrd, @CodLot, @NumSeqIte,
                                    @op_TipOpe, @cb_CodRegTri, @CodOpeSai
            if @@error <> 0
              begin
                if @@trancount > 0
                  Rollback Transaction
                Return
              end
        
            -- incrementa acumulador de itens
            Set @AccQtdIte = @AccQtdIte + 1

            if @AccQtdIte = @QtdMaxIteNot
              begin
                -- atualiza dados do cabecalho da nota
                Exec PR_NormalizaValoresNFS @CodEstabe, @SerNot, @NumNot
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end

                Set @AccQtdIte = 0 
              end

            FETCH NEXT FROM BALIT_Cr INTO @CodPrd, @CodLot, @QtdMov, @PrcUni
          END

          CLOSE BALIT_Cr
          DEALLOCATE BALIT_Cr     

          -- atualiza dados do cabecalho da ultima nota gerada
          Exec PR_NormalizaValoresNFS @CodEstabe, @SerNot, @NumNot
          if @@error <> 0
            begin
              if @@trancount > 0
                Rollback Transaction
              Return
            end
     
         -- atualiza Flag NF gerada em ACERT
         Update ac
            Set ac.Flg_NotFis = 1
           From ACERT ac 
                Inner Join TPMVE mv on ac.Cod_TipMov = mv.Codigo       
          Where ac.Cod_Estabe = @CodEstabe
            And ac.Num_SeqBal = @CodEstabe
            And mv.Tip_Movimento = 'S'
       
          -- atualiza parametros  
          Update PMEST
             Set CodOpeNfsBal = @CodOpeSai
           Where Cod_Estabe = @CodEstabe 
             and IsNull(CodOpeNfsBal,'') <> @CodOpeSai
      
          Update PMEST
             Set CodCliNotBal = @CodCliBal
           Where Cod_Estabe = @CodEstabe 
             and IsNull(CodCliNotBal,0) <> @CodCliBal

        end  -- if @QtdIteBal > 0

    end    -- if (@FlgGerSai = 1) or (@FlgGerDif = 1)
        
  --------------------------------------------------------------------------------------------------------------  
  
  -- Gera Notas de Entrada ----------------------------------------------------------------------------------------  
  if (@FlgGerEnt = 1) or (@FlgGerDif = 1)
    begin
      -- gera arq. auxiliar com itens da NF a gerar
      Delete From #BALIT_AUX

      if @FlgGerEnt = 1 
        begin
          -- todos os itens de entrada
          Insert Into #BALIT_AUX (Cod_Produt, Cod_Lote, Qtd_Produt, Prc_Unitar)        
            Select it.Cod_Produt, it.Cod_Lote, it.Qtd_EstPra,
                   Case
                     When @TipPrc = 'F' then Case  
                                               When pr.Prc_CusMedPra > 0 then ROUND(pr.Prc_CusMedPra,@pm_QtdDecPrcItePdv)
                                               When pr.Prc_CusMed > 0 then ROUND(pr.Prc_CusMed,@pm_QtdDecPrcItePdv)
                                               When pr.Prc_CusLiqEnt > 0 then ROUND(pr.Prc_CusLiqEnt,@pm_QtdDecPrcItePdv)
                                               Else 0.01
                                             End
                     When @TipPrc = 'G' then Case 
                                               When pr.Prc_CusMed > 0 then ROUND(pr.Prc_CusMed,@pm_QtdDecPrcItePdv)
                                               When pr.Prc_CusMedPra > 0 then ROUND(pr.Prc_CusMedPra,@pm_QtdDecPrcItePdv)
                                               When pr.Prc_CusLiqEnt > 0 then ROUND(pr.Prc_CusLiqEnt,@pm_QtdDecPrcItePdv)
                                               Else 0.01
                                             End  
                   End 
              From BALIT it Inner Join 
                   PRXES pr on it.Cod_Estabe = pr.Cod_Estabe and it.Cod_Produt = pr.Cod_Produt
             Where it.Cod_Estabe = @CodEstabe
               And it.Num_SeqBal = @NumSeqBal
               And it.Num_Contag = 1
               And it.Tip_Movim = 'E'
               And it.Qtd_EstPra > 0
        end
      else
        begin
          -- saidas somente das diferencas entre entradas e saidas
          DECLARE ITENS_Cr CURSOR Local Fast_Forward For 
     
            Select b.Cod_Produt, Qtd_DifEnt = IsNull(e.Qtd_Est,0) - IsNull(s.Qtd_Est,0),
                   Case
                     When @TipPrc = 'F' then Case  
                                               When pr.Prc_CusMedPra > 0 then ROUND(pr.Prc_CusMedPra,@pm_QtdDecPrcItePdv)
                                               When pr.Prc_CusMed > 0 then ROUND(pr.Prc_CusMed,@pm_QtdDecPrcItePdv)
                                               When pr.Prc_CusLiqEnt > 0 then ROUND(pr.Prc_CusLiqEnt,@pm_QtdDecPrcItePdv)
                                               Else 0.01
                                             End
                     When @TipPrc = 'G' then Case 
                                               When pr.Prc_CusMed > 0 then ROUND(pr.Prc_CusMed,@pm_QtdDecPrcItePdv)
                                               When pr.Prc_CusMedPra > 0 then ROUND(pr.Prc_CusMedPra,@pm_QtdDecPrcItePdv)
                                               When pr.Prc_CusLiqEnt > 0 then ROUND(pr.Prc_CusLiqEnt,@pm_QtdDecPrcItePdv)
                                               Else 0.01
                                             End  
                   End
              From (Select distinct Cod_Estabe, Cod_Produt
                      From BALIT
                     Where Cod_Estabe = @CodEstabe
                       And Num_SeqBal = @NumSeqBal
                       And Num_Contag = 1
                       And Qtd_EstPra > 0) b 
                   Inner Join PRXES pr on b.Cod_Estabe = pr.Cod_Estabe and b.Cod_Produt = pr.Cod_Produt 
                   Left  Join (Select Cod_Estabe, Cod_Produt, Qtd_Est = sum(Qtd_EstPra)
                                 From BALIT
                                Where Cod_Estabe = @CodEstabe
                                  And Num_SeqBal = @NumSeqBal
                                  And Num_Contag = 1
                                  And Tip_Movim = 'S'
                                  And Qtd_EstPra > 0
                                Group by Cod_Estabe, Cod_Produt) s on b.Cod_Estabe = s.Cod_Estabe and b.Cod_Produt = s.Cod_Produt 
                   Left  Join (Select Cod_Estabe, Cod_Produt, Qtd_Est = sum(Qtd_EstPra)
                                 From BALIT
                                Where Cod_Estabe = @CodEstabe
                                  And Num_SeqBal = @NumSeqBal
                                  And Num_Contag = 1
                                  And Tip_Movim = 'E'
                                  And Qtd_EstPra > 0
                                Group by Cod_Estabe, Cod_Produt) e on b.Cod_Estabe = e.Cod_Estabe and b.Cod_Produt = e.Cod_Produt
             Where (IsNull(e.Qtd_Est,0) - IsNull(s.Qtd_Est,0)) > 0

          OPEN ITENS_Cr
          FETCH NEXT FROM ITENS_Cr INTO @CodPrd, @QtdMov, @PrcUni
          WHILE @@FETCH_STATUS = 0
          BEGIN
            Set @AccQtdMov = @QtdMov
            
            -- lotes de itens inventariados a movimentar
            DECLARE LOTES_Cr CURSOR Local Fast_Forward For 
            
              Select Cod_Lote, Qtd_EstPra
                From BALIT
               Where Cod_Estabe = @CodEstabe
                 And Num_SeqBal = @NumSeqBal
                 And Num_Contag = 1
                 And Tip_Movim = 'E'
                 And Qtd_EstPra > 0
                 And Cod_Produt = @CodPrd
               Order by Dat_VctLot desc, Qtd_EstPra desc
            
            OPEN LOTES_Cr
            FETCH NEXT FROM LOTES_Cr INTO @CodLot, @QtdLot
            WHILE (@@FETCH_STATUS = 0) AND (@AccQtdMov > 0)
            BEGIN
              if @QtdLot > @AccQtdMov
                Set @QtdReg = @AccQtdMov
              else   
                Set @QtdReg = @QtdLot
              if @QtdReg > 0
                begin
                  Insert Into #BALIT_AUX (Cod_Produt, Cod_Lote, Qtd_Produt, Prc_Unitar)        
                                  Values (@CodPrd, @CodLot, @QtdReg, @PrcUni)
                  if @@error <> 0
                    begin
                      if @@trancount > 0
                        Rollback Transaction
                      Return
                    end
                end  
              Set @AccQtdMov = @AccQtdMov - @QtdReg
              FETCH NEXT FROM LOTES_Cr INTO @CodLot, @QtdLot
            END
            
            CLOSE LOTES_Cr
            DEALLOCATE LOTES_Cr     
            
            FETCH NEXT FROM ITENS_Cr INTO @CodPrd, @QtdMov, @PrcUni
          END

          CLOSE ITENS_Cr
          DEALLOCATE ITENS_Cr     

        end    

      Set @QtdIteBal = IsNull((Select COUNT(*) From #BALIT_AUX),0)
                        
      if @QtdIteBal > 0
        begin
        
          Select @op_TipOpe = Tip_Ope, 
                 @op_CodCfo = Cod_CfoNorInt,
                 @op_FlgBlqTrfEstFis = IsNull(cf.Flg_BlqTrfEstFis,0)
            From TPOPE op
                 left join TBCFO cf on op.Cod_CfoNorInt = cf.Codigo
           Where Cod_Ope = @CodOpeEnt

          -- quantidade de NF a gerar
          Set @QtdNot = CEILING(CAST(@QtdIteBal AS Numeric)/@QtdMaxIteNot)                 

          -- se qtd de itens da ultima NF < 100 aumenta qtd max de itens na NF para suportar resto
          Set @QtdRes = @QtdIteBal % @QtdMaxIteNot
          if (@QtdRes < 50) and (@QtdNot > 1)
            begin
              Set @QtdNot = @QtdNot - 1
              Set @QtdMaxIteNot = @QtdMaxIteNot + CEILING(CAST(@QtdRes AS Numeric)/@QtdNot)                 
            end
       
          Set @AccQtdIte = 0  
     
          DECLARE BALIT_Cr CURSOR Local Fast_Forward For 
     
            Select Cod_Produt, Cod_Lote, Qtd_Produt, Prc_Unitar
              From #BALIT_AUX

          OPEN BALIT_Cr
          FETCH NEXT FROM BALIT_Cr INTO @CodPrd, @CodLot, @QtdMov, @PrcUni
          WHILE @@FETCH_STATUS = 0
          BEGIN
            -- grava novo cabe�alho de NF
            if @AccQtdIte = 0
              begin
                -- Pega novo numero temporario (protocolo)
                EXEC PR_ProxNumero 'Protocolo', @NumPrt output

                -- grava cabecalho
                Insert Into NFECB (Cod_Estabe, Protocolo, Num_SeqBal, Flg_MovEst, Flg_ImpNot, Cod_EmiCliente)
                           Values (@CodEstabe, @NumPrt,   @NumSeqBal, 0,          1, @CodCliBal)   
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end
              
                -- grava campos na nota
                Update cb
                   Set cb.Cod_Ope = @CodOpeEnt, 
                       cb.Cod_Cfo = @op_CodCfo, 
                       cb.Flg_BlqTrfEstFis = @op_FlgBlqTrfEstFis,
                       cb.Especie = 'NF', 
                       cb.Status = 'A', 
                       cb.Status_2 = '', 
                       cb.Tip_NF = @op_TipOpe, 
                       cb.Dat_Emissao = @Date,   
                       cb.Dat_Entrada = @Date,       
                       cb.Flg_DevTot = 0,          
                       cb.Qtd_PagNF = 1,         
                       cb.Ser_SeloFisTran = '',              
                       cb.Cod_FinNfe = '1',        
                       cb.Tip_Frete = '1',       
                       cb.Cod_Vendedor = @pm_CodVdrPdvCon, 
                       cb.Tip_Emitente = 'C',                                 
                       cb.Cod_EmiFornec = 0,
                       cb.Cod_EmiTransp = 0,
                       cb.Cod_RegTri = en.Cod_RegTri,
                       cb.Pessoa = cl.Pessoa,
                       cb.Cgc_Cpf = cl.Cgc_Cpf,
                       cb.Cgf_Rg = cl.Cgf,
                       cb.Endereco = SUBSTRING(dbo.FN_EnderecoCompleto(cl.Endereco, cl.Numero, cl.Complemento),1,50),
                       cb.Bairro = ba.Descricao,
                       cb.Cidade = ci.Descricao,
                       cb.Cod_UfOrigem = cl.Cod_Estado,
                       cb.Cep = cl.Cep,
                       cb.Cod_CidIbge = ci.Cod_CidIbge,
                       cb.Usuario = @Usuario, 
                       cb.Transacao = @Now      
                  From NFECB cb 
                       Left Join CLIEN cl on (cb.Cod_EmiCliente = cl.Codigo) 
                       Left Join CIDAD ci on ((cl.Cod_Estado = ci.Cod_Estado) and (cl.Cod_Cidade = ci.Codigo)) 
                       Left Join BAIRR ba on ((cl.Cod_Estado = ba.Cod_Estado) and (cl.Cod_Cidade = ba.Cod_Cidade) and (cl.Cod_Bairro = ba.Codigo))
                       Left Join ENXES en on ((cb.Cod_Estabe = en.Cod_Estabe) and (cl.Cgc_Cpf = en.Num_CgcCpf)) 
                 Where cb.Cod_Estabe = @CodEstabe
                   And cb.Protocolo = @NumPrt
             
                Select @cb_CodRegTri = Cod_RegTri
                  From NFECB
                 Where Cod_Estabe = @CodEstabe
                   And Protocolo = @NumPrt
  
                -- grava numero temporario em BALCB
                Update BALCB
                   Set Protocolo = @NumPrt
                 Where Cod_Estabe = @CodEstabe 
                   and Num_SeqBal = @NumSeqBal

                Set @NumSeqIte = 0
              end

            -- grava itens da nota
            Set @NumSeqIte = @NumSeqIte + 1
        
            Insert Into NFEIT (Cod_Estabe, Protocolo, Cod_Produto, Cod_Lote, Num_SeqIte, Tip_Ent, Qtd_Pedido, Qtd_PedFat, Qtd_Bonificacao, Prc_Unitario, Per_DescItem, FATOR_FAT, Prc_UniFat, Per_IcmDiferi) 
                       Values (@CodEstabe, @NumPrt,   @CodPrd,     @CodLot,  @NumSeqIte, '',      @QtdMov,    @QtdMov   , 0,               @PrcUni,      0,            1,        @PrcUni, 0)
        
            -- atualiza campos do item da nota
            Update NFEIT
               Set Vlr_BruItem = Round(Prc_Unitario*(Qtd_Pedido+Qtd_Bonificacao),2),
                   Vlr_TotItem = Round(Qtd_Pedido*(Prc_Unitario*(1-Per_DescItem/100)),2),
                   Vlr_DescItem = 0
             Where Cod_Estabe = @CodEstabe
               And Protocolo = @NumPrt
               And Cod_Produto = @CodPrd 
               And Cod_Lote = @CodLot 
               And Num_SeqIte = @NumSeqIte
        
            -- calcula tributacao
            Exec PR_CalcTributNFEIT @CodEstabe, @NumPrt, @CodPrd, @CodLot, @NumSeqIte,
                                    @op_TipOpe, @cb_CodRegTri, 0
            if @@error <> 0
              begin
                if @@trancount > 0
                  Rollback Transaction
                Return
              end
        
            -- incrementa acumulador de itens
            Set @AccQtdIte = @AccQtdIte + 1

            if @AccQtdIte = @QtdMaxIteNot
              begin
                -- atualiza dados do cabecalho da nota
                Exec PR_NormalizaValoresNFE @CodEstabe, @NumPrt
                if @@error <> 0
                  begin
                    Rollback Transaction
                    Return
                  end

                Set @AccQtdIte = 0 
              end

            FETCH NEXT FROM BALIT_Cr INTO @CodPrd, @CodLot, @QtdMov, @PrcUni
          END

          CLOSE BALIT_Cr
          DEALLOCATE BALIT_Cr     

          -- atualiza dados do cabecalho da ultima nota gerada
          Exec PR_NormalizaValoresNFE @CodEstabe, @NumPrt
          if @@error <> 0
            begin
              if @@trancount > 0
                Rollback Transaction
              Return
            end

         -- atualiza Flag NF gerada em ACERT
         Update ac
            Set ac.Flg_NotFis = 1
           From ACERT ac 
                Inner Join TPMVE mv on ac.Cod_TipMov = mv.Codigo       
          Where ac.Cod_Estabe = @CodEstabe
            And ac.Num_SeqBal = @CodEstabe
            And mv.Tip_Movimento = 'E'
        
          -- atualiza parametros
          Update PMEST
             Set CodOpeNfeBal = @CodOpeEnt
           Where Cod_Estabe = @CodEstabe 
             and IsNull(CodOpeNfeBal,'') <> @CodOpeEnt

          Update PMEST
             Set CodCliNotBal = @CodCliBal
           Where Cod_Estabe = @CodEstabe 
             and IsNull(CodCliNotBal,0) <> @CodCliBal
      
        end  -- if @QtdIteBal > 0
      
    end    -- if (@FlgGerEnt = 1) or (@FlgGerDif = 1)
  --------------------------------------------------------------------------------------------------------------  

  Drop Table #BALIT_AUX
  
  if @@trancount > 0
    COMMIT TRANSACTION
END
GO
